// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":30,"question":"ما رأي فضيلتكم في علاج يميت اللذة الجنسية، فقد سمعتُ بعلاج يُدعى الكافور، فما رأي فضيلتكم في ذلك؟ أفيدوني أفادكم الله، وجزاكم خيرًا.","title":"ما حكم العلاج الذي يخفّف من شدة الشهوة؟","answer":"الجواب: شدة الشهوة وقوتها وخطرها قال فيه النبي ﷺ: يا معشر الشباب من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وِجَاء فينبغي لك أن تصوم ما تيسر، وتستعين بالله، ثم بالصوم الذي أرشد إليه النبي ﷺ إذا استطعتَ ذلك، فإن لم تستطع فاتصل بالمختصين من الأطباء الذين لهم عناية بهذا الشيء؛ حتى يرشدوك إلى ما يعينك على حفظ نفسك، وعلى كف شهوتك عما حرم الله، هناك أدوية تضعف الشهوة، ولا تقطع الشهوة؛ لكن تضعفها إلى أن تأتي الأسباب التي تعين على قضائها في الحلال، فعليك بسؤال المختصين الذين لهم عناية بهذا الأمر حتى يرشدوك إلى أسباب تعينك على كبح شهوتك، والحذر من طغيانها؛ بالأدوية النافعة التي لا تقطعها، ولا تضرك؛ ولكن تضعفها في وقت خاص، وفي وقت معين؛ حتى يتيسر لك الزواج، وقضاء الوطر فيما أباحه الله ، والصوم إذا أمكن فهو من أحسن، ومن أفضل الدواء الذي أرشد إليه النبي عليه الصلاة والسلام.\nوهنا نقطة ينبغي أن تُعْلَم، وهي: الزواج الذي أرشد إليه النبي ﷺ، كثير من الشباب يتقاعس عن الزواج، ويُعرض عن الزواج، وربما شجّعه بعض زملائه على ذلك، تارة بالصبر حتى تنتهي الدراسة، وتارة حتى يجد وظيفة تقوم بحاله، وتارة كذا، وتارة كذا، وهذا غلط.\nالواجب البِدار بالزواج إذا تيسر ذلك، ولو من طريق أبيك، أو من طريق أخيك الكبير، أو من طريق أمك، أو من أي طريق تصل بها إلى الزواج، بادر إلى الزواج، ولا تنتظر انتهاء الدراسة، ولا تنتظر الوظيفة، ولا تنتظر وجود بيت سكني لك تملكه، ولا غير هذا من الأعذار، بادر بالزواج، والمتزوج يعينه الله، والله يقول : وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ والصَّالِحِينَ مِنْ عِبَادِكُمْ وإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] فجعل النكاح من أسباب الغنى.\nفعليك بالزواج، والبِدار إليه، ولا تؤجل إلى انتهاء الدراسة، أو إلى كذا، أو إلى كذا؛ بل إذا تيسر ذلك، ولو من طريق والدك، أو من طريق أخيك، أو من طريق أمك، أو بأي طريق يحصل لك به ذلك، فلا تتأخر، وبادر، وسارع؛ لأن في هذا مصالح كثيرة منها: غض بصرك، ومنها إحصان فرجك، ومنها تكثير النسل، وتكثير الأمة، ومنها أن الله جلَّ وعَلا سيغنيك بذلك، ويعينك بذلك على مصالح كثيرة. ولا يخفى أيضًا أن الزواج فيه هدوء للنفس، وسكن للنفس، وطمأنينة، فالله جعل المرأة سكنًا للزوج: وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا لِتَسْكُنُوا إِلَيْهَا وجَعَلَ بَيْنَكُمْ مَوَدَّةً ورَحْمَةً [الروم:21] فالأزواج جعلهن الله سكنًا للزوج، وراحة له، وطمأنينة له، فإذا تزوج فقد استعان بشيء جعله الله له عونًا على الطمأنينة، والراحة، وسكن النفس، وراحة البال، فلا تؤخِّر هذا الشيء الذي جعله الله لك سكنًا، وعونًا على الخير، وسببًا لحمايتك مما حرم الله .","link":"https://binbaz.org.sa/fatwas/2810/ما-حكم-العلاج-الذي-يخفف-من-شدة-الشهوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0003.mp3","categories":["الطب والتداوي"]},{"id":100,"question":"أثابكم الله، يقول هذا السَّائل: عندما يكون الطبيبُ في مكان عمله الذي يستوجب منه علاج المسلم وغير المسلم، كالنصارى أو غيرهم مثلًا في حالة الحرب، مع الخوف مما قد يحصل فيما بعد من هذا النَّصراني، فما موقف الطبيب المُعالج أمام الله تعالى في علاج هذا الذي يُبغضه الله ورسوله، ويبغض الله ورسوله؟","title":"واجب الطبيب في علاج غير المسلم ودعوته","answer":"الجواب: الواجب على الطبيب أن يُعالجه كما يُعالج غيره؛ لأنَّ هذا صار في محلِّ الاستئمان، وليس في محلِّ حربٍ، إذا كان تبعنا أو دخل عندنا بالأمان موظفٌ أو طبيبٌ أو مع المُجاهدين أو مع الميلشيات التي تُحارب الآن، فلو جرى عليه شيءٌ لا بدّ أن تُعالجه كما تُعالج المريض المسلم، وتتقي الله في أداء الأمانة.\nوكونه يُبغضه الله، فهذا إلى الله ، لكن أنت الآن دخل عندك بالأمان، فلا بدّ أن تُعالجه إذا كان مُؤْتَمَنًا، أو مُعاهدًا، أو جاء برسالة أمانٍ، أو جاء طبيبًا، أو لأسبابٍ أخرى، فإن أصابه مرضٌ فعالجه بالأمانة ولا تضرّه بشيءٍ.\nس: ألا ترون يا سماحة الشيخ أنَّه في مثل هذه الحالة مجال للدعوة الإسلامية؟\nالشيخ: زيادة، الدعوة طيبة، فكونه يدعوه إلى الله ويُرَغِّبه في الإسلام هذا طيبٌ، مع العلاج، فلا يَخُن الأمانةَ ويُعالجه بشيءٍ يضرُّه، بل يجب أن ينصح له، وهذا من الدعوة إلى الإسلام، فكونه ينصح له هذا من الدَّعوة إلى الإسلام، ويستشعر النصراني أو غيره أنَّ الإسلام ينصح ويُؤدي الواجب لمَن اؤتُمِنَ عليه، أو صار في أمانته، أو في عهده، أو في ذمَّته.","link":"https://binbaz.org.sa/fatwas/3132/واجب-الطبيب-في-علاج-غير-المسلم-ودعوته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0080.mp3","categories":["الطب والتداوي"]},{"id":103,"question":"تمرُّ بالأطباء بعضُ الحالات، فعندما يُولد طفلٌ مثلًا قبل موعده في الشهر السادس من الحمل، ونظرًا لأنه تحدث مضاعفات كثيرة طبيًّا إن كان الطفلُ عاش، وذلك بعد قدرة الله  ثم بالجهاز التنفسي، لذا فإنَّ هناك قانونًا طبيًّا يقول: إن كان وزنُ الطفل أقلَّ من 750جم فلا يُعمل له الجهاز التنفسي الذي يكون بفضل الله مساعدًا للطفل على الحياة، بالرغم من المُضاعفات المتوقع حدوثها، فهل يجوز ترك الطفل بدون مساعدات إضافية تُكلِّف المريضَ والطبيبَ الكثير من الجهد والوقت والمال -إذا لزم الأمرُ بالنسبة للمال- مع احتمال كبير في عدم استمرار الطفل في الحياة، بل قد يكون مُعاقًا فيما بعد، أم نُرَكِّب له هذا الجهاز مع ما يحصل له بعد ذلك؟","title":"حكم منع العلاج إذا رأى الأطباء عدم فائدته","answer":"الجواب: القاعدة عند أهل العلم: أنَّ العلاج ليس بواجبٍ، بل مُستحبٌّ، فعلاج المرضى مُستحبٌّ وليس بواجبٍ، فكونه يُعالج بجراحةٍ أو بعمليةٍ أو بحبوبٍ أو بحميةٍ كلها مُستحبَّة، وليست واجبةً، فلو أبى العلاج لا حرج عليه. فإذا رأى الأطباء أنَّ من المصلحة أن يُعالج هذا الطفل فعلوا، وإن رأوا أنَّ المصلحة عدم العلاج تركوا، ولا حرج في ذلك، فالحكم يدور مع المصلحة الغالبة، فإن غلب على الظنِّ أن العلاج ينفع فلا بأس، وإن غلب على الظن أنَّه لا ينفع فلا بأس بتركه؛ لأنه ضياع وعدم فائدةٍ وإضاعة للأموال وللأوقات.","link":"https://binbaz.org.sa/fatwas/3198/حكم-منع-العلاج-اذا-راى-الاطباء-عدم-فاىدته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0084.mp3","categories":["الطب والتداوي"]},{"id":106,"question":"كثير من الأدوية التي تُستخدم في الطب مُفَتِّرَة، وبعضها مُسْكِر، أو كثيرة مُسْكِرة، وهذه الأدوية تُستخدم للآلام والعمليات وغيرها، فهل استخدامها جائز أو تدخل في حكم المُحَرَّم من الخمور؟","title":"حكم الأدوية الطبية المُخَدِّرة والمُسْكِرة","answer":"الجواب: أما المُخَدِّرة فلا بأس؛ المُفَتِّرة أو البَنْج لا بأس بها. أما المُسْكِرة التي تحصل بها النشوة والسُّكْر فلا يجوز، فالرسول ﷺ قال: كل مُسْكِر خمر، وكل مسكر حرام، وقال: إنَّ الله لم يجعل شفاءكم فيما حرَّم عليكم، وسأله رجلٌ فقال: يا رسول الله، أصنع الخمر للدواء، فقال: إنها ليست بدواء، ولكنها داء رواه مسلم في \"الصحيح\".\nفإذا عرف أنه مُسكر فلا يجوز التَّداوي به، أما كونه مُفتر ويمنع الألم كالبنج فلا بأس؛ لأنَّ هذا يُؤخذ لدفع الآلام ورفعها، وهذا لا بأس به، فهو ينفع المريض، أما كونه يُسكره ويتغيَّر عقله به ويهذي ويتكلم بما لا ينبغي كسائر المُسكرات؛ فلا.","link":"https://binbaz.org.sa/fatwas/3238/حكم-الادوية-الطبية-المخدرة-والمسكرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0088.mp3","categories":["الطب والتداوي"]},{"id":107,"question":"ما الحكم في إجراء الفحوصات الطبية على الجنين بغرض تشخيص بعض الأمراض الوراثية فيه وهو في بطن أمه، مع العلم أنَّ هناك دائمًا احتمالًا في التَّسبب في الإجهاض نتيجة لهذه الفحوصات؟","title":"حكم فحوصات الأمراض الوراثية على الجنين","answer":"الجواب: هذا فيه تفصيل: إن كانت الفحوص لا تُسبب قتله غالبًا؛ فلا بأس. وإن غلب على الظنِّ أنها تُسبب قتله فلا تجوز. فالعمدة على الغالب، إن كانت الفحوص التي يتعاطاها الطبيبُ مع الجنين في الغالب لا تضرُّ ولا تُوجب سقوطه ولا موته فلا حرج، أما إن كان الغالبُ أنها تُسبب سقوطه وموته لم تجز، فالواجب التَّحري في هذا.","link":"https://binbaz.org.sa/fatwas/3242/حكم-فحوصات-الامراض-الوراثية-على-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0090.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":130,"question":"سائلٌ يقول: إذا كان هناك شيءٌ يخاف عليه الإنسانُ من العين، فهل هناك شيءٌ من الكتاب والسنة يكون مانعًا من العين؟","title":"ما الذي يُشرع في الوقاية من العين؟","answer":"الجواب: نعم، إذا خفت عليه تقول: بارك الله فيه، أو: ما شاء الله، لا قوة إلا بالله، منزل أو طعام أو ولد أو غير ذلك: ما شاء الله، لا قوة إلا بالله، بارك الله فيه، اللهم بارك فيه، مع الثقة في الله والاعتماد عليه، وأنه لا يُصيبك إلا ما كتب الله لك.","link":"https://binbaz.org.sa/fatwas/3657/ما-الذي-يشرع-في-الوقاية-من-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0119.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":148,"question":"إذا طرق باب البيت أحدُ الأصدقاء وأنا غير موجودٍ، ولا توجد سوى زوجتي، هل تصمت أم ترد وتُخبره أني غير موجودٍ؟","title":"حكم رد المرأة على الهاتف ومن يطرق الباب؟","answer":"الجواب: إذا طرق البابَ وليس فيه إلا الزوجة، أو ضرب الهاتف، فلا بأس أن تُجيب الهاتف، ولا بأس أن تُجيب الباب، وقد كان النساءُ في عهد النبي ﷺ يُجبن ويتكلَّمن ويُرحبن بالضيوف، مع السلامة والبُعد عن الشرِّ، فإذا ردَّت قالت: ليس بحاضرٍ، وإذا سأل وقال: أين هو؟ ولا محذور في الخبر تقول: إنه في المحل الفلاني، إذا لم يكن هناك محذورٌ لا بأس بهذا. أو ضرب الهاتفُ وأخذت السَّماعة وعرفت مَن يضرب وحادثته بما يُريد وقالت: إن صاحب البيت ليس بحاضرٍ، وإن كان حاضرًا أخبرته حتى يكلم، وإن كان في محلٍّ معروفٍ دلَّت عليه، إذا كان يرضى بذلك، إلى غير هذا من المسائل التي لا حرج فيها.\nوقد كانت النساء في عهد النبي ﷺ وهكذا بعده لا يتحرَّجن من هذا الشيء، وليس فيه محذور، إنما المحذور ما يُفضي إلى الفتنة أو الخلوة أو ما يحصل به الخضوع -خضوع القول- حتى يطمع فيها، كما قال تعالى: فَلَا تَخْضَعْنَ بِالْقَوْلِ [الأحزاب:32].","link":"https://binbaz.org.sa/fatwas/3685/حكم-رد-المراة-على-الهاتف-ومن-يطرق-الباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0141.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":173,"question":"سماحة الشيخ، في كتابكم \"تحفة الأخيار\" ذكرت أنه يُشرع لكل مسلم أن يقول في صباح كل يومٍ: \"لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير\" في يوم مئة مرة.و هل يجوز أن يقولها أكثر من مئة مرة؟ وهل يجوز أن يقول هذا الذِّكْر في المساء أيضًا؟","title":"ما السُّنة في وقت وعدد ذكر التهليل؟","answer":"الجواب: نعم، يُشرع الإكثار من ذكر الله في كل وقتٍ، ولو آلاف المرات، لكن هذا الذي قلناه قاله النبيُّ ﷺ، قال النبيُّ ﷺ: مَن قال في يومٍ مئة مرة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير؛ كانت له عدل عشر رقاب –يعني: عدل عشر رقابٍ يعتقها- وكتب الله له مئة حسنة، ومحا عنه مئة سيئة، وكان في حرزٍ من الشيطان في يومه ذلك حتى يُمسي، ولم يأتِ أحدٌ بأفضل مما جاء به، إلَّا رجلٌ عمل أكثر من عمله رواه الشيخان: البخاري ومسلم في \"الصحيحين\".\nفهذا حديثٌ عظيمٌ، فإذا قاله في أول النهار يكون أكمل؛ حتى يكون في حرزٍ من الشيطان يومه ذلك حتى يُمسي، وإن قالها في الضُّحى أو الظهر أو العصر أو في الليل فكله طيب، ولو قاله آلاف المرات فكله طيب، يقول الله: وَاذْكُرُوا اللَّهَ كَثِيرًا [الجمعة:10]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا ۝ وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا [الأحزاب:42]، ويقول جلَّ وعلا: إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ إلى أن قال سبحانه: وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا [الأحزاب:35]، فالذكر له شأنٌ عظيمٌ.","link":"https://binbaz.org.sa/fatwas/3714/ما-السنة-في-وقت-وعدد-ذكر-التهليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0170.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":176,"question":"ما حكم وَسْم الأنعام بالكيّ إذا لم يُوجد البديلُ عن ذلك، وخاصَّةً الإبل؟","title":"حكم علاج الحيوانات بالكي","answer":"الجوب: كيّها لا بأس به، فالنبي كوى، فوسمها بالكي بأن تُكوى في أفخاذها ورقابها، لا في الوجه، فالكي لا بأس به في الإبل ونحوها، في الفخذ، أو في الرقبة، أما الوجه فلا، لا توسم في وجوهها، لا الإبل، ولا البقر، ولا الغنم، إنما تُكوى في الفخذ، أو في الأذن، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/3725/حكم-علاج-الحيوانات-بالكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0177.mp3","categories":["الطب والتداوي"]},{"id":179,"question":"في هذه الأيام تنتشر الأمراض بالعين، وهم يفتخرون بها، وهي تُصيب بعض الناس، فما نصيحتكم لهؤلاء؟","title":"ما حكم من يتعمد الإصابة بالعين؟","answer":"الجواب: الواجب الحذر، وأن الإنسان يتعمّد، فإذا كانت العينُ يتعمّدها فعليه الحذر من ذلك، وإذا عُرف أنه يتعمّد ذلك يجب أن يُؤاخذ بهذا ويُعاقب، أما إذا كان بغير اختياره فليس بيده قدرة، لا يُكلِّف الله نفسًا إلا وسعها. والمسلم يقول صباح ومساء: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\" ثلاث مرات، ويقرأ آية الكرسي بعد كلِّ صلاةٍ: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255]، ويقرأ قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مراتٍ صباح ومساء ويسلم، ما تضرُّه العين ولا غيرها.\nفيقرأ قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات صباح ومساء، وقايةً من كل سوءٍ، ويقرآ آية الكُرسي بعد كل صلاةٍ، ففيها الوقاية من كل سوءٍ، ويقرأها أيضًا: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ عند النوم.\nكل هذه من أسباب الوقاية، ويقول: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\" ثلاث مرات في الليل والنهار، و\"بسم الله الذي لا يضرُّ مع اسمه شيءٌ في الأرض ولا في السماء، وهو السميع العليم\" ثلاث مرات ليلًا ونهارًا، من أسباب الوقاية، ويقرأ آخر آيتين من سورة البقرة كل ليلةٍ: آمَنَ الرَّسُولُ [البقرة:285]، فهذه من أسباب العافية من كل سوءٍ.","link":"https://binbaz.org.sa/fatwas/3728/ما-حكم-من-يتعمد-الاصابة-بالعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0180.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":180,"question":"هذا سائلٌ يقول: إنه قد جاءني رجلٌ وقال: إنَّ في زوجتك سحرًا، فلا بأس أن تذهب للكاهن، ولكن بدون تصديقه، فما الحكم، أثابكم الله؟","title":"هل يجوز الذهاب للكاهن دون تصديقه؟","answer":"الجواب: لا، لا تُصدقه، لا تُصدق السَّحرة، ولا تذهب إلى السَّحرة، اقرأ عليها وانفث عليها بآية الكرسي والفاتحة: الْحَمْدُ لِلَّهِ [الفاتحة:2] وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، وتبرأ إن شاء الله، وهي كذلك تنفث على نفسها وتتعوَّذ بكلمات الله التامَّات من شرِّ ما خلق، وتبرأ إن شاء الله، وتقرأ الفاتحة وآية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، أنت تقرأ عليها، أو هي تقرأ على نفسها ويزول: قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات، تُكرر عليها ثلاث مرات في القراءة، وهي من أسباب الشِّفاء والعافية من كل بلاءٍ، ولا تذهبوا إلى السَّحرة، لا يجوز الذّهاب إلى السحرة، ولا سؤالهم، ولا تصديقهم.","link":"https://binbaz.org.sa/fatwas/3751/هل-يجوز-الذهاب-للكاهن-دون-تصديقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0181.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":182,"question":"نأمل من سماحتكم توجيه نصيحة للنساء، خاصَّةً أنهن حاضرات، وجزاكم الله خيرًا.","title":"نصيحة جامعة للنساء من الشيخ ابن باز","answer":"الجواب: نُوصي جميع أخواتنا في الله بتقوى الله، نوصيهن بطاعة الله، والاستقامة، والمُحافظة على الصلاة في وقتها، والسمع والطاعة للزوج في المعروف، والحذر من التبرج والسُّفور وأسباب الفتنة.\nونُوصي جميع النساء بتقوى الله، والمحافظة على الصلاة في وقتها في البيت، والطُّمأنينة والخشوع، والحذر من التَّبرج الذي يضرُّ المسلمين، والحذر من جميع المعاصي: من الغيبة والنَّميمة، وعصيان الزوج بغير حقٍّ، ونحو ذلك.\nونوصي الجميع بتقوى الله، والتعاون على البر والتقوى، والمُعاشرة بالمعروف، كما نوصي الأزواج بذلك، نوصي الجميع بطاعة الله، والتَّعاون على البر والتقوى، كما قال تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وقال تعالى: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2].\nونوصي الجميع بتقوى الله، والتعاون على الخير، والحذر من كلِّ ما نهى الله عنه ورسوله.\nنسأل الله للجميع الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/3755/نصيحة-جامعة-للنساء-من-الشيخ-ابن-باز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0185.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":249,"question":"تقول هذه السائلة: قرأتُ في مجلةٍ من المجلات الوافدة إفتاء حول صوت المرأة إذا كان عورةً أم لا، وقد أجاب المُفتي بأن صوت المرأة ليس بعورةٍ، وقد عرفنا كلامًا للنساء، والصَّحابيات للصحابة، ولم يأمرهنَّ الرسولُ ﷺ بالسكوت، ولا أحد من الخلفاء الراشدين. انتهى كلامه، فإذا كان صوت المرأة عورةً، وتأثم إن تحدثت للرجال، فماذا تفعل الطالبةُ في الكلية إذا كان المعلمُ رجلًا وعليها أن تُجيبه على سؤاله، أو قد تسأله، فهل ذلك مُحرَّم؟","title":"هل صوت المرأة عورة؟","answer":"الجواب: القول كما قال هذا المُفتي، ليس صوت المرأة بعورةٍ مطلقًا، صوتها ليس بعورةٍ، فلها أن تسأل، وعلى المسؤول أن يُجيب، وقد كنَّ في عهد النبيِّ ﷺ يسألن النبيَّ ﷺ ويُجيبهنَّ عليه الصلاة والسلام، وقد قال الله جلَّ وعلا: قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا نصَّ القرآن وَتَشْتَكِي إِلَى اللَّهِ [المجادلة:1]، وهكذا كنَّ يسألن الصحابة، ويسألن مَن بعد الصحابة، وهذا أمرٌ معلومٌ.\nولكن العورة من ذلك ما كان عن تغنجٍ، وعن خضوعٍ، هذا هو الذي يُمنع، هكذا قال جلَّ وعلا: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32]، فنهاهنَّ عن الخضوع لئلا يطمع فيهنَّ المُفسدون أصحابُ الشَّهوات ومرض القلوب، وَقُلْنَ قَوْلًا مَعْرُوفًا أمرهن أن يقولن قولًا معروفًا وسطًا، ليس فيه خضوعٌ، وليس فيه فحشٌ ونكر، ولكنه وسط، فلا تتكلم بالشدة والكلام السيئ، ولا بالكلام الرخيم الذي فيه الخضوع، وفيه التَّكسر والتَّغنج، لا، ولكن بين ذلك، كلام عادي وسط بين الكلامين، لا كلام فاحش، ولا كلام منكر، ولا كلام فيه غلظة وعنف، ولا كلام مرخم مزين خاضعة فيه، لا هذا، ولا هذا، هذا هو الحق الذي قاله أهلُ العلم.","link":"https://binbaz.org.sa/fatwas/4140/هل-صوت-المراة-عورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0291.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":255,"question":"قال في \"فتح المجيد\": \"إنَّ معنى الحَمْد هو الثناء على الجميل الاختياري\" فهل هذا الكلام هو الراجح؟","title":"ما الصواب في معنى \"الحَمْد\"؟","answer":"الجواب: الكلام في الحمد كلام مهم جدًّا، والذي يظهر أنَّ الشارح تبع فيه غيره، والصواب أنَّ الحمد أعمُّ من ذلك، فالحمد يكون على الجميل الاختياري: كإحسانه إلينا، وإرساله الرسل، ونحو ذلك مما تفضَّل به علينا سبحانه، ويكون الحمد أيضًا بالأسماء والصِّفات اللازمة: كالعزيز، والحكيم، والقدير، والقهار، وأشباه ذلك، فالحمد يكون بالصفات اللازمة، وبالصفات المتعدية، هذا هو الصواب.\nفالله يُحمد سبحانه لذاته العظيمة، ولأسمائه الحسنى، ولصفاته الكريمة، ويُحمد أيضًا لإحسانه، وجوده، وكرمه على عباده.\nفالذي سلكه الشارحُ تابع فيه غيره، والصواب ما هو أعمّ من ذلك.","link":"https://binbaz.org.sa/fatwas/4247/ما-الصواب-في-معنى-الحمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0298.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":270,"question":"سائلٌ يسأل فيقول: أنا أعلم أنَّ كل شيءٍ يُسبّح الله في هذا الكون، ولكن هل الكفار يُسبِّحون الله تعالى؟","title":"معنى: {وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ..}","answer":"الجواب: قال الله جلَّ وعلا: وَكَثِيرٌ مِنَ النَّاسِ [الحج:18]، ما قال: كلهم، قال: كثيرٌ من الناس، فالكفَّار العقلاء هؤلاء لا يُسبّحون التَّسبيح الذي شرعه الله: من صلاةٍ، وصوم، والإتيان بالأذكار الشرعية.\nلكن قال العلماء: إنَّهم شاهدون بلسان حالهم وبخلقتهم على أنَّ الله ربّهم وخالقهم ومُوجدهم والمُحسن إليهم، وهو بالحقيقة بلسان الحال، ومشاهدة ما فطرهم الله عليه، وما أعطاهم من النعم، هم بالحقيقة ساجدون لله، خاضعون لله؛ لما خلق فيهم وأوجد فيهم من آياته ونِعَمه العظيمة .\nوقد يُسبّح بعضُ عقلائهم، وقد يُثني على الله، ولكن لا ينفعه ذلك؛ لكفره، فقد يقول: سبحان الله، وقد يقول: الحمد لله، وقد يتكلم بكلامٍ طيبٍ، لكن لا ينفعه ما دام كافرًا، فإنَّ أعماله حابطة كما قال : وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88].\nولقد يقع من التَّسبيح منهم -وهو الثناء- حسنات يُعطون أجرها في الدنيا، يُعطون عليها في الدنيا، ولا تنفعهم في الآخرة؛ لأنَّ كفرهم وشركهم يُبطلها، ولهذا قال جلَّ وعلا: أَلَمْ تَرَ أَنَّ اللَّهَ يَسْجُدُ لَهُ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ وَالشَّمْسُ وَالْقَمَرُ وَالنُّجُومُ وَالْجِبَالُ وَالشَّجَرُ وَالدَّوَابُّ وَكَثِيرٌ مِنَ النَّاسِ [الحج:18]، فالمعنى: الآخرون ما سجدوا السُّجود الذي أراده الله سبحانه وتعالى، وهكذا قوله جلَّ وعلا: وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ [الإسراء:44]، هذا التَّسبيح لا نعلمه، ولكن الله يعلمه، فهم لا يُسبّحون التَّسبيح الشرعي الذي شرعه الله، ولكن قد يكون هناك تسبيحٌ خاصٌّ يقع منهم بغير قصدهم، أو بقصدهم، لكن ليس هو التَّسبيح الشرعي الذي شرعه الله لعباده.\nولكن التَّسبيح معناه: تنزيه الله، ومعناه: الشَّهادة لله بأنه المنعم، وبأنه ربّ العالمين، فالتَّسبيح هو التنزيه والتَّقديس، وقد يكون بلسان المقال، وقد يكون بلسان الحال، وقد يكون بطرقٍ الله أعلم بها ، ولهذا قال: وَلَكِنْ لَا تَفْقَهُونَ تَسْبِيحَهُمْ [الإسراء:44].\nوقد يكون أراد  بقوله: وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ يعني: ما عدا الكفار، قد يكون أراد لهم، وظهر ذلك من جهة الأدلة، يعني: ظهر استثناؤهم من جهة الأدلة المعروفة أنَّهم ناكبون عن طريق الله، وصادُّون عن سبيل الله، كما استثناهم في السجود، قال: وَكَثِيرٌ مِنَ النَّاسِ معناه: وآخرون لم يسجدوا من الكفرة.\nفالحاصل أن التَّسبيح عامٌّ من جميع المخلوقات، ولكننا لا نفقه تسبيحهم، هذا هو ظاهر الآية: وإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ وَلَكِنْ لَا تَفْقَهُونَ تَسْبِيحَهُمْ، قوله: تُسَبِّحُ لَهُ السَّمَاوَاتُ السَّبْعُ وَالْأَرْضُ وَمَنْ فِيهِنَّ، ثم قال بعدها: وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ يعني: ما من شيءٍ إلا يُسبّح بحمده، فهذه غايةٌ في التَّعميم، وَإِنْ مِنْ شَيْءٍ نكرة في سياق الشرط، في سياق النفي، مِنْ بمعنى ما، فالنكرة في سياق النفي تعمّ الكفار وغيرهم، ولكن يكون تسبيح الكفار تسبيحًا لا نفقهه، تسبيحًا من جهة ما يقع منهم من ذلٍّ واستكانةٍ لربِّهم  صاغرين، داخرين، ومن جهة ما يراه من أعمالهم وتصرُّفاتهم، وما يفعلونه من أشياء غريبة، كلها شاهدةٌ لله بأنه العظيم، وبأنه المُقدَّس .","link":"https://binbaz.org.sa/fatwas/4266/معنى-وان-من-شيء-الا-يسبح-بحمده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0315.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":287,"question":"يوجد عندي أخٌ شقيقٌ مصابٌ بالكلى -بالتهابٍ خطيرٍ في الكلى- وقد عزمتُ على التَّبرع له بكليةٍ، فهل يجوز ذلك، أو أذهب إلى الهند وأشتري كليةً لأخي؟ أرجو الإفادة عظَّم الله أجركم.","title":"حكم التَّبرُّع بالأعضاء للإنسان المضطر","answer":"الجواب: اختلف العلماءُ في هذا: منهم مَن أجاز ذلك، ومنهم مَن لم يُجز ذلك، والأقرب -والله أعلم- جواز ذلك إذا قرر الأطباءُ أنه لا خطرَ عليه، إذا قرر الطبيبُ المُختصُّ أنه لا خطر عليه، وأنه إذا أُخذ منه كلية تنفعه كليته الثانية ولا يضرُّه ذلك، وأنها تنفع لأخيه، تُطابق حاجة أخيه؛ لأنَّ بعض الشيء قد لا يُطابق، فإذا قرر الأطباءُ المُختصون ذلك ولا خطر عليه؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/4285/حكم-التبرع-بالاعضاء-للانسان-المضطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0334.mp3","categories":["الطب والتداوي"]},{"id":328,"question":"إني أحبّكم في الله، والسؤال هو: لقد قال بعضُ طلبة العلم أنه لا يجوز للرجل أن يسأل أخاه أن يدعو له، وقال البعض: بل يجوز ذلك، واستدلّوا بقول الرسول ﷺ لعمر بن الخطاب : لا تنسنا من دعائك يا أخي، فنرجو من سماحتكم توضيح ذلك.","title":"ما حكم سؤال المؤمن أخاه الدعاء له؟","answer":"الجواب: أحبَّك الله الذي أحببتنا له، ولا بأس أن يسأل أخاه يقول: ادع الله لي، لا بأس، ولا حرج في ذلك، لكن ما هو بدائمٍ، بعض الأحيان، بعض الناس دائم كل ساعةٍ: ادع لي، ادع لي، إذا سأله بعض الأحيان حسن، أما دائمًا دائمًا فتركه أوْلى.\nوقد ثبت عن رسول الله ﷺ أنه قال: إنه يقدم عليكم شخصٌ يُقال له: أويس القرني، بار بأمه، قد أصابه برصٌ فعافاه الله منه إلا موضع درهم، فمَن لقيه فليسأله أن يستغفر له رواه مسلم في \"الصحيح\"، فلما لقيه عمر قال: استغفر لي، فإني سمعتُ الرسول يقول هذا في حقِّك. هذا يدل على جواز هذا.\nوكذا جاء عن عمر أن النبيَّ ﷺ قال له لما أراد العمرة: لا تنسنا من دعائك، أو قال: أشركنا في دعائك، ولكن في سنده بعض الضَّعف، لكن يقوى بالحديث الآخر.\nفالحاصل أنَّ هذا لا بأس به، ولا حرج فيه، لكن الأوْلى والأفضل أن يُقلِّل منه الإنسان، بعض الناس كل ساعة يقول: ادع الله لي، ادع الله لي، فينبغي في مثل هذا؛ لأنَّ هذا يُملّ الناس، ويشقّ على الناس، فينبغي أن يكون بين وقتٍ وآخر، ما هو بدائمٍ كل ساعة.","link":"https://binbaz.org.sa/fatwas/4416/ما-حكم-سوال-المومن-اخاه-الدعاء-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0381.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":329,"question":"السلام عليكم ورحمة الله وبركاته، لقد طالعتنا بعضُ الجرائد بأن جنيًّا قد أسلم على يدي سماحتكم، فأرجو توضيح هذا الخبر، وهل يسكن أو يمسّ الجنُّ الإنسان؟","title":"ما قصة إسلام الجني عند الشيخ ابن باز؟","answer":"الجواب: نعم هذا الخبر صحيحٌ، وقد حكى أبو العباس ابنُ تيمية إجماعَ العلماء على إمكان دخول الجني بالإنسي وصرعه إياه، وهذا واقعٌ من عهد النبي إلى يومنا هذا، وقبله كذلك، ومَن استنكر هذا أو شكَّ في هذا؛ فهو من عدم البصيرة، ومن عدم قراءة كتب العلماء، وعدم الاطلاع على ما ذكره العلماء في هذا السَّبيل.\nوقد حضرت عندي امرأةٌ وأولياؤها، وجماعةٌ من أهل العلم حضروا ذلك، وكان قد عالج المرأة الأخُ في الله عبدالله بن يوسف العمري إمام مسجد العُلياء، ووجّه هذا الجني إلى الإسلام، ونصحه، ودعاه إليه، ورغَّبه في الخير، وحذَّره من الظلم، وأوصاه بالخروج من هذه المرأة، والبعد عنها، والكفّ عن أذاها، فتقبّل منه.\nوطلب أولياء المرأة من الراقي أن يحضر عندي هو والمرأة لإعلان إسلامه، فحضروا جميعًا عندي: حضر جمعٌ من المسلمين، وحضر أخواها، وخالها، وأختها، وجماعةٌ من طلبة العلم، وتحدَّث هو على لسان المرأة بصوت رجلٍ لا شكَّ فيه، وتكلم عن أسباب دخوله فيها وتلبُّسه فيها، وذكر أسباب ذلك، وذكر أنه بوذيٌّ، جني من الجن، وأنه اقتنع بوصية المرشد عبدالله بن يوسف العمري، وقَبِلَ منه دعوته، وهداه الله لقبول الإسلام، وأعلن عندي إسلامه، ووصيتُه بما يلزم من الدَّعوة إلى الله في قومه، وأن يكون من شكر الله على نعمة الإسلام أن يدعو قومه، وأن يُوصيهم بالخير كما هداه الله، وكان آخر كلامه بعد المُحادثة أن قال: \"السلام عليكم\"، ثم انفصل عنها.\nوهي بحمد الله بخيرٍ وعافيةٍ، وقد دعوتها منذ أيام قلائل أيضًا وسألتُها عن حالها فقالت: إنها بصحةٍ وعافيةٍ، وأنه لم يعد إليها بعد ذلك من حين غادرها، فذكرت أنها بعدما أصابها هذا من نحو سنتين وهو يُصيبها منه أذى كثير، ومشقَّة كبيرة، وأنه وسوس إليها بأفكار هدّامة، ودعوة إلى البوذية، وأنها تحسّ بنفسها بميول إلى الأفكار الرديئة والديانة البوذية، فلما سلَّمها الله منه؛ زالت عنها تلك الأفكار، وعادت إلى حالها الأولى وطبيعتها الأولى بإسلامها ودينها.\nالمقصود أنَّ هذا واقعٌ، وهذا قد وقع لغيرنا من العلماء القدامى والإمام أحمد بن حنبل، وشيخ الإسلام ابن تيمية، ولغيرهم، وقد وضح ذلك أهلُ العلم، وليس فيه إشكال، والرسول عليه الصلاة والسلام قال: إنَّ الشيطان يجري من ابن آدم مجرى الدم، والجن أقسام، ليسوا على قسمٍ واحدٍ، أقسام، ففي \"الصحيحين\" عن النبي ﷺ قال: إنَّ الشيطان يجري من ابن آدم مجرى الدم.","link":"https://binbaz.org.sa/fatwas/4417/ما-قصة-اسلام-الجني-عند-الشيخ-ابن-باز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0382.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":384,"question":"هل يجوز التَّداوي بشرب الماء وُضعت فيه آيات من القرآن الكريم؟","title":"ما حكم التداوي بماء قُرئت عليه آيات؟","answer":"الجواب: نعم، لا بأس أن يقرأ في الماء ويشرب ويغتسل به أيضًا، هذا من الدواء، من العلاج، والقرآن شفاء وهدى، قد كان النبيُّ ﷺ يُعالج بالقرآن، وأصحابه كذلك يُعالجون بالقرآن، وجاء في سنن أبي داود بإسنادٍ جيدٍ عن النبي ﷺ أنه قرأ لثابت بن شماس بإناء قرأ فيه الماء وصبَّه عليه عليه الصلاة والسلام، وقد قرأ جماعةٌ على اللَّديغ، نفثوا عليه بالفاتحة. فالاستشفاء بالقرآن وقراءته على المرضى أو في الماء، كله لا بأس به.","link":"https://binbaz.org.sa/fatwas/4714/ما-حكم-التداوي-بماء-قرىت-عليه-ايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0440.mp3","categories":["الطب والتداوي"]},{"id":414,"question":"هل يجوز للمرأة أن تستعمل مانعًا للحمل حتى بعد سنتين؟ نرجو الإيضاح.","title":"حكم استعمال وسائل منع الحمل","answer":"الجواب: قد صدر قرار من هيئة كبار العلماء في منع استعمال الحبوب واللَّولب وأشباه ذلك لمنع الحمل إلا عند الضَّرورة: كامرأة مصابة بمرضٍ في رحمها وبدنها يضرُّها الحمل، أو عندها صغارٌ تتابعوا وشقَّت عليها تربيتهم، فإنها تستعمل ذلك سنةً أو سنتين مدة الرضاع، حتى تستعين بذلك على التربية، أما للترفه وعدم المبالاة بالأولاد فلا.","link":"https://binbaz.org.sa/fatwas/4832/حكم-استعمال-وساىل-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0472.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":467,"question":"قول بعض العوام أن المرأة لا تستشار؛ لأنها  ناقصة عقل ودين، هل لهذا وجه؟","title":"هل تُستشار المرأة؟","answer":"الجواب: هذا غلط، النبي ﷺ استشار أم سلمة يوم الحديبية، استشارها فقالت: يا رسول الله انحر هديك واحلق رأسك وإذا رآك الناس فعلت ذلك فعلوا ذلك، ففعل ﷺ، فوافق على رأيها وخرج إلى الناس ونحر الهدي وحلق رأسه.\n(دروس شرح بلوغ المرام، كتاب الطهارة)","link":"https://binbaz.org.sa/fatwas/6192/هل-تستشار-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/salama027.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":508,"question":"قولهﷺ: تربت يداك؟","title":"ما معنى \"تربت يداك\" في الحديث؟","answer":"الجواب: كلمة يقولها العرب وما هي بمقصودة، مثل قوله ﷺ: ثكلتك أمك يا معاذ.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6338/ما-معنى-تربت-يداك-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/maram073 - 01 -  Start.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":565,"question":"الجراحة الحديثة لزراعة الشعر؟","title":"ما حكم زراعة الشعر؟","answer":"الجواب: إذا كان للتداوي ما هو داخل في هذا، إذا كان للتداوي ما هو للعبث أو الزينة أو التشبه بأعداء الله، هذا للتداوي.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6396/ما-حكم-زراعة-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/maram131 - 02 - .mp3","categories":["الطب والتداوي","اللباس والزينة"]},{"id":593,"question":"إذا كان الطبيب عارفًا بالطب وأخطأ في تشخيص المريض فهل يضمن؟","title":"هل يضمن الطبيب عن الخطأ في التشخيص؟","answer":"الجواب: إذا كان عارفًا بالطب واجتهد فما يضمن.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6432/هل-يضمن-الطبيب-عن-الخطا-في-التشخيص","audio":"https://files.zadapps.info/binbaz.org.sa/maram161 - 01 -  Start.mp3","categories":["الجنايات والحدود","الطب والتداوي"]},{"id":705,"question":"ما حكم الانتفاع بالكُلَى أو القلب من شخصٍ قُتِلَ في حدٍّ شرعيٍّ؟ هل يجوز أم لا؟","title":"حكم الانتفاع بأعضاء من قُتل في حد شرعي","answer":"الجواب: هذا فيه خلافٌ بين العلماء: فمنهم مَن أجازه إذا سمح الورثةُ، ومنهم مَن منع ذلك وقالوا: لا يجوز التَّصرف بالميت؛ لأنها مُثْلَة، وقطع جزءٍ من أجزائه هذا محل نظرٍ، وقد بحث هذا أكثرُ العلماء، وأجازه الأكثر، وعندي التَّوقف في ذلك؛ لما فيه من العبث بالأموات.","link":"https://binbaz.org.sa/fatwas/20583/حكم-الانتفاع-باعضاء-من-قتل-في-حد-شرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0536فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الطب والتداوي"]},{"id":853,"question":"يقول هذا السائل: يا فضيلة الشيخ حفظكم الله ورعاكم، رجلٌ له زوجة لا تُطيق الحمل لمرضٍ، فأشار عليها الأطباء بتعاطي حبوب منع الحمل، فعملت بذلك، ثم تخلَّت عنها لمدةٍ، وبعدما تبينت أنها حملت وأخبرها الأطباء بأنَّ هذا الحمل خطرٌ عليها وعلى الجنين؛ فعمدت إلى إسقاطه بمُشاركة زوجها، فماذا يعملان لتكفير ذلك؟ أفيدونا أثابكم الله.","title":"حكم إسقاط الجنين لوجود خطر على الأم","answer":"الجواب: إذا قرر الأطباء أنَّ عليها خطرًا من الولد، وأنَّ على حياتها خطرًا فلا مانع من إسقاطه، ولا حرج في ذلك؛ لأن حياتها مُقدَّمة على حياته، وليس فيه شيء؛ لأنه عمد لمصلحة المرأة.\nوقد قرر مجلس هيئة كبار العلماء عندنا أنَّ مثل هذا لا حرج فيه؛ لأن ذلك فيه وقاية الأم إذا كان الخطرُ عليها، وإذا كان هذا قبل أن تُنفخ فيه الروح فلا شيء في ذلك، ما دام علقة، مُضغة ليس فيه شيء، أما إذا كان قد نُفخت فيه الروح فهذا هو محل العناية، يجب أن يُعتنى بهذا، فإذا قرر جماعة من الأطباء الموثوقين المعروفين أنه يُخشى عليها –يعني: على حياتها خطر- وأن بقاءه قد يُفضي إلى موتها؛ فلا مانع من إسقاطه، إن خرج حيًّا فالحمد لله، وإن مات فلا يضرّ، من باب ارتكاب أدنى المفسدتين لتفويت كُبراهما، ومن باب تحصيل أعلى المصلحتين بتفويت صُغراهما.","link":"https://binbaz.org.sa/fatwas/20887/حكم-اسقاط-الجنين-لوجود-خطر-على-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0682حكم اسقاط الجنين إذا كان بقاء الجنين خطر على الأم؟ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":909,"question":"بعض الناس يُصلون ويقولون بعد الصلاة: يا شفاعة محمد، فهل هذا من الشرك؟","title":"حكم قول: \"يا شفاعة محمد\" بعد الصلاة","answer":"الجواب: \"يا شفاعة محمد\" هذا دعاءٌ لمن لا يعقل، الشفاعة هي معنًى من المعاني، ما تُدعى من دون الله، وهكذا لو قال: \"يا محمد اشفع لي\"، هذا دعاء لغير الله، واستغاثة بغير الله، وقد مات عليه الصلاة والسلام، فلا تُطلب الشفاعة منه، بل تطلب من الرب : اللهم شفِّع فيَّ نبيك، اللهم شفِّع في عبادك الصَّالحين. أما \"يا شفاعة محمد\" أو \"يا محمد اشفع لي\" هذا من أنواع الشرك الأكبر؛ لأنه استغاثة بغير الله، وطلب الشفاعة من الشفاعة، هذا منكرٌ عظيمٌ، وشركٌ وخيمٌ، مثل ذلك: \"يا إغاثة محمد\" أو \"يا إغاثة البدوي\" أو \"يا إغاثة الست نفيسة\" أو \"يا إغاثة الجيلاني\" أو \"يا شفاعة الجيلاني\"، معناه دعاؤه من دون الله، والاستغاثة به، والشفاعة تُطلب من الحيّ الحاضر القادر على أن يشفع لك، أما الميت ما تُطلب منه، تُطلب من الله .","link":"https://binbaz.org.sa/fatwas/20952/حكم-قول-يا-شفاعة-محمد-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0748ما حكم قول بعد الصلاة يا شفاعة محمد؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":914,"question":"متى تُرفع الأيدي عند الدّعاء؟","title":"حكم رفع الأيدي للدّعاء ومسح الوجه بها","answer":"الجواب: في كل دعاء تُرفع الأيدي، في كل الدعاء، إلا الدعاء الذي ما رفع فيه النبيُّ ﷺ، مثل: دعاء الخطبة في خطبة الجمعة، لا يرفع الأيدي؛ لأنَّ النبي ما كان يرفع يديه، وهكذا صلاة العيد، لا يرفع في خطبتها، وهكذا بين السَّجدتين لا يرفع، وهكذا في آخر التحيات والدعاء لا يرفع؛ لأن النبي ما رفع، وهكذا إذا سلَّم من الصلاة لا يرفع؛ لأن النبي ما رفع عليه الصلاة والسلام.\nأما الدعوات التي لم تُوجد في عهده ﷺ، أنه لم يرفع فيها؛ فإنه يرفع، مثل: الاستسقاء، رفع فيها النبيُّ ﷺ، وهكذا سائر الدعاء.\nفرفع اليدين في الدعاء من أسباب الإجابة، لكن الدعاء الذي فعله النبيُّ ﷺ ولم يرفع فيه لا يُشرع لنا أن نرفع فيه؛ لأنه لو كان خيرًا سبقنا إليه عليه الصلاة والسلام، فهو دعا بين السَّجدتين، ودعا في آخر الصلاة ولم يرفع، ودعا في خطبة الجمعة ولم يرفع.\nولما رأى بعضُ الصحابة بِشر بن مروان يرفع في خطبة الجمعة أنكر عليه ذلك، وما كان النبيُّ يرفع في خطبة الجمعة عليه الصلاة والسلام.\nس: القنوت ترفع الأيدي، أحسن الله إليك؟\nالشيخ: أما القنوت فنعم، ثبت أنه عليه الصلاة والسلام رفع في القنوت في النوازل عليه الصلاة والسلام.\nس: يمسح بها الوجه؟\nالشيخ: الوجه وردت فيه أحاديث ضعيفة، فمَن تركه فلعله أوْلى؛ لأنَّ الأحاديث الصَّحيحة ليس فيها مسحٌ، ومَن فعله فقد قال به بعضُ أهل العلم، قال بعضُ أهل العلم أن الأحاديث وإن كانت ضعيفةً لكن يشدُّ بعضُها بعضًا، وتكون من قبيل الحسن لغيره، هكذا قال الحافظُ ابن حجر في \"البلوغ\" -في آخر \"البلوغ\"- قال: إنَّ هذا من قبيل الحسن.\nولهذا ذهب بعضُ أهل العلم إلى أنه يمسح وجهه بالدعاء، ولكن الأحاديث الصَّحيحة ليس فيها مسحٌ، فالأولى ترك ذلك؛ عملًا بالأحاديث الصَّحيحة الثابتة، وقد دعا في الاستسقاء ولم يمسح وجهه عليه الصلاة والسلام، ودعا في مواضع كثيرةٍ صحيحة ولم يمسح وجهه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/20945/حكم-رفع-الايدي-للدعاء-ومسح-الوجه-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0741متى ترفع الأيدي عند الدعاء ؟ وهل يجوز مسح الوجه بعد الدعاء؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":917,"question":"ما حكم الإسلام في الذَّهاب إلى السَّحرة بخصوص عمل حجابٍ لاستجلاب المحبَّة بين زوجين معهما أطفال كادا أن يتفرقا؟","title":"حكم الذَّهاب للسَّحرة لجلب المحبَّة بين زوجين","answer":"الجواب: الذهاب إلى السَّحرة منكر، والكهنة والعرَّافون لا يجوز الذَّهاب إليهم، ولا سؤالهم، ولا تصديقهم، يقول النبي ﷺ: مَن أتى عرَّافًا فسأله عن شيءٍ لم تُقبل له صلاة أربعين ليلة.\nالعرَّاف الذي يدَّعي ماهية الأمور، بدعوى علم الغيب، وبخدمة الشياطين والجن، أو بالكف، أو ما أشبه ذلك من الخرافات، أو باستحضار الأرواح، كل هؤلاء يُقال لهم: عرَّافون، ويُقال لهم: كهنة، وهكذا مَن يتعاطى السحر بالنظر في النجوم، وبغير ذلك، أو باستخدام الشياطين، وكل هؤلاء لا يُؤتَون، ولا يُسألون.\nومَن كانت كهانته وسحره بعبادة غير الله وسؤال الشياطين والاستغاثة بهم صار كفرًا أكبر -نعوذ بالله- والسحرة معلومٌ أنهم إنما يتعاطون من طريق عبادة الجنّ وخدمتهم، ولهذا قال : وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ يعني: الملكين حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ [البقرة:102]، فدلَّ على أنَّ السحر كفرٌ.\nولكن للمُصاب بالأمراض -الحمد لله- دواء بالقراءة من القُرَّاء المعروفين بالتقوى والإيمان، بتعاطي الطب المعروف المادي، ليقرأ على نفسه هو، أو يقرأ عليه أخوه، أو أبوه، أو نحو ذلك، فالله جعل في القرآن شفاءً أيضًا من أمراضٍ كثيرةٍ، كما أنه شفاءٌ للقلوب من أمراضها وشركها ونفاقها وكبرها وحسدها، فهو شفاءٌ لكثيرٍ من أمراض الأبدان أيضًا بإذنه سبحانه وتعالى، فإذا قرأ على نفسه الفاتحة وآية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، أو قرأ عليه أخوه، أو أبوه، أو أمه، أو نحو ذلك، أو بعض الأخيار من أهل الإيمان والتقوى؛ يُرجى له الخير والعافية.","link":"https://binbaz.org.sa/fatwas/20967/حكم-الذهاب-للسحرة-لجلب-المحبة-بين-زوجين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0763ما حكم الإسلام في الذهاب إلى السحرة لعمل حجاب لاستجلاب المحابة بين الزوجين؟ابن باز.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":975,"question":"هل صحيحٌ ما يُقال بأنَّ المرأتين تكونان مَحْرَمًا لبعضهما، أو أربع حريم يحرم بعضهنَّ لبعض؟","title":"هل يصح أن تكون المرأة مَحْرَمًا لأخرى؟","answer":"الجواب: ليس بصحيحٍ، المرأة ما تكون محرمًا لغيرها، لا لبنتها، ولا لأمِّها، ولا لأختها، المحرم يكون الرجل، يقول النبيُّ ﷺ: لا تُسافر المرأةُ إلا مع ذي محرمٍ منها، ثم ذكر زوجَها وأباها ونحوه. فالمحرم هو الرجل الذي تحرم عليه على التَّأبيد بنسبٍ أو سببٍ مباحٍ: كالمصاهرة، والرضاع، هذا المحرم: زوجها، أبوها، أخوها، ولدها، عمُّها، خالها، هذا المحرم، ابن أخيها، نعم.","link":"https://binbaz.org.sa/fatwas/21017/هل-يصح-ان-تكون-المراة-محرما-لاخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0814هل صحيح ما يقال بأن المرأتين تكونان محرماً لبعضهما أو أربع حريم؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":978,"question":"في كلمات مُتداولة بين الناس، وهي: يا وجه الله، يا رفعة الله، يا فزعة الله، هل فيها شيءٌ؟ وهل دعاء الصِّفة فيه شيءٌ؟ وهل مَن وقع في الشرك وهو ليس عامدًا يُؤاخذ بذلك، حيث إنَّ كثيرًا من الناس يقعون فيه على غير قصدٍ؟ فهل من توضيحٍ وفَّقكم الله؟","title":"ما حكم قول: يا وجه الله ورحمة الله ونحوه؟","answer":"الجواب: ذكر أبو العباس ابن تيمية رحمه الله أنه لا يجوز دعاء الصفة، وحكى الإجماعَ على ذلك، لكن ليس بكفرٍ؛ لأنَّ هذا مقصودهم الله: \"وجه الله\" يعني: يا الله، المقصود: يا عزة الله، ويا فزعة الله، ويا رحمة الله، مقصودهم الله، لكن أساؤوا التَّعبير، فالواجب أن يقول: يا الله، يا رب العرش، يا ربنا، يا مولانا، يا عزيز، يا حكيم، ونحو ذلك، لا يدعو الصفة: يا رحمة الله، ولا: يا علم الله، ولا: يا كلام الله، ولا: يا عزة الله، ولا يا فزعة الله، لا يجوز هذا، ولكن يدعو الله جلَّ وعلا يقول: يا الله، يا رب العالمين، يا إلهي، يا ربي، يا ذا الجلال والإكرام، يا عزيز، يا حكيم، يا رؤوف، يا قدير، يا سميع، يا بصير، كسائر الصِّفات، هذا هو الواجب، لكن ليس بهذا يا رحمة الله ويا فزعة الله لا؛ لأنَّ مراده دعاء الله، لكن أساء التعبير في دعاء الصِّفة، وليس مقصوده إلا دعاء الله.\nوالصِّفات يتوسَّل بها، لا تُدعى، لكن يتوسَّل بها، فيقول: \"اللهم إني أسألك برحمتك، أسألك بعزتك، أسألك بجودك وكرمك، أسألك بإحسانك، أسألك بكمال قدرتك، أن تغفر لي، أن ترحمني\"، يتوسل إلى الله بصفاته وأسمائه: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، ولهذا كان الرسول ﷺ يتوسَّل إلى الله بأسمائه وصفاته جلَّ وعلا في دعواته.","link":"https://binbaz.org.sa/fatwas/21032/ما-حكم-قول-يا-وجه-الله-ورحمة-الله-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0829ما حكم من يقول يا وجه الله يا رحمة الله يا فزعة الله؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1010,"question":"ما حكم رفع اليدين بالدعاء بعد السنة الراتبة، والفريضة، وبعد الأذان، ومسح الوجه بهما بعد الدعاء؟","title":"حكم رفع اليدين بالدعاء بعد الفرض والراتبة","answer":"الجواب: أما بعد الفريضة فلا نعلم له أصلًا، ما كان النبيُّ يفعل إذا سلَّم من فريضته يرفع يديه، ولا الصحابة، أما السنن الراتبة فلا نعلم بأسًا في ذلك، لكن لا يكون بصفةٍ مستمرةٍ، تارةً وتارةً؛ لأنه لم يُحفظ عنه ﷺ أنه كان يرفع يديه بعد النافلة بصفةٍ مستمرةٍ، فإذا فعله بعض الأحيان ودعا ربَّه في الاستخارة، صلَّى واستخار ودعا ربَّه ورفع يديه، أو في بعض الأحيان صلَّى ودعا ربَّه ورفع يديه، فرفع اليدين من أسباب الإجابة، وهكذا لو عرض عارضٌ ورفع يديه ودعا في بيته، أو في المسجد، أو في الطريق؛ لعارضٍ عرض، كل ذلك من أسباب الإجابة، فرفع اليدين من أسباب الإجابة، وفي الحديث الصحيح: إنَّ ربَّكم حييٌّ كريمٌ، يستحي من عبده إذا رفع يديه أن يردَّهما صفرًا.\nلكن المواضع التي ما رفع فيها النبيُّ يديه لا نرفع، مثل: بعد الفريضة، مثل: خطبة الجمعة، كان يدعو ولا يرفع في خطبة العيد، دعا ولا رفع، وهكذا في صلاته: دعا في آخر الصلاة قبل أن يُسلِّم ولم يرفع، دعا بين السَّجدتين ولم يرفع، دعا بعد السلام ولم يرفع في الفرائض. أما في النوافل فلا نعلم في ذلك شيئًا ثابتًا عن رسول الله ﷺ، لكن للعموم، إذا فعله بعض الأحيان للعموم في بعض النوافل بعدها، أو في أوقاتٍ أخرى؛ فذلك من أسباب الإجابة.","link":"https://binbaz.org.sa/fatwas/21066/حكم-رفع-اليدين-بالدعاء-بعد-الفرض-والراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0862ما حكم رفع اليدين بالدعاء بعد السنة الراتبة والفريضة؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1023,"question":"كيف يمكن العلاج من السحر؟","title":"ما كيفية العلاج من السحر؟","answer":"الجواب: العلاج من السحر يكون بالرقية من كلام الله، وبالدعوات الطيبة، يُرقى المريضُ بالآيات: آية الكرسي، بالفاتحة، وقُلْ هُوَ اللَّهُ أَحَدٌ، والمعوذتين، وغيرها من الآيات، وإذا قرأ في ماءٍ أيضًا وشرب منه وتروش به فهو من العلاج، وهو أيضًا مما ينفع من حبس الرجل عن زوجته وعن امرأته، كونه ينفث على نفسه بالفاتحة، وآية الكرسي، وبـقُلْ هُوَ اللَّهُ أَحَدٌ، والمعوذتين، أو ينفث عليه غيره، أو يقرأ ذلك في ماءٍ ثم يشرب منه ويصبُّه على بدنه، كل ذلك من العلاج.\nوإن جعل في البيت سبع ورقات من السدر: دقَّها وجعلها في ماءٍ، فهذا أيضًا مما ينفع من حبس الرجل عن امرأته، ومما ينفع من السحر.\nولا يجوز الذهاب إلى السحرة، ولا الكهنة، لا، ولكن يُعالج نفسه بآيات الله، إما بأن يقرأ هو بنفسه على نفسه، يقرأ في يديه، يمسح بهما على رأسه ووجهه وصدره، وهكذا عند النوم، كان النبيُّ يفعل هذا، إذا اشتكى قرأ في يديه: قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، عند النوم، ومسح بهما ما أقبل من جسده: رأسه ووجهه وصدره ثلاث مراتٍ عليه الصلاة والسلام، كل هذا من أسباب الشِّفاء.\nوقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ وقُلْ أَعُوذُ بِرَبِّ النَّاسِ سورتان عظيمتان، علاجٌ لكل داءٍ، لكل مرضٍ، ما تعوَّذ مُتعوِّذٌ بمثلهما كما جاء في الحديث، فإذا قرأ على نفسه: قُلْ هُوَ اللَّهُ أَحَدٌ... وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ... وقُلْ أَعُوذُ بِرَبِّ النَّاسِ... وكرر ذلك، أو قرأ في ماءٍ وشربه وتروّش به، أو قرأ له غيرُه من إخوانه، أو فعل ذلك عند النوم ومسح على ما أقبل من جسده: رأسه وصدره ووجهه، كل هذا من العلاج،. والعلاج يفعله الإنسانُ بنفسه، أو يفعله غيرُه من طلبة العلم... يقرأ عليه أحدُ طلبة العلم، أو أخوه، أو أبوه، أو هو على زوجته، أو زوجته عليه إذا كانت تُحسن ذلك، الأمر واسع بحمد الله، تقرأ بنفسك، تنفث بنفسك، ينفث عليك أخوك، إخوانك المعروفون بالخير، أو ينفث عليك أخوك، أو أبوك، أو زوجتك، أو أختك، أو أمك، تقرأ الفاتحة، وآية الكرسي، وما تيسر من القرآن، وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، كل هذا من العلاج للسحر ولأمراضٍ أخرى، ولحبس الرجل عن زوجته.","link":"https://binbaz.org.sa/fatwas/21074/ما-كيفية-العلاج-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0870كيف العلاج من السحر؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":1024,"question":"وقول: \"ربّ اغفر لي ولوالديَّ بين السَّجدتين\"؟","title":"حكم \"رب اغفر لي ولوالدي\" بين السجدتين","answer":"الجواب: إذا قال: \"رب اغفر لي ولوالدي\" أو: \"اللهم أجرني من النار\" لا يضرُّه؛ لأنها محلُّ دعاءٍ، لكن يُكثر من قوله: رب اغفر لي، رب اغفر لي، رب اغفر لي، كما أكثر النبيُّ ﷺ، وجاء عنه ﷺ: اللهم اغفر لي ذنبي كلَّه، دقه وجله، وجاء فيه: اللهم اغفر لي، وارحمني، واجبرني، وارزقني، وعافني، جاء فيه دعوات، لكن أفضلها وأهمها: رب اغفر لي، حتى قال بعضُ أهل العلم: إنها واجبة مرةً واحدةً، وما زاد فهو سنة، وقال جمهورُ أهل العلم: إنها كلها سنة غير واجبةٍ: رب اغفر لي، وارحمني أو: اغفر لي ولوالدي سنة، ولكن كونه يتحرى ربي اغفر لي؛ لأن النبيَّ كان يقولها ويُكثر منها هو الذي ينبغي.\nوالقول بأنها واجبةٌ قولٌ قويٌّ؛ لأنَّ النبي عليه السلام كان يقولها، ويقول: صلُّوا كما رأيتُموني أُصلِّي، فإذا قالها مرةً كفته، والأفضل تكرارها ثلاثًا أو أكثر، مع قوله: اللهم اغفر لي، وارحمني، واهدني، واجبرني، وارزقني، وإذا قال: \"اللهم اغفر لي ولوالدي\"، أو \"اللهم اغفر لي وللمسلمين\"، أو \"اللهم أصلح ولاةَ أمرنا\" ما نعلم فيها محذورًا؛ لأنها محلُّ دعاء، بين السجدتين محل دعاء، وكان النبيُّ يُطيلها عليه الصلاة والسلام، يُطيل ما بين السَّجدتين، لكن الإكثار من ربِّ اغفر لي في هذا المقام أفضل، والواجب مرة واحدة.","link":"https://binbaz.org.sa/fatwas/21073/حكم-رب-اغفر-لي-ولوالدي-بين-السجدتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0869ما حكم قول ربِّ اغفر لي ولوالدي بين السجدتين؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1028,"question":"ما الحكم فيما يلي: أولًا: التَّداوي قبل وقوع الداء: كالتَّطعيم؟","title":"حكم التداوي قبل وقوع الداء كالتطعيم ونحوه","answer":"الجواب: لا بأس بالتَّداوي إذا خشي وقوع الداء، إن خشي وقوع الداء لوجود الوباء أو أسبابٍ أخرى يخشى من وقوع..... بها فلا بأس بتعاطي الدواء؛ لدفع البلاء الذي يخشى منه، يقول النبي ﷺ في الحديث الصحيح: مَن تصبَّح بسبع تمرات من تمر المدينة لم يضرّه سحرٌ ولا سمٌّ، فهذا من دفع البلاء، التَّصبّح بالتمرات السبع لدفع البلاء قبل وقوعه، يخشى من وقوع السحر أو السم، فهكذا إذا خشي من مرضٍ وطعم ضد الوباء الواقع في البلد، أو في المستشفى، أو في أي مكانٍ لا بأس بذلك، من باب الدفاع، كما يُعالج المرض النازل، يُعالج بالدواء المرض الذي يخشى منه. لكن لا تجوز التَّعليقات، كونه يُعلِّق تميمةً أو ودعةً، يخشى عينًا، أو يخشى مرضًا، لا، لا يجوز التَّعليق، تعليق التَّمائم لا يجوز، نهى عنها النبيُّ ﷺ، لكن الدواء بالكي، بشرب الدواء، بمروخ، بإبرة ضدّ ما يخشى منه، يطعّمه بذلك؛ فلا بأس به.","link":"https://binbaz.org.sa/fatwas/21101/حكم-التداوي-قبل-وقوع-الداء-كالتطعيم-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0897ما حكم التداوي قبل وقوع الداء كالتعطيم ضد مرض معين؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي"]},{"id":1029,"question":"ما رأي سماحتكم في أنَّ عمل الطبيب يتطلب في بعض الأحيان رؤية عورة المريض، أو مسّها للفحص؟ وفي بعض الأحيان أثناء العمليات يعمل الطبيبُ الجراح في وسطٍ مليء بالدم والبول، فهل إعادة الوضوء واجبة في هذه الحالات أم أنه لا يجب عليه؟","title":"ما حكم مس الطبيب للعورة والنجاسة للحاجة؟","answer":"الجواب: لا حرج في أن يمسَّ الطبيبُ عورةَ الرجل للحاجة، وينظر إليها للعلاج، سواء كان الدبر أو الذكر، ينظر للحاجة والضَّرورة، ولا بأس أن يلمس الدم إذا دعت الحاجةُ إلى لمسه الجرح لإزالة، أو لمعرفة حال الجرح، ويغسل يده بعد ذلك مما أصابه، ولا ينتقض وضوؤه بلمس الدم والبدن. لكن إذا مسَّ العورة -مس الفرج، مسّ الذكر والدبر- ينتقض وضوؤه، أما إذا مسَّ البدن أو الخصية فقط لا ينتقض وضوؤه، لكن متى مسَّ الذَّكَر من دون حائلٍ –يعني: مسّ اللحمُ اللحمَ- فإنه ينتقض الوضوء؛ لقول النبي ﷺ: مَن أفضى بيده إلى فرجه ليس دونهما سترٌ وجب عليه الوضوء.\nوهكذا الطبيبة إذا مسَّت فرج المرأة للحاجة ينتقض وضوؤها، ولا بأس أن تمسَّ فرج المرأة للحاجة إلى العلاج -الدبر أو القبل للحاجة- وإذا مسَّته من دون حائلٍ بأن مسَّ اللحمُ اللحمَ وهي على وضوء ينتقض الوضوء، لا تُصلي إلا بعد الوضوء؛ لقول النبي ﷺ: مَن أفضى بيده إلى فرجه...، وفي الحديث الآخر: أيُّما رجلٍ أفضى بيده إلى فرجه فعليه الوضوء، وأيما امرأةٍ أفضت بيدها إلى فرجها فعليها الوضوء، وإذا كان فرجُ الإنسان فيه الوضوء، فإذا أفضى إلى فرج غيره من باب أوْلى؛ لأنه أشد عورة، ولكن وجود النَّجاسة لا ينقض الوضوء، كونه يقرب النَّجاسة أو يلمسها بيده للجرح، أو في الفرج، لا ينقض الوضوء، إلا من جهة المس؛ فإذا مسَّ الفرجَ وعلى يده حائل لا ينقض الوضوء، وهكذا الطبيبة إذا كان في يدها حائلٌ عند مسِّ الفرج لا ينتقض الوضوء.","link":"https://binbaz.org.sa/fatwas/21100/ما-حكم-مس-الطبيب-للعورة-والنجاسة-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0896ما حكم مس الطبيب لعورة المريض للحاجة وهل ينتقض وضوءه؟ ابن باز فتاوى المحاضرات.mp3","categories":["نواقض الوضوء","الطب والتداوي"]},{"id":1032,"question":"هل يجوز لنا أن نُعطي بعض المرضى أدوية مُعينة لتخفيف نزع الموت وآلامه، علمًا بأن هذه الأدوية تُذهب المريض عن وعيه تمامًا، وقد يموت في أثناء نومه ذلك دون تمكنه من التَّلفظ بالشَّهادة عند الموت؟","title":"حكم إعطاء المريض أدوية لتخفيف آلام الموت","answer":"الجواب: إذا كانت هذه الأدوية قد تُسبب الموت العاجل لا، لا يجوز. أما إذا كانت لتخفيف الألم فقط، لكن ما تُسبب الموت، ولا تُعين على أسباب الموت؛ فلا بأس، إذا كانت لتخفيف الألم فقط. أما أنها أدوية تُعين على إزهاق الروح وتعجيل إزهاق الروح فهذا لا يجوز؛ لأن هذا أمرٌ من القتل، ومُساعدة على القتل. لكن إذا كانت لتخفيف الآلام وتسهيل خروج الروح من دون إعانةٍ على خروج الروح  في الموت، ولكنَّها تُعين على تخفيف الألم أو زوال الألم؛ فلا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/21094/حكم-اعطاء-المريض-ادوية-لتخفيف-الام-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0890هل يجوز لنا أن نعطي للمريض أدوية معينة لتخفيف نزع الموت وآلامه؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي"]},{"id":1033,"question":"يوجد لدينا بالمُستشفى -وكذلك في جميع المُستشفيات- بعض الأدوية التي تُستعمل لعلاج الآلام بعد العمليات، وكذلك لعلاج الآلام المُختلفة، وهذه الأدوية تحتوي على مواد مُخدرة، وأخرى كحولية بنسبٍ متفاوتةٍ، ثم إذا كان هنالك حرجٌ شرعيٌّ في استخدامها فهل هناك من فتوى إيجابية بالنظر فيها وعرضها على الجهات المسؤولة في وقت تداولها؟","title":"حكم الأدوية التي بها بعض المخدر أو الكحول","answer":"الجواب: بسم الله الرحمن الرحيم، والصلاة والسلام على رسول الله. الأدوية التي تحصل بها راحة المريض وتخفيف الآلام عنه لا حرج فيها، ولا بأس بها قبل العملية وبعد العملية، أما إذا علم أنها من شيءٍ مُسْكِرٍ أو من شيءٍ كثيره يُسكر فلا تُستعمل؛ لقوله ﷺ: ما أسكر كثيره فقليله حرام، أما إذا كانت لا تُسكر ولا يُسكر كثيرها، ولكن يحصل بها بعض التَّخفيف والتَّخدير لتخفيف الآلام فلا حرج في ذلك. المُحَرَّم أن تكون مُسكرةً تُزيل العقل، أو كثيرها يُسْكر، فإذا كان كثيرها يُسكر؛ حرم قليلها وكثيرها جميعًا، أما ما دامت تُخفف الآلام وتُسهل على المريض أداء العملية -كالبنج ونحو ذلك-؛ فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/21092/حكم-الادوية-التي-بها-بعض-المخدر-او-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0888يوجد في بعض الأدوية نسبة متفاوته من المخدر والكحول فما حكم الشرع في ذلك؟ ابن باز.mp3","categories":["الطب والتداوي"]},{"id":1052,"question":"ما حكم مُصافحة النساء؟","title":"ما حكم مُصافحة النساء؟","answer":"الجواب:\nمصافحة النساء فيها تفصيل: إن كانت من المحارم -كأمه وعمَّته وزوجته- فلا بأس، وإن كانت من غير المحارم فلا تجوز، مدَّت إلى النبي ﷺ امرأةٌ يدها لتُصافحه فقال: إني لا أُصافح النساء، وقالت عائشةُ رضي الله عنها: \"والله ما مسَّت يدُ رسول الله يدَ امرأةٍ قط، ما كان يُبايعهن إلا بالكلام\" عليه الصلاة والسلام.\nفلا تُصافح الرجال، ولا يُصافحهنَّ الرجال، بل يكون السلام من دون مصافحةٍ: مع زوج أختها، مع أحمائها من إخوان زوجها، أو أعمامه، كلامٌ بدون مصافحةٍ: السلام عليكم، وعليكم السلام، كيف حالك؟ كيف أولادك؟ وما أشبه ذلك، من دون مُصافحةٍ، وما كان من عادة بعض القبائل وبعض الناس يجب تركه، من عادة بعض القبائل المصافحة لنسائهم، هذا غلطٌ، يجب ترك العادة المخالفة للشَّرع.","link":"https://binbaz.org.sa/fatwas/21103/ما-حكم-مصافحة-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0899ما حكم مصافحة النساء؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1068,"question":"بماذا يكون التَّسبيح عقب الصَّلوات؟ هل يكون بالأنامل أم يكون بمفاصل الأصابع؟","title":"هل يُعقد التسبيح بالأنامل أم مفاصل الأصابع؟","answer":"الجواب:\nبأنامل الأصابع، يُعدّ التسبيح بالأصابع، كان يعده بالأصابع، يعقد بالأصابع عليه الصلاة والسلام، هذه هي السُّنة. يُسبح ثلاثًا وثلاثين، ويحمد ثلاثًا وثلاثين، ويُكبِّر ثلاثًا وثلاثين بعد كل فريضةٍ، ويقول تمام المئة: \"لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير\"، هذا نوعٌ، وإن جعل بدل التَّهليلة تكبيرة رابعة وثلاثين فسُنَّة أيضًا، وإن كبَّر وحمد وهلل وسبَّح خمسًا وعشرين فسنة أيضًا: \"سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر\" خمس وعشرون مرة، هذا نوعٌ أيضًا، ويكون هذا بعد استغفاره ثلاثًا، وبعد قوله: \"اللهم أنت السلام، ومنك السلام، تباركتَ يا ذا الجلال والإكرام\"، بعد قوله: \"لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيءٍ قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله، مخلصين له الدين ولو كره الكافرون، اللهم لا مانعَ لما أعطيتَ، ولا مُعطي لما منعتَ، ولا ينفع ذا الجدِّ منك الجدُّ\"، هذا ثابتٌ عن النبي ﷺ بعد كل فريضةٍ، بعضه من حديث ثوبان عند مسلم، وبعضه من حديث ابن الزبير عند مسلم، وبعضه من حديث المغيرة بن شُعبة عند الشيخين، ثم يأتي بالتَّسبيح والتَّحميد والتَّكبير ثلاثًا وثلاثين، إلى آخره.","link":"https://binbaz.org.sa/fatwas/21114/هل-يعقد-التسبيح-بالانامل-ام-مفاصل-الاصابع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0910بماذا يكون التسبيح عقب الصلوات هل يكون بالأنامل أم يكون بمفاصل الأصابع؟ ابن باز.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1087,"question":"هل يجوز لطالبات الطبّ تشريح رجلٍ ميتٍ؟","title":"هل يجوز لطالبات الطب تشريح رجل ميت؟","answer":"الجواب:\nهذا فيه قرارٌ من هيئة كبار العلماء مُوزَّع على الجامعات، ومُوزَّع على المستشفيات: أنه لا يجوز تشريح جثة المسلم، وفي إمكان الدولة تحصيل جثث أخرى يتعلم فيها الطلبة والطالبات.  أما جثة المسلم فلا يجوز؛ لأنه محترمٌ حيًّا وميتًا، وفي إمكان الدولة أن تستجلب جثثًا كافرةً ليس لها حُرمةٌ؛ للتعلم.","link":"https://binbaz.org.sa/fatwas/21129/هل-يجوز-لطالبات-الطب-تشريح-رجل-ميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0925هل يجوز طالبات الطب تشريح جثة الميت؟ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي"]},{"id":1092,"question":"هل التَّبرع بالدم، أو بأعضاء الإنسان، حيًّا أو ميتًا، جائزٌ؟ أفتونا جزاكم الله خيرًا.","title":"حكم التَّبرع بالدم وأعضاء الإنسان حيًّا أو ميتًا","answer":"الجواب:\nأما التَّبرع بالدم عند الضَّرورة إليه فلا بأس ولا حرج في ذلك، قد صدر من مجلس هيئة كبار العلماء قرار بذلك؛ لما فيه من المصلحة العظيمة، من دون مضرَّةٍ، عند الضَّرورة؛ لإنقاذ المريض، كما يجوز أكل الميتة.\nأما التبرع بالأعضاء: فهذا للعلماء فيه خلافٌ: علماء العصر منهم مَن أجازه، ومنهم مَن منعه، وعندي فيه توقُّفٌ، ولستُ ممن يُجيزه، عندي فيه توقف.\nالتبرع بالكلية أو بالقلب أو بغير ذلك أجازه بعضُ أهل العلم، وقالوا: من باب الإحسان، ومن باب التبرع، ومن باب الجود.\nوآخرون منعوه وقالوا: إنَّ هذا نوعٌ من التمثيل، ونوعٌ من الخطر، وليس له تصرُّفٌ في ذاته، ولا في أعضائه، وربما تصرَّف تصرُّفًا يضرُّه، يُفضي إلى موته.\nوبعض أهل العلم توقَّف في ذلك، وأنا من المتوقفين في جواز هذا.","link":"https://binbaz.org.sa/fatwas/21159/حكم-التبرع-بالدم-واعضاء-الانسان-حيا-او-ميتا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0955هل التبرع بالدم أو بأعضاء الإنسان حياَ أو ميتاً جائز؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي"]},{"id":1097,"question":"بعض الناس يُجيز سفر المرأة بغير محرمٍ مع نسوةٍ ثقات، مُستدلًّا بما ورد أنَّ الأمن ينتشر حتى تخرج المرأة مُتاجرةً وحدها، لا تخشى إلا الله والذئبَ على غنمها، ويزعمون أنَّ بعض أمهات المؤمنين كن يخرجن بلا محرم. أفيدونا جزاكم الله خيرًا.","title":"حكم سفر المرأة بدون محرم مع الأمن","answer":"الجواب:\nالصواب: لا بد من محرمٍ؛ لقول النبي ﷺ: لا تُسافر امرأةٌ إلا مع ذي محرمٍ متفق على صحَّته.\nوأما حديث: لا تخاف إلا الله والذئبَ على غنمها فهذا ليس فيه إذنٌ، وإنما فيه خبرٌ عن وجود الأمن، وأنَّ هذا يقع، والإخبار عن الواقع غير بيان الأحكام الشرعية، الإخبار عن الواقع شيءٌ والأحكام شيءٌ ثانٍ، هذا من التلبيس بالاحتجاج بهذا، هذا من اتباع المتشابه، والرسول ﷺ قد قال: إذا رأيتُم مَن يتبع المتشابه فأولئك الذين سمَّى الله فاحذروهم، هذا لا يجوز، يجب الأخذ بالأحاديث الصريحة الصحيحة الواضحة، ولهذا قال ﷺ: لا تُسافر المرأةُ إلا مع ذي مَحْرَمٍ، ولما بلغه أنَّ زوجة رجلٍ خرجت حاجَّةً، وكان في غزوٍ، قال: انطلق فحُجَّ مع امرأتك.\nولكن بعض العلماء أجاز سفر المرأة مع النساء الأمينات الثِّقات، ولكنه اجتهادٌ، والصواب خلاف ذلك، وأنها لا تُسافر إلا مع ذي محرمٍ ولو كان معها نساء، الرسول ﷺ أفصح الناس، وأنصح الناس، فلو كان هذا جائزًا لقال: \"إلا مع ذي محرمٍ، أو مع النساء الأمينات\"، ما أتى بهذه الزيادة، قال: إلا مع ذي محرمٍ عليه الصلاة والسلام، وهو يعرف أن يتكلم، ويعرف أن ينصح، ويعرف أن يُوضّح، وأقدر الناس على البيان عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21154/حكم-سفر-المراة-بدون-محرم-مع-الامن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0950ما حكم سفر المرأة بدون محرم؟ ابن باز فتاوى المحاضرات.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1133,"question":"هل العدسات المُلونة لمُعالجة ضعف البصر أو لغيره مُحرَّمة أم لا؟","title":"حكم العدسات الملونة لضعف البصر وغيره","answer":"الجواب:\nإذا كان للحاجة لا بأس، أما للزينة فتركها أوْلى. أما للحاجة: لضعف البصر، أو أمراض أخرى، فلا بأس بها، مثل: تركيب زجاج للعينين لتكبير الخطِّ ونحوه، نعم.","link":"https://binbaz.org.sa/fatwas/21199/حكم-العدسات-الملونة-لضعف-البصر-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0995هل يجوز لبس العدسات الملونة لضعف النظر او لغيره؟ ابن باز.mp3","categories":["الطب والتداوي"]},{"id":1135,"question":"ما حكم تقبيل الوالد أو الأخ في الفم أو الخدّين؟","title":"حكم تقبيل الوالد أو الأخ في الفم أو الخدّين","answer":"الجواب:\nالسنة التَّقبيل على الرأس، وبين العينين، أو الأنف، ما هو على الفم، الفم يكون للزوج والزوجة.  أما تقبيل الوالد والأخ الكبير: على رأسه أو بين عينيه أو أنفه، كتقبيل البنت: يُقبِّلها مع خدِّها، أو يُقبِّلها أخوها مع خدِّها، أو كانت كبيرةً: مع رأسها وبين عينيها. أما الفم فالأوْلى تركه، إلا الصغير الذي لا يزال صغيرًا فلا بأس.","link":"https://binbaz.org.sa/fatwas/21197/حكم-تقبيل-الوالد-او-الاخ-في-الفم-او-الخدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0993أمرأة تسأل ما حكم تقبيل الوالد او الأخ في الفم أو الخدين؟.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1137,"question":"هل يجوز للمرأة أو القواعد من النساء أن يُصافحن الرجال؟","title":"هل يجوز للمرأة كبيرة السن مصافحة الرجال؟","answer":"الجواب:\nالمصافحة لا تجوز للنساء، يقول النبيُّ ﷺ: إني لا أُصافح النساء، ولم يُصافح لا عجوزًا ولا شابَّةً، وتقول عائشة رضي الله عنها: \"والله ما مسّت يدُ رسول الله يدَ امرأةٍ قط، ما كان يُبايعهن إلا بالكلام\" يعني: امرأة قط من غير محارم، وإلا كان يُباشر محارمه، كانت بنته فاطمة تُسلِّم عليه، وتأخذ بيده، وتُقبله عليه الصلاة والسلام، وهو كذلك يفعل، لكن ما كان يُصافح النساء الأجنبيات.\nفليس للمرأة أن تُصافح الرجل الأجنبي: لا أستاذ، ولا ابن عم، ولا جار، ولا أخو الزوج، ولا زوج الأخت، ولا غيرهم، ولكن كلام فقط، ولو بحائلٍ؛ لأن الحائل يجرّ إلى شيءٍ آخر، ولا أصل له، ولكن تُسلم بالكلام فقط: كيف حالك؟ كيف أولادك؟ السلام عليكم، وعليكم السلام، وما أشبه ذلك، أما أن تُصافحه فلا، حتى قال بعضُ أهل العلم: إن المصافحة شرٌّ من النظر.\n س: وهل تكشف وجهها العجوز؟\nالشيخ: أما العجوز فلا بأس أن تكشف وجهها إذا كانت لا تريد النكاح، وسترها أفضل، كما قال الله : وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا فَلَيْسَ عَلَيْهِنَّ جُنَاحٌ أَنْ يَضَعْنَ ثِيَابَهُنَّ غَيْرَ مُتَبَرِّجَاتٍ بِزِينَةٍ، ثم قال بعدها: وَأَنْ يَسْتَعْفِفْنَ خَيْرٌ لَهُنَّ [النور:60]، فإذا كانت عجوزًا لا تُشْتَهى ولا تبرج بالزينة فلا بأس أن تطرح الثوبَ عن وجهها، وتَسَتُّرها أفضل، تعفّفها أفضل؛ لأنَّ كل ساقطةٍ لها لاقطة، قد يشتهيها مَن لا تظن أنه يشتهيها، قد تقع الفتنة، فتَحَجُّبُها وتَسَتُّرها أفضل.","link":"https://binbaz.org.sa/fatwas/21195/هل-يجوز-للمراة-كبيرة-السن-مصافحة-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0991هل يجوز للمرأة الكبيرة بالسن مصافحة الرجال؟.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1153,"question":"هل الصَّرَع نوعٌ من الجن، أو أنَّ الصرع شيءٌ آخر وليس من تلبُّس الجن بالإنسان؟","title":"هل الصَّرَع نوع من مَسِّ الجن؟","answer":"الجواب:\nالصَّرَع أنواع: بعضه من الجن، وبعضه من غير الجن، بعضه قد يكون بسبب أمراضٍ في الرأس، وخللٍ في بعض العروق، فيُصرع، فإذا عُولج بالكيِّ استقام وطاب.\nقد كان عندنا حين ولايتي بالخرج إنسانٌ يُصرع، فإذا كُوي عرقٌ من رأسه سلم وعاش مدةً طويلةً، ثم يعود له المرضُ بانفتاق العرق هذا، فإذا كُوي عادت إليه الصحةُ، وكذلك قد يُصاب بأمراضٍ أخرى غير العرق، يحصل به تخديرٌ فيُصرع، وليس به جنٌّ.\nوقد يكون بسبب صرع الجنّ، قد يكون معه دخيل يصرعه، قد يقع هذا وهذا، فكلها تُعالج من طريق الأطباء، وتُعالج من طريق القُرَّاء إذا كان من صرع الجن.\nوهنا حبوبٌ الآن مُجرَّبة للصرع المعتاد هذا، تنفع بإذن الله، غير صرع الجن.","link":"https://binbaz.org.sa/fatwas/21210/هل-الصرع-نوع-من-مس-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1006هل الصرع نوع من مس الجن أو أن الصرع شيءٌ واحد؟ ابن باز.mp3","categories":["الطب والتداوي"]},{"id":1174,"question":"تقول المرأة: إذا سافرتُ إلى جدة في الطائرة خلال ساعة واحدة بدون محرم، فهل يجوز ذلك؟ علمًا بأننا سمعنا من أحد المشايخ يقول: لا يجوز للمرأة أن تُسافر في الطائرة بدون محرم إذا كان السفرُ يومًا وليلةً، فهل يجوز لها أن تسافر بالطائرة في ساعةٍ واحدةٍ أو ساعةٍ ونصف؟ مع العلم أنها تذهب إلى المطار مع محرم، وإذا نزلت من الطائرة يستقبلها محرم. أفتونا وجزاكم الله خيرًا.","title":"حكم السفر للمرأة بغير محرم","answer":"الجواب:\nيقول النبيُّ ﷺ: لا تُسافر امرأةٌ إلا مع ذي محرمٍ، والسفر كان أولًا على مطايا الإبل ونحوها: كالبغال والحمير، أما اليوم فالغالب أنه في الطائرات والسيارات، فلا يجوز السفر من هنا إلى جدة أو غيرها بدون محرمٍ، هذا يُسمَّى سفرًا، فلا يجوز السفر بغير محرمٍ ولو كان معها مَن يُوصلها إلى المطار، ومَن يتلقَّاها في المطار، ولو كان مثل ذلك لا يمنع من تحريم السفر.\nالمقصود أنَّ السفر ممنوعٌ إلا بمحرمٍ، والخطر على النساء إذا ذهبن بغير محرمٍ خطرٌ كبيرٌ، والذي يتلقَّاها في المطار قد لا يتلقَّاها، قد يكون معها مواعيد في الطائرة مع بعض الناس.\nفالمقصود أنَّ هذا خطرٌ، فلا يجوز السفر بغير محرمٍ، لا في الطائرة، ولا في الباخرة، ولا في السفينة، ولا في السيارة، بل يجب أن يكون معها محرمٌ، وإلا لا تُسافر.\nنسأل الله للجميع الهداية، والتَّساهل بهذا يُفضي إلى شرٍّ كبيرٍ، التساهل بهذا يُفضي إلى مصائب عظيمة مع النساء، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/21230/حكم-السفر-للمراة-بغير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1165حكم السفر للمرأة بغير محرم؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1211,"question":"ما حكم رفع اليدين للدعاء بعد الفريضة؟","title":"ما حكم رفع اليدين للدعاء بعد الفريضة؟","answer":"الجواب:\nليس له أصل، بدعة رفع اليدين، ما كان النبي يرفع يديه بعد الفريضة، كان يذكر الله ويُهلل ولا يرفع يديه، لا بعد الظهر، ولا بعد العصر، ولا بعد المغرب، ولا بعد العشاء، ولا بعد الفجر، ولا في خطبة الجمعة، ولا في خطبة العيد، لا يرفع يديه؛ لأن النبي ما فعله ﷺ.\nلكن إذا استسقى في الجمعة وفي العيد يرفع يديه، إذا استغاث، يعني: يرفع يديه كما فعل النبيُّ ﷺ، وكذلك في بقية الأوقات يرفع يديه، رفع اليدين من أسباب الإجابة، إذا دعا ورفع يديه من أسباب الإجابة في النافلة، أو وهو جالسٌ مع الناس رفع يديه ودعا لا بأس، من أسباب الإجابة، يقول النبيُّ ﷺ: إنَّ ربَّكم حيي ستيرٌ، يستحي من عبده إذا رفع يديه أن يردَّهما صفرًا.\nفرفع اليدين من أسباب الإجابة، لكن إذا كان في حالٍ ما رفع فيها النبيُّ ﷺ لا ترفع؛ لأن فعله ﷺ سُنة، وتركه سُنة، فلا ترفع إذا كان ما رفع النبيُّ ﷺ، مثل: بعد الفريضة لا ترفع، أو بين السَّجدتين لا ترفع، أو في آخر الصلاة قبل السلام لا ترفع، النبي ما رفع ﷺ، ولا في خطبة الجمعة لا ترفع، ولا في العيد لا ترفع، إلا في الاستسقاء، في الاستسقاء في الجمعة أو في العيد يرفع يديه ويدعو.","link":"https://binbaz.org.sa/fatwas/21258/ما-حكم-رفع-اليدين-للدعاء-بعد-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1136ما حكم رفع اليدين في الدعاء بعد الفريضة؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1217,"question":"إنني أشكو من ظلم بعض مَن درّسني حتى الآن، وكلما ذكرتُه دعوتُ عليه صباحًا ومساءً، فما الحكم في ذلك جزاك الله عنا خير الجزاء؟","title":"ما حكم دعاء المظلوم على من ظلمه؟","answer":"الجواب:\nإذا كان قد تعمَّد ظلمك فلا شكَّ أنه جديرٌ بأن يُدْعَى عليه، لكن ترك الدعاء أفضل، إذا لم تدع عليه يكون أفضل وأشدّ في إثمه إذا كان ظلمك؛ علَّمك ما حرَّم الله عامدًا يَعْلم، أو منعك حقَّك في التعليم، لم يُعلّمك وهو قادرٌ، أو ما هو بتعليم أستاذٍ، أو علَّمك خلاف الحقِّ عامدًا يُريد إغواءك وإضلالك.\nأما إذا غلطَ غلطًا؛ ما يجوز لك أن تدعو عليه، إذا غلط الإنسانُ، قد يجهل الأستاذُ، قد يغلط الأستاذُ. لكن إذا علمتَ أنه أرادك بالشر، وصرَّح لك بالشر، وأنه يُريد إضلالك، ويُريد إخراجك من النور إلى الظُّلمات –إيذاءك- إذا تعدَّى عليك؛ إن دعوتَ عليه فلا بأس، يقول الله جلَّ وعلا: لَا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَنْ ظُلِمَ [النساء:148]، لكن إن لم تدع عليه وقلتَ: حسبنا الله ونعم الوكيل، كان أفضل من الدعاء.","link":"https://binbaz.org.sa/fatwas/21273/ما-حكم-دعاء-المظلوم-على-من-ظلمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1121أني أشكو من ظلم كبير وكلما تذكرته دعوت عليه صباحاً ومساءاً فهل هذا جائز؟.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1220,"question":"كثيرًا ما يسأل الناسُ عن حكم حبوب منع الحمل، كما يسأل بعضُهم عن حكم وضع اللَّولب، وهو جهازٌ يُوضَع في الرحم لمنع الحمل؟","title":"ما حكم استخدام حبوب منع الحمل واللولب؟","answer":"الجواب:\nإذا دعت إليه الحاجةُ فلا بأس، إذا دعت الحاجةُ إلى الحبوب وقرر الأطباءُ أنَّ ما فيها مضرَّة للحاجة، مثل: امرأة مريضة، أو تحصل لها بالحمل أمراض، أو ما تلد إلا بمشقَّةٍ عظيمةٍ خطر عليها؛ فلا بأس إذا كانت الحبوبُ لا تضر، أو لأجل أنها ذات أطفالٍ صغار تخشى أن تحمل في السنة الأولى والثانية، فلا مانع أن تستعملها في السنة الأولى والثانية حتى تُربي أطفالها، للحاجة والمصلحة، واللولب كذلك إذا كان للمصلحة والحاجة؛ لأنَّ بعض النساء تضرُّهم الحبوب.","link":"https://binbaz.org.sa/fatwas/21276/ما-حكم-استخدام-حبوب-منع-الحمل-واللولب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1118ما حكم أستخدام حبوب منع الحمل واللولب؟ابن باز فتاوى.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1264,"question":"من المُتعارف عليه أنه يُدرس اليوم في كلية الطبّ مادة التَّشريح على جثث بعض الآدميين، فهل يجوز تشريح جثة المسلم للتَّعَلُّم؟","title":"هل يجوز تشريح جثة المسلم للتَّعَلُّم؟","answer":"الجواب:\nهذا صدر قرارٌ من المجلس -من مجلس هيئة كبار العلماء- بمنع ذلك، وأنه لا يجوز تشريح جثة المسلم للتَّعَلُّم، بل تُشترى جثثٌ مباحة غير معصومةٍ: من الهند، أو من غير الهند من بلاد الكفر، حتى يكون التعلم عليها؛ لأن الرسول ﷺ حرَّم الاستهانة بالمسلم، وجعله -حيًّا وميتًا- مُحترمًا، وقال: كسر عظم المَيِّت ككسره حيًّا.","link":"https://binbaz.org.sa/fatwas/21341/هل-يجوز-تشريح-جثة-المسلم-للتعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1084هل يجوز تشرح جثة المسلم للتعلم؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي"]},{"id":1267,"question":"هل أفتت هيئةُ كبار العلماء بعدم جواز التبرع بالأعضاء؟ وإذا كان الأمر كذلك فما الدليل؟","title":"ما حكم التبرع بالأعضاء؟","answer":"الجواب:\nهذا موضوعٌ فيه خلافٌ بين العلماء: منهم مَن أجازه، ومنهم مَن توقَّف فيه، التبرع بالأعضاء: كالكلية والقلب واليد أو الرجل أو غير ذلك، ولا أذكر أنه صدر فيه قرارٌ من الهيئة، توقفت فيه الهيئة -هيئة كبار العلماء- فيما أذكر، ولا أعلم الآن أنه صدر فيه قرار بالجواز.\nوأنا متوقِّفٌ في ذلك؛ لأني أرى أنَّ هذا يُخشى أن يكون من المُثْلَة، كونه يتبرع بكليته أو بقلبه إذا مات أو بيده أو برجله: أخشى أن يكون هذا من المثلة التي جاء الشرعُ بالنَّهي عنها.\nوبعض العلماء وإخواننا أفتى بذلك: عند الموت، إذا أوصى بذلك، أنه لا حرج في ذلك.\nوالمسألة محل نظرٍ، ومحل تأمُّلٍ، والأحوط عندي ألا يتبرع بشيءٍ، وألا يسمح لأحدٍ أن يُقَطِّعه بعد وفاته، وألا يُتعرض له.","link":"https://binbaz.org.sa/fatwas/21338/ما-حكم-التبرع-بالاعضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1081ما حكم التبرع بالأعضاء؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي"]},{"id":1269,"question":"نحن الأطباء ذهبنا إلى الخارج للدراسة والتَّخصص، ودائمًا تُواجهنا مشكلة عند الكشف على النساء هناك، وهو عدم وجود المُمرضة لتُساعدنا عند الفحص عليهنَّ، وذلك بحكم التقاليد في تلك البلاد، فما العمل؟ هل يجوز؟ وإذا لم يجز فما الكفَّارة بعد أن عدنا إلى بلادنا؟ أفيدونا جزاكم الله خيرًا لنُبْرِئ ذممنا في ذلك.","title":"ما حكم كشف الطبيب الرجل على النساء؟","answer":"الجواب:\nإذا دعت الضَّرورة للكشف على المرأة؛ جاز في البلاد الإسلامية وفي غيرها، لكن يكون مع الكاشف مُشاركٌ، حتى لا يخلو بها، معه ممرضة، أو طبيبة، أو طبيب إذا كان ما تيسر نساء، لا يخلو بها؛ لأنَّ الرسول حرَّم الخلوة بالمرأة، والشيطان حاضرٌ حريصٌ، فيُعالج وينظر، ولكن بوجود مُشاركٍ، بوجود مَن يحضره، حتى لا تحمله النفسُ الأمَّارة بالسوء والشيطان على ما لا يحلّ له: من قبلةٍ، أو جماعٍ، أو غير ذلك، وإذا دعت الضَّرورة فلا بأس بهذا، لكن يكون معه غيرُه.\nأما إذا ما دعت الضَّرورة، فالمرأة لها طبيبة، والرجل له طبيب، النساء للنساء، والرجال للرجال، لكن إذا وقعت واقعةٌ احتاجت المرأةُ إلى طبيبٍ لعدم وجود مُتخصصة جاز، أو احتاج الرجلُ إلى طبيبةٍ لعدم وجود مُتخصص والطبيبة عندها تخصص؛ جاز عند الضَّرورة، لكن من دون خلوةٍ، لا بدّ من وجود عدم الخلوة مثل: وجود ممرض أو وجود ممرضة مع الرجل، أو ممرض عند الضَّرورة، حسب... إن كانت امرأة: وجود امرأة، وإن كان رجلًا، ما تيسرت المرأة فيكون رجل، يكون حاضرًا، حتى لا تكون خلوةً، حسب الطاقة والإمكان، المقصود: لا يخلو بها.","link":"https://binbaz.org.sa/fatwas/21336/ما-حكم-كشف-الطبيب-الرجل-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1079ما حكم كشف الطبيب الرجل للمرأة؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي"]},{"id":1271,"question":"تمرّ بالأطباء بعض الحالات: فعندما يُولد طفلٌ مثلًا قبل موعده -في الشهر السادس من الحمل- ونظرًا لأنه تحدث مضاعفات كثيرة طبيًّا إن كان الطفلُ عاش، وذلك بعد قدرة الله  ثم بالجهاز التنفسي، لذا فإنَّ هناك قانونًا طبيًّا يقول: إن كان وزن الطفل أقلَّ من سبعمئة وخمسين جرامًا فلا يعمل له الجهاز التنفسي الذي يكون بفضل الله مُساعدًا للطفل على الحياة، بالرغم من المُضاعفات المُتوقع حدوثها، فهل يجوز ترك الطفل بدون مُساعدات إضافية تُكلِّف المريض والطبيب الكثير من الجهد والوقت والمال -إذا لزم الأمرُ إلى المال- مع الاحتمال الكبير على عدم استمرار الطفل في الحياة، بل أن يكون مُعاقًا فيما بعد، أم يركب عليه هذا الجهاز مع ما يحصل له بعد ذلك؟","title":"ما حكم العلاج الطبي مع توقع ضعف أثره؟","answer":"الجواب:\nالقاعدة عند أهل العلم: أن العلاج ليس بواجبٍ، مُستحبّ، علاج المرضى مُستحبّ وليس بواجبٍ، كونه يُعالج بجراحةٍ أو بعمليةٍ أو بحبوبٍ أو بحميةٍ، كلها مُستحبّة، ما هي بواجبة، لو أبى العلاج لا حرج عليه.\nفإذا رأى الأطباء أنَّ من المصلحة أن يُعالج هذا الطفل فعلوا، وإن رأوا أنَّ من المصلحة عدم العلاج تركوا، ولا حرج في ذلك، الحكم يدور على المصلحة الغالبة، إن غلب على الظن أن العلاج ينفع فلا بأس، وإن غلب على الظنِّ أنه لا ينفع فلا بأس بتركه؛ لأنه ضياع، وعدم فائدةٍ، وإضاعة للأموال، وإضاعة للأوقات.","link":"https://binbaz.org.sa/fatwas/21334/ما-حكم-العلاج-الطبي-مع-توقع-ضعف-اثره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1077ما حكم علاج المرضى؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي"]},{"id":1274,"question":"عندما يكون الطبيبُ في مكان عمله الذي يستوجب منه علاج المسلم وغير المسلم: كالنَّصارى أو غيرهم، مثلًا في حالة الحرب، مع الخوف من هذا النَّصراني الذي قد يحصل فيما بعد، فما موقف الطبيب المُعالج أمام الله تعالى في ذلك، وفي علاج هذا الذي يبغضه اللهُ ورسولُه، ويبغض اللهَ ورسولَه؟","title":"ما واجب الطبيب تجاه المريض غير المسلم؟","answer":"الجواب:\nالواجب على الطبيب أداء الأمانة، يُعالجه كما يُعالج غيره؛ لأنَّ هذا صار في محلِّ الأمان، ومحل الاستئمان ما هو محل الحرب، إذا كان تبعنا أو دخل عندنا بالأمان: موظف، وطبيب، أو مع المجاهدين الآن، مع الميليشيات التي تُحارب الآن، لو جرى عليه شيءٌ لا بد أن تُعالجه كما تُعالج المريض المسلم، اتَّقِ الله في أداء الأمانة.  وكونه يبغضه الله: هذا إلى الله سبحانه، لكن أنت الآن دخل عندك بالأمان فلا بد أن تُعالجه، إن كان مؤتمنًا، أو مُعاهدًا، أو جاء في رسالةٍ، لو دخل بالأمان برسالةٍ، أو جاء طبيب، أو لأسبابٍ أخرى، ثم أصابه مرضٌ فعالجه بالأمانة، ولا تضرّه بشيءٍ.\nس: ألا ترون أنَّ في مثل هذه الحالة مجالًا للدعوة الإسلامية واستجلابًا للناس؟\nالشيخ: زيادة الدعوة، الدعوة طيبة، كونه يدعوه إلى الله، ويُرغِّبه في الإسلام؛ هذا طيبٌ، مع العلاج، لكن فقط لا يخون الأمانة، لا يُعالجه بشيءٍ يضرُّه، بل يجب أن ينصح له، وهذا من الدعوة إلى الإسلام، كونه ينصح له هذا من الدعوة إلى الإسلام، يستشعر النَّصراني أو غيرُه أنَّ الإسلام ينصح ويُؤدي الواجب لمن اؤتُمن عليه، أو صار في أمانته، أو في عهده، أو في ذمته.","link":"https://binbaz.org.sa/fatwas/21331/ما-واجب-الطبيب-تجاه-المريض-غير-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1074ما هو واجب الطبيب المسلم تجاه المريض الغير مسلم؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي","الدعوة والدعاة"]},{"id":1276,"question":"إنَّ تشخيص بعض الحالات المرضية للجنين يتم للمرأة الحامل، وذلك في الأشهر: أربعة وخمسة وستة، وهذه الأمراض غالبًا ما تكون ذات تأثيرٍ على المريض: من تخلُّفٍ عقلي، أو من تخلُّف جسماني، فهل من الجائز أن يعمل إسقاط للجنين في هذه الأشهر، مع مُراعاة تلك العواقب التي قد يعيش فيها الطفل من التَّخلُّف أو من المرض المُستديم في المجتمع؟ أفيدونا جزاكم الله خيرًا؛ لأنَّ هذه الحالة تُحيّر الأطباء.","title":"حكم إسقاط الجنين بسبب تشوه أو تخلف عقلي","answer":"الجواب:\nهذا الموضوع درسه مجلس هيئة كبار العلماء، وقرروا فيه قرارًا نُعطي المدير نسخةً منه إن شاء الله، وملخصه أنه: إن كان الضَّررُ على الطفل فهذا لا يجوز إسقاطه إذا تخلَّق أو نُفخت فيه الروح، أما إن كان الضَّررُ عليها هي، عليها خطرٌ هي نفسها -المرأة- لو تُرك فعليها خطرٌ منه، والخطر يعني الموت، فهذا يسقط ولو كان في السادس أو السابع أو الثامن، إذا كان الخطرُ عليها، إن كان بقي هلكت هي، هذا يُسقط.\nأما إذا كان لا، ما عليها خطر، فلا يُسقط؛ لأنه نوع قتلٍ، فيُترك حتى تلد، وإذا ولدت الأمر إلى الله: إن كان سليمًا فالحمد لله، وإن كان مُشوَّهًا فإنا لله وإنا إليه راجعون، ولا يجوز قتله، أما إذا كان قبل الأربعة أشهر فهذا إن كان فيه ضررٌ عليها -ضررٌ بيِّنٌ- جاز إسقاطه، وإن كان ما له ضررٌ بيِّنٌ؛ تُرك.","link":"https://binbaz.org.sa/fatwas/21329/حكم-اسقاط-الجنين-بسبب-تشوه-او-تخلف-عقلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1072هل يجوز أسقاط الجنين إذا تبين أنه سيسبب له تشوه أو تخلف عقلي؟ ابن باز.mp3","categories":["الطب والتداوي"]},{"id":1286,"question":"إذا بذل الطبيبُ أقصى ما لديه من جهدٍ ولم يُهمل في علاج المريض، ولكنه لم يُوفَّق، أي أخطأ في تشخيص المرض من غير قصدٍ، مع بذل الوسع في ذلك، فهل يُحاسَب الطبيبُ على الخطأ بدون قصدٍ مع ثبات بذل الوُسْع؟","title":"حكم خطأ الطبيب مع الخبرة وبذل الوُسْع","answer":"الجواب:\nهذا فيه تفصيلٌ: إذا كان طبيبًا حاذقًا قد اعتنى بهذا المرض، وهو من أهله، من العلاج، قد حذق فيه، وتعلم فيه، ويُعدّ من أهل العلاج، فلا شيء عليه إذا أخطأ، مثل: العالم إذا أخطأ، له أجران إن أصاب، وله أجرٌ إن أخطأ، أجر الاجتهاد.\nأما إذا كان لا، ما عنده فيه الحذق الكامل، ولكن تهجم عليه من غير عنايةٍ؛ فهو ضامن وآثمٌ. أما إذا كان لا، هو من أهل العلاج لهذا المرض، ولكن قُدر أنه أخطأ في علاجه، مع الاجتهاد والتَّحري، وكونه من أهل العلاج، ومن أهل هذا المرض، فلا حرج عليه إن شاء الله؛ لأنَّ الرسول قال: مَن تَطَبَّب ولم يكن بالطبِّ معروفًا...، أما إذا كان معروفًا به ومن أهله فلا شيء عليه بعد بذل الوسع، مثل: العالم الذي بذل وسعه في الإفتاء ولكنه أخطأ.","link":"https://binbaz.org.sa/fatwas/21349/حكم-خطا-الطبيب-مع-الخبرة-وبذل-الوسع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1092أذا بذل الطبيب أقصى ما لديه من جهد ولم يهمل في علاج المريض لكنه لم يوفق فماذا عليه؟.mp3","categories":["الطب والتداوي"]},{"id":1295,"question":"بحكم عملنا كأطباء نضطر أحيانًا للكشف على بعض النساء، وتخطر على قلوبنا بعضُ الخواطر، ولكننا نُجاهدها، فهل علينا إثمٌ في ذلك؟","title":"حكم ما يطرأ للطبيب نحو النساء مع المجاهدة","answer":"الجواب:\nمع المجاهدة لا، يُجاهد ويَحْذر، يقول النبيُّ ﷺ: إنَّ العبد إذا همَّ بالسيئة فلم يعملها لم يُكتب عليه شيءٌ، فإن همَّ بها وتركها من أجل الله كتبها الله له حسنةً، فلا يُؤخذ بها إلا إذا عملها، والرسول يقول عليه الصلاة والسلام: إنَّ الله تجاوز عن أمتي ما حدثتْ به أنفسها، ما لم تعمل، أو تكلم، وإذا خاف من نفسه وشيطانه فلا يُعالج المرأة، يعتذر ويُحيلها إلى غيره، فإنَّ دينه عليه ألزم.","link":"https://binbaz.org.sa/fatwas/21342/حكم-ما-يطرا-للطبيب-نحو-النساء-مع-المجاهدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1085نضطر للكشف على بعض النساء وتخطر على قلوبنا بعض الخواطر فهل علينا أثم؟.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1315,"question":"آخر ساعةٍ من عصر الجمعة هل هي ساعة الإجابة؟ وهل يلزم الرجل أن يكون في المسجد في هذه الساعة، وكذلك النساء في المنازل؟","title":"متى ساعة الإجابة يوم الجمعة وكيفية الدعاء؟","answer":"الجواب:\nأرجح الأقوال أن ساعة الإجابة بعد العصر، إذا جلس ينتظر المغرب، سواء في المسجد، أو في بيته كالمريض أو المرأة، إذا جلس ينتظر المغرب ويدعو ربَّه آخر ساعة من يوم الجمعة فهو حريٌّ بالإجابة، والأحاديث في هذا كثيرةٌ عن النبي ﷺ.\nوهناك وقتٌ آخر أيضًا حريٌّ بالإجابة، وهو ما إذا جلس الإمامُ على المنبر يوم الجمعة في الخطبة، والدعاء بعد جلوسه على المنبر إلى أن تُقضى الصلاة من أسباب الإجابة، في الصلاة، في السجود، بين الخطبتين، قبل أن يشرع في الخطبة، هذه من أسباب الإجابة.  وبقية ساعات الجمعة كلها من أسباب الإجابة، بقية ساعات الجمعة كلها يُرجى فيها الإجابة، لكن هذان الوقتان أرجاهما: حين يجلس الإمام على المنبر إلى أن تُقضى الصلاة، وبعد العصر إلى غروب الشمس لمن جلس ينتظر الصلاة؛ لأنه في صلاةٍ، مَن جلس ينتظرها فهو في صلاةٍ ما دام ينتظر الصَّلاة.","link":"https://binbaz.org.sa/fatwas/21354/متى-ساعة-الاجابة-يوم-الجمعة-وكيفية-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1097آخر ساعة من عصر الجمعة هل هي ساعة أجابة؟ ابن باز فتاوى.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1349,"question":"بالنسبة للأمراض البدنية هل الأولى الصبر أم المبادرة إلى الدواء؟","title":"هل الأفضل للمريض التداوي أم الصبر؟","answer":"الجواب:\nلا، العلاج هو الأفضل كما عالج الصحابة وعالج النبي ﷺ فالعلاج أوْلى؛ لأن العلاج يعين على طاعة الله وعلى كشف البلاء، فالعلاج مستحب ومن الأمور الجائزة ومن الأمور المستحبة، ومن ذلك الرقية، النبي ﷺ رَقَى ورُقِي عليه.\nس: أحسن الله إليك بالنسبة لتكرار العلاج على نفس المريض من شخص إلى شخص من القُرّاء هل ينبغي ذلك؟\nج: لا مانع، والحمد لله عباد الله تَدَاوَوْا ولا تداووا بحرام، ما أنزل الله داء إلا أنزل له شفاء، عَلِمه من علمه وجَهِلَه مَن جهله.\nس: يعني مثلاً، أحسن الله عملك، هل يُكَرِّر على شخص واحد أو يكرر على عدة أشخاص؟\nج: يعمل ما يراه نافعًا، ويجتهد؛ لعل الله ينفع بالأسباب، من طبيب إلى طبيب، حسب التيسير.","link":"https://binbaz.org.sa/fatwas/21441/هل-الافضل-للمريض-التداوي-ام-الصبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في التداوي.mp3","categories":["الطب والتداوي"]},{"id":1356,"question":"إذا أصيب إنسان بعين ولا يعرف مَن أصابه كيف العلاج؟","title":"ماذا يفعل مَنْ ظن إصابته بعين ونحوها؟","answer":"الجواب:\nويش يدريه أنه أُصيب بالعين؟\nس: مثلاً أحيانًا يكون فيه ضيق الصدر؟\nج: ما هو كلها على أنها عين، قد تكون أمراضًا داخلية غير العين، لكن إذا ظن بإنسان يطلب منه أن يغسل له وجهه ويديه أو يتوضأ له وجهه وكفيه وأطراف قدميه، كما جاء في الحديث، ثم يتروَّش بذلك، إذا تيسر له ذلك.\nس: بعض الناس مثلاً يقول: هذا نَفس فيه يعني أصابته نفس؟\nج: عند الناس الظنون كثيرة اللي ما عليها سلطان، هذا يظن \"نفس\"، وهذا يظن \"سحر\"، وهذا يظن \"جن\"، الناس يتخبطون في المسائل هذه.\nس: يعني يكتفي بالرقية؟\nج: الرقية كافية لكل شيء، إلا مِن عَيْن أو حمَّة.","link":"https://binbaz.org.sa/fatwas/21449/ماذا-يفعل-من-ظن-اصابته-بعين-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الإصابة بالعين والرقية منها.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":1360,"question":"بعض أهل العلم كره مقالة: يا فلان لا تَنْسَنا من الدعاء؟","title":"حكم قول: \"يا فلان لا تنسنا من الدعاء\"","answer":"الجواب:\nما فيها شيء إن شاء الله، لا حرج إن شاء الله؛ لأن الرسول ﷺ قال: يقدم عليكم أُويس وكان بارًّا بأمه وأنه كذا وكذا فمَن لَقِيَه فليطلب منه الاستغفار له رواه مسلم في الصحيح، وجاء في حديث عمر لما أراد العمرة، قال له النبي ﷺ: لا تنسنا يا أخي من دعائك، وإن كان في سنده بعض اللين ولكن يشهد له حديث أُويس.","link":"https://binbaz.org.sa/fatwas/21453/حكم-قول-يا-فلان-لا-تنسنا-من-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مقالة يا فلان لا تنسنا من الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1361,"question":"بعض البلدان الإسلامية هناك بعض الدول يعتبرون نفسهم يُحَكِّمون شرع الله ثم يتخذون بعض الثغرات، يقولون في عهد النبي ﷺ كانت (المرأة) تجاهد مع الرجال، ومن هذا الباب يُجَنِّدون الطالبات الجامعيات والثانويات ويخرجونهن مع الرجال إلى أماكن سفر بعيدة ويُجَنِّدونهن يحاربن مع الرجال؟","title":"حكم تسويغ خروج المرأة وجهادها مع الرجال","answer":"الجواب:\nما هم يجاهدون، كانوا يداوون الجرحى ويسقون المرضى قبل الحجاب، ثم لما نزل الحجاب مُنِعن، كانوا قبل الحجاب المرأة أولاً تمشي مع الرجل وتكشف وجهها وتكشف يديها وتكلمه، ثم أنزل الله الحجاب ومنعهن من ذلك، وما كانوا يجاهدون، المرأة ما عليها قتال، ما تجاهد، كانوا معهم إذا جاء جرحى أو مرضى يساعدن في سقي المرضى ومداواة الجرحى، بعض الناس المختصات يعني، ثم نُسخ هذا ومُنع الرجال من النساء وحُجب النساء عن الرجال.\nس: يدعون إليها باسم الشريعة وباسم الإسلام بهذه الحجة؟\nج: جَهْل.","link":"https://binbaz.org.sa/fatwas/21454/حكم-تسويغ-خروج-المراة-وجهادها-مع-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من ينزل النصوص في غير مكانها ليستدل على خروج المرأة.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1363,"question":"عندما يُذكر الرسول ﷺ في حِلَق العلم يكون ذكره عليه الصلاة والسلام بكثرة، هل يلزم أنه كلما ذُكر يُصلى ويُسَلَّم عليه؟","title":"حكم الصلاة على النبي ﷺ في حِلَق العلم","answer":"الجواب:\nالسُّنَّة الصلاة عليه رغم أنف امرئ ذكرت عنده فلم يصل عليّ كلما مر ذكره يصلي عليه، اللهم صَلِّ عليه.","link":"https://binbaz.org.sa/fatwas/21456/حكم-الصلاة-على-النبي-ﷺ-في-حلق-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الصلاة والسلام على النبي صلى الله عليه وسلم.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1428,"question":"سائل: ما رأي سماحتكم في استقدام خادمة مسلمة من بلد الإسلام بدون محرمٍ لحاجةٍ ضروريةٍ؟","title":"حكم استقدام خادمة مسلمة بدون محرمٍ لحاجة","answer":"الجواب:\nالواجب على جميع النساء ألا يُسافرن إلا بمحرمٍ، سواء خادمة وإلا...،  لكل امرأةٍ لا بد من محرمٍ لها، النبي ﷺ يقول: لا تُسافر المرأةُ إلا مع ذي محرم، هذا هو الواجب على الجميع، وعلى أهلها أن يجعلوا معها محرمًا.","link":"https://binbaz.org.sa/fatwas/21523/حكم-استقدام-خادمة-مسلمة-بدون-محرم-لحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استقدام خادمة مسلمة بدون محرمٍ لحاجة.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1477,"question":"هل يجوز الدعاء لمَن قدم من المدينة بقول: زيارة مقبولة، أو: تقبَّل الله؟","title":"حكم قول \"زيارة مقبولة\" لزائر المدينة","answer":"الجواب:\nما في مانع، لو قلت له: زيارة مقبولة، تقبَّل الله صلاتك، وتقبَّل الله صيامك، ما في شيء، جزاك الله خيرًا.","link":"https://binbaz.org.sa/fatwas/21575/حكم-قول-زيارة-مقبولة-لزاىر-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء لمن قدم من الدينة بقول زيارة مقبولة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1485,"question":"حديث لما جاء الأعرابُ قال الرسولُ ﷺ: اذهبوا واشربوا من أبوالها وألبانها؟","title":"ما حكم التداوي بأبوال الإبل وألبانها؟","answer":"الجواب:\nهؤلاء ناسٌ عُرَنِيون أصابهم مرضٌ فأرسلهم النبيُّ للتداوي بأبوال الإبل وألبانها.\nس: يشربون البول؟\nج: لا بأس، فهو طاهر للتداوي به، كل مأكول اللحم بوله طاهر، بول الإبل، أو البقر، أو الغنم.\nس: ما يُغسل؟\nج: للنَّظافة، من باب النظافة.","link":"https://binbaz.org.sa/fatwas/21583/ما-حكم-التداوي-بابوال-الابل-والبانها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التداوي بأبوال الإبل وألبانها.mp3","categories":["الطب والتداوي"]},{"id":1515,"question":"يقول السائل: فضيلة الشيخ، يقول النبي ﷺ: وإذا استُغْسِلْتُم فاغسلوا رواه مسلم، فمتى يُشرع طلب الاستغسال؟ هل يكفي الشك أم لا بد من غلبة ظن؟","title":"متى يُشرع طلب الاستغسال من العَيْن؟","answer":"الجواب:\nإذا ظنَّ أنه العائن يقول له: جزاك الله خيرًا اغسل لي، فإذا غسل وجهه ويديه كفى، وإن توضأ وغسل وجهه ويديه وداخلة إزاره وركبتيه وأطراف قدميه كان أكمل، ثم يرشه المعينُ على نفسه -الذي ظن أنه عائنه- ويبرأ بإذن الله، إذا كانت العين موجودةً، ولا بأس. والذي يُقال له لا ينبغي له أن يتكبَّر، بل يغسل لهم، فالرسول ﷺ قال: وإذا استُغْسِلْتُم فاغسلوا، فإذا اتَّهموه بالعين يغسل وجهه ويديه ويتمضمض لهم، وينفع بإذن الله.","link":"https://binbaz.org.sa/fatwas/21614/متى-يشرع-طلب-الاستغسال-من-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يشرع طلب الاستغسال.mp3","categories":["الطب والتداوي"]},{"id":1537,"question":"شخص كان مريضًا بمرضٍ لفترةٍ طويلةٍ ثم مات فقالوا: أحسن له أنه مات، هل في هذا شيء؟","title":"حكم استحسان الموت لمن طال مرضه","answer":"الجواب:\nما ينبغي أن يُقال هذا، الله أعلم بالحقيقة، قد يكون أحسن له لو عاش، فالمريض كلما تقدّم به المرض زاد أجره وتكفير السيئات، فكلما زادت أيام المرض يكفر الله بها السيئات: ما أصاب العبد من همٍّ ولا غمٍّ ولا نصبٍ ولا وصبٍ ولا أذًى إلا كفَّر الله به من خطاياه، أشد الناس بلاءً الأنبياء، ثم الصالحون، ثم الأمثل فالأمثل.\nس: شخصٌ أُصيب بمرضٍ لفترةٍ طويلةٍ وبعضهم يتمنى له الموت، يقولون: لو يموت يكون أحسن له؟\nج: كل هذا غلط، ما ينبغي هذا؛ لأن المرض الذي يُصيبه يُكفِّر الله به الخطايا، وربك أحكم وأعلم .","link":"https://binbaz.org.sa/fatwas/21637/حكم-استحسان-الموت-لمن-طال-مرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة فيمن ابتلي بمرض.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1541,"question":"سألتكم عن حكم التَّبرع بالكُلَى بحضور الشيخ عبدالعزيز القاسم، وكان جوابكم أنكم متوقفون، وفي إحدى المرات قلتم حفظكم الله: أنكم متوقفون، والمنع أقرب، ثم نقلت هذه الفتوى إلى المدرسة، فأحضر أحد المدرسين ورقةً مصورةً من \"المجلة العربية\" أحضرها أحدُ الطلاب، فيها فتوى لكم بجواز التبرع بالكلى، هل تأذنون حفظكم الله بقراءتها عليكم؟","title":"حكم التبرع بالكُلَى وأعضاء الإنسان","answer":"الجواب:\nهذا رأي بعض أعضاء المجلس.\nس: ذكر أنَّها لكم أحسن الله إليكم.\nج: ولو، فأنا راجعٌ عنها إن صحَّتْ عني.\nس: أقرؤها عليكم؟\nج: الصحف تنشر ما هَبَّ ودَبَّ.\nس: إذن ما الذي استقررتم عليه حفظكم الله؟\nج: أنا أرى عدم التبرع، المسلم محترم حيًّا وميتًا، لا يُقطع منه شيء.","link":"https://binbaz.org.sa/fatwas/21641/حكم-التبرع-بالكلى-واعضاء-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رأي الشيخ بن باز في حكم التبرع بالكلى.mp3","categories":["الطب والتداوي"]},{"id":1570,"question":"دعاء الملائكة لمَن أمسك شيئًا واجبًا أو المُتطوع؟","title":"ما معنى دعاء الملائكة على مَن يُمْسِك النفقة؟","answer":"الجواب:\nالظاهر: الذي يُمسك مع قدرته على الإنفاق في وجوه الخير، وأعظم ذلك الزكاة.\nس: هل يُستجاب دعاؤه؟\nج: يُخاف عليه.\nس: قد يُستجاب وقد لا يُستجاب؟\nج: الله أعلم.","link":"https://binbaz.org.sa/fatwas/21673/ما-معنى-دعاء-الملاىكة-على-من-يمسك-النفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء الملائكة لمَن أمسك شيئًا واجبًا أو المُتطوع.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1583,"question":"متى تكون التسميةُ واجبةً؟","title":"ما المواضع التي تجب فيها التسميةُ؟","answer":"الجواب:\nج: عند بدء الأكل.\nس: فقط في هذا الموضع؟\nج: عند أول الأكل، وعند الوضوء كذلك، وعند دخول المنزل، كلها مشروعة، وعند الاضطجاع للنوم: باسمك ربي وضعتُ جنبي وبك أرفعه.","link":"https://binbaz.org.sa/fatwas/21686/ما-المواضع-التي-تجب-فيها-التسمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وقت وجوب التسمية.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1661,"question":"طلب الدعاء من الرجل الصالح هل يكون فيه إحراج؟","title":"حكم طلب الدعاء من الرجل الصالح","answer":"الجواب:\nلا بأس أن يسأل أخاه الطيب أن يدعو له، فالنبيُّ ﷺ قال: يقدُم عليكم أُويس القرني، كان بارًّا بأمه، فمَن لقيه منكم فليطلب منه الدعاء، ويُروى عن النبيِّ ﷺ أنه قال لعمر لما أراد العمرة: لا تنسنا يا أخي من دعائك، لكن لا يلحّ، ولا يكون مِلْحَاحًا، يكون الدعاء خفيفًا من دون إلحاحٍ ولا مشقَّةٍ.","link":"https://binbaz.org.sa/fatwas/21766/حكم-طلب-الدعاء-من-الرجل-الصالح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم طلب الدعاء من الرجل الصالح.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1682,"question":"حديث عائشة عن الرسول ﷺ: كان إذا أوى إلى فراشه جمع كفيه فنفث فيهما، فقرأ فيهما: قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص] والمعوذتين، هل هذا يكفي؟ يعني: مَن يُداوم على هذا يكون له حِرْزًا؟","title":"استحباب التَّعَوُّذ كل ليلة بالمعوذات قبل النوم","answer":"الجواب:\nهذا من الحروز الشرعية، وكان النبيُّ يستعمله دائمًا كل ليلةٍ، ولا سيَّما إذا أصابه شيءٌعليه الصلاة والسلام، فهذا من العلاج.\nس: مع الأذكار؟\nج: مع الأذكار الأخرى.","link":"https://binbaz.org.sa/fatwas/21788/استحباب-التعوذ-كل-ليلة-بالمعوذات-قبل-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استحباب استعمال الحروز الشرعية.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1742,"question":"مصافحة الشاب للمرأة العجوز الكبيرة في السن؟","title":"حكم مصافحة الشاب للمرأة العجوز","answer":"الجواب:\nلا، إذا لم تكن مَحْرَمًا له فلا.\nس: إذا كانت عادتهم؟\nج: ولو، ولو، ما ينبغي.","link":"https://binbaz.org.sa/fatwas/21849/حكم-مصافحة-الشاب-للمراة-العجوز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم مصافحة الشاب للمرأة العجوز الكبيرة.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1751,"question":"مَن دعا للمريض عن طريق الهاتف ولم يتيسَّر له الذّهاب هل يُجزئ؟","title":"حكم الدعاء للمريض عن طريق الهاتف","answer":"الجواب:\nمن طريق الهاتف أو غير الهاتف، يدعو لأخيه ولو بظهر الغيب، فإذا دعا المؤمنُ لأخيه بظهر الغيب قال الملك المُوَكَّل: آمين ولك بمثله.","link":"https://binbaz.org.sa/fatwas/21858/حكم-الدعاء-للمريض-عن-طريق-الهاتف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء للمريض عن طريق الهاتف.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1752,"question":"ما رواه البخاري عن كفار قريش لما وضعوا سَلَى النَّاقة على رسول الله ﷺ وهو ساجدٌ، فلما سلَّم رسولُ الله ﷺ رفع يديه يدعو عليهم، هل يُؤخَذ من ذلك استحباب الدعاء بعد الصلاة؟","title":"ما حكم الدعاء مع رفع اليدين بعد النافلة؟","answer":"الجواب:\nهذا مما ورد في رفع اليدين، لا أحفظ أنه ورد بعد النافلة رفعٌ إلا هذا، دعا عليهم ﷺ لما وضعوا عليه السَّلى، دعا عليهم دعاءً عظيمًا، فلا بأس، لكن في بعض الأحيان، وليس دائمًا.","link":"https://binbaz.org.sa/fatwas/21859/ما-حكم-الدعاء-مع-رفع-اليدين-بعد-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء بعد الصلاة النافلة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1760,"question":"(دعاء الركوب) لو كان مجموعة في سيارةٍ واحدةٍ وقاله واحدٌ منهم هل يكفي أم السُّنة أن يقوله كلُّ واحدٍ؟","title":"متى يُقال دعاء السفر؟ وهل يجوز جماعيًّا؟","answer":"الجواب:\nلا، كل واحدٍ يقوله لنفسه من غير تشويشٍ على الآخر.\nس: هل دعاء الركوب خاصّ بالسفر؟\nج: نعم، المعروف في الأحاديث أنه في السفر.","link":"https://binbaz.org.sa/fatwas/21867/متى-يقال-دعاء-السفر-وهل-يجوز-جماعيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في دعاء السفر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1762,"question":"التَّسبيح عند النزول، والتَّكبير عند الصعود، هل يكون في الحضر أم أنه خاصٌّ بالسفر؟","title":"هل يُسبّح للنزول ويُكبّر للصعود بالسفر فقط؟","answer":"الجواب:\nالمعروف في السفر، أما في الحضر فإنَّه يُسبّح ويُكبّر في الصعود والنزول، يُكثر من الذكر، سواء في الحوش، أو في السطح، أو غير ذلك.\nس: هل يُكبَّرجماعيًّا؟\nج: لا، كلٌّ يُكبِّر لنفسه، ما يُراعي صوتَ غيره، الجماعي ما له أصلٌ، فهو بدعة، فكلٌّ يُكبِّر ويذكر الله على حسب حاله، ما يُراعي صوتَ غيره.\nس: مَن صعِد درجًا فكبَّر؟\nج: يُكبِّر صاعدًا أو نازلًا، كله واحد.\nس: وإذا نزل من درجٍ سبَّح؟\nج: كله طيب، أو يذكر الله وهو نازل: يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ [آل عمران:191]، لكن هذا الذي فيه مراعاة الأودية يكون في الأسفار.","link":"https://binbaz.org.sa/fatwas/21869/هل-يسبح-للنزول-ويكبر-للصعود-بالسفر-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التَّسبيح عند النزول، والتَّكبير عند الصعود في السفر أم في الحضر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1763,"question":"بعض الناس إذا عمل أحدُهم محاضرةً في مكانٍ ما وتكلَّم بكلامٍ يخصّ الدعوة أو يخصّ الإسلام يُكبّر الحضور بصوتٍ عالٍ: الله أكبر، الله أكبر؟","title":"حكم الجهر بالتكبير أثناء إلقاء المحاضرات","answer":"الجواب:\nكان النبي إذا رأى شيئًا يُعجبه أو شيئًا مُنكرًا كبَّر وسبَّح، لما قال لهم ﷺ: ألا ترضون أن تكونوا ربعَ أهل الجنة؟ كبَّروا، قال: ألا تَرْضَون أن تكونوا نصفَ أهل الجنة؟ كبَّروا، أما إذا سمع شيئًا ما يُناسب قال: سبحان الله، سبحان الله؛ فلها أصلٌ، فالإنسان إذا رأى شيئًا يُعجبه أو يستنكره سبَّح أو ذكر الله وكبَّر لا بأس.\nس: إذا كان المُستمعون يُكبِّرون بصوتٍ جماعيٍّ وعالٍ، وربما يُكبِّر واحدٌ في مُكبّر الصوت ويُردد الباقون معه؟\nج: إذا حدث شيءٌ له أهمية، كأن يُخبرهم الخطيبُ بأن المسلمين فتحوا كذا، أو حصل للمسلمين كذا -يعني: شيئًا يُلفت النّظر- وكبَّروا ما فيه شيء، لكن لا يكون بصوتٍ جماعيٍّ، كلٌّ يُكبِّر وحده، ولو سبق أخاه، ما هو بشرطٍ أن يكون صوتي مع صوتك.","link":"https://binbaz.org.sa/fatwas/21870/حكم-الجهر-بالتكبير-اثناء-القاء-المحاضرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التكبير وقت إلقاء المحاضرات بصوت عال.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1766,"question":"إحدى عشر مرة (للأذكار بعد الصلاة)، ما صحّة هذا؟","title":"ما الصحيح في عدد الأذكار بعد الصلاة؟","answer":"الجواب:\nأظن في بعض روايات مسلم جاء عشرًا وجاء إحدى عشر، لكن أثْبَتُها وأكْمَلُها ثلاث وثلاثون بعد كلِّ صلاةٍ، ويختم بالتَّكبير -أربعة وثلاثين- أو بلا إله إلا الله، وحده لا شريكَ له، له الملك...\nس: مَن قال أنَّ إحدى عشرة وهمٌ من الراوي، وأنَّ المراد عشرة؟\nج: يُراجع رواية مسلم.","link":"https://binbaz.org.sa/fatwas/21873/ما-الصحيح-في-عدد-الاذكار-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصحيح في عدد الأذكار بعد الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1769,"question":"إذا كان السفرُ أقلّ من يومٍ وليلةٍ هل يجوز (بدون مَحْرَم)؟","title":"ما حكم سفر المرأة أو حجها بدون مَحْرَم؟","answer":"الجواب:\nولو، ولو، أيّ سفرٍ ولو بريدًا.\nس: ولو نصف النهار؟\nج: نعم، لا تُسافر إلا مع ذي مَحْرَمٍ.\nس: يدخل في ذلك السّفر بالطائرة؟\nج: بالطائرة، والسيارة، والباخرة، كلها.\nس: وإذا أوصل المرأةَ مَحْرَمُها إلى المطار واستقبلها آخرُ في المطار الآخر؟\nج: ما يكفي، لا بدّ أن يكون معها المحرمُ في الطائرة، فقد يعرض لها في نفس الطائرة عارضٌ من أهل الشر.\nس: المرأة كبيرة السن هل يجوز لها الحج بدون مَحْرَمٍ؟\nج: كله واحد: الشابة والكبيرة، فالرسول ما فرَّق عليه الصلاة والسلام، مع امرأةٍ.\nس: وإذا كانت من القواعد؟\nج: ولو، عام.","link":"https://binbaz.org.sa/fatwas/21876/ما-حكم-سفر-المراة-او-حجها-بدون-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سفر المرأة أو حجها بدون محرم.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1780,"question":"بعض الناس يُعامل الخادمة كمملوكة له فيضربها؟","title":"حكم من يُعامل الخادمة كمملوكة ويضربها","answer":"الجواب:\nلا، ما يجوز هذا، الخادمة مُستأجرة، ما يضربها ولا يتعدَّى عليها، إنْ جازت لهم وإلا فعليه أن يخلي سراحها، يردّها لأهلها. المملوك معناه: الخادم المملوك، هذا الذي يُؤَدَّب.","link":"https://binbaz.org.sa/fatwas/21887/حكم-من-يعامل-الخادمة-كمملوكة-ويضربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الخادمة مملوكة.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1797,"question":"هل هناك دعاء يُقال حتى يسلم الإنسانُ من الرياء؟","title":"ما الدعاء المشروع لمن خشي الرياء؟","answer":"الجواب:\nمنه الدعاء المشهور: اللهم إني أعوذ بك أن أُشرك بك شيئًا وأنا أعلم وأستغفرك لما لا أعلم، هذا يُدْعَى به دائمًا، ينبغي للمسلم أن يدعو به دائمًا.\nس: يقول الدعاء قبل أن يبدأ أي عملٍ؟\nج: في كل وقتٍ.","link":"https://binbaz.org.sa/fatwas/21904/ما-الدعاء-المشروع-لمن-خشي-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كيف يسلم الإنسان من الرياء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1805,"question":"إذا أقدم الإنسانُ على عملٍ، ودعا الله  أن يكون العملُ خالصًا لوجه الله، هل يكون مصيبًا؟","title":"حكم الدعاء بأن يكون العملُ خالصًا صائبًا","answer":"الجواب:\nالتوفيق بيد الله، يسأل ربَّه أن يُعينه على الإخلاص، وعلى الصدق في العمل، يسأل ربَّه أن يُعيذه من الرياء، ومن التَّعَبُّد بالبدع، مع الجِدِّ في طلب العلم، والجِدِّ في الإخلاص، لكن يسأل ربه أن يُوفِّقه لذلك ويُعينه عليه.","link":"https://binbaz.org.sa/fatwas/21913/حكم-الدعاء-بان-يكون-العمل-خالصا-صاىبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل دعاء الله عز وجل أن يكون العملُ خالصًا عمل صائب.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1809,"question":"ما وجه تشبيه المرأة بالأمْرَد؟","title":"ما حكم النظر إلى الأمرد؟","answer":"الجواب:\nلأنها تُشْتَهَى، وهو يُشْتَهَى، بعض الناس قد يشتهي المُرْدان أكثر، مثل قوم لوط، فقوم لوط تركوا النساء وتحولوا إلى المُرْدان -نسأل الله العافية- حتى عاقبهم الله بالخَسْف.","link":"https://binbaz.org.sa/fatwas/21917/ما-حكم-النظر-الى-الامرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المردان والمرأة.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":1907,"question":"ما رأيك فيما يفعله بعضُ القُرَّاء إذا نطق جنيٌّ على لسان شخصٍ، فيستدرجه في بعض الأسئلة ويُسْمِع الحاضرين؟ ما رأيكم في هذه؟","title":"حكم تحاور قارئ الرقية مع الجِن أمام الناس","answer":"الجواب:\nالمقصود أنه يُحَذِّره ويقول له: إنك ظالم، وأن هذا ما يجوز لك، والواجب عليك الخروج، ويقرأ الآيات التي تُضايقه وتجعله يحرص على الخروج؛ لأنَّه ضدّ القرآن، فهم يغضبون من القرآن، وتُؤذيهم قراءة القرآن، وإذا سأله عن الأسباب فلا بأس: ما الذي أدخلك؟ ما الذي جاء بك؟ لا بأس بذلك.","link":"https://binbaz.org.sa/fatwas/22019/حكم-تحاور-قارى-الرقية-مع-الجن-امام-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ما يفعله بعضُ القُرَّاء إذا نطق جنيٌّ على لسان شخصٍ يُسْمِع الحاضرين.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":1908,"question":"امرأة اشترت \"دخون\" عودٍ من امرأةٍ، وقالت لها: تُدَخِّنِي به عندما تأتيك ضِيقة، أو عندما يبكي أحدُ أطفالك؟","title":"حكم اتخاذ بُخُور العود علاجًا لضِيقة الصدر","answer":"الجواب:\nالعود المعتاد والدّخون المعتاد؟\nس: عود معتاد، والله أعلم، هل فيه شيء أو لا، لكن استخدامه غريب، قالت: تُدَخِّنِي به إذا شعرت بضيقةٍ أو إذا بكى أحدُ الأطفال؟\nج: أقول: ما أعلم لهذا أصلًا، الطِّيب لا شكَّ أنه يشرح الصدر وينفع ويُطَيِّب النفس، سواء كان عودًا أو وردًا أو عنبرًا أو مسكًا، فهو طَيِّب، إن كان المقصود هكذا، وإن كان المقصود شيئًا آخر -اعتقاد آخر- فهذا باطلٌ، تُسأل: وأيش مقصودها؟\nس: المرأة هذه تُعالج؟\nج: تُسأل: وأيش مقصودها من هذا الكلام؟ إن كان قصدها أنَّ الطِّيب طَيِّب، وأنه يُوسِّع الخاطر، ويشرح الصدر، وهو أحسن من الخياس والشيء الذي ما هو طَيِّب؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/22020/حكم-اتخاذ-بخور-العود-علاجا-لضيقة-الصدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التدخين بالعود.mp3","categories":["الطب والتداوي"]},{"id":1916,"question":"أحد الشباب عندنا لديه اختبارات في الجامعة، فذهب إلى أحد الأئمة كي يكتب له ورقةً فيها بركة؟","title":"حكم التمائم والحروز بآيات القرآن وغيرها","answer":"الجواب:\nحِرْزٌ يعني؟\nس: نعم.\nج: تميمة؟\nس: نعم.\nج: لا، التمائم لا تجوز.\nس: هل هي شركٌ أكبر أم شركٌ أصغر؟\nج: هي شركٌ أصغر، التمائم وما يُسمَّى الحروز وما يُسمَّى الجوامع هذه ما تجوز، النبي ﷺ قال: مَن تعلَّق تميمةً فلا أتمّ الله له، ومَن تعلَّق ودعةً فلا ودعَ الله له، ومَن تعلَّق تميمةً فقد أشرك.\nس: والذي يُؤمن بهذا الحِرْز؟\nج: يُعَلَّم ويُنْصَح، يُعَلَّم بالأحاديث، لكن بعض أهل العلم رخَّص فيها إذا كان فيها آيات من القرآن، والصواب أنها لا تجوز مطلقًا، حتى من القرآن لا تُعلَّق.\nس: حتى آيات القرآن؟\nج: لا تُعلَّق، إنما يُنفث بها وتُقرأ، فيقرأ عليه وينفث عليه ولا بأس، أما أن يجعلها في شيءٍ ويُعلِّقها في رقبته أو في يده فلا.","link":"https://binbaz.org.sa/fatwas/22029/حكم-التماىم-والحروز-بايات-القران-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التميمة شرك ولو كانت من رجل صالح.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":1939,"question":"بالنسبة لـ\"ما شاء الله، تبارك الله\" و\"ما شاء الله، لا قوة إلا بالله\" هل تُقال إذا رأى شيئًا أعجبه؟","title":"السُّنَّة الصحيحة فيما يُقول من رأى ما يعجبه","answer":"الجواب:\n\"ما شاء الله، لا قوة إلا بالله\": وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ [الكهف:39]، أو يقول: \"اللهم بارك فيه\"، \"بارك الله فيه\"، مع هذا، يُبَرِّك.\nس: \"ما شاء الله، تبارك الله\"؟\nج: هذه ما ورد فيها شيء، الوارد: \"ما شاء الله، لا قوة إلا بالله\"، أما \"تبارك الله\" فما ورد فيها شيء، وفي لفظ الحديث: ألَّا بَرَّكْتَ. إذا رأى ما يُعجبه يقول: \"اللهم بارك فيه\"، \"بارك الله فيه\"، مع: \"ما شاء الله، لا قوة إلا بالله\"، يدعو بالبركة: \"اللهم بارك فيه\"، \"بارك الله فيه\"، ضدّ العين يعني.","link":"https://binbaz.org.sa/fatwas/22052/السنة-الصحيحة-فيما-يقول-من-راى-ما-يعجبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى تقال ما شاء الله، تبارك الله، ومتى تقال ما شاء الله، لا قوة إلا بالله.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1968,"question":"بعض الناس يقول: إذا صاح الدِّيكُ فإنه يكون قد رأى مَلَكًا؟","title":"هل صياح الديك دليل على رؤيته لمَلَك؟","answer":"الجواب:\nجاء في الحديث الصحيح: أنها رأت مَلَكًا، فإذا سمعها يقول: \"اللهم إني أسألك من فضلك\" ولا يسبُّها.\nس: الديكة: الألوان كلها أو لون معين؟\nج: كلها.\nس: حتى الأسْوَد؟\nج: أنواع الديكة كلها.","link":"https://binbaz.org.sa/fatwas/22083/هل-صياح-الديك-دليل-على-رويته-لملك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صياح الديك دليل على رؤيته لملك.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1970,"question":"الفرق بين الريح والرياح؟","title":"ما الفرق بين الرياح والريح والسُّنة فيها؟","answer":"الجواب:\nكلها تُسمَّى ريحًا ورياحًا، لكن الغالب أنَّ الواحدة تكون في الشرِّ، والرياح المتتابعة يكون فيها خير: وَمِنْ آيَاتِهِ أَنْ يُرْسِلَ الرِّيَاحَ مُبَشِّرَاتٍ [الروم:46]، والريح العاصفة في الغالب تكون شرًّا، لكن مهما كانت -سواء ريح شديدة أو رياح متتابعة- يسأل الله خيرها، ويتعوَّذ بالله من شرِّها، والغالب أن الرياح المتتابعة تكون خيرًا: وَمِنْ آيَاتِهِ أَنْ يُرْسِلَ الرِّيَاحَ مُبَشِّرَاتٍ، وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ [الأعراف:57] بين يدي المطر.\nس: كذلك الأمطار؟\nج: إذا نزل المطرُ يقول: اللهم صيِّبًا نافعًا، مُطِرْنَا بفضل الله ورحمته.","link":"https://binbaz.org.sa/fatwas/22085/ما-الفرق-بين-الرياح-والريح-والسنة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين الرياح والريح.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1977,"question":"الاستثناء من أجل التَّبرك؟","title":"حكم الاستثناء من أجل التَّبرك في الدعاء","answer":"الجواب:\nلا، ما يصلح، الدعاء لا يصلح فيه هذا، وإنما يكون في الخبر: \"أنا مسافر إن شاء الله\"، \"أنا متزوج إن شاء الله\"، وما أشبه ذلك.\nس: بالنسبة لقول الزائر للمريض؟\nج: طهورٌ إن شاء الله هذا ما هو بدعاء، هذا خبر، يُخبر أنَّه طهورٌ إن شاء الله، مثلما قال النبيُّ ﷺ للمريض: طهورٌ إن شاء الله.\nس: إذا قلتُ لصاحبي عندما أفارقه: \"نلتقي في الجنة إن شاء الله\"؟\nج: ما فيه بأس.\nس: يكون إخبارًا؟\nج: نعم، من باب الخبر.","link":"https://binbaz.org.sa/fatwas/22093/حكم-الاستثناء-من-اجل-التبرك-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الاستثناء من أجل التَّبرك في الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":1981,"question":"قول: \"ما طاب المريضُ إلا من هذا العلاج\"؟","title":"حكم قول: \"ما طاب المريضُ إلا بهذا العلاج\"","answer":"الجواب:\nلا، ما يُقال هذا، فهذا العلاج سبب، فيُقال: من أسباب شفاء الله له أنه تعالج بكذا، وسوَّى كذا، واحتمى من كذا، فهذه أسباب لا يُنْسَب الشفاء إليها، يل يُنْسَب إليها أنها سبب.","link":"https://binbaz.org.sa/fatwas/22097/حكم-قول-ما-طاب-المريض-الا-بهذا-العلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول ما طاب المريضُ إلا من هذا العلاج.mp3","categories":["مسائل متفرقة في العقيدة","الطب والتداوي"]},{"id":2007,"question":"بعض الناس يتناولون حبوب منع الحمل بحجة أنه يريد أن ينظم حياتهم، هل هذا يدخل في قتل العيال؟","title":"ما الأعذار التي تجيز تنظيم أوقات الحمل؟","answer":"الجواب:\nلا، هذا إذا دعت له الحاجة، تُرْضِع فتعاطت هذا، أو معها مرض أو في رمضان للصوم للحاجة؛ فلا بأس إن شاء الله، وإلا ما هو من الوَأْد، ليس من الوَأد.\nس: بعضهم يأخذون هذه الحبوب يقولون ننظم حياتنا، عنده مثلًا أولاد اثنان أو ثلاثة ويوقف الحمل؟\nالشيخ: لا، ما ينبغي له، ينبغي له إذا كان لحاجة أو علة أو مرض أو للرِّضاع، الشريعة جاءت بالحث على الأولاد وتكثير الأمة: تزوجوا الودود الولود، يقول ﷺ: فإني مكاثر بكم الأمم يوم القيامة فكون الرجل والمرأة يحتسبان الأجر ويصبران حتى تكثر الأمة، ولعل الله يرزقه أولادًا صالحين، أما إذا كان لعلة؛ المرأة مريضة يشق عليها، أو الرضاع يشق عليها أن تحمل وترضع، هذا شيء مؤقت.\nس: ما حكم من يفعل هذا؟\nالشيخ: شيء مؤقت إذا كان للحاجة فلا بأس.\nس: ما حكمه؟\nالشيخ: ما ينبغي، أقل أحواله الكراهة.","link":"https://binbaz.org.sa/fatwas/22123/ما-الاعذار-التي-تجيز-تنظيم-اوقات-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تناول حبوب منع الحمل هل يدخل في الوأد.mp3","categories":["الطب والتداوي"]},{"id":2008,"question":"من ينكر على مَنْ يرفع الصوت بالذكر بعد الصلاة ما رأيكم فيه؟","title":"حكم رفع الصوت بالذكر بعد الصلاة","answer":"الجواب:\nالسَّنة رفع الصوت بالذكر، كان يُفعل على عهد النبي ﷺ، قال ابن عباس: كنت أعلم إذا انصرف الناس من سماع الذكر، أصوات الناس بالذكر.","link":"https://binbaz.org.sa/fatwas/22124/حكم-رفع-الصوت-بالذكر-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع الصوت بالذكر بعد الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2015,"question":"هل يقاس على هذا (الطاعون) جميع الأمراض مثلًا الكوليرا؟","title":"هل يقاس على الطاعون أي مرض ينتشر؟","answer":"الجواب:\nإذا وقع في البلد وهو معروف أنه يتأثر به الناس مثله مثل الطاعون.","link":"https://binbaz.org.sa/fatwas/22131/هل-يقاس-على-الطاعون-اي-مرض-ينتشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/انتشار مرض معين هل يقاس على الطاعون.mp3","categories":["الطب والتداوي"]},{"id":2021,"question":"هل يبقى الإمام بعد الفجر والمغرب مستقبلا القبلة حتى يهلل","title":"هل يهلِّل الإمام إلى القبلة في الفجر والمغرب؟","answer":"الجواب:\nلا، غلط، السُّنة أن ينصرف إلى المأمومين إذا قال: اللهم أنت السلام.. ينصرف إلى المأمومين، هذه السُّنة.\nس: هل فيه نهي عن استقبال القبلة؟\nالشيخ: لا، هذا كان فعل النبي، النبي ﷺ قال: صلوا كما رأيتموني أصلي كان إذا استغفر ثلاثًا وقال: اللهم أنت السلام، ومنك السلام..، انصرف إلى الناس، في صحيح مسلم عن عائشة رضي الله عنها قالت: كان النبي ينصرف إذا فرغ من قوله: اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام.","link":"https://binbaz.org.sa/fatwas/22137/هل-يهلل-الامام-الى-القبلة-في-الفجر-والمغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يبقى الإمام بعد الفجر والمغرب مستقبلا القبلة حتى يهلل.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2023,"question":"بالنسبة للعلاج بالقرآن: هل يُكثر من التلاوة على نفس الشخص المصاب من عدد السور أو تكفي سورة واحدة؟","title":"كيف تكون القراءة في العلاج بالقرآن؟","answer":"الجواب:\nما تيسر، لكن إذا قرأ قل هو الله أحد والمعوذتين أفضل؛ لأن الرسول ﷺ لما نزلت عليه بعدما أصابه السحر عافاه الله من شر ما أصابه، قال: ما تعوذ المتعوذون بمثلهما، يعني قل أعوذ برب الفلق وقل أعوذ برب الناس، مع قل هو الله أحد كان النبي يقرؤها عند النوم ثلاث مرات صباح ومساء، ثلاث مرات عليه الصلاة والسلام، والصحابة رقوا اللديغ بالفاتحة وعافاه الله بالحال.\nس: أحسن الله إليك، إذا أيقن أنها تشفي..\nالشيخ: المقصود يقرأ ما تيسر، كل القرآن شفاء.\nس:... يقولون إنه إذا ما أثَّر في الشخص مع القراءة يعتبر أنه ما تيقن الشفاء.\nالشيخ: لا ما هو بلزوم، لكن بعض الناس قد يقرأ وهو ما عنده يقين، ما عنده نية طيبة، ما تنفع قراءته، وبعض الناس -المقروء عليه- ما عنده ثقة بالقارئ ولا ثقة بالقرآن ولا ثقة بالله؛ فلا تنفع فيه القراءة، أما إذا جمع الله بينهما: القارئ ثقة ومؤمن بالله وأن الله مُصِرِّف الأمور، والمقروء عليه عنده ثقة بالله وعنده إيمان بالله؛ بإذن الله يحصل الشفاء.","link":"https://binbaz.org.sa/fatwas/22139/كيف-تكون-القراءة-في-العلاج-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القراءة في العلاج بالقرآن.mp3","categories":["الطب والتداوي"]},{"id":2064,"question":"تركيب قلب الكافر في جسد المؤمن، يعني: عملية في المستشفى؟","title":"حكم زراعة قلب الكافر في جسد المؤمن","answer":"الجواب:\nهذا محل خلافٍ، ولا مانع من تركيبه، فإن عمل بطاعة الله وأخلص له فقد انتقل من قلب كافرٍ إلى قلب مؤمنٍ، مثلما تُنْقَل أصبعه أو يده أو ضِرْسه.\nس: هذا خاصٌّ بالكافر؟\nج: نعم، إذا احتاج المؤمنُ إلى عضوٍ من الكافر.\nس: كيف يصير الإيمانُ في هذه الحالة؟\nج: الإيمان محله القلب، خشية الله ومحبة الله والإخلاص لله ينتقل من الحالة السيئة إلى الحالة الطَّيبة.","link":"https://binbaz.org.sa/fatwas/22182/حكم-زراعة-قلب-الكافر-في-جسد-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/زراعة قلب الكافر في جسد المؤمن.mp3","categories":["الطب والتداوي"]},{"id":2075,"question":"سائلة تسأل: بالنسبة لاستخدام اللولب، مع العلم أنه يقتل البُويضة بعد الإخصاب، وليس قبله، فما حكمه؟","title":"حكم استخدام اللولب والحبوب لمنع الحمل","answer":"الجواب:\nهم يفعلونه لأجل منع الحمل، وتركه أوْلى، فترك اللولب والحبوب أوْلى، وكونها تحمل، إلا من حاجةٍ؛ إذا كان يضرُّها الحمل، أو أطفال كثير عندها، وتراضت وزوجها على ذلك؛ لا بأس إن شاء الله.\nس: وعند الحاجة هل تستخدم اللَّولب؟\nج: اللولب والحبوب؛ لأنه يمنع الحمل مؤقَّتًا.","link":"https://binbaz.org.sa/fatwas/22193/حكم-استخدام-اللولب-والحبوب-لمنع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استخدام اللولب للمرأة لمنع الحمل.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":2104,"question":"رجل يطلب الرزقَ بواسطة الإعلان في بعض الجرائد أو في الشوارع بأنَّ عنده \"أتوبيسات\"، ويأخذ بعض المدرسات خارج الرياض ما يُقارب 200 كيلو، ويقول: معي زوجتي أو محرم، ومعه ستّ مدرسات أو خمس؟","title":"حكم سفر نساءٍ مع سائق ومَحْرَم له","answer":"الجواب:\nالواجب ألا يُسافرن إلا ومعهن محرم، هذا هو الأحوط، وبعض أهل العلم يُرَخِّص في هذا عند الحاجة، وعند الأمن، ولكن ظاهر السنة عدم الجواز إلا بمحرمٍ؛ لقوله ﷺ: لا تُسافر المرأةُ إلا مع ذي مَحْرَمٍ.\nس: لكن يقول: هذا الرزق الذي آخذه من المُدرسات هل أستمر فيه؟\nج: الأحوْط له الترك، والتماس عمل آخر.","link":"https://binbaz.org.sa/fatwas/22222/حكم-سفر-نساء-مع-ساىق-ومحرم-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يسافر مع نساء ومعه زوجته أو محرم.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":2110,"question":"امرأةٌ حَرَّج عليها أبوها ألا تأخذ حبوب منع الحمل، فالآن أبوها توفي، وأنجبت تسعة أبناء بين ذكور وإناث.....؟","title":"حكم امرأة حَرَّجَ عليها أبوها في أمرٍ يضرُّها","answer":"الجواب:\nإذا كانت عليها مضرَّة لا بأس، وما عليها من كلام أبيها.\nس: عليها مضرَّة في صحتها.\nج: إذا كانت عليها مضرَّة لا بأس ولو حَرَّج.","link":"https://binbaz.org.sa/fatwas/22228/حكم-امراة-حرج-عليها-ابوها-في-امر-يضرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/امرأةٌ شدَّد عليها أبوها ألا تأخذ حبوب منع الحمل.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":2129,"question":"مَن اكتفى باتِّخاذ الدعاء سببًا في التَّداوي؟","title":"حكم الاكتفاء بالدعاء في التداوي","answer":"الجواب:\nالدعاء سبب، لكن إذا تداوى بشيءٍ آخر من: المأكولات، أو المشروبات، أو الكي، أو الدهون، أو المروخ، أو غير هذا؛ فلا بأس، فالأسباب لا بأس بها.","link":"https://binbaz.org.sa/fatwas/22247/حكم-الاكتفاء-بالدعاء-في-التداوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اتخاذ الدعاء سببا في التداوي.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2132,"question":"الماء الذي يُقرأ عليه، ويُوضع شيء من الزعفران عليه، فيشربه المريض الممسوس؟","title":"حكم وضع الزعفران في ماء يُقرأ عليه","answer":"الجواب:\nما فيه بأس، لكن إذا كان فيه محادَّة، فالمحادَّة لا يَلزم، هذا طِيب، أما إذا كان مِن سائر المرضى فلا بأس، فالزعفران قد ينفع الله به.","link":"https://binbaz.org.sa/fatwas/22250/حكم-وضع-الزعفران-في-ماء-يقرا-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وضع الزعفران في الماء الذي يُقرأ عليه.mp3","categories":["الطب والتداوي"]},{"id":2147,"question":"هل يُستحب قول سبحان الذي سخَّر لنا هذا وما كنا له مُقرنين .. في السيارة وفي المصعد؟","title":"هل يُقال دعاء الركوب في غير السفر؟","answer":"الجواب:\nعند السفر: السيارة، والباخرة، والطائرة.\nس: وفي الحضر؟\nج: لا، كان النبيُّ ﷺ يفعله في السفر، فكان إذا ركب الدابةَ في السفر كبَّر ثلاثًا، وحمد الله ثلاثًا، وقال: سبحان الذي سخَّر لنا هذا ...\nس: وفي المصعد؟\nج: في السفر فقط، فالمصعد ليس بسفرٍ.\nس: والركوب في أي وقتٍ؟\nج: عند السفر.","link":"https://binbaz.org.sa/fatwas/22266/هل-يقال-دعاء-الركوب-في-غير-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول سبحان الذي سخَّر لنا هذا وما كنا له مُقرنين.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2168,"question":"بعض أهل البادية لهم أسئلة: أولها: يقولون: إنَّ بعضنا يكتب من الفحم والسكر آيات في ورقة، ثم يضعها في إناء فيه ماء، ثم يشربها، فما حكم هذا؟","title":"حكم كتابة آيات ووضعها في ماء للتداوي","answer":"الجواب:\nالأحسن أن يكون من شيء آخر غير الفحم، إما من الزعفران أو غيره من الأشياء التي لا تضر، لا بأس، فالزعفران إذا كُتِبَ في ورقة أو صحن وشُرب لا بأس، آيات من القرآن.","link":"https://binbaz.org.sa/fatwas/22289/حكم-كتابة-ايات-ووضعها-في-ماء-للتداوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كتابة آيات من القرآن ووضعها في إناء فيه ماء ثم شربها للتداوي.mp3","categories":["الطب والتداوي"]},{"id":2192,"question":"سائلة تقول: هل سورة البقرة بواسطة قارئ في شريطٍ في البيت تكفي أو لا بد أن يقرأها الشخص نفسه؟","title":"هل تفيد القراءة المُسَجَّلة في الرُّقية؟","answer":"الجواب:\nيُرْجَى إن شاء الله.","link":"https://binbaz.org.sa/fatwas/22315/هل-تفيد-القراءة-المسجلة-في-الرقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في قراءة القرآن للتداوي.mp3","categories":["الطب والتداوي","القرآن وعلومه"]},{"id":2195,"question":"سائلٌ يقول: سماحة الشيخ، السلام عليكم ورحمة الله وبركاته، أُشهد الله أني أُحبّك في الله، فما حكم الدعاء بـ\"اللهم يا مالك الملك، تُؤتي الملك من تشاء، وتنزع الملك ممن تشاء، أسألك مُلكًا لا يَفْنَى\"؟","title":"ما حكم سؤال الله مُلكًا لا يَفْنَى؟","answer":"الجواب:\nأما الحب في الله فهو من القُربات، فنقول: أحبّك الله الذي أحببتنا له.  أما المُلك في الدنيا فليس هناك مُلك لا يفنى، ولكن إذا قصد الجنة فلا بأس، أما إذا كان يقصد ملكًا في الدنيا لا يفنى فهذا ليس بصحيحٍ، فكل الدنيا فانية: كُلُّ مَنْ عَلَيْهَا فَانٍ [الرحمن:26]، أما إذا أراد ملكًا في الآخرة -يعني: في الجنة- فلا بأس.\nس: يكون من الاعتداء في الدعاء؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/22318/ما-حكم-سوال-الله-ملكا-لا-يفنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعاء بـاللهم يا مالك الملك..mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2200,"question":"هل الدعاء المُستجاب يُغيِّر شيئًا؟","title":"هل الدعاء المُستجاب يُغيِّر ما هو مقدَّر؟","answer":"الجواب:\nلا، ما يُغير شيئًا، فكل شيء على قدره السابق، المنجز منجز، والمعلَّق معلَّق، فهناك قدر معلَّق، وهناك قدر منجز، والإنسان يدعو ربه ويسأله فهو أحكم وأعلم .","link":"https://binbaz.org.sa/fatwas/22323/هل-الدعاء-المستجاب-يغير-ما-هو-مقدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للدعاء أثر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2225,"question":"هل يُستفاد من حديث سلمة بن الأكوع: -أن رجلا أكل عند رسول الله بشماله، فقال: كل بيمينك قال: لا أستطيع، قال: لا استطعت، ما منعه إلا الكبر- جواز الدعاء على المسلم إذا خالف أمر الله وأمر ورسوله ﷺ؟","title":"ما حكم الدعاء على المسلم إذا خالف الشرع؟","answer":"الجواب:\nيظهر من الحديث الجواز إذا عرف أنه مُتكبّر، لكن العفو أفضل، فالعفو والدّعاء لأخيك بالهداية أفضل كما في النصوص الأخرى.","link":"https://binbaz.org.sa/fatwas/22348/ما-حكم-الدعاء-على-المسلم-اذا-خالف-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جواز الدعاء على المسلم إذا خالف أمر الله وأمر ورسوله.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2275,"question":"التَّميمة إذا كانت من القرآن ما الصواب فيها؟","title":"حكم التميمة إذا كانت من القرآن","answer":"الجواب:\nالمنع، يُسمَّى: الحروز، والتَّمائم من القرآن وغير القرآن: الصواب منعها.\nس: لكن إذا كانت من القرآن هل تصل إلى حدِّ الشرك الأكبر؟\nج: الشرك الأصغر؛ لأنها وسيلةٌ، ولعموم الأدلة.\nس: والأكبر إذا اعتقد النفعَ والضرَّ أو كيف؟\nج: الأكبر إذا اعتقد أنها هي التي تنفع بنفسها، أو تدفع الضرَّ بنفسها.","link":"https://binbaz.org.sa/fatwas/22398/حكم-التميمة-اذا-كانت-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التَّميمة إذا كانت من القرآن.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":2343,"question":"ما الدّعاء الذي يُشرع للمُسافر أن يقوله قبل أن يذهب؟","title":"ما الأدعية والأذكار المشروعة في السفر؟","answer":"الجواب:\nكان النبيُّ ﷺ إذا ركب راحلته قال الدّعاء المشهور عند ركوبه: فيُكبر ثلاثًا، ويحمد الله جلَّ وعلا، ويقول: سبحان الذي سخَّر لنا هذا وما كنا له مُقرنين وإنا إلى ربنا لمنقلبون، اللهم إنا نسألك في سفرنا هذا البِرَّ والتَّقوى، ومن العمل ما ترضى...، تُراجع في \"رياض الصَّالحين\" وغيره أحاديثُ السفر.\nس: ماذا يقول المسافرُ للمُقيم؟\nج: ما أعرف فيه شيئًا ورد، لكنَّ ذكر الله مطلوبٌ للمؤمن، مسافرًا أو مقيمًا، فالإكثار من ذكر الله والاستغفار هذا هو المطلوب دائمًا.\nس: وقول: \"أستودعك الله الذي لا تضيع ودائعه\"؟\nج: هذا عند السفر: أستودع الله: دينك، وأمانتك، وخواتيم عملك.","link":"https://binbaz.org.sa/fatwas/22467/ما-الادعية-والاذكار-المشروعة-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء السفر المشروع.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2372,"question":"ما معنى اللهم صل على محمد ﷺ؟","title":"معنى الصلاة على النبيﷺوأفضل صيغها","answer":"الجواب:\nطلب الثناء من الله، الصلاة من الله: الثناء على عبده، يعني: اللهم أثنِ عليه عند الملائكة وارفع شأنه.\nس: صيغة معينة للصلاة على النبي ﷺ؟\nالشيخ: مثل ما سمعت، جاء فيها عدة أحاديث، ولو قال: اللهم صل عليه وسلم حصل المقصود. والأفضل: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، هذا يعم، هذا أكملها. وفي أنواع، منها النوع الآخر: اللهم صل على محمد وعلى أزواجه وذريته كما صليت على آل إبراهيم، وبارك على محمد وعلى أزواجه وذريته كما باركت على آل إبراهيم إنك حميد مجيد. ونوع آخر: اللهم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم، وبارك على محمد وعلى آل محمد كما باركت على آل إبراهيم في العالمين إنك حميد مجيد، كل هذا حسن وغيرها من الأنواع الثابتة، مع الحمد والثناء على الله، يصلي على النبي ﷺ ثم يدعو.","link":"https://binbaz.org.sa/fatwas/22497/معنى-الصلاة-على-النبيﷺوافضل-صيغها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى اللهم صل على محمد.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2445,"question":"بعض الناس بعد الفريضة يَدْعُون ولا يأتون بالأذكار؟","title":"حكم مَنْ يشرعون في الدعاء عقب الفريضة","answer":"الجواب:\nيُعَلَّمُون السُّنة، السُّنة الذِّكر الذي جاء عن الرسول ﷺ، أما تجمعوا مع الدعاء ورفع أصواتهم بالدعاء جماعي، صوت جماعي؛ هذا خلاف السنة بل بدعة، إنما يذكر الله كل واحد، يذكر الله في نفسه، على ما جاء في الشريعة كما سمعتم.","link":"https://binbaz.org.sa/fatwas/22574/حكم-من-يشرعون-في-الدعاء-عقب-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل الدعاء بعد الفريضة أم الأذكار.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2450,"question":"هل يُشْرَع رفع اليدين في الدعاء...؟","title":"متى يُشْرَع رفع اليدين في الدعاء؟","answer":"الجواب:\nمن أسباب الإجابة رفع اليدين في الدعاء، إذا دعا في القنوت أو غيره، إلا الأماكن التي ما رفع فيها النبي ﷺ ما يرفع فيها، بعد السلام من الفريضة ما يرفع، ما رفع النبي ﷺ، ولا بين السجدتين ولا في آخر الصلاة، إذا دعا قبل أن يسلم لا يرفع؛ لأن الرسول ما كان يرفع، في هذه المواضع التي ما رفع فيها النبي ﷺ لا يرفع فيها، خطبة الجمعة لا يرفع فيها، خطبة العيد لا يرفع فيها، إلا إذا استسقى طلب الغيث يرفع يديه.","link":"https://binbaz.org.sa/fatwas/22579/متى-يشرع-رفع-اليدين-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع اليدين حال الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2454,"question":"ما يقول بعد الانتهاء من الوتر؟","title":"ماذا يُقال بعد الانتهاء من الوتر؟","answer":"الجواب:\nيقول: سبحان الملك القدوس، سبحان الملك القدوس، ويمدها في الثالثة سبحان الملك القدوس، يمدها قليلًا، رب الملائكة والروح، إلى آخرها، كان النبي ﷺ يقول ذلك إذا سَلَّم من الوتر، يقول: سبحان الملك القدوس، سبحان الملك القدوس، سبحان الملك القدوس، ويمدها في الثالثة قليلًا، زاد الدارقطني بإسناد صحيح: رب الملائكة والروح، في الأخيرة.","link":"https://binbaz.org.sa/fatwas/22583/ماذا-يقال-بعد-الانتهاء-من-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ماذا يقال بعد الانتهاء من الوتر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2481,"question":"هل هناك صيغة معينة في الصلاة على رسول الله ﷺ؟","title":"ما أفضل صيغة للصلاة على النبي ﷺ؟","answer":"الجواب:\nالصيغة الواردة عن رسول الله عدة صيغ: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، هذه أجْمَعُها. وفي بعضها حذف إحدى الصلاتين وإحدى البركتين على إبراهيم وآله، اللهم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم، اللهم بارك على محمد وعلى آل محمد كما باركت على آل إبراهيم، إنك حميد مجيد. وفي بعضها: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم، وبارك على محمد وعلى آل محمد كما باركت على إبراهيم، إنك حميد مجيد. وفي بعضها: اللهم صل على محمد وعلى آل محمد كما صليت على آل إبراهيم، وبارك على محمد وعلى آل محمد كما باركت على آل إبراهيم، في العالمين إنك حميد مجيد. وفي بعضها: اللهم صل على محمد عبدك ورسولك كما صليت على إبراهيم، وبارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم.  كله حسن إذا أتى بشيء من هذا؛ كله طيب.\nومعنى الصلاة من الله: ثناؤه عليه، صلاة الله على عبده، ثناؤه عليه في الملإ الأعلى.\nس: ... بعضهم يأتي بصلوات من عنده؟\nالشيخ: الأفضل الواردة، وإن قال: اللهم صل عليه وسلم فلا بأس، هذه مختصرة: اللهم صل عليه وسلم، اللهم صل على رسولك، اللهم صل على نبيك، اللهم سلم عليه، عليه الصلاة والسلام، كما يقول عند قراءة الحديث في الكتب.","link":"https://binbaz.org.sa/fatwas/22610/ما-افضل-صيغة-للصلاة-على-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صيغة الصلاة على رسول الله.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2483,"question":"مقدار الساعة (يوم الجمعة) بساعتنا هذه أم...؟","title":"ما مقدار ساعة الاستجابة يوم الجمعة؟","answer":"الجواب:\nلا، ساعة معينة، ما لها حد محدود، يعني ساعة خفيفة مثل ما قال ﷺ أشار بيده يقلِّلها، يعني خفيفة.\nس: ورود الاختلاف في تحديد ساعة الجمعة ألا يدل على أنها تتنقل؟\nالشيخ: محتمل أنها تتنقل، ومحتمل أنه أخبر هذا في وقت وهذا في وقت؛ فيكون أحدهما ناسخًا للآخر، فالحزم أنه يدعو كثيرًا، يدعو كثيرًا في ساعاتها لعله يصادف هذه الساعة، ويخص العصر ويخص وقت جلوس الإمام على المنبر، يخصه بمزيد عناية؛ لأنه ورد فيه نص.\nس: الراجح؟\nالشيخ: كلها صحيحة هذه وهذه، يدعو في هذا وفي هذا.\nس: يرفع يديه؟\nالشيخ: إن رفع يديه فلا بأس، لكن عند انتظار الجمعة لا يرفع يديه حين يسمع الخطيب، أو في الصلاة ما يرفع.\nس:في نهاية يوم الجمعة؟\nالشيخ: إذا جلس بعد العصر ورفع يديه ما في شيء.","link":"https://binbaz.org.sa/fatwas/22612/ما-مقدار-ساعة-الاستجابة-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مقدار ساعة الاستجابة يوم الجمعة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2491,"question":"بالنسبة للبرنامج اليومي للمسلم هل يبدأ من قيام الليل أو من صلاة الفجر؟","title":"متى يبدأ البرنامج اليومي للمسلم؟","answer":"الجواب:\nمن طلوع الفجر، الأذكار من طلوع الفجر، والليل من غروب الشمس، وآخر النهار تَبَعُ الليل، وأول النهار تَبَعُ النهار، لو فعله بعد الصبح أو بعد طلوع الشمس كله طيب، يكون أول النهار يصدق عليه إلى وقوف الشمس إلى زوال الشمس، وبعد الزوال، كله تبع المساء إلى أول الليل أثناء الليل.","link":"https://binbaz.org.sa/fatwas/22621/متى-يبدا-البرنامج-اليومي-للمسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يبدأ البرنامج اليومي للمسلم.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2499,"question":"قنوت الوتر سنة؟","title":"ما حكم قنوت الوتر؟","answer":"الجواب:\nمستحب، مستحب، علَّمه النبي ﷺ الحسنَ بن علي.\nس: مَنْ تركه؟\nالشيخ: لا حرج، مستحب.\nس: في رمضان أحيانًا يتركون القنوت وأحيانًا يقنتون، ويقولون: النبي ﷺ كان يقنت يومًا ويترك القنوت يومًا؟\nالشيخ: ما له أصل، لكنه مستحب، من تركه فلا بأس، الصحابة فعلوه تارة يقنتون وتارة لا يقنتون، والنبي ﷺ عَلَّم الحسن، ما قال افعله تارة وتارة، علمه القنوت كيف يقنت، فإذا داوم عليه فلا بأس، فعله جماعة من الصحابة، وإذا ترك بعض الأحيان فلا بأس، مستحب نافلة، وإذا تركه بعض الأحيان ليعلم الناس أنه ليس بواجب؛ من باب التعليم.","link":"https://binbaz.org.sa/fatwas/22629/ما-حكم-قنوت-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قنوت الوتر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2500,"question":"بعد الركوع قائمًا ماذا يقول؟","title":"ما يُقال في الرفع من الركوع وبين السجدتين","answer":"الجواب:\nربنا ولك الحمد حمدا كثيرًا طيبًا مباركًا فيه، أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد، لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجَدِّ منك الجَدُّ، يكرر الحمد والثناء، وبين السجدتين يقول: رب اغفر لي، رب اغفر لي، يكرر، اللهم اغفر وارحمني واهدني واجبرني وارزقني، اللهم اغفر لي وارحمني، اللهم أصلح قلبي وعملي، اللهم اغفر لي ولوالدي، يكرر الدعاء.","link":"https://binbaz.org.sa/fatwas/22630/ما-يقال-في-الرفع-من-الركوع-وبين-السجدتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يقال عند الرفع من الركوع وبين السجدتين.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2501,"question":"السؤال والتَّعَوُّذ في الفريضة أو في النافلة؟","title":"هل السؤال والتَّعَوُّذ بالصلاة يشمل الفريضة؟","answer":"الجواب:\nالمحفوظ عنه ﷺ في تهجده في الليل، أما في الفريضة ما كان يقف في الفريضة، كان يستمر في قراءته عليه الصلاة والسلام، لكن في التهجد كان يعمل هذا الشيء، يقف عند كل آية في صلاة الليل في النافلة.\nس: من فعله في الفريضة يُنْكَر عليه؟\nالشيخ: الأمر واسع، لكن تَرْكُه أفضل في الفريضة؛ لئلا يشق على الناس.","link":"https://binbaz.org.sa/fatwas/22631/هل-السوال-والتعوذ-بالصلاة-يشمل-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السؤال والتعوذ في الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2505,"question":"بالنسبة للدعاء في السجود هل الإنسان يشارك والديه وذريته؟","title":"حكم الدعاء في السجود للوالدين والذرية","answer":"الجواب:\nيدعو بما تيسر، يقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء يدعو لنفسه ولوالديه وللمسلمين ولمشايخه ولزملائه ولمن أحسن إليه.","link":"https://binbaz.org.sa/fatwas/22635/حكم-الدعاء-في-السجود-للوالدين-والذرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء في السجود.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2534,"question":"عدم رفع اليدين في الدعاء ووضعها على الركبتين مخافة الرياء هذا صحيح؟","title":"حكم عدم رفع اليدين في الدعاء مخافة الرياء","answer":"الجواب: رفع اليدين في الدعاء في محله أوْلى، رفع اليدين في محل رفع الدعاء في محله أوْلى، اقتداء بالنبي عليه الصلاة والسلام مثل ما فعل في الاستسقاء.","link":"https://binbaz.org.sa/fatwas/22665/حكم-عدم-رفع-اليدين-في-الدعاء-مخافة-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/عدم رفع اليدين في الدعاء مخافة الرياء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2554,"question":"هل يجوز للإنسان أن يتأفَّف من الدنيا ويتمنى الموت إذا كَثُرَت المعاصي؟","title":"حكم تمني الموت إذا كَثُرَت المعاصي","answer":"الجواب: يسأل ربه أن يختار له الأصلح، كما أمر النبي ﷺ: اللهم أحيني إذا كانت الحياة خيرًا لي، وتوفني إذا كانت الوفاة خيرًا لي.","link":"https://binbaz.org.sa/fatwas/22685/حكم-تمني-الموت-اذا-كثرت-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التأفف من الدنيا وتمني الموت.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2559,"question":"امرأة تريد أن تسافر إلى أمريكا مع زوجها من أجل الدراسة، السؤال تقول: هي عندما تصل إلى المطار لا بدّ أن يأمروا أي امرأة أن تكشف وجهها وهي ملتزمة ويجبرونها لا بدّ أن تفعل هذا الفعل، فماذا تصنع؟","title":"حكم كشف وجه المرأة في المطار للضرورة","answer":"الجواب: لماذا؟\nالطالب: يقول لا بدّ أن يطابقوا الصورة مع الشخص؟\nالشيخ: إذا اضطُرَّت؛ ما عليها شيء.","link":"https://binbaz.org.sa/fatwas/22691/حكم-كشف-وجه-المراة-في-المطار-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كشف وجه المرأة في المطارات للضرورة.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":2597,"question":"أي صيغة للاستغفار تصلح؟","title":"ما الألفاظ التي يكون بها الاستغفار؟","answer":"الجواب: أي صيغة، اللهم اغفر لي، أستغفر الله وأتوب إليه، اللهم اغفر لي وتب عليّ إنك أنت التواب الغفور، أستغفر الله وأتوب إليه، وهكذا: اللهم تب علي، اللهم اغفر لي.","link":"https://binbaz.org.sa/fatwas/22730/ما-الالفاظ-التي-يكون-بها-الاستغفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي الصيغة التي تصلح للاستغفار.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2600,"question":"هل الاستغفار يكون سببًا مِن أسباب الرزق؟","title":"هل الاستغفار مِن أسباب الرزق؟","answer":"الجواب: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ [الطلاق:2-3] الاستغفار والتوبة من التقوى.\nس: الذكر والاستغفار يُجمع مع بعض؟\nالشيخ: نعم، تارة كذا وتارة كذا، تارة يذكر الله، وتارة يستغفر، ولكن يكون صادقًا.","link":"https://binbaz.org.sa/fatwas/22734/هل-الاستغفار-من-اسباب-الرزق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الاستغفار من أسباب الرزق.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2610,"question":"بالنسبة لزيت الزيتون هو من شجرة مباركة، فهل يُعالج به السحر والمسّ؟","title":"هل يُعالج السحر والمسّ بزيت الزيتون؟","answer":"الجواب: الزيتون من شجرة مباركة، يُعالَج به ما جُرِّب فيه أنه ينفع، فيه كل خير، دواء طيب ويُعالج به ما جرب أنه ينفع فيه، والله المستعان.\nس: طيب هل يُدْهَن به ويُشرب منه؟\nالشيخ: كله طيب، الدهن منه والشرب منه، كله طيب، زيت مبارك.\nس: سواء قرئ فيه أم لا؟\nالشيخ: كله واحد، نعم.","link":"https://binbaz.org.sa/fatwas/22745/هل-يعالج-السحر-والمس-بزيت-الزيتون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعالج زيت الزيتون السحر والمس.mp3","categories":["الطب والتداوي"]},{"id":2647,"question":"المرأة إذا كانت موجودة في مكة مع أهلها هل تصلي في البيت أو في الحرم أفضل لها؟","title":"هل صلاة المرأة ببيتها أفضل حتى في الحرم؟","answer":"الجواب: في مكة والمدينة الأفضل في البيت، في كل مكان، إلا إذا كان لداعي إما لسماع مواعظ وتذكير ومحاضرات، أو لأنها تَكْسُل في البيت وتنشط هناك؛ فلا بأس أن تخرج للمسجد، وإلا البيت أفضل، يقول النبي ﷺ: وبيوتُهن خير لهن ومع هذا قال ﷺ: لا تمنعوا إماء الله مساجد الله.","link":"https://binbaz.org.sa/fatwas/22783/هل-صلاة-المراة-ببيتها-افضل-حتى-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل للمرأة في مكة أن تصلي في البيت أو في الحرم.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":2654,"question":"... الزيادة في الدعاء في السجود (غير الوارد)؟","title":"هل يجوز الدعاء في السجود بغير الوارد؟","answer":"الجواب: يدعو بما أحَبَّ من الدعوات الطيبة، النبي ﷺ يقول: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء وفي اللفظ الآخر: فاجتهدوا في الدعاء.\nس: ... الأفضل يدعو بما ورد؟\nالشيخ: ما هو بلازم؛ إذا دعا بالأفضل وإذا دعا بغيره، ما يخالف؛ لأن الناس لهم حاجات، تبدو لهم حاجات؛ فإذا دعا بالأفضل دعا بالوارد ودعا بغيره الحمد لله.\nس: ما يخالف السُّنَّة؟\nالشيخ: لا ما يخالف، يدعو بما يسَّر الله له.\nس: ألم يرد أنه يتخيَّر من الدعاء أحبه إليه؟\nالشيخ: هذا في آخر الصلاة، علمه النبي ﷺ الصحابة بعد التشهد قال: ثم يتخير من الدعاء أعجبه إليه وفي اللفظ الآخر: ثم ليتخير من المسألة ما شاء في آخر الصلاة، ودعاء السجود كذلك، الحكم واحد.","link":"https://binbaz.org.sa/fatwas/22790/هل-يجوز-الدعاء-في-السجود-بغير-الوارد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء في الصلاة عند السجود.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2741,"question":"الأوراق التي عليها البسملة: هل تُرمى في سلة المهملات؟ أو ماذا يُعمل بها وهي كثيرة؟","title":"حكم الأوراق المهملة التي عليها البسملة","answer":"الجواب: يُمحى اسم الجلالة ويمزّق، أو تمزق تمزيقًا تامًّا ويكفي.\nس: إذا طُمست في شيء؟\nالشيخ: إذا طُمست يكفي.\nس: كذلك الجرائد؟\nالشيخ: الجرائد محفوظة، يحفظها في دولاب أو غيره؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/22889/حكم-الاوراق-المهملة-التي-عليها-البسملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأوراق التي عليها البسملة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2754,"question":"بعض الناس يذكر حديثًا عند الوضوء عند غسل اليدين؟","title":"ما الصحيح من أذكار الوضوء؟","answer":"الجواب: لا، ما له أصل، إلا بعد الوضوء. يسمّي الله عند بدء الوضوء، ويتشهّد عند آخره، هذا الثابت.\nس: البسملة هل يقال بوجوبها عند الوضوء؟\nالشيخ: المعروف التسمية مستحبة، وقول بعض أهل العلم يجب، أحمد رحمه الله وجماعة الجمهور على أنها مستحبة، والقول الثاني أنها واجبة لكن الحديث ضعيف، حديث: لا وضوء لمن لم يذكر اسم الله قال الحافظ رحمه الله:..... بمجموعها يرتقي إلى درجة الحسن. وعلى كل حال المؤمن لا يدعها، يخرج من الخلاف، ينبغي أن يعتني بها عند أول الوضوء إذا ذَكَر، أما إذا نسي أو جهل ما عليه شيء.\nس: يقولها أثناء الوضوء إذا نسيها؟\nالشيخ: إذا نسيها يقولها في أثناء الوضوء، وإذا نسيها سقطت عنه.","link":"https://binbaz.org.sa/fatwas/22902/ما-الصحيح-من-اذكار-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأذكار التي تقال عند الوضوء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2850,"question":"هل يجب كتابة الصلاة على الرسول ﷺ عند ذكره في الكتابة؟","title":"حكم كتابة الصلاة والتسليم لذِكْر النبي ﷺ","answer":"الجواب: هذا الظاهر عند ذكره وعند السماع، عند كتابته وعند السماع، يقول ﷺ في الحديث الصحيح: رغم أنف امرئ ذُكرت عنده.. يقول له جبرائيل: رغم أنف امرئ ذكرت عنده فلم يصل عليك، قل: آمين، فقلت: آمين وهذا يدل على الوجوب رغم أنف امرئ.. اللهم صل عليه.\nس: إذا كتب الإنسان الرسول ثم صلى عليه شفهيًّا ولم يكتب ذلك؟\nالشيخ: يحصل المقصود، لكن إذا كتبه أحسن؛ حتى يعين القارئ.","link":"https://binbaz.org.sa/fatwas/23003/حكم-كتابة-الصلاة-والتسليم-لذكر-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كتابة الصلاة على الرسول عند ذكره في الكتابة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2853,"question":"بالنسبة للذي يظن أن الصلاة على النبي ﷺ فقط يوم الجمعة؟","title":"هل فضل الصلاة والتسليم يختص بالجمعة؟","answer":"الجواب: لا، في كل وقت، عام، من صلى علي صلاة الله عليه بها عشرًا عام في جميع الأوقات، في الليل والنهار، والسفر والحضر، وأنت جالس، وأنت مضطجع، وأنت ماش، مثل ذكر الله؛ من جنس الذكر.\nس: الإكثار يوم الجمعة مستحب؟\nالشيخ: يعني يكثر الزيادة، مثل ما قال فأكثروا عليّ....","link":"https://binbaz.org.sa/fatwas/23006/هل-فضل-الصلاة-والتسليم-يختص-بالجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الصلاة على النبي فقط يوم الجمعة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2863,"question":"في حديث فضالة (إذا صلى أحدكم فليبدأ بتحميد ربه) للوجوب أم للاستحباب؟","title":"هل البدءُ بالحَمْد في الدعاء واجب أم مستحب؟","answer":"الجواب: المشهور عند العلماء أنه للاستحباب للمؤمن؛ من آداب الدعاء.","link":"https://binbaz.org.sa/fatwas/23016/هل-البدء-بالحمد-في-الدعاء-واجب-ام-مستحب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا صلى أحدكم فليبدأ بتحميد ربه.. للوجوب أم للاستحباب.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2875,"question":"المداومة على رفع اليدين والدعاء بعد الفريضة؟","title":"حكم مداومة رفع اليدين والدعاء بعد الفريضة","answer":"الجواب: ما هو مشروع، ما كان النبي ﷺ يرفع بعد الفريضة.\nس: يعتبر بدعة؟\nالشيخ: ما ينبغي، يُنَبَّه.\nس: وإذا رأى أحدًا؟\nالشيخ: بعد الفريضة يُنَبَّه أن هذا ما يصلح، ما هو بمشروع هذا، بل بدعة، أما إذا فعله بعض الأحيان في النافلة؛ فعله النبي في النافلة ﷺ.","link":"https://binbaz.org.sa/fatwas/23030/حكم-مداومة-رفع-اليدين-والدعاء-بعد-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المداومة على رفع اليدين والدعاء بعد الفريضة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2877,"question":"الدعاء بعد الفريضة؟","title":"حكم الدعاء بعد الفريضة","answer":"الجواب: إذا دعا بينه وبين نفسه بعد السلام أو بعد الذكر لا بأس، بينه وبين نفسه بعد الذكر.","link":"https://binbaz.org.sa/fatwas/23032/حكم-الدعاء-بعد-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء بعد الفريضة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2878,"question":"بالنسبة للدعاء الأفضل: في أثناء السُّنَّة أو بعد الانتهاء من السُّنَّة؟","title":"ما المواضع الأفضل للدعاء في الصلاة؟","answer":"الجواب: الدعاء في السجود هذا الأفضل، في السجود وفي آخر الصلاة قبل أن يسلّم، ما هو بعد السلام، قبل أن يسلم، هذا الأفضل والأقرب للإجابة، وفي حال السجود كذلك، يقول ﷺ: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء، ويقول ﷺ: أما الركوع فعظّموا فيه الرب، وأما السجود فاجتهدوا في الدعاء، فقَمِن أن يستجاب لكم يعني حَرِيٌّ أن يستجاب لكم، ويقول ﷺ: إذا فرغ أحدكم من التشهد الأخير فليستعذ بالله من أربع، ويقول في حديث ابن مسعود: إذا فرغ من التشهد ليتخير من الدعاء أعجبه إليه ثم يدعو يعني قبل أن يسلّم، هذا هو الأفضل.","link":"https://binbaz.org.sa/fatwas/23033/ما-المواضع-الافضل-للدعاء-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مواضع الدعاء في الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2879,"question":"مَن يستعين بالأذكار فيصير مع أي موضوع؟","title":"حكم الاستعانة بالأذكار في كل وقت وأمر","answer":"الجواب: عون له في كل خير، الذكر عون له في كل خير، الله جل وعلا أوصى بالذكر وحرّض عليه  وحذّر أن يكون العبد من الغافلين وَاذْكُرْ رَبَّكَ فِي نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْآصَالِ وَلَا تَكُنْ مِنَ الْغَافِلِينَ [الأعراف:205]، وقال تعالى: أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلَّا كَالأَنْعَامِ بَلْ هُمْ أَضَلُّ سَبِيلًا [الفرقان:44] ما ينبغي للمؤمن أن يتشبه بالأنعام الغافلة، بل يكون لسانه رطبًا بذكر الله؛تسبيح وتهليل وتحميد والاستغفار والدعاء، هكذا المؤمن أوقاته معمورة.\nس: ما في بأس؟\nالشيخ: لا. إذا قالها في حدادته، وإلا نجار في أي عمل، وإلا زرّاع، كلها يعين على الخير، إنْ كان زارع يعينه على زراعته، إنْ كان حداد يعينه على حدادته، نجار يعينه على نجارته، ذكر الله يعينه على الأعمال الصالحة، تعين العبد على الخير وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ [البقرة:45].","link":"https://binbaz.org.sa/fatwas/23034/حكم-الاستعانة-بالاذكار-في-كل-وقت-وامر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستعانة بالأذكار في كل وقت.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2881,"question":"بالنسبة للحصر (في الذِّكر) ألف، ألفين...؟","title":"حكم مَن يُحصي الذكر بألف أو ألفين","answer":"الجواب: يحسب بمليون، يجوز يسبّح بمليون جزاه الله خيرًا، يبغى يسبّح بمليون جزاه الله خيرًا، يقول النبي ﷺ: ولم يأت أحد بأفضل مما جاء به إلا رجل عمل أكثر من عمله. س: في المسجد؟ الشيخ: في المسجد وإلا في البيت وإلا في السماء وإلا في الأرض.","link":"https://binbaz.org.sa/fatwas/23036/حكم-من-يحصي-الذكر-بالف-او-الفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يسبح ويحصر التسبيح بألف أو ألفين.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2889,"question":"التسبيح بالمِسْبَحة؟","title":"ما حكم التسبيح بالمِسْبَحة؟","answer":"الجواب: لا بأس، لكن الأصابع أفضل، لكن إذا سبح بالحصى أو بالمسبحة أو بالنواة أو بغير ذلك؛ فلا بأس، فعله بعض السلف وبعض الصحابيات، لكن الأصابع أفضل كفعل النبي عليه الصلاة والسلام، كونه يَعُدُّ بين أصابعه أفضل.","link":"https://binbaz.org.sa/fatwas/23044/ما-حكم-التسبيح-بالمسبحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التسبيح بالمسبحة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2893,"question":"صيغة \"سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر\" كل منهما خمسة وعشرون: ما ثبت؟","title":"ما صحة التسبيح خمسًا وعشرين بعد الصلاة؟","answer":"الجواب: \"سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر\"، لكن هذه أصح \"سبحان الله، والحمد لله، والله أكبر، ثلاثًا وثلاثين\" أصح في الأحاديث الصحيحة، وتلك نوع، خمس وعشرين.","link":"https://binbaz.org.sa/fatwas/23048/ما-صحة-التسبيح-خمسا-وعشرين-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ثبت التسبيح والتحميد والتهليل كل منها خمسة وعشرون.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2894,"question":"بعض أهل العلم يستدلّ: \"فرجع فقراء المهاجرين...\" أن الأصل عدم رفع الذكر بعد الصلاة؟","title":"حكم رفع الصوت بالذكر بعد الصلاة","answer":"الجواب: لا ما عليه.\nس: الأصل في الذكر أنه...؟\nالشيخ: لا، هذا غلط، هذا من سواليف الصوفية، الأحاديث صريحة في رفع الصوت.","link":"https://binbaz.org.sa/fatwas/23049/حكم-رفع-الصوت-بالذكر-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع الصوت بالذكر بعد الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2896,"question":"هل يلزم ترتيب الأذكار (بعد الصلاة) أو مثلًا الذي يتيسر له؟","title":"حكم الترتيب في الأذكار بعد الصلاة","answer":"الجواب: الذي رتَّبَه النبي ﷺ يرتِّبه، والذي ما رتبه النبي ﷺ ما هو بلازم، هذه الأذكار بعد السلام، والأفضل مثل ما قال ابن الزبير: كان النبي ﷺ إذا سلم قالها بعد أستغفر الله، اللهم أنت السلام، انصرف إلى الناس وقال: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد. هذا ثابت من حديث ابن الزبير ومن حديث المغيرة بن شعبة.  والتسبيح يكون بعد هذا، التسبيح ثلاثًا وثلاثين، والتحميد ثلاثًا وثلاثين، والتكبير ثلاثًا وثلاثين، ويكون تمام المائة لا إله إلا الله أو يكون التكبير أربعًا وثلاثين، كله يقوله بعد السلام، لكن بعد الأذكار كما فعله النبي عليه الصلاة والسلام.\nس: التسبيح والتحميد دُبُر كل صلاة؟\nالشيخ: يعني: بعد السلام، كما في الرواية، المغيرة كان يقول بعد التسليم.\nس: والدعاء: اللهم أعني على ذكرك؟\nالشيخ: هذا قبل التسليم، محل الدعاء قبل التسليم.\nس: لكن الدُّبُر؟\nالشيخ: الدُّبُر آخر شيء، دبر الصلاة آخرها قبل أن يسلم هذا دُبُرها، ويطلق على ما يليها دُبُر، لكن الدُّبُر الحقيقي هو آخرها مثل دُبُر الحيوان، جزء منه، آخرها قبل أن يسلم.\nس: حديث ابن عباس في مسلم: كنا نعرف انقضاء صلاة رسول الله ﷺ بالتكبير؟\nالشيخ: هذا التكبير: الله أكبر ثلاثًا وثلاثين أو أربعًا وثلاثين.\nس: ما هو تكبير خاص؟\nالشيخ: لا، هذا التكبير الذي مع التسبيح والتحميد، اجتمعت أصواتهم وارتفعت فسمعها الناس.\nس: تجتمع أصواتهم في التكبير فقط؟\nالشيخ: تجتمع أصواتهم في التكبير وغيره وفي التسبيح، لكن في التكبير؛ لأنه خاتمة، التكبير هو الخاتمة، ترتفع عنده الأصوات سبحان الله والحمد لله والله أكبر.","link":"https://binbaz.org.sa/fatwas/23051/حكم-الترتيب-في-الاذكار-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الترتيب في الأذكار.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2900,"question":"معنى سُبُّوحٌ قُدُّوسٌ؟","title":"ما معنى \"سُبُّوحٌ قُدُّوسٌ..\"؟","answer":"الجواب: يعني: أنت السُبُّوحُ القُدُّوسُ، يعني: المُنَزَّه عن كل عيب. سُبُّوحٌ قُدُّوسٌ يعني: مُنَزَّه من كل عيب. أو معناها: أقدسك وأسبحك. المعنى متقارب.\nس: هي صيغ مبالغة؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/23055/ما-معنى-سبوح-قدوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى سبوح قدوس.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2901,"question":"بعضهم في الدعاء في رمضان يدعو يقول: اللهم اجعلنا من الباء بركة، ومن الراء رحمة، وهكذا على الحروف؟","title":"حكم الدعاء بما يوافق بدايات الحروف","answer":"الجواب: لا، ما له أصل، هذا ما أعرف له أصلًا، يدعو بدعوات من دون الكلام هذا.","link":"https://binbaz.org.sa/fatwas/23056/حكم-الدعاء-بما-يوافق-بدايات-الحروف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعاء على الحروف.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2902,"question":"هل التسبيح بعد صلاة الفجر حتى طلوع الشمس كما جاء في الآية أفضل، أم قراءة القرآن؟ وما هو أفضل وقت لحفظ القرآن؟ وكيف الطريقة؟","title":"هل التسبيح بعد الفجر أفضل أم التلاوة؟","answer":"الجواب: العناية بالتسبيح وبالأذكار الشرعية أفضل؛ حتى يؤدي كل عبادة في وقتها، في آخر النهار، أو في أول الليل، في أول الصباح، كونه يعتني بالأذكار الشرعية والدعوات هذا أفضل، وإن قرأ فلا بأس، لكن إذا تحرّى الأذكار الشرعية فكل شيء في محله.  مثل ما أنه في الركوع يقول: سبحان ربي العظيم، ما يدعو، يقول: سبحان ربي العظيم، ويقول: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي. وبين السجدتين: ربي اغفر لي، ربي اغفر لي، يدعو. كل شيء في محله هو المشروع، وإذا أكثر من الدعاء وأكثر من التسبيح والتهليل وتعظيم الرب والإكثار من الدعوات المشروعة في الصباح والمساء؛ يكون هذا أفضل، وإن قرأ فالقرآن كله خير.","link":"https://binbaz.org.sa/fatwas/23057/هل-التسبيح-بعد-الفجر-افضل-ام-التلاوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسبيح بعد صلاة الفجر حتى طلوع الشمس.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2909,"question":"لو تهاون بالذكر بعد السلام: اللهم أنت السلام ومنك السلام؛ فما ذكره لأنه متهاون، ثم ذكره بعد ذلك، هل له أن يقول بعد انصرافه من الصلاة بمدة؟","title":"هل يُشرع قضاءُ أذكار الصلاة بعدها بمدة؟","answer":"الجواب: يَسْتَدْرِك من باب الإكثار من الذكر، وإلا السنة فات محلها، لكن يَسْتَدْرِك بالإكثار من الذكر، من ذكر الله جل وعلا؛ لأن الذكر أوقاته ما تُحصى؛ في جميع الليل والنهار .","link":"https://binbaz.org.sa/fatwas/23065/هل-يشرع-قضاء-اذكار-الصلاة-بعدها-بمدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تهاون بالذكر بعد السلام فهل له أن يأتي به بعد الصلاة بمدة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2915,"question":"في كتاب فتح المجيد في إبطال السحر أنه يأخذ سبع ورقات من سدر أخضر فيدقه بين حجرين ثم يضربه بالماء، ويقرأ فيه آية الكرسي والقوافل. ما المقصود بالقوافل؟","title":"ما السُّوَرُ المسمّاةُ بالقواقل؟","answer":"الجواب: قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] و قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] و قُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] هذا من علاج السحر.\nس: تسمى القوافل أو القواقل؟\nالشيخ: القواقل؛ التي أولها قُلْ.","link":"https://binbaz.org.sa/fatwas/23071/ما-السور-المسماة-بالقواقل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إبطال السحر بآية الكرسي والقوافل ما المقصود بالقوافل.mp3","categories":["شروح الحديث","الطب والتداوي"]},{"id":2916,"question":"حديث جويرية (سبحان الله عدد خلقه...) يقال في الصباح والمساء؟","title":"هل الذكر بلفظ \"عدد خلقه..\" عامٌّ لكل وقت؟","answer":"الجواب: في كل وقت، يقال في كل وقت، أينما كنت.\nس: أيقاس على هذا التسبيح سائر أنواع الذكر مثل قول: لا إله إلا الله عدد خلقه الحمد لله عدد خلقه، أو خاص بالتسبيح؟\nالشيخ: عام عام، ما في شيء.\nس: لو قال شخص: لا إله إلا الله عدد خلقه رضا نفسه زنة عرشه؟\nالشيخ: ما في مانع.","link":"https://binbaz.org.sa/fatwas/23072/هل-الذكر-بلفظ-عدد-خلقه-عام-لكل-وقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ذكر الله عام في كل وقت.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2930,"question":"الدعاء : إذا أتى أحدكم أهله... يقوله بينه وبين نفسه؟","title":"هل الذِّكر عند الجِماع يُقال سِرَّا؟","answer":"الجواب: نعم.. تَسْمَع هي، وتقوله هي بَعْد، كُلُّهم: بسم الله، اللهم جنبنا الشيطان وجنب الشيطان ما رزقتنا والمرأة تقول ذلك أيضًا.\nس: هل يأتي به إذا أراد أن يَعْزِل؟\nالشيخ: يأتي به ولو أراد أن يَعْزِل، قد يسبقه المنيُّ ولا يحصل له المطلوب.\nس: لكن ما يقوله بينه وبين نفسه؟\nالشيخ: لاـ يتكلم.","link":"https://binbaz.org.sa/fatwas/23086/هل-الذكر-عند-الجماع-يقال-سرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أتى أحدكم أهله يقول.. هل يقال بينه وبين نفسه.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2932,"question":"هل ورد دعاء للأمان من الحريق؟","title":"هل ورد دعاء معيّن للأمان من الحريق؟","answer":"الجواب: ذكر بعضهم التكبير، لكن ما أعرف فيه أدلة واضحة، لكن ذكر ابن القيم وغيره أنه يُشرع التكبير عند الحريق، وأنه من أسباب إطفاء الحريق، لكن ما يُغني عن الأسباب الحسية من وجود المياه وغير المياه مما يستعان به على إطفاء الحريق، لكن إذا كَبَّر فَحَسَن، الله أكبر الله أكبر، هذا استعانة بتعظيم الله جل وعلا، يعني الله أكبر من هذا الحريق ومن تسبب فيه.\nس: أحسن الله إليك، في المكتبات \"ضوء المصباح في أوراد المساء والصباح\" بقلم الشيخ علي بن محمد هندي، يقول هذا الدعاء: اللهم أنت ربي لا إله إلا أنت عليك، عليك توكلت، وأنت رب العرش العظيم، ما شاء الله كان وما لم يشأ لم يكن، لا حول ولا قوة إلا بالله العلي العظيم، أعلم أن الله على كل شيء قدير، وأن الله قد أحاط بكل شيء علماً، أعوذ بك من شر نفسي ومن شر كل دابة ربي آخذٌ بناصيتها، إن ربي على صراط مستقيم؟\nالشيخ: هذا يُروى عن أبي الدرداء، لكنه ضعيف، يُروى عن أبي الدرداء أنه من أسباب العافية من كل شيء من حريق وغيره، لكن الحديث ضعيف.","link":"https://binbaz.org.sa/fatwas/23088/هل-ورد-دعاء-معين-للامان-من-الحريق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ورد دعاء للأمان من الحريق.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2947,"question":"قول بعض أهل العلم إن الأذكار الواردة في التحرّز من الحيّات والعقارب والشياطين كالسيف في يد المقاتل؛ فإن كان قويًّا نفعت، وإن كان ضعيف الإيمان لم تنفع؟","title":"هل يكون أثر التعوّذات بقدر قوة الداعي؟","answer":"الجواب: تقريب، هذا من باب التقريب، الإنسان يفعلها ويرجو ربه، يعني لا يكون آمنًا ولا يكون ضعيف الإخلاص ولا ضعيف الرجاء، بل يأتي بها، ويعلم أنها أسباب، مع الصدق وحسن الظن بالله ورجائه وتصديق نبيه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23103/هل-يكون-اثر-التعوذات-بقدر-قوة-الداعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستعانة بالأذكار للتحرز من الهوام.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2948,"question":"ما ورد أن النبي ﷺ لما نزلت المعوذتان ترك كل ما كان عليه من التعويذات؟","title":"هل يُكتفى بالمعوذتين عن سائر التعوّذات؟","answer":"الجواب: ما أذكر هذا، لكنه قال ﷺ: ما تعوذ متعوذ بمثلهما، يستحب أن يأتي بهما المؤمن بعد كل صلاة، قل هو الله أحد والمعوذتين، بعد كل صلاة، وعند النوم ثلاث مرات، هذا كله من باب التحرُّزات، مثل ما أن الإنسان يأخذ بالأسباب الأخرى، يغلق  بابه، ويفعل الأسباب الأخرى، ويُسَمّي ويذكر الله ويأكل ويشرب، هذا السبب لا يمنع السبب الآخر مثل ما أنه يُسَمّي ويتعوّذ يأكل أيضًا، الأكل العادة، ويشرب، لا يخلي الأكل والشرب حتى يموت، يفعل الأسباب الأخرى.","link":"https://binbaz.org.sa/fatwas/23104/هل-يكتفى-بالمعوذتين-عن-ساىر-التعوذات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المعوذتين ما تعوذ متعوذ بمثلهما.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2949,"question":"بالنسبة لأذكار المساء تبدأ بعد صلاة العصر مباشرة أو بعد صلاة المغرب مباشرة؟","title":"متى يكون وقت أذكار المساء؟","answer":"الجواب: بعد الزوال مباشرة إلى الليل كله، لكن إذا ختم بها نهاره قبل الغروب يكون أحسن، إذا ختم بها نهاره  قبل الغروب يكون طيبًا، وإلا كُلُّها كل العَشِيّ محل دعاء، العَشِيّ كلها، والآصال كلها بُكْرَةً وَأَصِيلًا، ما قبل الزوال: بُكْرة، وما بعد الزوال: عَشِيّة؛ لأن النهار قسمان: عَشِيّة وبُكْرة.","link":"https://binbaz.org.sa/fatwas/23105/متى-يكون-وقت-اذكار-المساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون وقت أذكار المساء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2951,"question":"إذا كلم أحدا بعد الانتهاء من أذكار النوم؟","title":"حكم من أتى بأذكار النوم ثم قام لحاجة","answer":"الجواب: قام يعني لحاجة؟\nس: لحاجة أو..... أجاب أحدًا.\nالشيخ: إذا قام لحاجة ثم عاد؛ انتهى وحصل المطلوب، والحمد لله، وإن أعاد كله خير، لكن حصل المطلوب عند أول ما يضع جنبه، وإذا قام يقضي حاجة أو يكلم أحدًا إن أعادها فلا بأس، وإلا قد حصل المقصود، والحمد لله.","link":"https://binbaz.org.sa/fatwas/23107/حكم-من-اتى-باذكار-النوم-ثم-قام-لحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أتى بأذكار النوم ثم قام لحاجة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2957,"question":"بالنسبة للحديث قال رسول الله ﷺ لعلي بن أبي طالب وزوجته فاطمة رضي الله عنهما قال ﷺ: إذا أتيتما مضجعكما فسبحا ثلاثا وثلاثين واحمدا الله ثلاثا وثلاثين وكبرا الله أربعا وثلاثين هل مثلًا إذا كان الشخص مرهقًا يقوله... على أساس أنه أوصاهم أن هذا خير لهم من خادم، هل يقول في إرهاق أو كذا؟","title":"هل يُسّنُّ التسبيح والتحميد.. عند الإرهاق؟","answer":"الجواب: يُستحب أن يقوله، ويأتي الحديث في هذا وبيّنّاه الآن يقول: سبحان الله والحمد لله ثلاثًا وثلاثين مرة لكن التكبير يكون أربعًا وثلاثين، الجمع مائة، يستحب عند النوم ويستحب بعد كل صلاة، لكن بعد كل صلاة يختم بالتكبير أو بلا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، كله سنة عند النوم وبعد كل صلاة من الصلوات الخمس.\nس: ولكن ما يستخدمه بعد التعب من العمل أو كذا؟\nالشيخ: يًستحب له أن يسبّح كثيرًا ولو آلاف، يحمد الله ويكبّر، ما في حصر، يسبّح الله ويحمد الله ويكبّره ولو آلاف المرات، كل مرة بعشر حسنات، الحسنة بعشر أمثالها، إذا قالها ألف مرة صار له عشرة آلاف حسنة، وإذا قالها عشرة آلاف مرة صارت له مائة ألف حسنة، وهكذا.","link":"https://binbaz.org.sa/fatwas/23113/هل-يسن-التسبيح-والتحميد-عند-الارهاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وصية النبي لعلي وفاطمة إذا أتيتما مضجعكما فسبحا ثلاثا وثلاثين..mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2958,"question":"بالنسبة للطهارة إذا أراد شخص أن ينام يتطهر في نوم الليل والنهار؟","title":"هل يُستحب الوضوء في نوم الليل والنهار؟","answer":"الجواب: لا، هذا ورد في نوم الليل، إذا أراد أن يبيت.","link":"https://binbaz.org.sa/fatwas/23114/هل-يستحب-الوضوء-في-نوم-الليل-والنهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/الطهارة وقراءة تبارك والسجدة قبل النوم.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2961,"question":"ما المقصود بالمعتدين في الآية ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ۚ إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ؟","title":"ما معنى الاعتداء في {إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ}؟","answer":"الجواب: المعتدي: الذي يدعو بالإثم وقطعية الرحم. وقال بعض السلف: إذا رفع صوته من غير حاجة، لكن الحقيقة أن الاعتداء هو: الذي يدعو بإثم، مثل أن يدعو الله أن يعينه على الزنا أو على السرقة، هذا اعتداء، أو يدعو على الناس بغير حق، يدعو على غيره بغير حق، هذا إثم، أو على أرحامه بغير حق، هذا قطيعة رحم، يقول ﷺ: ما من عبد يدعو الله بدعوة ليس فيها إثم ولا قطيعة رحم إلا أعطاه الله بها إحدى ثلاث... والجهر بالدعاء من غير سبب تَرْكُه أوْلى أحوْط؛ لأن بعض السلف جعله من الاعتداء إذا رفع صوته.  أما إذا كان إمامًا يرفع صوته، مثل: في القنوت: قنوت النوازل وقنوت الوتر للإمام؛ يرفع صوته، وبالخطبة يدعو حتى يُؤمَّن عليه. لكن دعاؤه وحده إذا كان وحده: السُّنَّة السِّر، في سجوده أو في آخر الصلاة أو في غير ذلك الإسرار أفضل، كما قال تعالى: ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً.. [الأعراف:55].","link":"https://binbaz.org.sa/fatwas/23117/ما-معنى-الاعتداء-في-انه-لا-يحب-المعتدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاعتداء في الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2963,"question":"رب اغفر لي وارحمني وعافني في حديث حذيفة أن الرسول ﷺ قالها في صلاة الليل من فعله، هل يُفهم من فعله على الاستحباب؟","title":"موضع دعاء \"اغفر لي وارحمني وعافني\"","answer":"الجواب: نعم، الذي يدعو به النبي ﷺ دعاء طيب.\nس: بين السجدتين؟\nالشيخ: الذي يدعو به النبي عليه الصلاة والسلام دعاء طيب، والسنة تكون مِن فعله وقوله وتقريره عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23119/موضع-دعاء-اغفر-لي-وارحمني-وعافني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء النبي في صلاة الليل هل فعله على الاستحباب.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2967,"question":"هل كان من هَدْي النبي ﷺ التطويل في الدعاء؟ بعض الأئمة يطوّل في الدعاء يقول:  ليتخير مِن الدعاء ما شاء؟","title":"هل مِن هَدْي النبي ﷺ التطويل في الدعاء؟","answer":"الجواب: يكون مثل ما قالت عائشة «كان النبي ﷺ يستحب جوامع الدعاء، ويدع ما سوى ذلك» ويتحرى الدعوات الجامعة في قنوته وفي استسقائه، من غير أن يشقّ على الناس.\nس: الأفضل في السجود؟\nالشيخ: في السجود يدعو، من أسباب الإجابة الدعاء في السجود وفي آخر الصلاة قبل أن يسلم، كل هذا من أوقات الإجابة.","link":"https://binbaz.org.sa/fatwas/23124/هل-من-هدي-النبي-ﷺ-التطويل-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التطويل في الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2968,"question":"الدعاء بقوله: اللهم إني أشكو إليك عُجَرِي وَبُجَرِي؟","title":"حكم الدعاء بقول \"أشكو إليك عُجَرِي وَبُجَرِي\"","answer":"الجواب: معناها صحيح، يعني أغلاطي، يعني اهدني سواء السبيل، لكن يدعو دعوات أوضح: اللهم إني أسألك الهدى والسداد، اللهم أصلح قلبي وعملي، اللهم اكفني شر لساني وشر جوارحي، يدعو دعوات جامعة واضحة، أما العُجَر والبُجَر مجملة، ومعناها يعني أخطائي وأغلاطي، هذا معناه.\nس: منقول عن علي رضي الله عنه؟\nالشيخ: إذا صح عن علي، حتى لو ما صح عن علي، العُجَر والبُجَر معناها الأغلاط والأخطاء.","link":"https://binbaz.org.sa/fatwas/23125/حكم-الدعاء-بقول-اشكو-اليك-عجري-وبجري","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء بعجري وبجري.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2970,"question":"رفع اليدين في الدعاء؟","title":"ما حكم رفع اليدين في الدعاء؟","answer":"الجواب: مستحب، من أسباب الإجابة رفع اليدين، من أسباب الإجابة إلا في المواضع التي ما رفع فيها النبي ﷺ، وُجدت أسبابُها ولم يَرفع فيها فلا يرفع؛ مثل: ما بين السجدتين ما يرفع؛ لأن النبي ﷺ ما رفع، وفي آخر الصلاة قبل أن يسلم لا يرفع، وهكذا بعد الصلوات الخمس في الفرض لا يرفع؛ لأن الرسول ﷺ ما رفع فيها، وخطبة الجمعة، وخطبة الاستسقاء، وخطبة العيد؛ لا يرفع إلا إذا استسقى فيرفع. أما في خطبة العيد وخطبة الجمعة لا يرفع يديه؛ لأن الرسول ﷺ ما رفع إلا إذا استسقى فإنه يرفع يديه، أو استسقى في خطبة الجمعة أو في خطبة العيد يستحب له رفع اليدين كما رفع النبي ﷺ.\nس: يرفع يديه حذو منكبيه؟\nالشيخ: أو حِيَال أذنيه، كله واحد، حِيَال منكبيه هنا أو حيال أذنيه هكذا.\nس: في الدعاء؟\nالشيخ: بالدعاء هكذا قُدّام وجهه، أما في تكبيرة الإحرام وعند الركوع وعند الرفع منه هذا يكون هكذا حيال منكبيه أو حيال أذنيه، أو في الدعاء هكذا قُدّام يديه ويبالغ في الرفع إذا كان في الاستسقاء.\nس: بعض الأئمة يرفع إلى الصدر؟\nالشيخ: الأمر سهل إن شاء الله.","link":"https://binbaz.org.sa/fatwas/23127/ما-حكم-رفع-اليدين-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم رفع اليدين في الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2971,"question":"المسح على الوجه بعد الدعاء؟","title":"هل صح المسح على الوجه بعد الدعاء؟","answer":"الجواب: ورد فيه أحاديث متعددة، قال الحافظ رحمه الله: أنها بمجموعها أحاديث حسنة فإذا مسح فلا بأس، لكن الأفضل تارة وتارة؛ لأن الرسول ﷺ لم يحفظ عنه المسح من جهة فعله، ولكن أرشد إلى ذلك في عدة أحاديث يشدُّ بعضُها بعضًا.","link":"https://binbaz.org.sa/fatwas/23128/هل-صح-المسح-على-الوجه-بعد-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم المسح على الوجه بعد الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2972,"question":"أنواع التجرُّؤ على الله في الدعاء؟","title":"ما أنواع التعدي والتجاوز في الدعاء؟","answer":"الجواب: التعدي كونه يدعو بإثم يقول: اللهم يسر لي الزنا، أو يسر لي شرب الخمر، أو أعِني على قطيعة رحمي، أو على عقوق والدي، أو أعِني على ترك الصلاة، يعني يأتي بمنكر، يسأل ربه منكرًا.\nس: مسألة يعني لا يستحقها، مثل أن يقول: اللهم اجعلني في منزلة  الصالحين، أو منزلة الرسول ﷺ، هذا من أنواع الجرأة، أحسن الله إليك؟\nالشيخ: فإذا سأل يسأل الهداية، جزءٌ من  هذا يسأل الهداية حتى يعمل أعمال الصالحين.\nس: لكن لو دعا اللهم اجعلني بمنزلة الرسول ﷺ هذا يكون من الجُرأة؟\nالشيخ: الله أعلم.","link":"https://binbaz.org.sa/fatwas/23129/ما-انواع-التعدي-والتجاوز-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التجرؤ على الله في الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2974,"question":"متى يبدأ دعاء السفر؟","title":"متى يبدأ دعاء السفر؟","answer":"الجواب: مِن عند بيته أو مزرعته حين يركب.","link":"https://binbaz.org.sa/fatwas/23131/متى-يبدا-دعاء-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يبدأ دعاء السفر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2979,"question":"المُصِرُّ على معصيته إذا دعا الله تصيبه إحدى الثلاث ما يستجاب له؟","title":"هل يُستجاب دعاء المُصِرّ على معصيته؟","answer":"الجواب: قد يُستجاب له وقد يُمنع بسبب معصيته، وقد يُستجاب له فضلًا من الله وهو في ساعة ضرورة أو في أوقات الإجابة يستجيب الله دعوته، حتى الكافر قد تُستجاب دعوته.","link":"https://binbaz.org.sa/fatwas/23136/هل-يستجاب-دعاء-المصر-على-معصيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا دعا الله مصرٌ على معصيته.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2981,"question":"نسأل الله العافية في كل أمر؟","title":"هل سؤال الله العافية يشمل كل الأمور؟","answer":"الجواب: في الدنيا والآخرة، وفي كل شيء، اللهم إني أسألك العافية في الدنيا والآخرة، في كل شيء، العافية من جميع الأدواء، من شر الدنيا والآخرة من مرض وغيره.\nس: إذا رأى مُبتلى؟\nالشيخ: بينه وبين نفسه.\nس: يقول: اللهم إني أسألك العافية؟\nالشيخ: نعم، في كل شيء، في كل وقت.\nس: لو سمع خبرًا غير سار يقول: نسأل الله العافية، أو يقول: إنا لله وإنا إليه راجعون؟\nالشيخ: المصائب: إنا لله وإنا إليه راجعون، وسؤال العافية معه عند المصيبة يقول: إنا لله وإنا إليه راجعون، ويقول: اللهم إني أسألك العافية، هذا مع هذا طيب.","link":"https://binbaz.org.sa/fatwas/23138/هل-سوال-الله-العافية-يشمل-كل-الامور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سؤال الله العافية في كل أمر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2982,"question":"لو رأى شخصًا مُبتلى وهو يصلي: هل يدعو برفع البلاء وهو يصلي، يعني يقول: الحمد لله الذي عافاني مما ابتلاه به؟","title":"هل يُقال دعاءُ مَنْ رأى مُبْتلى في الصلاة؟","answer":"الجواب: ما في بأس، في السجود أو في آخر الصلاة، ما في بأس، الدعاء محل السجود، وآخر الصلاة قبل أن يسلم، وفي القنوت.","link":"https://binbaz.org.sa/fatwas/23139/هل-يقال-دعاء-من-راى-مبتلى-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء رفع البلاء وهو يصلي.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2987,"question":"الدعاء بـ\"بسم الله بسم الله بسم الله\" ثلاثًا عند المرض؟","title":"ما الدعاء المشروع عند المرض؟","answer":"الجواب: هذا جاء في حديث في صحيح مسلم، إذا أحس بمرض يضع يده على محل المرض ويقول:  بسم الله ثلاثًا، أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر سبع مرات. هذا رواه مسلم في الصحيح، وهذا من الدعوات الجامعة الطيبة المختصرة.\nس: ويضع يده اليمنى على مكان الألم؟\nالشيخ: يده اليمنى وإلا اليسرى، يضع يده على محل الألم: بسم الله، ثلاثَا، ثم يقول: أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر، سبع مرات.\nس: من دون ما ينفث؟\nالشيخ: ما ذكر النفث.\nس: اليد يضعها مرة واحدة وإلا يرفعها مع كل؟\nالشيخ: لا، يخليها عليه، وإن حطها وشالها ما في بأس، لكن الحديث يضع يده على محل الألم.","link":"https://binbaz.org.sa/fatwas/23144/ما-الدعاء-المشروع-عند-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء بسم الله ثلاثا عند المرض.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2988,"question":"\"الحمد لله الذي لا يُحْمَد على مكروه سواه\" هذا طيب؟","title":"حكم قول: \"الذي لا يُحْمَد على مكروه سواه\"","answer":"الجواب: ما أعلم فيه شيئًا؛ لأن الإنسان قد يصيبه شيء يكرهه، ومع هذا يحمد الله، إذا أصابه مرض أو مصيبة أخرى يحمده يقول: الحمد لله على كل حال، إنا لله وإنا إليه راجعون، هو يحمد على كل شيء  ؛لأنه لا يقضي قضاء إلا فيه الخير والمصلحة.\nس: المعنى صحيح؟\nالشيخ: نعم؛ معناه صحيح.","link":"https://binbaz.org.sa/fatwas/23145/حكم-قول-الذي-لا-يحمد-على-مكروه-سواه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول الحمد لله الذي لا يحمد على مكروه سواه.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2989,"question":"اللهم أعني على ذكرك وشكرك وحسن عبادتك؟","title":"متى يُقال: \"اللهم أعني على ذكرك..\"؟","answer":"الجواب: صحيح، في دُبُر كل صلاة قبل السلام، أفضل قبل السلام.","link":"https://binbaz.org.sa/fatwas/23146/متى-يقال-اللهم-اعني-على-ذكرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يقول اللهم أعني على ذكرك وشكرك وحسن عبادتك.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2990,"question":"الملائكة تُؤَمِّن على الخير فقط؟","title":"هل تُؤَمِّن الملائكة على كل دعاء؟","answer":"الجواب: على كل حال نعم.\nس: لو دعا بإثم؟\nالشيخ: لا؛ لأنها ما تعين على الإثم، الملائكة على الخير.","link":"https://binbaz.org.sa/fatwas/23147/هل-تومن-الملاىكة-على-كل-دعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تأمين الملائكة على الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2991,"question":"كثرة ما يقول الناس: \"لا تنسنا من دعائك\" فيه شيء؟","title":"حكم قول \"لا تنسنا من دعائك\"؟","answer":"الجواب: ما فيه شيء، لكن تركه أحسن؛ لأنه قد يؤذي إخوانه بكثرة الطلب، ولكن إذا فعله بعض الأحيان لا بأس، النبي ﷺ ثبت عنه في الحديث الصحيح رواه مسلم قال: يَقْدُم عليكم رجل من اليمن يقال له أويس القرني، من مراد، كان بارًّا بأمه، وعلامته أنه كان به بَرَص فبرئ إلا موضع درهم فمن لقيه منكم فليطلب منه المغفرة، يعني فليطلب منه الاستغفار له. ويُروى عنه ﷺ أنه لما توجّه عمر للعمرة قال: لا تنسنا يا أخي من دعائك، لكن في سنده بعض المقال اليسير. وحديث أويس في صحيح مسلم. المقصود أن كون الإنسان يدعو لأخيه المسلم أو لإخوانه أو لجلسائه أو زملائه، كله طيب، والحمد لله، وهو من باب الإحسان، والله يقول: وَأَحْسِنُوا إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ [البقرة:195].","link":"https://binbaz.org.sa/fatwas/23148/حكم-قول-لا-تنسنا-من-دعاىك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول الناس لا تنسانا من دعائك.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":2993,"question":"الدعاء مثلًا للأموات البعيدين له إذا ما كان عنده أقرباء من القريبين له يدعو لهم، هل يكون، أحسن الله إليك، من الدعاء بظهر الغيب، مثلًا جده، جدته؟","title":"هل الدعاء للأموات من الدعاء بظهر الغيب؟","answer":"الجواب: الدعاء للحي والميت كله بظهر الغيب، إذا كانوا ما هم حاضرين هو دعاء بظهر الغيب، سواء أحياء وإلا أموات، هذا دعاء بظهر الغيب، الحي إذا كان ما هو بحاضر، والميت معروف أنه ما هو بحاضر.","link":"https://binbaz.org.sa/fatwas/23150/هل-الدعاء-للاموات-من-الدعاء-بظهر-الغيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء للأموات البعيدين.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3000,"question":"الذي يدعو على نفسه دائمًا ويخشى أولاده أن الله يستجيب دعاءه؟","title":"حكم رجل يدعو على نفسه دائمًا","answer":"الجواب: ينصحونه يقولون: اللهم لا تؤاخذ آباءنا، اللهم لا تستجب دعاءه فيما يضرّنا وما أشبه ذلك، اللهم احفظه من كل سوء، اللهم سدّد دعوته، اللهم سدّد لسانه، يدعون له وينصحونه، والحمد لله، النصيحة تُقبل حتى مِن الولد ومِن البعيد.","link":"https://binbaz.org.sa/fatwas/23158/حكم-رجل-يدعو-على-نفسه-داىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يدعو على نفسه دائما.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3004,"question":"يجوز رفع الكفين أثناء الدعاء؟","title":"حكم رفع الكفين أثناء الدعاء","answer":"الجواب: سُنَّة من أسباب الإجابة.\nس: بعد الفرض وإلا بعد السنة؟\nالشيخ: في كل وقت، إلا فيما يتعلق بالأوقات التي ما رفع فيها النبي ﷺ مثل بعد الفريضة ما يرفع؛ لأن الرسول ﷺ ما رفع فيها، ومثل خطبة الجمعة وخطبة العيد، لا يرفع، إلا إذا استسقى، كان النبي ﷺ يدعو في الخطبة ولا يرفع يديه، خطبة الجمعة والعيد، أما إذا استسقى يرفع يديه في الجمعة أو في الاستسقاء أو في أي مكان، إذا دعا للاستسقاء يطلب الغيث من الله يرفع يديه، هذه السنة، ويرفع الناس أيديهم. وهكذا إذا دعا في غير ذلك؛ دعا في بيته، دعا في سيارته، دعا في طائرته، دعا في مصلاه، يرفع يديه، من أسباب الإجابة إلا المواضع التي ما رفع فيها النبي ﷺ، إذا سلم من الفريضة لا يرفع، ما كان النبي ﷺ يرفع بعد الفريضة؛ لا ظهر ولا عصر ولا مغرب ولا عشاء ولا فجر، ما كان يرفع في هذا عليه الصلاة والسلام، ولا بين السجدتين ولا في آخر الصلاة، ما كان يرفع، يدعو بدون رفع؛ لأن الرسول ﷺ ما كان يرفع.","link":"https://binbaz.org.sa/fatwas/23162/حكم-رفع-الكفين-اثناء-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع الكفين أثناء الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3005,"question":"بالنسبة لدعاء: اللهم إني لا أسألك رد القضاء، ولكن أسألك اللُّطْف فيه؟","title":"حكم قول: \"لا أسألك رد القضاء ولكن اللطف\"","answer":"الجواب: هذا ما له أصل، يدعو: اللهم إني أسألك الخير كله، وأعوذ بك من الشر كله، يسأل ربه الخير، ويستعيذ بالله من الشر، هذا المشروع.\nس: يَحْرُم الدعاءُ بذلك؟\nالشيخ: ..... لا أسألك رد القضاء ولكن أسألك اللُّطْف فيه، هذا ما له أصل، اللهم إني أسألك الخير كله، وأعوذ بك من الشر كله.","link":"https://binbaz.org.sa/fatwas/23163/حكم-قول-لا-اسالك-رد-القضاء-ولكن-اللطف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء اللهم إني لا أسألك رد القضاء ولكن أسألك اللطف فيه.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3007,"question":"الدعاء بقنوت النوازل؟","title":"حكم الدعاء بقنوت النوازل ورفع اليدين","answer":"الجواب: لو دعا به ما في شيء.\nس: هل ورد نص في رفع اليدين أثناء القنوت؟\nالشيخ: نعم ورد في القنوت أنه رفع يديه في قنوت النوازل، وقنوت الوتر مثله، الأصل مثله؛ لأن كله قنوت، كله دعاء، جاء النص بقنوت النوازل، وقنوت الوتر مثله.","link":"https://binbaz.org.sa/fatwas/23165/حكم-الدعاء-بقنوت-النوازل-ورفع-اليدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء بقنوت النوازل، ورفع اليدين أثناء القنوت.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3012,"question":"موضوع سعد (دعائه على من ظلمه) يبين جواز أن الإنسان يدعو على مَنْ ظلمه؟","title":"ما حكم الدعاء على الظالم؟","answer":"الجواب: نعم، مثل ما قال الله جل وعلا: لَا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَنْ ظُلِمَ [النساء:148] المظلوم له أن يدعو على مَن ظلمه ولو جهرة.","link":"https://binbaz.org.sa/fatwas/23170/ما-حكم-الدعاء-على-الظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعاء على الظالم.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3079,"question":"دعاء الرسول ﷺ: اللهم إني عبدك، ابن عبدك، ابن أمتك.. المرأة إذا أرادت أن تدعو بهذا الدعاء ماذا تقول؟","title":"ماذا تقول المرأة في دعاء \"اللهم إني عبدك..\"؟","answer":"الجواب: والله ما أعلم فيه شيئًا، لكن إن قالت: (إني أمَتُك، بِنْتُ عبدك) ما في بأس. وإذا قالت مثل ما قال، هي عبد مثلُ الرجل عبد.","link":"https://binbaz.org.sa/fatwas/23239/ماذا-تقول-المراة-في-دعاء-اللهم-اني-عبدك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء اللهم إني عبدك، ابن عبدك.. إذا أرادت امرأة أن تدعو به ماذا تقول.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3173,"question":"عندنا في السودان النساء يستعملن بعض الطعام كالدقيق في الطِّيب لإزالة ما في الجسم من الروائح، فهل في هذا محذور شرعي؟","title":"حكم استعمال الطعام لإزالة روائح الجسم","answer":"الجواب: ما في شيء.\nالطالب: لا بأس بهذا؟\nالشيخ: من باب الدواء.","link":"https://binbaz.org.sa/fatwas/23336/حكم-استعمال-الطعام-لازالة-رواىح-الجسم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال بعض الطعام لإزالة ما في الجسم من الروائح.mp3","categories":["الطب والتداوي"]},{"id":3175,"question":"أذكار النوم تقال في الليل والنهار؟","title":"هل تُقال أذكار النوم في الليل والنهار؟","answer":"الجواب: ما ورد إلا في نوم الليل.\nس: نوم النهار إذا كان خمس أو ست ساعات ما يذكر أذكار النوم؟\nالشيخ: إذا قالها ما في مانع كلها خير، لكن الذي جاء في نوم الليل، إذا فعل شيئًا في نوم النهار ما في مانع.","link":"https://binbaz.org.sa/fatwas/23338/هل-تقال-اذكار-النوم-في-الليل-والنهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تقال أذكار النوم في الليل والنهار.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3176,"question":"بالنسبة للدعاء لمن لبس ثوبًا جديدًا: لَبِسْتَ جديدًا وعشت حميدًا ومت شهيدًا، صحيح؟","title":"ما الصحيح في دعاء لبس الثوب الجديد؟","answer":"الجواب: ما بلغني، ما أعرف هذا الشيء.\nس: صحة الحديث اللهم لك الحمد أنت كسوتنيه؟\nالشيخ: ما راجعت أسانيده.\nالطالب: هذا السند.\nالشيخ: نعم.\nالطالب: يقول حدثنا عمرو بن عون أنبأنا ابن المبارك عن الجريري عن أبي نضرة عن أبي سعيد الخدري قال: كان رسول الله ﷺ إذا استجد ثوبا سماه باسمه إما قميصا أو عمامة ثم يقول: اللهم لك الحمد أنت كسوتنيه أسألك من خيره وخير ما صنع له وأعوذ بك من شره وشر ما صنع له.\nالشيخ: جيد إسناده جيد، تكلم على عمرو بن عون؟ شيخ المؤلف تكلم عليه؟\nالطالب: معي التقريب.\nالشيخ: عمرو بن عون والباقون معروفون.\nالطالب: عمرو بن عون بن أوس الواسطي، أبو عثمان البزار البصري ثقة ثبت من العاشرة مات سنة25 الجماعة.\nالشيخ: السند صحيح، أقول السند جيد.","link":"https://binbaz.org.sa/fatwas/23339/ما-الصحيح-في-دعاء-لبس-الثوب-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء لبس الثوب الجديد.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3186,"question":"(مَنْ) صلى ركعتين من النافلة يذكر ربه يقول: أستغفر الله استغفر الله ثلاث مرات، ثم يقول: اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام... إلى آخره...؟","title":"هل الأذكار دُبُر الصلوات تشمل النوافل؟","answer":"الجواب: هذا السنة.\nس: حتى في صلاة الليل مثلًا قام..؟\nالشيخ: أي صلاة.\nس: أو في الظهر أو أي وقت؟\nالشيخ: نعم؛ النبي ﷺ كان إذا سلم من صلاته قال: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام. والأصل أن النافلة كالفريضة في هذا إلا بدليل صلوا كما رأيتموني أصلي.","link":"https://binbaz.org.sa/fatwas/23349/هل-الاذكار-دبر-الصلوات-تشمل-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأذكار دبر الصلوات.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3200,"question":"إذا عَطَس الجُنُب فهل يحمد الله جل وعلا؟","title":"ما الذي يُشرع للجُنُب مِن الذِّكْر؟","answer":"الجواب: نعم، يحمد الله إذا عطس وإذا أكل وإذا شرب، ويسبّح ويهلل ويحمد، بس لا يقرأ القرآن حتى يغتسل.","link":"https://binbaz.org.sa/fatwas/23363/ما-الذي-يشرع-للجنب-من-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يحمد الله الجنب إذا عطس.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3202,"question":"الصلاة على النبي ﷺ في المَجْلِس: سرًّا أو جهرًا؟","title":"هل يُصلّى على النبي ﷺ بالمَجْلِس جهرًا؟","answer":"الجواب: يَسْمَعُه مَنْ حَوْله.","link":"https://binbaz.org.sa/fatwas/23365/هل-يصلى-على-النبي-ﷺ-بالمجلس-جهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على النبي في المجلس.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3251,"question":"(ذكر الصباح والمساء) فيه آيات غير المعوذتين ثابتة عن الرسول ﷺ، مثل فسبحان الله حين تمسون وحين تصبحون؟","title":"ما الصحيح من الأذكار في الصباح والمساء؟","answer":"الجواب: هذا ما هو ثابت. لكن جاء في الحديث: سبحان الله وبحمده مائة مرة صباحا، وسبحان الله وبحمده مائة مرة مساء، وفيه كلمتان خفيفتان على اللسان ثقيلتان في الميزان حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم، وفي الصحيحين أن من قال سبحان الله وبحمده حين يمسي مائة مرة حطت خطاياه وإن كانت مثل زَبَد البحر، وفي رواية مسلم من قال حين يصبح أو حين يمسي مائة مرة سبحان الله وبحمده، وفي رواية أبي داود سبحان الله العظيم وبحمده مائة مرة غفر له هذا كله فضل عظيم، فينبغي للمؤمن أن يتحرى هذا.  وكذلك لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، من قالها مائة مرة في يوم كانت له عَدْل عشر رقاب، وكتب الله له مائة حسنة، ومحا عنه مائة سيئة، وكانت له حرزًا من الشيطان يومه ذلك حتى يمسي، ولم يأت أحد بأفضل مما جاء به إلا رجل عمل أكثر من عمله» رواه الشيخان البخاري ومسلم في الصحيحين، فضل عظيم، لكن نعوذ بالله من الكسل.  وعند النوم أيضًا يستحب أن يقول: سبحان الله، والحمد الله، والله أكبر، ثلاثًا وثلاثين مرة عند النوم، وتمام المائة التكبيرة الرابعة والثلاثين؛ يكون التكبير أربعًا وثلاثين، والتسبيح ثلاثًا وثلاثين، والتحميد ثلاثًا وثلاثين، الجميع مائة عند النوم، كما يقولها بعد كل صلاة: سبحان الله، والحمد لله، والله أكبر، ثلاثًا وثلاثين، يختمها بالتكبير أو بقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، هذا خير عظيم وفضل كبير.","link":"https://binbaz.org.sa/fatwas/23415/ما-الصحيح-من-الاذكار-في-الصباح-والمساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فسبحان الله حين تمسون وحين تصبحون.. هل تقال عند أذكار الصباح والمساء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3252,"question":"بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء... يقولها في المساء كل ليلة، المساء يبدأ بعد الغروب أحسن الله إليك؟","title":"متى يُقال\" بسم الله الذي لا يضر مع اسمه..\"؟","answer":"الجواب: إيه نعم، المساء، وإذا قالها آخر النهار كان في المساء كذلك.","link":"https://binbaz.org.sa/fatwas/23416/متى-يقال-بسم-الله-الذي-لا-يضر-مع-اسمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الأذكار ومتى تقال.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3265,"question":"إذا وضعت المرأة عباءتها على كتفها تشبُّها بالرجال هل تكون ملعونة؟","title":"هل تَشَبُّهُ المرأة بالرِّجل في زيّها يُوجِب اللعن؟","answer":"الجواب: يُخشى عليها من هذا؛ لأن هذا من صفة الرجال، وضع العباءة على الكتفين هذا من زي الرجال؛ فلا يجوز للمرأة أن تَتَشَبَّه بهم.\nس: إذا لبست المرأة الكاب وتمشي مثل الرجال تكون ملعونة؟\nالشيخ: إذا كان مِنْ لِبْس الرجال هذه قاعدة: إذا كان من خصائص الرجال؛ تلعن.","link":"https://binbaz.org.sa/fatwas/23429/هل-تشبه-المراة-بالرجل-في-زيها-يوجب-اللعن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تكون المرأة ملعونة إذا وضعت عباءتها على كتفها تشبها.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":3281,"question":"هل مِن علاج الحسد يقول: اللهم زدنا وإياه، أو: اللهم ارزقنا وإياه؟","title":"ما المشروع قولُه لاتِّقاء الحسد؟","answer":"الجواب: بارك الله له، بارك الله فيه، ما شاء الله، هذا هو العلاج وَلَوْلَا إِذْ دَخَلْتَ جَنَّتَكَ قُلْتَ مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ.. [الكهف:39] إذا رأى شيئًا يعجبه يقول: بارك الله فيه، ما شاء الله، لا قوة إلا بالله، هذا مِن العلاج.","link":"https://binbaz.org.sa/fatwas/23445/ما-المشروع-قوله-لاتقاء-الحسد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من علاج الحسد قول اللهم زدنا وإياه، ونحوه.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3287,"question":"هل يجوز أن تضع امرأة على شعرها عسلًا وبيضًا لغرض التجمُّل؟","title":"حكم وضع العسل والبيض على الشعر للتجمُّل","answer":"الجواب: ما أعرف في هذا... تغسل به بذلك، تتجمل تحط عسل، بس كذا؟ ما أدري عنه: إن كان لعلاج فلا بأس، وإن كان فيه امتهان وتلاعب وإسراف ما يجوز، أما إذا كان لعلاج الشعر أو لعلاج جلدة الشعر فيها شيء تحتاج إلى عسل أو تحتاج إلى بيض، مثل ما يفعل فيه أشياء أخرى من باب العلاج؛ لا بأس.\nس: في بعض المحلات يقول هذا صابون بالبيض؟\nالشيخ: يعني فيه خلط؟\nس: نعم مخلوط به.\nالشيخ: ما يضر، مثل ما يعالج بالعجينة، يجعل على الجرح عجينة أو يجعل على الجرح شيئا آخر عند الحاجة، مثل ما يستعمل أيضًا أنواعًا مما يُؤكل لحاجة التداوي، فإذا كان للتداوي أو التجمُّل في شعر مثل: يجعل عسلًا في شعره؛ لأنه ينفع الشعر أو بيضًا ينفع الشعر إذا كان فيهما فائدة فسهل. أما إنْ كان تلاعب بالنعم فلا يجوز، أما إذا كان فيه مصلحة للشعر أو فيه مصلحة لجلدة الشعر، جلدة الرأس، بأنه يخلط بشيء من الصابون أو يخلط بشيء آخر يكون فيه منفعة للرأس؛ ما في بأس.","link":"https://binbaz.org.sa/fatwas/23451/حكم-وضع-العسل-والبيض-على-الشعر-للتجمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وضع العسل والبيض على الشعر للتجمل.mp3","categories":["الطب والتداوي"]},{"id":3288,"question":"امرأة مريضة يُوضع عند رأسها الراديو على إذاعة القرآن وشُفيت، فهل الاعتقاد بأن القرآن هو الذي شفاها جائز؟ وهل هذا الفعل جائز؟","title":"حكم سماع القرآن من المذياع بغرض الشفاء","answer":"الجواب: لا، هذا معناه ترتاح لسماع القرآن، قد يكون ارتياحها لسماع القرآن وفرحها به من أسباب رضا الله ومن أسباب شفائها، وإلا الشفاء ما هو من القرآن، الشفاء من الله جل وعلا، ولكن الله جعل القرآن شفاءً؛ لأنه كلامه  قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]. فالإنسان يتلذّذ به ويقرؤه ويَستشفي به، يعني يعتقد أن الله جعله شفاء، والشفاء من الله، ما هو من نفس الكلام لكن الشفاء من الله، لكن الله جعل تَدَبُّر كتابه وجعل قراءته على المريض وجعل قراءة الدعوات الطيبة على المريض من أسباب الشفاء.","link":"https://binbaz.org.sa/fatwas/23452/حكم-سماع-القران-من-المذياع-بغرض-الشفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وضع الراديو على إذاعة القرآن للمريض بغرض الشفاء.mp3","categories":["الطب والتداوي","القرآن وعلومه"]},{"id":3376,"question":"لكن لها (المرأة) أن تُحِدُّ على غير مَحْرَم، كعالم، أو كرجل له فضل؟","title":"هل يُشْرَعُ للمرأة أن تُحِدُّ على غير مَحْرَم؟","answer":"الجواب: نعم لها أن تُحِدَّ ثلاثًا فأقل؛ لأن الرسول ﷺ نهى أن تُحِدُّ على ميت فوق ثلاث.\nس: لكن على غير قريب مثلا...؟\nالشيخ: الحديث عام أن تُحِدّ على ميت فوق ثلاث.","link":"https://binbaz.org.sa/fatwas/23544/هل-يشرع-للمراة-ان-تحد-على-غير-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تحد المراة على غير محرم.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":3377,"question":"امرأة عندها عيب خلقي في أسنانها فهل لها أن تُسَوِّيَها وتُقَوِّمَها؟","title":"هل يجوز علاج الأسنان بالتقويم والتسوية؟","answer":"الجواب: نعم إذا كان علاج؛ لا بأس، المنهي عنه تفليج الحسن.\nس: السِّنُّ الزائد الذي في اللثة: يجوز نزعه؟\nالشيخ: أي نعم، إذا دعت المصلحة يُنزع، ما هو من التفليج.","link":"https://binbaz.org.sa/fatwas/23545/هل-يجوز-علاج-الاسنان-بالتقويم-والتسوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تسوية الخلقة يعد من التفليج بالحسن.mp3","categories":["الطب والتداوي"]},{"id":3449,"question":"امرأة تستعمل دواء للرأس، وفيه نسبة قليلة من الكحول، فهل يجوز هذا؟","title":"حكم الكحول في الطِّيب والدواء","answer":"الجواب: إذا كان فيه مُسكر ما يَصلح أن تداوَى به: ما أسكر كثيره فقليله حرام.\nس: استعمال هذا الشيء الذي فيه نسبة قليلة من الكحول لو كان خارج البدن، لا يؤكل، لا يشرب؟\nالشيخ: ولو، يُمنع، ظاهر السنة المنع؛ لأن وجوده وسيلة إلى استعماله في الشرب، والأكل.\nس: ما ينسب لشيخ الإسلام -رحمه الله- أنه أجاز هذا؟\nالشيخ: ما يظهر لي، ما كان يُسكر لا يُستعمل، ما كان فيه مُسكر لا يُستعمل، لا دهون، ولا في الرأس، ولا في الأدوية عباد الله تداووا، ولا تداووا بحرام.\nس: كذا الأطياب التي فيها نسبة من الكحول يا شيخ؟\nالشيخ: نعم، فيما بلغنا الكولونيا التي يسمونها الكولونيا فيها إسبرت، ومسكر.\nس: بعضها نسبة قليلة؟\nالشيخ: إذا وجد شيء يُسكر فيُترك، لا يُستعمل إذا عرف أن فيها مُسكر ًا من المسكرات التي يتعاطاها الناس.\nس: قوله ﷺ: وكل مسكر حرام، التداوي، واستعماله؟\nالشيخ: كل مسكر خمر، وكل مسكر حرام ما أسكر كثيره فقليله حرام عام.","link":"https://binbaz.org.sa/fatwas/23624/حكم-الكحول-في-الطيب-والدواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال الطيب والدواء فيه نسبة من الكحول.mp3","categories":["اللباس والزينة","الطب والتداوي"]},{"id":3470,"question":"هل يُشرع الدعاء بالأثر المروي عن عمر ... وهو: اللهم إن كتبتني شقيًّا فامحني واكتبني سعيدًا...؟","title":"حكم دعاء \"اللهم إن كنتَ كتبتني شقيًّا...\"","answer":"الجواب: هذا يُروى عن ابن عمر.\nالطالب: وإن كنت كتبتني سعيدًا...\nالشيخ: هذا يُروى عن ابن عمر. والأظهر أنه لا يشرع هذا الدعاء؛ لأن السعادة، والشقاوة قد كُتبت، وفُرِغ منها، لكن يقول: اللهم اهدني، اللهم أصلح قلبي، اللهم وفقني، وما أشبه ذلك.\nس: أليس هو عن عمر؟\nالشيخ: الذي أعرف أنه عن ابن عمر، لكن إذا كان رواه عن عمر يُمكن، أما الذي نعرفه فعن ابن عمر.","link":"https://binbaz.org.sa/fatwas/23647/حكم-دعاء-اللهم-ان-كنت-كتبتني-شقيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعاء المنسوب لبعض الصحابة اللهم إن كنتَ كتبتني شقيًّا فامحني واكتبني سعيدًا.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3517,"question":"بعض الناس إذا حصل له أمر أو صار له شيء قال: لا حول، ولا يكمل: لا حول ولا قوة إلا بالله؟","title":"حكم قَوْل \"لا حول..\" فقط دون بقيتها","answer":"الجواب: لا، يُكمل، الواجب يقول: لا حول ولا قوة إلا بالله، يقول ﷺ لأبي موسى: ألا أدلك على كنز من كنوز الجنة؟ لا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/23697/حكم-قول-لا-حول-فقط-دون-بقيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يقول لا حول، ولا يكمل لا حول ولا قوة إلا بالله.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3604,"question":"العدد تعبدي أم يمكن أن يزاد عليهن؟","title":"حكم الزيادة في عدد أذكار الصلاة على الوارد","answer":"الجواب: السنة أن يأتي بما قاله النبي ﷺ، وإذا أتى بكثير بعد ذلك ما يخالف، له أن يأتي بآلاف لكن يأتي بهذا العدد بعد كل صلاة عملًا بالسنة.","link":"https://binbaz.org.sa/fatwas/23786/حكم-الزيادة-في-عدد-اذكار-الصلاة-على-الوارد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسبيح والتحميد والتكبير ثلاث وثلاثين هل العدد تعبدي أو يمكن أن يزاد عليه.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3605,"question":"لو بدأ الإمام فقال بعدما سلم: الله أكبر، الله أكبر، ثم استغفر؟","title":"ما الذي يُبدأ به في أذكار الصلاة؟","answer":"الجواب: يبدأ: أستغفر الله أستغفر الله أستغفر، اللهم أنت السلام..، هكذا كان يبدأ النبي عليه الصلاة والسلام.\nس: وقوله في التكبير؟\nالشيخ: التكبير يعني مع سبحان الله، الأحاديث يفسر بعضُها بعضاً.","link":"https://binbaz.org.sa/fatwas/23787/ما-الذي-يبدا-به-في-اذكار-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/في أذكار الصلاة، هل يبدأ بالتكبير أم الاستغفار.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3606,"question":"ما ورد في بعض الآثار يقول: لا إله إلا الله قبل أن يثني رجله عشر مرات، هل معناه يستقبل القبلة ثم ينصرف وإلا بعد الانصراف؟","title":"ما الصحيح في أذكار الصلاة وترتيبها؟","answer":"الجواب: هذا الإمام بعدما يقبل عليهم بوجهه.\nس: يعني يقول \"لا إله الله..\" بعد الاستغفار..؟\nالشيخ: بعد الاستغفار وبعد اللهم أنت السلام، كما في حديث المغيرة وحديث ابن الزبير.\nس: ما ورد أنه يأتي بها ولم يثن رجله عشر مرات يقولها؟\nالشيخ: قبل أن ينهض.\nس: ما ورد أنه يقول: سبحان الله ثلاثًا وثلاثين مرة والحمد لله ثلاثًا وثلاثين مرة والله أكبر ثلاثًا وثلاثين مرة وآخرها لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير؟\nالشيخ: جاء هذا وهذا، كله سنة.","link":"https://binbaz.org.sa/fatwas/23788/ما-الصحيح-في-اذكار-الصلاة-وترتيبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في الأذكار بعد الصلوات.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3662,"question":"بعض النساء إذا اجتمعن في غير وليمة ولا عرس يضربن بالدف؟","title":"حكم ضرب النساء الدف في غير عرس","answer":"الجواب: تركه أحوط، النبي ﷺ سمح مع النساء في قصة البنات يوم العيد وقصة الرُّبَيِّع.","link":"https://binbaz.org.sa/fatwas/23850/حكم-ضرب-النساء-الدف-في-غير-عرس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضرب النساء الدف في غير وليمة ولا عرس.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":3693,"question":"هل للإنسان أن يدعو: اللهم أحيني مسكينًا وأمتني مسكينًا واحشرني في زمرة المساكين؟","title":"درجة حديث \"اللهم أحيني مسكينًا...\"","answer":"الجواب: جاء في حديث وفيه ضعف، الحديث هذا فيه ضعف، ولا يظهر لي مثل هذا؛ لأن الحديث فيه ضعف، ولكن يسأل ربه أن الله يغنيه عن الناس، وأن الله يعينه على أداء الحق؛ لأن الغنى فيه خير عظيم، إذا أعان الله صاحبه فيه خير عظيم: يتصدق، ويحسن، وينفق في سبيل الله، ويواسي الفقراء، ويعمر المساجد، وينفق في الجهاد؛ فالغنى فيه خير، الغني الشاكر أفضل من الفقير الصابر على الصحيح.  ولما ذكر النبي ﷺ أعمال الأغنياء وقال الفقراء: يا رسول الله ذهب أهل الدثور بالأجور يصلون كما نصلي.. الحديث؛ علمهم أن يسبحوا ويكبروا ويحمدوا ثلاثًا وثلاثين بعد كل صلاة، فجاءوا إليه وقالوا: يا رسول الله سمعنا إخواننا أهل الأموال ففعلوا مثلنا؟ فقال: ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم، إذا فعلوا مثل الفقراء وزادوا عليهم في الصدقات والأعمال الطيبة والعتق ونحو ذلك؛ هذا فضل الله، الغني الشاكر له أعمال عظيمة ينفع الله بها الأمة.","link":"https://binbaz.org.sa/fatwas/23882/درجة-حديث-اللهم-احيني-مسكينا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء اللهم أحيني مسكينًا وأمتني مسكينًا واحشرني في زمرة المساكين.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3728,"question":"الآن خروج النساء للأسواق صار شيئًا راتبًا لها؟","title":"حكم كثرة خروج النساء للأسواق","answer":"الجواب: إذا كان لحاجتها لا بأس، أو للبيع والشراء، لا بأس لكن مع التستر.\nس: الخرّاجة الولّاجة التي تخرج دائمًا؟\nالشيخ: إذا كان لحاجتها لا بأس، أما إذا كانت ما هي بحاجة فزوجها يعالج الموضوع.\nس: تخرج للكماليات؟\nالشيخ: ما كلٌّ يصلح أن يشتري الحاجة.\nس: ولا بد من المحرم ياشيخ؟\nالشيخ: لا، المحرم في السفر، ما يحتاج محرم، إذا كانت آمنة ما يحتاج محرم.\nس: ياشيخ بعضهم يخرج مع السائقين؟\nالشيخ: في السيارة لا، لا بدّ أن يكون معها ثالث، أما إن كانت تمشي على رجليها فلا تحتاج محرم، أما السائق لا، لا بدّ يكون معها ثالث، إما امرأة أو رجل أو أكثر من غير ريبة.","link":"https://binbaz.org.sa/fatwas/23920/حكم-كثرة-خروج-النساء-للاسواق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خروج النساء للأسواق.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":3745,"question":"حتى ولو كان وجهها قبيحًا واجب عليها سترها؟","title":"هل يجب ستر وجه المرأة ولو كان قبيحًا؟","answer":"الجواب: ولو، إلا القواعد العواجز اللاتي ليس لهن رغبة في النكاح ولا يتجملن لا بأس، أما غيرهن فقد تكون شابة وكل ساقطة لها لاقطة، قد يُفتن بها بعض الناس، ثم الدمامة ما لها حد مضبوط، قد تكون دميمة عند قوم، وجميلة عند آخرين.","link":"https://binbaz.org.sa/fatwas/23937/هل-يجب-ستر-وجه-المراة-ولو-كان-قبيحا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وجوب ستر المرأة وجهها ولو كان قبيحا.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":3848,"question":"الحجامة سُنة؟","title":"هل الحجامة سُنة؟","answer":"الجواب: ظاهر الحديث أنها سُنة، يقول: إن أمثل ما تداويتم به الحجامة.","link":"https://binbaz.org.sa/fatwas/24057/هل-الحجامة-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في الحجامة.mp3","categories":["الطب والتداوي"]},{"id":3854,"question":"بعض العلماء يقول أن أقواله ﷺ في الطبِّ راجعة للخبرة البشرية وليست لها العصمة؟","title":"هل كلام النبي ﷺ في الطب من الوحي؟","answer":"الجواب: الشيء الذي يجزم به مثل غيره، مثل قوله: فإنَّ فيه سبعة أشفية، هذا حقٌّ جزم به، وما يجزم به فهو من الوحي..... أما لو قال: قيل لي، أو لعله كذا، ولم يجزم به، أو لو فعل كذا لعله يكون كذا؛ ممكن هذا.","link":"https://binbaz.org.sa/fatwas/24065/هل-كلام-النبي-ﷺ-في-الطب-من-الوحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كلام النبي في الطب عصمة، أو للخبرة البشرية.mp3","categories":["الطب والتداوي"]},{"id":3861,"question":"تحديد المؤلف بسبع ورقات؟","title":"ما أصل تحديد سبع ورقات للتداوي من السحر؟","answer":"الجواب: هذا نُقل عن كتب الأقدمين، مجرَّب، والسبع لها مزية مثلما قال النبيُّ ﷺ: أريقوا عليَّ من سبع قربٍ لم تُحل أوكيتُها، سبع تمرات في قصة عجوة المدينة مَن تصبَّح بها، السبع لها شأن.\nس: يجوز بأجر؟\nج: يجوز من باب الدواء.\nس: تكرر أو مرة واحدة؟\nج: الغالب أنَّ مرةً واحدة تكفي، ولكن إذا لم يزل المحذور يُعيد، يُكرر مرتين، ثلاثًا، أكثر حتى يزول البلاء.","link":"https://binbaz.org.sa/fatwas/24072/ما-اصل-تحديد-سبع-ورقات-للتداوي-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تحديد سبع ورقات للتداوي من السحر.mp3","categories":["شروح الحديث","الطب والتداوي"]},{"id":3885,"question":"الدعاء المأثور عند الجديد؟","title":"ما الدعاء المأثور عند لبس الجديد؟","answer":"الجواب: يستحب أن يحمد الله على ما يَسّر يقول: اللهم لك الحمد أنت كسوتنيه، أسألك خيره وخير ما صنع له، وأعوذ بك من شره وشر ما صنع له كان يقول هذا عليه الصلاة والسلام.\nس: تُبلي ويُخْلفُ الله؟\nالشيخ: بهذا المعنى \"أبلي وأخلقي\"، حديث أبي سعيد كان إذا لبس جديدًا قال: اللهم لك الحمد أنت كسوتنيه، أسألك خيره وخير ما صنع له، وأعوذ بك من شره وشر ما صنع له.\nس: يقال بالأمر \"أبلي وأخلقي\"؟\nج: بمعنى الدعاء، مثل اغفر لنا وارحمنا.","link":"https://binbaz.org.sa/fatwas/24101/ما-الدعاء-الماثور-عند-لبس-الجديد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السنة عند لبس الجديد.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":3895,"question":"إذا أراد أن يتوب صاحبُ الوشم؟","title":"ماذا يفعل صاحبُ الوشم إذا أراد أن يتوب؟","answer":"الجواب: التوبة تَجُبُّ ما قبلها، والحمد لله.\nس: إذا ذهب للمستشفى لإزالة هذا الوشم؟\nج: إذا تيسر لا بأس، وإذا ما تيسر ما عليه شيء، إذا فعله أهله به فالإثم على أهله الذين فعلوه به، وإذا كان فعله وهو كبير ثم تاب تاب الله عليه، فإن تيسر بدون مضرَّة إزالته فلا بأس، وإلا يُعفى عنه، التوبة تَجُبُّ ما قبلها، وإن تيسرت إزالته بدون مشقَّةٍ فلا بأس.","link":"https://binbaz.org.sa/fatwas/24111/ماذا-يفعل-صاحب-الوشم-اذا-اراد-ان-يتوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لصاحب الوشم توبة.mp3","categories":["الطب والتداوي"]},{"id":3992,"question":"عند الدعاء يستحب..؟","title":"هل يستحب رفع البصر عند الدعاء؟","answer":"الجواب: الدعاء فيه تفصيل:  إن كان في الصلاة يطرح بصره.  وإن كان في غير الصلاة فالأمر واسع.","link":"https://binbaz.org.sa/fatwas/24223/هل-يستحب-رفع-البصر-عند-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يرفع البصر عند الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4051,"question":"يشاع بين ألسنة الكثير عند طلبة العلم، فضلًا عن العامة في هذا الزمن في كل مكان، وخصوصًا هنا.. يقول: وفَّقنا الله وإياكم إن شاء الله، هل يدخل في هذا؟","title":"حكم الاستثناء والتعليق في الدعاء","answer":"الجواب: يدخل في هذا، ما ينبغي هذا، لا يُعلق، هذه دعوات مطلوبة، والعبد في غاية الحاجة إليها.\nس: بعض الناس يقول: قلتُها تبَرُّكًا؟\nج: لا، ما ينبغي في الدّعاء مثل هذا.","link":"https://binbaz.org.sa/fatwas/24288/حكم-الاستثناء-والتعليق-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاستثناء والتعليق في الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4053,"question":"بعد ما يتكلم الإنسان بالموعظة ويرفع يديه ويستمر على هذا.. المتكلم إذا وعظ الناس؟","title":"هل ورد شيء في الدعاء بعد الموعظة؟","answer":"الجواب: ما نعرف فيه شيئًا، ما نعلم فيه شيئًا.","link":"https://binbaz.org.sa/fatwas/24290/هل-ورد-شيء-في-الدعاء-بعد-الموعظة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع اليدين في الدعاء بعد الموعظة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4055,"question":"الدعاء بطول العمر؟","title":"حكم الدعاء بطول العمر","answer":"الجواب: إنما يُروى عن عمر وجماعةٍ كراهة ذلك، ولكن إذا قيّد في طاعة الله وفي مرضاة الله جاز، الكراهة عند مَن كره: فإنَّ طول العمر قد يكون فيه شرّ، قد يكون فيه خير، فإذا كان في خيرٍ فهو مطلوب: خير الناس مَن طال عمره، وحسن عمله.","link":"https://binbaz.org.sa/fatwas/24292/حكم-الدعاء-بطول-العمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء بطول العمر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4056,"question":"في غير هذا الحديث - فلمّا فرغ من دفنه استقبل القبلة رافعًا يديه- يُشرع استقبالُ القبلة؟","title":"هل تُستقبل القبلة في الدعاء دائمًا؟","answer":"الجواب: الأصل فيه أن استقبال القبلة أفضل عند الدعاء، لكن يجوز الدعاء من غير استقبال القبلة، مثلما دعا النبيُّ ﷺ في الاستسقاء ووجهه إلى الشرق عليه الصلاة والسلام، وجهه إلى غير القبلة، يوم الجمعة استسقى.  كذلك حديث عبدالله بن زيد: أول ما خطب الناس قد استقبلهم، ثم توجَّه بعد ذلك إلى القبلة ليدعو، وهو رافع يديه للاستسقاء عليه الصلاة والسلام، لما خرج إلى المصلَّى جمع بين هذا وهذا: استقبلهم أولًا، ووعظهم، وذكَّرهم، ثم انحرف إلى القبلة ودعا، ثم نزل عليه الصلاة والسلام.\nوفي حديث أنس: أنه استقبل الناس: اللهم أغثنا، اللهم أغثنا، اللهم أغثنا، ولم ينصرف إلى القبلة لما استسقى لهم بعد صلاة الجمعة، كل دعائه وهو مُستقبل الناس، والقبلة خلف ظهره.  وهو يدل على أنَّ هذا جائز، وهذا جائز، إن شاء استقبل القبلة ودعا، وإن شاء استقبل الناس ودعا، وهكذا في الدَّعوات الأخرى في بيته، أو في أي مكانٍ، إن دعا مُستقبلًا القبلة فهو أفضل، وإن دعا إلى جهةٍ أخرى فلا بأس بذلك، الأمر واسعٌ، ليس من جنس الصلاة.\nس: الدعاء للميت بعد الدفن؟\nج: هذا يتوقف على حديث ابن مسعود هذا.\nس: بدون رفع اليدين، هل ورد؟\nج: الذي قبل هذا أنَّ الدعاء للميت بعد دفنه من أي جهةٍ، سواء مُستقبل القبلة، أو غير مُستقبل القبلة، إذا الكل وقفوا عليه ودعوا: هذا من جهة، وهذا من جهة، وهذا من جهة، الأمر فيه واسع.","link":"https://binbaz.org.sa/fatwas/24293/هل-تستقبل-القبلة-في-الدعاء-داىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استقبال القبلة عند الدعاء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4058,"question":"هذه الصلاة تكون في الصلاة المفروضة أو في غيرها أيضًا؟","title":"حكم الصلاة على النبي ﷺ في الصلاة","answer":"الجواب: ظاهر الأحاديث العموم في كل شيءٍ، جاء في بعض الروايات عند ابن خزيمة: \"إذا نحن صلينا عليك في صلاتنا\"، هذا يُفيد أنه يتأكّد في الصلاة أكثر، ولهذا قالوا: السلام قد عرفناه، وهو قولهم: السلام عليك أيها النبي ورحمة الله وبركاته، وفي اللفظ الآخر: وأما السلام فكما قد علمتُم، فهذا يُشعر بأنَّ هذا في الصلاة آكد.","link":"https://binbaz.org.sa/fatwas/24295/حكم-الصلاة-على-النبي-ﷺ-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الصلاة على النبي في الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4059,"question":"هل يُصلى على غير النبي ﷺ؟","title":"هل تجوز الصلاة على غير النبي ﷺ؟","answer":"الجواب: لا بأس، لو قال: اللهم صلِّ على آل أبي فلانٍ، اللهم صلِّ على آل أبي بكر، على آل عمر، على آل فلان. لا بأس، لكن ما يُتّخذ شعارًا عند أهل العلم، ما يكون عادةً، يكون بعض الأحيان، يعني: بخلاف مع الأنبياء، فهو أمرٌ مشروع في حقِّهم، ولا سيما خاتمهم عليه الصلاة والسلام؛ لأن معنى الصلاة الثناء: \"اللهم صلِّ عليه\" يعني: أثنِ عليه، واذكره بالخير عند الملأ الأعلى، صلِّ على فلانٍ، يعني: اذكره بالخير وأثنِ عليه.","link":"https://binbaz.org.sa/fatwas/24296/هل-تجوز-الصلاة-على-غير-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على غير النبي.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4061,"question":"تقديم بعضها على بعض، لو قدمت بعضها على بعض؟","title":"حكم مخالفة الترتيب في دعاء الهم والحزن","answer":"الجواب: ما يضرّ، الحمد لله؛ الأمر في هذا واسع.  الهم فيما يتعلق بالمستقبل، والحزن فيما يتعلق بالماضي.  والعجز عن شيءٍ يضرّه العجز عنه يسأل ربَّه قوته عليه.  والكسل على الأشياء التي هو يستطيعها ولكن يكسل عن فعلها وهي خيرٌ.  والجبن والبخل معروف، الجبن عن الإقدام في الخير، والبخل عن إنفاق المال في وجهه.  وغلبة الدين معروفة، وقهر الرجال معروف.","link":"https://binbaz.org.sa/fatwas/24298/حكم-مخالفة-الترتيب-في-دعاء-الهم-والحزن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء اللهم إني أعوذ بك من الهم والحزن... حكم تقديم بعضها على بعض.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4064,"question":"هذه الدَّعوات تُقال في الصباح والمساء؟","title":"متى يقال دعاء \"أعوذ بك من البخل والجبن..\"؟","answer":"الجواب: جاء في رواية سعد: تُقال في آخر الصلاة: اللهم إني أعوذ بك من البخل والجبن .. إلى آخره، والدعوات إذا أُطلقت يدعو بها الإنسانُ متى شاء: في الصباح، في المساء، في النهار، في كل وقتٍ، الذي أطلقه النبيُّ يُدْعَى به في كل وقتٍ.","link":"https://binbaz.org.sa/fatwas/24302/متى-يقال-دعاء-اعوذ-بك-من-البخل-والجبن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يقال دعاء اللّهم إنّي أعوذ بك من الكسل وأعوذ بك من الجبن..mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4066,"question":"استشكل على الإنسان.. الرسول عليه الصلاة والسلام واستغفاره من الخطايا؛ فماذا يقول في هذه الخطايا؟","title":"معنى دعاء النبي ﷺ أن يُغفر له الخطايا","answer":"الجواب: مثلما قال في دعائه في السجود: اللهم اغفر لي ذنبه كله، دقه وجله، وأوله وآخره، وعلانيته وسره، قد يقع منه الذنبُ، لكن يغفره الله له بسبب إيمانه وتقواه ودعواته العظيمة عليه الصلاة والسلام، وقد أخبره الله أنه غفر له ذنبه، ولكنه عبد شكور يسأل ربه مع ذلك ويضرع إليه.","link":"https://binbaz.org.sa/fatwas/24304/معنى-دعاء-النبي-ﷺ-ان-يغفر-له-الخطايا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء النبي أن يغفر له الخطايا.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4067,"question":"الدعاء بعد هذه الصلاة أو في آخرها؟","title":"متى يكون دعاء الاستخارة؟ وهل يرفع يديه؟","answer":"الجواب: بعد الصلاة؛ لأن النبي قال: يُصلي ركعتين، ثم يقول...\nس: حتى وإن كان وقت نهيٍ؟\nج: لا، في غير وقت النَّهي.\nس: يرفع يديه؟\nج: ما ورد شيء في هذا، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/24305/متى-يكون-دعاء-الاستخارة-وهل-يرفع-يديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون دعاء الاستخارة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4068,"question":"... في الأمر المجزوم به أو في الأمر المتردد فيه؟","title":"فيم تكون الاستخارة؟ وما حكم تكرارها؟","answer":"الجواب: الذي فيه تردد: إما من جهة الطريق إليه، أو عاقبته، أو مصلحته، أو ما أشبه ذلك، يعني: فيه نوع تردد.  أما إذا كان شيء معروف، ما فيه شبهة، ما يحتاج استخارة، ما يستخير، يُصلي الظهر وإلا ما يُصلي الظهر؟ ما يستخير، يُصلي المغرب وإلا ما يُصلي المغرب؟ ما يستخير، يُصلي الضُّحى وإلا ما يُصلي الضحى؟ ما يستخير، يصل رحمه وإلا ما يصل رحمه؟ يبرّ والديه وإلا ما يبرّ هم؟ أمور معروفة من الدين، منتهية.\nس: الأمر هذا يتعلق به سفر كالحج مثلا؟\nج: الحج كذلك، مثل: الحج، قد يكون خوف، إذا كان هناك خوف وخطر يستخير، أما إذا كانت الطريق آمنة، ولا خطر هناك؛ ما في استخارة.\nس: التكرار؟\nج: حتى يُشرح صدرُه، ويستحبّ أن يستشير أيضًا بعد الاستخارة، يستشير مَن يطمئن إليهم: وَأَمْرُهُمْ شُورَى بَيْنَهُمْ [الشورى:38]، وَشَاوِرْهُمْ فِي الْأَمْرِ [آل عمران:159].\nس: يجوز أن يكرر أكثر من مرتين؟\nج: ما في بأس؛ حتى يطمئن وينشرح صدره لأحد الأمرين.","link":"https://binbaz.org.sa/fatwas/24306/فيم-تكون-الاستخارة-وما-حكم-تكرارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء الاستخارة في الأمر المجزوم به أو في الأمر المتردد فيه.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4073,"question":"الدعاء سُنيته مُستمرة إذا نزلت نازلةٌ بالمسلمين؟","title":"ما حكم الدعاء في النوازل؟","answer":"الجواب: نعم، لكن يُبين للعباد أنَّ الأمر بيده ، أنتم عليكم الدعاء، والأمر بيد الله، لا تستطيعون النصر، الأمر بيد الله، العباد عليهم الدعاء، وعليهم الجهاد، وعليهم الإعداد، والتوفيق بيد الله ، ينصر مَن يشاء، ويُؤجل الفتح تارةً، ويُعجِّله تارةً، هو الحكيم العليم .","link":"https://binbaz.org.sa/fatwas/24312/ما-حكم-الدعاء-في-النوازل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء النوازل سُنيته مُستمرة إذا نزلت نازلةٌ بالمسلمين.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4074,"question":"قنوت بعض الناس في الفجر بحجة أنهم في شدة في هذه الأيام؟","title":"حكم المداومة على القنوت","answer":"الجواب: النبي ما كان يُديم القنوت، تارةً وتارةً، تارة يقنت، وتارة يترك، إذا جاءت الحاجات.","link":"https://binbaz.org.sa/fatwas/24313/حكم-المداومة-على-القنوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المداومة على القنوت.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4095,"question":"الاستغفار في السحر سنة؟","title":"هل الاستغفار في السحر سُنّة؟","answer":"الجواب: نعم، الله مدح المؤمنين قال: وَالْمُسْتَغْفِرِينَ بِالْأَسْحَارِ [آل عمران:17]، وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ [الذاريات:18]، والاستغفار مشروع دائمًا في كل وقتٍ.","link":"https://binbaz.org.sa/fatwas/24335/هل-الاستغفار-في-السحر-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من السنة الاستغفار في السحر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4099,"question":"إذا رقى نفسه؟","title":"ما حكم رقية المرء نفسه؟","answer":"الجواب: هذا من المشروع، من السُّنة، من الطبِّ المشروع، كان النبي يرقي نفسَه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24339/ما-حكم-رقية-المرء-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من الطب المشروع أن يرقي الإنسان نفسه.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4126,"question":"هل مباح أن يدعو الإنسان: اللهم اجعلني منهم (السبعين ألفًا)؟","title":"هل يجوز الدعاء بجعله من السبعين ألفًا؟","answer":"الجواب: هذا طيب، مثل ما قال النبي ﷺ لعكاشة: اللهم اجعله منهم؛ لكمال تقواه وكمال إيمانه.","link":"https://binbaz.org.sa/fatwas/24371/هل-يجوز-الدعاء-بجعله-من-السبعين-الفا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الدعاء اللهم اجعلني منهم السبعين ألف.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4127,"question":"س: إذا كان شخص يسأل الرقية.. يُجاب؟","title":"ما الحكم إذا سُئل الإنسان أن يَرقي غيره؟","answer":"الجواب: هو أعلم بنفسه، إذا طلبه هو أعلم بنفسه، والمسؤول مخير إن شاء أجاب وإن شاء ترك... المسؤول مخير إن أجابه فلا بأس، وإن ترك فلا بأس، الأمر واسع، النبي ﷺ أمر أن يُسترقى من العين والحمة؛ فدل ذلك على أن المسؤول يُشرع له الإجابة لينفع أخاه.","link":"https://binbaz.org.sa/fatwas/24373/ما-الحكم-اذا-سىل-الانسان-ان-يرقي-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا سئل الإنسان أن يرقي.mp3","categories":["الطب والتداوي"]},{"id":4130,"question":"هل الأفضل للمريض عدم طلب الرقية؟","title":"هل الأفضل للمريض ترك طلب الرقية؟","answer":"الجواب: الأفضل نعم، إلا إذا دعت الحاجة إلى ذلك، مثلًا ما تيسر له أسباب أخرى، ولهذا أمر النبي أن يسترقى من العين، ومثل الكي تركه أولى، مكروه، وإذا دعت الحاجة إليه زالت الكراهة.","link":"https://binbaz.org.sa/fatwas/24376/هل-الافضل-للمريض-ترك-طلب-الرقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل للمريض عدم طلب الرقية.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4191,"question":"هل للمظلوم أن يدعو على الظالم؟","title":"ما حكم دعاء المظلوم على الظالم؟","answer":"الجواب: لا حرج لَا يُحِبُّ اللَّهُ الْجَهْرَ بِالسُّوءِ مِنَ الْقَوْلِ إِلَّا مَنْ ظُلِمَ [النساء:148] ولهذا دعا سعيد عليها؛ لأنه مظلوم.","link":"https://binbaz.org.sa/fatwas/24448/ما-حكم-دعاء-المظلوم-على-الظالم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للمظلوم أن يدعو على الظالم.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4198,"question":"هل ذكر التهليل (قول: لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء قدير، مائة مرة)  مقيّد بأذكار الصباح والمساء؟","title":"هل ذكر التهليل مقيّد بأذكار الصباح والمساء؟","answer":"الجواب: لا، ما هي مقيّدة، أي وقت، حتى مائة مرة، ما هي مقيّدة، يقولها في أول الصباح أو في أثناء النهار أو في الليل أو في أي وقت، لكن إذا قالها في أول الصباح أحسن له حتى يستقبل نهاره بالسلامة من الشيطان.","link":"https://binbaz.org.sa/fatwas/24457/هل-ذكر-التهليل مقيد-باذكار-الصباح-والمساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول لا إله إلا الله وحده لا شريك له له الملك... هل هي مقيدة بأذكار الصباح والمساء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4199,"question":"س: متى يبدأ دخول وقت المساء؟ ومتى ينتهي؟","title":"متى يبدأ وقت المساء والصباح ومتى ينتهي؟","answer":"الجواب: آخر النهار المساء وأول النهار صباح وإذا قالها بعد المغرب كذلك هو من المساء أيضًا فَسُبْحَانَ اللَّهِ حِينَ تُمْسُونَ وَحِينَ تُصْبِحُونَ [الروم:17] والعشي يسمى مساء، ما بعد الزوال يسمى مساء، ويسمى عشي، ويسمى أصيل.","link":"https://binbaz.org.sa/fatwas/24458/متى-يبدا-وقت-المساء-والصباح-ومتى-ينتهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول سبحان الله والحمد لله ولا إله إلا الله والله أكبر صباحاً ومساءً.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4200,"question":"س: الورد في وقته ما يُقدَّم على القرآن؟","title":"هل تَفْضُل التلاوةُ على الأذكار في كل وقت؟","answer":"الجواب: ما ينافي، الفضل كل شيء يؤتى في وقته أفضل، لو تقرأ القرآن في الركوع فأنت منهي عن ذلك، وهكذا في السجود، وهكذا بين السجدتين. القرآن في محله والأذكار في محلها، كل شيء في محله أفضل، لكن ما ينافي كونه أفضل الكلام، كونه أفضل الكلام ما يقتضي أنه يُقرأ \nفي السجود أو في الركوع أو في محلات ليست محلًّا للقراءة، كل عبادة في محلها.\nس: حديث خير الدعاء دعاء يوم عرفة؟\nالشيخ: هذا فيه ضعف، يؤيد هذا، لكن فيه ضعف.","link":"https://binbaz.org.sa/fatwas/24459/هل-تفضل-التلاوة-على-الاذكار-في-كل-وقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الأدعية وقراءة القرآن والأذكار.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4201,"question":"قول شيخ الإسلام أن تركه أولى.. طلب الدعاء من أخيه؟","title":"هل طلب الدعاء من الغير أفضل أم تركه؟","answer":"الجواب: الذي يظهر أن قول شيخ الإسلام في هذا مرجوح، السنة مقدمة عليه وعلى غيره، السنة صريحة بهذا، فإن قوله: \"إذا دعا لأخيه الملك الموكل يقول ولك بمثل\" مما يشعر الرغبة في هذا الشيء... حديث صريح وهو صحيح رواه مسلم في الصحيح، وحديث عمر صريح وإن كان فيه مقال لكن له شواهد في المعنى. وهو إحسان لأخيه، لكن بعض الناس قد يكثر من هذا، بعض الناس ينبغي له ألا يكثر، بعضهم كلما لقيك يقول كلما شافك يقول: لا تنسني من دعائك، كل ساعة كل ساعة، ترك هذا أوْلى، في بعض الأوقات يعني في أوقات غير متكررة، يكون بين وقت وآخر، لا يلح دائمًا في ذلك؛ لأن هذا قد يثقل على النفوس.  لكن إذا كان فعله بعض الأحيان أو عند طول الغربة أو طول الغيبة أو نحو هذا؛ لعل هذا يكون أوْلى من الإكثار.\nس: أو في السفر لأنه موعود بالإجابة\nالشيخ: المهم عدم الإكثار؛ لأن الإكثار قد يؤذي قد يشق على الناس.\nس: قوله: \"ثم سلوا لي الوسيلة والفضيلة\" ما فيه جواز  طلب الدعاء من الأدنى؟\nالشيخ: كذلك، هذا شاهد للمقام، أحسنت، وهو أفضل الخلق.","link":"https://binbaz.org.sa/fatwas/24461/هل-طلب-الدعاء-من-الغير-افضل-ام-تركه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/توجيه قول شيخ الإسلام في طلب الدعاء من الغير.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4202,"question":"س: هل الدعاء بظهر الغيب بخير أو شر..؟","title":"حكم الدعاء على الغير بالشر بالغيب والشهادة","answer":"الجواب: إذا دعا لأخيه بالشر: يكون داعيًا لأخيه أو داعيًا على أخيه؟! إذا دعا عليه فما هو بداعٍ له، داعٍ عليه. ما يصلح، ما يجوز،  لا يجوز الدعاء على أخيه..... إذا كانت قصاصاً لا بأس، إذا قال أخوه له: قاتلك الله، فقال: قاتلك الله أنت، هذا قصاص لا بأس، لا يزيد بس عليها، النبي ﷺ قال: المستبان ما قالا فعلى البادئ ما لم يعتد المظلوم إذا قال: قاتلك الله، فقال: قاتلك الله ولعنك الله؛ يكون زائدًا عليه في الثانية، الأولى قصاص، والثانية ظلم، أو قال: قاتلك الله، كررها، التكرار غلط، أما إذا قال مثلما قال فقط، قال: أخزاك الله، قال: بل أنت أخزاك الله، أو: قاتلك الله، قال: بل أنت قاتلك الله؛ هذا قصاص، وإن زاد فهو يكون ظالمًا.....\nالدعاء عليه سواء بالغيب أو بالشهادة كله منكر لا يجوز، إلا من باب القصاص.","link":"https://binbaz.org.sa/fatwas/24462/حكم-الدعاء-على-الغير-بالشر-بالغيب-والشهادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعاء على الغير بالشر.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4228,"question":"السبب في عدم قراءة النبي ﷺ على أم المؤمنين عائشة وأمره لها بالاسترقاء؟","title":"ما سبب أمر النبي ﷺ لعائشة بالاسترقاء؟","answer":"الجواب: كأنه للحاجة، احتاجت للاسترقاء فأمرها أن تسترقي، وهكذا أم أولاد جعفر أسماء بنت عميس أمرها أن تسترقي لأولاد جعفر. س: يعني لم يقرأ عليها هو ﷺ؟ ج: لعله شغل عن ذلك، أو لأسباب أخرى.","link":"https://binbaz.org.sa/fatwas/24495/ما-سبب-امر-النبي-ﷺ-لعاىشة-بالاسترقاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سبب أمر النبي لأم المؤمنين عائشة بالاسترقاء.mp3","categories":["الطب والتداوي","شروح الحديث"]},{"id":4230,"question":"أمثلة الحاجات التي يجوز للإنسان أن يكتوي فيها أو يسترقي فيها؟","title":"ما الأحوال التي يجوز فيها الاسترقاء والاكتواء؟","answer":"الجواب: الأمراض التي تصيب الإنسان، أقول أنواع الأمراض.","link":"https://binbaz.org.sa/fatwas/24497/ما-الاحوال-التي-يجوز-فيها-الاسترقاء-والاكتواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما هي الأمور التي يجوز للإنسان أن يكتوي فيها.mp3","categories":["الطب والتداوي","شروح الحديث"]},{"id":4247,"question":"إذا كانت التميمة شيئًا من القرآن هل يكون من الشرك؟","title":"ها تجوز التميمة من القرآن؟","answer":"الجواب: ولو، الصحيح أنها لا  تُعَلَّق حتى من القرآن.\nس: يكون من الشرك؟\nج: الصحيح أنه من الشرك الأصغر، التعليق بعض الفقهاء بعض السلف أجازها إن كانت من القرآن، والأحاديث عامة: تعم القرآن وغيره، تعم التمائم كلها.","link":"https://binbaz.org.sa/fatwas/24516/ها-تجوز-التميمة-من-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التميمة من القرآن.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4248,"question":"هناك دليل يجوِّز للإنسان أن يكتب شيئًا من القرآن ويمسحه ويشربه؟","title":"حكم كتابة شيء من القرآن ومسحه وشربه","answer":"الجواب: هذا فعله السلف، يسمونه الرقية في صحن أو ورقة من الزعفران ويغسل، فعله بعض السلف، ذكره ابن القيم عن كثير من السلف الصالح أنه ينفع بإذن الله، يكتب آيات بالزعفران أو الأدعية ثم يغسلها ويشربها.\nس: يعني من يفعل هذا لا يُنكر عليه؟\nج: لا حرج؛ لأنه ما هو تعليق، شُرب.","link":"https://binbaz.org.sa/fatwas/24518/حكم-كتابة-شيء-من-القران-ومسحه-وشربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدليل على كتابة شيء من القرآن ومسحه وشربه.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4250,"question":"من يتعلّقون بهذه الأشياء تعليق التمائم وغيرها إذا إنسان نصحهم وذكرهم يقولون: هذه الآيات نزلت في المشركين في عهد النبي ﷺ أما نحن مسلمون؟","title":"هل النهي عن التمائم خاص بالمشركين؟","answer":"الجواب: الرسول ﷺ نهى عن هذا، الرسول قال: من تعلق تميمة فلا أتم الله له، نهى الله عن هذا وقال: لا تزيدك إلا وهنا قال لعمران وقال: من تعلق تميمة فقد أشرك، يبين له الأحاديث، أن هذه التعليقات تصرف القلوب عن الله، تصرف القلوب إلى المخلوقات.\nس: الآيات عامة تشملهم وغيرهم؟\nج: نعم، حسب ما جاء في النصوص. أما الأدوية النافعة والأسباب الشرعية فلا بأس بها، مثل ما يأكل الإنسان ويشرب، ومثل ما يلبس في الشتاء الشيء الدافي، وفي الصيف الشيء الخفيف، ومثل ما يتروّح بالمروحة.","link":"https://binbaz.org.sa/fatwas/24520/هل-النهي-عن-التماىم-خاص-بالمشركين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النهي عن التمائم عام في كل وقت.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4251,"question":"تعليق دعاء السفر في السيارة؟","title":"حكم تعليق دعاء السفر في السيارة","answer":"الجواب: كل هذا ما يصلح، يتكلم بلسانه هو في السفر، ما هو يعلقه، يقرؤه في السفر إذا ركب دابته أو سيارته.","link":"https://binbaz.org.sa/fatwas/24521/حكم-تعليق-دعاء-السفر-في-السيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق دعاء السفر في السيارة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4252,"question":"امرأة أرادت أن تسافر وحدها ما عندها محرم، من بلاد الكفر إلى بلاد الإسلام؟","title":"حكم المحرم للمرأة في سفرها من بلاد الكفر","answer":"الجواب: إذا كانت مهاجرة لا بأس، للضرورة،  مع الناس الثقات.","link":"https://binbaz.org.sa/fatwas/24522/حكم-المحرم-للمراة-في-سفرها-من-بلاد-الكفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/محرم المرأة من بلاد الكفر إلى بلاد الإسلام.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":4253,"question":"هل يجوز للمسلم أن يرقي الكافر؟","title":"هل يجوز للمسلم أن يَرْقِيَ الكافر؟","answer":"الجواب: لا بأس أن يرقيه، مثل ما يعطيه الدواء، إذا كان مستأمنًا له عهده.  أما الحربي لا، أما إذا كان مستأمنًا معاهدًا لا بأس، يرقيه أو يداويه، أو يساعده بشيء من المال لا بأس إذا كان فقيرًا.","link":"https://binbaz.org.sa/fatwas/24523/هل-يجوز-للمسلم-ان-يرقي-الكافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز للمسلم أن يرقي الكافر.mp3","categories":["الطب والتداوي"]},{"id":4255,"question":"الماء الذي يُقرأ فيه، هل ورد فيه شيء؟","title":"هل صح شيء في الماء الذي يُقرأ فيه؟","answer":"الجواب: ورد أن النبي ﷺ قرأ بماء لثابت بن قيس وصبه عليه. رواه أبو داود بإسناد صحيح.\nس: الأفضل أن يقرأ في الماء؟\nج: يقرأ في الماء ويسقيه إياه أو يتروّش به.","link":"https://binbaz.org.sa/fatwas/24525/هل-صح-شيء-في-الماء-الذي-يقرا-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ورد شيء في الماء الذي يقرأ فيه.mp3","categories":["الطب والتداوي"]},{"id":4256,"question":"تعليق السبحة على السيارة هل هو من جنس التمائم؟","title":"هل تعليق السبحة في السيارة يُعَدُّ من التمائم؟","answer":"الجواب: إن كان قصده لهذا ما يجوز، إن كان قصده تعليق تمائم ما يجوز، لدفع البلاء ما يجوز. وإن كان قصده علقها زينة فلا بأس، مثل ما يعلق في الجدران الآيات للذكرى.","link":"https://binbaz.org.sa/fatwas/24526/هل-تعليق-السبحة-في-السيارة-يعد-من-التماىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق السبحة على السيارة.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4257,"question":"ما يسمى \"الحصن الحصين\" الذي يباع في الحج فيه سورة يس، وآية الكرسي، ويحطونها في صندوق أحمر ويبيعونها؟","title":"حكم كتاب \"الحصن\" الذي يباع في الحج","answer":"الجواب: ما يصلح هذا.\nس: وحكم من يبيعها؟\nج: يعلم أنه لا يجوز؛ لأن هذا دعوة إلى التمائم.\nس: وإذا كانوا وافدين ولا معه؟\nج: يعلم يعلم ينصح.\nس: ما تسحب منه؟\nج: بالقوة لا، من باب النصيحة إلا إذا كان الساحب من أهل الأمر مثل الهيئة وأشباهها لأن القوة من غيرهم يسبب مشاكل.","link":"https://binbaz.org.sa/fatwas/24527/حكم-كتاب-الحصن-الذي-يباع-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كتاب الحصن الحصين.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4274,"question":"الكلمات تشمل الكائنة والكلمات كذلك الآيات العامة؟","title":"معنى التعوذ بكلمات الله التامات من شر ما خلق","answer":"الجواب: كلماته الشرعية القرآن، وكلماته الكونية التي يأمر بها سبحانه في التصرف في عباده جل وعلا.\nس: والتعوذ بالكلمات؟\nج: بهذا وهذا، نعم.","link":"https://binbaz.org.sa/fatwas/24544/معنى-التعوذ-بكلمات-الله-التامات-من-شر-ما-خلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العتوذ بأعوذ بكلمات الله التامات من شر ما خلق.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4275,"question":"ما صحة من اقتصر التعوذ بكلمات الله التامات في أذكار المساء فقط دون الصباح؟","title":"هل التعوذ بكلمات الله في أذكار المساء فقط؟","answer":"الجواب: لا، عام في كل وقت، يستعيذ بكلمات الله التامات في كل وقت.","link":"https://binbaz.org.sa/fatwas/24545/هل-التعوذ-بكلمات-الله-في-اذكار-المساء-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من اقتصر في التعوذ بكلمات الله في أذكار المساء فقط دون الصباح.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4333,"question":"يقول بعض القراء: يضع يده على رأس المرأة التي يقرأ عليها، فما حكم ذلك؟","title":"حكم لمس الرجل رأس المرأة في الرقية","answer":"الجواب: إذا كان من وراء حائل ما يضر، إذا كان من وراء حائل لتثبيت القراءة، أما المباشرة لا، إن كان من وراء حائل أو وراء خمار أو وراء العباءة التي تثبت حتى يقرأ عليها لا تحرك رأسها.","link":"https://binbaz.org.sa/fatwas/24608/حكم-لمس-الرجل-راس-المراة-في-الرقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم وضع يد القارئ على رأس المرأة التي يقرأ عليها.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4340,"question":"كتاب الشيخ ابن عثيمين المفيد في شرح كتاب التوحيد يقول: وقد ذكر بعض أهل العلم أن من العلاج أن يطلقها زوجها إن كان محبوسا الزوج عن زوجته، يقول من العلاج: أن يطلقها ثم يراجعها. طبعا الشيخ هنا يقول: لا أدري عن صحته؟","title":"ما علاج من كان محبوسًا عن زوجته؟","answer":"الجواب: والله ما بلغني، ما أعرف له أصلًا، هذا مشهور عندهم، ولكن ما أعرف له أصلًا.  العلاج يعالجها بالدعوات الشرعية والرقية الشرعية ويبشر بالخير إن شاء الله.\nس: مشهور عند من؟\nج: عند العامة.\nس: يطلقها ويراجعها؟\nج: لا، ما له أصل، هذا من كلام العامة الذي ما له أساس، العامة عندهم خرافات كثيرة.","link":"https://binbaz.org.sa/fatwas/24615/ما-علاج-من-كان-محبوسا-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/علاج من كان محبوسًا عن زوجته.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":4351,"question":"المرأة التي تكشف وجهها بعض الأجنبيات هل تنكر عليها؟ وهم يأخذون ببعض أقوال العلماء يقولون في كشف الوجه مسألة خلافية وكذا، هل ينكر عليها؟","title":"كيف تكون النصيحة لمن تكشف وجهها؟","answer":"الجواب: من باب النصيحة.\nس: يعني يقولون نحن نأخذ بقول فلان؟\nج: الله جل وعلا قال: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] وقال: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31] والوجه أعظم الزينة!\nس: هل ينكر عليهن؟\nج: ينكر لكن باللطف، ما هو بالشدة، والنصيحة.\nس: بالنسبة للخلاف في تغطية الوجه للمرأة أيهما أرجح التغطية أم الخلاف؟\nج: الراجح الحجاب بنص القرآن.\nس: بالنسبة للكشف هذا القرآن نسخه، وإلا ماذا يقال؟\nج: الحجاب بيّن القرآن أنه يجب الحجاب، كان أولا النساء يسمح لهن بالكشف، ثم منع الله ذلك، نسخ ذلك، نسخ الكشف وبقي الحجاب.\nس: التغطية للوجوب؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/24627/كيف-تكون-النصيحة-لمن-تكشف-وجهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كشف وجه المرأة، والاحتجاج بأنها مسألة خلافية.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":4354,"question":"بالنسبة للنقاب يا شيخ الذي يظهر العيون إذا كانوا بالغوا فيها هل يمنع؟","title":"حكم التوسع في فتحة العين في نقاب المرأة","answer":"الجواب: النقاب لا بأس به أقره النبي ﷺ.\nس: إذا وسعوا فيها؟\nج: قدر العين أو العينين بس.\nس: بعضهم يوسع إذا يمنع؟\nج: يمنع، قدر العين أو العينين بس من دون إيجاد شيء يفتن الناس.\nس: هل يعتبر ما يسمى \"برقع\" حيث يظهر عينيها وبعض جبهتها؟\nج: البرقع هو النقاب.","link":"https://binbaz.org.sa/fatwas/24631/حكم-التوسع-في-فتحة-العين-في-نقاب-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في نقاب المرأة الذي يظهر منه العينين.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":4399,"question":"هذا رجل ينشرح صدره إذا دعا بهذه الدعوات يقول: أسأل الله بأسمائه الحسنى وصفاته العلا ثم من بعد ذلك أقول: وبحق رسولك، وبحق كل ولي لك، فينشرح صدري، فماذا يدل عليه انشراح الصدر؟ وهل يجوز أن أسأل بحق نبيي ثم ينشرح صدري، وبحق الأولياء؟","title":"هل يجوز الدعاء بقول: \"بحق نبيّي والأولياء\"؟","answer":"الجواب: ما ينبغي السؤال بهذا، وإن كان له تأويل بأن حق الأنبياء وحق الدعاة حقهم أن يثيبهم، والإثابة وصف من أوصافه كما في حديث: بحق السائلين، وحق ممشاي هذا، وهو حديث ضعيف، لكن معناه حقهم الإثابة، وهي وصف من أوصافه جل وعلا، توسل بصفاته ، وحق السائلين الإجابة وصف من صفاته جل وعلا، لكن ترك التوسل بهذا أوْلى، يتوسل بأسمائه الصريحة وصفاته الواضحة، اللهم إني أسألك بأسمائك الحسنى كما قال تعالى: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، أسألك بأنك السميع، بأنك العليم، بأنك الحكيم، أسألك بعلمك الذي وسعت به كل شيء، أسألك بحكمتك، ما فيه بأس.\nس: الصواب الجواز؟\nج: بصفات الله وأسمائه.\nس: لكن سؤاله هذا صوابه الجواز؟\nج: هذا محل نظر، تركه أحوط هذا، وإلا معناه صحيح إذا كان قصده الإجابة والإثابة؛ لأنه وصف من أوصاف الله الإثابة والإجابة، من أوصاف الله وهو يسأل بصفاته جل وعلا، ولهذا جاء في الحديث: اللهم إني أسألك بحق السائلين، وحق ممشاي هذا، وهو حديث ضعيف لكن معناه صحيح لو صح؛ لأن حق السائلين الإجابة، وحق المشي بطاعة الله الإثابة، وهو سبحانه الذي قال: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186] وهو سبحانه يثيب عباده الصالحين ويأجرهم على أعمالهم الطيبة .\nس: منطقته مليئة بالقبور والتعبد؟\nالشيخ: ماذا يقول في سؤاله؟\nس: يقال: سلمك الله الأحوط أنك تترك هذا؟\nالشيخ: ماذا يقول هو في سؤاله؟\nس: نفس السؤال الله يسلمك.\nالشيخ: ماذا يقول أعده؟\nس: يقول سؤالي هو أنه ينشرح صدري إذا قلت: بحق أوليائي، ويقصد أولياءه القبور التي يطاف عليها في بلده؟\nالشيخ: يقول: اللهم إني أسألك؟\nالطالب: نعم.\nالشيخ: أسألك؟\nالطالب: بأسمائك الحسنى وصفاتك العلا.\nالشيخ: بس يقتصر على هذا.\nس: وبحق أوليائك وبحق نبيك.\nالشيخ: لا، يقتصر حتى لا يوهم الناس العامة.\nس: يعني من باب الاحتياط لا الجواز؟\nالشيخ: يقتصر على أسمائه الحسنى وصفاته العلا، هذا أحسن؛ حتى لا يوهمهم أنهم على حق في شركهم.","link":"https://binbaz.org.sa/fatwas/24676/هل-يجوز-الدعاء-بقول-بحق-نبيي-والاولياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز الدعاء بقول بحق نبيي وبحق الأولياء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4430,"question":"بالنسبة لـ\"بسم الله\" داخل الدورة، يُسمِّي أحيانًا؟","title":"حكم التسمية في دورة المياه عند الوضوء","answer":"الجواب: إذا دعت الحاجةُ إلى الوضوء داخل الدورة، فبعض المحلات تكون المغاسلُ داخلًا، فيُسمَّى عندها؛ لأنَّ بعض أهل العلم يرى وجوبها، والوجوب يُزيل الكراهة.","link":"https://binbaz.org.sa/fatwas/24708/حكم-التسمية-في-دورة-المياه-عند-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في ذكر الله في دورة المياه عند الوضوء.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4561,"question":"حبوب منع الحمل؟","title":"ما حكم استعمال حبوب منع الحمل؟","answer":"الجواب: فيها تفصيل: إذا كانت لضرورةٍ فلا بأس، وإلا ينبغي تركها.\nس: ما الضَّرورة؟\nج: مرض، أو تربية الأولاد الصغار إن كثروا عليها، أو ..... يعني هناك آلام.\nس: إذا كان عندها طفلٌ واحدٌ؟\nج: الظاهر ما يُكلّف، ما ينبغي تعاطي الحبوب، يعني إذا كثر الأولاد عليها وتقاربوا فصارت –يعني- تربيتهم تشقّ عليها.\nس: كم؟\nج: الله أعلم، ما في حدّ محدود، لكن المراد يعني مُراعاة .....، ومدته سنة أو سنتين، مدة الرضاع إذا كان ما فيه ضرر، إذا قرر الطبُّ أنَّ ما فيه ضرر.","link":"https://binbaz.org.sa/fatwas/24843/ما-حكم-استعمال-حبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال حبوب منع الحمل.mp3","categories":["تنظيم الحمل وموانعه","الطب والتداوي"]},{"id":4574,"question":"البركة \"وبارك على محمدٍ وعلى آل محمدٍ\"؟","title":"معنى البركة في \"وبارك على محمدٍ..\"","answer":"الجواب: البركة عامَّة: بركة في أعماله، وفي أقواله، وفي ثوابه، وفي كل شيءٍ، البركة عامَّة.","link":"https://binbaz.org.sa/fatwas/24857/معنى-البركة-في-وبارك-على-محمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى البركة في وبارك على محمدٍ...mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4579,"question":"التكبير بعد الصلاة؟","title":"ما معنى \"كنا نعرف انقضاء الصلاة بالتكبير\"؟","answer":"الجواب: جاء مطلقًا في حديث ابن عباس: \"كنا نعرف انقضاء الصلاة بالتكبير\"، ما جاء من فعل النبي ﷺ، إنما جاء في التسبيح: \"سبّح الله ثلاثًا وثلاثين، وحمد الله ثلاثًا وثلاثين، وكبَّر الله ثلاثًا وثلاثين\"، جاء فيها، جاء: \"كنا نعرف انقضاء الصلاة بالتكبير\"، كان الصحابة إذا رفعوا أصواتهم سمعهم مَن كان حول أبواب المساجد، أما المحفوظ عن النبي ﷺ فهو ما سمعتُم الآن.","link":"https://binbaz.org.sa/fatwas/24864/ما-معنى-كنا-نعرف-انقضاء-الصلاة-بالتكبير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التكبير بعد الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4599,"question":"إذا أراد أن يدعو وهو خارج الصلاة.. سجد ليكون أقرب إلى الله؟","title":"هل يشرع أن يسجد من أراد أن يدعو الله؟","answer":"الجواب: يدعو في السجود، الدعاء في السجود مُستحب، من أسباب الإجابة.\nس: خارج الصلاة؟\nج: لا، لا، في الصلاة، لا يُشرع مفردًا، يُشرع في الصلاة، أو لأسبابٍ مثل: سجود الشكر، سجود التلاوة، أما [أن] يتعبد بالسجود مجردًا غير مشروع، هذا المراد بكثرة السجود: كثرة الصلاة، هذا مراد النبيﷺ.","link":"https://binbaz.org.sa/fatwas/24888/هل-يشرع-ان-يسجد-من-اراد-ان-يدعو-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أقرب ما يكون العبد من ربه وهو ساجد، فإن كان خارج الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4640,"question":"مجموعة نساء يخرجن للحجِّ بدون محرمٍ؟","title":"حكم المحرم للمرأة في السفر والحج وغيره","answer":"الجواب: ما يجوز هذا، الأحاديث تعمُّ هذا.\nس: بعض النساء المُدرسات يذهبن إلى الخارج نصف يوم ثم يرجعن؟\nج: الذي يظهر لي أنه ممنوع، ظاهر السنة المنع، لكن بعض العلماء يتساهل في جماعة النساء، لكن ما يظهر لي وجه للتَّساهل في هذا؛ لأنَّ هذا يفتح باب شرٍّ خطر، فالواجب التقيد بالسنة.\nس: يقولون من باب الضَّرورة العلمية؟\nج: أين الضرورة؟! كل بلدٍ يلتمس مدرسوها منها، وإلا يُرافقها وليُّها: أخوها، عمها، زوجها، يصبر.\nس: حتى وإن كان السائقُ معه زوجته؟\nج: ولو معه زوجته، هي ما هي بمحرمٍ لهن.\nس: السفر بالخادمة للحج؟\nج: ولو للحجِّ، شرط وجوبه عليها وجود المحرم؛ لأنَّ الأحاديث عامَّة.\nس: المحرم في السفر بالطائرة؟\nج: والطائرة والسيارة كلها، لا تُسافر في الطائرة ولا في السيارة إلا بمحرمٍ.\nس: إذا كان دون البلوغ؟\nج: لا، المحرم البالغ.\nس: بعض الخادمات يُرسلونها بدون محرمٍ؟\nج: الإثم على مَن أرسلها، ولو خادمة ما تُرسل إلا بمحرمٍ، يُوصلها ويروح.\nس: الصبي المميز؟\nج: لا بد من البلوغ.\nس: لو كان مجنونًا؟\nج: لا، لا بدَّ أن يكون عاقلًا، المجنون يضرُّها ولا ينفعها.","link":"https://binbaz.org.sa/fatwas/24930/حكم-المحرم-للمراة-في-السفر-والحج-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في المحرم للمرأة في السفر والحج وغيره.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":4672,"question":"المرأة التي تخاف على نفسها العادة هل تشترط عند إحرامها؟","title":"هل تشترط المرأة عند إحرامها إن خافت العادة؟","answer":"الجواب: ما أعلم مانعًا، أما في الحجِّ لا؛ لأنها تنتظر؛ لأنَّ الحجَّ لا بد من الطواف فيه. الحيض محل نظر.. ، لكن ليس ببعيدٍ؛ لأنه قد يُعطلها كثيرًا.  قد يُقال بالحج أيضًا إذا كانت جاءت مُتأخرةً أو متقدمةً، يمديها تطهر، لكن قد تأتي متأخرةً وتخشى من التَّعطيل، وتفوت عليها أشياء، المقصود إذا دعت حاجةٌ إلى الاشتراط لا بأس، الأصل الجواز، النبي قال لضباعة وهي مريضة: حُجِّي واشترطي.","link":"https://binbaz.org.sa/fatwas/24964/هل-تشترط-المراة-عند-احرامها-ان-خافت-العادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تشترط المرأة عند إحرامها إن خافت على نفسها العادة.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":4759,"question":"قوله: إجابة الدّعاء قد يكون ضررًا عليه؟","title":"هل يمكن أن تكون إجابة الدّعاء ضررًا على الداعي؟","answer":"قد يسأل الله شيئًا يضرّه؛ قد يسأل الله المالَ الكثير، أو يسأل الله الزوجة الفلانية، وقد يسأل الله بعض الأولاد؛ فيُضرُّ بهذا، لما سبق في علم الله من هؤلاء، ولكن يتحرى الخير، ويسأل ربَّه أن يكون ما أعطاه خيرًا له، لا يتساهل، كم من زوجةٍ أهلكت صاحبَها، كم من ولدٍ أهلك صاحبه، كم من مالٍ هلك به صاحبه، نسأل الله السَّلامة.","link":"https://binbaz.org.sa/fatwas/25118/هل-يمكن-ان-تكون-اجابة-الدعاء-ضررا-على-الداعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى قول الطحاوي إجابة الدّعاء قد يكون ضررًا عليه.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4837,"question":"قول \"بسم الله\" إذا دخل الحمام هل واجب؟","title":"ما حكم قول «بسم الله» عند دخول الحمام؟","answer":"مُستحبّ نعم: بسم الله، اللهم إني أعوذ بك من الخبث والخبائث، وجاء في بعضها: «أعوذ بالله من الرجس النَّجس، الشيطان الرجيم».","link":"https://binbaz.org.sa/fatwas/25271/ما-حكم-قول-بسم-الله-عند-دخول-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول بسم الله إذ دخل الحمام.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4846,"question":"هل يؤخذ من حديث بريدة \"اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوًا أحد\" أن الإنسان لا بأس أن يدعو بآيات قرآنية؟","title":"حكم الدعاء بما يوافق آيات قرآنية؟","answer":"هذا موافق للقرآن، مثل رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ [آل عمران:8]\nس: يعني ما في بأس؟\nج: ما في بأس.","link":"https://binbaz.org.sa/fatwas/25294/حكم-الدعاء-بما-يوافق-ايات-قرانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء بآيات قرآنية.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4849,"question":"الدّعاء بالوفاة إذا خشي على نفسه الشرَّ مُستحبٌّ دائمًا أو عندما يخشى الفتنةَ؟","title":"حكم الدّعاء بالوفاة لمن خشي على نفسه الشرَّ","answer":"يدعو: \"اللهم بعلمك الغيب، وقُدرتك على الخلق، أحيني ما علمتَ الحياة خيرًا، وتوفَّني إذا كانت الوفاةُ خيرًا لي\" إذا قالها... أو قال: \"اللهم أحيني إذا كانت الحياةُ خيرًا\"؛ فلا بأس، النبي رخَّص في هذا وفعله، رخَّص فيه وفعله.","link":"https://binbaz.org.sa/fatwas/25300/حكم-الدعاء-بالوفاة-لمن-خشي-على-نفسه-الشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدّعاء بالوفاة إذا خشي على نفسه الشرَّ.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4873,"question":"هل الحجامة من السُّنة؟","title":"هل الحجامة من السُّنة؟","answer":"نعم، إذا احتاجها، وفي الحديث: إن خير ما تداويتم به الحجامة والسعوط رواه مسلم.\nس: المواضع التي احتجم فيها النبي ﷺ؟\nج: المعروف أنه احتجم في رأسه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/25359/هل-الحجامة-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الحجامة من السنة.mp3","categories":["الطب والتداوي"]},{"id":4962,"question":"بالنسبة للفاتحة، أحسن الله إليك، هل ثبت فيها شيء من أذكار المساء والصباح؟","title":"هل الفاتحة من أذكار المساء والصباح؟","answer":"الجواب: ما أذكر فيها شيئًا ثابتًا.","link":"https://binbaz.org.sa/fatwas/27636/هل-الفاتحة-من-اذكار-المساء-والصباح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الفاتحة من أذكار المساء والصباح؟.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4963,"question":"قراءة (الآيتين) آخر سورة البقرة؟","title":"متى يستحب قراءة الآيتين آخر سورة البقرة؟","answer":"الجواب: في أول الليل، من قالها في أول الليل كفتاه، آيتان من آخر سورة البقرة من قالها في ليلة كفتاه، يقولها في أول الليل أو في أثناء الليل، جاءت في أول الليل، أحسن في أول الليل.\nس: قبل النوم، أحسن الله إليك؟\nج: في أول الليل، قبل النوم، في أول الليل، كونه يبادر بها أوَّل.","link":"https://binbaz.org.sa/fatwas/27635/متى-يستحب-قراءة-الايتين-اخر-سورة-البقرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يستحب قراءة الآيتين آخر سورة البقرة؟.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4974,"question":"قراءة تبارك والسجدة قبل النوم؟","title":"هل يُسَنُّ قراءة تبارك والسجدة قبل النوم؟","answer":"الجواب: ما أحفظ فيها شيئًا، لكن إذا قرأها دائمًا؛ القرآن كله خير، يقرؤه دائمًا.","link":"https://binbaz.org.sa/fatwas/28043/هل-يسن-قراءة-تبارك-والسجدة-قبل-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُسَنُّ قراءة تبارك والسجدة قبل النوم؟.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4977,"question":"أذكار المساء بعد صلاة العصر؟","title":"ما وقت أذكار المساء؟","answer":"الجواب: بعد العصر وبعد المغرب، كلها، الحمد لله.","link":"https://binbaz.org.sa/fatwas/28124/ما-وقت-اذكار-المساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما وقت أذكار المساء؟.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":4980,"question":"ولا يٌقال: يرحمه الله؟","title":"هل يصح قول: يرحمه الله، ويغفر الله له؟","answer":"الجواب: من باب الدعاء ما يخالف، يرحمه الله، ويغفر الله له، من باب قصد الدعاء.","link":"https://binbaz.org.sa/fatwas/28351/هل-يصح-قول-يرحمه-الله-ويغفر-الله-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصح قول يرحمه الله ويغفر الله له.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5011,"question":"سورة الزلزلة هل تُؤثر على حمل مريضةٍ بالمس سحرًا أو حسدًا؟ تقول إن أحدُ القُرَّاء قال: إنها إذا قُرِئَتْ عليها فإنَّها تُؤثِّر على حملها؟","title":"هل صح أن لسورة الزلزلة أثرًا على الحمل؟","answer":"الجواب: لا، ما له أصل هذا، هذه خرافة.","link":"https://binbaz.org.sa/fatwas/28813/هل-صح-ان-لسورة-الزلزلة-اثرا-على-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صح أن لسورة الزلزلة أثرًا على الحمل؟.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":5012,"question":"التَّبَخُّر بالآيات القرآنية؟","title":"ما حكم التَّبَخُّر بالآيات القرآنية؟","answer":"الجواب: لا ما له أصلٌ هذا، فالقراءة تُقرأ، تُنفث على المريض.","link":"https://binbaz.org.sa/fatwas/28814/ما-حكم التبخر-بالايات-القرانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم التبخر بالآيات القرآنية؟.mp3","categories":["الطب والتداوي"]},{"id":5019,"question":"مَن يُشغل الشريطَ في البيت ليطرد الجنَّ، هل يُشرع؟","title":"حكم تشغيل شريط قرآن بالبيت لطرد الجن","answer":"الجواب: ما أعلم فيه شيئًا، ما فيه بأس.","link":"https://binbaz.org.sa/fatwas/28831/حكم-تشغيل-شريط-قران-بالبيت-لطرد-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تشغيل شريط قرآن بالبيت لطرد الجن.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":5056,"question":"يرقي الإنسانُ نفسه أم يطلب من غيره أن يرقيه؟","title":"هل الأفضل أن يرقي الإنسانُ نَفْسَه أم يطلب مِن غيره؟","answer":"الجواب: إن رقى نفسه فطيب، وإن طلبه من غيره فلا بأس، فالنبي ﷺ أمر عائشةَ أن تسترقي، وأمر أم أولاد جعفر أن تسترقي لأولاد جعفر، لا بأس، وإذا رقى نفسَه فالنبي كان يرقي نفسَه عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/29322/هل-الافضل-ان-يرقي-الانسان-نفسه-ام-يطلب-من-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل رقية الإنسان نفسه أم من غيره؟.mp3","categories":["الطب والتداوي"]},{"id":5066,"question":"حتى إذا مر على آية فيها ذكر النبي ﷺ وهو في أثناء الصلاة هل عليه أن يصلي على النبي ﷺ؟","title":"هل يُصلى على النبي أثناء الصلاة؟","answer":"الجواب: نعم، الظاهر تَعُمُّه الأحاديث. \nإلا إذا كان الإمام يجهر ينصت لقراءة إمامه. \nلكن في النافلة إذا وقف الإمام يدعو أو يصلي؛ المأموم مثله.","link":"https://binbaz.org.sa/fatwas/29358/هل-يصلى-على-النبي-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُصلى على النبي صلى الله عليه وسلم أثناء الصلاة.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5084,"question":"ما رأي فضيلتكم في علاج يميت اللذة الجنسية، فقد سمعتُ بعلاج يُدعى الكافور، فما رأي فضيلتكم في ذلك؟ أفيدوني أفادكم الله، وجزاكم خيرًا.","title":"حكم الأدوية التي تقطع اللذة الجنسية","answer":"الجواب: شدة الشهوة وقوتها وخطرها قال فيه النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء فينبغي لك أن تصوم ما تيسر، وتستعين بالله، ثم بالصوم الذي أرشد إليه النبي ﷺ إذا استطعتَ ذلك، فإن لم تستطع فاتصل بالمختصين من الأطباء الذين لهم عناية بهذا الشيء؛ حتى يرشدوك إلى ما يعينك على حفظ نفسك، وعلى كف شهوتك عما حرم الله، هناك أدوية تضعف الشهوة، ولا تقطع الشهوة؛ لكن تضعفها إلى أن تأتي الأسباب التي تعين على قضائها في الحلال، فعليك بسؤال المختصين الذين لهم عناية بهذا الأمر، حتى يرشدوك إلى أسباب تعينك على كبح شهوتك، والحذر من طغيانها؛ بالأدوية النافعة التي لا تقطعها، ولا تضرك؛ ولكن تضعفها في وقت خاص، وفي وقت معين؛ حتى يتيسر لك الزواج، وقضاء الوطر فيما أباحه الله ، والصوم إذا أمكن فهو من أحسن ومن أفضل الدواء الذي أرشد إليه النبي عليه الصلاة والسلام. وهنا نقطة ينبغي أن تُعْلَم، وهي: الزواج الذي أرشد إليه النبي ﷺ، كثير من الشباب يتقاعس عن الزواج، ويُعْرِض عن الزواج، وربما شجعه بعض زملائه على ذلك، تارة بالصبر حتى تنتهي الدراسة، وتارة حتى يجد وظيفة تقوم بحاله، وتارة كذا، وتارة كذا، وهذا خطأ. الواجب البدار بالزواج إذا تيسر ذلك، ولو من طريق أبيك، أو من طريق أخيك الكبير، أو من طريق أمك، أو من أي طريق تصل بها إلى الزواج، بادر إلى الزواج، ولا تنتظر انتهاء الدراسة، ولا تنتظر الوظيفة، ولا تنتظر وجود بيت سكني لك تملكه، ولا غير هذا من الأعذار، بادر بالزواج، والمتزوج يعينه الله، والله يقول : وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ والصَّالِحِينَ مِنْ عِبَادِكُمْ وإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] فجعل النكاح من أسباب الغنى. فعليك بالزواج، والبدار إليه، ولا تؤجل إلى انتهاء الدراسة، أو إلى كذا، أو إلى كذا؛ بل إذا تيسر ذلك، ولو من طريق والدك، أو من طريق أخيك، أو من طريق أمك، أو بأي طريق يحصل لك به ذلك، فلا تتأخر، وبادر، وسارع؛ لأن في هذا مصالح كثيرة منها: 1- غض بصرك. 2- إحصان فرجك. 3- تكثير النسل، وتكثير الأمة. 4- أن الله جلَّ وعَلا سيغنيك بذلك، ويعينك بذلك على مصالح كثيرة. ولا يخفى أيضًا أن الزواج فيه هدوء للنفس، وسكن للنفس، وطمأنينة، فالله جعل المرأة سكنًا للزوج: وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا لِتَسْكُنُوا إِلَيْهَا وجَعَلَ بَيْنَكُمْ مَوَدَّةً ورَحْمَةً [الروم:21] فالأزواج جعلهن الله سكنًا للزوج، وراحة له، وطمأنينة له، فإذا تزوج فقد استعان بشيء جعله الله له عونًا على الطمأنينة، والراحة، وسكن النفس، وراحة البال، فلا تؤخر هذا الشيء الذي جعله الله لك سكنًا، وعونًا على الخير، وسببًا لحمايتك مما حرم الله .","link":"https://binbaz.org.sa/fatwas/29986/حكم-الادوية-التي-تقطع-اللذة-الجنسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 03.mp3","categories":["الطب والتداوي"]},{"id":5144,"question":"أثابكم الله، يقول هذا السَّائل: عندما يكون الطبيبُ في مكان عمله الذي يستوجب منه علاج المسلم وغير المسلم، كالنصارى أو غيرهم مثلًا في حالة الحرب، مع الخوف من هذا النصراني الذي قد يحصل فيما بعد، فما موقف الطبيب المُعالج أمام الله تعالى في علاج هذا الذي يُبغضه الله ورسوله، ويبغض الله ورسوله؟","title":"ما حكم معالجة الطبيب المسلم لمريض كافر؟","answer":"الجواب: الواجب على الطبيب أن يُعالجه كما يُعالج غيره؛ لأنَّ هذا صار في محلِّ الاستئمان، وليس في محلِّ حربٍ، إذا كان تبعنا أو دخل عندنا بالأمان موظفٌ أو طبيبٌ أو مع المُجاهدين أو مع الميلشيات التي تُحارب الآن، فلو جرى عليه شيءٌ لا بدّ أن تُعالجه كما تُعالج المريض المسلم، وتتقي الله في أداء الأمانة. وكونه يُبغضه الله، فهذا إلى الله ، لكن أنت الآن دخل عندك بالأمان، فلا بدّ أن تُعالجه إذا كان مُؤْتَمَنًا، أو مُعاهدًا، أو جاء برسالة أمانٍ، أو جاء طبيبًا، أو لأسبابٍ أخرى، فإن أصابه مرضٌ فعالجه بالأمانة ولا تضرّه بشيءٍ. س: ألا ترون يا سماحة الشيخ أنَّه في مثل هذه الحالة مجال للدعوة الإسلامية؟ الشيخ: زيادة، الدعوة طيبة، فكونه يدعوه إلى الله ويُرَغِّبه في الإسلام هذا طيبٌ، مع العلاج، فلا يَخُن الأمانةَ ويُعالجه بشيءٍ يضرُّه، بل يجب أن ينصح له، وهذا من الدعوة إلى الإسلام، فكونه ينصح له هذا من الدَّعوة إلى الإسلام، ويستشعر النصراني أو غيره أنَّ الإسلام ينصح ويُؤدي الواجب لمَن اؤتُمِنَ عليه، أو صار في أمانته، أو في عهده، أو في ذمَّته.","link":"https://binbaz.org.sa/fatwas/30059/ما-حكم-معالجة-الطبيب-المسلم-لمريض-كافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 80.mp3","categories":["الطب والتداوي","الدعوة والدعاة"]},{"id":5148,"question":"يقول هذا السائل يا سماحة الشيخ: تمرُّ بالأطباء بعضُ الحالات، فعندما يُولد طفلٌ مثلًا قبل موعده في الشهر السادس من الحمل، ونظرًا لأنه تحدث مضاعفات كثيرة طبيًّا إن كان الطفلُ عاش، وذلك بعد قدرة الله  ثم بالجهاز التنفسي، لذا فإنَّ هناك قانونًا طبيًّا يقول: إن كان وزنُ الطفل أقلَّ من 750جم فلا يُعمل له الجهاز التنفسي الذي يكون بفضل الله مساعدًا للطفل على الحياة، بالرغم من المُضاعفات المتوقع حدوثها، فهل يجوز ترك الطفل بدون مساعدات إضافية تُكلِّف المريضَ والطبيبَ الكثير من الجهد والوقت والمال -إذا لزم الأمرُ بالنسبة للمال- مع احتمال كبير في عدم استمرار الطفل في الحياة، بل قد يكون مُعاقًا فيما بعد، أم نُرَكِّب له هذا الجهاز مع ما يحصل له بعد ذلك؟","title":"ما حكم التداوي وتركه لمن حالته متدهورة؟","answer":"الجواب: القاعدة عند أهل العلم: أنَّ العلاج ليس بواجبٍ، بل مُستحبٌّ، فعلاج المرضى مُستحبٌّ وليس بواجبٍ، فكونه يُعالج بجراحةٍ أو بعمليةٍ أو بحبوبٍ أو بحميةٍ، كلها مُستحبَّة، وليست واجبةً، فلو أبى العلاج لا حرج عليه. فإذا رأى الأطباء أنَّ من المصلحة أن يُعالج هذا الطفل فعلوا، وإن رأوا أنَّ المصلحة عدم العلاج تركوا ولا حرج في ذلك، فالحكم يدور مع المصلحة الغالبة، فإن غلب على الظنِّ أن العلاج ينفع فلا بأس، وإن غلب على الظن أنَّه لا ينفع فلا بأس بتركه؛ لأنه ضياع وعدم فائدةٍ وإضاعة للأموال وللأوقات.","link":"https://binbaz.org.sa/fatwas/30063/ما-حكم-التداوي-وتركه-لمن-حالته-متدهورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 84.mp3","categories":["الطب والتداوي"]},{"id":5151,"question":"يقول هذا السائل يا سماحة الشيخ: نحن أطباء ذهبنا إلى الخارج للدراسة والتَّخصص، ودائمًا تُواجهنا مشكلة عند الكشف على النِّساء هناك، وهو عدم وجود المُمرضات التي تُساعدنا عند فحصهنَّ، وذلك بحكم التَّقاليد في تلك البلاد، فما العمل؟ هل يجوز؟ وإذا لم يَجُزْ فما الكفَّارة بعد أن عُدنا إلى بلادنا؟ أفيدونا جزاكم الله خيرًا لنُبرئ ذممنا في ذلك.","title":"حكم الاختلاط لضرورة أو حاجة طبية","answer":"الجواب: إذا دعت الضَّرورةُ للكشف على المرأة جاز في البلاد الإسلامية وفي غيرها، لكن يكون مع الكاشف مُشاركٌ؛ حتى لا يخلو بها، فتكون معه ممرضة، أو طبيبة، أو طبيب إذا لم تتيسّر نساء؛ لأنَّ الرسول ﷺ حرَّم الخلوة بالمرأة، والشيطان حاضرٌ حريصٌ، فيُعالج وينظر إذا دعت الضَّرورةُ ولكن بوجود مُشاركٍ؛ حتى لا تحمله النفسُ الأمَّارةُ بالسوء والشيطان على ما لا يحلّ له: من قبلةٍ، أو جماعٍ، أو غير ذلك. وإذا دعت الضرورة فلا بأس بهذا لكن يكون معه غيره، أما إذا ما دعت الضَّرورة فالمرأة لها طبيبة، والرجل له طبيب، فالنساء للنساء، والرجال للرجال، لكن إذا وقعت واقعةٌ واحتاجت المرأةُ إلى طبيبٍ لعدم وجود متخصصة؛ جاز، أو احتاج الرجلُ إلى طبيبةٍ لعدم وجود متخصص، والطبيبة عندها تخصص؛ جاز عند الضَّرورة، لكن من دون خلوة، فلا بد من عدم الخلوة بوجود ممرضة مع الطبيب أو ممرض حسب الحاجة: فإن كان المريض امرأةً فبوجود امرأة، وإن لم تتيسر امرأةٌ يحضر رجلٌ؛ حتى لا تكون الخلوةُ، وذلك حسب الطاقة والإمكان، فالمقصود ألا يخلو بها.","link":"https://binbaz.org.sa/fatwas/30066/حكم-الاختلاط-لضرورة-او-حاجة-طبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 87.mp3","categories":["الطب والتداوي"]},{"id":5152,"question":"أثابكم الله، يقول هذا السائل يا سماحة الشيخ: كثير من الأدوية التي تُستخدم في الطب مُفترة، وبعضها مسكر، أو كثير منها مسكرة، وهذه الأدوية تُستخدم للآلام والعمليات وغيرها، فهل استخدامها جائز أو تدخل في حكم المحرم من الخمور؟","title":"ما حكم العلاج بالأدوية المُفتِّرة والمُسكرة؟","answer":"الجواب: أما المُخدرة فلا بأس؛ المُفترة والبنج لا بأس بها. أما المُسكرة التي تحصل بها النشوة والسكر فلا يجوز، فالرسول ﷺ قال: كل مُسْكِر خمر، وكل مُسكر حرام، وقال: إنَّ الله لم يجعل شفاءكم فيما حرَّم عليكم، وسأله رجلٌ فقال: يا رسول الله، أصنع الخمر للدواء، فقال: إنها ليست بدواء، ولكنها داء رواه مسلم في \"الصحيح\". فإذا عرف أنه مُسكر فلا يجوز التَّداوي به، أما كونه مُفترًا ويمنع الألم كالبنج فلا بأس؛ لأنَّ هذا يُؤخذ لدفع الآلام ورفعها، وهذا لا بأس به، فهو ينفع المريض. أما كونه يُسكره ويتغيَّر عقله به ويهذي ويتكلم بما لا ينبغي كسائر المُسكرات؛ فلا.","link":"https://binbaz.org.sa/fatwas/30067/ما-حكم-العلاج-بالادوية-المفترة-والمسكرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 88.mp3","categories":["الطب والتداوي"]},{"id":5197,"question":"سماحة الشيخ، في كتابكم \"تحفة الأخيار\" ذكرت أنه يُشرع لكل مسلم أن يقول في صباح كل يومٍ: \"لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير\" في يوم مئة مرة.و هل يجوز أن يقولها أكثر من مئة مرة؟ وهل يجوز أن يقول هذا الذِّكْر في المساء أيضًا؟","title":"حكم ترديد ذكر التهليل أكثر من مئة مرة","answer":"الجواب: نعم، يُشرع الإكثار من ذكر الله في كل وقتٍ، ولو آلاف المرات، لكن هذا الذي قلناه قاله النبيُّ ﷺ، قال النبيُّ ﷺ: مَن قال في يومٍ مئة مرة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير؛ كانت له عدل عشر رقاب -يعني: عدل عشر رقابٍ يعتقها- وكتب الله له مئة حسنة، ومحا عنه مئة سيئة، وكان في حرزٍ من الشيطان في يومه ذلك حتى يُمسي، ولم يأتِ أحدٌ بأفضل مما جاء به، إلَّا رجلٌ عمل أكثر من عمله رواه الشيخان: البخاري ومسلم في \"الصحيحين\". فهذا حديثٌ عظيمٌ، فإذا قاله في أول النهار يكون أكمل؛ حتى يكون في حرزٍ من الشيطان يومه ذلك حتى يُمسي، وإن قالها في الضُّحى أو الظهر أو العصر أو في الليل فكله طيب، ولو قاله آلاف المرات فكله طيب، يقول الله: وَاذْكُرُوا اللَّهَ كَثِيرًا [الجمعة:10]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا  ۝  وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا [الأحزاب:42]، ويقول جلَّ وعلا: إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ إلى أن قال سبحانه: وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا [الأحزاب:35]، فالذكر له شأنٌ عظيمٌ.","link":"https://binbaz.org.sa/fatwas/30141/حكم-ترديد-ذكر-التهليل-اكثر-من-مىة-مرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 170.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5245,"question":"يُقال: إنَّ لكم نظرةً في الحجاب تُخالف البعض من علماء الأمصار، وأنَّكم ترون أنَّ الحجاب يكون كامل المرأة محجبةً، علمًا بأننا قرأنا في بعض الكتب التي ترد من بعض علماء الأمصار الأخرى: أنَّ الوجه ليس بعورةٍ، فهل هذا صحيحٌ أم لا؟","title":"حكم كشف وجه المرأة والرد على من أجازه","answer":"الجواب: الصواب أن الوجه عورة، وأن المرأة عورة كلها، كما قال الله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. كانت في أول الإسلام يُباح لها كشف الوجه والكفّين، وكانت تجلس مع الرجال مكشوفة الوجه، ثم أنزل الله آيةَ الحجاب، ومُنعن من ذلك، ووجب عليهنَّ التَّستر؛ لقوله جلَّ وعلا في سورة الأحزاب: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ، وقال سبحانه: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ الآية [الأحزاب:59]، وقال سبحانه: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31]، والزينة تشمل الوجه، وتشمل الشعور، وتشمل بقية البدن، كلها زينة. والواجب على المرأة الستر والتستُّر عن الأجنبي، ولو أخا زوجها، ولو زوج أختها، عليها أن تتستَّر عن غير محارمها مطلقًا. ومَن قال بأنَّ الوجه ليس بعورةٍ فهو قولٌ غلطٌ ومرجوحٌ، فإنَّ الوجه هو عنوان المرأة، هو زينتها، هو الدال على الجمال أو الدَّمامة، فإذا لم يكن عورة فما العورة؟! وقد ثبت في \"الصحيحين\" من حديث عائشة رضي الله عنها: أنها لما سمعت صفوان بن معطل -في قصة الإفك- لما سمعت صوته قالت: \"خمَّرتُ وجهي، وكان قد رآني قبل الحجاب فعرفني\"، المقصود: أن الشاهد أنها قالت: \"خمرتُ وجهي\"؛ لأنَّها أخبرت أنَّ هذا بعد الحجاب، فالمرأة مأمورة بتخمير الوجه.","link":"https://binbaz.org.sa/fatwas/30656/حكم-كشف-وجه-المراة-والرد-على-من-اجازه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 571.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":5288,"question":"لقد قرأت في كتاب: (وقاية الإنسان من الجن والشيطان) تحت عنوان: كيف تطرد الجن من البيت؟ يقول: إذا تيقنت فعلًا أن البيت فيه جني فتكون طريقة إخراجه كالآتي: تذهب أنت واثنان معك إلى هذا البيت وتقول: أناشدكم بالعهد الذي أخذه عليكم سليمان أن تخرجوا أو ترحلوا من بيتنا، أناشدكم الله أن تخرجوا ولا تؤذوا أحدًا، وتكرر هذا ثلاثة أيام، وإذا استشعرت بعد ذلك بشيء في البيت تحضر ماء في إناء وتضع إصبعك فيه وتقرب فاك منه وتقول: بسم الله آمنا بالله الذي ليس منه شيء يمتنع، وبعزة الله التي لا تضام وسلطان الله المنيع نحتجب، إلى آخر الدعاء، ثم تقرأ سورة الصافات إلى قوله تعالى: فَأَتْبَعَهُ شِهَابٌ ثَاقِبٌ [الصافات: 10] ثم بعد هذا تتبع الماء جوانب الدار فيخرجون منه بإذن الله تعالى، فما الحكم في هذا؟","title":"حكم بعض الأدعية التي تقال لطرد الشيطان","answer":"الجواب: ليس عليه دليل، الرسول ﷺ أرشد إلى ما هو أخصر من هذا قال: يقول الإنسان إذا دخل بيتًا: أعوذ بكلمات الله التامات من شر ما خلق، هكذا يقول ﷺ: من نزل منزلًا فقال: أعوذ بكلمات الله التامات من شر ما خلق؛ لم يضره شيء حتى يرتحل من منزله ذلك فإذا أحس بشيء فليقل هذا ويكرر أعوذ بكلمات الله التامات من شر ما خلق، وهكذا: بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم، ويكثر من قراءة القرآن، ويكفي هذا والحمد لله، هذا هو الذي أرشد إليه النبي عليه الصلاة والسلام وعلمه أمته. وإذا جرب شيء من ملح يُرشُّ به البيت، أو شيء ينفع؛ فلا حرج إنْ جرب شيء ينفع يؤذيهم ويخرجهم ولا محذور فيه فلا بأس؛ لكن الأصل هو ما بيَّن النبي ﷺ وأرشد إليه.[1]","link":"https://binbaz.org.sa/fatwas/30930/حكم-بعض-الادعية-التي-تقال-لطرد-الشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 008.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5313,"question":"قرأت في أحد الكتب في شرح الأربعين النووية كلامًا هذا نصه: اللهم إني كتبتني شقيًا فامحني واكتبني سعيدًا، فما صحة هذا الدعاء؟","title":"ما صحة دعاء \"اللهم إني كتبتني شقيًّا فامحني..\"؟","answer":"الجواب: هذا يُروى عن ابن عمر ولكن ليس له أصل في الأحاديث الصحيحة؛ فإن من كتب شقاؤه مات شقيًّا ومن كتبت سعادته مات سعيدًا، فالله جل وعلا يوفق من كتب سعيدًا بعمله، ومن كتب شقيًّا هُدي لأعمال الشر، قال تعالى: إِنَّ سَعْيَكُمْ لَشَتَّى ۝ فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:10] ويقول النبي ﷺ: اعمَلوا فَكُلٌّ ميسَّرٌ لما خُلِقَ لَهُ، أمَّا أَهْلُ السَّعادةِ فيُيسَّرونَ لعملِ أَهْلِ السَّعادةِ، وأمَّا أَهْلُ الشَّقاوةِ فيُيسَّرونَ لعملِ أَهْلِ الشَّقاوةِ.[1]","link":"https://binbaz.org.sa/fatwas/30970/ما-صحة-دعاء-اللهم-اني-كتبتني-شقيا-فامحني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 032.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5337,"question":"ترد على ألسنة العامة من الناس بعض الألفاظ مثل: يا رب يا ساتر، ويارب يا ستَّار، فهل في ذلك حرج؟","title":"ما حكم قول العامة \"يا رب يا ساتر\"؟","answer":"الجواب: لا أعلم فيه شيء؛ لأن في المعنى: هو الساتر وهو الستار سبحانه، لكن لم يرد في الآيات ولا في الأحاديث اسم الساتر والستّار، لكن هذه الأسماء يُوصف بها من غير أن تُعد في أسمائه كالموجود والشيء والذات، له ذات مقدسة وهو شيء عظيم وهو موجود عظيم له الأسماء الحسنى، لكن لا يعد في أسمائه الذات والموجود والشيء، وهكذا الساتر والستّار لا نعلم فيها حديثًا صحيحًا، لكن ورد (الستّير) (حيِّي ستِّير) بمعنى الستّار وبمعنى الساتر ، لكنها صفة مبالغة.[1]","link":"https://binbaz.org.sa/fatwas/31010/ما-حكم-قول-العامة-يا-رب-يا-ساتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 058.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5344,"question":"ما حكم الكشف على المرأة على الحامل بغرض معرفة نوع الجنين ذكرًا أو أنثى بالأجهزة الحديثة؟ وهل يتعارض ذلك وقوله تعالى: إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ [لقمان: 34]؟","title":"حكم الكشف على الحمل لمعرفة نوع الجنين","answer":"الجواب: لا، لا يتعارض، بعد التخليق لا يتعارض، يطلع عليه المَلَك، والمَلَك يُؤمر: ذكر، أنثى، شقي، سعيد، فالمَلَك يطَّلِع، ما عاد يكون من علم الغيب، قد أطلع الله عليه المَلَك. والأجهزة الحديثة قد يعرفون أنه ذكر أو أنثى، هذا ليس من علم الغيب، علم الغيب قبل ذلك، قبل أن يُخلق.[1]","link":"https://binbaz.org.sa/fatwas/31017/حكم-الكشف-على-الحمل-لمعرفة-نوع-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 065.mp3","categories":["الطب والتداوي"]},{"id":5345,"question":"يقول: عن أبي هريرة ، عن النبي ﷺ قال: مَن قال حين يُصبح وحين يُمسي: سبحان الله وبحمده، مئة مرة، لم يأتِ أحدٌ يوم القيامة بأفضل مما جاء به إلا أحد قال مثلما قال أو زاد عليه، فهل عدد التَّسبيح هنا غير توقيفي على المئة أم ماذا؟","title":"هل العدد في أحاديث الأذكار توقيفي لا يُزاد عليه؟","answer":"الجواب: فيه الفضل العظيم: \"سبحان الله وبحمده\" مئة مرة صباحًا ومساءً من أسباب مغفرة الذنوب، وإذا زاد وأتى بمئات وآلاف صار أجره أعظم، ولكن هذا مع الاستقامة، هذه الفضائل مقيّدة بأداء الفرائض وترك المحارم، كما قال جلَّ وعلا: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31]، ويقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، كفَّارات لما بينهن إذا اجتنب الكبائر، فالفضائل مقيّدة باجتناب الكبائر، ويمحو الله بذلك الصغائر. أما مَن أصرَّ على المعاصي فهو مُتوَعَّد بالنار وإنْ أتى بالتسبيح، وإن أتى بالذكر، هو متوعد بالنار لإصراره على المعاصي، كما قال تعالى: وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ۝ أُولَئِكَ جَزَاؤُهُمْ مَغْفِرَةٌ مِنْ رَبِّهِمْ وَجَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ [آل عمران:135، 136]. فالواجب على العبد أن يحذر ما حرَّم الله، وأن يبتعد عمَّا يُغضب الله عليه، وأن يستمسك بما أوجب الله عليه، وأن يجتهد في ترك ما حرَّم الله عليه، وأن يلزم التوبةَ مما قد سلف، ويُشرع له الاستكثار من التَّسبيح والتهليل والتحميد والتكبير؛ فإن هذا من وسائل المغفرة، ومن وسائل التوفيق.[1]","link":"https://binbaz.org.sa/fatwas/31024/هل-العدد-في-احاديث-الاذكار-توقيفي-لا-يزاد-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 066.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5365,"question":"ما حكم قول الرجل في دعائه: هل في الوجود إله سواك فيُدْعَى؟","title":"حكم الدعاء بـ \"هل في الوجود إله سواك فيُدْعَى\"","answer":"الجواب: ليس في الوجود، ما يقول: هل! ليس في الوجود، على سبيل النَّفي، الاستفهام بمعنى المبالغة بهذه النية، ليس في الوجود، أما على سبيل الشك ما يجوز.[1]","link":"https://binbaz.org.sa/fatwas/31074/حكم-الدعاء-بـ-هل-في-الوجود-اله-سواك-فيدعى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima008.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5407,"question":"هل الأفضل الجهر بالذكر أم الإسرار به؟","title":"هل الأفضل الجهر بالأذكار أم الإسرار؟","answer":"الجواب: يذكر الله ذكرًا يسمعه مَن حوله حتى ينفع نفسه وينفع الناس، إلا في الصلاة، فإذا سلَّم من الصلاة يرفع صوته، كان النبي ﷺ يرفع صوتَه بعد السلام من الصلاة، والصحابة كانوا يرفعون أصواتَهم بعد السلام من الصلاة. أمَّا العادي في بقية الأوقات فيُسمِع نفسه ويُسمِع مَن حوله حتى يُقتدى به، النبي ﷺ كان يذكر الله ويُسمِع الصحابةَ فيقتدون به.[1]","link":"https://binbaz.org.sa/fatwas/31170/هل-الافضل-الجهر-بالاذكار-ام-الاسرار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 023.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5408,"question":"بالنسبة للذكر في الحمامات وفي الخلاء يكون بالقلب أم بالقول؟","title":"حكم الذكر والبسملة في الوضوء عند الخلاء؟","answer":"الجواب: بالقلب. س: وبالقول على الكراهة أو على التَّحريم؟ ج: يُكره كراهة تنزيه. س: والتسمية عند الوضوء؟ ج: إذا دعت الحاجة في الحمام يُسمِّي؛ لأنَّ التسمية واجبة، ما يُخليها من أجل الكراهة.[1]","link":"https://binbaz.org.sa/fatwas/31171/حكم-الذكر-والبسملة-في-الوضوء-عند-الخلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 024.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5409,"question":"بالنسبة للذكر: هل يحصل له الأجر على مَن ذكر الله  وقلبه لاهٍ؟","title":"هل يحصل الأجر لمن ذكر الله وقلبه لاهٍ؟","answer":"الجواب: على حسب حاله، وكلٌّ له حسبه، فإذا اجتمع القلب واللسان تمت المسألة، وإذا كان القلبُ فله نصيبه، وإذا كان اللسان فله نصيبه، وإذا اجتمعت الثلاثةُ: القلب واللسان والجوارح؛ فهذا هو الكمال. س: بالنسبة للأجر المُترتب؟ ج: كلٌّ على قدر حضور قلبه، وعلى قدر عمله. س: مَن قال أذكار الصباح والمساء بقلبٍ غافلٍ هل تنفعه؟ ج: على حسب استحضاره يكون أجره، كلما زاد الاستحضارُ كان الأجرُ أكثر.[1]","link":"https://binbaz.org.sa/fatwas/31172/هل-يحصل-الاجر-لمن-ذكر-الله-وقلبه-لاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 025.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5410,"question":"إذا كان للإنسان وردٌ يوميٌّ بعد الفجر وبعد صلاة المغرب من كتاب الله وسنة رسوله ﷺ، فهل في ذلك محظورٌ ولو لم يرد؟ يعني: زاد على الوارد من كتاب الله والسنة الصحيحة؟","title":"حكم الذكر والدعاء الزائد عن الكتاب والسنة؟","answer":"الجواب: إذا زاد في الأذكار والدعوات فلا بأس، لكن إذا تحرَّى الوارد وأكثر منه يكون أفضل، إلا إذا زاد دعوات من عنده احتاج إليها، أو أتى بكلماتٍ من الذكر ليست منقولةً؛ فلا بأس، مثل: سبحان الله العظيم الجليل القدوس الملك الرحمن، سبحان الله العظيم الشأن، سبحان الله القادر على كل شيء، ولو ما جاء في حديثٍ حتى؛ فلا بأس، فكله تسبيحٌ وتقديسٌ. س: وإذا استعمل هذا الورد اليومي رقيةً؛ فنفعت في أمورٍ كثيرةٍ في الشفاء من بعض الأمراض، فهل يأخذ بها وليس عليه محظور؟ ج: ما في بأس، ما في بأس، ما أعلم فيها بأسًا.[1]","link":"https://binbaz.org.sa/fatwas/31174/حكم-الذكر-والدعاء-الزاىد-عن-الكتاب-والسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 026.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5412,"question":"السجع في الدّعاء؟","title":"ما حكم السجع في الدعاء؟","answer":"الجواب: ما أعلم فيه شيئًا، إذا لم يكن فيه تكلُّف. س: وإذا كان مُتكلِّفًا؟ ج: تركه أوْلى.[1]","link":"https://binbaz.org.sa/fatwas/31179/ما-حكم-السجع-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 028.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5415,"question":"هل الأذكار توقيفية؟","title":"هل الأذكار توقيفية؟ وما أنواع الذكر؟","answer":"الجواب: الأذكار من جهةٍ توقيفية، ومن جهةٍ تُعرَف بالأدلة الشرعية.  فهناك أذكار يُقال فيها: توقيفية، وردت بالنص: كالتسبيح والتهليل والتحميد والتكبير. وهناك أذكار بالتدبر: كخوف الله عندما يقع أمام الإنسان شيءٌ يخشاه، ومثل: رجاء الله، ومثل: الشوق إلى الله، وتذكر عظمته، وتذكر نعمه العظيمة، هذه يحتاج إليها الإنسانُ بحسب تفكيره وتدبره وتعقله وقربه من الله وعدم غفلته. وهكذا الأعمال الصَّالحات التي شرعها الله، والتقرب إليه بها بفعلها كما شرع الله، من صلاةٍ وغيرها، فالعبادات توقيفية، لكن الطرق إليها تختلف.[1]","link":"https://binbaz.org.sa/fatwas/31186/هل-الاذكار-توقيفية-وما-انواع-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 031.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5416,"question":"الصوفية يذكرون الله بالضمير المجرد: هو، هو؟","title":"ما حكم ذكر الله بالضمير المجرد: هو، هو؟","answer":"الجواب: هذه بدعة، ليس من الذكر، مثل: الله، الله، ما هو بذكر.  الذكر: سبحان الله، لا إله إلا الله، كما جاءت به النصوص؛ لأنَّ العبادات توقيفية، لا تكون بالافتراء، لكن الطرق إليها بالتفكير والتَّدبر مشروعة.[1]","link":"https://binbaz.org.sa/fatwas/31187/ما-حكم-ذكر-الله-بالضمير-المجرد-هو-هو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 032.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5418,"question":"شخص يستمع إلى شريط قرآنٍ في السيارة أو إلى محاضرةٍ أو درسٍ، هل تحفّه الملائكة؟","title":"هل تحفّ الملائكة من يستمع إلى القرآن والعلم؟","answer":"الجواب: هذا من ذكر الله لا شكّ، مجالس ذكر لا شكّ، شريط فيه دعوة إلى الله وتعليم وتوجيه يستمع له، أو قارئ يقرأ يستمع له؛ هذا من ذكر الله.[1]","link":"https://binbaz.org.sa/fatwas/31189/هل-تحف-الملاىكة-من-يستمع-الى-القران-والعلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 034.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5420,"question":"ما أفضل الذكر؟","title":"ما أفضل الذكر؟","answer":"الجواب: أفضل الذكر \"لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير\"، مع التسبيح والتحميد والتكبير، يقول ﷺ: أحبُّ الكلام إلى الله أربع: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ويقول: الباقيات الصَّالحات: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، لكن مع الذكر القلبي والجارحي، ومع العمل في طاعة الله وترك معصيته. س: لو لم يذكر إلا \"لا إله إلا الله\" في اليوم فقط؟ ج: يكون طيِّبًا، يقول النبيُّ ﷺ: مَن قال: لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير في اليوم مئة مرة، كانت له عدل عشر رقابٍ -يعني: يُعتقها- وكتب الله له مئة حسنة، ومحا عنه مئة سيئة، وكان في حرزٍ من الشيطان يومه ذلك حتى يُمسي، ولم يأتِ أحدٌ بأفضل مما جاء به إلا رجلٌ عمل أكثر من عمله، فليُكثر العبدُ من ذكر الله، لكن إذا ضمَّ التسبيح والتحميد والتكبير؛ يكون أكمل.[1]","link":"https://binbaz.org.sa/fatwas/31198/ما-افضل-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/‫alwabel _alsaib 036.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5421,"question":"بالنسبة للدعاء، هل يجب أن يرفع يديه بين الأذان والإقامة أو فقط يدعو الله ؟","title":"هل يلزم رفع اليدين عند الدعاء؟","answer":"الجواب: رفع اليدين من أسباب الإجابة، لكن في المواضع التي ما رفع فيها النبيُّ ﷺ لا يرفعها، فإنَّه ما كان يرفع بعد أداء الفرائض، ولا يرفع في خطبة الجمعة، وخطبة العيد، أمَّا في الاستسقاء فكان يرفع يديه، أو في خطبة الجمعة إذا استسقى يرفع يديه، وهكذا في غير ذلك من دعواته، أمَّا الفرائض فما كان يرفع إذا سلَّم منها، ولا بين السجدتين ولا في آخر التحيات، ما كان يرفع عليه الصلاة والسلام.[1]","link":"https://binbaz.org.sa/fatwas/31199/هل-يلزم-رفع-اليدين-عند-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 037.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5423,"question":"هل الثناء أعظم من الدعاء؟","title":"هل الثناء على الله أعظم من الدعاء؟","answer":"الجواب: الثناء أفضل، فالثناء ذكر، لكن إذا دعت الحاجةُ إلى الدعاء صار الدعاءُ أفضل، كدعاء الاستخارة، ودعاء \"رب اغفر لي\" بين السَّجدتين، والدعاء في السجود، أفضل من القراءة.[1]","link":"https://binbaz.org.sa/fatwas/31208/هل-الثناء-على-الله-اعظم-من-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 046.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5427,"question":"متى يقول: اللهم إني ظلمتُ نفسي ظلمًا كثيرًا ..؟","title":"متى يُقال: \"اللهم إني ظلمتُ نفسي ظلمًا كثيرًا..\"؟","answer":"الجواب: هذا يقوله في آخر الصلاة قبل أن يُسلِّم، وإن قاله بعد السلام –بعد الذكر- لا بأس، لكن الدعاء قبل السلام أجود وأفضل؛ لأنَّه محلّ الدعاء، فيدعو به في كلِّ وقتٍ؛ لأنه جاء في حديث الصديق: \"أدعو به في صلاتي\"، قال: \"وفي بيتي\" كما رواه مسلم أيضًا، فيدعو به في صلاته، وفي بيته، وفي الطريق، وفي أي مكانٍ، فهو دعاء عظيم: اللهم إني ظلمتُ نفسي ظلمًا كثيرًا، وإنه لا يغفر الذنوب إلا أنت، فاغفر لي مغفرةً من عندك، وارحمني إنَّك أنت الغفور الرحيم، فهو دعاء عظيم يدعو به في صلاته: في السجود، في آخر التحيات، وبعد ذلك في الدعاء، وفي أي وقت.[1]","link":"https://binbaz.org.sa/fatwas/31204/متى-يقال-اللهم-اني-ظلمت-نفسي-ظلما-كثيرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 042.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5430,"question":"ما الفرق بين الثناء والحمد؟","title":"ما الفرق بين الثناء والحمد والتمجيد؟","answer":"الجواب: الثناء مكرر، والحمد ثناء، لكن إذا كُرر صدق عليه الثناء مع الحمد، وإذا كُرر ثلاث مراتٍ وأكثر صار تمجيدًا. س: قوله في الحديث: فحمد الله وأثنى عليه؟ ج: يعني: كرر، يقول الله جل وعلا في الحمد: إذا قال العبدُ:  الْحَمْدُ لِلَّه قال الله: حمدني عبدي، وإذا قال: الرَّحْمَنِ الرَّحِيمِ قال الله: أثنى عليَّ عبدي، وإذا قال: مَالِكِ يَوْمِ الدِّينِ قال الله: مجَّدني عبدي، فإذا قال: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ قال الله: هذا بيني وبين عبدي، ولعبدي ما سأل، فإذا قال: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ قال الله: هذا لعبدي، ولعبدي ما طلب، سألني عبدي، ولعبدي ما سأل. س: قوله في الحديث: والحمد لله مثل ذلك يقول: مثل ذلك، أو يقول: الحمد لله عدد ما خلق؟ ج: مثل ذلك يعني: عدد ما خلق في السماء.[1]","link":"https://binbaz.org.sa/fatwas/31201/ما-الفرق-بين-الثناء-والحمد-والتمجيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 039.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5434,"question":"إذا ذكر الإنسانُ الأذكارَ ورأى في منامه ما يسوؤه، هل تكون؟","title":"ماذا يفعل مَنْ رأى في منامه ما يسوؤه؟","answer":"الجواب: يفعل ما قاله النبيُّ ﷺ، إذا رأى ما يسوؤه يفعل ما قاله النبيُّ ﷺ، يتأدَّب بالآداب الشرعية. قبل النوم يقول: بسم الله أموت وأحيا، باسمك ربي وضعتُ جنبي، وبك أرفعه، إن أمسكتَ نفسي فارحمها، وإن أرسلتها فاحفظها بما تحفظ به عبادك الصالحين، اللهم قني عذابك يوم تبعث عبادك، ويقرأ بعد ذلك آية الكرسي، ويقرأ قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات، كل هذا من السُّنة ومن التعوُّذات الشرعية. ويقول في آخر دعائه: اللهم أسلمتُ نفسي إليك، وفوضتُ أمري إليك، ووجهتُ وجهي إليك، وألجأتُ ظهري إليك، رغبةً ورهبةً إليك، لا ملجأ ولا منجا منك إلا إليك، آمنتُ بكتابك الذي أنزلتَ، وبنبيك الذي أرسلتَ، فيجعل هذا من آخر ما يقرأ. ويُستحب له التعوُّذ بكلمات الله التامات من شرِّ ما خلق ثلاث مرات، بسم الله الذي لا يضرّ مع اسمه شيءٌ في الأرض ولا في السماء ثلاث مرات، كل هذه من أسباب الوقاية. كذلك: اللهم ربّ السّماوات السبع، وربّ الأرض، وربّ العرش العظيم، ربنا ورب كل شيءٍ، فالق الحب والنوى، ومنزل التوراة والإنجيل والفرقان، أعوذ بك من كل شيءٍ أنت آخذٌ بناصيته، أنت الأول فليس قبلك شيء، وأنت الآخر فليس بعدك شيء، وأنت الظاهر فليس فوقك شيء، وأنت الباطن فليس دونك شيء، اقضِ عني الدينَ وأغنني من الفقر، كل هذا مما يُستحب له عند النوم.[1]","link":"https://binbaz.org.sa/fatwas/31225/ماذا-يفعل-من-راى-في-منامه-ما-يسووه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 050.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5438,"question":"بالنسبة للدعاء بعد الأذان: هل يكون بعد الأذان مباشرةً أو بعد السُّنة –يعني: الدعاء بين الأذان والإقامة؟","title":"متى يكون الدعاء بين الأذان والإقامة؟","answer":"الجواب: بعد الأذان، وبعد الراتبة؛ لأنَّ الإنسان قد يأتي في الطريق، وقد يجلس بعد صلاة تحية المسجد قبل الأذان، فالمقصود الدعاء بين الأذان والإقامة، سواء في الصلاة لتحية المسجد، أو في الصلاة التي يسمعها بالأذان، أو في حال جلوسه. س: قوله: لا تُردان –أو: قلَّما تُردان من كلام الرسول ﷺ؟ ج: نعم. س: حديث أنسٍ: الدعاء لا يُردّ بين الأذان والإقامة ضعَّفه المُحَشِّي؟ ج: له طرقٌ كثيرةٌ، وهو جيد.[1]","link":"https://binbaz.org.sa/fatwas/31232/متى-يكون-الدعاء-بين-الاذان-والاقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 054.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5442,"question":"هل يشرع أن يرفع صوته بالدعاء لتعليم الناس كما فعل النبي ﷺ؟","title":"هل يُشرع رفع الصوت بالدعاء لتعليم الناس؟","answer":"الجواب: إذا رفع بعض الأحيان للتعليم؛ ما في بأس، إذا رفع صوته في التعليم حتى يعلِّم الناسُ الدعاء فهذا طيب، من باب التعليم، وابن عباس جهر بالقراءة قال: \"لتعلموا أنها سُنة\".[1]","link":"https://binbaz.org.sa/fatwas/31240/هل-يشرع-رفع-الصوت-بالدعاء-لتعليم-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 058.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5445,"question":"الإطالة الآن في دعاء ختم القرآن، يأخذون ساعةً، ساعةً إلا ربعًا أحيانًا، هل هذا من؟","title":"ما حكم الإطالة في دعاء ختم القرآن؟","answer":"الجواب: الإلحاح في الدعاء والإكثار من الدعاء كله طيب، أَكْثِرْ من الدعاء، فالنبي ﷺ يقول: ما من عبدٍ يدعو الله بدعوةٍ ليس فيها إثمٌ ولا قطيعة رحمٍ إلا أعطاه الله بها إحدى ثلاث: إمَّا أن تُعَجَّل له دعوته في الدنيا، وإمَّا أن تُدخَر له في الآخرة، وإمَّا أن يصرف عنه من الشرِّ مثل ذلك، قالوا: يا رسول الله، إذن نُكثر؟ قال: الله أكثر، فالله يحب الإكثار من الدّعاء.[1]","link":"https://binbaz.org.sa/fatwas/31245/ما-حكم-الاطالة-في-دعاء-ختم-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 061.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5502,"question":"من قال في الصلاة، يقول: اللهم صل على محمد طب القلوب ودوائها؟","title":"ما حكم قول: \"محمد طب القلوب ودوائها\"؟","answer":"الجواب: هذا الكلام ما هو بصحيح، مجمل؛ طب القلوب ودوائها: مجمل. طب القلوب باتباع الشرع، دوائها باتباع الشرع، لكن هذا يُوهم أنه طبّه بنفسه، وأنه دواؤها بنفسه، وأنه ينفع ويضرّ؛ هذا ما يصلح، هذا الكلام يُوهم، \"اللهم صلِّ على محمدٍ وعلى آل محمدٍ\" ويكفي، \"كما صليتَ على إبراهيم وعلى آل إبراهيم\"، اللهم صلِّ على النبي الأمي، ما يخالف.[1]","link":"https://binbaz.org.sa/fatwas/31412/ما-حكم-قول-محمد-طب-القلوب-ودواىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 016.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5526,"question":"ما حكم مَن قال في دعائه: (يا حبيبي) يريد الله، وقول: (يا مسهل)، وقول: (يا هادي، يا دليل)؟","title":"ما حكم: يا حبيبي، يا مسهل، يا دليل، في الدعاء؟","answer":"الجواب: ما فيها شيء، هو أحب حبيبٍ ، لكن ادعوه بأسمائه: يا الله، يا رحمن؛ لأنَّ الله يقول: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، ما قال: ادعوني بحبيبي، ادعوني بأسمائي وصفاتي: يا الله، يا رحمن، يا رحيم، يا ربي، يا ذا الجلال والإكرام، وإن كان هو أحب حبيبٍ، لكن يُدعى بصفاته التي بيَّنها .[1]","link":"https://binbaz.org.sa/fatwas/31459/ما-حكم-يا-حبيبي-يا-مسهل-يا-دليل-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 041.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5548,"question":"التكبير (في العيد) له صيغة خاصَّة؟","title":"هل للتكبير في العيد صيغة خاصَّة؟","answer":"الجواب: هذه صيغته: \"الله أكبر، الله أكبر، لا إله إلا الله، الله أكبر، الله أكبر، ولله الحمد\" شفعًا، وبعض الصحابة يُكبر وترًا: \"الله أكبر، الله أكبر، الله أكبر، لا إله إلا الله، الله أكبر، الله أكبر، الله أكبر، ولله الحمد\"، ومنها: \"الله أكبر كبيرًا، والحمد لله كثيرًا، وسبحان الله بكرةً وأصيلًا\"، هذه الألفاظ أفضل. س: ولو زيد عليها التهليل؟ ج: لو قال: \"سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر\" كله طيب.[1]","link":"https://binbaz.org.sa/fatwas/31495/هل-للتكبير-في-العيد-صيغة-خاصة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 012.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5579,"question":"مَن أراد أن ينام وهو جنب هل يقرأ آية الكرسي؟","title":"هل يقرأ الجُنُب آية الكرسي عند النوم؟","answer":"الجواب: لا، يأتي بالتعوَّذات الشرعية دون آية الكرسي، ودون المعوذات، و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص]، وإذا أحبَّ ذلك فليغتسل خيرٌ له.[1]","link":"https://binbaz.org.sa/fatwas/31530/هل-يقرا-الجنب-اية-الكرسي-عند-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 018.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5636,"question":"يكون الوشم علاجًا؟","title":"ما حكم الوشم للعلاج؟","answer":"الجواب: قد يكون لإخراج شيء من الدم، ما هو بوشم، لكن قد يبقى لها أثر في جسد الإنسان للعلاج.[1]","link":"https://binbaz.org.sa/fatwas/31636/ما-حكم-الوشم-للعلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 005.mp3","categories":["الطب والتداوي"]},{"id":5638,"question":"ما حكم التداوي بالحرام إذا دعت الحاجة؟","title":"ما حكم التداوي بالمُحرَّم للحاجة؟","answer":"الجواب: عباد الله: تداووا ولا تداووا بحرام، والله يقول: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]. س: قضية التداوي بالمحرمات؟ الشيخ: إذا اضطُر إليها. س: ويستثنى منها بالخمر؟ الشيخ: حتى الخمر، لو غص بشيء ولا عنده إلا هو؛ له أن يبتلع ما يزيل خطر الموت. س: لكن لو كانت علاجًا؟ الشيخ: لا، ما يعالج بها، لكن الضرورة العارضة التي ما هي بعلاج، إنما هو لخلاص من موت، مثل: الإسهام بالدم لمن احتاج إليه.[1]","link":"https://binbaz.org.sa/fatwas/31639/ما-حكم-التداوي-بالمحرم-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 007.mp3","categories":["الطب والتداوي"]},{"id":5640,"question":"الدُّعاء بـ\"أمد الله عمرك\" أو \"أطال الله عمرك\" يكون لا ينبغي؟","title":"ما حكم قول \"أطال الله عمرك\"؟","answer":"الجواب: لا، إذا قال: \"على خير\" مثلما في الحديث الأول مقدرة إلا الدّعاء، إذا قال: \"على خير\"، \"فسح الله في أجلك على خير، أو على هدى، أو على صلاحٍ، أو على الإسلام\"، أو ما أشبه ذلك؛ لأنه قد يمده الله بعمرٍ على شرٍّ.[1]","link":"https://binbaz.org.sa/fatwas/31649/ما-حكم-قول-اطال-الله-عمرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 001.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5641,"question":"ترك التَّداوي هل يُقال: أفضل من التَّداوي؟","title":"هل ترك التَّداوي أفضل من التَّداوي؟","answer":"الجواب: للعلماء فيه أربعة أقوال: أحسنها وأصحّها أنه مشروع، ومن الأسباب المباحة. وقال قومٌ: تركه أوْلى. وقال قومٌ: مستوي الطرفين. وقال بعضُهم: مكروه.  والصواب أنَّه مستحبٌّ؛ لأنَّ الرسول ﷺ تداوى، وداوى أصحابه عليه الصلاة والسلام، ورقى، ورُقِيَ، وقال: عباد الله، تداووا.[1]","link":"https://binbaz.org.sa/fatwas/31650/هل-ترك-التداوي-افضل-من-التداوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 002.mp3","categories":["الطب والتداوي"]},{"id":5643,"question":"رُقية الإنسان لنفسه؟","title":"ما حكم رُقية الإنسان لنفسه ولغيره؟","answer":"الجواب: المكروه الطَّلب، أما الرُّقية فهي مُستحبَّة: مَن استطاع أن ينفع أخاه فلينفعه من دون طلبٍ، يرقي نفسه، أو يرقي غيره، من دون طلبٍ، وهكذا الطَّلب عند الحاجة، إذا دعت الحاجةُ قد أمر النبيُّ ﷺ أسماء أن تسترقي لأولاد جعفر. س: تكون للاستحباب في هذه الحالة؟ ج: نعم، النبي ﷺ رَقى نفسه، ورَقى غيره.[1]","link":"https://binbaz.org.sa/fatwas/31655/ما-حكم-رقية-الانسان-لنفسه-ولغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 004.mp3","categories":["الطب والتداوي"]},{"id":5644,"question":"بيع الرُّقى، رُقى مكتوبة تُباع؟","title":"ما حكم كتابة الرُّقى وبيعها؟","answer":"الجواب: ما أعرف لهذا أصلًا، ما ينبغي هذا، بيعها، ما ينبغي هذا. أما كون الإنسان يرقي أخاه لا بأس. أما بيعها ما أعرف له أصلًا، قد يكون الكاتبُ لا خيرَ فيه، ما يصلح هذا، ولا ينبغي.[1]","link":"https://binbaz.org.sa/fatwas/31656/ما-حكم-كتابة-الرقى-وبيعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 005.mp3","categories":["الطب والتداوي"]},{"id":5650,"question":"ما حكم مَنْ يقول: لا حول.. ولا يكمل: لا حول ولا قوة إلا بالله؟","title":"ما حكم من يقول لا حول.. ولا يكمل الحوقلة؟","answer":"الجواب: المشروع: لا حول ولا قوة إلا بالله، لا يقتصر على: لا حول، بل يأتي بها كاملةً، هذه هي السُّنة: لا حول ولا قوة إلا بالله، وإذا قال: لا حول إلا بالله، ولا قوة إلا بالله، قصده الإزراء على نفسه لا بأس، لكن السنة أن يأتي بها كاملة: لا حول ولا قوة إلا بالله. س: بعض الناس يقول: لا حول الله؟ ج: يُعلَّم، عامي، يُعلَّم العبارة. س: يقصد أنَّ بعض العوام يقول: لا حُول؟ ج: يُعلَّم: لا حول إلا بالله، يعني: لا تحول لي من شيءٍ إلا بالله، أو لا قوة لي إلا بالله، لكن إذا علم يُقال له: كملها، قل: لا حول ولا قوة إلا بالله، يُعلم السُّنة، طيب.[1]","link":"https://binbaz.org.sa/fatwas/31686/ما-حكم-من-يقول-لا-حول-ولا-يكمل-الحوقلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 012.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5659,"question":"ما الفرق بين دعاء العبادة ودعاء المسألة؟","title":"ما الفرق بين دعاء العبادة ودعاء المسألة؟","answer":"الجواب: دعاء العبادة: العمل الصَّالح يُسمَّى: دعاء عبادة، الصَّلوات دعاء عبادة، الصوم دعاء عبادة، الصَّدقة دعاء عبادة، التَّسبيح والتَّهليل دعاء عبادة؛ لأنك تطلب الأجر، تفعل هذا تريد الأجر، هذا دعاء عبادة، المصلي والمسبِّح والمتصدِّق والحاجّ والمعتمر، كلها دعاء عبادة، إنما فعلوا هذا يرجون ثواب الله، يريدون الأجر من عنده. ودعاء المسألة الطلب: اللهم اغفر لي، اللهم ارحمني، اللهم أنجني من النار، اللهم أدخلني الجنة. هذا يُقال له: دعاء المسألة، صريح الطَّلب.[1]","link":"https://binbaz.org.sa/fatwas/31696/ما-الفرق-بين-دعاء-العبادة-ودعاء-المسالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 005.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":5970,"question":"أخ يسأل عن الآيات التي تقرأ على المسحور، والممنوع عن زوجته ما هي؟","title":"الآيات التي تقرأ على المسحور والمصاب بالعين","answer":"الجواب: ذكر كثير من أهل العلم: أن من أسباب العافية للمسحور، والذي حبس عن زوجته: أن يقرأ آيات ثلاث التي في سورة يونس، وسورة الأعراف، وطه المتعلقة بالسحر، يقرأها، وتقرئ على المسحور، وعلى المحبوس عن زوجته، مع آية الكرسي، ومع قل يا أيها الكافرون، وقل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، هذه يقرأها على المريض، أو في ماء، ويشربه المريض، ويشفى بإذن الله. وإن جعل معها سبع ورقات سدر، دقها، وجعلها في الماء، وقرأ في ذلك أيضًا ينفع هذا، وهذا، يقرأ على المريض، أو في ماء يقرأ فيه آيات السحر من سورة الأعراف، ومن سورة يونس، ومن سورة طه، ويقرأ معها آية الكرسي، وقل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، ثم يشرب منها المسحور، والمحبوس عن زوجته، ويتروش بالباقي، هذا ينفع، وجربناه كثيرًا، وكذلك إذا قرئ على المريض نفسه، هذه الآيات ينفعه كثيرًا. السؤال: سؤال عن العلاج من إصابة العين؟ الشيخ: كذلك العين الرقية تنفع فيها، يرقية من الآيات التي تناسب في القرآن، ويدعو له، وينفث عليه في ذلك، هذا ينفعه، النبي -عليه الصلاة والسلام- قال: لا رقية إلا من عين، أو حمة وإذا عرف العاين؛ يأمره أن يغسل وجهه، ويتمضمض من أطرافه في إناء، ثم يغتسل بهذا الماء، وتزول العين -بإذن الله- إذا كان معروفًا. السؤال: إذا كان يؤاذيه، ياشيخ، ويكون شحناء، وعداوة؟ الشيخ: إذا عرف، يتوسل إليه بالطريقة الطيبة، يقال: هذا ما يضرك، وهذا أمر الله، والعين حق، يجب عليك أن توافق، وأن تغتسل له أطرافك، وتمضمض، وتغسل وجهك، ويديك، وتعطيه من هذا؛ ينفع -بإذن الله- أيش يضرك، ويجوز للحاكم أن يلزمه بذلك، إذا عرف. السؤال: ما حكم من يقرأ على المجنون، ويدعي بأنه يكلمون الجن، ويطلعهم من الشخص؟ الشيخ: هذا واقع، إذا قرأ عليهم؛ قد يخرجوا -بإذن الله- إذا كان جيدًا، وصاحب إيمان، قد يخرج الجن بقراءته، وقد يضربهم أيضًا، إذا كان معروفًا وليس معروفًا بالسحر، ولا بغيره.","link":"https://binbaz.org.sa/fatwas/1366/الايات-التي-تقرا-على-المسحور-والمصاب-بالعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_324.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":5980,"question":"رجل يقرأ على المرضى بالقرآن، والأدعية النبوية، وقبل القراءة يحدد المال الذي سيأخذه من المريض، فما هو رأي سامحتكم في هذا؟","title":"حكم أخذ المال مقابل الرقى الشرعية على المرضى","answer":"الجواب: لا بأس بذلك إذا كان يقرأ ما تيسر من القرآن، ويدعو لهم بالدعوات، وينفث على المريض، لا بأس أن يحدد الأجر الذي له.  كما وقع لبعض الصحابة مع لديغ لدغ، وكانوا نزلوا بهم، ولم يضيفوهم، فجاءوا إليهم يطلبون من يرقي ليرقي هذا المريض، فقالوا: إلا أن تضربوا لنا سهمًا، فضربوا لهم شيئًا قطيعًا من الغنم، فرقوه حتى عافاه الله، وسلموا لهم نفس الأجرة، وبلغوا النبي ﷺ فأقرهم على ذلك.","link":"https://binbaz.org.sa/fatwas/1362/حكم-اخذ-المال-مقابل-الرقى-الشرعية-على-المرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_320.mp3","categories":["الإجارة","الطب والتداوي","الرقى والتمائم"]},{"id":5983,"question":"فيما يتعالق بموضوع السحر يا شيخ والله، يروج عند بعض العوام أن فلانًا ركبه مسيحي، ركبه قيسي، ركبه كذا وكذا ( جني) حتى أن بعضهم يروج هذا، في ريف مصر، ويذهبوا إلى الكنائس، وهذه وسيلة من وسائل تبشير، أو تنصير المسلمين، فما وجه مثل هذا، بخصوص الجن، وما إلى ذلك، يُرَوَّج لدى العوام أن الجن ركبهم، بعضهم يقولون: إن هذا جن مسلم، وبعضهم يقول: جني كافر، ويأخذه إلى الكنيسة، ويقول: تعال يا قسيس عندي كذا وكذا؟","title":"حكم إخراج الكافر الجني من الإنسان المسلم","answer":"الجواب: لا، هذا غلط، إذا دعي أن الجني دخل في الإنسي، سواء كان الجن كافرًا، أو مسلمًا؛ فالقراءة تكون للمسلم، لا للكفرة، المسلم يقرأ عليه، المسلم، يقرأ عليه آيات من القرآن، ويتوعده ويذكره بالله، وأنه حرم عليه ظلم هذا الرجل، أو هذه المرأة، ويتوعده بذلك، ويأخذ بالسلاح، ويقول: إن ما خرجت منه قتلتك، وما هو قاتله، لكن للتخويف؛ لأن بعض الجن خواف، جبان، إذا رأى الجد من القارئ؛ خاف. وكذلك يخوفه بالسكين، يقول: ترى إن ما خرجت؛ قطعت رقبتك، أو يأخذ عصًا، أو حجرًا يتوعده، ويجتهد بكلام قوي، ليس بكلام ضعيف، ويقرأ، وينفث، ويمسح، ويعاهد ألا يعود إليه.","link":"https://binbaz.org.sa/fatwas/1368/حكم-اخراج-الكافر-الجني-من-الانسان-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_326.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":5998,"question":"ما حكم نقل الدم من شخص إلى شخص آخر؟ وإذا قيل بجواز ذلك، فهل يأثم المسحوب منه الدم لو تضرر، أو مات بسبب ذلك؟ وهل يدخل تحت الوعيد فيمن قتل نفسه؟","title":"حكم نقل الدم من شخص إلى آخر","answer":"الجواب:  نقل الدم من شخص إلى آخر محل تفصيل، فإذا دعت إليه الضرورة، ونقله لا يضر في ذلك؛ فلا حرج على الصحيح، لأجل الضرورة، إذا كان المنقول لا يضره بقول الأطباء العارفين إذا قالوا: إن هذا لا يضره لحاجة المضطر لهذا الدم الذي يجانس دمه؛ فلا حرج في هذا -إن شاء الله- على القول المختار. أما إذا كان يضره  فلا، لا يضر نفسه بمصلحة غيره، ولكن إذا قرر الطبيب، والمختص بأن هذا المقدار لا يضر الشخص، وهو يحتاجه؛ فلا حرج في هذا، من باب الإيثار، ومن باب الإحسان.","link":"https://binbaz.org.sa/fatwas/1414/حكم-نقل-الدم-من-شخص-الى-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_359.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6126,"question":"طريقة العلاج على المسحور؟","title":"طريقة العلاج من السحر وحكم الساحر","answer":"الجواب: العلاج له طرق منها: القراءة على المسحور، والنفث عليه، ومنها: قراءة في الماء، يقرأ في الماء آيات السحر الثلاث التي في سورة الأعراف، ويونس، وطه مع آية الكرسي، وقل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، يقرأ فيها، ثم يشربه، ويتوضأ به، ويغتسل بالباقي. ومنها: أن يضع في الماء شيئًا من السدر سبع ورقات، من السدر المعروف .. ويجعل في الماء، ويقرأ فيه ما ذكر هذا مجرب -بإذن الله- لإزالة السحر، ولعلاج من صرف عن زوجته، فلم يطأها، هذا مجرب ... ومنها: الدعاء، دعاء الله، والضراعة إليه، واللجأ إليه في السجود .. يسأل الله أن يرفع عنه ... ومنها: ما عرف من فعله أنه يؤخذ، ويزجر، ويؤدب حتى يزيل ما فعله إذا عرف أنه فلان أخذ، وأجري عليه ما يلزم من التعذيب .. حتى يزيل ما فعله، وهو يستحق القتل إذا عرف بعدما يزيل ما فعل، يستحق أن يقتل. السؤال:.. الجواب: هذا ما يتنافى مع هذا، هذا قالوه لما كان النبي ﷺ في مكة -عليه الصلاة والسلام- والسحر المعروف الذي لا يعقل صاحبه، يتحير، ويذهب عقله، أما هذا السحر العارض فقد فُعِل به ﷺ ولم يؤثر  على عقله، ولا على بلاغه -عليه الصلاة والسلام- فهو شيء عارض، خفيف، أثر فيما بينه، وبين أهله، لم يؤثر على شيء فيما يتعلق بالبلاغ، والبيان، وإصدار الأحكام، فهو شيء مخصوص، مستثنى مما رماه به أعداء الله.","link":"https://binbaz.org.sa/fatwas/1543/طريقة-العلاج-من-السحر-وحكم-الساحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_473.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6176,"question":"بمناسبة هذا الموضوع هل يجوز شرب البيرة لقصد أنها تزيل الحصى من الكلى؟","title":"حكم شرب البيرة للعلاج","answer":"الجواب: البيرة الخالية من الكحول  إذا لم تسكر لا بأس بها، سواء من الشعير، إذا سلمت كما يقال لنا: إن البيرة الموجودة هنا أنها سليمة، إذا كانت سليمة؛ فلا بأس.  أما إذا ثبت أنها تسكر ، إذا ثبت أن كثيرها يسكر... قال النبي -عليه الصلاة والسلام-: ما أسكر كثيره فقليله حرام فإذا ثبت أنها تسكر؛ حرمت، وإلا فالأصل جوازها، وعدم تحريمها. والتي هنا في البلد يقال: إنها سليمة، فإذا كانت سليمة كما قيل، ولم يجرب منها أحد أنها تسكر؛ فلا بأس، أما ما يكون في الخارج فقد تقدم أن بعض التي تأتي من الخارج مسكرة.","link":"https://binbaz.org.sa/fatwas/1635/حكم-شرب-البيرة-للعلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_526.mp3","categories":["الطب والتداوي"]},{"id":6289,"question":"بعض المصابين بأمراض نفسية يذهبون إلى الكهان، والمنجمين؟","title":"حكم الذهاب إلى الكهان والمنجمين","answer":"الجواب: لا يجوز هذا، لا يجوز الذهاب إلى المنجمين، ولا الكهان، ولا سؤالهم عن مرض، ولا عن غيره، النبي -عليه الصلاة والسلام- يقول: من أتى عرافًا فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا رواه مسلم في صحيحه، ويقول لما سئل عن الكهان قال: ليسوا بشيء، ونهى عن إتيانهم، وقال: من أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد -عليه الصلاة والسلام- وقال: ليس منا من تكهن، أو تكهن له، أو سحر، أو سحر له، أو تطير، أو تطير له فقوله: ليس منا، هذا وعيد، فلا يؤتون، ولا يسألون.  هؤلاء الذين يقولون: اعطنا .. اعطنا اسم أمك، واسم أبوك، هؤلاء كهنة، أو كذابين، والمشعوذين يأكلون أموال الناس بالباطل، إما أنهم خدام للجن، ويكذبون على الناس، وإما أنهم يريدون بهذا التلبيس على الناس حتى يأخذوا أموالهم بغير حق، والدواء، والعلاج يكون عند الأطباء المعروفين، أو عند الناس المعروفين بالخير من العرب الذين يداوون بالكي، بالحمية، بأدوية أخرى معروفة، ولا يتهمون بخدمة الجن، ولا طاعة الجن، ولا سؤال الجن، هذا لا بأس به، والطيب معروف عند الناس.","link":"https://binbaz.org.sa/fatwas/1806/حكم-الذهاب-الى-الكهان-والمنجمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_647.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6339,"question":"كيف يعالج نفسه إذا رأى شيئًا من..؟","title":"علاج من أصيب بالعين","answer":"الجواب: لا أعلم علاجًا إلا الضراعة إلى الله مثل ما جاء في الحديث يقول: ما شاء الله، وليبارك إذا رأى شيئًا يعجبه، يقول: ما شاء الله، لا قوة إلا بالله ، بارك الله في هذا، اللهم بارك لي في هذا، مع سؤال الله العافية، جاء ما يدل على أن هذا ينفع، ويصرف العين.  السؤال: علاج المصاب بالعين؟  الجواب: يأخذ من العائن، يغسل أطرافه وجهه، وأطراف يديه، ورجليه، ويتمضمض كذلك وإزاره يعني داخلة الإزار الذي حول السرة، ويشرب منه، ويصب على رأسه، وعلى بدنه من قفاه، ويبرأ -بإذن الله- حتى جربنا، حتى مجرد غسل اليدين، أو وجهه -بإذن الله- ينفع إذا غسل يديه، ووجهه، وتمضمض، ويكب على المرئي، ويبرأ بإذن الله. السؤال: يعني هذا ورد ياشيخ؟ الجواب: ورد في الحديث: وإذا استغسلتم فاغسلوا. السؤال: إذا لم يعرف العائن؟ الجواب: بالقراءة، يرقى عليه من آيات الله ما تيسر، وهو من أسباب الشفاء أيضاً. السؤال: قراءة المعوذات تحمي من العين؟ الجواب: هي من الأسباب، وقل: أعوذ بكلمات الله التامات من شر ما خلق، بسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء، وهو السميع العليم، ثلاث مرات، صباحًا، وثلاث مرات مساء، من أسباب العافية، من كل شيء. السؤال: هل يكون الحاسد مؤمنًا؟ الجواب: قد يكون، الحسد يبتلى به المؤمن، والكافر، والنظرة كذلك يبتلى بها المؤمن، والكافر، العين.","link":"https://binbaz.org.sa/fatwas/1930/علاج-من-اصيب-بالعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_715.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":6357,"question":"كيف يعالج نفسه إذا رأى شيئًا من..؟","title":"علاج من أصيب بالعين","answer":"الجواب: لا أعلم علاجًا إلا الضراعة إلى الله مثل ما جاء في الحديث يقول: ما شاء الله، وليبارك إذا رأى شيئًا يعجبه، يقول: ما شاء الله، لا قوة إلا بالله ، بارك الله في هذا، اللهم بارك لي في هذا، مع سؤال الله العافية، جاء ما يدل على أن هذا ينفع، ويصرف العين.  السؤال: علاج المصاب بالعين؟  الجواب: يأخذ من العائن، يغسل أطرافه وجهه، وأطراف يديه، ورجليه، ويتمضمض كذلك وإزاره يعني داخلة الإزار الذي حول السرة، ويشرب منه، ويصب على رأسه، وعلى بدنه من قفاه، ويبرأ -بإذن الله- حتى جربنا، حتى مجرد غسل اليدين، أو وجهه -بإذن الله- ينفع إذا غسل يديه، ووجهه، وتمضمض، ويكب على المرئي، ويبرأ بإذن الله. السؤال: يعني هذا ورد ياشيخ؟ الجواب: ورد في الحديث: وإذا استغسلتم فاغسلوا. السؤال: إذا لم يعرف العائن؟ الجواب: بالقراءة، يرقى عليه من آيات الله ما تيسر، وهو من أسباب الشفاء أيضاً. السؤال: قراءة المعوذات تحمي من العين؟ الجواب: هي من الأسباب، وقل: أعوذ بكلمات الله التامات من شر ما خلق، بسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء، وهو السميع العليم، ثلاث مرات، صباحًا، وثلاث مرات مساء، من أسباب العافية، من كل شيء. السؤال: هل يكون الحاسد مؤمنًا؟ الجواب: قد يكون، الحسد يبتلى به المؤمن، والكافر، والنظرة كذلك يبتلى بها المؤمن، والكافر، العين.","link":"https://binbaz.org.sa/fatwas/1930/علاج-من-اصيب-بالعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_715.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":6569,"question":"مرض رجل، وذهب إلى آخر يسمى سيدًا، وشرط على المريض عدة رؤوس من الغنم، وكمية من الحب، ومبلغًا من الدراهم، وكتب له حرزًا، وكتب له عدة أوراق يمحو البعض منها، ويشربه، والآخر يتبخر عليها، وشرط عليه كل سنة رأسًا من الغنم، أفتونا جزاكم الله خير الجزاء عن هذا؟","title":"حكم التداوي عند من عرف بالكهانة والشعوذة","answer":"الجواب: هذا وأشباهه لا يؤتى، ولا يسأل، هذا من الكهنة، والفجرة الذين يأكلون أموال الناس بالباطل، هذا لا يجوز أن يسأل أبدًا، هذا غلط، من الدلائل على خبثه: اشتراطه رؤوس الغنم، ماذا يفعل برؤوس الغنم؟ يذبحها للجن، أو لمن؟ هذا شر، ثم إعطاؤه حروزًا يعلقها هذا من سنة الجن.. المقصود: أن هذا لا يجوز سؤاله، ونرجو من السائل أن يعطينا خبره حقيقه، وأين يكون هذا الرجل؟ وفي أي مكان؟ وما هو اسمه؟ ولو سرًا بيننا، وبينه، أنت أيها السائل تعطينا خبره؛ لأن هذا ما يجوز إقراراه، هذا عمله سيئ، وهذا يضر المسلمين. السؤال: من أنواع الشرك؟ الجواب: هذا من الكهنة، يدعون الغيب، ومن ادعى الغيب؛ كفر. السؤال: الذين يعالجون بدون أن يشترطوا شيء؟ الجواب: هذا لا يجوز يعلق التمائم .. التمائم شرك. السؤال: بعضهم يعالجون بالطب الشعبي، ولا يشترطون.. ؟ الجواب: لا يجوز شيء، ما يجوز تعليق التمائم أبدًا، ولا يجوز .. على صاحبها، ولا يجوز إقراره؛ لأنها من التمائم، وقد أخبر أنها من الشرك، وقال: من تعلق تميمة؛ فلا أتم الله له، ومن تعلق ودعة؛ فلا ودع الله له ومن تعلق شيئًا؛ فقد أشرك وقال: إن الرقى، والتمائم، والتولة شرك. فلا يجوز تعليقها، ولو كانت من القرآن؛ لأنها وسيلة إلى الشر، والرسول ﷺ نهى عن التمائم كلها، ولم يستثن شيئًا، وقال إبراهيم النخعي - رحمه الله-: كان أصحاب ابن مسعود يكرهونها، من القرآن، ومن غير القرآن، يعني يحرمونها. ثم تعليق التمائم التي من القرآن، ومن الدعوات الأخرى وسيلة لفتح باب للشرك؛ لأنه إذا علق هذا علق هذا، واشتبه الأمر.","link":"https://binbaz.org.sa/fatwas/2397/حكم-التداوي-عند-من-عرف-بالكهانة-والشعوذة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_926.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6637,"question":"ما هو العلاج لمن به صرف، أو عطف؟ وكيف يمكن للمؤمن أن ينجو ممن يفعل ذلك، ولا يضره فعلهم؟ وهل هناك أدعية، أو ذكر من القرآن، أو السنة لذلك؟","title":"كيفية علاج المسحور","answer":"الجواب: فيه أنواع من العلاج ممن ابتلي بالسحر. الأول: أن ينظر فيما فعله الساحر إذا عرف، فإن عرف ما عمله الساحر؛ أبطل، فإذا عرف أنه مثلًا جعل شعرًا في حبال، وربط هذا بهذا، أو في أمشاط، أو في غير ذلك، إذا عرف أنه فعل هذا الشيء وجعله في المكان الفلاني؛ أزيل هذا الشيء، وأخذ، وأحرق، وأتلف، فيبطل مفعول ما فعل. الثاني: أن يُلْزم بذلك إذا عرف أنه الساحر، أن يلزم أن يزيل ما فعل، وأن يقال له: إما أن تفعل، وإما ضربنا عنقك، فهو يُلزم بهذا الشيء الذي فعل حتى يزيله، يلتمسه من محله، ويزيله إذا عرف، إذا عرف أنه هو الساحر الذي فعل هذا الشيء، وتعاطى هذا الشيء، ثم بعد ذلك إذا أزال هذا الشيء يقتله ولي الأمر.. لأن السحرة لا يجوز إقرارهم، بل يجب قتلهم؛ لأنهم يضرون الناس، وقد روي عنه ﷺ أنه قال : حد الساحر ضربه بالسيف روي مرفوعًا، والصواب وقفه على الصحابي الجليل جندب أنه قال: (حد الساحر ضربه بالسيف). وكتب أمراء الجيش في الشام إلى عمر  أنهم وجدوا سواحر، فأمر بقتلهم، ولما وجدت حفصة -رضي الله عنها- أم المؤمنين جارية لها تتعامل بالسحر قتلتها. فالمقصود: أن السحرة الصحيح فيهم: أنهم يقتلون، وإذا عرف أنهم السحرة ألزموا بأن يزيلوا ما فعلوا من السحر لفلان، أو لفلانة حتى يزيلوه. النوع الثالث: القراءة، فإن لها أثرًا عظيمًا في إزالة السحر، كونه يقرأ في ماء آية الكرسي اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] وآية السحر التي في سورة الأعراف، أو في سورة يونس، أو في سورة طه، ويقرأ معها قُلْ يَا أَيُّهَا الْكَافِرُونَ وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين يقرأ في ماء، ويشرب منه صاحب السحر -المسحور يعني- ويتروش به مرة، أو مرتين، أو أكثر فإنه يزول بإذن الله، وقد ذكر هذا العلماء، كما ذكر الشيخ عبدالرحمن بن حسن -رحمه الله- ذلك في كتابه فتح المجيد شرح كتاب التوحيد، في باب ما جاء في النشرة، وذكره غيره. ونوع رابع مع القراءة: أن يأخذ ورقًا من السدر الأخضر -سبع ورقات من السدر الأخضر- يدق، ويقرأ في هذه الآيات، ويقرأ فيه السور المذكورة، ويشرب منه، ويغتسل بالباقي، هو أيضًا نافع، وهو مجرب لهذا، كما أنه مجرب أيضًا للرجل إذا حبس عن زوجته، ولم يأتها، فإنه إذا قرأ بهذه الآيات، والسور، وشرب من ذلك، وتروش بذلك؛ نفعه هذا بإذن الله... ورقة السدر دقها، وجعلها في الماء، وتروش به مرة، أو مرتين_ نفعه بإذن الله. وآية الأعراف معروفة، وهي قوله سبحانه: وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ  ۝  فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ۝ فَغُلِبُوا هُنَالِكَ وَانْقَلَبُوا صَاغِرِينَ  [الأعراف:117- 119] هذه من سورة الأعراف. ومن سورة يونس: وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ ۝ فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ ۝ فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لَا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ۝ وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ  [يونس:79 -82]. وفي سورة طه يقول -جل وعلا-: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لَا تَخَفْ إِنَّكَ أَنْتَ الْأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:65 -69]. هذه الآيات التي من السور الثلاث ينفث بها في الماء، ويقرأ بها.. ويقرأ: قل يا أيها الكافرون، وقل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، وإذا قرأ مع ذلك \"اللهم رب الناس أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقمًا\" ثلاث مرات طيب، وإذا قرأ مع ذلك \"بسم الله أرقيك من كل شيء يؤذيك، ومن شر كل نفس، أو عين حاسد، اللهم يشفيك..\" ثلاث مرات أيضًا، فهذا أيضًا من أسباب الشفاء، والعافية، ثم يشرب من هذا الماء، ثم يغتسل به، وإن قرأ عليه القارئ -قرأ على المسحور- بهذه الآيات، ونفث بها عليه على صدره، أو على يده، أو على رأسه، وتفل بها عليه، فذلك من أسباب الشفاء له.","link":"https://binbaz.org.sa/fatwas/2492/كيفية-علاج-المسحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1019.mp3","categories":["الطب والتداوي","الأدعية والأذكار"]},{"id":6653,"question":"أنشئت الآن في نجد بعض أنواع التي لا أحكم عليها، هل هي شعوذة، أم حقيقية جاءت عن الرسول، وهو انتشار بيع الماء في قوارير صحة، ويقولون: إنه قرئ عليه القرآن، وأن فيه شفاء بعد الله، ويبيعون أشياء أخرى، وبأسعار خيالية، وأخذ الناس تصديق ذلك، فما حكمه؟","title":"حكم بيع الماء المقروء عليه القرآن","answer":"الجواب: هذا بلغنا، وبينا للأمير أن هذا يمنع من الرياض، بلغنا منذ أشهر، بينا أنه يمنع كونه يباع قوارير يدعون أنه قرئ فيها، قرأ فيها بعض الناس حتى يعالج بها المرضى، قلنا: هذا يمنع؛ لأنه وسيلة إلى أن يفعلها كل واحد، أما كون المريض يقرأ عليه إنسان، أو يقرأ في ماء؛ لا بأس إذا كان ممن يظن فيه الخير، يقرأ في ماء. النبي ﷺ قرأ في ماء لقيس بن ثابت بن شماس، وصبه عليه، فهذا لا بأس به كونه يقرأ في ماء، أو في طعام لطلب الشفاء من الله ، وأن هذا من الأسباب مثل ما يقرأ على المريض نفسه، فيقال الرقية لا بأس بها، لكن هذا يمنع؛ لأنه وسيلة إلى التساهل في الأمور، وأن يفعلها كل أحد.\n\nالسؤال: يا شيخ غفر الله لك بالنسبة النوع هذا من العزائم يكتبونه بزعفران، ثم يبيعونه؟ الجواب: بلغني هذا، وإنما قلنا للأمير ينبغي أن يلحظ.","link":"https://binbaz.org.sa/fatwas/2531/حكم-بيع-الماء-المقروء-عليه-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1026.mp3","categories":["الطب والتداوي"]},{"id":6654,"question":"إن بعض الناس الذين ابتلاهم الله بالجن يذهبون إلى الكهان، مع العلم أن هؤلاء الكهنة يقومون بمنع الجن عن هؤلاء الناس، سواء بالقتل، أو بالمنع، فما رأيكم بهذا؟","title":"استخدام الكهنة للشياطين","answer":"الجواب: هذا كله لا يجوز، لأن الكهنة يستخدمون الشياطين، حتى في عهد الجاهلية الكاهن له صاحب من الجن يسمى كاهنًا، له رئيًا من الجن، صاحب يأتيه يخبره، جرى في الإحساء كذا، جرى في المدينة كذا، جرى في الشام كذا، جرى في مصر كذا، الشياطين فيما بينهم يتناقلون الأخبار: قتل فلان، مات فلان، حدث انقلاب في المحل الفلاني، حدث كذا، هكذا تتناقل الشياطين، فيظن الجاهل أن هذا الكاهن، أو هذا الرمال يعلم الغيب، وإنما هي الشياطين تذكر له بعض الأخبار، فيتظاهر للناس أنه عنده معلومات، وأن عنده معلومات عن الغيب، وأنه يطلع على كذا، وأنه يطلع على كذا.  وقد يكون يستخدم بعض الشياطين الآخرين الذين لهم قوة، ولهم سلطان من ملوك الشياطين، ورؤسائهم، فيأتون بهذا الشيطان الذي تلبس بالمجنونة، او بالمجنون، أو فعل فيه شيء من الأمور التي يتعاطاها الشياطين، فيقولون له إذا أرضاهم هذا الإنسي، إذا أرضاهم بعبادتهم من دون الله، أو ذبح لهم، أو نذر لهم، أو عبدهم بالسجود، أو بغيره، إذا أرضاهم قد يحضرون الشيطان الذي تحت إمرتهم، فيقولون: إما أن تفعل كذا، وإلا قتلناك، وإلا سجناك، وإلا فعلنا بك، فيدع عمله القبيح من أجل طاعة ساداته من الشياطين، والرؤساء.  فيحذر النفع للإنسان بهذه الطرق الخبيثة الشركية الظاهرة، هذا ليس بعذر، ولا يجوز إتيان هؤلاء أبدًا، ولو قدر أنه انتفع به بعض الناس، فيكون النفع لبعض الناس من طريق الشرك ليس بعذر، فعباد الجن قد ينتفعون بالجن، ولكن ضررهم أعظم، فقد يأتي لهم الجني بأشياء، قد يأتي لهم بدراهم، قد يأتي لهم بطيب يسرقه، قد يأتي لهم بغنم يسرقها، قد يأتي لهم بأشياء، فهذا مقتدر في عبادة الجن، واتخاذهم آلهة مع الله، نسأل الله العافية. حتى أهل الجاهلية كانت تسلمهم الأصنام، يأتي الشياطين إلى جوف الأصنام، ويكلمون هؤلاء العبدة من دون الله، ويكلفونهم بأشياء، ويخاطبونهم بأشياء، ويقولون جرى كذا وكذا، وربما خاطبوهم بلغة لا يعرفونها، فيغرونهم بالشرك، ويدعونهم إلى الشرك، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2526/استخدام-الكهنة-للشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1021.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6661,"question":"بعض الناس لا يتزوج من ابنة عمه؛ خشية أن يظهر الأولاد مشوهين، فهل هذا ينافي كمال التوحيد؟","title":"حكم ترك الزواج من الأقارب خشية الأمراض","answer":"الجواب: كثير من أهل العلم بينوا هذه الأمور، وأنه ينبغي للإنسان أن يختار لنطفه الزوجة المناسبة، حتى قال بعض الفقهاء: أن الأفضل أن يتزوج أجنبية، لا بنت عمه، وهذا غلط، لا أصل لهذا، سواء بنت عمه، أو ما هي بنت عمه، بنت خاله، أو ما هي بنت خاله، النبي تزوج بنات عمه -عليه الصلاة والسلام-.  لكن ينظر فإذا كانت المرأة من بيت يصابون بالخبل، أولادهم بالخبل، بالجنون، بنقص الخلقة، بتشويه الخلقة، لا يتزوج منهم، من باب تحري الأسباب؛ لأن الوراثة يكون بك عدوى، وأمراض تكون وراثة -بإذن الله-توجد في الولد، وولد الولد، وولد البنت، فإذا كانت هذه الأسرة معروفة بأن يوجد فيهم بالوراثة أمراض شينة في الأولاد؛ يتجنبهم، وإذا كانت الأسرة ما عرف فيها شيء؛ يتزوج منهم، وهذه أمور معروفة بالتوارث تقع، ولهذا يوصي العلماء، والأطباء بملاحظة هذه الأمور.","link":"https://binbaz.org.sa/fatwas/2565/حكم-ترك-الزواج-من-الاقارب-خشية-الامراض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1060.mp3","categories":["الطب والتداوي"]},{"id":6671,"question":"من المعلوم أن السحر لا يبطله إلا ساحر، فهل هذا صحيح؟","title":"حكم فك السحر بمثله","answer":"الجواب: ليس بصحيح، السحر قد ينقضه الساحر، وقد يزول بغير الساحر، الساحر قد ينقضه بسحر مثله، يخدم الشياطين، ويتعاطى ما يرضي الشياطين؛ فيزول السحر الذي أوقعوه بالمسحور؛ لأنهم يحبون أن يتصل بهم الناس؛ حتى يعبدوهم من دون الله. فالشياطين قد تفعل شيئًا بالإنسان حتى يتعاطى ما يرضيهم من الشرك بالله، والتقرب إليه بما حرم الله من العبادات، وغيرها؛ حتى يرفعوا سحرهم، وما .. هذا من عمل السحرة، ولا يجوز إتيانهم، ولا سؤالهم، النبي ﷺ قال: من أتى عرافًا، أو كاهنا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام.  وقال: ليس منا من تطير، أو تطير له، وليس منا من سحر، أو سحر له، وليس منا من تكهن، أو تكهن له، ومن أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد -عليه الصلاة والسلام- وقال: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة.  فلا يجوز للمؤمن أن يأتي السحرة، ولا الكهنة، ولا العرافين المعروفين بدعوى علم الغيب، ولا المنجمين، كل هؤلاء يحرم إتيانهم، ويحرم سؤالهم، ويحرم تصديقهم.  ولكن هناك علاج ثانٍ لهذه الوسائل بغير السحر، بالقراءة على المسحور، فإن هذا قد ينفعه الله به، ويزول السحر، هناك أدوية أخرى يتعاطاها المسحور لإزالة ما أصابه، منها: أوراق السدر المعروف -النبق المعروف- كان العلماء فيما سبق -علماء هذه الأمة- يأخذون سبع ورقات من السدر، تدق، ثم يقرأ فيها آية الكرسي، وآيات السحر التي نزلت في القرآن الكريم في سورة الأعراف، وسورة طه، وسورة يونس، ويقرأ: قل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، مع ما يسر الله من الدعاء اللهم رب الناس، أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقمًا ثم يشرب منها المسحور، ويغتسل بها، ويزول -بإذن الله- السحر، قد يكون يزول بأول مرة، وقد يكون يزول بثاني مرة، وقد يكون يزول بثالث مرة، وهذا مجرب كثيرًا، ونافع، قد نفع الله به كثيرًا.","link":"https://binbaz.org.sa/fatwas/2563/حكم-فك-السحر-بمثله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1058.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6690,"question":"في مريض مرضًا مزمنًا، وذهب إلى الأطباء في كل أنحاء المملكة ما جعل الله له سببًا وشفاء بسببهم، فأخذه أخوه، وذهب به إلى الشمال، إلى واحد عنده كلاب، يقولون: إنه كاهن، ونصحته، قال: إن الضرورة تبيح المحرمات؟","title":"حرمة إتيان الساحر للتداوي","answer":"الجواب: لا ما يجوز، هذا غلط، هذا أفتى نفسه فقط. السؤال: وأخذ منه خمسة آلاف ريالًا، هذا الكاهن أخذ منه خمسة آلاف ريالًا، وقال: إن امرأتك سحرتك في خبز، والمرأة هذه بارة به، حتى بعد عرفت ما يمكن أن تسحره، وهي عجوز، وهو فوق الخمسين عامًا. الجواب: وهذه من العقوبات، المقصود أن هذا ما يجوز. السؤال: والآن اختل عقله، ولا يصلي الآن، ما عاد يشعر، ولا عاد يصلي؟ الجواب: يقال له: ما يجوز هذا، إتيان السحرة، والكهنة ما يجوز إتيانهم، ولا يحل، هذا ولو كان مريضًا بعض الأمراض ما لها شفاء، بعض الأمراض قد كتب الله أنه يموت بأسبابها، ما لها علاج، قد يعالجه مائة طبيب، ولا ينفع، إذا كان الله أراد أنه يموت بهذا المرض ما فيه شيء، إنما الإنسان يأخذ بالأسباب، فإن شفاه الله، وإلا فالأمر بيد الله، ما كل مرض له دواء، بعض الأمراض ما لها دواء، قد كتب الله أنه يموت بها. السؤال: والضرورات تبيح المحرمات في ماذا؟ الجواب: إذا جاع ولا عنده شيء يأكله، جاز أن يأكل من الميتة مثلًا، وأشباه ذلك؛ حتى لا يموت، ما هو معناه: أنه إذا ما تزوج يروح يزني ... يشرب الخمر لا، هذا غلط، ما كل الضرورات تبيح المحرمات، ولا كل شيء يسمى ضرورة، الضرورة التي تفضي به إلى الموت، تأخذ من الميتة، أو من أي طعام وجدته حتى تبقي نفسك، وحياتك من هذا الجوع الشديد الذي أصابك: إما بالثمن، وإما بالمعروف. السؤال:... الجواب: ... ولو أن شيئًا سبق القضاء لسبقته العين، ما تسبق القدر، القدر من ورائها، لا يقع شيء إلا بقدر.","link":"https://binbaz.org.sa/fatwas/2567/حرمة-اتيان-الساحر-للتداوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1062.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6728,"question":"وتخصصي هو النساء، والولادة حيث إن هذا التخصص شاق على النساء، وغالبًا ما يكون مستواهم ضعيف فيه، فنحتاج كثيرًا إلى الرجال في هذا التخصص، فهل يجوز لي العمل في هذا التخصص، مع العلم أنني شخصيًا غيور جدًا، ولا أرضى لأهلي أن يكشفوا على رجال، وإن كان في تخصص باطنية، أو جلدية، فأفتونا جزاكم الله خيرًا؟","title":"حكم تخصص الرجال في طب النساء والولادة","answer":"الجواب: على كل حال هذا التخصص خطير، ويخشى منه على الرجل شر كثير، ولكن إذا دعت إليه الضرورة؛ لا بأس، لكن إذا تولاه النساء هو الذي ينبغي، إذا تخصص به النساء، واجتهد في تعليم النساء لهذا الأمر؛ يكون أولى، وأنفع للنساء، وأبعد عن الشر، ولكن قد تدعو الحاجة إلى تخصص الرجال؛ فلا يضر.","link":"https://binbaz.org.sa/fatwas/2604/حكم-تخصص-الرجال-في-طب-النساء-والولادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1100.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":6797,"question":"لقد اطلعت على كتاب الحديث السنة الثالثة المتوسط في حديث رقم 31 بعنوان: الشيطان يخالف بين المسلمين؛ فاحذروه،  بأن في معاني المفردات كلمة الشيطان معناها: أنه كان من الملائكة، فعاقبه الله بسبب عصيانه، وامتناعه عن السجود لآدم، فهو عدو للبشر، إلى آخره، فهل هو فعلًا كان من الملائكة؟","title":"الخلاف في كون إبليس من الملائكة أم لا","answer":"الجواب: هذا فيه خلاف بين العلماء معروف، بعضهم قال: إنه من الملائكة، ثم طرد، ولعن، وبعض أهل العلم قال: إنه من الجن، وأن الطائفة التي كان منها هم الجن، ولهذا قال -جل وعلا-: إِلَّا إِبْلِيسَ كَانَ مِنَ الْجِنِّ فَفَسَقَ عَنْ أَمْرِ رَبِّهِ [الكهف:50] فبين سبحانه أنه كان من الجن، والجن هم المعروفون، هم الثقل الثاني.  قال بعض أهل العلم: وهو أبوهم، كما أن آدم هو أبو الإنس، فهو أبو الجن، وفيهم الشياطين، وهم المردة، ولكن قال بعض أهل العلم: إن الجن طائفة من الملائكة يقال لهم: الجن؛ لأنهم استجنوا، اختفوا، فقيل لهم: الجن، وهم من الملائكة، وهذان القولان مشهوران، ولكن جماعة من المحققين يرجحون أن الجن غير الملائكة، وأنه كان مع الملائكة يصلي معهم، ويتعبد معهم، فعمه الأمر، فلما أبى، وفسق، وتكبر؛ لعن وطرد -نعوذ بالله- وصار من ذريته الشياطين، والجن منهم المؤمن، ومنهم الفاسق، ومنهم الكافر، كما قال تعالى: وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذَلِكَ [الجن:11].  س: يا شيخ هم من الجن، أو من الملائكة؟ ج: القول المشهور عن العلماء مشهور أنه من الملائكة، وأنه طرد لما استكبر، وأن الجن طائفة من الملائكة، يقال لهم: الجن. وقال آخرون: لا، الجن هم الثقل الثاني المعروفون الذين قال الله فيهم: وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وأنهم ليسوا من الملائكة، وأن الملائكة خلقوا من النور، والجن خلقوا من النار، كما قال تعالى: وَالْجَانَّ خَلَقْنَاهُ مِنْ قَبْلُ مِنْ نَارِ السَّمُومِ [الحجر:27] قَالَ أَنَا خَيْرٌ مِنْهُ خَلَقْتَنِي مِنْ نَارٍ وَخَلَقْتَهُ مِنْ طِينٍ [الأعراف:12] فهو ليس من الملائكة في العنصر، عنصر الملائكة من النور، وعنصره من النار، فليس منهم في العنصر، ولا في الحقيقة، ولكنه كان معهم، فلما أمر بالسجود؛ لم يسجد، وتكبر، وعصى، فطرده الله، وأبعده، ولعنه. ولهذا اختار هذا شيخ الإسلام ابن تيمية، وجماعة، وقالوا: إنه من الجن، وهو أبوهم، خلقه الله من مارج من نار، وليس من الملائكة، ولكنه كان معهم في السماء، كان يتعبد، فلما استكبر؛ طرد ولعن -نسأل الله العافية-.","link":"https://binbaz.org.sa/fatwas/2674/الخلاف-في-كون-ابليس-من-الملاىكة-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1171.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6873,"question":"ما حكم الدين في المرأة الحامل التي تذهب إلى المستشفيات الحكومية، ولا تجد إلا رجالًا، أو نساء هنودًا، أو كوريات، بوذيات، ومسيحيات؟ فهل تسمح بالكشف عليها عند الرجال، أم النساء غير المسلمات؟","title":"حكم علاج المرأة عند الرجال الأجانب أو النساء الكافرات","answer":"الجواب: لا، الواجب أن يكون عند الطبيبات، وهذا عند غير الضرورة، أما إذا كان ضرورة يخشى منها الخطر، هذا للضرورة، أما إذا كان ما هناك ضرورة، فالواجب أن هذا يكون عند النساء، عند الطبيبات.  والواجب على المستشفيات أن تعتني بهذا الأمر، ولهم في هذا جهود، وقد كتب لهم غير مرة من أهل الخير يحثوهم على هذا الشيء، ووزير الصحة كذلك يعتني بهذا الشيء، لكن قد يتعثر عليه بعض الأحيان وجود الكافي من الطبيبات.","link":"https://binbaz.org.sa/fatwas/2760/حكم-علاج-المراة-عند-الرجال-الاجانب-او-النساء-الكافرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1252.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":6887,"question":"هل يتغير القلب لو أزيل مثلًا بعملية جراحية، وبدل بقلب آخر في حالة الأمراض التي تحدث للقلب، وينتج عنها إجراء عملية بالقلب؟","title":"حكم استبدال قلب الإنسان بقلب آخر","answer":"الجواب: إجراء العملية للقلب من حيث التاريخ لم نعلم لها نجاحًا مستمرًا، وإنما سمعنا نجاحا مؤقتا في أوقات قليلة للعلاج.  أما إذا نجح القلب؛ حكمه حكم القلب الأصيل، إذا نجح، واستقر، وصار يعقل به، ويفهم به؛ صار هذا القلب الذي أبدل عن القلب الأول، وجعل فيه خصائصه، واتصلت به الشرايين، والأشياء التي كانت تمد القلب السابق، فإن حكمه حكم القلب السابق، ما دام يعقل به، ويفهم به، حكمه حكم العقل السابق، والقلب السابق، يكون مكلفًا في كل شيء.  أما إذا زال عقله؛ فإنه يزول تكليفه، ولكن فيما سمعنا الآن أن العلاج المتعلق بالقلب كل ذلك لم ينجح النجاح التام، وإنما هو نجاح مؤقت بأوقات محدودة.","link":"https://binbaz.org.sa/fatwas/2765/حكم-استبدال-قلب-الانسان-بقلب-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1257.mp3","categories":["الطب والتداوي","قضايا معاصرة"]},{"id":6904,"question":"ما حكم استعمال الأدوات المضعفة للشهوة الجنسية؟","title":"حكم استعمال ما يضعف الشهوة الجنسية","answer":"الجواب: إذا كان يضره نشاطه الجنسي، ويحب أن يتعاطى شيئًا يضعف ذلك؛ فلا حرج عليه من المادة التي تكون مباحة، التي يقرر الأطباء الموثقون أنه لا يضره، ولكن يضعف الشهوة إضعافًا لا يضره، بل يعينه على جهاد نفسه، والبعد عن أسباب الفاحشة، ونوصيه بالتزوج، عليه أن يبادر بالزواج، ولو بالاستدانة، والقروض، ويدعو الله  حتى يسلم من شر شهوته -إن شاء الله، وفق الله الجميع-.","link":"https://binbaz.org.sa/fatwas/2838/حكم-استعمال-ما-يضعف-الشهوة-الجنسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1286.mp3","categories":["الطب والتداوي"]},{"id":6948,"question":"يوجد بعض الناس يذهبون خارج البلاد للعلاج عند الكهان، فيقولون لهم: أنت فيك سحر، والذي سحرك فلان، ويعلمونه باسمه، وهو ما عرفه، هل يجب العلاج عندهم، ويدعون أنهم مباح لهم هذا العمل؟","title":"حكم الذهاب إلى الكهان والعرافين والسحرة","answer":"الجواب: العلاج عند السحرة، والكهنة منكر لا يجوز، لا يجوز سؤالهم، ولا إتيانهم، ولا تصديقهم، يقول النبي ﷺ: من أتى عرافًا، فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا أخرجه مسلم في الصحيح. ويقول ﷺ: من أتى كاهنًا، أو عرافًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد -عليه الصلاة والسلام-. فالعرافون هم الذين يدعون علم الكهانة، وعلم السحر، وعلم كل ما كان، ويقولون: ما اسم أمك، واسم أبيك، وهذا سحرك فلان، وقال لك فلان كذا، في يوم كذا، وفي يوم كذا، هكذا أفعالهم.  هؤلاء لا يأتون، ولا يجوز سؤالهم، بل ينبغي فضحهم، من عرفهم يرفع بأمرهم إلى الأمراء الطيبين، إلى المحكمة، وإلى وزارة الداخلية، أو إليّ، وأنا أقوم باللازم -إن شاء الله- إن عرفهم في أي مكان، ولا يجوز له السكوت عنهم، والتغطية عنهم، بل يبينهم في جيزان، في أبها، في الشمال، في المغرب، في أي مكان، هذا من باب التعاون على البر والتقوى. يرفع بأمره إلى المحكمة، إلى المحاكم، إلى الأمراء الطيبين، إلى الملك، إلى وزير الداخلية، إليّ، إلى رئيس الهيئات، من باب التعاون على البر والتقوى، ويبين مكانهم، يقول: في المكان الفلاني اسمه فلان ابن فلان؛ حتى يسعى في إزالتهم، والقضاء عليهم، الله يكفينا شرهم.","link":"https://binbaz.org.sa/fatwas/2878/حكم-الذهاب-الى-الكهان-والعرافين-والسحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1326.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":6952,"question":"هل يجوز أن يتبرع الشخص المسلم -حيًّا كان أو ميتًا- بأي عضو من أعضاء جسمه، سواء لشخص مثله محتاج لهذا العضو، مثل: الكلى لهيئة طيبة، أو مركز للأبحاث لعمل التجارب في جثته بعد وفاته، أو أن يهبها حرية التصرف في أعضائه بعد وفاته، يعني خدمة للطب؟","title":"حكم التبرع بعضو من الأعضاء حال الحياة أو الموت","answer":"الجواب: هذا فيه خلاف بين أهل العلم، التبرع بالكلية، ونحوها فيه خلاف بين أهل العلم، منهم من أجازه، ومنهم من منعه. أما كونه يتبرع بجثته لتشرح ما يجوز، ليس له أن يسمح بذلك، المسلم لا يشرح، إنما الخلاف في هل يجوز أن يسمح بكليته أن تؤخذ لغيره، أو قلبه يؤخذ لغيره عند وفاته؟  هذا محل النظر، وكثير من أهل العلم يمنعون من ذلك، ويقولون: ليس له التصرف في جسمه، فهو ملك لله، وليس ملك لنفسه، فليس له أن يتصرف بنفسه، وكليته، أو قلبه، أو كذا، أو كذا، وآخرون قالوا: إذا سمح بذلك في حياته؛ فلا بأس، وعندي في هذا توقف.. والكلام في هذا معروف عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/2882/حكم-التبرع-بعضو-من-الاعضاء-حال-الحياة-او-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1330.mp3","categories":["الطب والتداوي","قضايا معاصرة"]},{"id":6989,"question":"هل لأحد يطلب معلمًا في بيته، ويجلس عنده، وقال له: اكتب لي شيئًا من القرآن، أو غيره، ومعلم يكتب في اللوح، ويغسل له، ويشربه، وقال له: لأجل هذا الكتاب تنال الرزق كثيرًا، هل هذا يجوز فعله؟الشيخ: أعد.الطالب: جاب معلمًا في بيته كتب له قرآنا في لوح، ثم محا القرآن، وقال له: اشربه؛ إن شاء الله يكثر الرزق يعني؟","title":"حكم كتابة القرآن في ألواح وغسلها ثم شربها","answer":"الجواب:\n\nهذا ما له أصل، هذا ليس له أصل، القرآن يقرأ على المريض، وينفث عليه، ويدعى له، أو يكتب في لوح، أو صحن، أو قرطاس تكتب آيات من آيات الله -جل وعلا- وبعض الدعوات، ثم تغسل بالماء، ويشربه المريض، هذا فعله جماعة من السلف، لكن ما هو معناه أنه يحصل له الرزق.\n\nتفعل لبعض الأمراض التي تصيب الإنسان، إذا أصاب الإنسان في صدره، في بدنه، في رأسه؛ ينفث في ماء، ثم يشرب منه المصاب، أو يغتسل ببعضه، كما يفعل لصاحب العين إذا أصابته العين، أو أصابه السحر، يقرأ له بعض الآيات، ويشرب منها، ويغتسل بها، ويزول المرض -بإذن الله-.\n\nأما أنه يكتب له، أو يمحوه؛ لأجل الرزق، وسعة الرزق، ونحو ذلك، هذا لا أصل له.\n\nالسؤال: يصلح للعقم؟\n\nالجواب: العقم عقمان، العقم له أسباب، يعني سدد في مجاري المني، يعرفه الأطباء، وربما يزول، وهناك عقم لا حيلة فيه، مثل ما قال -جل وعل-ا: وَيَجْعَلُ مَنْ يَشَاءُ عَقِيمًا [الشورى:50] هذا لا حيلة فيه لأحد، العقم الأساسي الذي الرحم لا يتقبل، والمني ما يصلح منه الولد، هذا ليس فيه حيلة .","link":"https://binbaz.org.sa/fatwas/2907/حكم-كتابة-القران-في-الواح-وغسلها-ثم-شربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1355.mp3","categories":["الطب والتداوي","القرآن وعلومه"]},{"id":7045,"question":"ذكر السحر في المرتبة الثانية بعد الشرك بالله قبل القتل، مع عظم القتل، وهل هذا دليل على أن القتل أشنع، وقد قيل: إن القتيل يأتي يوم القيامة تقطر أوداجه دمًا؟","title":"عظم جرم السحر وأنه أعظم من القتل","answer":"الجواب:\n\nليس القتل بأشنع من الكفر، الكفر أعظم من القتل، لو كفر وقتل؛ لكان قتله أسهل من الشرك، الكافر له النار مخلدًا فيها أبد الآباد.\n\nوالقاتل قد يعفو الله عنه، ويخرج من النار، ويدخل الجنة إذا كان ما استحله، ولكن قتل بسبب الغضب، والنزاع، والأحقاد، أو الشحناء، أو ما أشبه ذلك، وأنه يعرف أن القتل حرام، ولكنه حمله الشيطان على أن قتل أخاه بسبب شحناء وعداوات بينهما، أو مخاصمات، أو مضاربة، أو ما أشبه ذلك، فهذا أتى جريمة عظيمة، ولكنها دون الكفر، هو موعود بالنار، وقد يعفو الله عنه؛ فلا يدخل النار، وإذا دخلها لا يخلد فيها إذا كان موحدًا لا يخلد، بل له نهاية خلود مؤقت، كما جاء في الآية الكريمة، ولكنه خلود مؤقت، خلود له نهاية؛ لأن الخلود خلودان في النار، الخلود خلودان: \n\nخلود لا نهاية له، وهذا خلود الكفار -نعوذ بالله- هذه حال الكفار، ليس لخلودهم فيها نهاية، بل أبد الآباد.\n\nوهناك خلود مؤقت، له نهاية، وهو خلود بعض العصاة، كما قال : وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] هذا الخلود غير مستمر، بل له نهاية، وهكذا قاتل نفسه، وهكذا الزاني موعود بالنار والخلود فيها، لكنه خلود له نهاية، ليس مثل خلود الكفار.\n\nفالحاصل: أن القتل دون السحر؛ لأن السحر كفر، ولا يتعاطاه الساحر إلا بعد كفره، وبعد عبادته للشياطين، ولهذا قرن بالشرك، وقال الله في حق السحرة: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ [البقرة:102].","link":"https://binbaz.org.sa/fatwas/3058/عظم-جرم-السحر-وانه-اعظم-من-القتل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1448.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7052,"question":"ما هي الطريقة الشرعية للوقاية من السحر؟","title":"الطرق الشرعية للوقاية من السحر","answer":"الجواب:\n\nمثل ما سمعتم في الندوة أن يسأل الله -جل وعلا- العافية، ويتعوذ بكلمات الله التامات من شر ما خلق، يقول النبي ﷺ: من قال: بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات لم يضره شيء.\n\nوكذلك إذا نزل بيتا فقال: أعوذ بكلمات الله التامات من شر ما خلق، لم يضره شيء حتى يرتحل من منزله ذلك ويكرر في الصباح والمساء أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات.\n\nكذلك يقرأ آية الكرسي بعد كل صلاة وعند النوم من أسباب السلامة  وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين بعد كل صلاة من أسباب السلامة، وبعد الفريضة والمغرب ثلاث مرات وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين هذه من أسباب السلامة.\n\nوذكر الله -جل وعلا- والإكثار من قراءة كتابه العظيم وسؤاله  أن يكفيك شر كل ذي شر من أسباب السلامة أعوذ بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة، كذلك أعوذ بكلمات الله التامات التي لا يجاوزها بر ولا فاجر، من شر ما خلق وذرأ وبرأ، ومن شر ما ينزل من السماء ومن شر ما يعرج فيها، ومن شر ما ذرأ في الأرض ومن شر ما يخرج منها، ومن شر طوارق الليل والنهار، ومن شر كل طارق إلا طارق يطرق بخير يا رحمن وهذه من التعوذات التي يقي الله بها العبد الشر.","link":"https://binbaz.org.sa/fatwas/3059/الطرق-الشرعية-للوقاية-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1449.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7056,"question":"مرض أخ لي فترة من الزمن، فترة طويلة جدًا، وذهبت به إلى كثير من المستشفيات، ولكن لم يستفد من كل ذلك، وبعد ذلك قالوا: إن عنده بعض سحر، فذهبت به إلى شخص يدعي أنه يعالج مرض السحر، وعالجه بطرق غريبة حسب طرقهم الخاصة والمعروفة للجميع، وقد شفي بإذن الله، وسؤالي هل أنا آثم في ذلك؟","title":"حكم إتيان السحرة والمشعوذين لعلاج السحر","answer":"الجواب:\n\nنعم إذا كان معروفًا أنه يتعاطى السحر، أو علم الغيب أنت آثم، فعليك التوبة إلى الله، والرجوع إليه، وعدم العودة، وإن كان يتعاطى القراءة، والآيات المباحة، لا بالسحر، ولا بخدمة الشياطين، ولا بادعاء علم الغيب؛ فلا بأس. \n\nأما من يعرف بأنه يدعي علم الغيب، ويقول: أصابك فلان، وحصل عليك كذا وكذا، في يوم كذا، وأنت أعطيت كذا يوم كذا، هذا كله دليل على أنه يخدم الشياطين، أو يكذب، يدعي علم الغيب، ويكذب، أو يخدم الشياطين، هذا لا يؤتى، ولا يسأل.\n\nيقول النبي ﷺ: من أتى عرافًا، فسأله عن شيء لم تقبل له صلاة أربعين يومًا رواه مسلم في الصحيح، وفي اللفظ الآخر: من أتى عرافًا، أو كاهنًا، فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، رواه أهل السنن بإسناد جيد. \n\nوقال أيضًا -عليه الصلاة والسلام-: ليس منّا من سحر، أو سحر له، وليس منّا من تطير، أو تطير له، وليس منّا من تكهن، أو تكهن له فلا يجوز للمسلم أن يسأل هؤلاء، قد يشفى المرض بأسباب كثيرة، وقد لا يشفى، فليس كل مريض يشفى، وليس كل مرض له دواء يشفى منه، قد يعالج له دواء، لكن ما قدر الله له الشفاء؛ لأن الحكمة المدة قد تمت، والأجل قد حضر، فالأدوية مشروطة بعدم وجود الأجل، أما إذا جاء الأجل ما تنفع الأدوية.","link":"https://binbaz.org.sa/fatwas/3062/حكم-اتيان-السحرة-والمشعوذين-لعلاج-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1451.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7058,"question":"هناك من أنواع المخدرات، نوع آخر استعمله البعض جهلًا، والبعض الآخر استعمله ليتقوى على مواصلة عمله، وهذا من تلبيس إبليس لعنه الله، ألا وهي الحبوب المنبهة، مع العلم أنه ما يعقب أكلها، أي بعد انتهاء مفعولها تتحول إلى العكس، والمشكلة أن أكثر من يستعملها يعتد بعدم تحريمها، نرجو من سماحتكم الرأي؟","title":"حكم استعمال الحبوب المنبهة","answer":"الجواب:\n\nهذه يجب منعها؛ لأنها تجعل الإنسان شبه نائم، وهو ليس بنائم، هي تجعله شبه مستيقظ، وهو ليس مستيقظ، في حكم النائم، كم من حوادث وقعت بسبب ذلك! فالحبوب التي تطرد النوم؛ تجعل صاحبها في صورة اليقظان، وهو في حكم النائمين، فقد يدعس بعض الناس، وقد يصدم بعض الناس؛ بسبب عدم حضور عقله وضبطه، هذه الحبوب ينبغي منعها، الواجب منعها وعدم إقرارها، وعدم تعاطيها.","link":"https://binbaz.org.sa/fatwas/3055/حكم-استعمال-الحبوب-المنبهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1446.mp3","categories":["الطب والتداوي"]},{"id":7064,"question":"ما رأي سماحتكم في رجل استعمل الرقية، ولم ير أنها تنفعه، فيؤول إلى السحر، ويقول: إنه لا يضر ذلك ما دام أنه لا يسبب شيئًا من المشاكل؟","title":"حكم إتيان السحرة لمعالجة المرضى","answer":"الجواب:\n\nمثل ما تقدم، مثل ما سمعت، السحر منكر وكفر، وإذا كان ما ينفعك في القراءة فقد الطب بعد ما ينفع، حتى الطب نفسه الذي هو معروف عند الأطباء، ما كل علاج ينفع، ويحصل به المقصود، قد يؤجل الله الشفاء إلى مدة طويلة، وقد يموت الإنسان بهذا المرض، ليس من شرط العلاج أن يشفى الإنسان. \n\nفليس له عذر إذا عالج عند إنسان بالقراءة، يقول: أروح للسحرة، لا، يعالج عند ثان مثل ما عالج عند طبيب ثاني، يقرأ في يديه عند النوم قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات كما كان النبي يفعل -عليه الصلاة والسلام- كان إذا مسه مرض؛ قرأ في يديه قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات، ثم يمسح بهما ما أقبل من جسده، وجهه وصدغيه وصدره، هكذا أخبرت عائشة -رضي الله عنها- أنه كان يفعل هذا -عليه الصلاة والسلام- فلما مرض، وعجز عن ذلك؛ صارت تقرأ في يديه هي، وتمسح بهما على وجهه وصدره -عليه الصلاة والسلام-.\n\nفالمقصود: أن هذا علاج ،يقرأ في يديه، أو يطلب من بعض إخوانه أن يقرؤون عليه؛ لا بأس، وإذا قرأ هو يكون أنفع، يقرأ في يديه الفاتحة وقُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين، آية الكرسي، يقرأ ويمسح ولو ألف مرة، ولو آلاف، الحمد لله لا ييأس، يقرأ ويسأل ربه الشفاء والعافية.\n\nالسؤال: سبق أن أخبرت بشأن الساحر الموجود في منطقة القنفذة ببلدة الحبيل، وإلى ذلك هذا الرجل يعمل عمله الخبيث، وبعدما طلع من السجن الآن يتحدى ويقول: الكتب التي أخذت مني أحفظها عن ظهر قلب، أو عن غيب، وهو رجل كبير السن، يبلغ من العمر ثمانين عامًا، وقد سبق من سماحة الشيخ ابن باز بقوله: بأنه أقدم حتى يحصل العثور عليه، ومتى وهذا الرجل لم ينته، بل يتحدى كل شيء الآن، نحن والله مغلوبون منه، نرجو من الله، ثم من سماحتكم المساعدة؟\n\nالجواب: الذي يعرفه يجينا البيت؛ حتى يسميه باسمه، الذي يعرفه، تعرفه يا شيخ محمد؟\n\nالطالب: نعم الحبيل معروف. \n\nالجواب: تعرف الرجل؟\n\nالطالب: الرجل ما أعرفه.\n\nالجواب: الذي كتب هذا إذا كان يعرفه يجينا، يسميه حتى نكتب للقاضي.\n\nالطالب: .. الرجل معروف زيد بن عبده ... معروف محله ومعروف..\n\nالجواب: لعل الشيخ أحمد يذكرنا يوم السبت، إن شاء الله، بارك الله فيك.","link":"https://binbaz.org.sa/fatwas/3056/حكم-اتيان-السحرة-لمعالجة-المرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1447.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7070,"question":"ذكر السحر في المرتبة الثانية بعد الشرك بالله قبل القتل، مع عظم القتل، وهل هذا دليل على أن القتل أشنع، وقد قيل: إن القتيل يأتي يوم القيامة تقطر أوداجه دمًا؟","title":"عظم جرم السحر وأنه أعظم من القتل","answer":"الجواب:\n\nليس القتل بأشنع من الكفر، الكفر أعظم من القتل، لو كفر وقتل؛ لكان قتله أسهل من الشرك، الكافر له النار مخلدًا فيها أبد الآباد.\n\nوالقاتل قد يعفو الله عنه، ويخرج من النار، ويدخل الجنة إذا كان ما استحله، ولكن قتل بسبب الغضب، والنزاع، والأحقاد، أو الشحناء، أو ما أشبه ذلك، وأنه يعرف أن القتل حرام، ولكنه حمله الشيطان على أن قتل أخاه بسبب شحناء وعداوات بينهما، أو مخاصمات، أو مضاربة، أو ما أشبه ذلك، فهذا أتى جريمة عظيمة، ولكنها دون الكفر، هو موعود بالنار، وقد يعفو الله عنه؛ فلا يدخل النار، وإذا دخلها لا يخلد فيها إذا كان موحدًا لا يخلد، بل له نهاية خلود مؤقت، كما جاء في الآية الكريمة، ولكنه خلود مؤقت، خلود له نهاية؛ لأن الخلود خلودان في النار، الخلود خلودان: \n\nخلود لا نهاية له، وهذا خلود الكفار -نعوذ بالله- هذه حال الكفار، ليس لخلودهم فيها نهاية، بل أبد الآباد.\n\nوهناك خلود مؤقت، له نهاية، وهو خلود بعض العصاة، كما قال : وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93] هذا الخلود غير مستمر، بل له نهاية، وهكذا قاتل نفسه، وهكذا الزاني موعود بالنار والخلود فيها، لكنه خلود له نهاية، ليس مثل خلود الكفار.\n\nفالحاصل: أن القتل دون السحر؛ لأن السحر كفر، ولا يتعاطاه الساحر إلا بعد كفره، وبعد عبادته للشياطين، ولهذا قرن بالشرك، وقال الله في حق السحرة: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ [البقرة:102].","link":"https://binbaz.org.sa/fatwas/3058/عظم-جرم-السحر-وانه-اعظم-من-القتل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1448.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7083,"question":"أخت مسلمة تقول عندي خمسة أولاد، وأنا أتغير عند كل ولادة، وذهبت إلى إحدى المستشفيات بالمملكة، ولا أجد علاجًا إلا استعمال حبوب توقف الحمل، علمًا بأني أصلي، وأصوم، وأخاف الله أن علي شيء في ذلك، أفتونا جزاكم الله خيرًا؟","title":"حكم استخدام المرأة حبوب منع الحمل","answer":"الجواب:\n\nعند الضرورة لا بأس بأخذ الحبوب مؤقتًا، إذا كان هناك مرض، وتعب للرحم بسبب الولادة، أو إجراء عملية؛ فلا مانع من أخذ الحبوب وقتًا دون وقت، كوقت الرضاع سنة أو سنتين؛ حتى يستريح الرحم بعض الراحة، فهذا يحتاج إلى مراجعة الأطباء العارفين، واتفاق مع الزوج في ذلك، إذا اتفقتما وصار هناك ضرر فيوقت، تؤخذ الحبوب بقدر محدود؛ حتى يزول الأثر الذي يحصل به الضرر.","link":"https://binbaz.org.sa/fatwas/3087/حكم-استخدام-المراة-حبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1468.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":7125,"question":"أخبرك يا سماحة الشيخ أنني أحبك في الله، أطال الله في عمرك على طاعته، أخبرك أنني اطلعت على كتاب روائع البيان، للشيخ ابن الشيخ محمد بن علي الصابوني جزء واحد، وعند تفسيره لقوله تعالى: وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ [البقرة:102] إلى آخر الآيات قال: إن السحر نوعان:فمن تعلمه ليتوقى به ضرر، أو يدفع أذاه عن الناس؛ فقد نجا، وثبت على الإيمان، ومن تعلمه معتقدًا صحته؛ ليلحق الأذى بالناس؛ فقد ضل وكفر، فكان الناس فريقين، فريق تعلمه عن نية صالحة؛ ليدفع ضرره عن الناس، ويطلب من سماحتكم بيان ذلك حتى لا يعني؟","title":"تعلم السحر وتعليمه للناس منكر لا يجوز","answer":"الجواب:\n\nوالجواب: أن حبك لي في الله، فأقول: أحبك الله الذي أحببتنا له، ونسأل الله أن يجعلنا وإياكم جميعًا من المتحابين في الله  فقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: يقول الله يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظل إلا ظلي نسأل الله أن يجعلنا وإياكم منهم. \n\nوأما هذا الكتاب \"روائع البيان\" للصابوني ما اطلعت عليه، ولكن إذا كان أجاز فيه تعلم السحر؛ فقد أخطأ وغلط، لا يجوز تعلم السحر، ولو حسن قصد المتعلم؛ لأن تعلم السحر لا يكون إلا بالكفر بالله -نعوذ بالله- لا يكون إلا بعبادة الشياطين، والتقرب إلى الشياطين، وحتى يعلموه ما غمض من علم الغيب بزعمهم.\n\nفالمقصود: أن تعلم السحر، وتعليمه للناس منكر، لا يجوز عند أهل العلم، سواء قاله الصابوني، أو غير الصابوني، هذا لا يجوز أبدًا، بل هو منكر، وقد غلط، وأفحش إن كان قال هذا الكلام.\n\nالسؤال: ما رأيك بالكتاب يا شيخ؟\n\nالجواب: ما اطلعت عليه، لكن إذا كان فيه هذا، فهذا غلط منكر.","link":"https://binbaz.org.sa/fatwas/3148/تعلم-السحر-وتعليمه-للناس-منكر-لا-يجوز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1506.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7178,"question":"بعض أئمة المساجد والشيوخ يقرؤون على الناس بآيات من القرآن والدعاء، فيعلموهم ماذا أصابهم، فبعضهم يقول له: أصابك سحر، وبعضهم يقول: أصابتك عين، إلى غير ذلك من الكلام الذي يقولون، فما حكمكم في هؤلاء، وحكم الذهاب إليهم، وحكم التصديق بهم؟ وهل ما يقولون صحيحًا؟","title":"معرفة السحر والعين من خلال الخبرة","answer":"الجواب:\n\nإذا كان طالب العلم الذي يرقي الناس قد اعتاد علامات يعرفها مما يصيب المسحور، أو علامات يعرف بها العين؛ فلا بأس بذلك، يقرأ عليه ما يسر الله من كتاب الله، كالفاتحة، وآية الكرسي، وقل هو الله أحد، والمعوذتين، أو غيرها من الآيات، الله جعل القرآن شفاء من العين، ومن السحر أيضًا، حتى قال ﷺ: لا رقية إلا من عين أو حمة. \n\nقال العلماء: معنى لا رقية أولى وأشفى، أو لا أولى وأنفع إلا من عين أو حمة، والعين هي النظرة يسمونها النظرة، هي النفس، والحمة السم من ذوات السموم، وقال -عليه الصلاة والسلام-: لا بأس بالرقى ما لم تكن شركًا وقد رَقى ورُقي -عليه الصلاة والسلام- وأمر أن يرقى أولاد جعفر وقال: إنها أصابتهم العين قال لأمهم: إنها أصابتهم العين فأمرها أن تسترقي لهم، فالرقية نافعة من العين. \n\nفإذا كان طالب العلم المعروف بالعقيدة الصالحة أنه جرب هذه الأمور، ورأى أن ما في فلان أنه مما يعرف أنه عين، أو أنه سحر، مسحور، فيتعاطى بعلاج السحر، أو علاج العين، النبي  قال: العين حق، ولو أن شيئًا سبق القضاء؛ لسبقته العين وقال: استغسلوا فإذا عرف العائن يستغسل، يطلب منه أن يغسل وجهه، ويتمضمض، ويغسل داخلة إزاره، وأطراف يديه ورجليه، حتى يصب على المعين، وهو يشفى بإذن الله، أو يرفع بما يسر الله من القرآن، من الفاتحة، وآية الكرسي، وغير ذلك، والغالب أنه ينفعه ذلك بإذن الله.\n\nوهكذا المسحور يرقى بالفاتحة، وآية الكرسي، وآية السحر التي في سورة الأعراف، ويونس، وطه تقرأ في ماء له مع القواقل -قل يا أيها الكافرون، قل هو الله أحد، والمعوذتين- ويشرب منه بعض الشيء، ويغتسل بالباقي، فينفع الله بذلك كثيرًا ممن يصاب بالسحر.\n\nوالسحر واقع يقع كثيرًا، كما قال الله -جل وعلا-: وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ [البقرة:102]. \n\nفالسحر واقعن وكثير من الناس منه ما يقتل، ومنه ما يمرض، ومنه ما يغير العقل، لهم فيه أنواع من التصرفات، فيستعينون بالجن والشياطين في ذلك، وقد وقع هذا في عهد موسى -عليه الصلاة والسلام- وقام سحرة فرعون بجمع العصي، والحبال  على أعين الناس، وسحروا أعينهم؛ حتى ظن الناس أن هذه العصي، وهذه الحبال حيات يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66] فلما ألقى موسى عصاه لقفتهان وأخذتها كلها، وعرف الناس بطلان هذا السحر، وخر السحرة سجدا لله  وتابوا وأنابوا إلى الله .\n\nوالمقصود: أن هذا له علاج، فإذا عرف بالعلامات التي اعتادها أنه سحر؛ استعمل الرقية من السحر، وذكر بعض المتقدمين أن من أسباب العلاج، وأن مما يدخل في العلاج سبع ورقات سدر، تدق وتجعل في الماء أيضًا، وأن هذا أيضًا قد ينفع بإذن الله من أمر السحر.\n\nوهكذا في أمر الرجل الذي يحبس عن زوجته، ويمنع من زوجته إذا قرئ له هذه الآيات مع الفاتحة، مع آية الكرسي، مع قل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، وشرب منه، واغتسل بالباقي، فالغالب أنه يزول أثره ويطلق حبسه.","link":"https://binbaz.org.sa/fatwas/3220/معرفة-السحر-والعين-من-خلال-الخبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1565.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7179,"question":"بعض أئمة المساجد والشيوخ يقرؤون على الناس بآيات من القرآن والدعاء، فيعلموهم ماذا أصابهم، فبعضهم يقول له: أصابك سحر، وبعضهم يقول: أصابتك عين، إلى غير ذلك من الكلام الذي يقولون، فما حكمكم في هؤلاء، وحكم الذهاب إليهم، وحكم التصديق بهم؟ وهل ما يقولون صحيحًا؟","title":"حكم تشخيص الرقاة للمصابين","answer":"الجواب:\n\nإذا كان طالب العلم الذي يرقي الناس قد اعتاد علامات يعرفها مما يصيب المسحور، أو علامات يعرف بها العين؛ فلا بأس بذلك، يقرأ عليه ما يسر الله من كتاب الله، كالفاتحة، وآية الكرسي، وقل هو الله أحد، والمعوذتين، أو غيرها من الآيات، الله جعل القرآن شفاء من العين، ومن السحر أيضًا، حتى قال ﷺ: لا رقية إلا من عين أو حمة. \n\nقال العلماء: معنى لا رقية أولى وأشفى، أو لا أولى وأنفع إلا من عين أو حمة، والعين هي النظرة يسمونها النظرة، هي النفس، والحمة السم من ذوات السموم، وقال -عليه الصلاة والسلام-: لا بأس بالرقى ما لم تكن شركًا وقد رَقى ورُقي -عليه الصلاة والسلام- وأمر أن يرقى أولاد جعفر وقال: إنها أصابتهم العين قال لأمهم: إنها أصابتهم العين فأمرها أن تسترقي لهم، فالرقية نافعة من العين. \n\nفإذا كان طالب العلم المعروف بالعقيدة الصالحة أنه جرب هذه الأمور، ورأى أن ما في فلان أنه مما يعرف أنه عين، أو أنه سحر، مسحور، فيتعاطى بعلاج السحر، أو علاج العين، النبي  قال: العين حق، ولو أن شيئًا سبق القضاء؛ لسبقته العين وقال: استغسلوا فإذا عرف العائن يستغسل، يطلب منه أن يغسل وجهه، ويتمضمض، ويغسل داخلة إزاره، وأطراف يديه ورجليه، حتى يصب على المعين، وهو يشفى بإذن الله، أو يرفع بما يسر الله من القرآن، من الفاتحة، وآية الكرسي، وغير ذلك، والغالب أنه ينفعه ذلك بإذن الله.\n\nوهكذا المسحور يرقى بالفاتحة، وآية الكرسي، وآية السحر التي في سورة الأعراف، ويونس، وطه تقرأ في ماء له مع القواقل -قل يا أيها الكافرون، قل هو الله أحد، والمعوذتين- ويشرب منه بعض الشيء، ويغتسل بالباقي، فينفع الله بذلك كثيرًا ممن يصاب بالسحر.\n\nوالسحر واقع يقع كثيرًا، كما قال الله -جل وعلا-: وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ [البقرة:102]. \n\nفالسحر واقعن وكثير من الناس منه ما يقتل، ومنه ما يمرض، ومنه ما يغير العقل، لهم فيه أنواع من التصرفات، فيستعينون بالجن والشياطين في ذلك، وقد وقع هذا في عهد موسى -عليه الصلاة والسلام- وقام سحرة فرعون بجمع العصي، والحبال  على أعين الناس، وسحروا أعينهم؛ حتى ظن الناس أن هذه العصي، وهذه الحبال حيات يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66] فلما ألقى موسى عصاه لقفتهان وأخذتها كلها، وعرف الناس بطلان هذا السحر، وخر السحرة سجدا لله  وتابوا وأنابوا إلى الله .\n\nوالمقصود: أن هذا له علاج، فإذا عرف بالعلامات التي اعتادها أنه سحر؛ استعمل الرقية من السحر، وذكر بعض المتقدمين أن من أسباب العلاج، وأن مما يدخل في العلاج سبع ورقات سدر، تدق وتجعل في الماء أيضًا، وأن هذا أيضًا قد ينفع بإذن الله من أمر السحر.\n\nوهكذا في أمر الرجل الذي يحبس عن زوجته، ويمنع من زوجته إذا قرئ له هذه الآيات مع الفاتحة، مع آية الكرسي، مع قل يا أيها الكافرون، وقل هو الله أحد، والمعوذتين، وشرب منه، واغتسل بالباقي، فالغالب أنه يزول أثره ويطلق حبسه.","link":"https://binbaz.org.sa/fatwas/3221/حكم-تشخيص-الرقاة-للمصابين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1432.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":7297,"question":"والدي مريض، وطلب مني أن أكويه، وبعد مدة توفي من ذلك المرض، فهل يلحقني إثم من ذلك إذا لم أقم بكيه؟","title":"حكم العلاج بالكي وما يترتب عليه","answer":"الجواب: إذا عالج الولد أباه عند الأطباء، أو طلب منه أبوه أن يكويه، وتحرى أن هذا الكي مناسب؛ فلا حرج في ذلك، وليس عليه شيء لو مات؛ لأن الكي من أسباب الشفاء، يقول النبي ﷺ: الشفاء في ثلاثة: كية نار، أو شرطة محجم، أو شربة عسل الحديث. المقصود: أنه إذا مات بعد ذلك لا يقال بسبب الكي، هذا أجله تم، وليس عليك بأس في علاجه، وفي كيه لما طلب منك ذلك، أو إحضار الطبيب له، أو ما أشبه ذلك، نسأل الله أن يوفق الجميع.","link":"https://binbaz.org.sa/fatwas/3376/حكم-العلاج-بالكي-وما-يترتب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1694.mp3","categories":["الطب والتداوي"]},{"id":7344,"question":"لي أخ في الله أصابه مرض شديد، وقلت له: اذهب إلى الطبيب؛ لتأخذ العلاج، وتشفى -بإذن الله- فقال: الحمد لله الذي أغناني عنهم، إن الله رتب على هذا المرض أجرًا عظيمًا، وسيكفيني هذا الأمر، فهل هو مصيب، أم  مخطئ؟","title":"حكم ترك المداواة بالعلاج طلباً للأجر","answer":"الجواب: لا حرج عليه، ترك الدواء لا بأس، لكن الأفضل له التداوي، وله الصبر على المرض لأجل طلب الأجر، فلا بأس، لكن الأفضل له والأولى به أن يأخذ الدواء، يعالج؛ لأن تعاطي الأسباب أمر مشروع، والنبي ﷺ تداوى، وتداوى الصحابة وهم أفضل الناس، فالتداوي أفضل. والنبي ﷺ يقول: لكل داء دواء، فإذا أصيب الدواء الداء؛ برء بإذن الله، ما أنزل الله من داء إلا أنزل له شفاء هذه أسباب، فقد يعافى المريض، وينفع السبب، وقد يموت؛ لأنه تم أمره، تمت حسبته، لكن إذا أراد الله -جل وعلا- أنه يشفى؛ جعل له سببًا، وإذا كانت المنية قد حضرت، والأجل قد انتهى، ما نفعت الأسباب، انتهى كل شيء.","link":"https://binbaz.org.sa/fatwas/3439/حكم-ترك-المداواة-بالعلاج-طلبا-للاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1746.mp3","categories":["الطب والتداوي"]},{"id":7345,"question":"تغيب أخي عن المنزل منذ مدة، وبحثنا عنه في كل مكان بواسطة الشرطة، وعن طريقنا، وفي المستشفيات، ولكننا لم نجد له أثرًا أبدًا، فأخذت أبحث أنا وبعض الناس عن الموضوع، فنصحوني بأن أخبر سماحتكم عن الموضوع؛ لأنهم قالوا لي: ربما اهتم الشيخ بالموضوع، ويرى رؤيا تدلكم على مكانه، أما القسم الآخر فقالوا لي: اذهب إلى أي ساحر؛ لكي يخبرني عن مكانه فقط، ولكن رفضت كلا الافتراضين خوفًا من حرمتهما، نرجو أن تخبرونا إلى الطريق السليم أثابكم الله؟","title":"حكم الذهاب إلى السحرة والكهنة","answer":"الجواب: أما الذهاب إلى السحرة والكهنة فلا يجوز، قال النبي ﷺ: من أتى عرافًا فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا وقال: من أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام وسئل عن الكهان فقال: لا تأتوهم، وقال: ليسوا بشيء فقالوا له: قد يصدقون؟ فقال: تلك الكلمة يسمعها الجني من السماء فيقرها في أذن وليه من الإنس، فيكذب معها مائة كذبة، وفي لفظ آخر: أكثر من مائة كذبة فلا يجوز سؤالهم ولا إتيانهم.  لكن بالإمكان سؤال الناس في مجامع الناس، بإمكان الكتابة في الجرايد والصحف، من رأى فلانًا وصورته كذا وصورته كذا؟ قد يقرأ الجريدة بعض الناس، ويكون عنده خبر أو يسمع الجريدة هو في أي مكان، المقصود بالإذاعة والصحف المحلية أو الصحف الأخرى في البلد التي تظن أنه ذهب إليها، وكذلك مجامع الناس، فينطبق عليه ما ينطبق على الضالة، من رأى فلانًا وصفته كذا وكذا وكذا، أما الرؤيا فقد تقع الرؤيا من بعض الناس، قد تنفع الرؤيا، الرؤيا جزء من ستة وأربعين جزءًا من النبوة، ذهبت النبوة وبقيت المبشرات، قد تقع في بعض الناس، ويستدل ...","link":"https://binbaz.org.sa/fatwas/3433/حكم-الذهاب-الى-السحرة-والكهنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1741.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7356,"question":"تغيب أخي عن المنزل منذ مدة، وبحثنا عنه في كل مكان بواسطة الشرطة، وعن طريقنا، وفي المستشفيات، ولكننا لم نجد له أثرًا أبدًا، فأخذت أبحث أنا وبعض الناس عن الموضوع، فنصحوني بأن أخبر سماحتكم عن الموضوع؛ لأنهم قالوا لي: ربما اهتم الشيخ بالموضوع، ويرى رؤيا تدلكم على مكانه، أما القسم الآخر فقالوا لي: اذهب إلى أي ساحر؛ لكي يخبرني عن مكانه فقط، ولكن رفضت كلا الافتراضين خوفًا من حرمتهما، نرجو أن تخبرونا إلى الطريق السليم أثابكم الله؟","title":"حكم الذهاب إلى السحرة والكهنة","answer":"الجواب: أما الذهاب إلى السحرة والكهنة فلا يجوز، قال النبي ﷺ: من أتى عرافًا فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا وقال: من أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام وسئل عن الكهان فقال: لا تأتوهم، وقال: ليسوا بشيء فقالوا له: قد يصدقون؟ فقال: تلك الكلمة يسمعها الجني من السماء فيقرها في أذن وليه من الإنس، فيكذب معها مائة كذبة، وفي لفظ آخر: أكثر من مائة كذبة فلا يجوز سؤالهم ولا إتيانهم.  لكن بالإمكان سؤال الناس في مجامع الناس، بإمكان الكتابة في الجرايد والصحف، من رأى فلانًا وصورته كذا وصورته كذا؟ قد يقرأ الجريدة بعض الناس، ويكون عنده خبر أو يسمع الجريدة هو في أي مكان، المقصود بالإذاعة والصحف المحلية أو الصحف الأخرى في البلد التي تظن أنه ذهب إليها، وكذلك مجامع الناس، فينطبق عليه ما ينطبق على الضالة، من رأى فلانًا وصفته كذا وكذا وكذا، أما الرؤيا فقد تقع الرؤيا من بعض الناس، قد تنفع الرؤيا، الرؤيا جزء من ستة وأربعين جزءًا من النبوة، ذهبت النبوة وبقيت المبشرات، قد تقع في بعض الناس، ويستدل ...","link":"https://binbaz.org.sa/fatwas/3433/حكم-الذهاب-الى-السحرة-والكهنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1741.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":7457,"question":"هل يجوز للطبيب أن يكشف على المرأة؟","title":"هل يجوز للطبيب أن يكشف على المرأة؟","answer":"الجواب: إذا دعت الحاجة إلى ذلك؛ فلا بأس، وإن كان في طبيبة تكشف فهي أولى وأحسن، لكن إن كان في طبيبة تعرف أمراض النساء وإلا جاز للطبيب أن يكشف على النساء للحاجة.  وهنا شيء ينبغي التنبيه عليه عند ذكر الصوم، كثير من المرضى إذا جاء المرض يتساهل في الصلاة، وربما قال أؤخرها حتى أشفى، حتى أصلي على بصيرة، وهذا غلط، الصوم يؤخر؛ لأن المريض لا يستطيع، لكن الصلاة لا تؤخر، يجب أن يصلي المريض على حسب حاله، ولو أنه على جنبه، ولو أنه مستلق يصلي على حسب حاله بالإيماء بالنية، ولا يجوز له التأخير.  قال النبي ﷺ لعمران بن حصين وهو مريض: صل قائمًا فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب أخرجه البخاري في الصحيح، وزاد النسائي في سننه: فإن لم تستطع فمستلقيًا.  فالمريض هكذا إن قدر على القيام؛ صلى قائمًا، وإن عجز؛ صلى قاعدًا، يصلي وهو قاعد، يركع في الهواء، ثم يسجد في الأرض إن استطاع حتى يكمل صلاته، فإن عجز صلى على جنبه، والأفضل يصلي على جنبه الأيمن، فإن عجز؛ صلى مستلقيًا، يكبر ويقرأ ويكبر ويركع بالنية، ويقول: سبحان ربي العظيم، ويقول: سمع الله لمن حمده، ويرفع بالنية، ويقول: ربنا ولك الحمد، ثم يكبر ويسجد بالنية ويقول: سبحان ربي الأعلى، ثم يرفع ويقول: ربي اغفر لي، ثم يسجد ويقول: سبحان ربي الأعلى بالنية، وهكذا حتى يكمل صلاته وهو على جنبه أو مستلقٍ، وليس له التأخير أبداً، بل يصلي على حسب حاله الفريضة والنوافل، ويتعبد وهو على حاله.  وإذا كان هناك مشقة في الوضوء؛ تيمم بالتراب إذا ما تيسر الوضوء؛ يتيمم بالتراب، يؤتى له بالتراب في إناء، أو في خرقة، وتكون عنده، فيتيمم منه عند الحاجة، وكذلك قضاء الحاجة إذا قضى حاجته يمسح بالخرق والمناديل، ولا حاجة إلى الماء، بل يمسح دبره وقبله بالمناديل حتى يزال الأذى ثلاث مرات، أو أكثر، حتى يزال الأذى عنه ويكفي ذلك.  وهكذا فراشه إن تيسر إبداله بفراش طاهر يصلي عليه وجب، فإن لم يتيسر فراش طاهر يصلي على حسب حاله على فراش نفسه، ولو كان فيه النجاسة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] والنبي -عليه الصلاة والسلام- يقول: إذا أمرتكم بأمر فأتوا منه ما استطعتم. فينبغي التنبيه على هذا، كل من يزور مريضًا، أو عنده مريض، أو يعود مريضًا ينبهه على هذه الأشياء، لا يؤجل الصلاة،  ولا بأس أن يصلي الظهر والعصر جميعًا والمغرب والعشاء جميعًا لأجل المشقة عليه.","link":"https://binbaz.org.sa/fatwas/30445/هل-يجوز-للطبيب-ان-يكشف-على-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_185_2.mp3","categories":["الطب والتداوي"]},{"id":7527,"question":"هذه الرسالة من الأردن؛ المملكة الأردنية الهاشمية. الزرقاء. مديرية شرطة الزرقاء، العريف/ عبد القادر صلاح .. في الحقيقة الأخ/ عبد القادر يعرض مشكلة مالية فيما أعتقد، يقول: ما حكم الدين في علاج أو في علاجات منع الحمل واستعمالها، حيث إنني متزوج ولي أطفال وأن الطفل عندي لما يولد لا يرضع من أمه؛ لأنه لا يوجد بها حليب، وتتم تغذية الطفل بواسطة علب الحليب المجفف مما يؤدي باستمرار إلى إصابة الطفل في النهاية بالتهابات واضطرابات نتيجة هذه التغذية، مما يضطرون إلى مراجعة الطبيب والصيدلية التي تعتبر مراجعتها إرهاب بسبب ارتفاع التكاليف، حتى أني أعجز عن تأمين مصروف العائلة الشهري؛ بسبب ارتفاع الأسعار وارتفاع تكاليف المعيشة التي لا تطاق، وأريد أن أعرف رأي الدين في استعمال علاجات منع الحمل حتى أستعملها، حتى أستطيع تأمين الحياة لعائلتي التي أجد مشقة في تأمين احتياجاتها الضرورية، وإذا كان الدين لا يسمح في استعمال العلاجات فما لي سوى أن أعتزل زوجتي، لذلك أرجو أن تتفضلوا علي بالإجابة، والسلام عليكم ورحمة الله وبركاته؟","title":"ضوابط أخذ حبوب منع الحمل","answer":"الجواب: علاج منع الحمل كثير، لكن هناك حبوب معروفة يعرفها الأطباء إذا تناولتها المرأة لأجل عدم توالي الحمل لمدة سنة أو سنتين، لا بأس بذلك عند الحاجة إلى هذا لا حرج في ذلك، وإن أرضعت الطفل ولم تتركه للحليب المجفف فذلك أفضل لها إذا تيسر أنها ترضعه وحصل فيها لبن، كونها ترضعه هذا من أسباب عدم حملها، ما دامت ترضعه حتى تفطمه، هذا هو الغالب بإذن الله، إذا كانت ترضع فإنها لا تحمل في الغالب، فترضعه وتكفي زوجها مئونة التعب في الصيدليات، وشراء الحاجات الأخرى، فإذا قدر أنها ليس فيها حليب فإنه يعتني بما يجب حول الطفل، وسوف يعطيه الله من فضله  وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا * وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرً [الطلاق: 4].\nفعلى والد الطفل أن يستعين بالله، وأن يسأله من فضله، وأن يتعاطى الأسباب الجيدة، أسباب الرزق وله البشرى، سوف يعطيه الله من فضله سبحانه وتعالى، ولا بأس أن تتعاطى المرأة الحبوب التي تمنع الحمل لمدة سنة أو سنتين رفقاً بالوالد عن توالي الحمل، ورفقاً بها أيضاً عن مشقة الحمل، هذا بعد هذا بسرعة، لا حرج في هذا إن شاء الله، وإن صبرت على الحمل وصبر هو على الحمل ولو توالى فهذا خير إلى خير، ولعل الله يخرج من أصلابهم من يعبد الله وينفع المسلمين.\nفالحاصل: أن تعاطي حبوب الحمل لا بأس بها عند الحاجة إليها لكن لا يطول، مدة سنة أو سنتين ثم تترك حتى تحمل وحتى يكثر الأولاد، والله هو الرزاق، ما ينبغي للوالد أن ..... مشقة من المئونة، فإن الله سوف ييسرها ويعينه عليها إذا لجأ إليه واستعان به سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/4501/ضوابط-اخذ-حبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_010/01005.mp3","categories":["الطب والتداوي","قضايا المرأة"]},{"id":7617,"question":"هذه الرسالة من المقدم المواطن عبد المعين حمادي محمد المطرفي من مكة المكرمة، يقول في رسالته: أنه تلف أحد أسنانه وأراد أن يعوضه بسن صناعي، ولكن مركب الأسنان تعذر ذلك، إلا بتلبيس الذي يليه ذهباً لكي يقوم بتثبيته، فهل يأثم ذلك الرجل على تلبيس هذا السن ذهباً، علماً أنه لا يريده للزينة، وإنما أجبرته الضرورة على ذلك، أفيدونا أثابكم الله؟","title":"حكم استخدام الذهب للضرورة كالتطبيب","answer":"الجواب: لا حرج في ذلك، اتخاذ السن لحاجة أو ربطه بالذهب لحاجة لا بأس بذلك ولا حرج، إنما المحرم أن يتخذه للزينة، أما إذا اتخذه للحاجة إليه فلا حرج في ذلك. نعم. \nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4670/حكم-استخدام-الذهب-للضرورة-كالتطبيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_023/02306.mp3","categories":["الطب والتداوي"]},{"id":7693,"question":"أيضاً يقول: إذا مات رجل أو امرأة وهو كافر، هل يمكن أن نقول: إنا لله وإنا إليه راجعون، أو لا يجوز، ونقول أيضاً: يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ۝ ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً [الفجر:27-28].. إلى آخره؟","title":"حكم قول: {يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ} إذا مات الكافر","answer":"الجواب: الكافر إذا مات لا بأس أن تقول: إنا لله وإنا إليه راجعون، الحمد لله، من أقربائك لا بأس، كل الناس إلى الله راجعون، كل الناس ملك لله سبحانه وتعالى، لا بأس بهذا، ولكن لا يدعى له، ما دام كافر لا يدعى له، ولا يقال: يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ۝ ارْجِعِي لأن النفس ما هي مطمئنة، نفس فاجرة، ما يقال لها، وإنما يقال هذا في المؤمن. \nفالحاصل أن الكافر إذا مات لا بأس أن تقول: إنا لله وإنا إليه راجعون ولا بأس أن يقول لك غيرك: أعظم الله أجرك فيه، وأحسن عزاءك فيه، ما في بأس، قد يكون لك مصلحة في حياته، قد يكون في حياته يحسن إليك، ينفعك فلا بأس، لكن لا يدعى له ولا يستغفر له، ولا يتصدق عنه إذا مات كافراً. نعم.","link":"https://binbaz.org.sa/fatwas/4892/حكم-قول-يا-ايتها-النفس-المطمىنة-اذا-مات-الكافر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_028/02804.mp3","categories":["مسائل متفرقة في الجنائز","الطب والتداوي"]},{"id":7707,"question":"هذا السؤال يا سماحة الشيخ وردنا من عيظة بن محمد سراج الحارثي يقول: من وادي ميسان إلى فضيلة الشيخ عبد العزيز بن باز نفيدكم بأن فيه بئر واقعة بين المدينة المنورة وحائل، والناس يتجمعون من كل مكان إليها، يريدون الشفاء من مائها، يزعمون أنها تزيل جميع الأمراض مثل الجرب والحساسية والشلل.. إلى آخره، يقول: أفيدونا مشكورين عن حكم التوجه إليها؟","title":"حكم الذهاب إلى البئر التي بين المدينة وحائل للعلاج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: \nهذه البئر الذي سأل عنها الأخ عيظة قد سأل عنها غيره، وقد تأملنا ما نقل عنها وما رآه من يستعمل ماءها، فاتضح لنا من ذلك أنها تفيد في مواضع كثيرة، وأن الله جل وعلا قد جعل في مائها شفاء لبعض الأمراض الجلدية والحساسية، ولا نرى مانعاً من استشفاء الناس بهذا الماء الذي جعل الله فيه بركة ونفع للمسلمين، وإن كانت قد تضر آخرين؛ لأنهم يستعملونها في أشياء لا تناسبهم. \nفالحاصل أنها فيها فائدة للكثير من الأمراض، ولا حرج في الاستفادة منها لمن وجد منها فائدة وأحس بجدوى، فلا حرج في ذلك، مثل ما يستعمل بقية الأدوية، فالله جل وعلا جعل لكل داء دواء كما في الحديث الصحيح، يقول النبي ﷺ: ما أنزل الله داء إلا أنزل له شفاء، علمه من علمه وجهله من جهله فهذا الماء فيه شيء من الفوائد لبعض الأمراض فلا حرج في ذلك، لكن ينبغي لمن يزورها ويتصل بها أن يتثبت في ذلك، وأن يسأل من جرب حتى لا يقع فيها بما يضرهم، يسأل المجربين فيستعمل ما اتضح أنه ينفع، ويدع الشيء الذي يضره، هذا هو الذي ينبغي. نعم.","link":"https://binbaz.org.sa/fatwas/4906/حكم-الذهاب-الى-البىر-التي-بين-المدينة-وحاىل-للعلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_030/03001.mp3","categories":["الطب والتداوي"]},{"id":7708,"question":"أيضاً يقول: إن بعض الناس يصيبهم أعصاب وشلل، وأن بعض الناس يزعمون أن عندهم طب عربي، أولاً: الكي في الرأس، ثم يحبسه في غرفة مظلمة سبعة أيام على طعام بدون ملح، وألا يسمع الأصوات، هل هذا صحيح أم لا، أفيدونا وفقكم الله؟","title":"حكم التداوي بالطب العربي","answer":"الجواب: أكثر الطب أو كثير منه، كله مبني على التجارب، فإذا وجد طبيب عربي أو عجمي يتعاطى أدوية نافعة ليس فيها محظوراً شرعاً، ليس فيها مداواة بالشرك وليس فيها مداواة بالنجائس، وإنما يداوي بأمور مباحة من أدوية مباحة من كي.. من قراءة مباحة، كل هذا لا بأس به، لأن الطب يختلف ويتنوع، فليس من شرطه أن يكون مستورداً من أوروبا أو من أمريكا أو من كذا أو من كذا بل متى جاء فيه شيء من النصوص تدل على فائدته عمل به، ومتى جرب شيء من الحبوب أو الثمار أو الكي أو غير ذلك في بعض الأمراض فلا بأس. \nوالحاصل أن الغالب في الطب أو الكثير في الطب أنه إنما هو التجارب، فإذا جرب إنسان يتعاطى الطب جرب علاجاً بالكي لبعض الأمراض أو حمية لبعض الأمراض أو جعل المريض في حجرة ليس فيها نور؛ لأنه ينفعه ذلك في بعض الأمراض أو يحميه عن الملح أو عن كذا أو عن كذا، كل هذا لا بأس به على حسب التجارب، بشرط أن لا يكون في هذا شيء يخالف أمر الله جل وعلا، لا بد أن تكون هذه الإجراءات غير مخالفة للشريعة. \nأما العلاج بشيء يخالف الشرع من المحرمات المعروفة فلا يجوز؛ لأن الرسول عليه السلام قال: عباد الله تداووا، ولا تداووا بحرام وروي عنه عليه السلام إنه قال: إن الله لم يجعل شفاءكم فيما حرم عليكم ولما سأله بعض الناس عن الخمر يصنعها للدواء؛ قال عليه الصلاة والسلام: إنها ليست بدواء، ولكنها داء، فبين عليه الصلاة والسلام أن الخمر ليس بدواء ولكنها داء. \nفالحاصل من هذا أن الشيء الذي جرب وعرف أنه ينفع، سواء كان كياً أو ثمرة تؤكل أو حبوباً تؤكل أو دهاناً أو حمية عن أشياء أخرى أو ما أشبه ذلك مما ليس فيه مخالفة للشرع فكل هذا لا بأس به والحمد لله: عباد الله تداووا، ولا تداووا بحرام هذا شيء معروف، والله جل وعلا جعل لكل داء دواء فإذا أصيب دواء الداء برأ بإذن الله هكذا جاء الحديث، يقول عليه الصلاة والسلام: لكل داء دواء، فإذا أصيب دواء الداء برأ بإذن الله سبحانه وتعالى. نعم.","link":"https://binbaz.org.sa/fatwas/4907/حكم-التداوي-بالطب-العربي ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_030/03002.mp3","categories":["الطب والتداوي"]},{"id":7804,"question":"هذا سائل يقول: رجل أصيب بمرض وقد عالج بالدواء وقراءة القرآن ولم يشف، وقد أشار عليه البعض بالذهاب إلى أحد السحرة، وعلل له بأنه إذا لم يشف فالذهاب للسحرة لا بأس به، فما الجواب؟","title":"حكم الذهاب إلى السحرة للعلاج","answer":"الجواب: هذا منكر لا يجوز، الرسول ﷺ نهى عن ذلك: من أتى عرافاً أو كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، وفي الحديث الآخر: ليس منا من سحر أو سحر له أو تكهن أو تكهن له، كذلك في الحديث الآخر: ثلاثة لا يدخلون الجنة: مدمن خمر وقاطع رحم ومصدق بالسحر.\nفالواجب على المسلم الحذر من ذلك، وأن يقرأ القرآن ويذهب إلى العلماء الأخيار وقراء القرآن الطيبين، ويسأل ربه الشفاء والعافية، يلجأ إلى الله في سجوده وفي الليل وفي آخر الليل وفي آخر الصلاة يسأل ربه العافية والشفاء.\nأما الذهاب إلى العرافين أو الكهنة أو المنجمين أو السحرة كله منكر والعياذ بالله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5202/حكم-الذهاب-الى-السحرة-للعلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05120.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":7806,"question":"سماحة الشيخ يقول السائل مصري ومقيم بتبوك: ما هي الحدود والضوابط في الرقية الشرعية؟ وهل يجوز للراقي أن يرقى مجموعةً من الأشخاص في وقت واحد؟ وبماذا تنصحون المرضى مأجورين؟","title":"ما هي ضوابط الرقية الشرعية؟","answer":"الجواب: الرقية تكون بالقرآن وبالدعوات الطيبة هذه الرقية، مع رجاء أن الله يتقبل وينفع بها فينفث عليها بريقه ويقرأ الفاتحة أو بعض الآيات أو آية الكرسي أو قل هو الله أحد والمعوذتين القرآن كله شفاء، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44].\nفالرقية تكون بالقرآن وبالدعوات الطيبة على محل الألم، ينفث على محل الألم في صدره أو رأسه أو يده أو رجله ويقرأ الفاتحة وما تيسر معها من القرآن ويدعو: (رب الناس أذهب البأس واشف أنت الشافي لا شفاء إلا شفاؤك شفاءً لا يغادر سقما)، ويقول: (باسم الله أرقيك من كل شيء يؤذيك من شر كل نفس أو عين حاسد، الله يشفيك باسم الله أرقيك)، هذه الرقية الشرعية، مع رجاء أن الله ينفع بذلك، وسؤاله أن يتقبل وأن ينفع وأن يشفي المريض، يكون عنده إيمان بأن الله هو الشافي وأن هذه أسباب، فهو يسأل الله أن يشفي المريض ويقرأ عليه، ويرجو من الله أن ينفع برقيته.\nيجوز أن يرقي أشخاص اثنين ثلاثة قدامه ينفث على هذا وهذا ويقرأ لا بأس إذا استطاع ذلك يكون اثنين أو ثلاثة قدامه ينفث عليهم على صدورهم أو في أيديهم أو على رءوسهم على حسب المرض لا بأس ما هو بشرط واحد، لو كان اثنين قدامه أو ثلاثة نفث على هذا وهذا لا حرج فيه، لا نعلم في هذا حرج. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5197/ما-هي-ضوابط-الرقية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05115.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":7824,"question":"هذا سائل يقول: رجل أصيب بمرض وقد عالج بالدواء وقراءة القرآن ولم يشف، وقد أشار عليه البعض بالذهاب إلى أحد السحرة، وعلل له بأنه إذا لم يشف فالذهاب للسحرة لا بأس به، فما الجواب؟","title":"حكم الذهاب إلى السحرة للعلاج","answer":"الجواب: هذا منكر لا يجوز، الرسول ﷺ نهى عن ذلك: من أتى عرافاً أو كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، وفي الحديث الآخر: ليس منا من سحر أو سحر له أو تكهن أو تكهن له، كذلك في الحديث الآخر: ثلاثة لا يدخلون الجنة: مدمن خمر وقاطع رحم ومصدق بالسحر.\nفالواجب على المسلم الحذر من ذلك، وأن يقرأ القرآن ويذهب إلى العلماء الأخيار وقراء القرآن الطيبين، ويسأل ربه الشفاء والعافية، يلجأ إلى الله في سجوده وفي الليل وفي آخر الليل وفي آخر الصلاة يسأل ربه العافية والشفاء.\nأما الذهاب إلى العرافين أو الكهنة أو المنجمين أو السحرة كله منكر والعياذ بالله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5202/حكم-الذهاب-الى-السحرة-للعلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05120.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":7825,"question":"سماحة الشيخ يقول السائل مصري ومقيم بتبوك: ما هي الحدود والضوابط في الرقية الشرعية؟ وهل يجوز للراقي أن يرقى مجموعةً من الأشخاص في وقت واحد؟ وبماذا تنصحون المرضى مأجورين؟","title":"ما هي ضوابط الرقية الشرعية؟","answer":"الجواب: الرقية تكون بالقرآن وبالدعوات الطيبة هذه الرقية، مع رجاء أن الله يتقبل وينفع بها فينفث عليها بريقه ويقرأ الفاتحة أو بعض الآيات أو آية الكرسي أو قل هو الله أحد والمعوذتين القرآن كله شفاء، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44].\nفالرقية تكون بالقرآن وبالدعوات الطيبة على محل الألم، ينفث على محل الألم في صدره أو رأسه أو يده أو رجله ويقرأ الفاتحة وما تيسر معها من القرآن ويدعو: (رب الناس أذهب البأس واشف أنت الشافي لا شفاء إلا شفاؤك شفاءً لا يغادر سقما)، ويقول: (باسم الله أرقيك من كل شيء يؤذيك من شر كل نفس أو عين حاسد، الله يشفيك باسم الله أرقيك)، هذه الرقية الشرعية، مع رجاء أن الله ينفع بذلك، وسؤاله أن يتقبل وأن ينفع وأن يشفي المريض، يكون عنده إيمان بأن الله هو الشافي وأن هذه أسباب، فهو يسأل الله أن يشفي المريض ويقرأ عليه، ويرجو من الله أن ينفع برقيته.\nيجوز أن يرقي أشخاص اثنين ثلاثة قدامه ينفث على هذا وهذا ويقرأ لا بأس إذا استطاع ذلك يكون اثنين أو ثلاثة قدامه ينفث عليهم على صدورهم أو في أيديهم أو على رءوسهم على حسب المرض لا بأس ما هو بشرط واحد، لو كان اثنين قدامه أو ثلاثة نفث على هذا وهذا لا حرج فيه، لا نعلم في هذا حرج. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5197/ما-هي-ضوابط-الرقية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05115.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":7917,"question":"أيضاً يقول في رسالته: يتناول بعض سائقي السيارات أو سيارات السفر حبوب منشطة وهي لا تغير في العقل، ولكنها تذهب النوم عنهم، فهل هي حرام علماً أنها تكلف شيئاً من المال؟","title":"حكم تناول الحبوب المنشطة","answer":"الجواب: هذه الحبوب بلغنا من الطرق المعروفة ومن العارفين بها ومن أهل الثقة أنها تضرهم، وأنها تسبب صحواً غير صحيح، فيسوق وهو غير عاقل، ويقع منه الحوادث الكثيرة بأسباب عدم النوم وهو يظن أنه سليم وهو ليس بسليم.\nفهذه الحبوب يجب الحذر منها ويجب إنكارها والقضاء عليها، وأن يسوق الإنسان مادام نشيطاً قوياً بعيداً عن النعاس، فإذا حس بالنعاس وجب عليه ترك السياقة؛ لئلا يضر الناس، ولئلا يضر نفسه أيضاً.\nأما تعاطي هذه الحبوب فهو يفضي إلى شر كثير، وإلى مفاسد كثيرة، وأخطار عظيمة، كما هو الواقع من هؤلاء السائقين المتعاطين لهذه الحبوب، وكما يشهد به كل من عرف شأن هذه الحبوب وشأن أهلها. نعم.","link":"https://binbaz.org.sa/fatwas/5416/حكم-تناول-الحبوب-المنشطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_063/06304.mp3","categories":["الطب والتداوي"]},{"id":8026,"question":"سؤالها الأخير تسأل تقول: قرأت في كتاب النصيحة في الأدعية الصحيحة عن ابن مالك  قال: قال رسول الله ﷺ لا يتمنين أحدكم الموت من ضر أصابه، فإن كان لابد فاعلاً فليقل: اللهم أحيني ما دامت الحياة خيراً لي، وتوفني إذا كانت الوفاة خيراً لي أخرجه الإمام أحمد والبخاري ومسلم و هل يعني هذا الدعاء عدولاً عن الانتحار، وفي أي وقت من الصلاة يمكن أن يستجاب لمثل هذا الدعاء والسلام عليكم ورحمة الله؟","title":"حرمة الانتحار وتمني الموت","answer":"الجواب: نعم ليس لها الانتحار ولا لغيرها الانتحار لضر أصابها، ليس للمسلم أن ينتحر ولا للمسلمة أن تنتحر لضر أصابه من مرض أو جراحات أو مضايقات أو فقر أو ما أشبه ذلك، بل الواجب الصبر ولا بأس بهذا الدعاء، يقول الإنسان في صلاته أو غيرها: اللهم أحيني إذا كانت الحياة خيراً لي وتوفني إذا كانت الوفاة خيراً لي وهذا من دعاء النبي صلى الله عليه وسلم ثبت من رواية النسائي عن عمار بن ياسر رضي الله عنه قال: كان النبي ﷺ يدعو بهذه الدعوات: اللهم بعلمك الغيب، وقدرتك على الخلق، أحيني ما علمت الحياة خيراً لي، وتوفني إذا كانت الوفاة خيراً لي وذكر دعوات أخرى.\nفالمقصود: أن من دعاء النبي ﷺ اللهم بعلمك الغيب، وقدرتك على الخلق! أحيني ما علمت الحياة خيراً لي، وتوفني إذا كانت الوفاة خيراً لي وحديث أنس بن مالك هذا الذي ذكرته السائلة رواه البخاري ومسلم في الصحيحين حديث عظيم وهو يدل على أنه لا حرج في السؤال هذا: اللهم أحيني إذا كانت الحياة خيراً لي، وتوفني إذا كانت الوفاة خيراً لي وإذا دعا بهذا الدعاء في السجود، أو في آخر الصلاة قبل السلام فهو حسن؛ لأن السجود يستجاب فيه الدعاء كما قال النبي ﷺ : أقرب ما يكون العبد من ربه وهو ساجد؛ فأكثروا الدعاء وهكذا الدعاء في آخر الصلاة دعاء في محله، والنبي ﷺ أمر به لما علم أصحابه التحيات قال لهم بعدما علمهم الشهادة: ثم ليتخير من الدعاء أعجبه إليه فيدعو بعدما علمهم التشهد ثم ليتخير من الدعاء أعجبه إليه فيدعو فالمؤمن يدعو في آخر الصلاة بما يسر الله من الدعوات الطيبة، وهكذا في السجود. نعم.","link":"https://binbaz.org.sa/fatwas/5633/حرمة-الانتحار-وتمني-الموت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_078/07806.mp3","categories":["مسائل متفرقة في الجنائز","الطب والتداوي"]},{"id":8093,"question":"ونبدأ أولاً برسالة عبد الله صالح محمد أبو صافية العمري من قرية آل عطيف، يقول: ما حكم من لجأ إلى المشعوذين، الذين يدعون أن لهم القدرة على رفع بعض الأمراض العقلية عن بعض الناس، وقد لجأ إليهم بعض الناس وشوفي من مرضه، ويقال: إنهم يستعينون بالجن في ذلك، فما جزاؤهم عند الله؟ وما حكم من لجأ إليهم؟","title":"حكم الذهاب إلى المشعوذين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فاللجأ إلى المشعوذين وسؤالهم عما يبتلى به بعض الناس من الأمراض، أمر لا يجوز، وقد صح عن النبي عليه الصلاة والسلام أنه قال: من أتى عرافاً فسأله عن شيء، لم تقبل له صلاة أربعين يوماً أخرجه مسلم في الصحيح، وقال عليه الصلاة والسلام: من أتى كاهناً -وفي لفظ: عرافاً- فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ، في أحاديث أخرى، والعراف والكاهن ونحوهما هو الذي يدعي علم الغيب بواسطة الجن، هذا يقال له: عراف، ويقال له: كاهن، فلا يجوز سؤال هؤلاء، ولا يجوز إتيانهم، بل يجب ترك سؤالهم، ومن سألهم وأتاهم يستحق أن يؤدب ويعزر حتى يدع ذلك، وكذلك هم الكهان والعرافون يجب أن يزجروا ويؤدبوا ويمنعوا من أعمالهم هذه، ويستتابوا عما فعلوا من دعواهم أنهم يعرفون ما يصيب الناس، بواسطة من يتوسطون به من الجن، وهذا كله باطل وكله منكر، أما كون بعض الناس قد يشفى، فهذا قد يكون عن أمراض سببها له الجن وشياطين الجن، ثم إذا تقرب إليهم وتقرب إليهم هذا الذي يدعي أنه طبيب، إذا تقرب إليهم بما يريدون، قد يزيلون ويرفعون ما فعلوه هم بأنفسهم، من أسباب مرض هذا الشخص.\nفالحاصل أنهم قد يتعاطون أشياء تؤذي الإنسان، فإذا اتصل بهم من يعبدهم ويعظمهم، أزالوا ذلك الشيء الذي يفعلونه، فيسكن المرض، كما يروى عن ابن مسعود : «أنه قال لامرأته لما كانت تذهب إلى يهودي فيرقي عينها، قال لها: إنه الشيطان ينخسها بيده، فإذا قرأ عليك ذاك اليهودي كف عنها » يعني لإغرائها باليهودي.\nفالمقصود أن هؤلاء الذين يدعون أنهم يتصلون بالجن، ويسألونهم بعض الحاجات، هؤلاء لا يسألون ولا يصدقون، بل يجب أن يبتعد عنهم المسلم ويحذرهم، ويجب على ولاة الأمور إذا عرفوهم أن يزجروهم وأن يؤدبوهم، حتى يمتنعوا من هذه الأعمال، وإذا كانوا يدعون الغيب وجب أن يستتابوا، فإن تابوا وإلا قتلوا كفاراً؛ لأن دعوى علم الغيب كفر، الغيب لا يعلمه إلا الله . نعم.","link":"https://binbaz.org.sa/fatwas/5885/حكم-الذهاب-الى-المشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08601.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8155,"question":"الرسالة الأخيرة في هذا اللقاء وردتنا من الشاب (ع. ع. م) من البحرين، يقول أخوكم في الله: أنا شاب أبلغ من العمر ثمانية عشر سنة مقبل على الزواج، يوجد أثر على وجهي مما جعلني خجول أمام الناس وينتابني الضيق، هل يجوز لي أن أعمل عملية لوجهي مما يجعلني مشوه أمام الناس؟","title":"هل يجوز عمل عملية تجميل لمن به تشوهات؟","answer":"الجواب: إذا كان في الوجه شيء من الأثر الجدري أو أمراض في الوجه أخرى تشوهه فلا بأس، إذا كان عند الأطباء شيء يزيل هذا الأثر ويزيل التشويه عنه فلا بأس، النبي صلى الله عليه وسلم لما قطع أنف بعض الناس في الحروب أشار عليه بأن يجعل أنفاً من فضة، فلما أنتن عليه أمره النبي صلى الله عليه وسلم يجعل أنفاً من ذهب، ورخص في ذلك؛ لأن وجه الإنسان بدون أنف يكون مشوهاً، فمن رحمة الله أن أذن له النبي صلى الله عليه وسلم في ذلك، فإذا كان في وجهه حفر من الجدري أو غيره أو وجد الطب عند الأطباء يخفف هذا الشيء، أو في وجهه نقطة سوداء أو أشياء مما يشوه الوجه ووجد علاجاً يزيل هذه الأشياء المشوهة فلا بأس بذلك ولا حرج. نعم.\nالمقدم: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5960/هل-يجوز-عمل-عملية-تجميل-لمن-به-تشوهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09011.mp3","categories":["الطب والتداوي"]},{"id":8220,"question":"شيخ عبد العزيز أمامي قضية كثيراً ما يسأل عنها وهي في الواقع محرجة لإخواننا المسلمين، تلكم القضية هي قضية المرأة والطبيب، ماذا يقول الشيخ عبد العزيز عن هذا الموضوع، وبم تنصحون الأخوات المسلمات حول هذا، وبم تنصحون أولياء الأمور جزاكم الله خيراً؟ ويمثل هذه القضية نيابة عن السادة المستمعين أخونا محمود محمد حسن من الرياض الملز.","title":"ضوابط علاج المرأة عند الطبيب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن قضية المرأة والطبيب قضية مهمة، وفي الحقيقة أنها متعبة كثيراً، ولكن إذا رزق الله المرأة التقوى والبصيرة فإنها تحتاط لنفسها وتعتني بهذا الأمر، فليس لها أن تخلو بالطبيب، وليس للطبيب أن يخلو بها، وقد صدرت الأوامر والتعميمات في منع ذلك من ولاة الأمور.\nفعلى المرأة أن تعتني بهذا الأمر، وأن تتحرى التماس الطبيبات الكافيات، فإذا وجدن فالحمد لله ولا حاجة إلى الطبيب، فإن دعت الحاجة إلى الطبيب.. وعدم وجود الطبيبات فلا مانع عند الحاجة إلى الكشف والعلاج، هذه من الأمور التي تباح عند الحاجة، لكن لا يكون الكشف عن خلوة، بل يكون مع وجود محرمها أو زوجها إن كان الكشف في أمر ظاهر كالرأس واليد والرجل ونحو ذلك، وإن كان الكشف في عورات يكون عندها مرأة، يكون معها امرأة، وهذا أحسن وأحوط أو ممرضة على الأقل، يكون معها ممرضة أو ممرضتان تحضران، ولكن إذا وجد غير الممرضة امرأة تقوم معها يكون ذلك أولى وأحوط وأبعد عن الريبة، وأما الخلوة فلا تجوز أبداً، والتعميمات قد صدرت بهذا والحمد لله، جزاهم الله خيراً.\nفينبغي للأزواج وللأولياء أن يعتنوا بهذا الأمر، وينبغي للمرأة أن تعتني بهذا أكثر؛ لأنها المسئولة عن نفسها، فعليها أن تتقي الله وأن تحذر أسباب الفتنة، وأسباب التهمة في جميع الأحوال، ولكن في مسألة الطبيب بوجه أخص يجب عليها أن تحذر أن تخلو به مهما كان فضله أو أمانته أو نحو ذلك. نعم.\nالمقدم: أولياء الأمور سماحة الشيخ أو المحارم ماذا تقول لهم لو تكرمت؟\nالشيخ: مثل ما تقدم؛ يجب عليهم أن يعتنوا بهذا الأمر، وأن يؤكدوا على أما المسئول عن الأطباء كوزير الصحة ومن دونه من المسئولين، الواجب عليهم أن يؤكدوا هذا مرة بعد مرة، وأن يعتنوا بهذا حتى لا يخلو الطبيب بامرأة أبداً، بل لابد أن يكون معها من نسائها من يحضر معها وهو أحوط، أو على الأقل يكون معها ممرضة أو ممرضتان وهو الأحوط أيضاً حتى لا تكون هناك تهمة ولا شبهة؛ لأن بعض الناس يقول: إن الممرضة قد لا تكفي، وقد يكون بينها وبين الطبيب شيء من التواطؤ في شيء.\nفالحاصل: أنه إذا كان ممرضتان أو امرأة من أصحاب المرأة ورفيقاتها يكون ذلك أحوط، إلا إذا كان المرض في شيء طارف يمكن أن يراه الزوج أو يراه المحرم فلا بأس، يكفي الزوج والمحرم، كالمرض في يدها، أو في قدمها أو في رأسها فإن المحرم يجوز له ذلك، يجوز له أن يرى ذلك. نعم.\nالمقدم: الطبيب سماحة الشيخ فيما إذا رد المرأة التي ليس معها محرم أو امرأة وهي تريد الكشف، هل له أن يرد المرأة والحالة هذه؟\nالشيخ: نعم، يجب عليه إلا إذا أحضر من الممرضات من يشارك في هذا الشيء، حتى لا تقع الخلوة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6028/ضوابط-علاج-المراة-عند-الطبيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09601.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":8221,"question":"أختنا لها سؤال يبدو أنه مما يختص بتجمل النساء، تقول: هل يجوز استعمال الحناء مع صفار البيض لتصليح الشعر؟","title":"حكم استعمال الحناء مع صفار البيض للشعر","answer":"الجواب: لا حرج فيه إذا كان فيه فائدة، استعمال الحناء مع صفار البيض أو غيره من الأمور المباحة لا بأس إذا كان فيه فائدة للشعر، لتطويله، أو تمليسه أو غير هذا من مصالحه، أو بقائه وعدم سقوطه لا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6034/حكم-استعمال-الحناء-مع-صفار-البيض-للشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09607.mp3","categories":["الطب والتداوي"]},{"id":8226,"question":"شيخ عبد العزيز أمامي قضية كثيراً ما يسأل عنها وهي في الواقع محرجة لإخواننا المسلمين، تلكم القضية هي قضية المرأة والطبيب، ماذا يقول الشيخ عبد العزيز عن هذا الموضوع، وبم تنصحون الأخوات المسلمات حول هذا، وبم تنصحون أولياء الأمور جزاكم الله خيراً؟ ويمثل هذه القضية نيابة عن السادة المستمعين أخونا محمود محمد حسن من الرياض الملز.","title":"ضوابط علاج المرأة عند الطبيب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن قضية المرأة والطبيب قضية مهمة، وفي الحقيقة أنها متعبة كثيراً، ولكن إذا رزق الله المرأة التقوى والبصيرة فإنها تحتاط لنفسها وتعتني بهذا الأمر، فليس لها أن تخلو بالطبيب، وليس للطبيب أن يخلو بها، وقد صدرت الأوامر والتعميمات في منع ذلك من ولاة الأمور.\nفعلى المرأة أن تعتني بهذا الأمر، وأن تتحرى التماس الطبيبات الكافيات، فإذا وجدن فالحمد لله ولا حاجة إلى الطبيب، فإن دعت الحاجة إلى الطبيب.. وعدم وجود الطبيبات فلا مانع عند الحاجة إلى الكشف والعلاج، هذه من الأمور التي تباح عند الحاجة، لكن لا يكون الكشف عن خلوة، بل يكون مع وجود محرمها أو زوجها إن كان الكشف في أمر ظاهر كالرأس واليد والرجل ونحو ذلك، وإن كان الكشف في عورات يكون عندها مرأة، يكون معها امرأة، وهذا أحسن وأحوط أو ممرضة على الأقل، يكون معها ممرضة أو ممرضتان تحضران، ولكن إذا وجد غير الممرضة امرأة تقوم معها يكون ذلك أولى وأحوط وأبعد عن الريبة، وأما الخلوة فلا تجوز أبداً، والتعميمات قد صدرت بهذا والحمد لله، جزاهم الله خيراً.\nفينبغي للأزواج وللأولياء أن يعتنوا بهذا الأمر، وينبغي للمرأة أن تعتني بهذا أكثر؛ لأنها المسئولة عن نفسها، فعليها أن تتقي الله وأن تحذر أسباب الفتنة، وأسباب التهمة في جميع الأحوال، ولكن في مسألة الطبيب بوجه أخص يجب عليها أن تحذر أن تخلو به مهما كان فضله أو أمانته أو نحو ذلك. نعم.\nالمقدم: أولياء الأمور سماحة الشيخ أو المحارم ماذا تقول لهم لو تكرمت؟\nالشيخ: مثل ما تقدم؛ يجب عليهم أن يعتنوا بهذا الأمر، وأن يؤكدوا على أما المسئول عن الأطباء كوزير الصحة ومن دونه من المسئولين، الواجب عليهم أن يؤكدوا هذا مرة بعد مرة، وأن يعتنوا بهذا حتى لا يخلو الطبيب بامرأة أبداً، بل لابد أن يكون معها من نسائها من يحضر معها وهو أحوط، أو على الأقل يكون معها ممرضة أو ممرضتان وهو الأحوط أيضاً حتى لا تكون هناك تهمة ولا شبهة؛ لأن بعض الناس يقول: إن الممرضة قد لا تكفي، وقد يكون بينها وبين الطبيب شيء من التواطؤ في شيء.\nفالحاصل: أنه إذا كان ممرضتان أو امرأة من أصحاب المرأة ورفيقاتها يكون ذلك أحوط، إلا إذا كان المرض في شيء طارف يمكن أن يراه الزوج أو يراه المحرم فلا بأس، يكفي الزوج والمحرم، كالمرض في يدها، أو في قدمها أو في رأسها فإن المحرم يجوز له ذلك، يجوز له أن يرى ذلك. نعم.\nالمقدم: الطبيب سماحة الشيخ فيما إذا رد المرأة التي ليس معها محرم أو امرأة وهي تريد الكشف، هل له أن يرد المرأة والحالة هذه؟\nالشيخ: نعم، يجب عليه إلا إذا أحضر من الممرضات من يشارك في هذا الشيء، حتى لا تقع الخلوة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6028/ضوابط-علاج-المراة-عند-الطبيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09601.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":8227,"question":"أختنا لها سؤال يبدو أنه مما يختص بتجمل النساء، تقول: هل يجوز استعمال الحناء مع صفار البيض لتصليح الشعر؟","title":"حكم استعمال الحناء مع صفار البيض للشعر","answer":"الجواب: لا حرج فيه إذا كان فيه فائدة، استعمال الحناء مع صفار البيض أو غيره من الأمور المباحة لا بأس إذا كان فيه فائدة للشعر، لتطويله، أو تمليسه أو غير هذا من مصالحه، أو بقائه وعدم سقوطه لا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6034/حكم-استعمال-الحناء-مع-صفار-البيض-للشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_096/09607.mp3","categories":["الطب والتداوي"]},{"id":8383,"question":"شيخ عبد العزيز ، في بداية لقائنا في هذه الحلقة نعود إلى رسالة الأخ عبد الهادي النور بشير من قوات الشعب المسلحة في الخرطوم، جمهورية السودان، أخونا يقول: في قطرنا توجد مستشفيات للأمراض النفسية، وبعض الدكاترة يقول: إن الموسيقى هي هدوء نفسي، فما حكم ذلك في الإسلام، ولاسيما أن كثيراً من الناس يرى أنه قد استفاد منها؟","title":"حكم استخدام الموسيقى لمعالجة الأمراض","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفإن الموسيقى وغيرها من آلات اللهو كلها شر وبلاء، وليست من أسباب الهدوء، ولكنها مما يزين الشيطان التلذذ به، والدعوة إليه، حتى يشغل النفوس عن الحق بالباطل، وحتى يلهيها عما أحب الله إلى ما كره الله وحرم، فالموسيقى والعود وسائر أنواع الملاهي، كلها منكر، وكلها لا يجوز أن يعالج بها المرضى، بل يعالج المرضى بأنواع الأدوية التي تنفعهم في مرضهم سواء كانت حسيةً أو غير حسية، فقراءة القرآن، والإكثار من ذكر الله، والتسبيح والتهليل والاستغفار، كل هذا مما يهدئ النفوس، ويجلب إليها الطمأنينة إذا كانت نفوساً مؤمنة، فإذا كان عنده شيء من القلق، فينبغي له أن يكثر من ذكر الله، من التسبيح والتهليل والتحميد، من الاستغفار، يحدث بالأحاديث التي تناسبه، التي ليس فيها محذور، يحدثه الطبيب، يحدثه إخوانه وزواره.\nأما أن يلهى بالموسيقى، أو بغيرها من آلات اللهو فهذا منكر، وهذا من تزيين الشيطان، وعاقبته وخيمة، وإن تسلى بها بعض الوقت، لأن الشيطان زين له ذلك، ولأن النفوس ميالة إلى أصوات الملاهي، لكن عاقبتها وخيمة، والعياذ بالله. نعم.","link":"https://binbaz.org.sa/fatwas/6234/حكم-استخدام-الموسيقى-لمعالجة-الامراض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11601.mp3","categories":["الطب والتداوي"]},{"id":8437,"question":"أخونا يقول: توجد في جنوب الأردن المياه المعدنية، والتي يطلق عليها: برك سليمان بن داود، فيقصدها الناس للاستجمام والشفاء، ويحضرون معهم الذبائح لذبحها حال وصولهم، فما حكم ذبح مثل هذه الذبائح، أفيدونا بارك الله فيكم، وجزاكم خير الجزاء؟","title":"حكم الاستشفاء بماء معين والذبح عنده","answer":"الجواب:\n\n إذا كان الماء المذكور مجربًا معروفًا، ينفع في بعض الأمراض فلا بأس بذلك؛ لأن الله جعل في بعض المياه فائدة لبعض الأمراض، فإذا عرف بالتجارب أن هذا الماء ينفع من بعض الأمراض المعينة، كالروماتيزم أو غيره فلا بأس في ذلك.\n\nأما الذبائح ففيها تفصيل: فإن كانت عندما تذبح من أجل حاجتهم وأكلهم ونحو ذلك، وما يقع لهم من ضيوف فلا بأس بذلك، أما إن كانت تذبح لأجل شيء آخر، لأجل التقرب إلى الماء أو التقرب إلى الجن، أو التقرب إلى الأنبياء أو ما أشبه ذلك من الاعتقادات الفاسدة فهذا لا يجوز؛ لأن الله يقول سبحانه وتعالى: قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ  ۝  لَا شَرِيكَ لَهُ [الأنعام: 162، 163].\n\nويقول سبحانه: إنَّا أَعْطَيْنَاكَ الْكَوْثَرَ  ۝  فَصَلِّ لِرَبِّكَ وَانْحَر [الكوثر: 1، 2ٍْ] فالذبح لله والنسك لله والصلاة لله، فليس لأحد أن يذبح للجن أو للكوكب الفلاني، أو النجم الفلاني أو الماء الفلاني، أو النبي الفلاني، أو أي شخص، بل التقرب كله لله وحده سبحانه وتعالى بالذبائح والصلوات وسائر العبادات، يقول الله تعالى: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة: 5]، ويقول سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [البينة: 5]، ويقول سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ  ۝  أَلَا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر: 2، 3].\n\nوالذبح من أهم العبادات ومن أفضل العبادات، فإذا كان المقصود من هذه الذبائح الأكل؛ لأنهم جالسون هناك فيذبحونها للأكل والحاجة فلا بأس، وأما إن كان الذبح لأمر آخر ولقصد آخر؛ إما لأجل المكان، أو مسألة الماء من أجل الماء، أو من أجل الجن أو من أجل ملك من الملائكة يقصدونه، أو نبي من الأنبياء يقصدونه، ويتقربون إليه أو أي شخص كان، أو أي كوكب أو أي صنم، أو أي وثن هذا كله شرك بالله، فيجب الحذر والله المستعان، ويقول الرسول صلى الله عليه وسلم: لعن الله من ذبح لغير الله.\n\nخرجه الإمام مسلم في صحيحه من حديث علي أمير المؤمنين رضي الله عنه.","link":"https://binbaz.org.sa/fatwas/6321/حكم-الاستشفاء-بماء-معين-والذبح-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12002.mp3","categories":["الطب والتداوي","نواقض الإسلام"]},{"id":8502,"question":"أختنا تسأل في سؤالها الأخير وتقول: إن والدتها أنجبت أحد عشر مولوداً، خمسة صغار والبقية كبروا، وقد تعبت كثيراً هل لها أن تقف عن الحمل والولادة ؟","title":"حكم امتناع المرأة عن الإنجاب","answer":"الجواب: إذا كان يضرها الحمل بشهادة الأطباء فلا بأس، وإلا فلا تقف، قد يرزقها الله خير من هؤلاء، قد يرزقها الله ولداً خيراً من هؤلاء وأصلح فلا تقف إلا إذا كان هناك مضرة، فإذا كان مضرة فلا بأس.\nالمقدم: بارك الله فيكم. جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6570/حكم-امتناع-المراة-عن-الانجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12702.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":8590,"question":"هذه رسالة وردتنا من السائل محمد علي القرني من جدة القاعدة الجوية، والسؤال موجه لسماحة الشيخ عبد العزيز بن باز ، يقول: هل يجوز التداوي عند بعض الناس من النساء والرجال الذين يدعون أنهم يعالجون المريض عن طريق استحضار الجن، والسؤال يدور حول امرأة تستدعي الجن عند معالجة المريض، وهي تذكر الله ورسوله صلى الله عليه وسلم وتقرأ الفاتحة وبعض سور القرآن، ثم يحضر الجان ويسلم على الجالسين حوله، ويذكر أن الفساد منتشر في الأرض، وأن الظلم سائر بين الناس، ثم يصف العلاج من بعض الأعشاب، ومن ضمن ما يذكر للمريض أن يذبح ديكاً أو دجاجة ويخصها بلون من الألوان، ويضعها على صدر المريض، ويقول: بمشيئة الله أن يزول هذا المرض عن المريض، ولكن بعد أن يتم الشفاء يطلبون من المريض أن يزورهم في السنة مرة أو مرتين عند عيد الفطر أو الأضحى أو في رجب، وللأسف يعود المرض على المريض أو أحد أقربائه مما جعل لها الأثر الكبير في قلوب من يذهب إليها أو غيرهم، وأن من يذكرها بسوء أو يقول: إنها مشعوذة -إن جاز له التعبير عند هؤلاء- يردون عليه بقولهم: إنها طيبة ويغدقون عليها المدح، ويدعون لها بالستر والرضا من الله، هل يجوز الذهاب إلى هذه المرأة لغرض العلاج إذا عجز الطب الحديث، أفيدونا أفادكم الله؟","title":"حكم الذهاب إلى العرافين والمشعوذين","answer":"الجواب: هذه المرأة وأشباهها لا يجوز أن تؤتى لطلب العلاج ولا للسؤال عن شيء، هذه المشعوذة ويطلق عليها كاهنة وعرافة، فلا يجوز إتيانها ولا سؤالها، بل يجب إبعادها عن الأرض، والقضاء عليها، إن كانت غير سعودية يجب أن تؤدب وتبعد، وإن كانت سعودية يجب أن تؤدب وتضرب وتسجن حتى تدع هذا العمل القبيح، فإن التقرب إلى الجن واستحضارهم والاستعانة بهم في العلاج من أعظم الشرور، ومن أعظم الفساد، وقد يفضي إلى الشرك، فقد تدعوهم من دون الله، وقد تستغيث بهم، وقد تقرب إليهم بعض القرابين من الذبائح وهذا شرك أكبر، نعوذ بالله، وقد قال النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً رواه مسلم في الصحيح.\nوقال عليه الصلاة والسلام: من أتى كاهناً أو عرافاً فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ فهذه من العرافات، فلا يجوز إتيانها ولا سؤالها، وذلك مما دلت عليه السنة الصحيحة عن رسول الله عليه الصلاة والسلام، وهو أيضاً يفضي إلى فساد كبير، وإلى الشرك الأكبر، ومما يدل على خبثها وفسادها أنها تأمر بذبح بعض الحيوانات ويجعل على المريض، وهذا من الكذب وليس له دخل في العلاج، ولكنها تلبس به وربما بعد حين تأمر بذبحه للجن، فيقع الشرك الأكبر.\nومن تلبيسها أنها تذكر الله وتصلي على النبي ﷺ حتى لا يظن بها سوء، حتى يقال: إنها طيبة، ومن تلبيس الجني وخداعه أنه يأتي ويقول للناس: فعلوا وفعلوا ويتوجع من ظلم الناس ومعاصيهم حتى يظن الناس به خيراً، وحتى يقلدوه ويقبلوا علاجه، فكل هذا تلبيس وخداع، فالواجب الحذر منها، والواجب على من عرفها أن يرفع أمرها إلى ولاة الأمور، إلى الأمير، أمير البلد والحاكم.. القاضي.. حتى يقوموا بما يلزم من جهة إبعادها وتأديبها ومنعها من هذه الأعمال القبيحة. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6668/حكم-الذهاب-الى-العرافين-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20907.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8620,"question":"إذا اتفق الزوجان على الانتهاء من الإنجاب فما الحكم؟","title":"حكم اتفاق الزوجين على إيقاف الإنجاب","answer":"الجواب: لا يجوز لهما ما دامت المرأة قادرة فليس لهما ذلك؛ لأن الشريعة تريد من الناس العناية بالأولاد وتكثير الأمة، يقول النبي ﷺ: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة وفي لفظ: الأنبياء يوم القيامة ولأن في ذلك تكثير من يعبد الله من المسلمين، ولأن في ذلك أيضاً تكثير الأمة حتى تكون الأقوى ضد أعدائها، فليس للرجل أن يدع الإنجاب خوفاً من تبعة المئونة ومشقة النفقة، أو من أجل التلذذ بالمرأة ونحو ذلك، وليس للمرأة كذلك، بل عليهما أن يتعاطيا أسباب الذرية ويحرصا على أسباب الذرية حتى يكثرا الأمة، وحتى يحققا ما قاله النبي ﷺ، لكن متى وجد ضرر على المرأة؛ لأنها تتألم كثيراً بسبب مرض في رحمها أو لأنها لا تلد إلا بعملية، فهذا عذر في عدم الإنجاب إذا كانت العملية تضرها ويخشى عليها منها.\nكذلك إذا كان الأولاد كثيرين، بأن تتابعوا في زمن متقارب وشق عليها التربية فلا مانع من أن تأخذ بعض الحبوب أو بعض المانع سنة أو سنتين مدة الرضاع حتى تقوى على التربية، وحتى تستعين بذلك على تربية الآخرين الجديدين. نعم.","link":"https://binbaz.org.sa/fatwas/6751/حكم-اتفاق-الزوجين-على-ايقاف-الانجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_129/12909.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":8643,"question":"هذه رسالة وردتنا من السائل: (م. ع. أ) من السودان في الحقيقة له فيها عدة أسئلة نعرض بعضها والبعض الآخر قد تكررت الإجابة عنه في كثير من حلقات البرنامج، يقول في سؤاله: تزوجت ولي عشر سنوات ولم أنجب، وتلك إرادة الله سبحانه، ولكن  إذا كان في هذه المسألة مصدر عدم الإنجاب الرجل، فهل عليه ذنب إذا لم يصارح المرأة بذلك، وهل يترتب على الإنسان أن يسرحها، وما الحكم أفيدونا أفادكم الله؟","title":"ما يفعله من أصيب بالعقم مع امرأته","answer":"الجواب: إذا لم يقدر للمؤمن الإنجاب فليس من المقطوع به أن يكون عقيماً، فقد تكون هناك أسباب تحتاج إلى علاج فكل داء له دواء، فإذا تحقق من طريق أهل الخبرة من الأطباء أنه عقيم فقد اختلف العلماء، هل للمرأة الفسخ أم لا؟ فإن طلقها تحقيقاً لطلبها ورحمة لها فهذا حسن من دون حاجة إلى المخاصمة إذا طلبت ذلك، فالأولى له والأفضل والأحوط أن يطلقها إذا طلبت الطلاق، أو يرضيها بشيء حتى تبقى معه راضية مطمئنة، وأما كونه يحكم لها بالفراق هذا محل نظر ويرجع إلى المحاكم.\nلكن نصيحتي لمن أصيب بالعقم أن يستشير المرأة ويخبرها؛ فإن سمحت ورضيت فلا بأس ولا حرج عليه، وإن أرضاها بشيء من المال كمقرر شهري أو سنوي فلا بأس، أما إن صممت على طلب الطلاق فإن نصيحتي له أن يطلقها وأن لا يخاصمها عند المحاكم بل يطلقها لعل الله يرزقها ذرية، وهو قد يجد غيرها وربما أخطأ الأطباء في قولهم: إنه عقيم، وربما يسر الله له زوجة أخرى أو زوجة ثالثة فتحمل منه، فقد يقول الأطباء: إنه عقيم ويخطئون ويغلطون، هذه نصيحتي للأخ السائل. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6775/ما-يفعله-من-اصيب-بالعقم-مع-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21202.mp3","categories":["الطب والتداوي","نصائح وتوجيهات"]},{"id":8646,"question":"هذه رسالة وردتنا من السائل: (م. ع. أ) من السودان في الحقيقة له فيها عدة أسئلة نعرض بعضها والبعض الآخر قد تكررت الإجابة عنه في كثير من حلقات البرنامج، يقول في سؤاله: تزوجت ولي عشر سنوات ولم أنجب، وتلك إرادة الله سبحانه، ولكن  إذا كان في هذه المسألة مصدر عدم الإنجاب الرجل، فهل عليه ذنب إذا لم يصارح المرأة بذلك، وهل يترتب على الإنسان أن يسرحها، وما الحكم أفيدونا أفادكم الله؟","title":"ما يفعله من أصيب بالعقم مع امرأته","answer":"الجواب: إذا لم يقدر للمؤمن الإنجاب فليس من المقطوع به أن يكون عقيماً، فقد تكون هناك أسباب تحتاج إلى علاج فكل داء له دواء، فإذا تحقق من طريق أهل الخبرة من الأطباء أنه عقيم فقد اختلف العلماء، هل للمرأة الفسخ أم لا؟ فإن طلقها تحقيقاً لطلبها ورحمة لها فهذا حسن من دون حاجة إلى المخاصمة إذا طلبت ذلك، فالأولى له والأفضل والأحوط أن يطلقها إذا طلبت الطلاق، أو يرضيها بشيء حتى تبقى معه راضية مطمئنة، وأما كونه يحكم لها بالفراق هذا محل نظر ويرجع إلى المحاكم.\nلكن نصيحتي لمن أصيب بالعقم أن يستشير المرأة ويخبرها؛ فإن سمحت ورضيت فلا بأس ولا حرج عليه، وإن أرضاها بشيء من المال كمقرر شهري أو سنوي فلا بأس، أما إن صممت على طلب الطلاق فإن نصيحتي له أن يطلقها وأن لا يخاصمها عند المحاكم بل يطلقها لعل الله يرزقها ذرية، وهو قد يجد غيرها وربما أخطأ الأطباء في قولهم: إنه عقيم، وربما يسر الله له زوجة أخرى أو زوجة ثالثة فتحمل منه، فقد يقول الأطباء: إنه عقيم ويخطئون ويغلطون، هذه نصيحتي للأخ السائل. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6775/ما-يفعله-من-اصيب-بالعقم-مع-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21202.mp3","categories":["الطب والتداوي","نصائح وتوجيهات"]},{"id":8647,"question":"له سؤال ثانٍ يقول فيه: هناك بعض الناس يصيبهم الجنون ويذهب بهم إلى شيوخ المتصوفة ويعالجونهم بالبخور والمحو والحجاب، وبعد ذلك يصيرون بحالة متحسنة فما رأي الشرع في ذلك؟","title":"حكم الذهاب بالمجانين إلى شيوخ المتصوفة لعلاجهم","answer":"الجواب: من أصابه الجنون لا يذهب به إلى الخرافيين يذهب به إلى أهل الخير من القراء الطيبين والعارفين بعلاج هذه الأشياء، يقرأ عليه وينفث عليه، ويستعمل ما يسبب خروج الجني منه، والله جعل لكل شيء سبباً ولكل داء دواء، والغالب أن المؤمن التقي والعالم المعروف بالاستقامة وحسن العقيدة إذا قرأ عليه ونفث عليه وتعاهده بالقراءة والوعيد للجني وتحذيره فإنه يخرج بإذن الله، وبكل حال فليس للمسلم أن يذهب إلى الصوفية المخرفين المعروفين ببدعهم وضلالهم وخرافاتهم ليس له أن يذهب إليهم ولا يتعالج عندهم؛ لئلا يضروه لئلا يجروه إلى ما هم فيه من الشرك والبدع والخرافات، فإن الصوفية في الغالب طريقتهم هي البدع والخرافات وكثير منهم يعبد شيخه من دون الله ويستغيث به وينذر له ويطلب منه المدد حياً وميتاً، فأحوالهم خطيرة والناجي منهم قليل ولا حول ولا قوة إلا بالله، نسأل الله لنا ولهم الهداية والبصيرة، والطريقة السليمة الناجية السعيدة هي طريقة الكتاب والسنة، هي طريقة أصحاب النبي ﷺ وأتباعهم بإحسان، وهو الصراط المستقيم، وهو دين الله، التمسك بشرع الله والحذر مما نهى الله عنه والحذر من البدع. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6781/حكم-الذهاب-بالمجانين-الى-شيوخ-المتصوفة-لعلاجهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21208.mp3","categories":["الطب والتداوي"]},{"id":8657,"question":"الرسالة الأولى في هذه الحلقة وردتنا من السائل عيظة محمد الدعبلي لم يذكر عنواناً، يقول في رسالته: ما حكم الرجل الذي يسعف زوجته بالدم، وما حكم لبس الساعة في اليد اليمنى بالنسبة للرجل؟","title":"حكم التبرع بالدم للزوجة، ولبس الساعة في اليمين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإسعاف الرجل لزوجته بالدم ليس فيه محذور، ولا يؤثر في النكاح، وليس مثل الرضاع، فللرجل أن يسعف زوجته وللمرأة أن تسعف زوجها، ولا حرج في ذلك والحمد لله.\nأما لبس الساعة فيجوز في اليمين وفي اليسار، وقد ثبت عن النبي ﷺ: أنه تختم في يمينه تارة وفي يساره تارة وهذا لبيان التوسعة، فالساعة مثل ذلك إذا لبسها في اليمين أو في اليسار فلا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6786/حكم-التبرع-بالدم-للزوجة-ولبس-الساعة-في-اليمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21301.mp3","categories":["اللباس والزينة","الطب والتداوي"]},{"id":8699,"question":"هنا رسالة من حوطة بني تميم باعثها أخونا عبد الله راشد طالب، أخونا يقول: أرجو أن تقدموا رسالتي هذه إلى سماحة الشيخ عبدالعزيز بن باز، وتساؤلي هو: نسمع كثيراً عن الكهنة والمنجمين، فما صحة ديانة من يذهب إليهم والإيمان بأقاويلهم ذلكم أنهم يأتون بما يثبت الصحيح، فمن ذلك: أنهم يخبرون المرء باسم قريب من أقاربه ويصفون له منزله وربما وصفوا له ما عنده من المال والأولاد.. ويستمر في سرد ما يقوله أولئك سماحة الشيخ ويرجو التوجيه؟","title":"حقيقة الكهنة والمشعوذين وحكم إتيانهم","answer":"الشيخ: هذا موجود في عهد النبي ﷺ وقبله وبعده ولهذا نهى النبي ﷺ عن إتيان الكهان وعن سؤالهم، قال عليه الصلاة والسلام: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً رواه مسلم في صحيحه، وقال أيضاً عليه الصلاة والسلام: من أتى كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ وسأله بعض الناس عن إتيان الكهان؟ قال: لا تأتوهم، وقال: ليسوا بشيء. قالوا: يا رسول الله! إنهم يصدقوننا في بعض الأحيان، قال: تلك الكلمة يسمعها الجني من السماء -المسترق للسمع- فيقرها في أذن وليه من الإنس -وهو الكاهن والساحر- فيصدق في تلك الكلمة ولكنهم يقرفون ويزيدون عليها مائة كذبة -وفي رواية: أكثر من مائة كذبة فيقول الناس: إنه صدق يوم كذا وكذا، فيصدقونه بتلك الكلمة التي سمعت من السماء وتكون وسيلة إلى تصديقه في كذبه الكثير.\nفالكهان لهم أصحاب من الشياطين من الجن، الكاهن هو الذي له رئي، يعني: صاحب من الجن يخبره عن بعض المغيبات وعن بعض ما يقع في البلدان، وهذا معروف في الجاهلية وفي الإسلام وهو الكاهن، وهو الذي له صاحب من الجن يشعره ويخبره عما يلقاه من شياطينه وإخوانه فيقول: جرى كذا، ووقع كذا في البلد الفلانية؛ لأن الجن يتناقلون الأخبار فيما بينهم، والشياطين تتناقل الأخبار فيما بينها، فيخبر بعضهم بعضاً بسرعة هائلة من الشام إلى اليمن من اليمن إلى الشام إلى مصر إلى نجد إلى أمريكا إلى أي مكان، بينهم تناقل للأخبار فلهذا قد يغتر بهم من يسمع صدقهم في بعض المسائل.\nوكذلك قد يعرف الشيطان قريب هذا المبتلى؛ أخوه.. عمه من الشياطين التي بينهم، كل إنسان معه شيطان، كل إنسان منا معه شيطان، معه قرين من الإنس وقرين من الجن، كل واحد من بني آدم، فالشياطين يخبر بعضها بعضاً ويدل بعضها على عورات بعض وقد تخبر عما عندهم من المال، ما عندهم من الأولاد، ما عندهم من الأثاث، كل هذا يقع بين الناس.\nوقد يسترقون السمع فيسمعون بعض ما يقع في السماء بين الملائكة مما يتكلم الله به جل وعلا من أمور أهل الأرض وما يحدث في الأرض، فيتسامعون تلك الكلمة، فإذا سمعوها قروها في أذن أصحابهم من الكهنة والسحرة والمنجمين، فيقول المنجم والساحر والكاهن: سوف يقع كذا سوف يقع كذا، عن تلك الكلمة التي سمعت من السماء، ولا يكتفي بهذا بل يكذب معها الكذب الكثير حتى يروج بضاعته وحتى يأخذ أموال الناس بالباطل، فهي بسبب هذا الكلام الذي ينقله إليهم سوف يجري كذا سوف يقع كذا، إذا صدق في موضع نقل الناس هذا الصدق الذي وافق فيه الخبر الذي وقع في السماء، أو وافق فيه الحوادث التي وقعت في بعض البلدان، فعند هذا الناس يغلب عليهم تصديقهم بسبب هذه الحوادث، فيقولون: صدق في يوم كذا، صدق في كذا، صدق في كذا، والمرضى يتعلقون بخيط العنكبوت ويتشبثون بكل شيء، فلهذا يأتون الكهنة ويأتون المنجمين ويأتون السحرة بسبب ما قد يسمعون عنهم أنهم صدقوا في كذا وصدقوا في كذا.\nفالواجب عدم إتيانهم وعدم سؤالهم وعدم تصديقهم ولو قدر أنهم صدقوا في بعض الشيء، الواجب تركهم بالكلية؛ لأن الرسول ﷺ نهى عن إتيانهم، ونهى عن سؤالهم ونهى عن تصديقهم، فالواجب على المسلمين أن لا يصدقوهم وأن لا يسألوهم وأن لا يأتوهم بالكلية، هذا هو الواجب على الجميع، وأن يسلكوا في علاج المرضى ما شرعه الله من القراءة والدواء المباح ونحو ذلك مما يعرفه الأطباء، فبين الأطباء وبين القراء الذين يرقون المرضى ويعرفون بإسلامهم ودينهم، هذه هي الأسباب الشرعية والوسائل الشرعية، أما إتيان الكهان والمنجمين والرمالين والعرافين وسؤالهم هذا منكر لا يجوز، نسأل الله العافية والسلامة. نعم.","link":"https://binbaz.org.sa/fatwas/6846/حقيقة-الكهنة-والمشعوذين-وحكم-اتيانهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13106.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8712,"question":"لعل من الأدوية الحسية سماحة الشيخ ما يسأل عنه أخونا أبو محمد أيضاً يقول: قرأت في كتاب الطب النبوي لابن قيم الجوزية حيث أشار إلى أن الذهب مفيد في علاج الخوف وضعف القلب والرجفان العارض من السوداء، وينفع حديث النفس والحزن والغم ومن الفزع والعشق -فيما يبدو- هل يجوز لمن عنده من هذه الحالات أن يستخدم الذهب، وهل هو حلال أم حرام، وما رأيكم عموماً فيما يصفه ابن القيم في كتابه هذا أو في زاد المعاد؟","title":"مدى صحة كون الذهب والمال مما يعين على الشفاء","answer":"الجواب: لست أعرف لهذا أصلاً بيناً ولعل الأسباب أن الذهب مال نفيس وله قيمة وأهمية فإذا اقتناه المحزون أو المهموم أو نحو ذلك يرى من الراحة والطمأنينة والفرح ما يدفع ما به من هم وحزن وفزع ونحو ذلك لغلائه ونفاسته، كما أن الإنسان إذا رأى محبوبه ومن يرغب في لقائه يحصل له من الفرح والسرور والنشاط والقوة ما يدفع بعض المرض وبعض الأذى.\nفالمال محبوب للنفوس ولاسيما الذهب له نفاسة وله أهمية وله قيمة، وقد يكون إذا رآه الإنسان وكان حوله أو عرف أنه عنده أو أنه في حوزته يحصل له من الراحة والطمأنينة والأنس بهذا الشيء ما يعين على دفع هذا البلاء أو تخفيفه، وهذا يعني يلحق به بقية الأموال التي لها قيمة، فإن المال معروف حب النفوس له كما قال الله : وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا [الفجر:20] قال سبحانه: وَإِنَّهُ لِحُبِّ الْخَيْرِِ لَشَدِيدٌ [العاديات:8] يعني: المال، فإذا كان من الذهب صار الأمر أحب أكثر؛ لأن الذهب أنفس الأموال بالنسبة إلى معلومات الناس في الجملة وإن كان هناك معادن قد تكون أغلى منه لكن بالنسبة إلى معلومات الناس ولاسيما العامة فإن الذهب عندهم في القمة، وله أثر في النفوس وفي دفع الأوهام والأحزان والفزع ونحو ذلك، لعله من هذه الحيثية فقط أما غير ذلك فلا أعلم شيئاً، و ابن القيم كغيره من أهل العلم ينقل ما يقول الناس ما يقول الأطباء وما يقول من قبلهم فقد ينبهون على شيء، وقد يعلقون على شيء، وقد ينقلونه كما وجدوه. نعم.\nوالمسألة في هذا ترجع إلى أمرين:\nأحدهما ما ينقل عن الرسول صلى الله عليه وسلم، فما ثبت عنه ﷺ فلا شك أنه على ما قال ﷺ نافع ومفيد على ما قال ﷺ، إذا ثبت عنه السند.\nأما الشيء الثاني فما ينقل عن الأطباء الأوائل أو المحدثين فهذا في الغالب يكون عن تجارب يكون عن تجارب جربوها أو نقلوها عن غيرهم، فقد يفيد وقد لا يفيد، قد تكون هناك أشياء تعيقه عن الفائدة وتمنع فائدته، فإن من شرط الفائدة من الدواء أن لا يكون هناك مانع يمنع منه، فإذا صار الدواء له أثر في المرض وصار المرض ليس هناك مانع من تأثير الدواء فيه فإنه ينفع بإذن الله؛ لأنه قد يكون هناك موانع في نفس جسد الإنسان أو في المريض تدفع أثر هذا الدواء وتعيقه أو تبطله فالله حكيم عليم جل وعلا.\nولهذا قال ﷺ: لكل داء دواء فإذا أصيب -يعني: حصلت الموافقة- فإذا أصيب دواء الداء برئ بإذن الله فقد يكون هذا الدواء ليس صالحاً لهذا الداء نعم فلا ينفع فيه، أما إذا وجد دواء الداء نفسه الذي جعله الله دواءً له وأحسن استعماله ووضع كما ينبغي فإنه الغالب ينفع الله به.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6862/مدى-صحة-كون-الذهب-والمال-مما-يعين-على-الشفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_133/13302.mp3","categories":["الطب والتداوي"]},{"id":8713,"question":"كما ينوه الإخوان سماحة الشيخ من خوفهم على عقيدتهم عند اللجوء إلى أولئك الذين يجسدون الأمور وقد يتكهنون بأشياء وأشياء لعل لسماحة الشيخ توجيه في علاج مثل هذا ولاسيما فيما يتعلق أيضاً بخوف الناس من السحر ومن الجن؟","title":"النهي عن إتيان الكهنة والمشعوذين وسؤالهم","answer":"الجواب: أما ما يتعلق بسؤال الكهنة والمنجمين والعرافين والرمالين وأشباههم من أصحاب الشعوذة ودعوى علم الغيب ودعوى أنهم يدركون أشياء بواسطة الجن ما أدركها غيرهم فهذا كله لا يجوز، والرسول ﷺ نهى عن إتيانهم وعن سؤالهم، سئل عن الكهان عليه الصلاة والسلام فقال: إنهم ليسوا بشيء وقال: لا تأتوهم وقال عليه الصلاة والسلام: من أتى عرافاً فسأله عن شيء لمم تقبل له صلاة أربعين يوماً خرجه الإمام مسلم في صحيحه من حديث بعض أزواج النبي عليه الصلاة والسلام، وفي لفظ: من أتى كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ.\nهذا يدل على أن هؤلاء لا يؤتون ولا يسألون ولا يصدقون؛ لأن عمدتهم الخرص والتكهنات التي لا أساس لها أو الاعتماد على ما يقوله الجن وخرافات الجن وشياطينهم، فلا ينبغي أن يعتمد عليهم، وقد قال ﷺ لما قيل له: إن الكهان قد يصدقون قال: إنهمم يصدقون في كلمة ويكذبون في مائة وفي اللفظ الآخر: في أكثر من مائة وبين عليه الصلاة والسلام أن هذه الكلمة التي يصدقون فيها هي التي يسمعونها من السماء يسمعها مسترقو السمع من السماء من الملائكة فيكذبون معها الكذب الكثير، في إحدى الروايات: فيكذبون معها مائة كذبة وفي لفظ آخر: فيقرفون ويزيدون في بعضها: فيكذبون أكثر من مائة كذبة فيقال: قد صدقوا في كذا وكذا فيصدقون بسبب تلك الكلمة التي سمعت من السماء، والناس من عادتهم الميل إلى الشعوذة وإلى كل ما يظنون أنه ينفع فيتشبثون بكل شيء، والمريض يتشبث بكل شيء أيضاً، فلهذا يصدقون الكهنة والمنجمين في كذبهم الكثير بأسباب أنهم قد صدقوا في واحدة أو نفعوا في واحدة أو ثنتين مثلاً، وهذا كله من طبيعة البشر الميل إلى من ظن أن عنده شيئاً ولاسيما إذا كان قد عرف أنه نفع فيه ولو في واحدة، فيتعلق به ويصدقه في كل شيء ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6863/النهي-عن-اتيان-الكهنة-والمشعوذين-وسوالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_133/13303.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":8780,"question":"والرسالة الأولى وردتنا من مهيوب حسان سيف علي من تعز بالجمهورية العربية اليمنية، يقول في رسالته: أنا شاب أؤدي الصلاة المفروضة وأحافظ عليها والحمد لله، لكني تزوجت امرأة وخلفت منها ثلاثة أولاد، وما خلفت من ولد عاش سنتين ومات، فسمعت أناساً يدعون أنهم صوفة -أي: منجمين- فألح علي أهل القرية أن أذهب إليهم وأشتري منهم الذرية -هذا حسب ادعائهم- وأنا رفضت ذلك، وأقول: أن الله هو الذي يحيي ويميت يهب لمن يشاء الذرية. أفتوني بارك الله فيكم؟","title":"مشروعية التداوي والأخذ بالأسباب لموت الأطفال المتكرر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد: فإن الذهاب إلى المنجمين والعرافين والكهنة أمر منكر في الشريعة الإسلامية، وقد حذر النبي ﷺ من ذلك، فقال عليه الصلاة والسلام: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً خرجه مسلم في الصحيح، وقال عليه الصلاة والسلام: من أتى كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ فالإتيان إلى الكهنة والعرافين والمنجمين أمر منكر لا يجوز في الشريعة، وقد أصبت في امتناعك من الذهاب إلى هؤلاء المنجمين، وليس عندهم علم بهذا، فإن أمر الذرية إلى الله  هو الذي يهب لمن يشاء ما يشاء ، وقد تكون هناك أمراض داخلية في رحم المرأة يمكن عرضها على الأطباء المختصين والطبيبات المختصات فربما ظهر لهم أسباب ما يصيب الأولاد بعد الولادة، قد يكون هناك أسباب في الرحم وأمراض داخلية تخرج معهم وتبقى معهم حتى يموتوا، وقد يكون ذلك لأمر آخر لا يعلمه إلا الله سبحانه وتعالى، ولا مانع من أن تجرب امرأة أخرى أو أكثر، تتزوج امرأة ثانية ثالثة تلتمس الذرية، ولعل الله جل وعلا يهبك ذرية طيبة تعيش، ولا حاجة إلى الاقتصار على واحدة، فالله قد وسع -الحمد لله- ويسر وأباح للرجل الزواج للحاجة، وأباح له أن يجمع ثنتين وثلاثاً وأربعا، فأنت -يا أخي- يمكنك أن تتسبب وأن تتزوج امرأة أخرى لعل الله يهبك منها ذرية تعيش، والحمد لله، وعليك أن تقول: إنا لله وإنا إليه راجعون قدر الله وما شاء فعل، وقد قال الله سبحانه: وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ ۝ أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:155-157]، وصح عن رسول الله عليه الصلاة والسلام أنه قال: ما من عبد يصاب بمصيبة فيقول: إنا لله وإنا إليه راجعون، اللهم آجرني في مصيبتي وأخلفني خيراً منها إلا آجره الله في مصيبته وأخلفه خيراً منها.\nثم يا أخي: الذرية في ال حقيقة هم الذين يقدمون أفراطاً هؤلاء هم الذرية؛ ولهذا صح عن رسول الله عليه الصلاة والسلام أنه قال: ما تعدون الرقوب فيكم؟ قالوا: من لا يولد له، قال: لكن الرقوب هو الذي لم يقدم من ولده شيئاً، وصح عنه عليه السلام أنه قال: من مات له ثلاثة أفراط لم يبلغوا الحنث كن له حجاباً من النار فأنت بحمد الله على خير إن شاء الله مع الصبر والاحتساب، ولكن هذا لا يمنع الأسباب؛ عليك أن تأخذ بالأسباب وأن تعرض المرأة على الطبيبات الطيبات والأطباء المختصين إذا لم توجد امرأة جيدة مختصة في هذا الشيء لعل الله جل وعلا أن ييسر دواءً نافعاً يحصل به الشفاء من هذا المرض، وفي إمكانك أيضاً أن تزوج امرأة ثانية وثالثة حتى يتيسر لك الذرية المطلوبة التي تعيش إن شاء الله. نعم..\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6928/مشروعية-التداوي-والاخذ-بالاسباب-لموت-الاطفال-المتكرر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21901.mp3","categories":["الطب والتداوي"]},{"id":8893,"question":"رسالة باعثها أيضاً من اليمن أخ لنا من هناك يقول: جمال عبده أحمد صالح الشعبي ، أستاذ يمني في مدرسة الفوز أخونا يقول: هل يحاسب المرء الذي استبدل قلبه بقلب قرد، أو قلب صناعي على تصرف القلب الجديد، وما جزاء الطبيب الذي يستأصل القلوب، وما موقف الدين من الطبيب الذي ينزع القلب من حيوان بريء ويحكم عليه بالموت من دون ذنب؟","title":"حكم زرع قلب الحيوان في الإنسان","answer":"الجواب: هذا محل نظر ولم يثبت عندنا حتى الآن أن أحداً عاش بقلب غيره واستقام له ذلك القلب، فلو فرضنا أنه عاش بذلك فإن القلب ينتقل إلى حال صاحبه الذي ركب فيه، بدلاً ما كان قلب حيوان آخر يكون تابعاً لمن ركب فيه؛ لأن المواد التي اتصلت بهذا القلب وصارت إليه وغذته هي مواد القلب الأول، فصار القلب الآن هو قلب المركب فيه، الإنسان الذي ركب فيه لا قلب الحيوان سواء قرداً أو كلباً أو غير ذلك، ويكون له الحكم الذي كان للقلب الأول؛ لأن المادة التي غذي بها القلب الأول تغذى بها هذا القلب الجديد من دم هذا الشخص فصار له حكم القلب الأول إذا عاش به واستقام به أمره.\nأما كونه يذبح الحيوان ويأخذ منه هذا شيء آخر، فقد يقال: إن أخذه من حيوان يباح مثل أخذه من خروف أو من معزة أو من بقر أو من إبل، هذه حيوانات مباح ذبحها للمصلحة، فإذا أخذ منها قلباً وركبه في إنسان فلا بأس، أما ذبح القرود أو الكلاب فهذا محل نظر، والأقرب والله أعلم أنه لا يجوز تعاطي ذلك، والأظهر أنه ما يجوز تعاطي ذلك، لكن لو وقع وفعل وعاش به الإنسان وانتفع به الإنسان، مثل لو ركب في عضو من حيوان آخر من كلب أو غيره وعاش به لا يزال ينفعه ويستقيم عليه، لكن كونه يتعمد أن يأخذ قلب قرد أو قلب كلب أو قلب بغل أو حمار من الحيوانات النجسة هذا محل نظر، وفي الإقدام عليه نظر، وقد يقال إنه يجوز؛ لأن الإنسان مقدم على هذه الحيوانات ومصلحته مراعاة فهو أولى بالعناية وأولى بتحقيق مصلحته إذا تحقق ذلك، وأنه ينتفع بقلب هذا الحيوان، وقد يقال: لا؛ لأن النجاسات لا يداوى بها، والنبي ﷺ قال: لا تداوى بحرام، وهذا نوع من التداوي بالحرام فيمنع.\nفالمقصود أن أخذ قلب حيوان محرم كالكلب والقرد ونحو ذلك أو عضو من أعضائه للإنسان هذا هو محل النظر، بعض أهل العلم أجاز ذلك، وبعض أهل العلم لم يجز ذلك وهو محل نظر ومحل اجتهاد.نعم.\nالمقدم: والذي يذهب إليه الشيخ عبد العزيز بن باز ؟\nالشيخ: والله عندي توقف في هذا في الحيوانات المحرمة، فيها نظر. نعم.\nالمقدم: فيها نظر، بارك الله فيكم إذاً القلب المزروع هو يتحول إلى المكان المزروع فيه؟\nالشيخ: لو وقع، سواء قلنا بجوازه أو بعدم جوازه، لو وقع لا ينزع يستمر به ويكون له حكم القلب الأول ولا يضره كونه من حيوان ما يضره إذا عاش به واستقام عليه وعقل به الأمور، فالحمد لله. نعم.\nالمقدم: والأشياء التي هي في محل القلب الأول تنتقل إلى القلب الجديد كالحب والكراهية والإيمان؟\nالشيخ: كله....؛ لأن المواد موجودة في الإنسان، مواد القلب الأول موجودة. نعم.","link":"https://binbaz.org.sa/fatwas/7049/حكم-زرع-قلب-الحيوان-في-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_140/14006.mp3","categories":["الطب والتداوي"]},{"id":8903,"question":"هنا رسالة وصلت إلى البرنامج من سلطنة عمان باعثها أحد الإخوة يقول: (عمر . ع .ح . ش) أخونا يسرني -هذا كلامه- يسرني بل يسعدني جدًا أن أبعث إليكم بهذه الرسالة والتي تحمل في طيها هذا السؤال المتواضع علمًا بأنني أول مرة أبعث إليكم من أجل الاستفادة، السؤال يقول: سمعنا وقرأنا كثيرًا في الصحف والمجلات عن موضوع التلقيح بالحقنة، امرأة تلقح عن طريق الحقنة -الإبرة- في إحدى المستشفيات وذلك من أجل الإنجاب، كون رجل هذه المرأة غير قادر على الإنجاب علمًا بأن الطبيب يأخذ مَنِيًّا من رجل آخر حتى يلقح تلك المرأة، والسؤال هنا: هل هذه الطريقة جائزة في الإسلام والتعامل بها جائز أم غير ذلك، وإن كان الجواب غير ذلك فما عقوبة الفاعلة والفاعل والراضي بهذا؟ جزاكم الله خيرا. ولعله يشير إلى طفل الأنبوب سماحة الشيخ؟","title":"حكم الإنجاب بواسطة الأنابيب","answer":"الجواب: هذا الموضوع فيه تفصيل وقد درسه أعضاء المجمع الفقهي في مكة في الرابطة في دورة مضت وبينوا في قرارهم الأنواع الممنوعة والأنواع الجائزة، وهذا الذي سأل عنه السائل، على حالين:\nأحدهما أجازه المجمع.\nوالثاني: منعه وهو ممنوع بإجماع المسلمين.\nأما الذي أجازه المجمع فهو أن تكون المرأة لا تنجب بسبب مرض في المبيض أو في القنوات التي توصل المني إلى الرحم أو الرجل كذلك ليسا بعقيمين ولكن هناك أسباب عرفها الأطباء في الرجل أو في المرأة، ورأى الطبيب المختص أن في الإمكان أخذ المني من الرجل من زوجها ثم حقنه فيها في رحمها وأن هذا قد يلقحها بإذن الله وينفع بإذن الله.\nالمقدم: من الزوج ذاته؟\nالشيخ: من الزوج نفسه بصفة خاصة ولا يحضرها إلا الطبيب المختص أو الطبيبة، والواجب الطبيبة إن تيسرت، طبيبة أنثى تتولى ذلك تحقنه يعطيها إياه، يأخذه من نفسه هو الزوج ويعطيها المرأة تحقنه في رحم الزوجة، وإن كان لا يستطيع أخذه الرجل منه ثم أعطاه المرأة وتحقنه في رحم المرأة إذا تيسرت امرأة، فإن لم يتيسر امرأة تعرف ذلك جاز للرجل للضرورة أن يأخذه من الزوج ثم يحقنه بالإبرة في رحمها.\nهذه صورة من الصور التي أجازها المجمع وذكر أنها استعملت ونجحت، مع أن فيها خطرًا يجب الاحتياط فيه وأن تكون العملية بحضرة الزوج والزوجة والطبيب المختص أو الطبيبة المختصة من دون أن يحضر ذلك أحد؛ لأن المرأة تنكشف فلا يحضرها ولو محارمها؛ لأن المحرم لا يرى العورة؛ ليس له رؤية العورة ما بين السرة والركبة لا يراه إلا الزوج أو السيد كونه الذي يباح له الاتصال بها.\nففي هذه الحال إذا رأى الطبيب المختص أو الطبيبة المختصة أن هذا ينفع وأنه ليس هناك عقم يمنع الحمل وإنما هو شيء من المرض في مبيض المرأة أو في قنواتها أو الرجل ليس منيه يصل لضعف في منيه لا يصل إلى محل المرأة أو لأسباب أخرى فيؤخذ منه بالأنبوب بالإبرة ويحقن في رحم المرأة، هذا هو الجائز والأحوط تركه، حتى ولو قلنا بجوازه، الأحوط تركه لئلا يجر إلى ما لا تحمد عقباه.\nالمقدم: رغم أنه بين الزوجين.\nالشيخ: بين الزوجين لئلا يجر الزوجة إلى أن تفعل شيئًا خلاف ذلك وتزعم أنه من زوجها؛ لأنه تحيط به الأخطار تحيط به الأخطار فتركه أولى عند أهل العلم إلا عند الحيطة الكاملة عند الحيطة الكاملة.\nأما أن يؤخذ المني من غير الزوج ليحقن في زوجة الرجل فهذا محرم بإجماع المسلمين، هذا من جنس الزنا، كونها تأخذ ماء من غير زوجها لتحقنه فيها لعلها تحمل بماء هذا الرجل الأجنبي هذا منكر وهذا لا يجوز، ويجب تعزيرهما جميعًا وتأديبهما جميعًا على ولي الأمر إذا ثبت ذلك، حتى لا يقع مثل ذلك.\nوصورة ثانية..\nالمقدم: أو ثالثة.\nالشيخ: صورة ثالثة بالنسبة إلى الصورتين هاتين تكون ثالثة، وهي ثانية بالنسبة إلى الجواز، وهي ما إذا أخذ ماء الرجل ماء الزوج والزوجة جميعًا وجعلا في أنبوب حتى يمتزجا ويختلطا على صفة خاصة عند الأطباء ثم يحقن الماءان في رحم المرأة بعد اختلاطهما في الأنبوب الخاص الذي يفعله الطبيب، وهذه أخطر من الأولى وأشد ... أشد خطرًا لأنها قد توضع في أنبوب يختلط بأنابيب عند الأطباء، وقد يقع أخذ ماء من غير الزوجة أو من غير الزوج لشيء من الحيل أو شيء من التساهل الديني.\nفالحاصل أن هذه أجازها المجمع بالأكثرية وبعض أعضائه لم يجزها وبعض أعضائه توقف، وأنا ممن توقف في ذلك؛ لأنها خطيرة.\nفالحاصل: أن الجواز ينحصر في الزوج والزوجة فقط، أما ماء يؤخذ من غير الزوج أو من غير الزوجة فهذا محرم بإجماع المسلمين ليس فيه نزاع، إنما محل الخلاف ماء يؤخذ من الزوج يحقن في رحم امرأته، أو منهما جميعًا يوضع في أنبوب ساعات معلومة ثم يحقن في رحمها، هذا هو محل الخلاف وهو الذي رأى فيه المجمع الجواز في هاتين الصورتين مع وجوب التحفظ والحذر. نعم.\nالمقدم: جزاكم الله خيرا، إذًا: له صور متعددة وكل صورة لها حكمها.\nالشيخ: نعم ..، والذي أجازه المجمع هاتان الصورتان فقط.\nالمقدم: ما كان بين الزوجين نفسيهما.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7059/حكم-الانجاب-بواسطة-الانابيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_168/168005.mp3","categories":["الطب والتداوي"]},{"id":8911,"question":"أخونا يسأل عن حكم نقل الأعضاء كالقلب مثلًا، ولاسيما إذا كانت من غير مسلم إلى مسلم؟","title":"حكم نقل الأعضاء من جسد إلى آخر","answer":"الجواب: هذا موضوع عرض في مجلس هيئة كبار العلماء، وهو نقل عضو من ميت إلى حي لحاجة الحي إليه، واختلف فيه المجلس، منهم من رأى جوازه، ومنهم من رأى التوقف في ذلك، ومن رأى جوازه قيده بالقيود، وهو أن ينقل العضو إلى مسلم حي من الميت بشرط: أن يسمح به الميت في حال حياته، وأن لا يترتب عليه فتنة من الورثة، وأن يقرر الطبيب المختص أنه صالح لهذا الحي، وأنه يرجى نجاح الزراعة، زراعته فيه مثل: الكلية ونحوها.\nهذه مسألة خلاف بين أهل العلم في الوقت الحاضر، منهم من أجاز ذلك وقال: إنه لا بأس بالتبرع، إذا تبرع الحي المكلف الرشيد إذا تبرع بكليته أو نحوها لمسلم حي ينتفع بذلك، ومنهم من منع ذلك وقال: إن الإنسان لا يملك نفسه، ولا يملك أعضاءه، وليس له التصرف فيها بقطعها وبتها يعطيها أحد من الناس، وإنما يتصرف في المال، يعطي ويمنح ما لا يخالف الشرع، أما كونه يتصرف في نفسه بأن يعطي إصبعًا من أصابعه، أو كلية من كلاه أو غير ذلك؛ فليس له ذلك.\nوبكل حال فهي مسألة خلاف بين أهل العلم المعاصرين، وأنا عندي فيها التوقف، وبعض أهل العلم أجازها بهذه الشروط؛ أن يقرر الطبيب المختص أنها صالحة لهذا المريض، وأن يكون مسلمًا، وأن يقرر الطبيب نجاح العملية؛ وأن غالب الظن تنجح العملية، وأن يسمح المنقولة من الميت قبل أن يموت في حياته يسمح بذلك، وأن لا يخشى فتنة أيضًا. نعم.\nالمقدم: لا أثر في الحكم بين كونها تنقل من غير مسلم إلى مسلم؟\nالشيخ: هذا أيضًا محل نظر، ومن أجازها أجازها من غير المسلم أيضًا كما ينقل عظمه ودمه ونحو ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7067/حكم-نقل-الاعضاء-من-جسد-الى-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_169/16903.mp3","categories":["الطب والتداوي"]},{"id":8984,"question":"هنا رسالة مطولة من صفحتين من القطع الكبير وبعثت بها إحدى الأخوات من العراق تقول: الوالدة المعذبة علية علي جواد أختنا تشكو حالة ابنها الصحية حيث أنه كلما قرب الاختبار اعتراه كثير من الأمراض، وترجو التوجيه ولاسيما أنها تخشى الذهاب إلى المشعوذين والكهان؟","title":"دور الأم تجاه ولدها المريض","answer":"الجواب: نوصي بالدعاء له بالعافية أن تدعو له كثيرًا في صلاتها في سجودها في تشهدها قبل السلام، تدعو له بالعافية والشفاء، وتعرضه على الأطباء المختصين في مثل هذا المرض من علماء النفس وغيرهم، وتوصي أيضًا من يقرأ عليه من خواص الطيبين يقرءون عليه لعل الله يشفيه في ذلك، قد تكون هذه نفسًا وهي اللي يسمونها العين، قد تكون.. والقراءة ينفعه الله بها في هذا الشيء، فإذا تيسر من الناس الطيبين من يقرءوا عليه فهذا إن شاء الله يكون سببًا للشفاء، وهكذا عرضه على بعض الأطباء الطيبين من علماء النفس، أو علماء مثل هذا المرض الذي يعتري الناس فإذا تيسر من يعالجه فالحمد لله وإلا فالقراءة كافية، يقرأ عليه مع الدعاء، أما الذهاب إلى المشعوذين فلا يجوز، الكهان الذين يخدمون الجن ويسألون الجن ويدعون علم الغيب هؤلاء لا يجوز إتيانهم ولا سؤالهم بل يجب البراءة منهم والحذر منهم، لقول النبي ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا رواه مسلم في الصحيح.\nوقال عليه الصلاة والسلام: من أتى كاهنًا أو عرافًا فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، فالواجب على كل مؤمن وعلى كل مؤمنة الحذر مما حرم الله ورسوله والاكتفاء بماشرع الله، ونسأل الله له الشفاء والعافية، نسأل الله أن يمن عليه بالشفاء وأن يخلصه مما أصابه، وأن ييسر له العلاج الصالح الناجع إنه سميع قريب.\nالمقدم: جزاكم الله خيرًا، إذًا سماحة الشيخ لا ترون أن هناك محظورًا في عرضه على بعض الثقات كيما يقرأ عليه أو كذا؟\nالشيخ: نعم.\nالمقدم: ولا يعد هذا أيضًا من الذهاب إلى ما أسميتم بالمشعوذين؟\nالشيخ: لا، تلتمس الناس الطيبين المعروفين بحسن العقيدة والقراءة على المرضى لعل الله أن ينفعه بذلك؛ لأن القراءة على المرضى نافعة، الله جعل في القرآن شفاء، والنبي ﷺ قال: اعرضوا علي رقاكم لا بأس بالرقى ما لم تكن شركًا، ورقى النبي ورقي عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/7142/دور-الام-تجاه-ولدها-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17409.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":9297,"question":"وأخيراً. يسأل الأخ أحمد علي معوضة في رسالته، فيقول: هل صحيح أن الجن تستطيع أن تدخل جسم الإنسان وتجعله يتكلم أو تتكلم بصوته، أفيدونا أفادكم الله؟","title":"ما صحة تلبُّس الجِنِيِّ بالإنس؟","answer":"الجواب: نعم، الجن تلتبس بالإنسان، تلتبس به على صفة خاصة حتى تنطق على لسانه، وتتكلم على لسانه بأشياء يعرف صوت الجني من صوت الإنسي، وهذا واقع قديماً وحديثاً، وهو المجنون الذي تلتبس به الجن هو المجنون، يتكلم الجني على لسانه، أعطوني كذا، أعطوني طيب، اذبحوا لي كذا، افعلوا كذا، ترى الدراهم في المحل الفلاني، بصوت يسمعه الناس غير صوت الإنسي، وهذا شيء يقع، ومن أنكره فقد غلط، وهذا التباس الجني بالإنسي، وبهذا يكون مجنوناً يختل عقله ويضطرب، فإذا ذهب عنه وفارقه رجع إليه عقله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7470/ما-صحة-تلبس-الجني-بالانس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23611.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9317,"question":"وهذه رسالة وردت من السائل عبد خلف محمد من العراق، يقول في رسالته: كنت غافلاً فوجدت سحراً قد عملوه لي ولزوجتي ليطردوني عن داري؛ لأنهم يقولون: هذا البيت مسكون وفيه شياطين، وذهبت إلى سيد من السادة أهل الدين وكشف لعائلتي ولبيتي، وقال لي: فعلوا لك سحراً قدره مائتين وخمسين دينار فهل هذا صحيح، ووجدت منه قطعة طويلة مكتوبة بالأزرق، وذهبت إلى هذا السيد وسحبه وأخذ مني عشرين دينار، وأن البيت لم يأتيه أي شيء، هل يصيبني ذنب مما فعلت أم لا؟","title":"حكم الذهاب إلى السحرة والعرافين","answer":"الجواب: السحرة والكهنة والعرافون لا يجوز سؤالهم ولا تصديقهم بما يقولون، يقول النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً رواه مسلم في الصحيح، والعراف: هو الذي يدعي معرفة الأمور من طريق الغيب والتكهن، وهكذا الكاهن وهو الذي له رئي من الجن وصاحب من الجن يخبره ببعض المغيبات التي يسمعها من الناس في بلدان بعيدة أو قريبة أو يسمعها حين يسترق السمع من جهة السماء، فهؤلاء لا يسألون ولا يصدقون، وهكذا السحرة: وهم الذين يتعاطون أموراً يضرون بها الناس، فالسحر له وجود وله حقيقة وبعضه خيال، لكن بعضه له حقيقة يقتل، ويمرض، ويفرق بين المرء وزوجه، فلا يجوز سؤال السحرة ولا تصديقهم ولا العلاج عندهم، ولكنك تعالج المرض عند الأطباء المعروفين، أو بقراءة القرآن، يقرأ عليك القرآن وآيات السحر وينفث عليك، أو في ماء تشربه وتتروش به لا بأس.\nأما المعروفون بالسحر والمعروفون بتعاطي السحر أو الكهانة أو العرافة التي فيها دعوى علم الغيب فهذا كله لا يجوز، هؤلاء كلهم لا يجوز سؤالهم ولا تصديقهم.\nوعليك أن تتوب إلى الله من سؤال هذا الساحر، وعليك أن تعمل الأدوية المباحة والطب المباح، ومن ذلك أن تقرأ أنت أو يقرأ لك بعض الإخوان الطيبين أصحاب العقيدة الطيبة في ماء، يقرأ لك الفاتحة وآية الكرسي، وقل هو الله أحد والمعوذتين، وآيات السحر الموجودة في سورة الأعراف، وفي سورة يونس، وفي سورة طه، يقرؤها في الماء ثم تشرب من ذلك الماء وتتروش بالباقي، هذا بإذن الله علاج لما قد يقع من السحر، وقد يجعل فيه سبع ورقات من السدر الأخضر يدق ويجعل في الماء ويكون أيضاً من باب الطب والعلاج المباح، لأنه مجرب ونافع في حق المسحور، وفي حق من حبس عن زوجته لأسباب، فإن هذا العلاج الشرعي بقراءة الفاتحة وآية الكرسي، وآيات السحر المعروفة في سورة الأعراف، وسورة يونس، وسورة طه، وقل يا أيها الكافرون، وقل هو الله أحد والمعوذتين، تقرأ في الماء وفيه السدر، أو ليس فيه سدر ثم يشرب منه الإنسان ويتروش منه المصاب بالسحر، أو المحبوس عن زوجته، ثم يبرأ بإذن الله ، وإن نفث فيه مع ذلك: اللهم رب الناس، أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقماً، وكرر هذا ثلاثاً طيب، هذه دعوات طيبة ثابتة عن رسول الله عليه الصلاة والسلام: اللهم رب الناس، أذهب البأس، واشف أنت الشافي لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً.\nوهكذا الدعاء المعروف: باسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد، الله يشفيك، باسم الله أرقيك ثلاث مرات أيضاً هذا ثابت عن النبي ﷺ أيضاً، فإذا نفث في هذا في الماء فهو أيضاً طيب ومن أسباب الشفاء وهو علاج نبوي علاج شرعي، الدعاء الأول: اللهم رب الناس أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً.\nوالدعاء الثاني: باسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد، الله يشفيك، باسم الله أرقيك يقوله ثلاث مرات.\nهذا من الدعاء الطيب الذي يرجى فيه النفع، والله المستعان، نعم، مع سؤال الله جل وعلا.. الإنسان يسأل ربه أن الله يمن عليه بالشفاء.. يضرع إلى الله في سجوده، وفي آخر التحيات، بين الأذان والإقامة، في آخر الليل، في جميع الأوقات، يدعو ربه، يسأله ويضرع إليه أن الله يشفيه مما أصابه، ويزيل عنه ما به من أذى، والله يحب السائلين جل وعلا، وهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7487/حكم-الذهاب-الى-السحرة-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_237/23705.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9370,"question":"وننتقل إلى رسالة وصلت من رابغ وباعثها أحد الإخوة يقول عبدالله الهواري: أخونا له ثلاثة أسئلة:سؤاله الأول: يسأل عن معنى حديث رسول الله ﷺ الذي يقول: شفاء أمتي في ثلاث: كية من نار -كما يورد سماحة الشيخ- أو آية من كتاب الله، أو جرعة من عسل هل هذا حديث صحيح؟","title":"معنى حديث: (الشفاء في ثلاث ...)","answer":"الجواب: الحديث في الصحيح يقول الرسول ﷺ: الشفاء في ثلاث: كية نار، أو شرطة محجم، أو شربة عسل ليس فيه الآية، أما الآية تؤخذ من قوله تعالى: وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِينَ [الإسراء:82] ومن قوله تعالى: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] ومن عمله ﷺ فإنه كان يقرأ الآيات على المريض، كان يقرأ على نفسه: قُلْ هُوَ اللَّهُ أَحَدٌ  والمعوذتين عند النوم إذا اشتكى عليه الصلاة والسلام.\nوالصحابة كانوا يقرءون على المريض من الآيات، وقد قرأ بعض الصحابة على لديغ سورة الفاتحة فشفاه الله، وعرضوا هذا على النبي ﷺ فأقرهم، وقال: وما يدريك أنها رقية؟ وكانوا قد جعل لهم قطيع من الغنم، فأخذوه وأقرهم النبي ﷺ على ذلك وقال: اضربوا لي معكم بسهم.\nفالحاصل أنه ﷺ أقرهم على قراءة القرآن على المريض للاستشفاء.\nوأما الحديث فالذي فيه: الشفاء في ثلاث: كية نار، أو شرطة محجم - يعني: حجامة- أو شربة عسل، قال: وما أحب أن أكتوي وفي اللفظ الآخر: وأنا أنهى أمتي عن الكي رواه البخاري في الصحيح، فهذا يدل على أن هذه الثلاث من أسباب الشفاء، الكي عند الحاجة إليه، والحجامة عند الحاجة إليها، والعسل، والله بين في كتابه العظيم أن العسل فيه شفاء للناس، لكن إذا تيسر علاج بغير الكي فهو أولى؛ ولهذا قال الرسول ﷺ: وما أحب أن أكتوي، وقال: وأنا أنهى أمتي عن الكي لكنه كوى بعض أصحابه للحاجة.\nفالحاصل: أنه لا يشرع الكي إلا عند الحاجة، عند عدم وجود ما يكفي عنه، فإذا تيسر دواء آخر يكفي عنه فالأولى ترك الكي؛ لأنه نوع تعذيب بالنار، فلا يصار إليه إلا عند الحاجة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7534/معنى-حديث-الشفاء-في-ثلاث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/186009.mp3","categories":["الطب والتداوي","شروح الحديث"]},{"id":9374,"question":"أخونا عبدالله الهواري من رابغ يسأل أيضًا عن الحناء للرجال ولا سيما إذا كان للعلاج؟","title":"حكم استعمال الرجل الحناء للعلاج","answer":"الجواب: لا نعلم فيه بأسًا للعلاج، أما أن يفعله كالنساء فلا يجوز لأنه تشبه بالنساء، أما إذا فعله الرجل على وجه يعالج به مرضًا في رجله أو يده أو غير ذلك فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/7538/حكم-استعمال-الرجل-الحناء-للعلاج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18612.mp3","categories":["الطب والتداوي"]},{"id":9381,"question":"الأخ ياسين عبدالرحيم أحمد يسأل ويقول: يصف بعض الناس في منطقتهم دواءً لكنه نجس واستعمله البعض فعوفي ولا سيما أولئك الذين لهم حبيبات في وجوههم ويسأل عن التوجيه لو تكرمتم شيخ عبدالعزيز؟","title":"حكم التداوي بالأشياء المحرمة والنجسة","answer":"الشيخ: يصف إيش؟\nالمقدم: يقول: إن هناك من يصف أدوية نجسة ولا سيما لأولئك الذين لهم حبيبات في وجوههم، ويسأل عن التوجيه؟\nالشيخ: هذا لا يجوز، التداوي بالحرام والنجاسات أمر منكر لا يجوز؛ لأن الرسول عليه الصلاة والسلام قال: عباد الله تداووا ولا تداووا بحرام وقال: إن الله لم يجعل شفاءكم فيما حرم عليكم وسأله رجل عن الخمر يصنعها للدواء فقال: إنها ليست بدواء ولكنها داء فلا يجوز للمسلم ولا للمسلمة أن يتداووا بالحرام، لا من الأبوال، ولا من العذرة، ولا من الدماء ولا من سائر النجاسات، الدواء يكون بالمباح والطاهر، وعلى من أصيب بشيء من الأدواء يسأل أهل الخبرة من الأطباء وأهل الاختصاص والله جل وعلا ما أنزل داءً إلا أنزل له شفاء كما قاله النبي ﷺ، فيلتمس من أهل الطب من يعرف داءه، حتى يعطيه الدواء المناسب، ولا ييئس ولا يعمل بما يغضب الله عليه جل وعلا، ولكن يتصبر ويتحمل حتى يسهل الله له الشفاء، أما التساهل مع الناس والأخذ بما يقوله الناس من الرخص الباطلة التي لا أساس لها هذا لا يجوز، وليس العامة قدوة في هذه الأمور إذا فعلوا الأدوية الرديئة النجسة والمحرمة هؤلاء ليس بالقدوة ولا يجوز تقليدهم في ذلك ولا متابعتهم في ذلك، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7545/حكم-التداوي-بالاشياء-المحرمة-والنجسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_187/18704.mp3","categories":["الطب والتداوي"]},{"id":9466,"question":"للأخت من العراق سؤال ثان في هذه الرسالة تقول فيه: هناك بعض الاعتقادات عند بعض الناس لإفساد السحر وإبطاله، وهي عبارة عن أخذ شيء من الرصاص المذاب على النار، وسكبه في إناء فيه ماء، ثم يوضع على رأس المسحور وتعاد العملية ثلاث مرات في اليوم، فهل هذا له أصل؟ وما حكم الشرع فيه؟","title":"حكم إبطال السحر بإذابة الرصاص وجعله مع الماء على الرأس","answer":"الجواب: هذا شيء لا أصل له، ولا فائدة فيه، وهو تلبيس وتخييل، وإلا فهذا لا فائدة فيه، إذابة الرصاص وجعله على الرأس، وجعله في الماء ثم جعله.. كل هذا يفعله الكاهنات، ويفعله الملبسون والمشعوذون تلبيساً، وإلا فهم يعملون في خدمة الجن، وخدمة الشياطين، فلا يجوز الحل بهذا الشيء، وإنما يحل السحر بما شرع الله من الأدوية الشرعية، والقراءة، هذا هو الطريق في حل السحر، فإذا أصيب الإنسان بالسحر، أو حبس عن زوجته عولج بالقراءة، يقرأ عليه الرجل الطيب المعروف بالخير، وإن كانت امرأة قرأت عليها المرأة الطيبة بالخير، المعروفة بالخير، آيات من القرآن، بفاتحة الكتاب، آية الكرسي، آيات السحر المعروفة في سورة الأعراف، وفي سورة يونس وفي سورة طه مع قراءة: قل يا أيها الكافرون، وقل هو الله أحد والمعوذتين، ثم يشرب منه ما تيسر ثم يتروش بالباقي، فإنه بإذن الله يزول عنه السحر، وهكذا يزول عنه الحبس الذي جرى عليه حين حبس عن زوجته، وإذا كرر ذلك مرتين أو ثلاث أو أكثر فلا بأس، حتى يزول عنه الأذى، وإذا جعل فيه سبع ورقات من سدر كان هذا أيضاً طيباً، فقد استعمل هذا وذكره المتقدمون وينفع بإذن الله، والسدر شيء طاهر لا بأس به، فإذا دق وجعل في الماء مع القراءة فيه كان هذا من أسباب الشفاء، وإذا أضاف إلى ذلك الدعاء المعروف الثابت عن النبي ﷺ: اللهم رب الناس، أذهب الباس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً.\nإذا دعا بهذا الدعاء ثلاث مرات كان حسناً ينفث به في الماء، وهكذا: باسم الله أرقيه من كل شيء يؤذيه، من شر كل نفس أو عين حاسد، الله يشفيه باسم الله أرقيه ثلاث مرات، يكرر هذا: باسم الله أرقيه يعني: المريض، أو باسم الله أرقيك يخاطبه من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد، الله يشفيك باسم الله أرقيك، يكررها ثلاث مرات، هذا أيضاً من الدعوات المناسبة لهذا العلاج، وآيات السحر معروفة، في الأعراف قوله : وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ۝ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ۝ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ[الأعراف:117-119] .\nوفي يونس يقول : وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ ۝ فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ ۝ فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ۝ وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ [يونس:79-82]، وفي طه يقول سبحانه: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لا تَخَفْ إِنَّكَ أَنْتَ الأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:65-69]، ثم يقرأ: قل يا أيها الكافرون، قل هو الله أحد ثلاث مرات، قل أعوذ برب الفلق ثلاث مرات، قل أعوذ برب الناس ثلاث مرات، فهذا هو الدواء الشرعي، والعلاج الشرعي الذي قد وصفه أهل العلم وجربه أهل العلم وجربناه أيضاً فنفع الله به، فهو دواء طيب بآيات الله، وإذا جعل فيه ما تقدم من ورقات السدر السبع ودقت هذا كله طيب أيضاً.\nوإذا عرف دواء آخر لا محذور فيه، دواء آخر بأوراق، أو بحبوب أو بإبر فلا بأس، إذا كان سليماً مما حرم الله من نجاسة أو غيرها، أما التداوي بما يتعاطاه خدام الجن، والمشعوذون من الرصاص وغيره أو بالذبح للجن، أو بالاستجارة بالجن فهذا كله ما يجوز منكر، وبعضه شرك.. الاستجارة بالجن ودعاؤهم، والاستغاثة بهم والذبح لهم كل هذا من الشرك الأكبر، نسأل الله العافية، فيجب الحذر ويجب على من بلي بهذا الشيء أن يحذر ما حرم الله وأن يتعاطى ما أباح الله.. لا بأس، يشرع له التداوي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7628/حكم-ابطال-السحر-باذابة-الرصاص-وجعله-مع-الماء-على-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_240/24006.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9543,"question":"تسأل الأخت أيضاً وتقول: يوجد في مدينتا بعض الناس يستفتحون بالسلة، وهذه الطريقة هي أنهم يأتون بسلة طاهرة ويضعون بداخلها قرآناً ويغلقون فتحتها بسجادة الصلاة، ويضعون فوق السجادة مفتاح ويضعون على جانب السلة قلم وتحتها ورقة، ويأتي شخصان ويحملان السلة ويحركانها، وآخر يقرأ سورة الجن وعندما يقرؤها تأتي روح ميت، ويسألونها بعض الأسئلة وتجيب بواسطة القلم والورقة، والأسئلة التي في علم الغيب تقول: الله أعلم، والأسئلة التي لا تستطيع أن تجيب عليها كتابة بواسطة الورقة والقلم تقول فيها أيضاً: الله أعلم، المهم: هل هذه فعلاً روح ميت أم أنها جني وما الحكم في مثل هذا العمل؟","title":"التحذير من عمل الكهان والعرافين","answer":"الجواب: هذا عمل منكر ولا يجوز وهو من الكهانة المحرمة، فلا يجوز فعل هذا بالكلية، وهذا العمل من أعمال الشياطين وليس من أرواح الموتى ولكنه من أعمال الشياطين التي بها يلبسون على الناس ويأخذون أموالهم بالباطل، هذا العمل لا يجوز بل هو منكر ومن أعمال الكهانة، والواجب على ولاة الأمور منع هذا وتأديب من فعله حتى لا يعود إلى مثله، ولا يجوز للمسلم أن يشارك في هذا ولا أن يسألهم عن شيء، نعم لقول النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً، ولقوله ﷺ: من أتى عرافاً أو كاهناً فصدقه بما يقول، فقد كفر بما أنزل على محمد ﷺ، هذا من جنس العرافين والكهنة، وهذه الأرواح التي تطلب هي من أرواح الجن والشياطين وليست أرواح الموتى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7712/التحذير-من-عمل-الكهان-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24611.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9546,"question":"تسأل الأخت أيضاً وتقول: يوجد في مدينتا بعض الناس يستفتحون بالسلة، وهذه الطريقة هي أنهم يأتون بسلة طاهرة ويضعون بداخلها قرآناً ويغلقون فتحتها بسجادة الصلاة، ويضعون فوق السجادة مفتاح ويضعون على جانب السلة قلم وتحتها ورقة، ويأتي شخصان ويحملان السلة ويحركانها، وآخر يقرأ سورة الجن وعندما يقرؤها تأتي روح ميت، ويسألونها بعض الأسئلة وتجيب بواسطة القلم والورقة، والأسئلة التي في علم الغيب تقول: الله أعلم، والأسئلة التي لا تستطيع أن تجيب عليها كتابة بواسطة الورقة والقلم تقول فيها أيضاً: الله أعلم، المهم: هل هذه فعلاً روح ميت أم أنها جني وما الحكم في مثل هذا العمل؟","title":"التحذير من عمل الكهان والعرافين","answer":"الجواب: هذا عمل منكر ولا يجوز وهو من الكهانة المحرمة، فلا يجوز فعل هذا بالكلية، وهذا العمل من أعمال الشياطين وليس من أرواح الموتى ولكنه من أعمال الشياطين التي بها يلبسون على الناس ويأخذون أموالهم بالباطل، هذا العمل لا يجوز بل هو منكر ومن أعمال الكهانة، والواجب على ولاة الأمور منع هذا وتأديب من فعله حتى لا يعود إلى مثله، ولا يجوز للمسلم أن يشارك في هذا ولا أن يسألهم عن شيء، نعم لقول النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً، ولقوله ﷺ: من أتى عرافاً أو كاهناً فصدقه بما يقول، فقد كفر بما أنزل على محمد ﷺ، هذا من جنس العرافين والكهنة، وهذه الأرواح التي تطلب هي من أرواح الجن والشياطين وليست أرواح الموتى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7712/التحذير-من-عمل-الكهان-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24611.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9612,"question":"السؤال الثالث: نحن نسمع بأن من مات غرقًا أو حرقًا لم تمسه النار، نرجو رأي الدين في ذلك، أفيدونا ولكم الأجر والمثوبة من الله؟","title":"فضل من مات بالغرق أو الحرق","answer":"الجواب: نعم، ثبت عن النبي ﷺ فيها عدة أحاديث أنه أخبر: أن من يموت بالغرق أو بالطاعون أو بالبطن من إسهال أنه شهيد فالمطعون شهيد والمبطون شهيد وصاحب الغرق شهيد وصاحب الهدم شهيد والمقتول في سبيل الله شهيد ...... في سبيل الله شهيد في عدة شهداء آخرين وهذا من فضل الله جل وعلا بأن يكون لهم في ميتتهم أجر وثواب جزيل لكن أفضلهم الشهداء في سبيل الله الذين يقتلون في سبيل الله، هم أفضلهم لا يغسلون ولا يصلى عليهم ؛ لأنهم أحياء عند ربهم يرزقون.\nوأما الشهداء الآخرون غير الشهداء في سبيل الله؛ كالمبطون والمطعون وصاحب الهدم والغرق فهؤلاء يغسلون ويصلى عليهم، يلحق بهم من يموت في انقلاب السيارات أو باصطدام السيارات فإن هذا يشبه الذي يموت بالهدم ويرجى لهم الشهادة ولكن يغسلون ويصلى عليهم مثل الموت بالبطن أو الغرق. نعم.","link":"https://binbaz.org.sa/fatwas/7770/فضل-من-مات-بالغرق-او-الحرق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19310.mp3","categories":["مسائل متفرقة في الجنائز","الطب والتداوي"]},{"id":9619,"question":"أختنا السائلة تسأل أيضاً وتقول: هناك بعض الدهون أو الشامبو التي توضع في رءوس النساء، وتغسل به الرءوس يحتوي على نعم من نعم الله، كالبيض والليمون مثلاً، فما حكم استعماله، وخاصةً أن النساء يستعملنه ثم يزلنه بالماء في داخل دورات المياه، فيختلط بالنجاسات، أفيدونا أفادكم الله؟","title":"حكم استعمال بعض المواد الغذائية كدواء للشعر","answer":"الجواب: لا حرج فيه، ما نعلم فيه حرج، في استعماله لأجل مصلحة الرأس مصلحة التداوي، لا مانع يتداوى بالبيض، يتداوى بالحنطة ويتداوى بغير ذلك، الشيء الذي فيه منفعة يتداوى به، وإذا جعل في الرأس للتداوي فقد تعفن، ما عاد يصلح للأكل، صار متعفناً ما يضر غسله في الحمامات. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7783/حكم-استعمال-بعض-المواد-الغذاىية-كدواء-للشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27107.mp3","categories":["الطب والتداوي"]},{"id":9696,"question":"هذه رسالة وردت إلى البرنامج من الجمهورية الجزائرية، جنوب الجزائر قرية تماسين من السائلة (ب. س) تقول في رسالتها: هناك بنت مشلولة في يديها ورجليها، وعجز الأطباء عن علاجها، وسمع أهلها برجل يعالج بطريقة خاصة، حيث أنهم يضعون الكمون تحت رأسها وفي الصباح يأخذونها إلى الرجل ومعهم هذا الكمون فيقول لهم: بأنها بها مس من الجنون، فطلب منهم أن يأتوه بجدي، فأخذوا له الجدي فبدأ الرجل يسن السكين فصار الجدي مشلولاً مثل الطفلة، وبعد ذلك قطع شيئاً من أذن الجدي ومسح بها عند أنف الطفلة ووراء أذنيها، وأمر الجدي بالذهاب فقام مسرعاً وقال لهم: ابنتكم بخير إن شاء الله، فقامت الطفلة كأن لم يكن بها شلل، وبعد ذلك كتب لها بعض الأدوية من الحشائش لتتابع العلاج في البيت، لكي تشفى تماماً، وقبل أن يبدأ في مخاطبتهم، يبدأ باسم الله، ويقرأ آية الكرسي، ثم يأخذ هذا الكمون وينظر فيه ويبدأ يقول: ويصف حالة المريض ما به ومتى وكيف، أرجو أن تدرسوا هذه القضية وتفيدونا برأيكم في هذا، وإذا كانت الإجابة بمنع مثل هذا العمل فما الدليل، علماً بأن أهل هذه الطفلة سألوني عن الجواب فلم أستطع أن أجبهم وكتبت إليكم أفيدونا أفادكم الله؟","title":"حكم الذهاب بالمرضى إلى الكهان والمشعوذين","answer":"الجواب: هذا العمل يدل على أن الرجل كاهن يستخدم الجن ويتقرب إليهم بما يريدون، وأما جعله الكمون تحت الرأس، وقطع أذن الجدي وما أشبهه هذا تلبيس، حتى لا يكشف أمره، وإنما هو رجل مستخدم للجن، وقد يكون بعض الجن مس المرأة بشيء حتى حصل لها ما حصل، ثم اتفق معهم على أن يتركها فتركها فحصل الشفاء، وليس في الحقيقة من جهة قراءته وإنما يلبس على الناس بقراءة آية الكرسي أو بقوله: باسم الله عند إعطائهم الكمون كل هذا تلبيس.\nوالواجب عدم الذهاب إلى هذا الرجل وأشباهه؛ لقول النبي ﷺ: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً رواه مسلم في الصحيح، ولقوله ﷺ: من أتى عرافاً أو كاهناً فصدقه بما يقول، فقد كفر بما أنزل على محمد ﷺ رواه أهل السنن؛ ولقوله ﷺ في الكهان: لا تأتوهم وهذا منهم، فإن عمله هذا يدل على أنه يستخدم الجن ويسألهم ويتفق معهم على ما يريدون، ويعطونه ما أراد حتى يعبدهم من دون الله، ويعطيهم ما يريدون حتى يخدموه فلا يجوز سؤال هذا، ولا يجوز أخذ علاجه، ولا الذهاب إليه بالكلية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7866/حكم-الذهاب-بالمرضى-الى-الكهان-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_253/25307.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9773,"question":"أولى الرسائل وردت من المستمعة مهدية بنت صدام من العراق، تقول في رسالتها: ما هو العمل لإبطال السحر بارك الله فيكم؟","title":"الوسائل الشرعية لإبطال السحر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والعاقبة للمتقين، والصلاة والسلام على عبده ورسوله وخيرته من خلقه، وأمينه على وحيه، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد:\nفعلاج السحر يكون بشيئين:\nأحدهما: الرقى الشرعية.\nوالثاني: الأدوية المباحة التي جربت في علاجه.\nومن أنجع العلاج وأنفع العلاج الرقى الشرعية، فقد ثبت أن الرقية يرفع الله بها السحر، ويبطل بها السحر.\nوهناك نوع ثالث وهو: العثور على ما فعله الساحر من عقد أو غيرها وإتلافها، كذلك من أسباب من زوال السحر وإبطاله.\nفمن الرقى التي تستعمل أن يرقى المسحور بفاتحة الكتاب وآية الكرسي، وقل يا أيها الكافرون، قل هو الله أحد، وقل أعوذ برب الفلق، وقل أعوذ برب الناس، مع آيات السحر التي جاءت في سورة الأعراف وسورة يونس وسورة طه.\nوهي في سورة الأعراف قوله سبحانه: وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ۝ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ۝ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ [الأعراف:117-119].\nوفي سورة يونس يقول سبحانه: وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ ۝ فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ ۝ فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ۝ وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ [يونس:79-82].\nوفي سورة طه يقول سبحانه: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لا تَخَفْ إِنَّكَ أَنْتَ الأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:65-69].\nفهذه الآيات الكريمات العظيمات ينفث بها في الماء، ثم بعد ذلك يصب هذا الماء الذي قرئ فيه على ماء أكثر، ثم يتروش به المسحور، ويشرب منه بعض الشيء كثلاث حسوات يشربها منه، ويزول السحر بإذن الله ويبطل، ويعافى من أصيب بذلك، وهذا مجرب مع المسحورين، جربناه نحن وغيرنا ونفع الله به من أصابه شيء من ذلك.\nوقد يوضع في الماء سبع ورقات من السدر تدق وتلقى في الماء الذي يقرأ فيه أيضاً ولا بأس، قد ينفع الله بذلك أيضاً، سبع ورق سدر وهي شجر النبق، تدق وهي خضر رطبة تدق ثم توضع في الماء الذي يقرأ فيه، ويشرب منه ما تيسر ويغتسل بالباقي المسحور.\nهذا من الدواء النافع والرقية النافعة.\nوهناك أدوية لمن يتعاطى هذا الشيء.. ويعالج بهذا الشيء أدوية مباحة قد يستفاد منها في علاج السحر وإزالته، كما أشار إلى هذا العلامة ابن القيم رحمه الله في بيان النشرة المشروعة، وقد ذكر ذلك أيضاًَ الشيخ عبد الرحمن بن حسن آل الشيخ في كتابه فتح المجيد في شرح كتاب التوحيد في باب ما جاء في النشرة.\nأما ما يتعلق بإتيان الكهان أو السحرة أو المشعوذين هذا لا يجوز، وإنما الطريق الشرعي هو ما ذكرنا من القراءة على المسحور، أو القراءة في ماء ويشربه ويتروش منه، وإن وضع فيه سبع ورقات من السدر الأخضر الرطبة ودقت فهذا أيضاً قد ينفع بإذن الله مع القراءة، وهذا شيء مجرب.\nوالغالب على من استعمل هذا مع إخلاصه لله وتوجهه إلى الله في طلب الشفاء أنه يعافى بإذن الله، وعلى المسحور أن يضرع إلى الله وأن يسأله كثيراً أن يشفيه ويعافيه، وأن يصدق في طلبه، وأن يعلم أن ربه هو الذي يشفي، وهو الذي بيده الضر والنفع، والعطاء والمنع، ليس بيد غيره سبحانه وتعالى. نعم.\nالمقدم: بارك الله فيكم، ما أدري رأي سماحتكم في مقولة يتناقلها كثير ممن يرتادون أماكن السحرة يقولون: لا يحل السحر إلا ساحر، وبعضهم يقول: أذهب إلى الساحر ليدلني على مكان العقد حتى أحلها بعد ذلك؟\nالجواب: السحرة والكهنة لا يؤتون، النبي ﷺ نهى عن إتيانهم وعن سؤالهم قال: من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين يوماً وقال: من أتى كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام.\nوالسحرة كفرة، لا يجوز إتيانهم ولا سؤالهم.\nوأما هذه العبارة: لا يحل السحر إلا ساحر، فهذا يروى عن الحسن البصري التابعي الجليل أنه قال: لا يحل السحر إلا ساحر، والنبي ﷺ سئل عن هذا، النبي ﷺ سئل عن النشرة يعني: حل السحر عن المسحور، قال: هي من عمل الشيطان يعني: الذي يتعاطى حله بالسحر، قال ﷺ: هي من عمل الشيطان يعني: النشرة بالسحر وأنواعه، هذا هو من عمل الشيطان، رواه الإمام أحمد رحمه الله وأبو داود رحمه الله بإسناد جيد، وهو موجود في باب النشرة هذا الحديث.\nفالمقصود: أن حل السحر بالنشرة الشيطانية التي يتعاطاها السحرة هذا مثل ما قال النبي ﷺ: هي من عمل الشيطان هكذا قاله المصطفى عليه الصلاة والسلام: هي من عمل الشيطان فلا يجوز حلها بطريق السحرة، يعني لا يجوز حل السحر بطريق السحرة وذلك يسمى النشرة، ولكن يحل بطريق القراءة والأدوية المباحة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7940/الوساىل-الشرعية-لابطال-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25801.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":9839,"question":"هذه رسالة من ممرضة مصرية تعمل بالمملكة العربية السعودية في أبها، تقول في رسالتها: إنني أعمل ممرضة، وأحيانًا أعطي للرجال إبر بحكم عملي في حالة عدم وجود ممرض رجل يعطيهم هذه الإبر، ويكون المريض في حالة ماسة لهذا العلاج، فما حكم ذلك؟ وهل علي إثم؟","title":"حكم ضرب الممرضة الإبر للرجال للضرورة","answer":"الجواب: إذا دعت الحاجة إلى ذلك فلا حرج إن شاء الله، ولكن ينبغي لك أن تكوني مع النساء، وأن يكون الممرضون من الرجال للرجال، وأن كلًا يحافظ على وقته، وأن يؤدي ما عليه من الخدمة، فإذا دعت الضرورة إلى أن تقومي أنت بضرب الإبرة للمحتاج عند عدم وجود الممرض فلا حرج عليك إن شاء الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8005/حكم-ضرب-الممرضة-الابر-للرجال-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19806.mp3","categories":["الطب والتداوي"]},{"id":9900,"question":"السائل يقول: هل يجوز لطلاب الطب الذكور أن يكشفوا على النساء على سبيل التعلم، لاسيما أن ذلك يؤدي إلى ملامسة أعضاء المرأة وهي مكشوفة وخاصة إذا كان ذلك في شهر رمضان؟","title":"حكم كشف الطبيب على المرأة للتعليم","answer":"الجواب: الذي يظهر لي أنه لا يجوز لأنه وسيلة للشر إلا عند الضرورة إذا لم يوجد طبيبات واضطرت المرأة إلى الكشف؛ فلا بأس عند الضرورة، لقول الله سبحانه: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119] فعند الضرورات وإلا فالواجب إحالتهن للطبيبات وعدم كشف الشباب عليهن؛ لأن ذلك يسبب فتنة وخطراً عظيماً نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8068/حكم-كشف-الطبيب-على-المراة-للتعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27312.mp3","categories":["الطب والتداوي"]},{"id":9923,"question":"وهذه رسالة وردت من (م. ب) من جامعة البترول والمعادن بالظهران يسأل فيها عن أمرين: في الأول يقول: مسألة التداوي؛ فإن بعض أهل العلم قال ما محصلته: أنه لا يجب التداوي من مرض ولو ظن نفعه وتركه أفضل روي عن الإمام أحمد ؛ لأنه أقرب للتوكل، ولخبر الصديق إلى آخره. نرجو بسط القول في هذه المسألة، وما هو خبر الصديق؟ وما رأي سماحتكم؟","title":"حكم التداوي من الأمراض","answer":"الجواب: الصواب في التداوي أنه مستحب ومشروع، ذكره النووي رحمه الله وآخرون عن جمهور العلماء، وأن قول الأكثرين أنه مستحب، وذهب بعض أهل العلم إلى أنه مستوي الطرفين لا يستحب ولا يكره بل هو حلال، وذهب آخرون إلى أن تركه أفضل، ويروى عن الصديق أنه قال لما قيل له: الطبيب؟ قال: الطبيب أمرضني ولكن لا أعلم صحة هذا عن الصديق، ولا أعرف صحة هذا عن الصديق. فالمقصود أن الذي عليه جمهور أهل العلم وهو الصواب أن التداوي مستحب بالأدوية الشرعية المباحة التي ليس فيها حرام كالتداوي بقراءة القرآن والرقية، التداوي بالكي، التداوي عند عدم دواء آخر الكي لا بأس به عند الحاجة، التداوي بأمور مباحة لا بأس بذلك، وقد رقى النبي ﷺ بعض أصحابه، وقد رقاه جبرائيل عليه الصلاة والسلام، فالتداوي لا بأس به، والنبي عليه السلام قال: عباد الله! تداووا، ولا تداووا بحرام فالتداوي أمر مشروع لا بأس به ولا ينافي التوكل، فالتوكل يشمل الأمرين: الاعتماد على الله والتفويض إليه مع تعاطي الأسباب، ولا يجوز للإنسان أن يقول: أنا أتوكل ولا آكل ولا أشرب ولا أتسبب ولا أبيع ولا أشتري ولا أتعاطى زراعة ولا صناعة ولا غيره.. لا هذا غلط، تعاطي الأسباب لا ينافي التوكل، بل هو من التوكل وهكذا التداوي من التوكل، ولهذا أرشد النبي ﷺ إلى التداوي، وسئل عن الرقى والأدوية قال: هي من قدر الله، وقال عمر  لما أتى الشام وبلغه حصول الوباء في الشام الطاعون انصرف بالناس ورجع بهم وقال: نفر من قدر الله إلى قدر الله ثم أبلغه عبد الرحمن بن عوف أن النبي ﷺ قال: إذا سمعتم به في بلد فلا تقدموا عليه فسر بذلك حيث وافق السنة.\nفالمقصود أن التداوي أمر مشروع على الصحيح وهو قول أكثر أهل العلم ومن تركه فلا حرج عليه، وإذا ظن نفعه واشتدت الحاجة إليه تأكد؛ لأن تركه يضر يتعب نفسه ويتعب أهله ويتعب خدامه، فالتداوي فيه مصالح لنفسه ولأهله، ولأن التداوي يعينه على أسباب الشفاء ويعينه على طاعة الله حتى يصلي في المسجد، حتى يقوم بأمور تنفع الناس وتنفعه، فإذا تعطل بسبب المرض تعطلت أشياء كثيرة، وإن كان يثاب عما كان يعمله في حال الصحة في حال المرض كما في الحديث الصحيح يقول ﷺ: إذا مرض العبد أو سافر كتب الله له ما كان يعمله وهو صحيح مقيم هذا من فضل الله جل وعلا، ولكن التداوي فيه مصالح كثيرة إذا كان بالوجه الشرعي والأدوية المباحة هذا هو الصواب، ومن قال: إنه مستوي الطرفين أو إن تركه أفضل فقوله مرجوح والحق أحق بالاتباع، والأدلة الشرعية مقدمة على كل أحد. وفق الله الجميع.\nالمقدم: بارك الله فيكم! سماحة الشيخ! هناك من يحتج في هذا الباب بحديث السبعين ألف الذين يدخلون الجنة بغير حساب.\nالشيخ: هؤلاء ما تركوا الأسباب، إنما تركوا شيئاً وهو الاسترقاء طلب الرقية من الناس تركها أفضل، تركوا الكي وتركه أفضل، لكن عند الحاجة لا بأس؛ النبي عليه السلام قال: الشفاء في ثلاث: كية نار أو شرطة محجم أو شربة عسل وما أحب أن أكتوي وفي لفظ آخر قال: وأنهى أمتي عن الكي وقد كوى ﷺ بعض أصحابه، فإذا دعت الحاجة للكي فلا بأس هو سبب مباح عند الحاجة إليه، والاسترقاء: طلب الرقية، أما إذا رقى من دون سؤال فهو من الأسباب لا بأس به ولا كراهة في ذلك، أما الطيرة في حديث السبعين: لا يسترقون ولا يكتوون ولا يتطيرون الطيرة محرمة وشرك أصغر وهو التشاؤم بالمرئيات أو المسموعات حتى يرجع عن حاجته هذا لا يجوز، وعلى ربهم يتوكلون هذا يشمل المتداوي وغيره، فإن التوكل لا يمنع تعاطي الأسباب، ألست تأكل؟! وألست تشرب؟! الأكل سبب للشبع ولقوام هذا البدن وسلامته وهكذا الشرب فهل يجوز للإنسان أن يقول: أنا لا آكل ولا أشرب وأتوكل على الله في حياتي وأبقى صحيحاً سليماً لا يأكل ولا يشرب هذا لا يقوله عاقل، هكذا يلبس الثياب الثقيلة في الشتاء للدفء لأنه يضره البرد، وهكذا يتعاطى الأسباب الأخرى من إغلاق الباب حذراً من السراق، من حمل السلاح عند الحاجة كل هذه أسباب مأمور بها لا تنافي التوكل، والنبي ﷺ هو سيد المتوكلين في أحد لبس السلاح لبس اللأمة، وفي بدر كذلك، وفي أحد ظاهر بين درعين، لبس درعان وعليه المغفر حين دخل مكة وعليه البيضة في أحد، كل هذه أسباب فعلها ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/8104/حكم-التداوي-من-الامراض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_269/26908.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":9954,"question":"وهذه رسالة من سائلة لا ترغب ذكر اسمها تقول: في بعض مستشفيات الولادة يتساهل كثير من الأطباء بالكشف على المرأة الحامل ولو كانت في بداية حملها، ويفرضون عليها كثرة المراجعة بمعدل كل أسبوعين مرة، وأحياناً كل أسبوع مرة طيلة مدة الحمل، وبمجرد ما تدخل على غرفة الطبيب يطلب منها الصعود إلى السرير وكشف عورتها مباشرةً، بحجة أن الطبيب لا بد في كل مرة أن يرى، ومن الأطباء من يتجرأ على تعديل وضع الجنين كما يزعم، وألاحظ في هذا تساهلاً، وإذا كانت بعض النساء ترفض ذلك فهم لا يجبرونها ويصرفون لها الدواء، ولا يحصل مكروهاً من عدم الرؤية، ولكن الذي لفت انتباهي هو: جرأة هؤلاء الأطباء وتساهل كثير من النساء في الموافقة من غير ما ضرورة فما حكم الشرع في ذلك، بارك الله فيكم؟","title":"حكم كشف المرأة الحامل عورتها للتأكد من وضع الجنين","answer":"الجواب: الذي يظهر لي من هذا الأمر أنه منكر، وأنه محرم وأنه ليس لها أن تتساهل في هذا الأمر إلا من علة ومرض خطير تخشى منه، أما مجرد الكشف على الحمل وما يحصل به من نفع ونمو ونحو ذلك هذا لا يسوغ له أن ينظر إلى عورتها، ولا لها أن تكشف على عورتها، بل ينبغي للنساء البعد عن هذا الأمر والتستر والبعد عن هذا الخلق الذي يفضي إلى كشف العورة للطبيب من دون ما ضرورة إلى ذلك، بل ينبغي للأطباء أيضاً أن يترفعوا عن هذا الأمر، وإذا كان هناك حاجة، ففي الإمكان أن ينظروا إلى شيء آخر، إذا أمكن النظر إلى شيء خارج العورة يدلهم على الحاجة إلى حبوب أو إلى إبر أو إلى حمية من شيء، أما الكشف على عوراتهن الداخلية فهذا خطر عظيم، ومنكر كبير وقد يفضي إلى فساد عريض، ولا حول ولا قوة إلا بالله.\nالمقصود: أن هذا منكر الكشف على العورة له شأن، فلا ينبغي إلا أن يكون لحاجة شديدة وخطر عظيم، وإذا كان ولا بد فليكن من طريق النساء، من طريق الطبيبات. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8123/حكم-كشف-المراة-الحامل-عورتها-للتاكد-من-وضع-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26502.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":9977,"question":"هذه رسالة من سائلة في العراق رمزت لاسمها بـ (أ. ح. ح) تقول في رسالتها: قد ولدت خمسة أطفال اثنان منهما ماتا وثلاثة أحياء، لكن في كل مرة تكون ولادتي صعبة، والله يعلم أنني أضطر إلى الذهاب إلى المستشفى، وفي ثلاث مرات يشرف علي أطباء رجال مع ممرضات وطبيبات، وأرفض الأطباء أن يولدونني، لكن لا أستطيع أن أفعل شيء لأنني في حالة من المرض والعجز، والأطباء هم الذين يشرفون على الولادة، وقررت أن أجري عملية لإزالة الرحم حتى لا يحدث لي حمل أبداً، فهل يجوز لي ذلك، وهل يجوز للمرأة أن يولدها طبيب، فأنا كلما وجدت طبيب في المستشفى عند زيارتي فإنني أخاف من الله عز وجل، والآن أنا حامل وخائفة من يوم الولادة أن يولدني رجل كما حصل في المرات الماضية؟ أفيدوني أفادكم الله.","title":"حكم ولادة المرأة بإشراف طبيب، واستئصال الرحم","answer":"الجواب: إذا كان الواقع كما ذكرت -أيها السائلة- فلا حرج عليك عند الضرورة، أما إن تيسر وجود الطبيبة المولدة فهذا هو الواجب، لكن إذا لم يتيسر ذلك ولم تجدي إلا طبيبًا وأنت مضطرة إلى ذلك فليس عليك حرج والحمد لله؛ لأن الطبيب ينظر عورة المرأة عند الحاجة والضرورة، لكن متى وجدت طبيبة صالحة لهذا الأمر لم يجز لك أن تذهبي إلى الرجل وعليك أن تذهبي للطبيبة، وليس لك قطع الرحم بل اصبري واستعيني بالله، ولعل الله يرزقك من الأولاد من ينفع الله بهم العباد، ويدعون لك في حياتك وبعد وفاتك.\nفالمقصود لا تقطعي الرحم واصبري ولا تعجلي في الأمور، وإذا وجدت الحاجة إلى الطبيب الرجل فليس عليك بأس من ذلك، ومتى استغنيت بالطبيبة فالحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8135/حكم-ولادة-المراة-باشراف-طبيب-واستىصال-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27410.mp3","categories":["الطب والتداوي"]},{"id":10101,"question":"تقول: أقوم أنا وزوجي بالذهاب إلى الأطباء أثناء الحمل لمعرفة نوع الجنين أهو ذكر أم أنثى، هل علينا إثم في ذلك؟","title":"حكم الذهاب للأطباء لمعرفة نوع الجنين","answer":"الجواب: حتى لو ذهبتما كلامهما ليس بمضبوط، كلام الأطباء ليس بمضبوط وليس هناك حاجة، والأولى عدم الذهاب إليهم وأن تسألوا الله أن يقدر الأصلح، والأولى عدم الذهاب إلى الأطباء وعدم سؤالهم، وأن يسأل الوالد والوالدة أن الله يقدر لهما الأصلح من الذكر والأنثى، ثم لو أخبر الأطباء فإخبارهم ليس بمضبوط، وقد يغلطون كثيراً في العلامات التي يعرفون بها الذكر من الأنثى بعد التخليق، قد يغلطون كثيراً. نعم\nالمقدم: إذاً ..\nالشيخ: ترك الذهاب إليهم أولى وأحسن.\nالمقدم: يحفظكم الله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8270/حكم-الذهاب-للاطباء-لمعرفة-نوع-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27702.mp3","categories":["الطب والتداوي"]},{"id":10116,"question":"ما رأي الدين الإسلامي في الأساليب والطرق السحرية التي تنتشر في بعض الكتب في المكتبات والتي تغري كل شاب بقراءتها والعمل بما فيها، وخصوصًا أن هناك حديثًا شريفًا يقول: تعلموا السحر ولا تعملوا به، فكيف يمكن تعلم السحر وعدم العمل به؟ أرجو الإجابة عن هذا الاستفسار؟ جزاكم الله خيرًا.","title":"حكم تعلم السحر والواجب تجاه كتب السحر","answer":"الجواب: الكتب التي تعلم السحر يجب إتلافها والقضاء عليها ولا يجوز تعلمها ولا العمل بما فيها، وهذا الحديث الذي ذكره السائل لا أصل له بل هو حديث غير صحيح تعلموا السحر ولا تعملوا به هذا باطل ما له أصل، هذا الحديث الذي ذكره السائل ليس له أصل، والذي عليه أهل العلم أنه لا يجوز تعلم السحر ولا العمل به، بل يجب الحذر من ذلك؛ لأن تعلمه وتعليمه كفر لأنه لا يتوصل إلا بعبادة الشياطين من دون الله والاستغاثة بالجن ونحو ذلك، والله ذكر عن الملكين في سورة البقرة قال سبحانه: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُر [البقرة:102]، فبين أن تعلمه كفر، وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُر [البقرة:102]، فدل ذلك على أن تعلم السحر من أمور الكفر، فالواجب على كل مسلم أن يحذر ذلك وألا يتعلم الكفر والسحر وألا يذهب إلى السحرة والكهنة والمنجمين، ولا يجوز له سؤالهم ولا تصديقهم؛ لقول النبي ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة رواه مسلم في الصحيح، وإن لم يصدقه من أتى عرافًا فسأله عن شيء ولم يقل: فصدقه، فدل ذلك على أن سؤاله لا يجوز، وتصديقه أكبر في الإثم، فلا يسأله ولا يصدقه، وقال أيضًا عليه الصلاة والسلام: من أتى كاهنًا أو عرافًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ، فلا يجوز إتيان الكهان وهم الذين يدعون علم الغيب، ولا العرافون الذين يدعون علم الغيب من مقدمات يدعونها وأشياء يدعونها، كل هذا باطل، فلا يجوز سؤالهم ولا يجوز تصديقهم، ولا يجوز شراء الكتب التي فيها علومهم، بل يجب إتلافها وإحراقها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8287/حكم-تعلم-السحر-والواجب-تجاه-كتب-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33405.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10203,"question":"هل صحيح أن من بخر منزله باللبان الشهري يذهب الشياطين من المنزل؟ وهل يوجد دليل على ذلك؟ لأن كثيرًا ممن حولنا يبخرون منازلهم عند الغروب اعتقادًا منهم أنه يذهب الشياطين وأنا لست مقتنعًا بعملهم هذا.","title":"حكم استخدام البخور لطرد الشياطين","answer":"الجواب: هذا شيء لا أصل له، وإنما يذهب الشياطين ذكر الله والتعوذ بكلمات الله التامات من شر ما خلق، هكذا أخبر النبي ﷺ، يقول ﷺ: من نزل منزلًا فقال: أعوذ بكلمات الله التامات من شر ما خلق لم يضره شيء حتى يرتحل من منزله ذلك، وقال: إذا دخل الإنسان منزله مساءً وقال: باسم الله، قال الشيطان: لا مبيت، وإذا سمى عند الأكل قال: لا مبيت ولا عشاء، فالتسمية بالله والتعوذ بكلمات الله التامات من شر ما خلق هذه من أسباب الحفظ من الشياطين، وهكذا قراءة القرآن كل ذلك من أسباب السلامة، فينبغي للمؤمن أن يفعل ما شرعه الله من التعوذ بكلمات الله التامات من شر ما خلق، ومن التسمية عند الدخول يقول: باسم الله عند دخول المنزل، والتسمية عند الأكل وعند الشرب، هكذا السنة، وإذا كرر: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات كان أولى وأفضل، كذلك يقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباح ومساء هذا من أسباب السلامة من كل شر، باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباح ومساء، وهكذا: أعوذ بكلمات الله التامات من شر ما خلق، إذا قالها لم يضره شيء حتى يرتحل من منزله ذلك، وإن كرر ثلاث مرات أولى وأكمل كما جاء في بعض الروايات عن النبي ﷺ.\nفالحاصل أن هذه التعوذات وهذه الأذكار هي التي يقي الله بها العبد من شر الشياطين، ومن كل ما يضره، أما البخور الذي ذكره السائل فلا أصل له.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8367/حكم-استخدام-البخور-لطرد-الشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33412.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10272,"question":"رسالة وصلت إلى البرنامج من العراق نينوى باعثها مستمع من هناك هو (م. ن. ي) يسأل في أحد أسئلته ويقول: هل عمليات التجميل حرام أم حلال مثل زرع الشعر وقصر الأنف؟","title":"حكم عمليات التجميل كزرع الشعر وغيره","answer":"الجواب: أما كون المرأة تعمل أعمال تنبت لها الشعر إذا كان ما فيها شعر، تتعاطى يعني أدوية تكون سببًا لنبات الشعر، هذا لا بأس، نبات الشعر مطلوب، أما كونها تعلق شعر أو تصل شعر أو تلبس الباروكة، هذا لا، هذا لا يجوز، أما إذا وجد دواء ينبت الشعر في الرأس فلا بأس في استعمال الدواء إذا كان دواء طيبًا ليس فيه مضرة ولا نجاسة، فلا بأس باستعماله.\nأما إذا كان دواء فيه مضرة أو فيه نجاسة أو مسكر، فإنه لا يستعمل.\nوأما التجميل الذي يتضمن تغيير خلق الله بأن يضع وشم في يديه أو في وجهه أو يعمل في وجهه شيء لا يجوز مثل قطع شيء منه، وهو ليس فيه خلل، ليس فيه مرض، أما إذا كانت فيه زائدة.. قرحة فيه شيء داواها وعالجها لا بأس.\nوهكذا تفليج الأسنان مثلما قال النبي ﷺ في الحديث الصحيح: لعن الله الواشمة والمستوشمة والواصلة والمستوصلة، والمتفلجات للحسن.\nالمقصود: أنه إذا غير خلق الله للتجمل فهذا لا يجوز أما إذا كان لعلة في يده مرض فعالجها ليسلم من المرض أو لتسلم أصابعه أو في أنفه مرض فعالجه ليسلم ويزول ما فيه من الجراحات أو السواد الذي نزل به، أو الألم الذي نزل به فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/8443/حكم-عمليات-التجميل-كزرع-الشعر-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33712.mp3","categories":["الطب والتداوي"]},{"id":10360,"question":"من المستمع حسين العميري من سوريا رسالة وضمنها سؤالين، في أحد أسئلته يقول: يوجد أشخاص يقال لهم: عرافون، ويدعون أنهم يعرفون علم الغيب، ما حكم الدين في ذلك، وهل يمكن تصديقهم؟","title":"حكم الذهاب إلى الكهنة والعرافين وتصديقهم","answer":"الجواب: العرافون والكهنة والسحرة لا يجوز تصديقهم ولا سؤالهم ولا إتيانهم، بل يجب الحذر منهم والإنكار عليهم، ويجب على ولاة الأمر من المسلمين تتبعهم وعقابهم بما يردعهم وأمثالهم، وإذا ادعوا علم الغيب يستتابون فإن تابوا وإلا قتلهم ولي الأمر. فإن دعوى علم الغيب كفر أكبر، وقد قال النبي ﷺ: من أتى عرافًأ فسأله عن شيء، لم تقبل له صلاة أربعين يوما، هذا سؤال مجرد سؤال من غير تصديق فكيف إذا صدقه؟ من أتى عرافًأ فسأله عن شيء لم تقبل له صلاة أربعين ليلة، هكذا جاء في صحيح مسلم أربعين ليلة.\nفإذا صدقه صار الإثم أعظم، وقال عليه الصلاة والسلام: من أتى عرافًأ أو كاهنًأ فصدقه بما يقول: فقد كفر بما أنزل على محمد ﷺ، فإذا صدقه في علم الغيب كفر مثله، فالذي يدعي علم الغيب أو يصدق من يدعي علم الغيب يكفر كفرًأ أكبر نعوذ بالله، يستتاب فإن تاب وإلا قتل، يجب أن يستتيبه ولي الأمر السلطان أو نائبه من القضاة فإن تاب وإلا قتل كافرًأ نسأل الله العافية. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8528/حكم-الذهاب-الى-الكهنة-والعرافين-وتصديقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33811.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10361,"question":"من المعلوم أن الجن والإنس من مخلوقات الله تعالى، وأمرهم بالعبادة في قوله تعالى: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، سؤالي: هل الجن يؤذون الإنس وكيف وبأي طريقة، وما أعراض الشخص المصاب، وكيف الشفاء إذا وقع؟","title":"أذية الجني للإنسي، وطرق الوقاية من ذلك","answer":"الجواب: الجن ثقل عظيم خلقهم الله لعبادته، وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، والصحيح: أنهم أولاد إبليس يقال لهم: الجن، فهو أبوهم كما أن آدم هو أبو الإنس، وهم فيهم الكافر وفيهم المسلم، وفيهم العاصي، مثل بني آدم ، فيهم الطيب والخبيث، والله كلفهم بعبادته وطاعته، وفرض عليهم فرائض، فالواجب عليهم أن يسمعوا ويطيعوا، وأن ينقادوا لأمر الله، وأن يعظموا حرماته.\nوهم أصناف وأشكال يأكلون ويشربون، وينكحون ويتناسلون، وهم أصناف وأشكال، وقد يؤذون بني آدم كما يؤذي بنو آدم بعضهم بعضا، قد يؤذي الجن الإنس في بعض الأحيان بالحجارة، أو بشب النار في بعض أمتعتهم، أو بالكلام المزعج أو بغير ذلك، وقد يؤذون أيضًأ بتلبس الجني بالإنسي، والغالب يكون هذا بأسباب من الإنس، إما بطرح شيء ثقيل ولم يسم، أو صب ماء حار ولم يسم، أو ما أشبه ذلك، مما قد يؤذيهم هم، فيتسلطون بسبب الأذى الذي حصل من الإنسي فيتلبس به الجني، ولكن متى قرأ عليه من آيات الله العزيز من آيات الله جل وعلا الكريمة وطولب بالخروج وخوف من الله سبحانه وتعالى، وقرأ عليه من لديه قوة في دين الله وإيمان قوي، فإنه يخرج إذا كان فيه دين إذا كان فيه خير يخرج ويتعظ ويتذكر، وقد لا يخرج إذا كان فاسقًأ أو كافرًأ مثل فسقة الإنس قد يظلمون ويتعدون ولا يبالون بالنصيحة لكفرهم أو فسقهم، فهم كالإنس فيهم الفاسق وفيهم الكافر وفيهم الظالم وفيهم الطيب وفيهم الخبيث، والله شرع لنا أن نتقي شرهم بالتعوذات، الإنسان مشروع له صباحًأ ومساءً أن يقول: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات، باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباح ومساء، كل هذا من أسباب السلامة من الجن وغيرهم.\nكذلك قراءة آية الكرسي بعد كل صلاة، وقراءتها عند النوم، من أسباب حفظ الله له من الشياطين، وهكذا قراءة قل هو الله أحد والمعوذتين بعد كل صلاة، وقراءتها ثلاث مرات بعد المغرب والفجر، كل هذا من أسباب السلامة من شياطين الإنس والجن.\nوالمؤمن ينبغي له أن يكون بعيدًأ عن أسباب الأذى للإنس والجن جميعًأ، ومن كان معتصمًأ بالله آخذًأ بالأسباب الشرعية وقاه الله شر الإنس والجن جميعًأ، ومن تساهل فقد يسلط عليه الإنس والجن بسبب تساهله أو عدوانه أو ظلمه، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/8531/اذية-الجني-للانسي-وطرق-الوقاية-من-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_338/33812.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10413,"question":"رسالة وصلت إلى البرنامج من الرياض، بعثت بها إحدى الأخوات المستمعات، رمزت إلى اسمها بالحروف (م. ج. م) تقول: أنا امرأة مصابة بالعين منذ ست سنوات ولم يفد معي أي علاج، والآن أخبرتني امرأة برجل لديه بعض العلاج وأنا أتعالج عنده دون علم لزوجي، فما رأي سماحتكم فيمن يستعمل القراءة وفيها استعمال فتش الكتاب، ويحتوي هذا الكتاب على جمع الجن وتفريقهم، إذًا من أين هذا المرض؟ -هكذا تقول في رسالتها سماحة الشيخ- هل هو منهم أو من غيرهم؟ وغير ذلك من علاجات ضدهم أي طردهم إن كان منهم المرض أو من غيرهم جزاكم الله خيرًا؟","title":"حكم الذهاب إلى الكهنة والعرافين","answer":"الجواب: هذا العلاج عند مثل هذا الرجل لا يجوز، وهذا يسمى عرافًا ويسمى كاهنًا، فلا يجوز المجيء إليه ولا سؤاله، ولا العلاج عنده، ولا يجوز لك أن تفعلي هذا حتى لو أذن لك الزوج، فكيف وهو لم يعلم، هذا لا يجوز لك أبدًا حتى لو قال لك الزوج لم تجز لك طاعته فيما حرم الله.\nوقد قال النبي ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة رواه مسلم في الصحيح، وقال عليه الصلاة والسلام: من أتى كاهنًا فصدقه بما يقول، فقد كفر بما أنزل على محمد عليه الصلاة والسلام.\nولما سئل عن العرافين والكهنة قال: لا تأتوهم.\nفالواجب عليك التوبة إلى الله وعدم المجيء إليه؛ لأنه بهذا العمل كاهن يستعين بالجن ويعبدهم من دون الله، فإنهم لا ينفعونه ولا يطيعونه إلا إذا تقرب إليهم بالذبح لهم أو النذر لهم أو دعائهم والاستغاثة بهم أو نحو ذلك، وهذا من الشرك الأكبر، فليس لك أن تعالجي عند هذا وأمثاله، وعليك التوبة إلى الله ، وسؤاله جل وعلا أن يشفيك مما أصابك ولا مانع من العلاج عن الأطباء المعروفين وعند الأخيار من الناس الذين يقرءون عليك، وينفثون عليك بالآيات القرآنية والدعوات النبوية، وإذا تيسر امرأة صالحة ذات علم تقرأ عليك نفعت إن شاء الله، فإذا لم تتيسر فرجل صالح يقرأ عليك وينفث عليك ولكن لا يخلو بك بل يقرأ عليك وعندك زوجك أو أمك أو أ ختك ونحو ذلك، فإن الخلوة لا تجوز، لا يجوز للرجل أن يخلو بالمرأة الأجنبية التي ليست محرمًا له، أو يقرأ لك في ماء وتشربينه أو تروشين به.\nكل هذا لا بأس به والحمد لله، وإذا عرفتم من يتهم بالعين تتصلون به وتطلبون منه أن يغسل لكم يغسل وجه ويديه ويتمضمض في الماء ثم تروشين به وينفع بإذن الله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8586/حكم-الذهاب-الى-الكهنة-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_341/34102.mp3","categories":["الطب والتداوي","مسائل متفرقة في العقيدة"]},{"id":10427,"question":"من جمهورية مصر العربية المستمع صلاح بن محمد بن آدم الدرديري ، بعث برسالة مطولة بعض الشيء يقول فيها: نظراً لأني طالب بكلية طب الأزهر، وبحكم المهنة فإني أقوم بحقن المسلمين لوجه الله تعالى في بلدتي راجياً المثوبة من الله تعالى، وهؤلاء الناس كثير منهم من النساء ممن لا يحل لي مسهن ومصافحتهن مع العلم بأنه لا توجد نساء ليقمن بهذه المهمة بدلاً مني، وتضطرني الظروف إلى ذلك، مما يضطرني أن أمس ما لا يحل لي، علماً بأني والحمد لله مؤمن بالله ولا يخطر ببالي إلا الخير، وأقرأ القرآن وأنا أقوم بهذه المهمة، وكذلك أشترط وجود رجل من أهلها معنا وإذا لم يوجد رجل أجلت القيام بها لحين وجود أحد من أهلها، وحريص على ذلك جداً إن شاء الله، فما حكم ذلك؟ وما الحكم إذا كنت صائماً سواءً كان الصيام فرضاً أو سنة، جزاكم الله خيراً؟","title":"حكم حقن الطبيب للنساء لعدم وجود طبيبة","answer":"الجواب: إذا كان الواقع مثلما ذكرت فأنت مأجور ولا حرج عليك بأن تضرب الإبرة والحقنة للمرأة والرجل، أنت مشكور مأجور، لكن تلاحظ أن لا تخلو بها مثلما ذكرت، يكون ذلك بحضرة رجل أو امرأة حتى لا تحصل الخلوة، لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فإذا ضربتها في المحل الذي تدعو الحاجة إلى ضربها فيه فلا بأس، لا تكشف إلا محل الحاجة فقط والباقي مستور، تستر نفسها وتحتجب إلا محل الحاجة، وأنت كذلك مهما أمكن تغض البصر عما قد يبدو إلا محل الحاجة، من غير خلوة، ولا حرج عليك في ذلك والحمد لله، ولو كنت صائماً لا حرج عليك. نعم.\nالمقدم: سواءً كان الصيام فرضاً أو نافلة؟\nالشيخ: سواءً كان الصيام فرضاً أو نافلة لا حرج عليه، لكن إذا كانت هي صائمة هي أو الرجل صائم إذا أجلت ضربهم في الليل يكون أحسن خروجاً من الخلاف، أما أنت لا شيء عليك، لكن إذا أجلت ضرب الإبرة للرجل أو المرأة للفطر إذا تيسر ذلك فهو أحوط. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8597/حكم-حقن-الطبيب-للنساء-لعدم-وجود-طبيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31705.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":10453,"question":"يقول: لدينا بعض الناس يعالجون المرضى بالآيات القرآنية وكي النار، وشرب العسل، وعندما ناقشناهم قال أحدهم: إن العلاج في ثلاث: آية من القرآن، أو جرعة من العسل، أو كية من النار، هل ورد هذا في شريعتنا، جزاكم الله خيراً؟","title":"مشروعية معالجة المرضى بالقرآن وكية النار وشربة العسل","answer":"الجواب: نعم. القرآن كله شفاء، يقول الله جل وعلا: وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ [الإسراء:82] وكان النبي ﷺ يرقي الناس بالقرآن، وهكذا الصحابة  وأرضاهم، يرقون الناس بالقرآن، والفاتحة أعظم سورة وأعظم رقية، فاتحة الكتاب الحمد، وهكذا آية الكرسي وهكذا قُلْ هُوَ اللَّهُ أَحَدٌ وهكذا المعوذتان: قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ و قُلْ أَعُوذُ بِرَبِّ النَّاسِ، وهكذا ما تيسر من الآيات، كلها شفاء، فالذي يرقي الناس بالقرآن قد أحسن بذلك، والغالب أنه ينجح إذا كان صادقاً طيباً مؤمناً، ينفع الله بقراءته ويجيب الله دعوته، أما كية النار وشربة العسل ففيها حديث صحيح، يقول النبي ﷺ: الشفاء في ثلاث: شربة عسل، أو شرطة محجم، أو كية نار، وما أحب أن أكتويرواه البخاري في صحيحه رحمه الله، وفي رواية: وأنا أنهى أمتي عن الكي فشربة العسل فيها خير كثير، والله بين في كتابه العظيم أن العسل فيه شفاء للناس، قال في النحل: يَخْرُجُ مِنْ بُطُونِهَا شَرَابٌ مُخْتَلِفٌ أَلْوَانُهُ فِيهِ شِفَاءٌ لِلنَّاسِ [النحل:69] وكية النار مجربة تنفع كما قال النبي ﷺ، لكن تكون آخر الطب، لقوله ﷺ: ما أحب أن أكتوي، وأنهى أمتي عن الكي فيكون الكي آخر الطب، إذا عجز الإنسان عن دواء آخر يكوي، وقد كوى النبي ﷺ بعض أصحابه عند الحاجة إلى الكي، وقد اكتوى بعض الصحابة كـخباب بن الأرت ، فالكي جائز عند الحاجة إليه، وإذا استغنى عنه الإنسان بأسباب أخرى فهو أحسن، وهكذا الحجامة أيضاً طيبة، علاج لكثرة الدم ... الدم إذا تيسر من يعرف الحجامة من المتبصرين فيها، فهي أيضاً من الدواء الطيب. نعم.\nالمقدم: جزاكم الله خيراً، هناك بعض الأمراض سماحة الشيخ لا تتفق مع العسل، توجيهكم في هذا لو تكرمتم؟\nالشيخ: كل دواء يعالج بما يناسبه، يقول النبي ﷺ في الحديث الصحيح: ما أنزل الله داء إلا أنزل له شفاء وفي اللفظ الآخر: علمه من علمه، وجهله من جهله ويقول ﷺ: لكل داء دواء، فإذا أصيب دواء الداء برئ بإذن الله فإذا أصيب دواءه المناسب له برئ بإذن الله، والأطباء يعرفون هذه المسائل، فيختارون لكل داء ما يناسبه، فإذا كان الداء لا يناسبه العسل ولا تناسبه الحجامة ولا الكي يلتمس له دواء آخر مما يناسبه، بمعرفة أهل الطب وأهل التجارب، والقرآن شفاء للجميع، القرآن ينفع الله به في الجميع، يقرأ على أخيه، ويسأل الله له الشفاء في كل أمراضه. نعم.\nالمقدم: جزاكم الله خيراً، إذاً العسل مقيد بقيود هي التي تفضلتم بذكرها؟\nالشيخ: نعم المرض الذي يناسبه. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8625/مشروعية-معالجة-المرضى-بالقران-وكية-النار-وشربة-العسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_319/31903.mp3","categories":["الطب والتداوي"]},{"id":10467,"question":"له سؤال طويل ملخصه: أن له أخت كانت مع رجل وطلقها بسبب والدته، ثم إنها بعد الطلاق أصيبت بحالة مرضية، أرغمه والده ووالدته على الذهاب بها إلى أحد الأشخاص يعتقد أنه مشعوذ، ومنذ ذلك الوقت وهو يفكر في أمره، ويرجو من سماحتكم توجيهه كيف يتصرف، وهل يكون قد وقع في الإثم، جزاكم الله خيراً؟الشيخ: أعد. الله المستعان.المقدم: يقول: إن له أخت كانت متزوجة من أحد الأشخاص، ثم إنه طلقها بسبب والدته، وبعد الطلاق أصيبت أخته بحالة مرضية، اضطر معها بسبب والده ووالدته إلى الذهاب بها عند أحد الأشخاص يعتقد أنه مشعوذ، وحينئذ أصيب بالقلق وأصبح يفكر هل قمت بعمل محرم كالشرك، ويرجو توجيهكم جزاكم الله خيراً؟","title":"حكم الذهاب إلى المشعوذين طاعة للوالدين","answer":"الجواب: نعم لا يجوز له ذلك، ليس له طاعة والديه فيما حرم الله، والذهاب بأخته إلى المشعوذ لا يجوز؛ لأن الرسول ﷺ نهى عن إتيان الكهان وعن سؤالهم، والمشعوذون هم العرافون والمنجمون والكهنة، فلا يجوز إتيانهم ولا سؤالهم، وإذا أمره بذلك والده لم يجز له طاعته؛ لأن الرسول عليه السلام قال: إنما الطاعة في المعروف وقال عليه الصلاة والسلام: لا طاعة لمخلوق في معصية الخالق.\nفيعتذر ويقول: يا والدي هذا ما يجوز، لكن نذهب بها إلى من يقرأ عليها من الطيبين امرأة صالحة تقرأ عليها، رجل صالح يقرأ عليها بدون خلوة، إلى الطبيب أما إلى المشعوذين من كهنة ومنجمين وسحرة ونحو ذلك هذا لا يجوز، فإنه لا يجوز إتيانهم ولا سؤالهم ولا العلاج عندهم بالكلية، بل يجب على ولي الأمر أن يمنعهم من ذلك وأن يؤدبهم، حتى يرتدعوا عن تعاطي العلاج. نعم.\nالمقدم: جزاكم الله خيراً، أما الحال وقد وقعت فبم توجهونه جزاكم الله ...؟\nالشيخ: ... التوبة إلى الله والندم، والعزم أن لا يعود في هذا الشيء. نعم.\nالمقدم: وحينئذٍ يكون إن شاء الله تعالى ..\nالشيخ: لأن التوبة تجب ما قبلها، إذا صدقت التوبة بالندم على الماضي والإقلاع من الذنب والعزم الصادق أن لا يعود فيه فإن الله يغفر له سبحانه وتعالى. نعم.\nالمقدم: جزاكم الله خيرا، هو قلقه من كونه قد وقع منه هذا الشيء.\nالشيخ: إن شاء الله يرجى له الخير في هذا، نعم الإنسان إذا قلق من أجل خوف الله والرغبة فيما عنده فهو على خير عظيم، الله المستعان.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8642/حكم-الذهاب-الى-المشعوذين-طاعة-للوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32008.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10485,"question":"أختنا تقول: يوجد امرأة تقوم بنثر الودع أمامها وتخبر أنه سوف يحدث كذا وكذا من الأمور الغيبية، ولكنها لا تقول: إنها تعلم الغيب، لكن تقول: إنما تفعله مجرد تسلية، وأن ما تقوله قد يحدث وقد لا يحدث ما حكم ذلك؟","title":"حكم نثر الودع والإخبار عن المغيبات","answer":"الجواب: لا يجوز لها هذا العمل، هذا من عمل أهل السحر والشعوذة، لا يجوز هذا بل يجب الإنكار عليها ومنعها من هذا العمل، وإخبارها أن هذا لا يجوز، وأن هذا يفضي إلى دعواها علم الغيب، والتلبيس على الناس، هذا لا يجوز، فالواجب على هذه المرأة أن تخاف الله وأن تراقب الله، وتحذر هذا العمل السيئ الذي أنكره النبي ﷺ وحذر منه، يقول ﷺ: من علق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، فالواجب الحذر من هذا العمل السيئ، وهو وسيلة إلى دعوى علم الغيب، ووسيلة إلى التلبيس على الناس، نسأل الله للجميع العافية والهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8660/حكم-نثر-الودع-والاخبار-عن-المغيبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28112.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":10512,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من اليمن الحديدة، باعثة الرسالة إحدى الأخوات تقول المرسلة أم عبدالله، أم عبدالله صدرت رسالتها بالعبارات التالية تقول: يسعدني أن أخبركم بأنني لم أعرف طريق الالتزام بأوامر الله ورسوله إلا بعد أن سمعت برنامجكم الذي اسمه: نور على الدرب، وهو حق اسم على مسمى، فجزى الله كل من شارك في هذا البرنامج خيرًا في الدنيا والآخرة، ولدي بعض الأسئلة أرجو من سماحتكم التفضل بالإجابة عليها، وجزاكم الله خيرًا سؤالها الأول تقول يا سماحة الشيخ-: هل يجوز للرجل أن يتبرع لزوجته بدمه إذا احتاجت إلى ذلك، جزاكم الله خيراً؟","title":"حكم تبرع الزوج بالدم لزوجته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلقد سرني كثيرًا انتفاعك أيها السائلة بهذا البرنامج والتزامك بأوامر الشرع بأسباب ذلك فالحمد لله، نسأل الله أن يزيدك من الخير، وأن يمنحك الفقه في الدين والثبات عليه، وأن يوفقك وجميع المسلمين والمسلمات لكل ما فيه رضاه وصلاح أمر عباده، ولا شك أن هذا البرنامج بحمد الله نافع ومفيد، فنسأل الله أن يوفق القائمين عليه لكل خير، وأن يمنحهم إصابة الحق إنه سميع قريب.\nأما سؤالك فلا بأس أن يساعدها بشيء من دمه، إذا احتاجت الزوجة إلى شيء من دمه فلا بأس؛ لأن هذه الأشياء لا دخل لها في التحريم إنما هذا خاص بالرضاعة، أما مسألة المساعدة بشيء من الدم فلا حرج في ذلك عند الضرورة.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8687/حكم-تبرع-الزوج-بالدم-لزوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28301.mp3","categories":["الطب والتداوي"]},{"id":10587,"question":"ما حكم عملية التجميل خاصةً إذا كان سبب العملية أمراً طارئاً وليس من أصل موجود؟","title":"حكم عملية التجميل","answer":"الجواب: لا حرج في تعاطي أسباب التجميل من دواء، كأن يحدث له في أنفه مرض أو شرم أو في شفته شرم، أو في ضرسه عيب فيصلحه، أو في عينه مرض، أو في جفنه أو في شيء شبه ذلك أو في أذنه لا بأس، ..... أن يعمل ما يزيل الأثر، أو سواد في وجهه فيعمل ما يزيله من دواء كل ذلك لا حرج فيه؛ للحديث: عباد الله تداووا ولا تداووا بحرام، وقوله ﷺ: ما أنزل الله داءً إلا أنزل له شفاء، علمه من علمه وجهله من جهله فالمقصود أنه إذا تداوى عن الشين الذي حصل فيه، فلا حرج في ذلك، ليس من تغيير خلق الله، هذا من الدواء من التداوي، فإذا وقع في يده أو رجله أو وجهه شيء يشينه، فإنه يتداوى في ذلك ولا حرج.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8756/حكم-عملية-التجميل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_324/32404.mp3","categories":["الطب والتداوي"]},{"id":10601,"question":"هل يجوز للمرأة أن تتعاطى علاجاً يمنع عنها العذر الشرعي إذا كانت تريد الحج؟","title":"حكم تعاطي المرأة علاجاً يمنع الحيض في الحج ورمضان","answer":"الجواب: لا أعلم مانعاً من ذلك، تتعاطى ما يمنع الحيض في حال الحج أو العمرة أو في شهر رمضان حتى تصوم مع الناس كل هذا لا حرج فيه إن شاء الله نعم، إذا كان لا يترتب عليه ضرر، إذا كانت الحبوب التي تتعاطاها لا يترتب عليها ضرر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8777/حكم-تعاطي-المراة-علاجا-يمنع-الحيض-في-الحج-ورمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32604.mp3","categories":["الحيض والنفاس","الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":10610,"question":"هل يجوز للمرأة أن تتعاطى علاجاً يمنع عنها العذر الشرعي إذا كانت تريد الحج؟","title":"حكم تعاطي المرأة علاجاً يمنع الحيض في الحج ورمضان","answer":"الجواب: لا أعلم مانعاً من ذلك، تتعاطى ما يمنع الحيض في حال الحج أو العمرة أو في شهر رمضان حتى تصوم مع الناس كل هذا لا حرج فيه إن شاء الله نعم، إذا كان لا يترتب عليه ضرر، إذا كانت الحبوب التي تتعاطاها لا يترتب عليها ضرر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8777/حكم-تعاطي-المراة-علاجا-يمنع-الحيض-في-الحج-ورمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32604.mp3","categories":["الحيض والنفاس","الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":10734,"question":"ما رأيكم سماحة الشيخ فيمن يستعمل الذهب والفضة للأسنان؟","title":"حكم استعمال الذهب والفضة في تركيب الأسنان","answer":"الجواب: الأسنان فيها تفصيل: إذا تيسر اتخاذ الأسنان من غير ذهب وفضة هذا أولى، أما إذا دعت الحاجة إلى ذلك فلا حرج في ذلك؛ لأنه ثبت عنه ﷺ أنه أذن لشخص قطع أنفه أن يجعل أنفاً من فضة، فلما أنتن عليه أمر أن يجعله من ذهب.\nفدل ذلك على أنه لا حرج في مثل هذا للضرورة، ولأنه ثبت عن بعض الصحابة رضي الله عنهم أنهم ربطوا أسنانهم بالذهب، فإذا دعت الحاجة إلى ذلك فلا حرج في ذلك، وإن تيسر معدن آخر يقوم مقام الذهب فهو أفضل وأولى وأحوط.\nوهذا للرجال خاصة أما النساء فأمرهم أوسع النساء أمرهن أوسع في ذلك؛ لأنه من الزينة، فإذا طلت بعض أسنانها بالذهب أو ركبت سناً سقط ركبت بدله سناً من ذهب فالأمر في حق المرأة أسهل وأيسر.\nأما الرجال فالواجب في حقهم التورع والبعد عن الذهب والفضة إلا عند الحاجة في مثل الأسنان أو مثل الأنف إذا قطع -لا حول ولا قوة إلا بالله- يجعل مكانه أنف من ذهب لا حرج في ذلك، فالأسنان الآن موجود من أشياء كثيرة تقوم مقام الذهب ولا حاجة إلى الذهب. نعم.\nالمقدم: بالنسبة للرجال؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8911/حكم-استعمال-الذهب-والفضة-في-تركيب-الاسنان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_345/34502.mp3","categories":["الطب والتداوي"]},{"id":10803,"question":"طبيب مسلم بعث برسالة يقول فيها: أنا طبيب في قسم الأطفال في أحد مستشفيات المملكة، تحدث عندنا حالات كثيرة يخرج فيها الأب ابنه من المستشفى على مسئوليته رافضُا النصيحة والعلاج الطبي، وإن نسبة من هؤلاء الأطفال تحدث لهم مضاعفات سيئة تؤثر على صحتهم طوال عمرهم، ومنهم من قد يتسبب هذا الخروج من المستشفى في وفاته، ومنهم من يموت في البيت نظرًا لجهل الآباء وعنادهم رغم بذل كل الأسباب لإقناعهم،  من المسؤول عن هذه الضحايا؟ وهل لإدارة المستشفى الحق في منع الأب ولو باستخدام الشرطة والاستعانة برجال الأمن؟ وهل من حق الأب الإصرار على أخذ ابنه حتى وهو يعرف أنه قد يموت دون علاج؟ أفتونا وما الحل؟ جزاكم الله خيرًا.","title":"حكم الأب الذي يرفض علاج ابنه المريض","answer":"الجواب:  العلاج مستحب، والطب مستحب، التطبب والعلاج مستحب، وليس بواجب، فإذا رأى والد الطفل عدم العلاج وهو رجل عاقل يفهم، ورأى أنه لا حاجة إلى العلاج فلا يجبر الوالد على العلاج لابنه أو بنته، أما إذا كان الوالد جاهلًا، ولا يفهم الأمور، فلا مانع من كون الدولة التي تحت إشرافها المستشفى تلزم بالعلاج لمصلحة الأطفال، أو مصلحة المسلمين مصلحة الرعية، إذا رأت الدولة ورأى المسؤولون عنها القائمون على المستشفى أن إخراجه خطر، وأنه في أشد الضرورة إلى العلاج، والأب لا يفهم هذه الأمور، ولا يعقل هذه الأمور فلا مانع من علاجه، ومنع الأب من إخراجه؛ لأن هذا من باب التعاون على البر والتقوى، ومن باب الإصلاح العام للمسلمين، ومن باب الأخذ على يد الإنسان الذي لا يفهم الأمور، ولا يعقلها كما ينبغي. أما إذا كان والدًا له فهمه وله عقله وله دينه، ولكن رأى أن هناك أسبابًا تقتضي إخراجه، فهو على مسؤوليته، وعلى اجتهاده، والله يغفر له إذا مات الطفل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8982/حكم-الاب-الذي-يرفض-علاج-ابنه-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35304.mp3","categories":["الطب والتداوي"]},{"id":10806,"question":"طبيب مسلم بعث برسالة يقول فيها: أنا طبيب في قسم الأطفال في أحد مستشفيات المملكة، تحدث عندنا حالات كثيرة يخرج فيها الأب ابنه من المستشفى على مسئوليته رافضُا النصيحة والعلاج الطبي، وإن نسبة من هؤلاء الأطفال تحدث لهم مضاعفات سيئة تؤثر على صحتهم طوال عمرهم، ومنهم من قد يتسبب هذا الخروج من المستشفى في وفاته، ومنهم من يموت في البيت نظرًا لجهل الآباء وعنادهم رغم بذل كل الأسباب لإقناعهم،  من المسؤول عن هذه الضحايا؟ وهل لإدارة المستشفى الحق في منع الأب ولو باستخدام الشرطة والاستعانة برجال الأمن؟ وهل من حق الأب الإصرار على أخذ ابنه حتى وهو يعرف أنه قد يموت دون علاج؟ أفتونا وما الحل؟ جزاكم الله خيرًا.","title":"حكم الأب الذي يرفض علاج ابنه المريض","answer":"الجواب:  العلاج مستحب، والطب مستحب، التطبب والعلاج مستحب، وليس بواجب، فإذا رأى والد الطفل عدم العلاج وهو رجل عاقل يفهم، ورأى أنه لا حاجة إلى العلاج فلا يجبر الوالد على العلاج لابنه أو بنته، أما إذا كان الوالد جاهلًا، ولا يفهم الأمور، فلا مانع من كون الدولة التي تحت إشرافها المستشفى تلزم بالعلاج لمصلحة الأطفال، أو مصلحة المسلمين مصلحة الرعية، إذا رأت الدولة ورأى المسؤولون عنها القائمون على المستشفى أن إخراجه خطر، وأنه في أشد الضرورة إلى العلاج، والأب لا يفهم هذه الأمور، ولا يعقل هذه الأمور فلا مانع من علاجه، ومنع الأب من إخراجه؛ لأن هذا من باب التعاون على البر والتقوى، ومن باب الإصلاح العام للمسلمين، ومن باب الأخذ على يد الإنسان الذي لا يفهم الأمور، ولا يعقلها كما ينبغي. أما إذا كان والدًا له فهمه وله عقله وله دينه، ولكن رأى أن هناك أسبابًا تقتضي إخراجه، فهو على مسؤوليته، وعلى اجتهاده، والله يغفر له إذا مات الطفل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8982/حكم-الاب-الذي-يرفض-علاج-ابنه-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_353/35304.mp3","categories":["الطب والتداوي"]},{"id":10840,"question":"يسأل سؤالًا آخر، ويقول: ما هو الحكم في الأدوية المحتوية على مذيبات كحولية، وهل يحرم تداولها؟","title":"حكم الدواء المحتوي على نسبة من الكحول","answer":"الجواب:  هذا فيه تفصيل: إذا عرفت أن هذه الأدوية فيها ما يسكر كثيره فاجتنبها، وأما إذا لم تعلم فالأصل الإباحة والحمد لله، الأصل في الأدوية الإباحة، والأصل في الطعام الإباحة، قال تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَاشْكُرُوا لِلَّهِ [البقرة:172] وقال تعالى: يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الأَرْضِ حَلالًا طَيِّبًا [البقرة:168]. فالأصل الإباحة إلا ما عرفت أنه محرم، فإذا كان الدواء بين لك الأطباء أن فيه ما يسكر كثيره، يعني: مواد مسكرة فاجتنبه، وأما إذا لم يتبين لك ذلك، أو نصحك الأطباء بأنه طيب فلا بأس والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9013/حكم-الدواء-المحتوي-على-نسبة-من-الكحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35506.mp3","categories":["الطب والتداوي"]},{"id":11046,"question":"يقول هذا السائل أبو أحمد: هل يجوز عرض المرأة في مدة حملها على دكتور نساء وتوليد؟ مع العلم بأن دور المرأة في هذا التخصص قليل جدًا، أفيدوني سماحة الشيخ.","title":"حكم عرض المرأة على طبيب نساء وتوليد","answer":"الجواب:  لا حرج في عرض أمرها على الطبيب المختص بالنساء إذا لم يتيسر طبيبة امرأة تقوم بالمطلوب؛ لأن هذه أشياء ضرورية. فالحاصل: أنه لا بأس أن تعرض نفسها على الطبيب المختص بالولادة عند الضرورة، أما إذا وجد طبيبة تقوم باللازم فلا.","link":"https://binbaz.org.sa/fatwas/9224/حكم-عرض-المراة-على-طبيب-نساء-وتوليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28802.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":11475,"question":"يقول: هناك بعض المشايخ -كما سماهم- يضربون أجسامهم بالسكاكين والخناجر والسيوف، وبعضهم يحاد الآخر أحيانًا متوسلًا كل واحد منهم بشيخه، فما حكم الشرع في هذا العمل؟ جزاكم الله خيرًا.","title":"حكم من يضربون أجسادهم بالخناجر والسيوف ويدعونها كرامة","answer":"الجواب:  هذا عمل الصوفية يدعون أنهم لا يضرون أنفسهم، وأن هذا من كراماتهم، وهو باطل، إنما هو تلبيس، ولا حقيقة لذلك، إنما هو تلبيس وتقليب على العيون كونه ضربه بالسيف، أو كسر رأسه، أو كسر رجله، كله تلبيس، لا حقيقة له، وهم بهذا كفار؛ لأنهم يسحرون الناس، كما قال الله عن سحرة فرعون: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66]، قال: سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَاءُوا بِسِحْرٍ عَظِيمٍ [الأعراف:116]، فهؤلاء المقدمون الذين يلبسون على الناس هم كفرة بذلك، سحرة مجرمون، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9659/حكم-من-يضربون-اجسادهم-بالخناجر-والسيوف-ويدعونها-كرامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38205.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":11486,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من اليمن الحديدة، باعثها مستمع رمز إلى اسمه بالحروف (ع. ص. ف) أخونا يقول: أعمل ممرضًا بالريف، وحصل أن مرض طفل، فعملت له إبرة؛ لتخفيف الحمى عنه، وبعد ثمان ساعات توفي الطفل، ومرة ثانية عملت إبرة لامرأة في الخمسين من عمرها، وبعد ساعة من ضرب الإبرة توفيت، وعندما أضرب الإبرة أنا واثق من عدم خطورتها، وأنا إنسان مستقيم -ولله الحمد- في كل أعمالي، وبعد أن حصلت لي هاتان المشكلتان؛ امتنعت عن هذا العمل، وتركت هذه المهنة إلا بين أفراد عائلتي للضرورة، فهل يلزمني شيء تجاه من توفوا؟ جزاكم الله خيرًا.","title":"حكم الطبيب إذا توفي مريض بعد إعطائه إبرة","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد. فإذا كنت حاذقًا عارفًا بضرب الإبر، على بصيرة فيما يحسن علاجه في ضرب الإبرة؛ فليس عليك شيء؛ لأنك مجتهد، والتوفيق بيد الله، أما إذا كنت لا تعلم الأمراض التي يحسن ضرب الإبرة فيها، وأنك تتخرص في ضرب الإبرة، ولا عندك بصيرة؛ فأنت ضامن؛ لأنه بأسبابك، أما إذا كنت حاذقاً في هذا الشيء، عارفًا به، على بصيرة في أن هذا المرض يعالج بالإبرة، وأن الإبرة هذه التي ضربتها هي مناسبة؛ فلا حرج عليك، والحمد لله. المقدم: الله المستعان، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9668/حكم-الطبيب-اذا-توفي-مريض-بعد-اعطاىه-ابرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38301.mp3","categories":["الطب والتداوي"]},{"id":11563,"question":"أيضًا تقول: اضطرت لكشف وجهها أمام الطبيب من أجل الكشف على الأسنان، ومن أجل أخذ صورة للمستشفى، فما هو توجيهكم؟","title":"حكم كشف المرأة وجهها للطبيب","answer":"الجواب:  إذا دعت الحاجة إلى ذلك؛ فلا بأس، كما تكشف له عن يدها، وعن رجلها، وعن بطنها على حسب الحاجة، إذا كان المرض في شيء من بدنها، ولم يتيسر لها امرأة، دعت الحاجة إلى الطبيب لعدم وجود طبيبة مختصة؛ فلا حرج، تكشف على قدر الحاجة، إذا كان في الأسنان تكشف له الفم فقط، بقية الوجه ما له لزوم، فإذا كانت العين تكشف له العين، وهكذا، في الرجل تكشف الرجل، في اليد اليد، وهكذا، على حسب الحاجة، يكشف الشيء الذي تدعو الحاجة إلى كشفه، والباقي يستر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9746/حكم-كشف-المراة-وجهها-للطبيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_297/29712.mp3","categories":["الطب والتداوي"]},{"id":11605,"question":"يسأل سؤال آخر فيقول: ما حكم الشرع في كتابة آيات من القرآن، أو اسم من أسماء الله الحسنى، ومحوها بالماء، وشربها بقصد الشفاء من مرض، أو جلب منفعة؟","title":"حكم كتابة آيات ومحوها في الماء وشربه بقصد الشفاء","answer":"الجواب:  لا حرج في ذلك قد ذكر ابن القيم -رحمه الله- ذلك عن جماعة من السلف، وهو من الأسباب، من العلاج، فإذا كتب آيات من القرآن بالزعفران، ثم غسلها وشربها؛ فلا حرج في ذلك -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9781/حكم-كتابة-ايات-ومحوها-في-الماء-وشربه-بقصد-الشفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38707.mp3","categories":["الطب والتداوي"]},{"id":11672,"question":"يسأل أخونا عن حكم التداوي بالأعشاب شرعًا؟","title":"حكم التداوي بالأعشاب","answer":"الجواب:  لا حرج في التداوي بالأعشاب، وغير الأعشاب، إذا كان مباحًا، يقول النبي ﷺ: عباد الله تداووا، ولا تداووا بحرام ويقول ﷺ: ما أنزل الله داء إلا أنزل له شفاء، علمه من علمه، وجهله من جهله فالأصل الإباحة، الأصل في التداوي الإباحة بالأعشاب، أو بغير الأعشاب مما عرف وجرب أنه ينفع، وليس بحرام في نفسه، سواء كان من أعشاب أو من غير الأعشاب، إذا عرف الأطباء أنه ينفع من هذا المرض يتداوى به، إلا أن يكون محرمًا كالخمر وكالخنزير ونحو ذلك. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9854/حكم-التداوي-بالاعشاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39004.mp3","categories":["الطب والتداوي"]},{"id":11686,"question":"أحد الإخوة المستمعين يسأل سماحتكم ويقول: المرسل عصام علي يسأل ويقول: صدرت بعض الكتب تحت عنوان: عالج نفسك بالقرآن، عالج نفسك بالطب النبوي، الصيدلية المحمدية، فما هو تعليقكم حول تلك الكتب، ومدى نفعها؟","title":"حكم التداوي بالقرآن والسنة وتأليف الكتب في ذلك","answer":"الجواب:  لم أطلع عليها، لكن المعنى صحيح، العلاج بالقرآن وبالسنة طيب، كونه يقرأ على نفسه الفاتحة ويكررها، يقرأ: قل هو الله أحد والمعوذتين، أو بعض الآيات الأخرى، ينفث على صدره، ينفث على محل المرض، كل هذا طيب، ولا بأس، هذا هو العلاج الصحيح، العلاج بالقرآن وبالدعوات الطيبة النبوية كله طيب، لكن إذا تداوى ... أيضًا بأشياء أخرى، يتداوى بأشياء مباحة، غير القرآن من أعشاب أو حبوب أو إبر أو غير ذلك مما ينفع؛ فلا بأس بذلك، الحمد لله، الله يقول -جل وعلا- في كتابه الكريم: كُلُوا وَاشْرَبُوا [البقرة:60] .... يعني: المباح، ويقول: كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَاشْكُرُوا لِلَّهِ [البقرة:172] . ويقول النبي ﷺ: ما أنزل الله داء إلا أنزل له شفاء، علمه من علمه، وجهله من جهله فالله أمرنا أن نأكل من الطيبات، وأن نتداوى، وعلينا أن نتقيد بالقيد الشرعي، بأن يكون الدواء ليس فيه تحريم، يعني: يتداوى بالمباحات، يقول ﷺ: عباد الله! تداووا، ولا تداووا بحرام وقال له رجل: يا رسول الله! إني أصنع الخمر للدواء، لا للشرب، قال: إنها ليست بدواء ولكنها داء فالخمر والخنزير والكلاب، وأشباه ذلك لا يتداوى به؛ لأنها محرمة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9865/حكم-التداوي-بالقران-والسنة-وتاليف-الكتب-في-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39013.mp3","categories":["الطب والتداوي"]},{"id":11727,"question":"هل الذهاب لبعض الأماكن التي بها مياه يقال: إنها تشفي الأمراض الجلدية بإذن الله، هل هذا جائز، أو لا؟","title":"حكم الذهاب إلى ينابيع مياه للاستشفاء بمائها","answer":"الجواب: إذا كان شيئًا مجربًا؛ لا حرج، إذا كان مجربًا، وأخذ منه مثلما يأخذ الناس من ماء زمزم؛ لأنه ماء مبارك، فإذا وجد ماء قد جرب لعلاج بعض الأمراض؛ فلا بأس أن يؤخذ منه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9910/حكم-الذهاب-الى-ينابيع-مياه-للاستشفاء-بماىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42108.mp3","categories":["الطب والتداوي"]},{"id":11826,"question":"مستمع بعث يسألكم -يحفظكم الله- عن السحر ويقول: سمعت أنه لا يجوز علاجه، ما هو توجيهكم؟ جزاكم الله خيرًا.","title":"أنواع السحر ووسائل علاجه","answer":"الجواب: السحر يعالج، السحر نوعان:  نوع خيالي، كما قال -جل وعلا-: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66] تقمير على العيون، تقمير لا حقيقة له. ونوع ثانٍ: حقيقة، قد يمرض الإنسان، قد يذهب عقله، قد يفرق بينه وبين زوجته، فيعالج بالقراءة وبالأدوية، يعالج بالقراءة وبالأدوية الشرعية المباحة. نعم.","link":"https://binbaz.org.sa/fatwas/10013/انواع-السحر-ووساىل-علاجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39516.mp3","categories":["الطب والتداوي"]},{"id":12330,"question":"إحدى الأخوات من الجزائر بعثت برسالة وضمنتها جمعًا من الأسئلة، في أحد أسئلتها تسأل عن حبوب منع الحمل، هل يجوز استعمالها، أو لا؟ جزاكم الله خيرًا.","title":"حبوب منع الحمل، هل يجوز استعمالها أم لا؟","answer":"الجواب:  هذه فيها تفصيل: إذا كان هناك مضرة، لأن معها طفل ترضعه، وتريد أن ترضعه، وألا تحمل عليه، ورضي الزوج بذلك؛ فلا بأس، أو كان يعني: يضرها الحبل، عندها مرض، ويضرها الحمل، فلا بأس أن تتعاطى الحبوب مؤقتًا حتى يزول المرض والأذى. أما تعاطيها لكراهة الأولاد، أو خوف المشقة من نفقتهم هذا لا يجوز. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10528/حبوب-منع-الحمل-هل-يجوز-استعمالها-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39814.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":12390,"question":"يسأل ما هي الحكمة والفوائد من الحجامة؟","title":"الحكمة من الحجامة وفوائدها","answer":"الجواب:  الحجامة فيها مصالح لمن اعتادها في تخفيف الدم عنه الفاسد ، فيها مصالح لمن اعتادها إذا حجمه من يعرف هذه الأمور إذا حجمه من يعرف هذه الأمور، يستفيد منها في الحال، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، هذه الفائدة، لكن هل هناك حكمة شيخ عبدالعزيز . الشيخ: نعم. المقدم: هل هناك حكمة؟  الشيخ: الحكمة الفائدة التي يجدها في إخراج الدم هذه الحكمة، كونه ينتفع بذلك، ويجد يعني: مصلحة، راحة له في إخراج هذا الدم، تكون هذه الحكمة، الحكمة الفائدة مثلما أن الحكمة في الأكل والشرب .. يستغني عن أسباب الخطر. فالمقصود: أنه إذا كان يجد من الحجامة فائدة ينتفع بها، ويرتاح لها، وتدفع عنه ضررًا، هذا كله حكمة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10591/الحكمة-من-الحجامة-وفواىدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40110.mp3","categories":["الطب والتداوي"]},{"id":12520,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (م. ش) يسأل سماحتكم، ويقول: أريد أن أعرف -يا سماحة الشيخ- هل هذا صواب، أم خطأ، فإن كان صوابًا؛ أعينوني بما يزيد عندي اليقين والتوكل على الله: إنني مريض بالفشل الكلوي، ويقول الأطباء: لو صبرت عن الغسيل الكلوي عشرة أيام تموت، وإني قد عزمت العلاج بالطب النبوي الذي يحتم علي أن أترك الغسيل، وأحتمي من الأكل متوكلًا على الله، وآخذًا بالأسباب التي هي أكل العسل الذي ذكره الله في القرآن، وشرب زمزم بنية العلاج، وقراءة القرآن بالرقية، فهل إذا مت أكون أهلكت نفسي، أم هو أجل قد انتهى؟ جزاكم الله خيرًا.","title":"حكم ترك التداوي بالطب الحديث والتداوي بالطب النبوي","answer":"الجواب:  كلها أسباب، عملك من باب الأسباب، وعمل الأطباء من باب الأسباب، فإن خضعت لقول الأطباء؛ لأنهم أعلم بالمرض؛ فلا بأس عليك، ولا حرج، والحمد لله، وإن أخذت بالأسباب الأخرى، ولم تقبل علاج الأطباء؛ فلا حرج؛ لأن العلاج ليس بلازم، ليس بواجب، العلاج مستحب، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10722/حكم-ترك-التداوي-بالطب-الحديث-والتداوي-بالطب-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40801.mp3","categories":["الطب والتداوي"]},{"id":12547,"question":"أحد الإخوة المستمعين من جمهورية مصر العربية، هو: محمد محمد علي فرغلي، بعث يقول: عندنا في مصر، في بعض القرى الريفية أناس يقومون بأعمال الطبل والمزمار، ويقولون: إننا نخرج الجن من الناس، ومن النساء، فما حكم ما يفعلون؟","title":"إخراج الجن بالطبل والمزمار","answer":"الجواب:  هذا من عمل بعض الصوفية، وهو منكر، غلط لا يجوز فعله، ولا يجوز تقليدهم، بل يجب الإنكار عليهم، يتعبدون بالطبل والمزامير والغناء، هذا منكر، وهذا من فعل بعض طوائف الصوفية، فأنت يا أخي! تنكر عليهم ذلك وإخوانك، تنكرون عليهم وتعلمونهم وترشدونهم أن هذا لا يجوز، وأن الواجب الاشتغال بما شرع الله من العبادة، من صلاة وقراءة وذكر، لا بالطبل والمزامير، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10752/اخراج-الجن-بالطبل-والمزمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45615.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":12586,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين من السودان، يسأل عددًا من الأسئلة من بينها سؤال طويل مكتوب بلهجته العامية، عن أولئك المشعوذين أصحاب البخور، وأصحاب الإخبار بالمغيبات، ويرجو من سماحة الشيخ التوجيه بخصوصهم، جزاكم الله خيرًا.","title":"واجب المسلم تجاه المشعوذين والمخرفين وأهل الطرق البدعية","answer":"الجواب:  يجب على المسلم أن يحذر هؤلاء المخرفين الذين ينسبون إلى التصوف والشعوذة، إما بدعوى علم الغيب، أو بدعاوى أخرى يدعونها أنهم بينهم وبين شيوخهم صلة تمكنهم من أن يفعلوا كذا وكذا، فيشوشوا على الناس، ويوهموهم أنهم لهم قدرة على شفاء المرضى، أو قضاء الحاجات بالطرق غير الشرعية. فهؤلاء يجب الحذر منهم؛ لأنهم مخرفون، ودعاة باطل، وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: من أتى عرافًا، فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا وقال: من أتى كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد ﷺ فهؤلاء الذين يدعون أمور الغيب، أو يدعون أن مشايخهم يرشدونهم إلى أشياء تتعلق بالغيب، وأن ما يقول مشايخهم صحيح، وأنهم معصومون، وأن أخبارهم لابد أن تقع وما أشبه، هذا مما يقع لبعض الصوفية، أو يعتقد أنه يأتيه الوحي من السماء، فيقول: حدثني قلبي عن ربي بكذا وكذا، فكل هذه خرافات، والذي يدعيها كافر، الذي يدعي أنه يعلم الغيب، أو أنه يأتيه الوحي من السماء بعد محمد ﷺ كل هذا كفر وضلال، وهكذا من يصدقهم في دعوى علم الغيب، من صدقهم؛ فهو مثلهم. وإذا جعل بخورًا، أو غيره من الأشياء التي يشوش بها، أو يلبس بها؛ فلا يلتفت إليه، العمدة على ما يقول، إذا كان يدعي علم الغيب، أو يدعي أنه يخدم الجن، وأن الجن هم الذين يخبرونه بالمغيبات، أو ما أشبه ذلك، هذا من الخرافيين، ومن المشعوذين؛ فيجب الحذر منهم، وعدم سؤالهم، وعدم تصديقهم، ومتى ظهر منه أنه يدعي علم الغيب، أو أنه يعبد الجن، ويخدمهم بالطاعات، والذبح لهم، والنذر لهم؛ صار بذلك مشركًا، إما بدعواه علم الغيب، وإما لكونه يعبد الجن، ويستغيث بهم، وينذر لهم، ونحو ذلك، وإذا زعم أنه يعرف الأشياء بالطرق الأخرى؛ فهو كذاب؟ لقصده التلبيس؛ لأنه لا يعلم المغيبات إلا الله . أما إذا كان يداوي المريض بالأدوية المعروفة الحسية، كما يفعل الأطباء المعروفون، يداوي بالكي، يداوي بأشياء يستعملها من مأكولات، أو مشروبات، أو مروخات جربت ونفعت، ولا يدعي علم الغيب، ولا يخدم الجن؛ هذا لا حرج عليه، هذا طب شعبي قد اعتاده الناس فيما بينهم، وقد يعتاد الناس أشياء يعرفونها فيما بينهم من أنواع من المأكولات، أو المشروبات، أو الدهونات، والمروخات، أو الكي؛ هذا لا بأس به إذا كان سليمًا ليس معه دعوى علم الغيب، وليس معه عبادته للجن، وقد كانت العرب وغالب الناس على هذا .... معهم فيما مضى، يعرفون عادات يفعلونها ويعالجون بها، ويتطببون بها، فقد تنفع، وقد لا تنفع، وليست من علم الغيب، ولا من خدمة الجن، بل هي أمور اعتادوها من أشربة، أو مأكولات، أو بخور يتبخرون به، وينفع الله به، أو ما أشبه ذلك من الأمور الواضحة والظاهرة التي ليس فيها تلبيس، ولا عبادة للجن، ولا دعوى علم الغيب، وهكذا الكي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10787/واجب-المسلم-تجاه-المشعوذين-والمخرفين-واهل-الطرق-البدعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_412/41204.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":12639,"question":"تقول في آخر سؤال نعرضه في هذه الحلقة: العين حق فهل هناك علاج لها مما ثبت عن النبي ﷺ؟","title":"وسائل علاج العين","answer":"الجواب:  نعم، العين حق هذا حديث صحيح، قال: العين حق، وإذا استغسلتم؛ فاغسلوا فإذا عرف العائن يطلب منه أن يغسل وجهه، وأطراف يديه، وداخلة إزاره، وأطراف قدميه، توضع في إناء، وتصب على المعين، ويبرأ -بإذن الله- ولو تمضمض، وغسل وجهه؛ كفى هذا مجرب، يصب على المعين، ويبرأ بإذن الله  هذا من العلاج النبوي. ومن العلاج أيضًا أن يقرأ عليه بعض الآيات مثل الفاتحة، وآية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ [الأخلاص: 1] والمعوذتين، هذه من أسباب الشفاء أيضًا. ومن أسباب ذلك أن يقرأ عليه: اللهم أذهب البأس ينفث عليه بعض الطيبين اللهم رب الناس، أذهب البأس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا بسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس، أو عين حاسد، الله يشفيك باسم الله أرقيك ثلاث مرات، كل هذا من أسباب الشفاء. المقصود: أن استغسال العائن حتى يصب على المعين من أسباب الشفاء، وكونه يقرأ عليه من بعض الإخوان الطيبين، يقرأ عليه، أو في ماء، ويصبه عليه؛ فهذا من أسباب الشفاء أيضًا -نسأل الله السلامة- نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10849/وساىل-علاج-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_415/41513.mp3","categories":["الطب والتداوي"]},{"id":12677,"question":"امرأة وضع لها الوشم وهي صغيرة، وهي الآن في الستين من عمرها، وهذا الوسم قليل، ولا يكاد يرى، فهل يجب عليها إزالته بإجراء عملية جراحية، أو كيف توجهونها جزاكم الله خيرًا؟","title":"حكم إزالة الوشم","answer":"الجواب:  لا يجب عليها ذلك، والإثم على من فعل إذا كان يفهم؛ لأن الوشم لا يجوز، وهي لم تفعله إنما فعل بها، فليس عليها شيء، والحمد لله، لو تيسر أن يزال ... لا يضر، ولا يشق فهو حسن، لكن إذا كان في إزالته جراحة، ومشقة؛ فلا حاجة إلى ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10887/حكم-ازالة-الوشم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41706.mp3","categories":["الطب والتداوي"]},{"id":12730,"question":"إحدى الأخوات المستمعات بعثت برسالة مطولة بعض الشيء وقعت في نهايتها بقولها أمة الرحمن، ملخص ما في هذه الرسالة السؤال عما يسمى بقراءة الكف، سواءً كان ذلك جدًا، أو هزلًا؟","title":"حكم قراءة الكف والفنجان وضرب الحصا","answer":"الجواب:  هذه باطلة ومن الكهانة، ولا يجوز الكف والفنجال وأشباه ذلك، وضرب الحصى والودع، كل هذا ضلال، ومن دعوى علم الغيب، فإذا زعم أنه يعلم الغيب بهذه الأمور؛ صار كافرًا كفرًا أكبر، نعوذ بالله؛ لأن الغيب لا يعلمه إلا الله، ولا يعلم بضرب الحصى، ولا بضرب الكف، ولا الفنجال، ولا بغير ذلك مما يتعاطاه المشعوذون. فعلم الغيب إلى الله  فمن زعم أنه بضرب الكف، أو ضرب الحصى، أو حساب بالأصابع، أو بأي شيء من الأشياء أنه يعلم الغيب، كل هذا من الكفر بالله -عز وجل- والله يقول سبحانه: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] ويقول -جل وعلا- في كتابه العظيم لنبيه ﷺ: قُلْ لا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلا أَعْلَمُ الْغَيْبَ [الأنعام:50] فمن ادعى بعمل الكف، أو عمل الحصى، أو الودع، أو غير هذا من الحسابات؛ فكله باطل، وكله كفر وضلال، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10943/حكم-قراءة-الكف-والفنجان-وضرب-الحصا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46102.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":12833,"question":"المستمع خليل إبراهيم عبدالرحمن الربيع من الأحساء العيون بعث يسأل عن الهدية التي تعطى للطبيب بعد قيامه بالعلاج، هل هي مشروعة، أو جائزة، أو محرمة؟","title":"حكم الإهداء للطبيب بعد قيامه بعلاج المريض","answer":"الجواب:  إذا كان بعد العلاج، وبعد النهاية لا نعلم فيها شيئًا، وتركها أولى، تركها أولى إذا كان يعمل للحكومة عمل الحكومة؛ لئلا يجره ذلك إلى تخصيصه بالاجتهاد دون بقية الناس، أما إذا كان طبيبًا لنفسه هذا بالأجرة التي تعاقد معه عليها، أو بما يشاء من الأجرة يعطيه إذا كان ما شرط له شيئًا، أما إذا كان في مستشفى الحكومة، مستوصف الحكومة؛ فلا يعطى شيء، لا يعطى، لكن لو أعطاه بعد الخلاص، وبعد النهاية.. من دون وعد، ومن دون شيء؛ لعله لا حرج، لكن تركه أحوط حتى ولو بعد ذلك؛ لأنه قد يتفق معه على ذلك من الداخل، قد يخص المريض بعناية، ويهمل المرضى الآخرين، فالذي أراه أنه لا يعطيه شيئًا، ولو بعد الفراغ. المقدم: وقد تتوق نفسه أيضًا .... الجواب: سدًا للباب، وسدًا للحيل، فلا ينبغي أن يعطيه شيئًا، بل يدعو له، يدعو له بالتوفيق، والإعانة بأن يقول: جزاك الله خيرًا، يسأل الله له الإعانة والتوفيق، هذا كلام طيب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11047/حكم-الاهداء-للطبيب-بعد-قيامه-بعلاج-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46321.mp3","categories":["الطب والتداوي"]},{"id":12922,"question":"تسأل وتقول: هل يجوز استعمال حبوب منع الحمل بدلًا من العزل لمدة عامين حتى يتم فطام الطفل الأول، مع العلم بأن الأم ليس بها أي مرض، ولكنها تريد إرضاع طفلها لمدة عامين؟","title":"هل يجوز استعمال حبوب منع الحمل بدلاً من العزل؟","answer":"الجواب:  لا ينبغي استعمال الحبوب؛ لأنها تضر، وتسبب امتناع الولد، أما العزل فهو أسهل؛ لأنه قد يسبق الماء، ويحصل الولد، أما استعمال الحبوب ونحوها؛ فلا ينبغي إلا من مضرة، كأن يكون عندها أولاد كثيرون تعجز عن خدمتهم، وتربيتهم؛ فلا بأس أن تستعمل الحبوب بعد استشارة الطبيب المختص، وتقريره عدم مضرتها، مع رضا زوجها بذلك. وأما إذا كان ما هناك مضرة، سليمة، ورحمها سليم، وليست مريضة، وليس عندها أولاد كثيرون يشق عليها تربيتهم؛ فلا ينبغي في هذه الحال، ولا يجوز استعمال الحبوب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11137/هل-يجوز-استعمال-حبوب-منع-الحمل-بدلا-من-العزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46907.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":12971,"question":"السائلة تقول: هل مانع الحمل، أو أي نوع من أنواع موانع الحمل الطبية لمدة سنة أو سنتين أو ثلاث سنوات حرام أو مكروه أو مباح، وضحوا لنا الأمر، جزاكم الله خيرًا؟","title":"حكم استعمال موانع الحمل","answer":"الجواب: على حسب الحاجة إلى ذلك، إذا دعت الحاجة إلى ذلك لمرض بالمرأة، أو لأسباب أخرى تبيح لها أخذ موانع الحمل لا بأس، مثل: كونها ترضع، وإذا حملت؛ حصل لها ضرر على الرضيع. فالمقصود: أنه إذا كان عذرًا شرعيًا، إما لكثرة الصبية، وتعبها أو لأن الصبي يتضرر بلبنها وهي حامل، أو لمرض بها هي يضرها الحمل بتقرير الأطباء الثقات؛ فلا حرج في ذلك. أما أن تتعاطى موانع الحمل للترفه؛ فلا يجوز، أو لخوف ألا يقوموا بالخدمة، أو النفقة؛ هذا سوء ظن لا يصلح. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11187/حكم-استعمال-موانع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50304.mp3","categories":["الطب والتداوي"]},{"id":13145,"question":"السائلة تقول: هل يجوز التداوي بالكي؟ وما هي الأحوال التي يجوز أن أستخدم فيها الكي، وجزاكم الله خيرًا؟","title":"حكم التداوي بالكي","answer":"الجواب:  نعم، يجوز التداوي بالكي؛ لقول النبي ﷺ: الشفاء في ثلاث ذكر منها: كية نار قال: وما أحب أن أكتوي  شرطة محجم، وشربة عسل، وكية نار قال: وما أحب أن أكتوي عليه الصلاة والسلام. لكن إذا دعت الحاجة إلى الكي؛ فلا بأس، قد كوى جماعة من الصحابة، فإذا احتيج إلى الكي؛ فلا حرج في ذلك، ولكن ترك الكي أولى، إذا تيسر دواء آخر، وعلاج آخر؛ لأنه نوع من التعذيب، فتركه أولى، إلا عند الحاجة، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11399/حكم-التداوي-بالكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51005.mp3","categories":["الطب والتداوي"]},{"id":13241,"question":"في آخر أسئلتها تقول السائلة أم عبدالرحمن: جدتي امرأة كبيرة في السن، وليس عندها ما تشتغل به وقت الفراغ، وتتسلى بما يسمى الخط، علمًا بأننا نصحناها كثيرًا بالابتعاد عن هذا الخط، لكنها تقول: بأنني آخذ ذلك من باب التسلية، ولا أصدق ما يأتي فيه، وتقول: بأن السيدة فاطمة -رضي الله عنها- كانت تتسلى به، فهل هذا صحيح، وماذا يجب عليها، ونلاحظ أن هناك أمور تقولها، فيحدث في الواقع، فما تفسير ذلك، مأجورين؟","title":"حكم العيافة والطرق والخط في الأرض","answer":"الجواب: هذا فيه تفصيل: إن كان الخط يعني عن اعتقاد أنه يقع شيء هذا هو الذي أنكره النبي ﷺ وسماه من السحر، قال: إن العيافة والطرق من الجبت.  فالمقصود: أن الطرق في الأرض، والخطوط في الأرض إذا كان لمقصد أنها تستعلم بها أمور الغيب، وأنها تريد أن هذا يفيدها شيئًا من الغيب، هذا باطل، وهذا من أعمال الجاهلية، وقال النبي ﷺ: إن العيافة والطرق والطيرة من الجبت فالواجب على المؤمن ترك ذلك. أما إذا كانت الخطوط من باب العبث... من باب التسلي، الخطوط تخطط في الأرض للتسلي والعبث، وليس عن عقيدة شيء؛ فهذا لا يضر، كونها تتسلى بخطوط، أو بأحجار تصفها، أو تلعب بها، أو شعابة، أو ما أشبه ذلك؛ هذا كله لا بأس إذا كان من باب التسلي والعبث، ليس عن اعتقاد شيء. أما أن تخط، أو تعمل بحصى، أو بودع، أو غيره، تعتقد أن هذا يترتب عليه شيء، هذا لا يجوز؛ لأن هذا من عمل السحرة، ومن عمل العرافين، ومن عمل الجاهلية، ولا يجوز، وسماه النبي ﷺ الطرق، قال: إن العيافة والطرق والطيرة من الجبت قال عمر: «الجبت السحر، والطاغوت الشيطان» وقال بعضهم: الجبت معناه: الشيء الذي لا خير فيه، الشر الذي لا خير فيه، فإذا فعلت ما يفعله جهال العرب، وهي العيافة، إذا مر بهم طائر، أو رأوا حيوانًا ما هو بزين، أو مقطوع الذنب؛ تشاءموا، ورجعوا عن حوائجهم، هذه الطيرة، هذه العيافة التي أنكرها الرسول ﷺ يقال: عاف يعيف إذا زجر الطير، وقال: خيرًا يا طير، أو رجع عن قصده، أو توقف عن قصده، هذا كله من العيافة .. من التشاؤم المنكر. وهكذا الطرق يعني: الخط في الأرض إذا كان لقصد يتعلم علوم الغيب، أو يظن أن هذا يعطيه شيئًا من علم الغيب، هذا من الجبت .. من الشيء الذي لا خير فيه، ومن أعمال السحر المنكرة، فلا يجوز، كما تقدم. نعم. وأما ما تقول عن فاطمة؛ فلا أعلم له أصلًا، ما تذكره عن فاطمة -رضي الله عنها- هذا لا أعلم له أصلًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11525/حكم-العيافة-والطرق-والخط-في-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51307.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13380,"question":"هذه رسالة وصلت من السائلة التي رمزت لاسمها بـ (أ. ب. أ) تقول في هذا  لدينا طفل يبلغ من العمر خمسة أشهر، ولديه أصبع زائد في اليد اليمنى، وقد قال لنا الدكتور: قصوه بعد سنة، هل قصه جائز، أم غير جائز؟ وضحوا لنا ذلك.","title":"حكم قطع الأصبع الزائدة","answer":"الجواب: الصواب أنه لا حرج في ذلك بواسطة الطبيب المختص؛ لأنه مثلة، وقد يؤذيه، ويشق عليه ويتعبه، فإذا أزاله؛ فلا بأس، الإصبع الزائدة في يده، أو رجله لا حرج في ذلك، هذا هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/11670/حكم-قطع-الاصبع-الزاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52505.mp3","categories":["الطب والتداوي"]},{"id":13618,"question":"السائلة التي رمزت لاسمها بـ (س. ل. ع) جمهورية مصر العربية، تذكر في هذه الرسالة بأنها فتاة تبلغ من العمر الثالثة والعشرين، وتعمل بالسحر والشعوذة، تقول: منذ صغري، وأريد أن أعرف من فضيلتكم بعض الإجابة عن هذا السؤال، وهي  هل الأموال حرام، والمأكل، والمشرب، والملبس حرام، مع العلم بأنني أصوم وأصلي، وأساعد أبي في عمله، فأبي يعمل في هذه العملية، وهي السحر والشعوذة، علمًا بأنني عندما أحاول أن أبتعد عنه يغضب مني هو ووالدتي، وجهونا في ضوء سؤالنا؟","title":"حكم السحر وتعلمه والذهاب إلى السحرة والعرافين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلا شك أن تعاطي السحر من المنكرات العظيمة، بل من الشرك، إذا عرف أنه يستخدم الجن، ويسألهم، ويدعي بذلك علم الغيب، وأنه يكون كذا، ويقع كذا، هذا كله من الشرك الأكبر، قال الله -جل وعلا- في كتابه العظيم: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102] فجعلهم كفارًا بتعليم الناس السحر، ثم قال: وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] يعني: حتى يقول الملكان: إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] دل على الكفر فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلاَّ بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنْ اشْتَرَاهُ [البقرة:102] يعني: اعتاضه مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ [البقرة:102] يعني: من حظ ولا نصيب وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ ۝ وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:102- 103] دل على أنه ضد التقوى، وضد الإيمان. فالواجب على كل حال: الحذر من هذا الأمر، وإذا كان في بلاد إسلامية تحكم بالشريعة؛ وجب أن يحكم فيه شرع الله -هذا الساحر- بأن يقتل؛ لأن السحرة قد يقتلون كما كتب عمر إلى عماله في الشام: أن يقتلوا كل ساحر وساحرة. حكم السحرة القتل لكفرهم؛ لأنهم يعبدون الجن، ويستعينوا بهم في إيذاء الناس، وفي ظلم الناس. أما الشعوذة تحتاج لتفصيل، لابد يعرف ما هي الشعوذة، فإن كان يدعي علم الغيب -المشعوذ- يدعي أنه كاهن، وأنه يسرق السمع، فهذا من جنس الساحر، يدعي علم الغيب؛ حكمه حكم الساحر، من ادعى علم الغيب؛ كفر. فأما إن كان شعوذة غير هذا، شعوذة بأن يكذب على الناس، يقول: ترى المحل الذي تطلبونه ... الفلاني، وترى سيارتكم في المحل الفلاني الضايع، بعيركم في المحل الفلاني، يكذب عليهم وإلا هو ما يدعي علم الغيب، ولكن يكذب.. يقول: إنه بعلامات، ثم آثار وإلا غيرها دلت على ذلك، هذا يسمى مشعوذ، ولا يجوز في مثل هذا سؤاله، ولا إتيانه إذا عرف منه الشعوذة والكذب، لا يسأل؛ لأنه داخل في العرافين، والنبي ﷺ يقول: من أتى عرافًا، فسأله عن شيء؛ لم تقبل له صلاة أربعين ليلة وفي اللفظ الآخر: من أتى عرافًا، أو كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام. فهذا العراف الذي يدعي أنه يعرف الأمور دعوته علم الغيب ... بكذا وكذا من الشعوذة، يصير في يوم كذا كذا، يخسف القمر في يوم كذا، وهو ما عنده خبر بالحساب، بل بزعمه علم الغيب، أو أنه يموت فلان في يوم كذا، أو يصاب بكذا. المقصود: دعوى علم الغيب، هذا العراف الذي يدعي هذا حكمه حكم السحرة، كافر -نسأل الله العافية- فعليه يستتاب، فإن تاب وإلا قتل، والقاعدة: كل من ادعى علم الغيب؛ يكون كافرًا؛ لأن الله يقول: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] ويقول سبحانه: وَعِنْدَهُ مَفَاتِحُ الْغَيْبِ لا يَعْلَمُهَا إِلَّا هُوَ [الأنعام:59]. فهو -جل وعلا- الذي يعلم الغيب، فمن ادعى علم الغيب؛ كفر، ومن تعاطى السحر؛ كفر؛ لأنه بتعاطيه السحر، يعبد الجن، ويستعين بهم في حاجاته من ضرر الناس، أو أخذ أموالهم، أو ما أشبه ذلك مما يفعله بسبب دعواه السحر. نعم. ومثل هذا التنجيم الذي يعبد النجوم، ويستعين بالنجوم، ويرى أنه يعلم الغيب بواسطة النجوم، يستتاب، فإن تاب وإلا قتل؛ لأن دعوى علم الغيب كفر، سواء من طريق النجوم، أو من طريق الجن، أو من غير ذلك، أو من أي طريق، نسأل الله العافية. المقدم: جزاكم الله خيرًا. سماحة الشيخ! هذا الموضوع حقيقة يحتاج إلى بسط في القول، ولكن هناك تساهل الناس في الذهاب إلى السحرة والمشعوذين، ما توجيهكم لهم يا سماحة الشيخ؟ الشيخ: مثل ما تقدم، الواجب الحذر، لا يجوز سؤالهم، ولا التوجه لهم، لا السحرة، ولا المنجمين، والعرافين، ولا المشعوذين، يجب الحذر من هؤلاء الذين يدعون علم الغيب، سواء بالسحر، أو بالشعوذة، أو بالكهانة، أو بالتنجيم، أو ما أشبه ذلك، يجب الحذر منهم، وألا يصدقوا، وألا يسألوا؛ لأن الرسول ﷺ حذر من ذلك، حذر من سؤالهم، ومن تصديقهم، فيجب الحذر من ذلك، والذي يدعي علم الغيب؛ يكون كافرًا، نسأل الله العافية، كالساحر سواء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11960/حكم-السحر-وتعلمه-والذهاب-الى-السحرة-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53401.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13625,"question":"السائلة التي رمزت لاسمها بـ (س. ل. ع) جمهورية مصر العربية، تذكر في هذه الرسالة بأنها فتاة تبلغ من العمر الثالثة والعشرين، وتعمل بالسحر والشعوذة، تقول: منذ صغري، وأريد أن أعرف من فضيلتكم بعض الإجابة عن هذا السؤال، وهي  هل الأموال حرام، والمأكل، والمشرب، والملبس حرام، مع العلم بأنني أصوم وأصلي، وأساعد أبي في عمله، فأبي يعمل في هذه العملية، وهي السحر والشعوذة، علمًا بأنني عندما أحاول أن أبتعد عنه يغضب مني هو ووالدتي، وجهونا في ضوء سؤالنا؟","title":"حكم السحر وتعلمه والذهاب إلى السحرة والعرافين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فلا شك أن تعاطي السحر من المنكرات العظيمة، بل من الشرك، إذا عرف أنه يستخدم الجن، ويسألهم، ويدعي بذلك علم الغيب، وأنه يكون كذا، ويقع كذا، هذا كله من الشرك الأكبر، قال الله -جل وعلا- في كتابه العظيم: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102] فجعلهم كفارًا بتعليم الناس السحر، ثم قال: وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] يعني: حتى يقول الملكان: إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102] دل على الكفر فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلاَّ بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنْ اشْتَرَاهُ [البقرة:102] يعني: اعتاضه مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ [البقرة:102] يعني: من حظ ولا نصيب وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ ۝ وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:102- 103] دل على أنه ضد التقوى، وضد الإيمان. فالواجب على كل حال: الحذر من هذا الأمر، وإذا كان في بلاد إسلامية تحكم بالشريعة؛ وجب أن يحكم فيه شرع الله -هذا الساحر- بأن يقتل؛ لأن السحرة قد يقتلون كما كتب عمر إلى عماله في الشام: أن يقتلوا كل ساحر وساحرة. حكم السحرة القتل لكفرهم؛ لأنهم يعبدون الجن، ويستعينوا بهم في إيذاء الناس، وفي ظلم الناس. أما الشعوذة تحتاج لتفصيل، لابد يعرف ما هي الشعوذة، فإن كان يدعي علم الغيب -المشعوذ- يدعي أنه كاهن، وأنه يسرق السمع، فهذا من جنس الساحر، يدعي علم الغيب؛ حكمه حكم الساحر، من ادعى علم الغيب؛ كفر. فأما إن كان شعوذة غير هذا، شعوذة بأن يكذب على الناس، يقول: ترى المحل الذي تطلبونه ... الفلاني، وترى سيارتكم في المحل الفلاني الضايع، بعيركم في المحل الفلاني، يكذب عليهم وإلا هو ما يدعي علم الغيب، ولكن يكذب.. يقول: إنه بعلامات، ثم آثار وإلا غيرها دلت على ذلك، هذا يسمى مشعوذ، ولا يجوز في مثل هذا سؤاله، ولا إتيانه إذا عرف منه الشعوذة والكذب، لا يسأل؛ لأنه داخل في العرافين، والنبي ﷺ يقول: من أتى عرافًا، فسأله عن شيء؛ لم تقبل له صلاة أربعين ليلة وفي اللفظ الآخر: من أتى عرافًا، أو كاهنًا، فصدقه بما يقول؛ فقد كفر بما أنزل على محمد عليه الصلاة والسلام. فهذا العراف الذي يدعي أنه يعرف الأمور دعوته علم الغيب ... بكذا وكذا من الشعوذة، يصير في يوم كذا كذا، يخسف القمر في يوم كذا، وهو ما عنده خبر بالحساب، بل بزعمه علم الغيب، أو أنه يموت فلان في يوم كذا، أو يصاب بكذا. المقصود: دعوى علم الغيب، هذا العراف الذي يدعي هذا حكمه حكم السحرة، كافر -نسأل الله العافية- فعليه يستتاب، فإن تاب وإلا قتل، والقاعدة: كل من ادعى علم الغيب؛ يكون كافرًا؛ لأن الله يقول: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] ويقول سبحانه: وَعِنْدَهُ مَفَاتِحُ الْغَيْبِ لا يَعْلَمُهَا إِلَّا هُوَ [الأنعام:59]. فهو -جل وعلا- الذي يعلم الغيب، فمن ادعى علم الغيب؛ كفر، ومن تعاطى السحر؛ كفر؛ لأنه بتعاطيه السحر، يعبد الجن، ويستعين بهم في حاجاته من ضرر الناس، أو أخذ أموالهم، أو ما أشبه ذلك مما يفعله بسبب دعواه السحر. نعم. ومثل هذا التنجيم الذي يعبد النجوم، ويستعين بالنجوم، ويرى أنه يعلم الغيب بواسطة النجوم، يستتاب، فإن تاب وإلا قتل؛ لأن دعوى علم الغيب كفر، سواء من طريق النجوم، أو من طريق الجن، أو من غير ذلك، أو من أي طريق، نسأل الله العافية. المقدم: جزاكم الله خيرًا. سماحة الشيخ! هذا الموضوع حقيقة يحتاج إلى بسط في القول، ولكن هناك تساهل الناس في الذهاب إلى السحرة والمشعوذين، ما توجيهكم لهم يا سماحة الشيخ؟ الشيخ: مثل ما تقدم، الواجب الحذر، لا يجوز سؤالهم، ولا التوجه لهم، لا السحرة، ولا المنجمين، والعرافين، ولا المشعوذين، يجب الحذر من هؤلاء الذين يدعون علم الغيب، سواء بالسحر، أو بالشعوذة، أو بالكهانة، أو بالتنجيم، أو ما أشبه ذلك، يجب الحذر منهم، وألا يصدقوا، وألا يسألوا؛ لأن الرسول ﷺ حذر من ذلك، حذر من سؤالهم، ومن تصديقهم، فيجب الحذر من ذلك، والذي يدعي علم الغيب؛ يكون كافرًا، نسأل الله العافية، كالساحر سواء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11960/حكم-السحر-وتعلمه-والذهاب-الى-السحرة-والعرافين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53401.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13698,"question":"يقول هذا السائل طه عبدالحميد من السودان: يزعم أحد الدجالين بأنه يستطيع أن يتعرف على السارق بعد أن يسرق غيبًا، وذلك بأمور لا يعلمها كثير من الناس، منها: بأنه يأمر بإحضار صحن ماء، وطفل دون سن البلوغ، ويكون قد رضع من ثديي أمه حولين كاملين، ولم يخيفه كلب، ثم يقوم بقراءة شيء من القرآن، وبعض الكلمات التي لا تفهم، ثم يسأل الطفل، هل رأيت شيئًا في الماء الذي في الصحن، فيصف الطفل السارق بالتفاصيل، وأين أخفى المسروقات، فما حكم الشرع في مثل هذا؟ وهل تجوز الصلاة خلفه؟ وهل يجوز لنا أن نقوم بوصله في السراء والضراء، علمًا بأننا نصحناه، ولكنه لا يقبل النصيحة، ويقول: بأنه على حق، أفتونا مأجورين؟","title":"حكم الصلاة خلف العراف والتعامل معه","answer":"الجواب: هذا من باب التلبيس والخداع والكذب، وإنما هو يستخدم الجن، ويسأل الجن، فقد يخبرونه، وقد يعرفون السارق فيخبرونه، مثل هذا لا يصلى خلفه، بل يجب أن يرفع أمره للمحكمة، أو للهيئة، أو للإمارة حتى يردع عن هذا العمل؛ لأن هذا من باب دعوى علم الغيب، وذكر الطفل والصبي، وكذا، والماء، كل هذه من باب التلبيس والخداع. وإنما الحقيقة أنه يسأل الجن، ويستعين بالجن، ويخبر عنهم، وقد يغلطون، وقد يصدقون. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12069/حكم-الصلاة-خلف-العراف-والتعامل-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53502.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13700,"question":"يقول هذا السائل طه عبدالحميد من السودان: يزعم أحد الدجالين بأنه يستطيع أن يتعرف على السارق بعد أن يسرق غيبًا، وذلك بأمور لا يعلمها كثير من الناس، منها: بأنه يأمر بإحضار صحن ماء، وطفل دون سن البلوغ، ويكون قد رضع من ثديي أمه حولين كاملين، ولم يخيفه كلب، ثم يقوم بقراءة شيء من القرآن، وبعض الكلمات التي لا تفهم، ثم يسأل الطفل، هل رأيت شيئًا في الماء الذي في الصحن، فيصف الطفل السارق بالتفاصيل، وأين أخفى المسروقات، فما حكم الشرع في مثل هذا؟ وهل تجوز الصلاة خلفه؟ وهل يجوز لنا أن نقوم بوصله في السراء والضراء، علمًا بأننا نصحناه، ولكنه لا يقبل النصيحة، ويقول: بأنه على حق، أفتونا مأجورين؟","title":"حكم الصلاة خلف العراف والتعامل معه","answer":"الجواب: هذا من باب التلبيس والخداع والكذب، وإنما هو يستخدم الجن، ويسأل الجن، فقد يخبرونه، وقد يعرفون السارق فيخبرونه، مثل هذا لا يصلى خلفه، بل يجب أن يرفع أمره للمحكمة، أو للهيئة، أو للإمارة حتى يردع عن هذا العمل؛ لأن هذا من باب دعوى علم الغيب، وذكر الطفل والصبي، وكذا، والماء، كل هذه من باب التلبيس والخداع. وإنما الحقيقة أنه يسأل الجن، ويستعين بالجن، ويخبر عنهم، وقد يغلطون، وقد يصدقون. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12069/حكم-الصلاة-خلف-العراف-والتعامل-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53502.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":13920,"question":"السائلة (س. م. م) من جمهورية مصر العربية تقول في سؤالها: ما حكم استعمال وسائل تنظيم الأسرة التي نسمع عنها في وقتنا الحاضر؟ وهل في هذا مخالفة لما جاء في القرآن والسنة؟","title":"حكم استعمال وسائل تنظيم الأسرة","answer":"الجواب: هذا سؤال مجمل، تنظيم الأسرة هذا سؤال مجمل لابد من التفصيل، فإن كان المراد تنظيم الأسرة يعني تنظيم الحمل فهذا فيه تفصيل: إذا كان عليها مشقة كونها ترضع وتخشى الحمل ويضر الولد حملها فلا بأس بتعاطي ما يمنع الحمل حتى تكمل الرضاعة، أو كان عليها مضرة.. تقرير الأطباء أن عليها مضرة من الحمل المتوالي فلا مانع من تعاطي ما يمنع الحمل المتوالي إن كان تحمل بعد كل ثلاث سنين أو أربع سنين إذا كان عليها مضرة في الحمل المتوالي.\nالمقصود تنظيم الأسرة إذا كان لأمر شرعي فلا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12313/حكم-استعمال-وساىل-تنظيم-الاسرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54405.mp3","categories":["الطب والتداوي","قضايا معاصرة"]},{"id":13999,"question":"المقدم مساعد سالم جار النبي المالكي يقول في رسالته: هل يجوز نقل الدم من الزوج إلى زوجته، وهل ينقل من شخص ثاني إلى ثاني ولو اختلفت دياناتهم مثل: من مسلم إلى شيوعي أو من شيوعي إلى مسلم ؟","title":"حكم نقل الدم بين الزوجين ومن الكافر إلى المسلم","answer":"الجواب: لا أرى حرجًا في نقل الدم إذا دعت الحاجة إليه، إذا قرر الأطباء الحاجة إليه وناسب دم هذا دم هذا فلا بأس، سواء كان من زوجة إلى زوجها أو من زوج إلى زوجته أو من كافر إلى مسلم أو من مسلم إلى كافر لا بأس بهذا، إلا أن يكون الكافر حربيًا تدعو الشرعية إلى قتله فلا ينقل له شيء، أما إذا كان الكافر ذميًا أو معاهدًا أو مستأمنًا فلا حرج.\nفالحاصل: أن نقل الدم لا يؤثر ما هو مثل الرضاع، الرضاع إذا تمت شروطه أثر وحصل به التحريم، أما نقل الدم فلا ليس مثل الرضاع، فلا بأس أن ينقل الدم من الزوج إلى الزوجة ومن الزوجة إلى الزوج. نعم.","link":"https://binbaz.org.sa/fatwas/12423/حكم-نقل-الدم-بين-الزوجين-ومن-الكافر-الى-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_540/54005.mp3","categories":["الطب والتداوي","قضايا المرأة","قضايا معاصرة"]},{"id":14056,"question":"رسالة وصلت إلى البرنامج من صنعاء باعثها مستمع من هناك يقول: (ج.ع. ي) وزميل له هو (ن. د. ي. ط) يقولون في هذه الرسالة: إننا في زمن كثرت فيه الخرافات والشعوذة، وإن هناك رجلًا يدعي أنه يعلم المخفيات مثل السرقة وغير ذلك، والأمر أنه في حالة عجز المواطنين عن معرفة أي شيء حصل في البلاد فإن العمدة يرسل بعض الأشخاص إلى هذا الرجل ليعرفوا منه ما حدث، وقد يكذب أو يصدق ولكن المؤسف أنهم يحكمون على الناس بما قال هذا الدجال ولا يحق لأحد أن يتكلم أو يدافع عن نفسه بعد هذا، نرجو من سماحة الشيخ التوجيه؟ جزاكم الله خيرًا.","title":"حكم الأخذ بأقوال الكهنة والمشعوذين","answer":"الجواب: هذا غلط عظيم، لا يجوز الاعتماد على الكهنة والمشعوذين والعرافين، بل يجب أن يقضى عليهم، يجب على الدولة إذا كانت مسلمة تخاف الله يجب عليها أن تقضي عليهم وأن تلتمسهم وأن تؤدبهم وتعاقبهم حتى يتركوا هذا العمل، وقد صح عن رسول الله عليه الصلاة والسلام: أنه سئل عن الكهان؟ فقال: لا تأتوهم فقيل له: إنهم قد يصدقون في بعض الشيء؟ فقال: تلك الكلمة يسمعها الجني يسمعها من الملائكة عند استراقه السمع فيقرها في أذن وليه من الإنس، يعني يقرها في أذن الكاهن أو الساحر فيصدق أولئك الكهنة بتلك الكلمة التي سمعت من السماء في كذبهم الكثير، ويقولون: قد قال كذا وكذا وصدق، فيصدقونه بما يكذب فيه من مئات الكذبات التي لا أساس لها.  وقد قال عليه الصلاة والسلام في الحديث الصحيح: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، وقال عليه الصلاة والسلام: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا، لم تقبل له صلاة أربعين ليلة كما في مسلم في الصحيح، ........ رحمه الله، وقال عليه الصلاة والسلام: ليس منا من سحر أو سحر له أو تكهن أو تكهن له أو تطير أو تطير له.  فهؤلاء لا يصدقون ولا يعتمد عليهم، وإذا صمموا وأقروا بأنهم يعلمون الغيب أو يدعون علم الغيب صاروا كفارًا بذلك، فمن ادعى أنه يعلم المغيبات يكون كافرًا كما قال الله : قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ[النمل:65]، فمن زعم أنه يعلم الغيب فهو مكذب لله ومشارك لله فيما اختص به ، وهذا كفر أكبر وضلال بعيد، علم الغيب لا يعلمه إلا الله، حتى الأنبياء لا يعلمونه، حتى محمد عليه الصلاة والسلام -وهو أفضل الخلق- لا يعلم الغيب إلا ما علمه الله إياه، كما قال : قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ[الأعراف:188]، وقال جل وعلا: قُلْ لا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلا أَعْلَمُ الْغَيْبَ وَلا أَقُولُ لَكُمْ إِنِّي مَلَكٌ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَى إِلَيَّ[الأنعام:50] الآية. فمن زعم أنه يعلم الغيب من الكهنة ونحوهم وهو كافر ضال ومن صدقه بذلك فهو مثله يكون كافرًا مثله، نسأل الله العافية.\nالمقصود أن هؤلاء المشعوذين من الكهنة يجب أن يحاربوا وأن يقضى عليهم من جهة الدولة وأن يؤدبوا ويعاقبوا حتى يتركوا هذا الأمر، فإن أصروا على هذا الباطل وجب قتلهم؛ لأنهم من المفسدين في الأرض. نعم.\nالمقدم: جزاكم الله خيرًا، الواقع تكثر شكاية كثير من الناس من أمثال هؤلاء يا سماحة الشيخ، لعل لسماحتكم توجيه فيما يخص التعامل معهم ومقاطعتهم إذا لزم الأمر؟\nالشيخ: نعم، مثلما تقدم يجب أن يقاطعوا ويجب على من عرفهم أن يعرف عنهم ولاة الأمور من الهيئة والمحكمة والإمارة ولاسيما في هذه المملكة التي هي بحمد الله تحكم بالشرع.\nفالواجب على من عرف أحدًا من هؤلاء الكهنة والمنجمين والرمالين والمشعوذين أن يرفع أمره إلى الإمارة في بلده أو المحكمة أو الهيئة أو إلى الجميع حتى تبرأ ذمته وحتى يحصل التعاون، ولا يجوز التستر عليه ولا إخفاء أمره، بل يجب إعلان أمره وفضيحته حتى لا يضر الناس.\nوهكذا في اليمن، في اليمن يجب على من عرف ذلك أن يرفعه إلى ولاة الأمر حتى يمنعوه من التعدي على الناس والكذب عليهم، بل يجب على ولاة الأمور في اليمن وفي غيرها أن يقضوا على هؤلاء المشعوذين والرمالين والكهنة وأن يمنعوهم من تعاطي هذه الأعمال القبيحة المنكرة التي فيها.. تضل الناس وخداعهم وأخذ أموالهم بالباطل والكذب عليهم.\nالمقصود: أن هذا واجب على المسلمين أن يتعاونوا فيه، في الدول الإسلامية وفي غير الدول الإسلامية مع المسلمين في الأقليات الإسلامية إذا وجد بينهم من يفعل هذا يتعاونون في نصيحته وفي بيان باطله حتى يرجع إلى الحق والصواب، أما في الدول الإسلامية فالواجب عليهم القضاء عليه، كما يجب على الدول الإسلامية القضاء على كل ما حرم الله من المنكرات الظاهرة وأعظمها الشرك بالله  من دعوة أصحاب القبور والاستغاثة بالأموات والنذر لهم والذبح لهم كل ذلك يجب القضاء عليه؛ لأنه منكر عظيم وشرك وخيم، وهكذا إظهار البدع المنكرة المخالفة لشرع الله يجب القضاء عليها، وهكذا وجود الكهنة والمنجمين والمشعوذين يجب القضاء عليهم وإعلان أن الدولة ضدهم حتى يفضحهم الناس وحتى يرفعوا بأمرهم إلى ولاة الأمور للقضاء عليهم وحماية المجتمع الإسلامي من شرهم ومكائدهم. نعم.\nالمقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/12495/حكم-الاخذ-باقوال-الكهنة-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_613/61305.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14118,"question":"كما توقعنا في الحلقة الماضية شيخ عبد العزيز أن هناك عددًا من السادة المستمعين سيسألون عن هؤلاء الكهان والدجالين، هذا هو المستمع إدريس محمد فضل المولى يسأل أيضًا عن هذا الموضوع، ويبدو أن القضية موجودة حتى في السودان، فهم يتعلقون بهم ولاسيما أولئك الذين ابتلي بعض أقاربهم بالمرضى أو بضياع شيء من الأموال وما أشبه ذلك، ويرجو التوجيه جزاكم الله خيرًا، وسؤال أخينا حول هذا الموضوع استغرق ما يقرب من صفحة؟","title":"حكم سؤال الكهنة والمشعوذين","answer":"الجواب: سبق التنبيه على هذا وأنه لا يجوز لأي مسلم أن يسأل الكهنة والمنجمين والعرافين والمشعوذين الذين يدعون علم الغيب أو يعرفون بأشياء تدل على ذلك، فمن كان يتهم بذلك أو يعرف بذلك لا يسأل ولا يصدق، بل يلتمس أهل الخير وأهل العلم والإيمان حتى يقرأ على المريض، ينفث على المريض، أو الطبيب المعروف بالحذق والفهم، يسأل عن المرض، الطبيب المعروف، أما الكهان والمنجمون والرمالون والمشعوذون والعرافون كل من يدعي شيئًا من أمور الغيب ويزعم أنه يعرف هذا بكذا وكذا منهم، هذا كله منكر يجب الحذر منهم. وقد قال عليه الصلاة والسلام في الحديث الصحيح: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا، «أربعين ليلة» في ..... وقال ﷺ: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، فالأمر عظيم، وقال النبي ﷺ لما سئل عن الكهان قال: لا تأتوهم، وقال: ليسوا بشيء. فالكاهن والعراف والرمال ونحوهم يدعون علم الغيب بأمور وأشياء يشبهون بها على الناس ويخدعون بها الناس من ضرب بالحصى أو سؤال عن اسم أمه واسم فلانة وفلانة، أو غير ذلك من الأسئلة التي يزعمون بها أنهم يعلمون الغائب أو يعلمون كذا وكذا من أسباب مرضه غير الطريقة المعروفة من سؤاله عن صفة المرض وأسباب المرض الذي أصابه حتى يهتدوا إلى علاج، الذين يدعون أشياء خارجية عن ذلك من جهة النجوم أو من جهة اسم أمه أو من جهة الأشياء التي لا تعلق بها بالمرض هذا كله من أمارات أنهم مشعوذون وأنهم كهنة يجب الحذر منهم، وإنما يؤتى المعروف بالخير والاستقامة والدين، وأن يتعاطى طبًا واضحًا ليس فيه شبهة وليس فيه ما يوهم دعوى علم الغيب أو خدمة الجن ودعاء الجن وعبادة الجن، نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12567/حكم-سوال-الكهنة-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61505.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14191,"question":"السائل الذي رمز لاسمه أبو هاجر من الخرج يقول في هذا السؤال سماحة الشيخ: هل يجوز للإنسان أن يذهب للعلاج عند السحرة وذلك في الضرورة القصوى؟ وجهونا في ضوء هذا السؤال.","title":"حكم الذهاب للعلاج عند السحرة","answer":"الجواب: لا يجوز للمسلم أن يذهب إلى السحرة والكهنة، لا لسؤالهم ولا للعلاج، يجب الحذر منهم وعدم تصديقهم وعدم إتيانهم؛ لأن الرسول حذر من ذلك، الرسول ﷺ حذر من المجيء إلى السحرة والكهنة والعرافين، وقال: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة وقال عليه الصلاة والسلام: من أتى عرافًا أو كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ. فالواجب الحذر من السحرة وغيرهم من الكهنة والعرافين وغيرهم ممن يتكلم في الأمور بالطرق الغيبية ويتخرص، نسأل الله العافية.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12644/حكم-الذهاب-للعلاج-عند-السحرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54723.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14194,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ع. م. د) أخونا رسالته من صفحتين مجمول ما في هاتين الصفحتين السؤال عن الكهان والمشعوذين حيث انتشر أمرهم حتى بين الطلبة في الامتحانات وبين أولئك الذين يبحثون عن عمل ولا يجدون، فهؤلاء يكتبون لهم أوراق ويأمرونهم بأشياء وأشياء يعتقدون من ورائها أنها ستكون مجلبة للعمل، ويرجون من سماحة الشيخ التوجيه. جزاكم الله خيرًا.","title":"حكم إتيان الكهنة والمشعوذين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد أوضح النبي عليه الصلاة والسلام حكم الكهان والمنجمين والعرافين ومن في حكمهم ممن يدعي علم الحوادث وعلم المستقبل بالتنجيم أو بضرب الحصى أو بغير هذا من الطرق الخفية التي يزعم أنها تطلعه على علم الغيب، وقد أوضح النبي ﷺ أن حكم هؤلاء أنهم لا يجوز أن يؤتوا ولا أن يسألوا ولا أن يصدقوا، فقد ثبت في صحيح مسلم عن بعض أزواج النبي ﷺ أنه قال: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة، هذا الحديث الصحيح يدل على تحريم السؤال مجرد من دون تصديق، فكيف إذا كان مع التصديق؟ فلا يجوز سؤال الكهان، ولا إتيانهم، ولا تصديقهم.\nوفي الحديث الثاني يقول عليه الصلاة والسلام: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ أخرجه أهل السنن بإسناد صحيح، وقال أيضًا عليه الصلاة والسلام: ليس منا من سحر أو سحر له أو تكهن أو تكهن له أو تطير أو تطير له. فالذين يدعون علم المغيبات أو الحظ أو الكف أو متى ينجح فلان أو متى يقبل في وظيفة أو غير هذا من هؤلاء وأشباههم كل ذلك مما حرم الله سؤالهم واللجوء إليهم أو تصديقهم، وإنما المؤمن يسأل ربه التوفيق والتسهيل والتيسير، يسأل ربه أن يقضي له حاجته من نجاح في اختبار ومن حصول وظيفة تنفعه ... إلى غير ذلك، أما إتيان الكهان الذين يدعون علم الغيب بأي طريقة فلا يجوز إتيانهم ولا سؤالهم ولا تصديقهم، لما ثبت في حقهم من الأحاديث الصحيحة التي سبق بعضها والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12647/حكم-اتيان-الكهنة-والمشعوذين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_616/61601.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14263,"question":"يقول النبي ﷺ فيما معناه: إن الله  لم يجعل شفاء أمتي فيما حرم عليها وبعض الناس عندما يصاب ببعض الأمراض المزمنة يذهبون لبعض المشعوذين، أي: من يسمون أنفسهم بالأطباء العرب، فينصحونهم: إما بأكل لحم الخنزير، أو بشرب الخمر، وقد حدث هذا كثيرًا، ويستدل هؤلاء المشعوذون بالقاعدة الشرعية التي تقول: إن الضرورات تبيح المحظورات، ما حكم التداوي بما ذكرت، وهل القاعدة تتعارض مع معنى الحديث السابق؟!","title":"حكم التداوي بالحرام بحجة الضرورة","answer":"الجواب: هذا غلط من بعض الناس، فإن الله جل وعلا لم يجعل شفاء الناس فيما حرم عليهم، وليست داخلة في القاعدة فليس هناك ضرورة؛ لأنه ليس فيه شفاء، الشفاء فيما أباح الله جل وعلا، ولهذا قال عليه الصلاة والسلام لما سأله سائل قال: يا رسول الله! إني أصنع الخمر للدواء، قال عليه الصلاة والسلام:إنها ليست بدواء ولكنها داء وفي الحديث: إن الله لم يجعل شفاءكم فيما حرم عليكم.\nفلا يجوز للمريض أن يأتي المشعوذين الذين يتهمون باستخدام الجن ودعوى علم الغيب ونحو ذلك، أو يتهمون بأنهم يعالجون بالحرام كلحم الخنزير أو شرب الخمر أو غير هذا مما حرم الله، هذا منكر لا يجوز، بل يجب على المريض أن يبتعد عما حرم الله وألا يتعاطى إلا ما أباح الله في علاجه، فلا يأتي السحرة والكهان والمشعوذين، ولا يجوز له سؤالهم ولا تصديقهم، ولا يجوز له أن يتعالج بما حرم الله من خمر أو خنزير أو دخان أو غير هذا مما حرم الله، وفيما أباح الله غنية -والحمد لله- عما حرم الله، نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12754/حكم-التداوي-بالحرام-بحجة-الضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62107.mp3","categories":["الطب والتداوي","شروح الحديث"]},{"id":14409,"question":"السائلة (ن. ف) من الرياض تقول: احتجت إلى تقويم أسناني، وبحثت عن طبيبة لعمل ذلك التقويم، ولم أجد سوى أطباء رجال في مستشفيات متعددة، هل يجوز لي عمل ذلك عند أطباء رجال؟علمًا بأن ذلك العمل ضروري لجمالي، فأنا مقبلة على زواج، وما حكم كشف الوجه لعلاج الأسنان؟","title":"حكم ذهاب المرأة لطبيب الأسنان إذا لم توجد طبيبة","answer":"الجواب: إذا دعت الحاجة إلى ذلك، لا بأس عند فقد الطبيبة المسلمة يكون طبيب مسلم بدون خلوة، لكن من دون تفليج إذا كان مرض في الأسنان، أو حاجة إلى قلع.  أما التفليج للحسن فلا يجوز، فالرسول ﷺ لعن المتفلجات للحسن، ولعن النامصات، ولعن الواشمات والمستوشمات والمتفلجات للحسن، يعني: تفلج أسنانها لحسن، أما إذا كان بالسن مرض، أو سواد ليزال، أو ما أشبه ذلك من الأمراض لا حرج يتولاها الطبيبة المسلمة، فإن فقدت فالطبيب المسلم من دون خلوة، يكون معك أخوك أو أبوك أو أمك، ونحو ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12891/حكم-ذهاب-المراة-لطبيب-الاسنان-اذا-لم-توجد-طبيبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55306.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":14435,"question":"أخيرًا من أسئلة أختنا نعرض هذا السؤال تقول: سمعت خبرًا بأن هناك امرأة تتعامل مع الجن، وأخبرها الجن بأنها ستكون وسيطة خير بين الجن والإنس لتعالج الأمراض المستعصية في الإنس، والتي عجز عنها طب الإنس، والمرأة هي الوسيط، والجن يعطون الأدوية، ويعملون العمليات لبني الإنسان، ولكن الإنسان لا يراهم، ما رأي سماحتكم في مثل هذا؟","title":"حكم التعامل مع الجن لعلاج الناس","answer":"الجواب: ليس لهذا أصل، ولا يعتمد عليه، فإن أخبار الجن، وأخبار العجائز، وأخبار من يخدم الجن لا يوثق بها، ولا يعتمد عليها، ولا يجوز أن يعتمد على قول عجوز أو شيخ أو شاب، أو غير ذلك ينقل عن الجن أشياء، بل يجب أن يحذر منهم، وأن لا يستخدمهم في شيء؛ لأنهم إذا استخدموه قد يجرونه إلى الشرك بالله ، إذا كانوا غير مؤمنين، وليس المؤمن منهم معروفًا معرفة يقينية، فقد يكون منافقًا، وقد يكون يدس السم في الدسم؛ لأنك لا تعرفهم ولا تخالطهم مخالطة جهرية، وتعرف أحوالهم وأحوال قرنائهم من الأخيار، حتى تعرف الثقة من غير الثقة. فالحاصل: أنّ بيننا وبينهم جهلًا كبيرًا، وأخلاقًا متباينة، وصفات متباينة، لا نستطيع معها أن نتحقق ما هم عليه، ومن عرفنا منهم بما يظهره من الإيمان ندعو له بالتوفيق، وندعو له بالصلاح، ولكن لا نثق به، ولا نطمئن إليه في أن نأخذ منه طبًا، أو غير ذلك، أو نستشيره في شيء، أو ما أشبه ذلك، فإن هذا قد يفضي إلى دعوى علم الغيب، قد يبتلى الإنسان بذلك فيظن أن عنده شيئًا من علم الغيب بواسطة الجن، وقد يدعو إلى ذلك، فيكون ممن قال الله فيهم -جل وعلا-: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا[الجن:6].\nفهو مع الجن على خطر، قد يستخدمونه في الشرك، قد يستخدمونه في البدع، قد يستخدمونه في المعاصي، فيضر نفسه، وهو لا يدري، ويضر غيره وهو لا يدري. فلا تجوز المعاملة لهم في الطب ولا في غيره، بل من عرف منهم أحدًا أو اتصل به أحد يدعوه إلى الله يعلمه الخير، يدعوه إلى توحيد الله، وإلى طاعة الله، وينصحه أن يعلم من عنده خير طاعة الله ، ولا يطمئن إليه في شيء، ولا يطلب منه شيئًا للناس؛ لأنه قد ينقل شيئًا يضر الناس، وقد يعطيه شيئًا طيبًا ثم يغشه بعد ذلك. فالحاصل: أنه على خطر؛ لأنك لا تعلم أحوالهم على اليقين، وهم يرونك ولا تراهم، وقد يخفون عنك أشياء كثيرة، وقد يدعون الإيمان وهم منافقون، وقد يتصلون بك لأغراض أخرى، حتى يأخذوها منك، ثم يفعلوا بك ما يريدون، فأنت على خطر، فالواجب الحذر منهم إلا من الدعوة إلى الله  وتبصيرهم بالحق، ودعوتهم إليه، وإرشادهم إليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12925/حكم-التعامل-مع-الجن-لعلاج-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_631/nour_63105.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14538,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول الراسلة:آمال محمد عبدالعزيز، جمهورية مصر العربية، الإسكندرية، أختنا رسالتها مطولة بعض الشيء سأقرؤها كما وردت تقول:بسم الله الرحمن الرحيم. السلام عليكم ورحمة الله وبركاته.أرجو إفادتي بالرد على هذا  أنا سيدة متزوجة منذ عامين، ولم أرزق بأولاد بعد، وكنت قد ذهبت للأطباء المتخصصين أنا وزوجي، وتأكدنا من سلامتنا نحن الاثنين، ولا سبب عند أحد منا، أشار عليَّ بعض الأهل بعمل بعض الوصفات البلدية، والتي هي في اعتقادهم تسبب الحمل، ومنها: أن أجلس فوق خلاص السيدة الحامل بعد أن تلد، ولكني رفضت.الشيخ: ومنها...المقدم: ومنها: أن أجلس فوق خلاص السيدة الحامل بعد أن تلد، ولكني رفضت فعل مثل هذه الأشياء وشبيهاتها، خوفًا من أن أغضب الله ، ولكوني أعلم أن هذا شرك بالله .وأخيرًا جاؤوا لي بنبات من المدينة المنورة، اسمه: كف مريم، وقالوا: إنه يوضع في الماء عند الغروب في آخر ليلة جمعة من الشهر العربي، ثم يؤخذ ماؤه قبل الغروب في يوم الجمعة، ويغسل به بعض أجزاء الجسم، مع ترديد القرآن الكريم، والدعاء لله ، وأكدوا لي أن سيدات استعملوه، ثم رزقهم الله بالذرية بعد ذلك، ففعلت ذلك، وأنا لا أدري إذا كان هذا قد يغضب الله أم لا؟ علمًا بأني حريصة كل الحرص أن لا أفعل شيئًا من ذلك يغضب الله، وأولًا: هل هذا ما فعلت يعد شرك بالله  أم لا؟ثانيًا: أرجو أن تنصحوني بأي شيء أو بأي عمل أستطيع أن أتقرب به لله  لكي يتقبل الدعاء ويرزقنا بالذرية الصالحة، جزاكم الله خيرًا.","title":"تعاطي الأسباب الشرعية من أجل الحمل","answer":"الجواب:\n\nبسم الله الرحمن الرحيم. \n\nالحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد:\n\nفأسأل الله أن يزيدك -أيها الأخت في الله- من الخير والعلم النافع، والعمل الصالح، والرغبة فيما عند الله، والحذر من أسباب غضبه. \n\nولا شك أن الواجب على كل مكلف من الرجال والنساء هو تقوى الله، والحذر من أسباب الغضب، وأن لا يتعاطى شيئًا مما حرم الله عليه، وأنت في تحريك الخير وحرصك على ما أباح الله تشكرين على ذلك.\n\nولا شك أن ما قيل لك أن الجلوس على خلاص امرأة نفساء أمر لا أصل له، سواء أرادوا بذلك الدم الذي خرج منها، أو أرادوا شيئًا غير ذلك كالمشيمة، أو غير ذلك، كل هذا لا أصل له.\n\nأما التداوي بشيء من النبات من المدينة أو غير المدينة، إذا جرب، ونفع فلا بأس بذلك، إذا وجد نبات في المدينة أو غير المدينة تفعله المرأة بطريق التدخين، أو بطريق سحقه وغسل الجسد به، أو بعض الجسد أو شربه أو غير ذلك فلا بأس بذلك، إذا جرب ونفع؛ لأن التداوي جائز، بل مشروع، ولا حرج في ذلك أن يتداوى الإنسان بما أباح الله له: عباد الله، تداووا، ولا تداووا بحرام النبي ﷺ شرع للأمة التداوي، فلا حرج في ذلك إذا وجد نبات جرب فيه أنه من أسباب الحمل، أو وجد علاج آخر مما أباح الله، كالكي في بعض البدن، أو شراب مما أباح الله، أو فاكهة مما أباح الله، أو ما أشبه ذلك مما جرب ونفع مما هو مباح.\n\nوأما الدعاء فينبغي للمؤمن أن يلح في الدعاء أنت والزوج، كل منكما يشرع له الإلحاح في الدعاء بطلب الله  أن يمنحكما الذرية الصالحة، ولا سيما في أوقات الإجابة، مثل آخر الليل، جوف الليل، مثل آخر الصلاة قبل السلام، مثل وقت السجود، حال السجود في الصلاة فإنه محل دعاء، يقول النبي ﷺ: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء وإذا كان على طهارة وقت استقبال القبلة كان ذلك من أسباب الإجابة، فأوصيكما جميعًا بدعاء الله، والضراعة إليه، وسؤاله سبحانه بصدق وإخلاص وضراعة وانكسار أن يمنحكما الذرية الطيبة، وهذا من أنفع العلاج، ومن أعظم الأسباب، وفق الله الجميع.\n\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13034/تعاطي-الاسباب-الشرعية-من-اجل-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63501.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":14697,"question":"سمعت من برنامجكم بأن تقرأ بعض آيات القرآن الكريم لإبطال عمل السحر، فما هي هذه الآيات؟ وهل يجوز قراءتها من قبل الشخص نفسه أم من قبل شخص آخر؟","title":"آيات فك السحر، وهل يجوز قراءتها من المسحور؟","answer":"الجواب: نعم، قراءة الآيات قد ينفع الله بها من الشخص نفسه، ومن غيره من أهل الإيمان والتقوى، فإذا ظن الإنسان أن به سحرًا، أو علم أن به سحرًا، وقرأ على نفسه آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] مع فاتحة الكتاب، ومع قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1]، وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1]، وقُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] ينفث على صدره، ويقرأ هذه السور والآيات، كل ذلك يفيده -إن شاء الله-، ومن أسباب عافيته، وسلامته من السحر. والأحسن أن يكرر قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين ثلاث مرات، مع النفث على صدره، ويحسن أيضًا أن يقرأ آيات السحر المعروفة في سورة الأعراف، وفي سورة يونس، وفي سورة طه، يقرؤها أيضًا، مع ذلك في الماء، ويشرب منه، ويغتسل بالباقي، كل هذا من أسباب العافية، إن نفث على نفسه بذلك على صدره بذلك فهذا من أسباب العافية، وإن قرأ ذلك في ماء ثم شرب منه واغتسل به فذلك أيضًا من أسباب الشفاء، وإن جعل في الماء سبع ورقات من السدر دقها -السدر الأخضر- دقها وجعلها في الماء، فذلك أيضًا مفيد في علاج السحر، وهكذا في علاج الرجل الذي حبس عن زوجته ينفعه هذا -بإذن الله-، وإن قرأها غير المصاب -قرأها بعض إخوانه في الله- في ماء وشرب منه، واغتسل به، فذلك نافع -إن شاء الله-، وينبغي أن يختار من ذلك أهل الخير المعروفون بالخير والعلم والفضل حتى يقرأ هذه الآيات في الماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13197/ايات-فك-السحر-وهل-يجوز-قراءتها-من-المسحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62902.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14704,"question":"سمعت من برنامجكم بأن تقرأ بعض آيات القرآن الكريم لإبطال عمل السحر، فما هي هذه الآيات؟ وهل يجوز قراءتها من قبل الشخص نفسه أم من قبل شخص آخر؟","title":"آيات فك السحر، وهل يجوز قراءتها من المسحور؟","answer":"الجواب: نعم، قراءة الآيات قد ينفع الله بها من الشخص نفسه، ومن غيره من أهل الإيمان والتقوى، فإذا ظن الإنسان أن به سحرًا، أو علم أن به سحرًا، وقرأ على نفسه آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255] مع فاتحة الكتاب، ومع قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1]، وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1]، وقُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] ينفث على صدره، ويقرأ هذه السور والآيات، كل ذلك يفيده -إن شاء الله-، ومن أسباب عافيته، وسلامته من السحر. والأحسن أن يكرر قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين ثلاث مرات، مع النفث على صدره، ويحسن أيضًا أن يقرأ آيات السحر المعروفة في سورة الأعراف، وفي سورة يونس، وفي سورة طه، يقرؤها أيضًا، مع ذلك في الماء، ويشرب منه، ويغتسل بالباقي، كل هذا من أسباب العافية، إن نفث على نفسه بذلك على صدره بذلك فهذا من أسباب العافية، وإن قرأ ذلك في ماء ثم شرب منه واغتسل به فذلك أيضًا من أسباب الشفاء، وإن جعل في الماء سبع ورقات من السدر دقها -السدر الأخضر- دقها وجعلها في الماء، فذلك أيضًا مفيد في علاج السحر، وهكذا في علاج الرجل الذي حبس عن زوجته ينفعه هذا -بإذن الله-، وإن قرأها غير المصاب -قرأها بعض إخوانه في الله- في ماء وشرب منه، واغتسل به، فذلك نافع -إن شاء الله-، وينبغي أن يختار من ذلك أهل الخير المعروفون بالخير والعلم والفضل حتى يقرأ هذه الآيات في الماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13197/ايات-فك-السحر-وهل-يجوز-قراءتها-من-المسحور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62902.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":14727,"question":"أنا أشكو من صداع، وطلب مني الأطباء أن أعمل صورة على الرأس، أي: كشف بالأشعة، وهذا العمل يتطلب مني الكشف عن شعري وهو حرام ماذا أفعل؟أطلب من الشيخ النصيحة.","title":"حكم كشف المرأة رأسها للطبيب","answer":"الجواب: إذا دعت الحاجة إلى الكشف على الرأس، أو على عضو من البدن للمرض، فلا حرج في ذلك، الله يقول سبحانه: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ[الأنعام:119] فإذا دعت الحاجة إلى كشف الطبيب على يدك أو رجلك أو رأسك أو نحو ذلك فلا حرج في ذلك، وإن كان المرض يسيرًا، واستغنيت وتركت ذلك؛ لأن المرض يسير، وله دواء ميسر، فالحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13229/حكم-كشف-المراة-راسها-للطبيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63714.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":14815,"question":"رسالة وصلت إلى البرنامج من مكة المكرمة، وباعثها المستمع (ع. ي. ح. ج) رسالته مطولة يقول فيها: لي ابنة تبلغ من العمر عشرة أشهر، وقد مرضت وذهبت بها إلى المستشفى، وهي في حالة خطيرة، وأمروا بتنويمها، وجلست معها أمرضها مدة التنويم بالمستشفى، والحمد لله تحسنت حالتها عن حالتها الأولى، وأخرجونا بعد ذلك، وذهبنا إلى المنزل، وبعد يومين فقط عاد إليها المرض، وكان كل من رآها قال: هذه فيها كذا وكذا، وأنا لا أدري ماذا أفعل بها؟ وبعد ذلك رآها أحد الناس وقال: اكوها فإن شاء الله أنها ستشفى، وذهبت بها عند رجل فكواها، ولكن اشتد بها المرض، وبما أنني قد ذهبت بها إلى المستشفى وإلى الكاوي، ولكن دون فائدة استحكمت بحكم الله، وجلست بها في المنزل، ولكن حكم الله أقوى على كل شيء، وتوفيت بعد ذلك، قلت: يا ليتني لم أكوها، يا ليتني ذهبت بها إلى المستشفى مرة ثانية، يا ليت يا ليت، وبدأت أتألم وأتندم، هل علي فيما فعلت حكم شرعي؟وجهوني، جزاكم الله خيرًا.","title":"حكم من عالج ابنته ثم تركها في المنزل فماتت؟","answer":"الجواب: ليس عليك بأس، وأنت مجتهد، ولا حرج عليك، وهذه أسباب؛ الذهاب إلى المستشفى وإلى الكاوي كل هذه أسباب، والنبي  قال: الشفاء في ثلاث: كية نار، أو شرطة محجم، أو شربة عسل، وما أحب أن أكتوي وفي اللفظ الآخر: وأنا أنهى أمتي عن الكي فالكي يعتبر آخر الطب عند الحاجة إليه، وأنت فعلته عند الحاجة، فإذا كان الكاوي ممن قد جرب في معرفة الكي، وأنه يكوي المرضى، ويجتهد، لا بأس عليك في ذلك، والحمد لله، وبكل حال فأنت مجتهد ولا شيء عليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13323/حكم-من-عالج-ابنته-ثم-تركها-في-المنزل-فماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64306.mp3","categories":["الطب والتداوي"]},{"id":14830,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين من الكويت، وقع في نهايتها بالحرفين (ن. م) يقول في أحد أسئلته:أنا قرأت في كتاب الطب النبوي أنه عندما يريد أي شخص أن يزيح عن نفسه الاكتئاب يكتب بعض الآيات، ويضعها في الماء، ويشرب منها، فهل هذا الشيء مفيد؟ وإذا كان مفيدًا أخبرونا -جزاكم الله خيرًا- كيف نكتب؟ وما هي الآيات التي نكتبها؟","title":"حكم كتابة بعض الآيات ثم غسلها وشربها","answer":"الجواب: لا حرج أن يكتب الإنسان في إناء نظيف، أو ورق نظيف، يكتب بعض الآيات، مثل آية الكرسي، وسورة الفاتحة وقُلْ هُوَ اللهُ أحدٌ [الإخلاص:1] والمعوذتين، وما تيسر من القرآن، ثم يكتبها بالزعفران، ثم يغسله، ويشرب ذلك لا بأس، أو يقرأ في الماء، ثم يشرب ذلك، فلا حرج في ذلك.  وقد ثبت أنه ﷺ قرأ في ماء لـ ثابت بن قيس بن شماس، ونص أهل العلم كـ ابن القيم وغيره أنه لا بأس بالكتابة في الإناء النظيف، أو في الأوراق النظيفة، يكتب بالزعفران، ثم يعصره ويشربه، لا حرج في ذلك -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13327/حكم-كتابة-بعض-الايات-ثم-غسلها-وشربها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64309.mp3","categories":["الطب والتداوي"]},{"id":15001,"question":"يقول صاحب الودع وقارئة الفنجان والرسل وقراءة الكف لنا، هل هي حرام أم حلال؟","title":"حكم قراءة الفنجان والكف والودع","answer":"الجواب: كل هذا بدع، كلها منكرة، لا صحة لها، صاحب الفنجان وقراءة الكف، ورمي الودع، أو ضرب الودع، أو بالحصى كله من تعاطي علم الغيب كله باطل، كله منكر ولا صحة له، بل هو دجل وكذب وافتراء، ويدعون علم الغيب بأشياء أخرى غير هذا كذب، وإنما يعتمدون على ما تقول لهم أصحابهم من الجن، فإن بعضهم يستخدم الجن ويقول ما تقوله له الجن، فيصدقون ويكذبون، يصدقون في بعض الأشياء التي اطلعوا عليها في بعض البلدان، أو استرقوها من السمع، ويكذبون في الغالب، والأكثر يكذبون، ويتحيلون على الناس، حتى يأخذوا أموالهم بالباطل، وهكذا الإنس الذين يخدمونهم، قد يكذبون أيضًا ويفترون ويقولون هذا كذا، وهذا كذا، وهم كذبة، إنما يأكلون أموال الناس بالباطل، وعلم الغيب لا يعلمه إلا الله . أما كلمة الرسل ما أدري إيش مراده بالرسل، كلمة الرسل هذا كلام مجمل، إن كان المقصود قراءة القرآن الذي جاء به الرسول ﷺ يقرؤه ويتدبر ما فيه لعله يجد شيئًا يستعين به على علاج المريض، يعني يتدبر القرآن لعله يجد شيئًا يعني يستعين به على علاج المريض بقراءة آية على المريض، أو ما أشبه ذلك، فهذا لا يحتاج إلى هذا الكلام، القرآن شفاء، فإذا قرأ من بعض الآيات آية الكرسي، أو الفاتحة أو قُل هُو اللّهُ أَحْدٌ [الإخلاص:1]  أو المعوذتين هذا طيب، وهذه من أسباب الشفاء، فتسمية الرسل ما أدري ما مراده.\nالمقدم: بالنسبة للرسل -بارك الله فيكم- يقول: يحكى أنه هناك إذا جاء لهم من يريد الاستفادة من صاحبة الودع وقارئة الفنجال إلى آخره أنهم يرسلون رسولًا يخبر عن هذا الشخص، يخبر أهله وأقاربه أنه بخير. الشيخ: هذا كلام ما له تعلق بالعلاج، إرسال الرسل جمع رسول إلى أهل المريض هذا ما له تعلق بالعلاج، سواء أرسلوا لهم، أو ما أرسلوا لهم، هذا شيء ماله تعلق بالعلاج، إنما هو متعلق بتطمينهم عن صحته، هذا شيء آخر، نعم. المقدم: هو يشتكي من كثرة هؤلاء في البلد، يعني: في بلده في السودان، ويقول: إذا تكرر تحقق ما يقولون، هل في هذا علم بالغيب أم لا؟ الشيخ: أبدًا، فهو كله باطل، ولكن قد يتكرر لأنهم شيء يعرفونه من بلادهم، مثل يخبرون عن إنسان فعل كذا، أو فعل كذا، وهم قد شاهدوه في البلاد الأخرى من السودان، أو أشياء خبرتهم بها جن أن هذا وقع في بلد كذا، وعمل له كذا، وصار كذا، فهم يأخذون عن الجن أخبارًا أدركها الجن في بعض البلدان، فأخبروا بها أولياءهم، هذا كله لا صحة له، ولا يحكم فيه بأنهم يعلمون الغيب أبدًا، علم الغيب إلى الله ، لكن هناك أمور تقع في بعض البلدان فينقلها الجن بعضهم إلى بعض، أو شيء يسترق من السماء، كلمة يسمعونها من الملائكة إذا استرقوا السمع إلى السماء فينقلونها إلى أوليائهم من الإنس، فقد تكون حقًا سمعوه ما لبس عليهم فيه فيقع، ويظن الناس أن كل ما فعلوه، قالوا: صحيح، ويكذبون مع ذلك الكذب الكثير كما في الحديث: أنهم يكذبون معها مائة كذبة وفي بعض الروايات: يكذبون أكثر من مائة كذبة فلا يلتفت إليهم؛ لأن عمدتهم الكذب، أو الاستعانة بالجن في كذب الجن، وفيما يتعاطونه من الباطل الذي يشوشون به على الناس، نسأل الله العافية. والجن كالإنس فيهم الكافر، فيهم المبتدع، فيهم الفاسق، فيهم الطيب، فالفساق للفساق، والكفار للكفار، والطيبون للطيبين، فالجن الذين يخدمون بعض شياطين الإنس، بإخبارهم بعض المغيبات التي سمعوها من السماء، أو سمعوها من بعض البلدان، هؤلاء لأنهم خدموهم بعبادتهم من دون الله، والذبح لهم ونحو ذلك، فالجن الذين يخدمونهم بهذه الأخبار، وهذه الأسفار التي يكذبون فيها، وقد يصدقون فيها شيء قليل فيظنهم الناس صادقين في البقية، نعم.","link":"https://binbaz.org.sa/fatwas/13517/حكم-قراءة-الفنجان-والكف-والودع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_662/nour_66204.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":15004,"question":"يقول صاحب الودع وقارئة الفنجان والرسل وقراءة الكف لنا، هل هي حرام أم حلال؟","title":"حكم قراءة الفنجان والكف والودع","answer":"الجواب: كل هذا بدع، كلها منكرة، لا صحة لها، صاحب الفنجان وقراءة الكف، ورمي الودع، أو ضرب الودع، أو بالحصى كله من تعاطي علم الغيب كله باطل، كله منكر ولا صحة له، بل هو دجل وكذب وافتراء، ويدعون علم الغيب بأشياء أخرى غير هذا كذب، وإنما يعتمدون على ما تقول لهم أصحابهم من الجن، فإن بعضهم يستخدم الجن ويقول ما تقوله له الجن، فيصدقون ويكذبون، يصدقون في بعض الأشياء التي اطلعوا عليها في بعض البلدان، أو استرقوها من السمع، ويكذبون في الغالب، والأكثر يكذبون، ويتحيلون على الناس، حتى يأخذوا أموالهم بالباطل، وهكذا الإنس الذين يخدمونهم، قد يكذبون أيضًا ويفترون ويقولون هذا كذا، وهذا كذا، وهم كذبة، إنما يأكلون أموال الناس بالباطل، وعلم الغيب لا يعلمه إلا الله . أما كلمة الرسل ما أدري إيش مراده بالرسل، كلمة الرسل هذا كلام مجمل، إن كان المقصود قراءة القرآن الذي جاء به الرسول ﷺ يقرؤه ويتدبر ما فيه لعله يجد شيئًا يستعين به على علاج المريض، يعني يتدبر القرآن لعله يجد شيئًا يعني يستعين به على علاج المريض بقراءة آية على المريض، أو ما أشبه ذلك، فهذا لا يحتاج إلى هذا الكلام، القرآن شفاء، فإذا قرأ من بعض الآيات آية الكرسي، أو الفاتحة أو قُل هُو اللّهُ أَحْدٌ [الإخلاص:1]  أو المعوذتين هذا طيب، وهذه من أسباب الشفاء، فتسمية الرسل ما أدري ما مراده.\nالمقدم: بالنسبة للرسل -بارك الله فيكم- يقول: يحكى أنه هناك إذا جاء لهم من يريد الاستفادة من صاحبة الودع وقارئة الفنجال إلى آخره أنهم يرسلون رسولًا يخبر عن هذا الشخص، يخبر أهله وأقاربه أنه بخير. الشيخ: هذا كلام ما له تعلق بالعلاج، إرسال الرسل جمع رسول إلى أهل المريض هذا ما له تعلق بالعلاج، سواء أرسلوا لهم، أو ما أرسلوا لهم، هذا شيء ماله تعلق بالعلاج، إنما هو متعلق بتطمينهم عن صحته، هذا شيء آخر، نعم. المقدم: هو يشتكي من كثرة هؤلاء في البلد، يعني: في بلده في السودان، ويقول: إذا تكرر تحقق ما يقولون، هل في هذا علم بالغيب أم لا؟ الشيخ: أبدًا، فهو كله باطل، ولكن قد يتكرر لأنهم شيء يعرفونه من بلادهم، مثل يخبرون عن إنسان فعل كذا، أو فعل كذا، وهم قد شاهدوه في البلاد الأخرى من السودان، أو أشياء خبرتهم بها جن أن هذا وقع في بلد كذا، وعمل له كذا، وصار كذا، فهم يأخذون عن الجن أخبارًا أدركها الجن في بعض البلدان، فأخبروا بها أولياءهم، هذا كله لا صحة له، ولا يحكم فيه بأنهم يعلمون الغيب أبدًا، علم الغيب إلى الله ، لكن هناك أمور تقع في بعض البلدان فينقلها الجن بعضهم إلى بعض، أو شيء يسترق من السماء، كلمة يسمعونها من الملائكة إذا استرقوا السمع إلى السماء فينقلونها إلى أوليائهم من الإنس، فقد تكون حقًا سمعوه ما لبس عليهم فيه فيقع، ويظن الناس أن كل ما فعلوه، قالوا: صحيح، ويكذبون مع ذلك الكذب الكثير كما في الحديث: أنهم يكذبون معها مائة كذبة وفي بعض الروايات: يكذبون أكثر من مائة كذبة فلا يلتفت إليهم؛ لأن عمدتهم الكذب، أو الاستعانة بالجن في كذب الجن، وفيما يتعاطونه من الباطل الذي يشوشون به على الناس، نسأل الله العافية. والجن كالإنس فيهم الكافر، فيهم المبتدع، فيهم الفاسق، فيهم الطيب، فالفساق للفساق، والكفار للكفار، والطيبون للطيبين، فالجن الذين يخدمون بعض شياطين الإنس، بإخبارهم بعض المغيبات التي سمعوها من السماء، أو سمعوها من بعض البلدان، هؤلاء لأنهم خدموهم بعبادتهم من دون الله، والذبح لهم ونحو ذلك، فالجن الذين يخدمونهم بهذه الأخبار، وهذه الأسفار التي يكذبون فيها، وقد يصدقون فيها شيء قليل فيظنهم الناس صادقين في البقية، نعم.","link":"https://binbaz.org.sa/fatwas/13517/حكم-قراءة-الفنجان-والكف-والودع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_662/nour_66204.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":15061,"question":"المستمع عايد سعيد الزهيدي الجهني، بعث يسأل ويقول: تلفت بعض أسناني بسبب التسوس، وذهبت إلى المستشفى لتبديلهن بذهب، قال لي بعض الأصدقاء: إنه لا يجوز، فهل ما قاله صحيح؟","title":"حكم تركيب أسنان من الذهب للرجل","answer":"الجواب: إذا تيسر غير الذهب فهو أحوط، من المعادن الأخرى إذا تيسر فهو أحوط، فإن لم يتيسر جاز للحاجة، فقد ثبت أن بعض أصحاب النبي ﷺ ربطوا أسنانهم بالذهب، وهذه حاجة شديدة تشبه الضرورة، فإذا دعت الحاجة فلا حرج، لكن كونه يستعمل أسنانًا من غير الذهب إذا تيسر ذلك فهو أحوط وأولى، وهو متيسر بحمد الله. أما النساء فأمرهن أوسع؛ لأن الذهب حل لهن، لكن الرجل ينبغي له أن يدع الأسنان من الذهب إذا تيسر غيرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13548/حكم-تركيب-اسنان-من-الذهب-للرجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49315.mp3","categories":["الطب والتداوي"]},{"id":15149,"question":"هذه رسالة أيضًا وردتنا من زوجة طبيب مسلم تقول فيها: أيهما أفضل: الطبيب الرجل المسلم أم الطبيبة المرأة غير المسلمة؟  يعني: في الكشف على النساء.","title":"أيهما يقدم الطبيبة الكافرة أم الطبيب المسلم بالنسبة للمرأة؟","answer":"الجواب: إذا ما تيسر طبيبة مسلمة فالطبيبة الكافرة أولى من الطبيب الرجل فيما يتعلق بعورات النساء، وأسلم، هذا فيما يظهر لي -والله أعلم- أن الطبيبة الكافرة المأمونة التي لا يظهر منها شر على المسلمين، ويظهر منها النصح للمسلمين في طبها، أولى من الرجل في طب المرأة عند الحاجة إلى ذلك. أما إذا وجدت الطبيبة المسلمة فهي تغني عن الطبيبة الكافرة، ثم بعدها الطبيب المسلم، ثم الطبيب الكافر بالتدريج: أول طبيبة مسلمة، ثم طبيبة كافرة -للنساء يعني-، ثم طبيب مسلم، ثم طبيب كافر عند الحاجة.  ومهما أمكن الاستغناء عن الطبيب الكافر والطبيبة الكافرة فهو أولى بالأطباء المسلمين والطبيبات المسلمات، لكن عند الحاجة عند عدم الاكتفاء بالأطباء المسلمين والطبيبات؛ لا بأس من استعمال الطبيب الكافر والطبيبة الكافرة عند الحاجة إليهم، مع العناية بعدم إظهارهم ما يضر المسلمين، أو دعوتهم للمسلمين لما يضرهم، يعني بشيء من شعائر كفرهم وضلالهم، يكونون مشغولين بمهمتهم غير مستعملين ما يضر المسلمين في دعوتهم إلى الباطل، أو تعليم الباطل، أو ما أشبه ذلك مما يضر المسلمين.","link":"https://binbaz.org.sa/fatwas/13645/ايهما-يقدم-الطبيبة-الكافرة-ام-الطبيب-المسلم-بالنسبة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65802.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":15170,"question":"هذه رسالة وردتنا من خميس مشيط من المستمع عبد بن حمد، يقول في رسالته: هل يجوز التداوي من عند الساحر أو الكاهن؟ وهل هذا يعد من الشرك المحبط للعمل أم لا؟","title":"ما حكم التداوي عند السحرة والكهان؟","answer":"الجواب: لا يجوز التداوي عند السحرة والكهنة؛ لأن النبي ﷺ نهى عن إتيان الكهنة والسحرة، قال: لا تأتوهم وقال -عليه الصلاة والسلام-: من أتى عرافًا فسأله عن شيء؛ لم تقبل له صلاة أربعين يومًا رواه مسلم في الصحيح، والعراف يطلق على الكاهن والمنجم والساحر والرمال وأشباههم، وقال ﷺ: من أتى كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد -عليه الصلاة والسلام-، قال: ليس منا من سحر أو سُحر له، وليس منا من تكهن أو تُكهن له. فلا ينبغي للمؤمن أن يأتي العرافين، ولا الكهنة، ولا المنجمين، بل يحذرهم غاية الحذر، ولا يجوز سؤالهم، ولا تصديقهم، سؤالهم منكر، وليس من الشرك، لكنه منكر، وتصديقهم في علم الغيب إذا صدقهم بأنهم يعلمون الغيب هذا كفر أكبر؛ لأن علم الغيب إلى الله ، فمن زعم أن أحدًا يعلم الغيب الرسول ﷺ أو غيره فهو كافر؛ لأن علم الغيب إلى الله ، قال تعالى: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65] فالغيب عنده  ليس إلى غيره، نعم.","link":"https://binbaz.org.sa/fatwas/13677/ما-حكم-التداوي-عند-السحرة-والكهان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_659/nour_65907.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":15227,"question":"الرسالة الأخيرة في لقائنا هذا وردتنا من المرسل عبداللطيف عبدالله من الدلم بالخرج، يقول: إن زوجتي مصابة بمرض السكر، وعندها مرض ضغط الدم، فقرر الطبيب المختص أن الحمل عليها منه ضرر كبير، أو يكون خطر عليها، وعلى الجنين أيضًا، وحبوب منع الحمل تضرها، وتسبب مضاعفات أخرى، وقال: ما فيه إلا حالتين فقط:الأولى: قفل أو قلب الرحم.والثانية: العزل، أفيدوني بالأصلح، جزاكم الله عني خير الجزاء.","title":"حكم منع الحمل إذا كان فيه ضرر على المرأة","answer":"الجواب:  إذا تيسر دواء يغني عن قلب الرحم هذا أولى؛ لأنها قد تحتاج إلى الولد، وقد يزول الأذى، ويطيب المرض، فتحتاج إلى الولد، فينبغي العلاج بما يزيل الضرر، أو يخفف الضرر من دون قلب الرحم، حتى لا يفوتها الولد لو رغبت في ذلك.  وإذا كفى العزل في بعض الأحيان هذا طيب، العزل لا بأس به، أو دواء آخر غير العزل يمنع من الحمل منعًا مؤقتًا حتى يزول الأذى، ويزول المرض، فهذا أولى.  أما الشيء الذي يقطع الحمل مرة واحدة، فهذا ينبغي أن لا يفعل إلا عند الضرورة، نعم.","link":"https://binbaz.org.sa/fatwas/13729/حكم-منع-الحمل-اذا-كان-فيه-ضرر-على-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_668/nour_66807.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":15281,"question":"سؤاله الثاني يقول: هل يجوز استعمال مانع الحمل بسبب قلة دخلي المالي الذي لا يفي بحاجاتنا المعيشية، إضافة إلى سوء صحتي، وما أصاب به من الإرهاق والسهر، وأخشى أن يتضاعف ذلك حينما يكثر الأولاد؟ أفيدونا، جزاكم الله خيرًا.","title":"ما حكم استعمال موانع الحمل لقلة الدخل؟","answer":"الجواب: لا يجوز تعاطي ما يمنع الحمل من أجل خوف ضيق المعيشة، فالله هو الرزاق ، وهذا يشبه أحوال الجاهلية الذين كانوا يقتلوا الأولاد خشية الفقر، بل يجب حسن الظن بالله، والاعتماد عليه ، فهو الرزاق العظيم -جل وعلا-، وهو القائل : وَمَا مِنْ دَابَّةٍ فِي الأَرْضِ إِلَّا عَلَى اللَّهِ رِزْقُهَا[هود:6] فالواجب حسن الظن بالله من الزوج والزوجة، وألا يتعاطوا مانع الحمل.  أما إذا كان مانع الحمل لأمر آخر لمرض الأم، أو لكونه يضر بصحتها ورحمها، أو يخشى عليها منه، أو لأن الأولاد تكاثروا؛ لأنها تحمل هذا على هذا من دون فاصل، فأرادت أن تعاطى المانع لمدة يسيرة كسنة أو سنتين، حتى لا يشق عليها تربية الأولاد، وحتى لا تعجز عن ذلك فلا بأس لمصلحة الأولاد، لا لسوء الظن بالله ، أو لمضرتها هي وعجزها هي. أما ما يتعلق بالرزق فالرزاق هو الله، سواء كنت مريضًا، أو صحيحًا، فالله هو الذي يرزقهم  وبيده تصريف الأمور -جل وعلا-، فعليك حسن الظن بالله، وعليك الثقة بالله، والله هو الرزاق  ذو القوة المتين -جل وعلا-، نعم.","link":"https://binbaz.org.sa/fatwas/13794/ما-حكم-استعمال-موانع-الحمل-لقلة-الدخل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68105.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":15609,"question":"هذا سؤال من المستمع خالد عبد العزيز الخالد من مكة المكرمة، يقول: نعلم جميعًا مدى ما وصل إليه الطب البشري الآن من تقدم إلى درجة زراعة القلب، أو نقله من شخص إلى آخر، أو أي عضو آخر كالعين مثلًا، فما الحكم الشرعي في حالة نقل قلب غير المسلم إلى شخص مسلم أو عينه أو كليته أو أي عضو من أعضاء الجسم؟وبالنسبة للقلب فالحكم مطلوب مع النظر إلى معنى الحديث الذي يفيد: أن في الجسد مضغة إذا صلحت صلح الجسد كله، وإذا فسدت فسد الجسد كله.","title":"حكم نقل أعضاء جسم الكافر إلى المسلم","answer":"الجواب: أما النقل ففيه خلاف بين العلماء: منهم من يجيز ذلك، ويجيز التبرع بذلك، ومنهم من لا يجيز هذا؛ لأن المؤمن والمسلم، والإنسان ليس له التصرف في نفسه بما يضره، فهو ملك لله ، فذهب جماعة من أهل العلم إلى أنه إذا تبرع بذلك على وجه، لا خوف عليه فيه، ولا خطر عليه فيه، أو أخذ منه عند موته على وجه ينفع غيره، منهم من أجاز هذا، ومنهم من لم يجز هذا، وقالوا: ليس للإنسان أن يتبرع بشيء من أعضائه؛ لأنها غير مملوكة له، بل هي ملك لله، فليس له أن يتبرع بها، لا كلية، ولا قلب، ولا غير ذلك. وقال آخرون من أهل العلم: إذا تبرع بشيء لا يضره كإحدى كليتيه والقرنية، وأشباه ذلك، فلا حرج؛ لأنه شيء ينفع غيره، ولا يضره، أما شيء يضره فلا، ليس له أن يتبرع بشيء يضره أو يسبب موته. وعلى كل تقدير لو فرضنا أن انتقلت كلية كافر إلى مسلم صار له حكم المسلم، وصارت تبع المسلم إذا مات على الإسلام لا تعذب؛ لأنها انتقلت من ذاك الجسد الخبيث إلى جسد طيب، فصار لها حكم الجسد الطيب بالانتقال، كما أن الخمرة إذا تخللت من غير أن يخللها أحد صارت طيبة، وكما أن الماء النجس الكثير إذا زال عنه أسباب النجاسة زال اللون والريح والطعم، وصار طيبًا، واستحال إلى الطيب طهر، فهكذا ما نقل من كافر، من كلية أو غيرها، أو قلب أو غيره، فإنه يتبع المسلم، فيكون طيبًا تبع المسلم إذا طاب المسلم طاب قلبه، ولو كان منقولًا، فإن الشرايين والأشياء المتعلقة بهذا القلب، وتمده بالدم، كلها من المسلم. فيكون الطيب جديدًا له بعدما كان خبيثًا جاءه الطيب بإمداد المسلم له، وبقائه فيه يعبد الله، ويعظم الله ويخشاه ويراقبه  فإن هذا على فرض وجوده، وعلى فرض صحة النقل، وأنه يعيش في المحل الثاني، فإنه مثل الكلية إذا نقلت ومثل القرنية، ومثل غير ذلك يكون له حكم من انتقل إليه، فإذا نقل من الكافر إلى المسلم صار طيبًا، وله حكم المسلم، وإذا نقل من المسلم إلى الكافر، صار له حكم الكافر، وحشر معه يوم القيامة، وصار تابعًا له؛ لأن الأعضاء تتبع الإنسان، فهي أعضاؤه وأجزاؤه، قلب وغيره، فإذا عُمر بالطاعات صار طيبًا، وإذا عُمر بالشرك والكفر وبغض الله ورسوله، انتقل من حال الطيب إلى حال الخبث، مثل المسلم لو ارتد عن دينه بينما هو طيب مسلم، فإذا ارتد عن دينه، وصار منافقًا أو كافرًا معلنًا صار له الخبث، انتقل له الخبث، وزال عنه الطيب لكفره وردته. فهكذا إذا انتقل عضو المسلم إلى الكافر صار له الخبث، وإذا انتقل عضو الكافر إلى المسلم صار له الطيب بالانتقال، وهذا شيء لا أعلم فيه إشكالًا ولا نزاعًا لو وقع، نعم.","link":"https://binbaz.org.sa/fatwas/14151/حكم-نقل-اعضاء-جسم-الكافر-الى-المسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_695/nour_69502.mp3","categories":["الطب والتداوي"]},{"id":15610,"question":"بالنسبة لبعض الناس حينما ييئس مثلًا من شفائه من مرض ما، ويكون إلى الموت أقرب، فقد يتبرع بشيء من أعضائه، كالعينين مثلًا، أو ربما يبيعها بيعًا، فما الحكم في هذا؟","title":"حكم تبرع أو بيع الإنسان بعض أعضائه","answer":"الجواب: أنا حتى الآن لم يتضح لي الجواز، وبعض إخواننا قد أجاز ما يتبرع به الإنسان إذا كان لا يضره، أو بعد موته إذا لم يترتب عليه نزاع بين الورثة ولا فتنة.  وأما أنا فالذي يظهر لي عدم الجواز؛ لأن هذه أمور أعطاها الله العبد، وليس له التصرف فيها، بل يجب عليه أن يقف عند حده، ولا يتصرف في أعضائه؛ ولأن المثلة محرمة في الحياة، وهذا نوع من المثلة كونه يسمح أن يمثل به فيؤخذ قلبه، أو تؤخذ كليته، أو ما أشبه ذلك، أخشى أن يكون داخلًا في النهي عن المثلة، وأخشى أن يكون عليه بهذا حرج. فأنا عندي توقف في هذا، وأنا إلى المنع أميل، أما بعض إخواني العلماء فإنهم يجيزون بعض هذا، نعم. المقدم: حتى البيع؟ الشيخ: نعم؟ المقدم: حتى البيع؟ الشيخ: البيع ما أعلم له مجيزًا، ما أعلم الآن له مجيزًا، أقول: ما أذكر أحدًا من إخواننا أجاز البيع، لا أعلم أحدًا. المقدم: إنما الخلاف هذا بالنسبة للتبرع؟ الشيخ: للتبرع، جواز التبرع، نعم. المقدم: للتبرع، أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14152/حكم-تبرع-او-بيع-الانسان-بعض-اعضاىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_695/nour_69503.mp3","categories":["الطب والتداوي"]},{"id":15677,"question":"إذا مرض شخص، يدعون الشيخ يداويه، وهو يعمل حرزًا؛ وذلك إذا كان المرض من جنون، أو من سحر، ويرش عليه الدم المسفوح، هل كان هذا في عهد النبي ﷺ والصحابة؟","title":"حرمة التداوي بالدم المسفوح والحروز","answer":"الجواب: هذا منكر، أعوذ بالله، رشه بالدم المسفوح هذا منكر، نجس، لا يجوز هذا، وكذلك عمل الحروز كونه يكتب له حروزًا يعلقها في رقبته، أو في عضده، أو في غير ذلك، فهذا كله لا يجوز، الرسول -عليه الصلاة والسلام- قال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، من تعلق تميمة فقد أشرك. المقصود: الرسول ﷺ نهى عن هذا، تعليق الحروز، وهي التمائم في أوراق، أو في خرق، أو في جلود، فيها دعوات أو آيات أو طلاسم، كل هذا لا يجوز، لا يعلق لا في يد المريض، ولا في رقبته، ولا في غير ذلك؛ لأن الرسول نهى عن هذا -عليه الصلاة والسلام-، قال ﷺ: من تعلق تميمة فلا أتم الله له، من تعلق ودعة فلا ودع الله له، من تعلق تميمة فقد أشرك. فالواجب على أهل الإسلام ترك هذه الأشياء المنكرة؛ لأن الرسول نهى عنها -عليه الصلاة والسلام-، وأما صب الدم النجس فهذا منكر ظاهر، والمسفوح: هو المراق الذي عند الذبح يخرج من البهيمة عند الذبح، هذا نجس ومحرم، فالواجب على المسلم أن يحذر ما حرم الله عليه. أما إذا قرأ عليه القرآن، قرأ عليه الفاتحة، آية الكرسي، ونفث عليه، ودعا له، هذا طيب......، وهكذا لو أخذ له دواء من الأطباء العارفين، وعالجه ببعض الطب بالدواء لا بأس، الرسول -عليه الصلاة والسلام- قال: ما أنزل الله داءً إلا أنزل له شفاء فالدواء لا بأس به، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14221/حرمة-التداوي-بالدم-المسفوح-والحروز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70608.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":15710,"question":"في حالة كون المرأة حامل، فإنها تذهب للطبيب للفحص عليها، و ما حكم كشف الطبيب؛ إذا كان الرجل مسلم للحامل، وفحصها الفحص الدقيق، هل يجوز هذا؟","title":"حكم كشف الطبيب المسلم على المرأة الحامل","answer":"الجواب: إذا كان هناك حاجة للفحص، فالواجب أن تعرض نفسها على الطبيبة المختصة، وليس على الرجل، إذا كان هناك حاجة على الطبيبة المختصة، أما على الرجل لا، لا يجوز هذا؛ لأنه فتنة، خطر فتنة إلا للضرورة، إذا كان ضرورة يخشى الموت، كالضرورة تخشى من الموت، وهناك أمراض معها، أما ما اعتاده النساء من عرض أنفسهم على الأطباء من دون حاجة، كذا عادة اتخذوها؛ هذا غلط، ما يجوز. أما مع المرأة مع الطبيبة الخاصة، إذا كان هناك حاجة فلا بأس؛ لأن عرضها على الرجل فيه خطر وفتنة، نسأل الله السلامة، إلا عند الضرورة، نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/14268/حكم-كشف-الطبيب-المسلم-على-المراة-الحامل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57319.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":15753,"question":"يقول: إن أبي وعمي يذهبون إلى السحرة ويصدقونهم، وقد نهيتهم عن ذلك، ولكن لم يستجيبوا لنهيي، فكيف لي وأنا ساكن معهم؟جزاكم الله خيرًا.","title":"التحذير من إتيان السحرة وتصديقهم","answer":"الجواب: الواجب عليك الاستمرار في النصيحة لهم، تحذرهم من ذلك، فإن امتنعوا فينبغي لك، بل الواجب عليك الخروج منهم، والانتقال إلى محل آخر؛ لقول النبي ﷺ في الحديث الصحيح: ليس منا من سحر أو سحر له وقوله ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين يومًا رواه مسلم في الصحيح، وقوله ﷺ: من أتى عرافًا، أو كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد ﷺ، هذا وعيد عظيم، والساحر من العرافين، وأشد من الكهنة، وأخبث، فيجب الحذر من المجيء إليه، ومن سؤاله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14343/التحذير-من-اتيان-السحرة-وتصديقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74105.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":15786,"question":"تسأل أم أنس فتقول: هل يجوز استخدام حبوب منع الحمل بقصد التنظيم لفترة معينة؟","title":"هل يجوز استخدام حبوب منع الحمل بقصد التنظيم لفترة؟","answer":"الجواب: إذا دعت الحاجة إلى ذلك، كأن يكون عندها أطفال كثيرون، ويشق عليها أن تحمل في وقت الرضاعة، ورضي الزوج بذلك فلا حرج، إذا كان فيه مصلحة، ودفع مضرة في أيام الرضاعة، أو كانت يضرها الحمل بالتتابع حتى يكون بينهما فجوة سنتين أو أكثر دفعًا للمضرة، ورضي الزوج بذلك فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14376/هل-يجوز-استخدام-حبوب-منع-الحمل-بقصد-التنظيم-لفترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74213.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":15791,"question":"رسالة من إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (د. ق) من المجمعة، أختنا تقول: كثيرًا ما أعاني من مرض الجاثوم، وأسمع الكثيرين ويذكرون كثيرًا من معاناتهم من هذا المرض، ما منشأ هذا المرض؟ وهل هو عضوي أم نفسي؟ أم هو من الجن؟ وما السبيل للتخلص منه؟جزاكم الله خيرًا.","title":"كيفية العلاج من مرض الجاثوم","answer":"الجواب: لا أعلم في هذا شيئًا واضحًا، إلا أني أنصح بتعاطي التعوذات الشرعية عند النوم، الإنسان يأتي بالذكر الشرعي عند النوم اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة: 255] آية الكرسي، ويقرأ قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص: 1] والمعوذتين ثلاث مرات عند النوم، ويسلم من هذا الشر، ومن ذلك أن يقول: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات عند النوم، أو في أول الليل، باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء، وهو السميع العليم ثلاث مرات في أول الليل، أو عند النوم، كل هذه وقاية من أسباب الوقاية من هذا الجاثوم، والأغلب -والله أعلم- أنه من عمل الشياطين، لكن هذه الأذكار والتعوذات تزيله وتمنعه، والحمد لله. المقدم: الحمد لله. تذكر أختنا سماحة الشيخ أنها مستمرة على أوراد الصباح والمساء؟ الشيخ: متى صدقت زال هذا، متى صدقت بذلك، وأتت بها عن علم وعن يقين وعن إخلاص، فإن الله يقيها هذا الشر، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14381/كيفية-العلاج-من-مرض-الجاثوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74218.mp3","categories":["الطب والتداوي"]},{"id":16024,"question":"آخر أسئلته يقول: أختم القرآن للاستشفاء، وأنفخه على المريض، هل هذا يجوز، أو لا؟","title":"حكم قراءة القرآن بنية الاستشفاء به","answer":"الجواب: لا بأس بذلك، القرآن جعله الله شفاء، فإذا قرأته، أو بعضه على نفسك، وأنت مريض، ترجو من الله الشفاء، أو على بعض المرضى؛ فلا حرج عليك، بل في ذلك الشفاء، قال تعالى: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] فالقرآن فيه الشفاء والخير، فإذا قرأته كله، أو بعض الآيات، كل ذلك خير، والحمد لله.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14668/حكم-قراءة-القران-بنية-الاستشفاء-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_801/nour_80109.mp3","categories":["الطب والتداوي","القرآن وعلومه"]},{"id":16063,"question":"مستمع بعث برسالة يسأل فيها ويقول: جاء في الحديث أن الرسول ﷺ قال: لعن الله الواشرة والمستوشرة ومنذ أن كنت طفلة وقعت على الأرض، وتكسرت بعض أسناني، فإذا أجريت عملية تجميل من أجل ذلك هل أكون ضمن هذا الوعيد المذكور في الحديث؟ جزاكم الله خيرًا.","title":"حكم تعديل الأسنان المشوهة","answer":"الجواب: هذا الحديث في من يفعل هذا للحسن، يوشر الأسنان، يفلجها للحسن، أما إذا كان فيها عيب لإصلاحها، أو قلعها وإبدالها؛ فلا حرج في ذلك، أما إذا كان المقصود توشيرها، وتحسينها بالتفليج هذا هو المنهي عنه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14694/حكم-تعديل-الاسنان-المشوهة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_748/nour_74820.mp3","categories":["الطب والتداوي"]},{"id":16077,"question":"يقول: ما حكم نقل دم الإنسان إلى مريض محتاج، ذلك أني سمعت بعض الناس يفسر الدم في القرآن في قوله تعالى: حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ [المائدة:3] بأن الدم هنا يشمل دم الإنسان أيضًا؟ أفتونا جزاكم الله خيرًا.","title":"حكم نقل الدم من شخص لآخر","answer":"الجواب: نعم، الدم محرم، وهو الدم المسفوح كما في الآية الأخرى: أَوْ دَمًا مَسْفُوحًا [الأنعام:145] وهو الدم الذي تحصل إراقته عند الذبح، هذا هو الدم المحرم.  وهكذا أنواع الدماء التي تسفح من الحيوانات من بني آدم وغيرهم، أما الدم الذي يكون في اللحوم بعد الذبح .... اللحم ... يوم الدم، هذا لا يضرها؛ لأنه ليس مسفوحًا.  وإذا نقل الدم لأخيه، منه إلى أخيه المحتاج على وجه لا يضر المنقول منه؛ فلا بأس إذا أقر الطبيب أن هذا الشخص مضطر إلى الدم، وتبرع له أخوه بدم لا يضره؛ فلا حرج في ذلك؛لعموم الأدلة في شرعية عون الإنسان لأخيه، مثل قوله ﷺ: من كان في حاجة أخيه؛ كان الله في حاجته مثل قوله ﷺ: والله في عون العبد ما كان العبد في عون أخيه فإذا أقر الطبيب أن هذا الدم ينفع هذا المضطر، ولا يضر المأخوذ منه؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14710/حكم-نقل-الدم-من-شخص-لاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74907.mp3","categories":["الطب والتداوي"]},{"id":16190,"question":"يقول: رجل يقرأ القرآن الكريم على مادة، ثم يأكلها بعد قراءة القرآن، هل هذا حرام، أم لا؟","title":"حكم قراءة القرآن على الطعام والشراب ثم أكله وشربه","answer":"الجواب: إذا قرأ في ماء، أو في طعام، وأكله لا نعلم فيه بأسًا، إذا قرأه في الماء هذا مستعمل معروف، قد قرأ النبي ﷺ في الماء لثابت بن قيس، وصبه عليه، فإذا قرأ في ماء، وشربه، أو صبه على المريض هذا من أسباب الشفاء، وإذا قرأه في طعام، أو في شراب، فاكهة أو ما أشبه ذلك، إذا قرأه، وأكله، ما أعلم فيه مانعًا مثل الشراب، لا أعلم مانعًا في ذلك، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14889/حكم-قراءة-القران-على-الطعام-والشراب-ثم-اكله-وشربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80613.mp3","categories":["الطب والتداوي"]},{"id":16192,"question":"من محافظة حمص في الجمهورية العربية السورية، المستمع (ح. م. م) رسالة وضمنها جمعًا من الأسئلة، في سؤاله الأول يقول: هل صحيح أن بعض الناس يجتمعون مع الجن، ويتكلمون معهم، وهل للجن تأثير على المؤمن؟","title":"هل يجتمع الجن بالأنس؟ وهل لهم تأثير على المؤمن؟","answer":"الجواب: قد يجتمع بعض الناس مع الجن، قد يكون له اختلاط بهم، وخدمة لهم في عبادتهم من دون الله، أو الذبح لهم، أو النذر لهم، فيخدمونه، فالمقصود أنه قد يجتمع بالجن، والجن ثقل عظيم، خلقهم الله للعبادة، قال تعالى: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] فهم مأمورون بعبادة الله وطاعته، كما أن الإنس مأمورون بذلك، وبعض الناس قد يخدمهم، ويعبدهم من دون الله؛ ليقضوا له بعض الحوائج، فيكون قد أشرك بالله، وعبد معه سواه . وقد يتراؤون لبعض الناس في بيته، أو في السفر، أو في أي مكان يبرزون للناس، ولكن الغالب أنهم يروننا، ولا نراهم، كما قال -جل وعلا-: إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لا تَرَوْنَهُمْ [الأعراف:27] وطاعتهم في المعاصي مثل طاعة الإنس محرمة، لا يجوز طاعتهم في المعاصي، وعبادتهم شرك بالله . فإذا طلبوا من الإنسي أن يضرب أحدًا، أو يأخذ مال أحد، يعطيهم مال أحد؛ فهذا من الظلم، وإذا تقرب إليهم بذلك، بالمال، أو بالذبح، أو بالدعاء؛ صار شركًا أكبر، نسأل الله العافية. وكان أهل الجاهلية يستعينون بالجن، إذا نزلوا الأودية؛ خافوا منهم، وقالوا: نعوذ بعزيز هذا الوادي من سفهاء قومه، فأنكر الله عليهم ذلك في قوله سبحانه: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6] في سورة قل أوحي إلي يقول سبحانه: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6] فلا يجوز الاستعانة بالجن، ولا دعاؤهم، ولا الاستغاثة بهم، ولا الذبح لهم، ولا النذر لهم، كل هذا من الشرك بالله. أما كونهم قد يسمع أصواتهم، أو قد يجتمع بهم، أو قد يخدمهم؛ فهذا يقع لبعض الناس، قد يقع لعباد القبور، عباد الشياطين، قد يجتمعون بهم، ويخدمونهم، كل طائفة تخدم الأخرى، نسأل الله السلامة، نعم. المقدم: جزاكم الله خيرًا، إذًا لهم تأثير على المؤمن كما يسأل أخونا؟ الجواب: نعم، قد يلتحق الجني بالإنسي فيصرعه، يدخل فيه، يشتمل عليه؛ فيكون مجنونًا بسبب ذلك، ويؤذيه بذلك، يكون ظالمًا له، وهذا موجود كثيرًا، مثلما قال ﷺ في الحديث الصحيح، يقول النبي ﷺ: إن الشيطان يجري من ابن آدم مجرى الدم قد يكون يدخل فيه، يعني: يلتبس به حتى يتكلم على لسانه، قد يكون رجلًا، قد يكون امرأة، قد يكون مسلمًا، قد يكون كافرًا، فالمسلم يكون ظالمًا متعديًا، والكافر معروف ظلمه وشره. وينبغي علاجه، وتذكيره بالله، وتحذيره من الظلم، فالمسلم قد يخرج بسهولة، يخاف الله إذا ذكر ويخرج، وبعض المسلمين من الجن قد يكون فيه ظلم، وشر كثير، لا يخرج إلا بتعب، والكافر كذلك قد لا يخرج لظلمه وكفره، ولكن مع القراءة قراءة القرآن، والتعوذات الشرعية يخرج -بإذن الله- في الغالب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14877/هل-يجتمع-الجن-بالانس-وهل-لهم-تاثير-على-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80609.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":16207,"question":"يقول: رجل يقرأ القرآن الكريم على مادة، ثم يأكلها بعد قراءة القرآن، هل هذا حرام، أم لا؟","title":"حكم قراءة القرآن على الطعام والشراب ثم أكله وشربه","answer":"الجواب: إذا قرأ في ماء، أو في طعام، وأكله لا نعلم فيه بأسًا، إذا قرأه في الماء هذا مستعمل معروف، قد قرأ النبي ﷺ في الماء لثابت بن قيس، وصبه عليه، فإذا قرأ في ماء، وشربه، أو صبه على المريض هذا من أسباب الشفاء، وإذا قرأه في طعام، أو في شراب، فاكهة أو ما أشبه ذلك، إذا قرأه، وأكله، ما أعلم فيه مانعًا مثل الشراب، لا أعلم مانعًا في ذلك، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14889/حكم-قراءة-القران-على-الطعام-والشراب-ثم-اكله-وشربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80613.mp3","categories":["الطب والتداوي"]},{"id":16209,"question":"من محافظة حمص في الجمهورية العربية السورية، المستمع (ح. م. م) رسالة وضمنها جمعًا من الأسئلة، في سؤاله الأول يقول: هل صحيح أن بعض الناس يجتمعون مع الجن، ويتكلمون معهم، وهل للجن تأثير على المؤمن؟","title":"هل يجتمع الجن بالأنس؟ وهل لهم تأثير على المؤمن؟","answer":"الجواب: قد يجتمع بعض الناس مع الجن، قد يكون له اختلاط بهم، وخدمة لهم في عبادتهم من دون الله، أو الذبح لهم، أو النذر لهم، فيخدمونه، فالمقصود أنه قد يجتمع بالجن، والجن ثقل عظيم، خلقهم الله للعبادة، قال تعالى: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] فهم مأمورون بعبادة الله وطاعته، كما أن الإنس مأمورون بذلك، وبعض الناس قد يخدمهم، ويعبدهم من دون الله؛ ليقضوا له بعض الحوائج، فيكون قد أشرك بالله، وعبد معه سواه . وقد يتراؤون لبعض الناس في بيته، أو في السفر، أو في أي مكان يبرزون للناس، ولكن الغالب أنهم يروننا، ولا نراهم، كما قال -جل وعلا-: إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لا تَرَوْنَهُمْ [الأعراف:27] وطاعتهم في المعاصي مثل طاعة الإنس محرمة، لا يجوز طاعتهم في المعاصي، وعبادتهم شرك بالله . فإذا طلبوا من الإنسي أن يضرب أحدًا، أو يأخذ مال أحد، يعطيهم مال أحد؛ فهذا من الظلم، وإذا تقرب إليهم بذلك، بالمال، أو بالذبح، أو بالدعاء؛ صار شركًا أكبر، نسأل الله العافية. وكان أهل الجاهلية يستعينون بالجن، إذا نزلوا الأودية؛ خافوا منهم، وقالوا: نعوذ بعزيز هذا الوادي من سفهاء قومه، فأنكر الله عليهم ذلك في قوله سبحانه: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6] في سورة قل أوحي إلي يقول سبحانه: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6] فلا يجوز الاستعانة بالجن، ولا دعاؤهم، ولا الاستغاثة بهم، ولا الذبح لهم، ولا النذر لهم، كل هذا من الشرك بالله. أما كونهم قد يسمع أصواتهم، أو قد يجتمع بهم، أو قد يخدمهم؛ فهذا يقع لبعض الناس، قد يقع لعباد القبور، عباد الشياطين، قد يجتمعون بهم، ويخدمونهم، كل طائفة تخدم الأخرى، نسأل الله السلامة، نعم. المقدم: جزاكم الله خيرًا، إذًا لهم تأثير على المؤمن كما يسأل أخونا؟ الجواب: نعم، قد يلتحق الجني بالإنسي فيصرعه، يدخل فيه، يشتمل عليه؛ فيكون مجنونًا بسبب ذلك، ويؤذيه بذلك، يكون ظالمًا له، وهذا موجود كثيرًا، مثلما قال ﷺ في الحديث الصحيح، يقول النبي ﷺ: إن الشيطان يجري من ابن آدم مجرى الدم قد يكون يدخل فيه، يعني: يلتبس به حتى يتكلم على لسانه، قد يكون رجلًا، قد يكون امرأة، قد يكون مسلمًا، قد يكون كافرًا، فالمسلم يكون ظالمًا متعديًا، والكافر معروف ظلمه وشره. وينبغي علاجه، وتذكيره بالله، وتحذيره من الظلم، فالمسلم قد يخرج بسهولة، يخاف الله إذا ذكر ويخرج، وبعض المسلمين من الجن قد يكون فيه ظلم، وشر كثير، لا يخرج إلا بتعب، والكافر كذلك قد لا يخرج لظلمه وكفره، ولكن مع القراءة قراءة القرآن، والتعوذات الشرعية يخرج -بإذن الله- في الغالب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14877/هل-يجتمع-الجن-بالانس-وهل-لهم-تاثير-على-المومن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_806/nour_80609.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":16251,"question":"يسأل سؤالًا ربما يكون فيه شيء من الغرابة، يقول: ما الفرق بين الجن، والشياطين؟","title":"ما الفرق بين الجن والشياطين؟","answer":"الجواب: الجن: من.. جنس الجن، هم الثقل الثاني من المخلوقات، مثل الإنس يقول الله سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] الجن: هم جنس من المخلوقات، خلقهم الله لعبادته كالإنس. والشياطين: المردة منهم، الشيطان وذرية المردة، وهكذا شياطين الإنس مثل ذلك، الشياطين يكونون من الجن، ويكونون من الإنس، فالشيطان الإنسي، والشيطان الجني داخل في الشياطين، كما قال تعالى: وَكَذَلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا شَيَاطِينَ الإِنسِ وَالْجِنِّ يُوحِي بَعْضُهُمْ إِلَى بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُورًا وَلَوْ شَاءَ رَبُّكَ مَا فَعَلُوهُ فَذَرْهُمْ وَمَا يَفْتَرُونَ [الأنعام:112]. فالمقصود: أن الشياطين يكونون من الجن والإنس، وهم المردة المتعدون لحدود الله، يقال لهم: شياطين، والشيطان الذي هو أبو الجن، هو رأسهم، وهكذا من تمرد من ذريته، وتعدى الحدود؛ هو شيطان، ومن استقام على أمر الله؛ فليس من الشياطين، بل من المؤمنين، كما قال تعالى في الجن: وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذَلِكَ كُنَّا طَرَائِقَ قِدَدًا[الجن:11] وقال أيضًا عن الجن: وَأَنَّا مِنَّا الْمُسْلِمُونَ وَمِنَّا الْقَاسِطُونَ فَمَنْ أَسْلَمَ فَأُوْلَئِكَ تَحَرَّوْا رَشَدًا ۝ وَأَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَبًا [الجن:14-15]، فهو فيهم المسلم والكافر .. فيهم المبتدع والسني.. فيهم الرافضي والسني.. فيهم الشيوعي.. فيهم المعتزلي والجهمي، مثلما في الإنس، نعم، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14958/ما-الفرق-بين-الجن-والشياطين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75204.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":16318,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من الدمام يقول: أبو أنفال، أبو أنفال يقول: أنا شاب -ولله الحمد- قائم بواجباتي نحو الله، ومحافظ على الصلوات الخمس في المسجد مع الجماعة، ولكن مشكلتي: أنني في السابق قبل توبتي قد قمت بعمل، وشم في يدي وفي يدي اليسرى، وأنا الآن أجزم أنه من أشد المحرمات، ومن أخبث الخبائث، كيف توجهونني سماحة الشيخ حتى أزيل أثر ذلك الوشم؟ جزاكم الله خيرًا، وأحسن إليكم، ولاسيما وأنني إذا حاولت إزالته بطريقة عادية يؤلمني، وجهوني جزاكم الله خيرًا.","title":"كيفية إزالة أثر الوشم","answer":"الجواب: الوشم من كبائر الذنوب: و\"قد لعن النبي ﷺ الواشمة والمستوشمة\" فالواجب عليك بذل الوسع في إزالته من طريق الأطباء المختصين، فإذا تيسر لك ذلك؛ فهذا هو الواجب عليك، أن تعرض نفسك على المختص الذي يستطيع إزالة هذا الوشم بالطريقة الممكنة التي لا يترتب عليها خطر عليك، فالأطباء عندهم في هذا البصيرة، فاعرض ذلك على المختصين، وأبشر بالخير -إن شاء الله- وسوف يزول ذلك. أما الماضي فالتوبة تجب ما قبلها، والحمد لله، التوبة كافية، لكن أثره الباقي تجتهد في إزالته بواسطة المختصين، ونسأل الله لك العون. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15010/كيفية-ازالة-اثر-الوشم","audio":"","categories":["الطب والتداوي"]},{"id":16350,"question":"تسأل سماحتكم عن الحبوب التي تمنع العذر الشرعي من أجل أن تتمكن المرأة من الصيام، أو من الحج، جزاكم الله خيرًا.","title":"حكم حبوب تأخير الدورة لأجل الصوم والحج","answer":"الجواب: لا مانع من تعاطي الحبوب في رمضان، أو في أيام الحج لمنع العادة الشهرية إذا كانت الحبوب ليس فيها مضرة، إذا كانت تعرف أنها ليس فيها مضرة عليها؛ فلا بأس أن تستعملها لمنع العادة حتى تصوم مع الناس، وتصلي مع الناس، وهكذا في الحج؛ حتى لا تتعطل، كل هذا لا بأس به -إن شاء الله- لأنه مصلحة بلا أذى. أما إن كان فيه مضرة عليها، يضر رحمها، أو يضر بدنها؛ فلا يجوز. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15044/حكم-حبوب-تاخير-الدورة-لاجل-الصوم-والحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71413.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":16509,"question":"سماحة الشيخ حفظكم الله، ما أفضل الأدعية الجامعة في القراءة على المريض؟ وأيضًا ما هي الآيات الواردة في ذلك؟","title":"الآيات والأدعية الواردة في رقية المريض","answer":"الجواب: من الأدعية الجامعة الواردة قوله ﷺ: أذهب البأس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا هذه من أجمع الدعاء، وأصح الدعاء، أذهب البأس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا ومن ذلك: باسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس، أو عين حاسد، الله يشفيك باسم الله أرقيك كما رقى جبرائيل النبي ﷺ بهذه الرقية الأخيرة، ومن ذلك: (اللهم اشفه وعافه، اللهم اشفه وعافه، نسأل الله لك الشفاء والعافية) دعاء، نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15218/الايات-والادعية-الواردة-في-رقية-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58303.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":16510,"question":"سماحة الشيخ! ما رأيكم في قراءة الإنسان على نفسه؟","title":"حكم قراءة الإنسان على نفسه","answer":"الجواب: ينفث على نفسه كما نفث النبي ﷺ على نفسه، من العلاج التام، النبي ﷺ كان يرقي نفسه عند النوم -عليه الصلاة والسلام- ولما مرض، واشتد عليه الأمر، وعجز عن ذلك؛ صارت عائشة تأخذ بيديه، وترقيه في يديه، وتمسح بيديه وجهه -عليه الصلاة والسلام- نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/15220/حكم-قراءة-الانسان-على-نفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58304.mp3","categories":["الطب والتداوي"]},{"id":16512,"question":"الرسالة التالية من إحدى الأخوات المستمعات تقول: المرسلة أم أمل، أم أمل لها قضية تقول فيها: تزوجت منذ عشر سنوات، ولم أنجب سوى طفل واحد منذ ثمان سنوات، وتوقفت عن الإنجاب بعد ذلك بدون أي سبب مني، وإنما بإرادة الله  وقد عرضت نفسي على كثير من الطبيبات؛ ولكن دون جدوى، فهل يجوز لي يا سماحة الشيخ عرض نفسي على الأطباء؟ جزاكم الله خيرًا.","title":"جواز علاج المرأة عند طبيب للضرورة","answer":"الجواب: نعم، إذا كان هناك أطباء مختصون في معرفة أمراض النساء المانعة من الحبل، ولم يوجد من يقوم مقامهم من الطبيبات؛ فلا بأس أن تعرض المرأة نفسها فيما يتعلق بالمرض الذي لم يعرفه النساء. وهكذا الرجل إذا كان به مرض لم يعرفه الأطباء من الرجال، وكان هناك طبيبات يعرفن هذا المرض، أو يرجى أن يعرفن هذا المرض؛ فلا بأس.  فالمقصود: أن التطبب عند الرجل من المرأة عند الحاجة، والتطبب من الرجل عند المرأة عند الحاجة؛ لا حرج فيه، أما إذا وجد من يكفي؛ فإن الطبيب يكون للرجال، والطبيبة تكون للنساء؛ حذرًا من الاختلاط الذي قد يضر الجميع؛ وحذرًا من الفتنة. لكن عند الضرورة يجوز أن يطب الرجل المرأة، ويجوز للمرأة أن تطب الرجل عند الضرورة الداعية إلى ذلك، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15223/جواز-علاج-المراة-عند-طبيب-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75609.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":16607,"question":"المستمع محمد أبو نوح بعث برسالة يعرض فيها قضية المرأة، والطبيب مرة أخرى، وأخونا محمد أبو نوح من الجزائر، ومقيم في مكة المكرمة فما هو توجيه سماحتكم حول هذا الموضوع؟الشيخ: أي موضوع؟المقدم: موضوع المرأة والطبيب.","title":"حكم تداوي المرأة عند طبيب","answer":"الجواب: المرأة يعالجها امرأة، وأما الرجل يعالجه الرجل، فإذا اضطرت المرأة للطبيب فلا حرج، ما وجدت طبيبة لا بأس أن يعالجها الطبيب، وهكذا الرجل إذا اضطر أن تعالجه المرأة لعدم وجود الطبيب الذي يعرف مرضه، لا بأس بذلك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. المقدم: جزاكم الله خيرًا، حتى وإن كان الأمر أمر ولادة، وما أشبه ذلك؟ الشيخ: عند الضرورة لا بأس، عند الضرورة إذا ما تيسر من يولدها، وخافت على نفسها، نعم. المقدم: نعم جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15338/حكم-تداوي-المراة-عند-طبيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81718.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":16790,"question":"تقول عن نفسها: أنا مريضة، وشخّص الأطباء حالتي، وهي فتحة قلبية، وزوجي يريد أطفالًا، لكن خوفًا على صحتي بدأت أستعمل أقراص منع الحمل، فهل أنا على صواب، أم ماذا؟ جزاكم الله خيرًا.","title":"حكم استعمال حبوب منع الحمل بغير إذن الزوج","answer":"الجواب: هذا يحتاج إلى مراجعة أهل الخبرة من الأطباء، فإذا كان عليك مضرة، وخطر من ترك هذه الأقراص؛ فلا حرج، وإن كانت هذه الأقراص ليست بضرورية، ولم يرض زوجك بها؛ فاتركيها. والخلاصة: أن هذا يرجع إلى سؤال أهل الخبرة من الأطباء؛ فإن كنت في ضرورة إلى هذا؛ فلا بأس، وإن كان هناك غنية عنها، فالواجب تركها إلا أن يأذن الزوج في استعمالها، نسأل الله لنا ولك العافية. المقدم: جزاكم الله خيرًا، مع ملاحظة -سماحة الشيخ- أن الزوج هو ذلكم المسؤول عنه في السؤال الأول؟ الشيخ: وسبق ما دام هو الزوج المذكور، سبق أنك لا يجوز أن تعتبريه زوجًا ما دام بهذه الحالة، ولك أن تستعملي ما ينفعك، ويخفف الضرر عنك، وإن لم يرض؛ لأنه ليس بزوج في الحقيقة، ما دام يدع الصلاة، أو يتعاطى شيئًا آخر مما يوجب كفره من سب الدين، أو تعاطي أشياء أخرى من أنواع الكفر، أما شرب المسكر إذا لم يستحله، ولكن فعله، وهو يعلم أنه حرام، وفعله طاعة لهواه؛ فإنه يكون بذلك عاصيًا وفاسقًا، ولا يكون كافرًا، ولكن لك -كما تقدم- طلب الطلاق، أما إن استحله يرى أنه حلال، وأنه لا بأس به؛ يكون كافرًا بذلك نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15547/حكم-استعمال-حبوب-منع-الحمل-بغير-اذن-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76302.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":16827,"question":"أحسن الله إليكم، سماحة الشيخ: العلاج بالزيت، وزيت الزيتون، كيف يكون ذلك؟","title":"كيفية العلاج بزيت الزيتون","answer":"الجواب: الزيت مبارك، والعلاج به من أسباب الشفاء، لكن تفصيل ذلك عند الأطباء الذين يستعملونه، وهو مبارك، شجرة مباركة، التداوي به مبارك، وفيه خير كثير، والعسل فيه خير كثير، وشرب زمزم كذلك، يقول النبي ﷺ: الشفاء في ثلاث: شرطة محجم، وشربة عسل، وكية نار هذه من أسباب الشفاء، لكن كيفية العمل هذا يحتاج إلى مراجعة العارفين بذلك، والذين قد تدربوا على هذا الشيء، وجربوه، نعم. المقدم: محلات العطارة يا سماحة الشيخ التي تبيع العسل، وتبيع هذا الزيت الزيتون، وكذلك ماء زمزم، ما رأيكم في ذلك للعلاج؟ الجواب: لا حرج إذا شرى منهم، لا حرج، نعم.","link":"https://binbaz.org.sa/fatwas/15576/كيفية-العلاج-بزيت-الزيتون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58602.mp3","categories":["الطب والتداوي"]},{"id":16828,"question":"الشخص الذي يشتكي من ضيق في الصدر هل يقرأ عليه؟","title":"هل يقرأ على من يشعر بضيق الصدر؟","answer":"الجواب: ينبغي له أن يكثر من ذكر الله، ومن قراءة القرآن، وإذا قرئ عليه لا بأس، لكن الأفضل له أن يكثر من قراءة القرآن، ومن ذكر الله؛ لأن هذا يشرح الصدر أَلا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ [الرعد:28] يكثر من قول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، يحيي ويميت، وهو على كل شيء قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله، وبحمده، سبحان الله العظيم، يكثر من قراءة القرآن إذا كان يحفظ، أو من المفصل إذا كان ما يحفظ إلا القليل، أو يردد السورة التي يحفظها، كل هذا من أسباب انشراح الصدر، مع دعاء الرب، يقول: اللهم اشرح لي صدري، اللهم يسر لي أمري، اللهم اشرح لي صدري، اللهم أزل عني كل بأس، اللهم اشفني من كل سوء، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/15582/هل-يقرا-على-من-يشعر-بضيق-الصدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58603.mp3","categories":["الطب والتداوي"]},{"id":16880,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول في أولها: أنا الشاب المسلم صلاح الدين الشبيب من الجمهورية العربية السورية، أخونا له جمع من الأسئلة من بينها سؤال يقول: هل يستطيع الساحر الاتصال بالشياطين كما يزعم فعلًا، وبالتالي يستطيع أن يغير ما يريده الشخص المسلم الواعي، والذي يحفظ قدرًا كبيرًا من القرآن، وذلك بواسطة هؤلاء الشياطين، وإن كان ذلك ممكن، فماذا يترتب على الشخص أن يفعل إذا ابتلي بالسحر؟ أفيدونا جزاكم الله خيرًا.","title":"طرقة الوقاية من السحر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فالسحر بينه الله -جل وعلا- في كتابه العظيم، وهكذا الرسول ﷺ أنه موجود، وأن السحرة موجودون، وأن الشياطين هم الأساتذة، هم الذين يعلمونهم السحر، الشياطين، شياطين الجن هم الذين يعلمون شياطين الإنس السحر، والسحر يكون بالرقى الشيطانية، والتعوذات الشيطانية، والعقد والنفث، كما قال تعالى: وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ [الفلق:4] يعني: السواحر اللاتي ينفثن في العقد بكلمات ضالة خاطئة، يردن بها إيذاء المسحور. ويقع بالتخييل، كما قال تعالى: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66] فيخيلون للإنسان أن الحبل حية، والعصا حية، والكلب نوع آخر، والقط نوع آخر، إلى غير ذلك، يسميه العامة التذمير، يعني يذمر على العيون، كما قال -جل وعلا-: فَلَمَّا أَلْقَوْا سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَاءُوا بِسِحْرٍ عَظِيمٍ [الأعراف:116] وسحروا أعين الناس، أي: لبسوا عليهم حتى صار الإنسان ينظر الشيء على غير وجهه، ويظنه غير المعروف؛ بسبب ما وقع من التلبيس الذي شوش على العين، حتى ظن الناس أن الحبال، والعصي بسبب سحرة فرعون ظنوا أنها حيات، واعتقدوا أنها حيات. والساحر يتلقى من الشياطين، قال تعالى: وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ [البقرة:102]. هكذا بين  ثم قال: وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ [البقرة:102] يعني: ويعلمونهم ما أنزل على الملكين بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ [البقرة:102] يعني: الملكين هاروت وماروت حَتَّى يَقُولا [البقرة:102] للمتعلم، يقولا للمتعلم،إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102]، يعني: أن الملكين مبتلى بهما الناس، فلا تكفر بتعاطي السحر، فدل ذلك على أن تعاطي السحر كفر بعد الإيمان، وردة بعد الإسلام إذا كان مسلمًا؛ لأنه لا يتوصل إليه إلا بعبادة الشياطين، التقرب إليهم بالذبح، والنذر، والاستغاثة، والسجود لهم، ونحو ذلك. فيكون الساحر بهذا كافرًا مرتدًا؛ لكونه يتعاطى مع الشياطين ما هو من حق الله من العبادة، ولهذا قال -جل وعلا-: وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا [البقرة:102] أي: ينصحاه حتى يقولا له: إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا [البقرة:102] أي: من هاروت وماروت. مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ [البقرة:102] يعني: يتعلمون من الملكين أشياء من السحر، تلبس على الزوج والزوجة، حتى يعتقد الزوج أن المرأة غير امرأته، شانت حالها، وتغيرت حالها، حتى يبغضها، ويطلقها، وهكذا المرأة يلبس عليها ... عليها، ويسحر عينها بالنسبة إلى زوجها، حتى تتخيل أنه غير زوجها، وأن صورته تغيرت، وأن حاله تغيرت؛ فتنكر، فتنكره، وتطلب الفراق.  قال تعالى: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102] أي: لا يقع السحر إلا بإذن الله، يعني: بإذن الله الكوني القدري، لا الشرعي؛ لأن الله سبحانه ما أذن فيه شرعًا، بل حرمه، وحذر منه، ولكنه يقع بإذنه الكوني القدري، كل شيء بقدره، الكفر والإيمان، والسحر، والقتل، والأكل والشرب، والموت، والحياة كلها بقدر، كلها بإذن الله القدري، ولهذا قال سبحانه: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ. ثم قال : وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ [البقرة:102] دل على أن السحر يضر، ولا ينفع، والمضرة على الساحر، وعلى المسحور جميعًا، وأن شره عظيم، وقدره الله لحكمة بالغة، وابتلاء وامتحان. ثم قال سبحانه: وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ [البقرة:102] يعني: اعتاظه مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ  يعني: من حظ، ولا نصيب، وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ يعني: باعوا، ما شرى معنى باع وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ يعني: باعوا أنفسهم على الشيطان لَوْ كَانُوا يَعْلَمُونَ [البقرة:102] ثم قال سبحانه: وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:103]. فدل على أن السحر ضد الإيمان والتقوى، وضد الآخرة، فوجب على كل إنسان أن يحذره، على كل مسلم أن يحذر السحر، وأن يتباعد عنه، وعن أسبابه، وعن أهله، وفي إمكان المؤمن أن يتعوذ بالله من شر السحرة، ويبتعد عنهم بالاعتصام بحبل الله، والاستقامة على دين الله، وعدم الركون لهم، وعدم التعلم منهم، ويتحرز من ذلك بالأشياء المشروعة: مثل آية الكرسي عند النوم، وبعد كل صلاة، ومثل: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] وقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] وقُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1] بعد كل صلاة، وبعد المغرب، والفجر ثلاث مرات، وعند النوم ثلاث مرات، كل هذا من أسباب السلامة من السحر. وهكذا كونه يقول: أعوذ بكلمات الله التامات من شر ما خلق هذا أيضًا من الأسباب، من أسباب العافية، فالمؤمن يتحرز من كل شر بما شرعه الله، ومن ذلك السحر؛ فإنه شر عظيم، وخطره كبير. فالواجب على المؤمن أن يحذر كل شر، وأن يتعاطى الأسباب التي جعلها الله أسبابًا للسلامة، ويعلم أن الأمر بيد الله  فلا يضرك ساحر، ولا غيره إلا بإذن الله، فالجأ إلى الله، واستقم على دينه، والتزم التعوذات الشرعية، والأسباب الشرعية، وبه تسلم -بإذن الله- ولا يضرك السحرة، ولا الشياطين. ومن أسباب السلامة: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات، صباحًا، ومساءً، باسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء، وهو السميع العليم ثلاث مرات، صباحًا، ومساءً، هذه من أسباب السلامة من كل شر، أعيدها: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات، صباحًا ومساء، من أسباب العافية من كل سوء.  جاء رجل إلى النبي ﷺ فقال: لدغتني عقرب البارحة، فقال: أما إنك لو قلت: أعوذ بكلمات الله التامات من شر ما خلق لم تضرك وقال ﷺ: من نزل منزلًا، فقال: أعوذ بكلمات الله التامات من شر ما خلق؛ لم يضره شيء حتى يرتحل من منزله ذلك وقال ﷺ: من قال: باسم الله الذي لا يضر مع اسمه شيء، في الأرض، ولا في السماء، وهو السميع العليم، ثلاث مرات صباحًا؛ لا يضره شيء حتى يمسي، وإن قالها مساءً؛ لم يضره شيء حتى يصبح.  هذه نعمة من الله  فعليك يا عبد الله! أن تجتهد في التعوذات الشرعية، والأسباب المرعية، وبذلك تسلم من شر أعدائك، ومكائد أعدائك من الشياطين، ومن السحرة، ومن غيرهم، والله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا خُذُوا حِذْرَكُمْ [النساء:71] فأنت مأمور بأخذ الحذر من كل سوء، مما يضرك في الدنيا، ومما يضرك في الآخرة، بالتحرزات الشرعية، والأسباب المرعية، في جميع الأحوال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15635/طرقة-الوقاية-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_825/nour_82501.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":16965,"question":"هل العمليات الطبية لتجميل جزء مشوه في الإنسان، هل يعتبر هذا تغيير في خلق الله؟ أم أنه محرم؟ أم أنه جائز؟ جزاكم الله خيرًا.","title":"حكم إجراء عمليات التجميل لمعالجة التشوهات","answer":"الجواب: لا حرج في ذلك، لو كان في يده عيب، أو سواد، أو في وجهه، أو في أنفه، أو في شفته، وأصلح ذلك لا حرج في ذلك، الحمد لله، الرب -جل وعلا- أمر العباد بأن يعملوا ما فيه خيرهم وصلاحهم، فإذا فعل ما ينفعه، وما يسره؛ فهو داخل في الحديث الصحيح: ما أنزل الله داءً إلا أنزل له شفاء، علمه من علمه، وجهله من جهله فالحمد لله عباد الله تداووا، ولا تداووا بالحرام فإذا كان فيه سواد في وجهه، أو عروق تؤذيه، أو ثآليل، أو أشياء نكت تؤذيه؛ فأزالها فلا بأس بذلك، أو في يدهن أو في رجله، أو في رأسه، أو في غير ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15750/حكم-اجراء-عمليات-التجميل-لمعالجة-التشوهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_766/nour_76602.mp3","categories":["الطب والتداوي"]},{"id":17060,"question":"تسأل سماحتكم عن حكم مراجعة الطبيب، ولا سيما طبيب الأسنان، إذ إنها تقول: إنها ذهبت ذات مرة، ولم تجد إلا رجلًا، لكن كانت الممرضة حاضرة -كما تقول- فما هو توجيه سماحتكم؟ جزاكم الله خيرًا.","title":"حكم علاج المرأة عند الطبيب بوجود الممرضة","answer":"الجواب: إن تيسر طبيبة فالواجب العلاج عند الطبيبة، فإن لم يتيسر جاز عند الطبيب، لكن من دون خلوة يكون معها زوجها، أو أخوها، أو امرأة أخرى؛ لأن الخلوة لا تجوز، فالخلوة بالطبيب، أو بغير الطبيب لا تجوز، يقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فليس للمرأة أن تخلو بأخي زوجها، أو عمه، أو بجار من جيرانها، أو بابن عمها، أو بخادمها، لا، لا بد أن يكون .. وجود ثالث، أو أكثر مع عدم الريبة، والطبيب كذلك لا بد أن يكون معها زوجها، أو أخوها، أو عمها، أو امرأة أخرى ممرضة، أو غيرها، ليس لها أن تخلو بالطبيب. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15852/حكم-علاج-المراة-عند-الطبيب-بوجود-الممرضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_721/nour_72106.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":17168,"question":"ماذا أيضًا سماحة الشيخ عن استعمال صفار البيض لشعور النساء، هل يكون هذا مباحًا، أو محرمًا؟","title":"حكم استعمال صفار البيض لشعور النساء","answer":"الجواب: إذا كان فيه مصلحة لا بأس، إذا كان فيه مصلحة للشعر، صفار البيض، أو بياض البيض، أو غيره مما أباح الله من الحنطة، أو الشعير، أو الذرة، أو الأدهان المباحة، لا بأس. نعم، الأصل الإباحة، كونه للأكل ما يمنع التداوي بها. نعم. المقدم: ما شاء الله، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/15987/حكم-استعمال-صفار-البيض-لشعور-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76716.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":17182,"question":"هذا سائل للبرنامج سماحة الشيخ أرسل بسؤالٍ يستفسر فيه، ويقول: هل يجوز في الرقية أن يقرأ المسلم القرآن الكريم، وبعض الأدعية النبوية على الماء، أو الزيت، ويقوم المريض بشرب ذلك الماء، والاغتسال به؟ وإذا كان لا يجوز، فما الرقية الشرعية، والشروط التي يجب أن تتوفر في الرقية، ويجوز أن يستعملها المسلم بعد ذلك؟","title":"حكم الرقية على ماء وشربه والاغتسال به","answer":"الجواب: لا حرج في الرقية في الماء، ثم يشرب مثل المريض، أو يغتسل به، كل هذا لا بأس به، الرقية تكون على المريض بالنفث عليه، وتكون في ماء يشربه المريض، أو يتروش به، كل هذا لا بأس به، وقد ثبت عن النبي ﷺ أنه: رقى لثابت بن قيس بن شماس في ماء، ثم صبه عليه. فإذا رقى الإنسان أخاه في ماء، ثم شرب منه، أو صبه عليه يرجى فيه العافية والشفاء، وإذا قرأ لنفسه على العضو المريض، يده، أو رجله، أو صدره، ونفث عليه، ودعا له بالشفاء؛ فهذا كله حسن. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16000/حكم-الرقية-على-ماء-وشربه-والاغتسال-به","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59010.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":17220,"question":"أيضًا كثر الحديث عن الحبة السوداء، ما هو رأي سماحة الشيخ؟","title":"فائدة الحبة السوداء","answer":"الجواب: الحبة السوداء طيبة، قال فيها النبي ﷺ: إنها شفاء من كل داء ولكن ينبغي لمن يعالج بها أن يستأنس بأراء الأطباء العارفين بها من ... كيفية العلاج بها، قلة أو كثرة، وأوقات العلاج بها، حتى يستفاد منها على الوجه الذي يعرفه الأطباء، وإلا فهي طيبة مثل ما قال فيها النبي ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16046/فاىدة-الحبة-السوداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72316.mp3","categories":["الطب والتداوي"]},{"id":17315,"question":"يقول: هل ورد عن الرسول ﷺ على أن الماء المقروء فيه بالقرآن يشفي وفيه علاج؟ وهل شربه ليس من البدع؟ أفيدونا جزاكم الله خيرًا.","title":"جواز التداوي بالماء المقروء فيه قرآن","answer":"الجواب: ثبت في سنن أبي داود -رحمه الله- عن النبي ﷺ أنه قرأ في ماء لثابت بن قيس بن شماس، وصبه عليه، فالقراءة في الماء من العلاج.. من أنواع العلاج، والقراءة على المريض من أنواع العلاج، كل هذا جاءت به السنة، وهو من أسباب الشفاء والعافية، وهكذا كتابة آيات كريمات في قرطاس، أو صحن نظيف بالزعفران، ثم يغسل، ويشرب هو أيضًا من العلاج، فعله كثير من السلف -رحمة الله عليهم- إذا كان القارئ، والكاتب من المعروفين بالخير والاستقامة فهذا من العلاج كله، ومن باب الطب، من باب العلاج. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16166/جواز-التداوي-بالماء-المقروء-فيه-قران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_833/nour_83307.mp3","categories":["الطب والتداوي"]},{"id":17328,"question":"السائلة من جمهورية مصر العربية، ومقيمة بالدمام تقول: نويت الإحرام من الميقات، ثم بعد ذلك.. هذه المرأة نوت الإحرام من الميقات، ثم بعد ذلك نزل عليها الحيض قبل الوقوف بعرفة، ثم طهرت في اليوم الحادي عشر، وسعت، وطافت بدون إعادة للإحرام أي: أنها لم تذهب مرة أخرى للميقات لتجدد إحرامها بعد أن طهرت، فهل فعلها صحيح؟","title":"حكم من أتاها الحيض بعد الإحرام","answer":"الجواب: نعم فعلها صحيح، وليس هناك حاجة للتجديد، فهي أحرمت من الميقات، ثم أصابها الحيض، تبقى على إحرامها، وتفعل أفعال الحج ما عدا الطواف، والسعي يؤجل، فتقف مع الناس بعرفة، وفي مزدلفة، وترمي الجمار، وتقص من رأسها، وتحل، فإذا طهرت؛ طافت، وسعت والحمد لله، وليس عليها أن تعيد الإحرام، إحرامها من الميقات كافٍ، والحيض لا يبطل الإحرام، الإحرام باقٍ، ولكن يمنع من الطواف. وهكذا النفاس لو ولدت في عرفة، أو بعد عرفة؛ تفعل أفعال الحج كلها، إلا الطواف، والسعي تؤجل حتى تطهر. نعم.  المقدم: سماحة الشيخ! حتى ولو لم تكن قد اشترطت؟ الشيخ: نعم؟ المقدم: حتى ولو لم تكن قد اشترطت، تقول: وهل إن اشترطت عند نيتها للإحرام، ثم جاءتها الحيضة يلزمها إعادة الإحرام بعد الطهر؟ الشيخ: إذا كانت شرطت لها الحل لها التحلل إذا كانت اشترطت، قالت: محلي حيث حبستني .... مقصودها من الحيض يعني: إذا أصابها الحيض تحل، فهذا لها الحل، أما إذا ما قصدها هذا القصد تخاف من أن يصيبها مرض، أو نحوه، فالحيض ليس بمانع، الحيض، حجت عائشة، وأصابها الحيض قبل دخول مكة، وأمرها النبي ﷺ أن تفعل ما يفعل الحجاج إلا الطواف. فالمقصود: أنها إذا قالت: محلي حيث حبستني عند الإحرام، قالت: إن حبسني حابس فمحلي حيث حبستني، هذا إذا منعها مرض، أو منعها عدو؛ لها أن تحل، أما الحيض لا يمنعها، لكن لو كانت تقصد الحيض جاءت للعمرة مثلًا، ومعها رفاق، فأحرمت بالعمرة، وقالت: إن حبسني حابس، ومقصودها حتى الحيض إذا حبسها حتى تحل، وترجع مع أصحابها، فهي على نيتها، أما الحيض ما يمنع الحج، ولو قالت: إن حبسني حابس، الحيض تمشي تمضي في حجها، وإذا طهرت تطوف، وتسعى، والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16169/حكم-من-اتاها-الحيض-بعد-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76907.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":17333,"question":"السائلة من جمهورية مصر العربية، ومقيمة بالدمام تقول: نويت الإحرام من الميقات، ثم بعد ذلك.. هذه المرأة نوت الإحرام من الميقات، ثم بعد ذلك نزل عليها الحيض قبل الوقوف بعرفة، ثم طهرت في اليوم الحادي عشر، وسعت، وطافت بدون إعادة للإحرام أي: أنها لم تذهب مرة أخرى للميقات لتجدد إحرامها بعد أن طهرت، فهل فعلها صحيح؟","title":"حكم من أتاها الحيض بعد الإحرام","answer":"الجواب: نعم فعلها صحيح، وليس هناك حاجة للتجديد، فهي أحرمت من الميقات، ثم أصابها الحيض، تبقى على إحرامها، وتفعل أفعال الحج ما عدا الطواف، والسعي يؤجل، فتقف مع الناس بعرفة، وفي مزدلفة، وترمي الجمار، وتقص من رأسها، وتحل، فإذا طهرت؛ طافت، وسعت والحمد لله، وليس عليها أن تعيد الإحرام، إحرامها من الميقات كافٍ، والحيض لا يبطل الإحرام، الإحرام باقٍ، ولكن يمنع من الطواف. وهكذا النفاس لو ولدت في عرفة، أو بعد عرفة؛ تفعل أفعال الحج كلها، إلا الطواف، والسعي تؤجل حتى تطهر. نعم.  المقدم: سماحة الشيخ! حتى ولو لم تكن قد اشترطت؟ الشيخ: نعم؟ المقدم: حتى ولو لم تكن قد اشترطت، تقول: وهل إن اشترطت عند نيتها للإحرام، ثم جاءتها الحيضة يلزمها إعادة الإحرام بعد الطهر؟ الشيخ: إذا كانت شرطت لها الحل لها التحلل إذا كانت اشترطت، قالت: محلي حيث حبستني .... مقصودها من الحيض يعني: إذا أصابها الحيض تحل، فهذا لها الحل، أما إذا ما قصدها هذا القصد تخاف من أن يصيبها مرض، أو نحوه، فالحيض ليس بمانع، الحيض، حجت عائشة، وأصابها الحيض قبل دخول مكة، وأمرها النبي ﷺ أن تفعل ما يفعل الحجاج إلا الطواف. فالمقصود: أنها إذا قالت: محلي حيث حبستني عند الإحرام، قالت: إن حبسني حابس فمحلي حيث حبستني، هذا إذا منعها مرض، أو منعها عدو؛ لها أن تحل، أما الحيض لا يمنعها، لكن لو كانت تقصد الحيض جاءت للعمرة مثلًا، ومعها رفاق، فأحرمت بالعمرة، وقالت: إن حبسني حابس، ومقصودها حتى الحيض إذا حبسها حتى تحل، وترجع مع أصحابها، فهي على نيتها، أما الحيض ما يمنع الحج، ولو قالت: إن حبسني حابس، الحيض تمشي تمضي في حجها، وإذا طهرت تطوف، وتسعى، والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16169/حكم-من-اتاها-الحيض-بعد-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76907.mp3","categories":["الإحرام","الحيض والنفاس","الطب والتداوي","قضايا المرأة"]},{"id":17382,"question":"في آخر أسئلة هذه السائلة من الرياض تقول: سماحة الشيخ جاء إلى منزلنا رجل لمعالجة إحدى قريباتي، وذلك بأن يقرأ عليها آيات من القرآن الكريم، وعندما دخلت لأستمع فقط لقراءته، وأنا ألبس الحجاب الشرعي، طلب أخي من الشيخ أن يقرأ علي، مع العلم بأنني لم أكن أريد ذلك، ولكنه قرأ علي، ووضع يده على أنحاء متفرقة من جسدي، مثل الرأس، والأيدي، وأعلى الساق، ولكن من وراء الحجاب، وأعطاني بعض الأوراق التي كتب عليها آيات من القرآن الكريم، وطلب مني التبخر بها، و هل هذا العمل مشروع؟ وهل يجوز؟ وهل علي إثم في ذلك مأجورين؟","title":"حكم تداوي المرأة بالقرآن عند رجل","answer":"الجواب: إذا قرأ على المرأة، ونفث عليها من القرآن، أو قرأ على الرجل فهذا مشروع، أو في ماء، ثم تشرب منه، أو تتروش به، أو كتب لها قرآنًا بزعفران ونحوه، وغسلها، وشربته فلا بأس، لكن لا يضع يده على شيء من جسدها، لحمها؛ لأنها عورة، ولكن من دون ذلك، يقرأ على محل الألم.. محل اليد.. محل الرأس.. محل الصدر.. يقرأ محل الألم من غير لمس. وإذا تيسر أن يكون الراقي امرأة فهذا أولى، وأحسن، المرأة للمرأة، والرجل للرجل، ولكن إذا دعت الحاجة إلى الرجل يقرأ من غير مس، وأما كونه يكتب ذلك في ورقة، وتغسل بالزعفران مثلًا فلا بأس أيضًا، أو في صحن، ونحوه، يكتب الآيات بالزعفران، ثم يغسل، ويشرب، كل هذا لا بأس به. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16237/حكم-تداوي-المراة-بالقران-عند-رجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77012.mp3","categories":["الطب والتداوي"]},{"id":17408,"question":"سماحة الشيخ! يستفسر الكثير الحقيقة من الناس عن كيفية الرقية الشرعية؟","title":"كيفية الرقية الشرعية","answer":"الجواب: الرقية الشرعية هي الرقية بالآيات، والدعوات الطيبة هذه ... الشرعية، الرقية بالقرآن، أو بالدعوات الطيبة، يرقي بالفاتحة، بآية الكرسي، بغيرها من الآيات: قل هو الله أحد المعوذتين بغيرها، هذه الرقية الشرعية، أو بالدعاء يدعو له .... أذهب البأس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا باسم الله أرقيك، من كل شيء يؤذيك، ومن شر كل نفس، أو عين حاسد الله يشفيك، باسم الله أرقيك.  أو اللهم اشفه وعافه، اللهم أنزل عليه الشفاء، اللهم أبرئه من مرضه.. وما أشبه ذلك الدعوات الطيبة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16267/كيفية-الرقية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77108.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":17451,"question":"هذا السائل أحمد الرفاعي له مجموعة من الأسئلة يقول: كثر في هذه الأيام التحدث عن السحر -أعاذنا الله منه وإياكم- فما هي الوقاية الصحيحة من القرآن والسنة حول هذا الأمر؟ جزاكم الله خيرًا سماحة الشيخ.","title":"كيفية الوقاية من السحر","answer":"الجواب: السحر يقع، معروف، يعني: لا شك أنه قد يقع من بعض الناس، والساحر مشرك يجب قتله إذا عرف -نسأل الله العافية- وقد أمر عمر  أمراءه أن يقتلوا السحرة، يروى عن النبي ﷺ أنه قال: حد الساحر ضربه بالسيف؛ لأنه كافر، ويدعو إلى الكفر، وأما التوقي، فالتوقي بالتعوذ بكلمات الله التامات من شر ما خلق، كونه يتعوذ صباحًا ومساء بكلمات الله التامات من شر ما خلق ثلاث مرات، باسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء وهو السميع العليم ثلاث مرات صباحًا ومساء كما جاءت الأحاديث بذلك، من أتى بهذا؛ كفاه الله شر كل شيء، أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات صباحًا ومساء: باسم الله الذي لا يضر مع اسمه شيء في الأرض، ولا في السماء، وهو السميع العليم ثلاث مرات.  كذلك قراءة قل هو الله أحد والمعوذتين صباحًا ومساء ثلاث مرات من أسباب السلامة من السحر، وغيره ثلاث مرات قل هو الله أحد [الإخلاص: 1] قل أعوذ برب الفلق [الفلق: 1] قل أعوذ برب الناس [الناس: 1] صباحًا ومساء. وهكذا عند النوم يقرأها ثلاث مرات، آية الكرسي عند النوم من أسباب السلامة من السحر والشيطان، قراءتها بعد كل صلاة، كل هذا من أسباب العافية والسلامة، نسأل الله السلامة والعافية، نعم. المقدم: اللهم آمين، شكر الله لكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16320/كيفية-الوقاية-من-السحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77208.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":17485,"question":"يقول هذا السائل من سوريا رمز لاسمه بـ (ح. م. س): أستفسر في سؤالي عن الآتي: هل يجوز للمؤمن أن يذهب إلى العراف أو إلى عراف من أجل مشكلة ما اشتكى منها، علمًا بأن هذا العراف يفتتح بالقرآن الكريم، فأريد منكم التوجيه مأجورين؟","title":"حكم إتيان العرافين وسؤالهم","answer":"الشيخ: العرافون: هم الذين يدعون علم المغيبات وعلم الحوادث بطرق غير شرعية، هؤلاء لا يؤتون يقول النبي ﷺ: من أتى عرافًا فسأله عن شيء لم تقبل له صلاة أربعين ليلة رواه مسلم في الصحيح، ويقول ﷺ: من أتى عرافًا أو كاهنًا فصدقه بما يقول فقد كفر بما أنزل على محمد عليه الصلاة والسلام، فلا يجوز إتيان العرافين، ولا الكهنة، ولا المنجمين، ولا السحرة، ولا يجوز سؤالهم، ولا تصديقهم، بل يجب الحذر منهم، والإنكار عليهم، ورفع أمرهم إلى الجهات المسئولة حتى يعاقبوا بما يستحقون. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16394/حكم-اتيان-العرافين-وسوالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_773/nour_77317.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":17512,"question":"من المستمع عجينا مشير رسالة وضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: ما حكم كتابة الآيات القرآنية على اللوح ومحوها وشرابها من أجل الاستشفاء، هل ورد هذا؟ وهل هو طريقة صحيحة؟ جزاكم الله خيرًا.","title":"حكم كتابة الآيات القرآنية ثم محوها للاستشفاء؟","answer":"الجواب: نعم، فعل هذا بعض السلف وذكره ابن القيم رحمه الله وشيخ الإسلام ابن تيمية وجماعة، لا حرج في ذلك، كونه يكتب آيات في لوح أو في صحن أو في قرطاس بالزعفران مثلًا ثم يغسله ويشربه أو يرشه على بدنه لا حرج في ذلك، قد فعله جمع من السلف، وذكر ابن القيم رحمه الله وجماعة أنه نافع بإذن الله.  وله أن يقرأ في الماء.. ينفث في الماء ثم يشرب منه ويغتسل به، فعله النبي ﷺ مع ثابت بن قيس بن شماس، فإذا قرأ في الماء الفاتحة وآية الكرسي و قل يا أيها الكافرون و قل هو الله أحد و قل أعوذ برب الفلق و قل أعوذ برب الناس ، أو بعض ذلك ودعا بالدعوات المناسبة ثم شرب من الماء واغتسل بالباقي هذا مجرب للشفاء. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16448/حكم-كتابة-الايات-القرانية-ثم-محوها-للاستشفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83707.mp3","categories":["الطب والتداوي","القرآن وعلومه"]},{"id":17706,"question":"هذا السائل أبو عبد الله يقول: القرآن فيه شفاء للناس ورحمة نرجو أن تذكروا الآيات التي يشرع قراءتها على المريض وعدد المرات وكيفية النفث جزاكم الله خيرًا؛ لأن عندنا شخص مصاب بمرض ونريد أن نقرأ عليه؟","title":"الآيات والسور التي يرقى بها المريض","answer":"الجواب: كل القرآن شفاء من أوله إلى آخره، وإذا قرأ الفاتحة فهي أعظم سورة في القرآن ... كررها كما قرأها الصحابة على اللديغ لما مروا عليه في بعض أحياء العرب قرأ عليه بعض الصحابة بسورة الفاتحة وكررها فشفاه الله، فإذا قرأ سورة الفاتحة وقرأ معها آية الكرسي أو بعض الآيات الأخرى كله طيب، وإذا قرأ قل هو الله أحد وقل أعوذ برب الفلق وقل أعوذ برب الناس ثلاث مرات كان حسنًا أيضًا من أسباب الشفاء، وكل القرآن شفاء إذا قرأ منه ما يسر الله من البقرة.. من آل عمران.. من النساء.. من المائدة، من بقية القرآن كله شفاء، كما قال الله جل وعلا: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ[فصلت:44]، وقال سبحانه: وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِينَ[الإسراء:82] يعني: كله شفاء، فإذا تحرى بعض الآيات وقرأها كله طيب، ولكن من أهم ما يقرأ الفاتحة وآية الكرسي، وقل هو الله أحد، وسورة المعوذتين هذه من أهم ما يقرأ على المريض. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16666/الايات-والسور-التي-يرقى-بها-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_776/nour_77618.mp3","categories":["الطب والتداوي","الأدعية والأذكار","السحر والكهانة"]},{"id":17745,"question":"هذه مستمعة رمزت لاسمها بـ (أ. ج. ط) من حماة في سوريا، تذكر بأنها فتاة عمرها خمسة وعشرين سنة، وتقول: تعقدت من حياتي حيث أن لي وجه مشوه بسبب حادث سيارة في صغري ويستحقرني جميع من يراني ففكرت بإجراء عملية تجميل، فهل علي إثم أو كفارة يا سماحة الشيخ؟","title":"حكم عملية التجميل إذا كان الوجه مشوهًا","answer":"الجواب: لا حرج في ذلك، إذا كان في الوجه تشويه سواد أو أشباه ذلك فلا بأس بالتجميل بعلاج هذه الأشياء حتى تزول هذه الأشياء التي تشوه الوجه، وهذا لا حرج فيه من باب التداوي، ومن باب الأخذ بالأسباب، كما لو كان فيها أورام أو أشياء أخرى مما يؤذي تعالج في وجهها، وفي رأسها، وفي جميع بدنها.\nالمقصود أن التشويه الواقع في الوجه من أجل حادث سيارات أو غيرها لا بأس بعلاجه، بل يستحب علاجه حتى يزول التشويه، يقول النبي ﷺ في الحديث الصحيح: احرص على ما ينفعك، واستعن بالله جمع بين الأمرين احرص على ما ينفعك، واستعن بالله رواه مسلم في الصحيح، أول الحديث: المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وفي كل خير، ثم قال ﷺ: احرص على ما ينفعك واستعن بالله ولا تعجزن، وإن أصابك شيء فلا تقل: لو أني فعلت لكان كذا وكذا، ولكن قل: قدر الله وما شاء فعل، فإن لو تفتح عمل الشيطان. فأمر بالأخذ بالأسباب، وأمر بالتوكل، والاستعانة بالله، وسئل النبي عليه الصلاة والسلام قيل: «يا رسول الله! أي الكسب أطيب؟ قال: عمل الرجل بيده، وكل بيع مبرور لما سئل: «أي الكسب أطيب؟ قال: عمل الرجل بيده - هذا من الأسباب -، وكل بيع مبرور.\nفالتوكل يجمع الأمرين: الثقة بالله، والاستعانة بالله، والاعتماد عليه، والإيمان بأنه الرزاق، وبأنه مسبب الأسباب، وأن ما شاء الله كان، وما لم يشأ لم يكن، ثم مع ذلك يفعل الأسباب، يبيع ويشتري، يعالج المرض، يغرس النخل، يأتي بالنفقة لأولاده، يغلق بابه عن السراق، يعقل ناقته لا تشرد وما أشبه ذلك. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16708/حكم-عملية-التجميل-اذا-كان-الوجه-مشوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77708.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":17770,"question":"سماحة الشيخ حفظكم الله تقول السائلة: هل للعين -أعني: الحسد- أنواع، بمعنى: أنه فيه عين تضر بالمعان بشدة، وعين تضر بالمعان بأضرار بسيطة؟","title":"هل للعين أنواع؟","answer":"الجواب: العين حق مثل ما قال ﷺ: العين حق، ولو أن شيئًا سبق القضاء لسبقته العين قد تقع العين تضر بعض الناس، وليس باختيار الإنسان، قد يكون عنده عندما يرى شيئًا يعجبه قد يصاب المعيون بشيء يضره، فالإنسان يتعوذ بكلمات الله التامات من شر ما خلق صباح ومساء ثلاث مرات، فهذا من أسباب الوقاية، يقول: أعوذ بكلمات الله التامات من شر ما خلق صباحًا ومساء ثلاث مرات، هذه من أسباب الوقاية، ويقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات صباحًا ومساء، هذا من أسباب الوقاية.\nوالعين حق قد تصدر من الإنسان بغير اختياره، قد يرى ما يعجبه من صحة إنسان أو كثرة ماله، أو غير هذا؛ فيحصل له أن يعينه، نعم، يعني ينظره. نعم.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16742/هل-للعين-انواع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59621.mp3","categories":["الطب والتداوي"]},{"id":17771,"question":"تقول الأخت من الزلفي يا سماحة الشيخ: علاج العين هل نكتفي بالرقية الشرعية؟ أم لابد من الاغتسال من العائن؟","title":"كيفية العلاج من العين","answer":"الجواب: الرقية الشرعية علاج، والاغتسال علاج، إذا تيسر أن العائن يغتسل، يعني: لو ما اغتسل المقصود... يغسل وجهه ويتمضمض، ويغسل داخلة إزاره وأطراف قدميه، ينفع هذا، يصب على المريض ويغتسل به المعين؛ هذا ينفعه بإذن الله، وإن غسل وجهه وتمضمض في إناء وصبوه على المريض؛ نفع بإذن الله.\nلو ما اغتسل، المقصود كونه يغسل وجهه ويتمضمض ويغسل يديه وداخلة إزاره وأطراف قدميه وركبتيه هذا ينفع في علاج المعين، وقد جربنا أن غسل الوجه والمضمضة وغسل اليدين وحده يكفي بإذن الله في إزالة العين، فإذا اتهم إنسان بهذا وغسل وجهه ويديه وتمضمض في إناء، ثم صب على المريض؛ يبرأ بإذن الله.\nالمقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16744/كيفية-العلاج-من-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59622.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":17775,"question":"هذا السائل محمد (و) يقول: ما العلامات التي يعرف بها الساحر والكاهن والمشعوذ؟","title":"علامات الساحر والكاهن وغيرهما","answer":"الجواب: يعرفون بما يقولون من الكلام الباطل والأعمال الباطلة، يعرفون بدعواهم الباطلة المخالفة للشرع، فهذا دليل ظاهر يعني، فيعرف المشعوذ والكاهن والرمال والمنجم والساحر بأعمالهم التي يعملونها، كل واحد يعرف بعمله، فالذي يدعي علم الغيب أو يدعي أشياء لا أساس لها، هذه من الدلائل على أنه يستخدم الجن ويستعين بالجن، أو كذاب يكذب على الناس لأكل أموالهم.\nوهكذا الذي يستعمل أشياء تضر الناس، فهذا ينبغي أن يرفع أمره إلى الجهة المختصة كالهيئة والمحكمة؛ لأنه قد يتعاطى السحر وقد يتعاطى أشياء تضر الناس بغير علم؛ لجهله وعدم بصيرته.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16758/علامات-الساحر-والكاهن-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59627.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":17841,"question":"سماحة الشيخ! هذه السائلة أم عبد الله أرسلت بسؤال طويل ملخصه سماحة الشيخ: تذكر بأنها امرأة متزوجة منذ ثلاثة أعوام ولم ترزق بأطفال، تذكر بأنها تعالجت هي وزوجها عند كثير من الأطباء وتذكر بأنها خسرت الكثير من المال والجهد، والتعب والإرهاق، ولكن دون فائدة، تقول: لذلك تركنا العلاج وتوجهنا إلى الله  ندعوه ونرجوه، وقد كان زوجي تقول: على معصية، فتركها بعد أن هداه الله، السؤال يبقى يا سماحة الشيخ هل - تقول - أعتمد على الله  فقط وأستمر في دعائي دون إكمال العلاج؟ أم أستمر في البحث عن العلاج مع توكلي على الله، والدعاء؟ وجزاكم الله خيرًا.","title":"هل يترك العلاج ويكتفى بالتوكل على الله؟","answer":"الجواب: الجمع بين الأمرين أفضل؛ العلاج والدعاء، إذا تيسر العلاج من أطباء طيبين فهذا أمر مطلوب، تعاطي الأسباب أمر مشروع مع التوكل على الله، والثقة بالله، ودعائه، والضراعة إليه ، لكن لا يجوز العلاج عند المخرفين والمشعوذين، ومن يدعي علم الغيب ..... هؤلاء يجب الحذر منهم، أما عند الأطباء المعروفين، والقراء المعروفين الذين لا يتهمون فلا بأس يقول النبي ﷺ: عباد الله تداووا ولا تداووا بحرام ويقول ﷺ: ما أنزل الله داءً إلا أنزل له شفاءً علمه من علمه وجهله من جهله. فالتداوي مطلوب لا بأس به ولا حرج فيه مع الثقة بالله، والتوكل على الله، والإيمان بأنه سبحانه هو المقدر، هو الذي بيده كل شيء، يقول جل وعلا في كتابه العظيم: يَهَبُ لِمَنْ يَشَاءُ إِنَاثًا وَيَهَبُ لِمَنْ يَشَاءُ الذُّكُورَ ۝ أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَاثًا وَيَجْعَلُ مَنْ يَشَاءُ عَقِيمًا إِنَّهُ عَلِيمٌ قَدِيرٌ[الشورى:49-50] .\nالناس أربعة أقسام: قسم يرزق إناثًا، وقسم يرزق ذكورًا، وقسم يرزق ذكورًا وإناثًا، وقسم لا يولد له؛ عقيم من الرجال والنساء، فأنت وزوجك قد تكونان من القسم الأول، وقد تكونان من القسم الثاني، وقد تكونان من القسم الثالث، وقد تكونان من القسم الرابع كل واحد منكم عقيم، قد تكوني أنت عقيمة وهو ليس بعقيم أو بالعكس، ربنا هو الذي يعلم كل شيء ، فلا مانع من تعاطي الدواء منك وزوجك جميعًا. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16834/هل-يترك-العلاج-ويكتفى-بالتوكل-على-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77914.mp3","categories":["مسائل متفرقة في العقيدة","الطب والتداوي"]},{"id":17882,"question":"هذا سائل يقول: ما هي الآيات التي كان الرسول ﷺ يرقي بها المرضى، وكيف تكون؟وهل يرقي بها عند بداية المرض؟ أم تكون دائمة حتى يزول المرض؟ وما نصيحتكم للقراء؟ مأجورين.","title":"ما الآيات التي يرقى بها المريض؟","answer":"الجواب: كل القرآن مبارك، كله رقية، ومن الرقية: الفاتحة وآية الكرسي وقُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين، مما كان يستعمله النبي ﷺ ويحث عليه: الفاتحة؛ لأنها أم القرآن وهي أفضل السور، وآية الكرسي الرسول ﷺ أرشد إلى قراءتها بعد كل صلاة وعند النوم، وكذا قل هو الله أحد والمعوذتين كان يقرؤها ﷺ عند النوم ثلاث مرات عند النوم، وينفث في يديه ويمسح بهما على رأسه ووجهه وما أقبل من جسده، كل هذا ثبت عنه ﷺ، وقال: «من قرأ هذه السور الثلاث في أول الليل أو في أول النهار لم يمسه شيء أو لم يصبه شيء»، فهذا كله مما يشرع، وثبت أن بعض الصحابة رقى بعض المرضى بالفاتحة فقط؛ فشفاه الله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16888/ما-الايات-التي-يرقى-بها-المريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59812.mp3","categories":["الطب والتداوي"]},{"id":18065,"question":"هذه سائلة سهام من سوريا تقول: مضت على زواجي خمس سنوات، ولم أرزق بمولود، وقد تداويت كثيرًا عند طبيبات، ولم أستفد شيئًا، فهل يجوز لي أن أتداوى عند طبيب رجل؟ أرشدوني جزاكم الله خيرًا.","title":"ما حكم تداوي المرأة عند الطبيب؟","answer":"الجواب: نعم لا بأس إذا لم يتيسر طبيبة تعرف الداء فلا مانع من العلاج عند الرجال، إذا كان عندهم دواء من أهل الخبرة الذين يعرفون مثل هذا المرض؛ فإنه لا حرج في هذا الشيء عند الطبيب المجرب المعروف بأنه يتعاطى علاج أمراض النساء، وأمراض العقم. نعم.","link":"https://binbaz.org.sa/fatwas/17100/ما-حكم-تداوي-المراة-عند-الطبيب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90108.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":18082,"question":"ما حكم المعالجة بالكي بالنار، بالنسبة للإنسان، وكذلك الحيوان؟ وكذلك وضع العلامات على الحيوانات بطريقة الكي بالنار؛ حتى إذا اختلطت مع غيرها تعرف؟ جزاكم الله خيرًا.","title":"حكم الكي بالنار للإنسان والوسم للحيوان","answer":"الجواب: الكي بالنار جائز إذا احتاج إليه الإنسان؛ يقول النبي ﷺ: الشفاء في ثلاث: شربة عسل، وكية نار، وشرطة محجم، ولا أحب أن أكتوي، رواه البخاري في الصحيح، وفي رواية: وأنا أنهى أمتي عن الكي، فالكي من أسباب الشفاء، وهكذا شرب العسل، وهكذا الحجامة، لكن إذا تيسر علاجٌ آخر غير الكي؛ فهو أولى، لأن فيه نوعا من التعذيب، فإذا تيسر علاجٌ آخر، فهو أولى، وهو المقدم، فإن احتاج إلى الكي؛ فلا بأس، لأنه كوى بعض أصحابه، وبعض الصحابة اكتووا، خباب بن الأرت اكتوى كياتٍ كثيرة، للحاجة، فلا بأس بالكي عند الحاجة. وهكذا الوسم، وسم الحيوانات بالكي، في الأذن، أو في الفخذ، لا بأس، لكن في الوجه لا، ما يجوز في الوجه، الوسم بالكي في الوجه ما يجوز، لا ضرب الوجه، ولا وسم الوجه، لكن إذا كان وسمها في أذنها، أو في فخذها، أو في عضدها؛ فلا بأس بذلك، الإبل، أو البقر، أو الغنم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17117/حكم-الكي-بالنار-للانسان-والوسم-للحيوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73006.mp3","categories":["الطب والتداوي"]},{"id":18198,"question":"يسأل أخونا ويقول: يوجد في منطقتنا شخص يسكن في بيت وحده، ويدعي وجود الجان في بيته، ولا يستطيع -حسب قوله - إشعال النور ليلًا ويغمض عينيه في أغلب الأحيان، وقد زار منزله بعض من يدعي معرفة الجان، وقالوا: إن البيت فعلًا يسكنه الجان، يأكلون معه، وهناك جنية تصحبه دائمًا، فهل حقيقة أن الجان تتحكم في بعض الناس بهذه الطريقة؟ وهل في شريعتنا الغراء ما يتم به طرد الجان من مثل هذا البيت أرجو الإفادة، جزاكم الله خيرًا.والسلام عليكم ورحمة الله.","title":"حكم من يتعامل مع الجن ويدعي مصاحبتهم","answer":"الجواب: نعم، نعم، قد يقع هذا لبعض الناس، قد يصحبه الجان، قد يضلونه، وقد يغرونه بأشياء تضر الناس، قد يعطونه بعض العلوم المغيبة التي اطلعوا عليها باستراق السمع أو بمجيئهم من بلدان أخرى، كأن يخبروه بأنه مات أمير البلد أو مات فلان في البلد الفلانية؛ لأن الشياطين يخبر بعضهم بعضًا، وهم سريعو التنقل من بلد إلى بلد، قد يسترقون السمع ويسمعون شيئًا من الملائكة في السماء أو في العنان في سماء الدنيا أو في العنان فيبلغون أولياءهم من الإنس. فالإنسي قد يكون له صاحب من الجن يسمونه الرائي، أهل الجاهلية، ويسمى صاحبه الكاهن، فهذا واقع من قديم الزمان، وكل إنسان معه شيطان، ومعه ملك قرين، قد يكون الشيطان الذي مع الإنسان يصحب هذا ويدعوه إلى الحضور، قد يتعاون معه على مقاصدهم الخبيثة مع هذا الرجل أو مع هذه المرأة، هذا واقع في الناس صحبة الجن واتخاذهم أولياء والاستعانة بهم على ضرر بعض الناس أو نفع بعض الناس كل هذا واقع، ولكنه منكر لا يجوز محرم لا يجوز للمسلم أن يتخذهم أصحاب من طريق الكهانة أو طريق السحر حتى يضر بهم الناس، بل يجب أن يحذرهم. ويجب على المسلمين أن يجاهدوا هؤلاء بما يزيل شرهم، ولي الأمر يبعث لهم من يستتيبهم فإن تابوا ورجعوا إلى الحق والصواب وإلا عذبهم وعاقبهم بالضرب والسجن حتى يتركوا هذه الشعوذة، وهذا الفساد، وإذا علم منهم أنهم يدعون الجن ويستغيثون بالجن ولهم ينذرون صار هذا شركًا أكبر يستحقون معه القتل، أو علم منهم أنهم يدعون علم الغيب بسبب شياطينهم، وأنهم يعلمون الغيب وأنه سوف يكون كذا وسوف يكون كذا، فهم يستتابون أيضًا فإن تابوا وإلا قتلوا كفارًا؛ لأن دعوى علم الغيب كفر كما قال الله سبحانه: قُلْ لا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالأَرْضِ الْغَيْبَ إِلَّا اللَّهُ [النمل:65]، وقال سبحانه: وَلِلَّهِ غَيْبُ السَّمَوَاتِ وَالأَرْضِ [هود:123]، قال الله  لنبيه ﷺ: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ [الأعراف:188]، فإذا كان محمد ﷺ وهو أفضل الخلق وسيد ولد آدم لا يعلم الغيب، فغيره من باب أولى. فالواجب القضاء على هذه الشعوذة وعلى هذا الشخص الذي يفعل ما ذكرت من جلوسه وحده، ودعواه أنه له جنية، وأنه لا ينور في بيته في الليل، وأنه يغمض عينيه، هذا كله من باب إيهام الناس وأخذ أموالهم بالباطل حتى يقول لهم: افعلوا كذا وافعلوا كذا وسوف يكون كذا وسوف يكون كذا، هذا لا يجوز إقراره على حاله عند من له أدنى تمسك بالشرع من الولاة، بل الواجب على ولاة الأمور الإسلاميين أن يأخذوا على أيدي هؤلاء، وأن يقضوا على خرافاتهم وشعوذتهم وإفكهم. ومعلوم إذا كان صادقًا أنه يزول عن هذا، إذا تاب إلى الله ورجع إلى الحق وتاب إلى ربه من هذه الأشياء فإنها تبتعد عنه، فإنها تنزل على كل أفاك أثيم، وكذاب أثيم على أصحابهم، فإذا تاب رجع إلى الله وصدق واستعاذ بالله من شرهم كفاه الله شرهم. ومن أسباب الوقاية كثرة قراءة القرآن والتعوذ بكلمات الله التامات من شر ما خلق، إذا دخل المنزل، وأن يقول صباح ومساء: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات فإنه لا يضره شيء، وهكذا إذا قال: أعوذ بكلمات الله التامات من شر ما خلق ثلاث مرات إذا دخل المنزل، كل هذا من أسباب العافية والسلامة من هؤلاء الأشرار من الشياطين شياطين الإنس والجن، ولا يجوز أن يقر هذا الشخص وأشباهه على هذا الباطل وهذه الشعوذة المنكرة التي يضل بها الناس ولاسيما الجهال. والله المستعان. نعم. المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17235/حكم-من-يتعامل-مع-الجن-ويدعي-مصاحبتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_907/nour_90705.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":18220,"question":"هذه السائلة نائلة من الرياض تذكر في سؤالها الأول وتقول: انتشرت في الآونة الأخيرة في المدارس، ودور التعليم المختلفة بأنه إذا أصيبت إحدى الطالبات أو ما سواها بالعين أي الحسد؛ فإنه يدار على جميع الطالبات في قاعة الدراسة بماء في قوارير علبة -مثلاً- ماء صحة، ويطلب النفث من الطالبات في هذه القوارير من كل طالبة، وغالبًا يكون هذا الأمر إلزامي، فما رأي الشرع في نظركم سماحة الشيخ في ذلك؟","title":"حكم إلزام الطالبات بالنفث في ماء لمن أصيبت بعين","answer":"الجواب: لا حرج في هذا، لكن لا يكون إلزامي، يكون، يطلب منها أن تنفث فيه لعل الله ينفع بذلك، تنفث فيه وتقول: اللهم اشفها، اللهم عافها، اللهم اشفه، اللهم عافه، لا حرج في هذا، القراءة في الماء تنفع بإذن الله، وإذا كانت مصابة بالعين وتخشى أنه من زميلاتها فلا بأس، والحمد لله. وإذا غسلوا لها أيديهم ووجوههم في إناء وشربت منه، وتروشت منه؛ هذا حسن، العين تقع بغير اختيار، تقع العين من الإنسان بغير اختياره، فإذا خشي أنها وقعت منهم العين، وأصابها شيء تظن أنه عين من زميلاتها، وغسلوا وجوههم لها، وأيديهم، وشربت منه، وتروشت به، أو قرءوا لها؛ كل هذا حسن إن شاء الله. نعم. المقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17265/حكم-الزام-الطالبات-بالنفث-في-ماء-لمن-اصيبت-بعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78209.mp3","categories":["الطب والتداوي"]},{"id":18358,"question":"هذه سائلة للبرنامج تقول يا سماحة الشيخ! في حالة من خيف عليه من الإصابة بالعين هل تكفي المعوذات فقط في مثل هذه الحالة أن يحصن بها؟","title":"ما يعوذ به الإنسان إذا خيف عليه من العين","answer":"الجواب: نعم، إذا قرئ عليه قل هو الله أحد والمعوذتين كفى، كان النبي ﷺ يقرأ على الحسن والحسين ويعوذهما بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة، فإذا قرئ عليهما قل هو الله أحد والمعوذتين، وقرئ عليهما: أعيذكم بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة سواء واحد وإلا جماعة، كل هذا حسن.","link":"https://binbaz.org.sa/fatwas/17413/ما-يعوذ-به-الانسان-اذا-خيف-عليه-من-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91325.mp3","categories":["الطب والتداوي"]},{"id":18397,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجزائر باعثها أحد الإخوة من هناك يقول: (س. ع. ف) أخونا يسأل في أول أسئلته عن حكم امرأة كانت حاملًا؛ فأكلت دواء فسبب مرضًا فأسقط الجنين، هل عليها شيء أو لا؟","title":"حكم المرأة إذا تسببت بإسقاط جنينها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الله  أباح لعباده التداوي، بل شرعه لهم بما لا محذور فيه، فقال: عباد الله! تداووا ولا تداووا بحرام، وقال عليه الصلاة والسلام: ما أنزل الله داء إلا أنزل له شفاء علمه من علمه وجهله من جهله، وقال أيضًا عليه الصلاة والسلام: لكل داء دواء؛ فإذا أصيب دواء الداء برأ بإذن الله. فللرجل والمرأة أن يتداوى بالأمر المباح الذي يرجو فيه الفائدة، فإذا تداوت المرأة بشيء من الدواء وحصل بسببه إسقاط حبلها؛ فإنه يكون من باب القتل الخطأ، فإن قتل الخطأ هو أن يفعل الإنسان ما له فعله فيترتب عليه قتل؛ كأن يرمي الصيد فيصيب إنسانًا، أو يرمي الهدف فيصيب إنسانًا، فهذا هو قتل الخطأ. فإذا تعاطت شيئًا من الدواء لا لقصد إسقاط الحبل، ولكن لأجل التداوي فذكر الأطباء، أو العارفون بهذا الدواء وآثاره على الحمل أنه هو السبب في قتله فإن عليها دية؛ وهي غرة عبد أو أمة إذا سقط ميتًا بأسباب هذا الدواء، وعليها كفارة إذا كان قد مضى عليه أربعة أشهر؛ لأنه حينئذ تنفخ فيه الروح، ويكون إنسانًا فعليها عنه غرة عبد أو أمة للورثة، وعليها كفارة: عتق رقبة مؤمنة، فإن لم تستطع فصيام شهرين متتابعين، كأمثاله من النفوس المعصومة، إلا أن يسمح الورثة عن الغرة فلا حرج في ذلك، كما لو سمح الورثة عن الدية الكاملة إذا كانوا عقلاء مرشدين، وهذه الغرة التي هي عبد أو أمة تكون للورثة قيمتها خمس من الإبل عشر دية أمه. وأما الكفارة فهي حق لله ليس للورثة فيها حق، فعليها أن تصوم إذا عجزت عن العتق، فإن لم تستطع العتق ولا الصيام بقي في ذمتها حتى تقدر على شيء من ذلك، تبقى الكفارة في ذمتها حتى تقدر على العتق أو تقدر على الصيام، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/17467/حكم-المراة-اذا-تسببت-باسقاط-جنينها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86301.mp3","categories":["الجنايات والحدود","الطب والتداوي"]},{"id":18421,"question":"يقال: إن وضع لبان النار في أوقات الغروب والشروق يبعد الشياطين من البيت، هل هذا صحيح؟","title":"مدى صحة أن لبان النار يطرد الشياطين من البيت","answer":"الجواب: ما بلغني شيء في هذا، أقول: لا أعلم شيئًا في هذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17501/مدى-صحة-ان-لبان-النار-يطرد-الشياطين-من-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_733/nour_73306.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":18552,"question":"الرسالة التالية رسالة بعث بها أخونا إسماعيل البشير علي سوداني، يعمل بدولة قطر، أخونا له ثلاثة أسئلة، في سؤاله الأول: يسأل عن حكم الإسلام في جراحة التجميل؟","title":"حكم الإسلام في جراحة التجميل","answer":"الجواب: هذا فيه تفصيل: إذا كانت الجراحة لا تغير شيئًا مما أمر الله ببقائه فلا بأس؛ فإذا كان التجميل لا يتضمن نقشًا في وجه الإنسان وهو الوشم، ولا يتضمن قطع عضو، وإنما ينور الوجه، أو ينور البدن، أو يعدل ما اعوج، كيد فيها عوج لتصلح، أو رجل فيها عوج، أو أنف فيه خلل يصلح، فلا بأس بذلك، أو أسنان فيها خلل تصلح، كطول بعضها أو ميلان بعضها، أو سواد في الشفة أو شيء مما يمكن زواله، وحصول الجمال من دون أن يخالف أمر الله في شيء من ذلك، فلا حرج في ذلك، والرسول ﷺ نهى عن الوشم، ونهى عن الوصل، ولم ينه عن التجمل، نعم إن الله جميل يحب الجمال . كذلك إذا كان في إصبع زائدة في الرجل أو في اليد، فالصواب أنه لا حرج في إزالتها إذا قرر الطبيب أن إزالتها لا خطر فيها، وهكذا لو كان هناك ورم في وجه أو في يد يمكن إزالته بالعلاج فلا بأس، أو بقع سوداء في بدنه أو وجهه تمكن معالجتها، كل هذا لا حرج فيه؛ لأنه تجميل لا يخالف أمر الله، نعم. المقدم: بارك الله فيكم، هل تتكرمون سماحة الشيخ بالنص على الأشياء الممنوعة، وإن قصد بها التجمل المباح؟ الشيخ: مثل ما تقدم الوصل -وصل الشعر- لا يجوز، يسمونها الباروكة التي تلبس على الرأس لا يجوز؛ لأنها أشد من الوصل، والرسول ﷺ نهى عن الوصل، ولعن الواصلة. كذلك مسألة الوشم، كونه يغرز في الوجه، أو في اليد إبر ونحوها حتى يخرج الدم، ثم يجعل فيه شيء من الكحل أو غيره من الأشياء حتى تكون وشمًا في الوجه أو في اليد، هذا من باب الممنوع، الرسول ﷺ لعن الواشمة والمستوشمة والواصلة والمستوصلة. كذلك تفليج الأسنان، تحسينها بفلج ما بينها، فتكون مفلجة، هذا ممنوع، أما إذا كان السن مائلًا لإصلاحه أو زائد لإصلاح الزيادة، وإزالة الزيادة، أو أسود لإصلاحه، فلا بأس بذلك، هذا ليس مما نهى عنه النبي ﷺ. المقدم: بارك الله فيكم، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17659/حكم-الاسلام-في-جراحة-التجميل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91603.mp3","categories":["الطب والتداوي"]},{"id":18640,"question":"السائل( مصطفى .ش.أ) جمهورية مصر العربية محافظة المنيا يقول: لي أخ متزوج منذ أربع سنوات، ولم يرزق بأبناء، فقال له البعض من الناس بأن هناك عمل للجان، أو بأن هذا من عمل الجان، وقال الآخرون: بأنه سحر، وما شابه ذلك، فأرجو من سماحتكم التوضيح بالتفصيل: ما هو العمل في تلك الحالة؟ علمًا بأن تلك المشكلة معقدة، وتمثل شيئًا بالنسبة لأخي وأمي ولي أيضًا، جزاكم الله خيرًا سماحة الشيخ.","title":"توجيه من لم يرزق بالأبناء","answer":"الجواب: الله  بيَّن الأمر، قال -جل وعلا-: يَهَبُ لِمَنْ يَشَاءُ إِنَاثًا وَيَهَبُ لِمَنْ يَشَاءُ الذُّكُورَ ۝ أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَاثًا وَيَجْعَلُ مَنْ يَشَاءُ عَقِيمًا[الشورى:49-50] فالناس أربعة أقسام: واحد يعطى ذكورًا، واحد يعطى إناثًا، واحد يعطى ذكورًا وإناثًا، وواحد لا يولد له شيء، يكون عقيمًا، ما كتب الله له الذرية. فإذا أحب أن يعرض نفسه على الأطباء المختصين لعل هناك مانعًا يعالج فلا بأس، فإذا لم يتيسر العلاج، فالحمد لله. أما إتيان السحرة والكهان فلا يجوز، لا يجوز سؤالهم ولا إتيانهم لا الكهان ولا السحرة ولا العرافون، إنما الأطباء الخاصون الذين يتعاطون الطب والجراحات، ويتعاطون أسباب العقم ما هي حتى يدرسوها، فإذا وجد من يعالجه من جهة موانع منعت من الحمل غير العقم، يعني: اتضح للطبيب أشياء قد منعت الحمل وعالجها فلا بأس. أما العقيم فلا حيلة فيه، من كتب الله أنه عقيم فلا حيلة فيه، لكن قد يكون هناك أسباب منعت الحمل، فتعالج من جهة الأطباء المختصين. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17757/توجيه-من-لم-يرزق-بالابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78719.mp3","categories":["الطب والتداوي","نصائح وتوجيهات"]},{"id":18694,"question":"من اليمن السائل (عبد الله. أ) يقول في هذا  سماحة الشيخ، السلام عليكم ورحمة الله وبركاته، يقول: رجل طلب منه شخص مريض أن يشتري له إبرة لضيق التنفس؛ وذلك من الصيدلية؛ لأنه تعود على شرائها من قبل ذلك، فذهب واشتراها له هذا الرجل، فأمره أن يضربها له، فضربها له في العضل، وهذه الإبرة تضرب في الوريد، فضربها له في المساء، وفي الصباح مات الرجل المريض.والآن الرجل الذي ضرب له هذه الإبرة لا ينام الليل لهول ما أصابه، فهو يظن بأنه هو الذي قتله بتلك الإبرة التي ضربها له، بالرغم أنهم ذهبوا إلى الأطباء بمثل هذه الإبرة، وسألوهم عن ذلك: هل هي تقتل إذا ضربت في العضل، ولم تضرب في الوريد لجهل الرجل هذا؟ قالوا لهم: لا. ولكن قد تسبب بعض الالتهابات بعد ضربها، وعلى الرغم من هذا لم يقتنع هذا الرجل، بل يقول بأنه هو الذي قتله.نرجو منكم أن توضحوا لنا ذلك مأجورين.","title":"حكم من يظن أنه تسبب في قتل رجل مريض","answer":"الجواب: على الفاعل أن يسأل المختصين من الأطباء، فإذا قالوا: إن فعله سبب الموت؛ عليه الكفارة في قتل الخطأ، وهي عتق رقبة، فإن عجز يصوم شهرين متتابعين، وإن قالوا: إنها لا تسبب الموت فلا شيء عليه، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17796/حكم-من-يظن-انه-تسبب-في-قتل-رجل-مريض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78806.mp3","categories":["الجنايات والحدود","الطب والتداوي","قضايا المرأة"]},{"id":18698,"question":"أخونا له مسألة أخرى يقول فيها: ظهور الكتب لمؤلفين مستشرقين باللغة العربية قد أظهر خطرًا محدقًا بتفكيرنا الذي نشأ بقراءة كتب السلف الصالح، وإني أوضح ذلك قائلًا: إن أدباءنا وكتابنا ومؤرخينا ظلوا وما لبثوا يستعملون الألفاظ المبجلة لمن كتبوا عنهم، بينما نرى هؤلاء المستشرقين تحسهم وأنت تقرأ لهم أنهم يعتدلون في ذلك، أي: إنك ترى أنهم يكتبون بكل تدبر، ولا يلقون الكلمات جزافًا، أي أنهم يذكرون العيوب والحسنات، بينما الكاتب العربي حتى ولو أنه يكتب قصة أو شيئًا عن المسلمين تجد أنه يذكر الحسنات دون السقطات والمساوئ مما جعل القارئ غير واثق فيما يكتب هذا الكاتب العربي المسلم. أرجو التوجيه وتوضيح هذه المسألة، جزاكم الله خيرًا.","title":"كيفية التعامل مع المستشرقين وكتاباتهم","answer":"الجواب: لا شك أن الكتاب يتفاوتون، ولا ريب أن المترجمين للناس يتفاوتون، فمن الناس من يعتدل، ويذكر حسنات الرجل وأعماله الطيبة حتى يقتدى به، حتى يتأسى به في الخير، ويترك السيئات التي لا ينبغي ذكرها؛ لأنه لا ينبغي ذكر سيئات الأموات؛ لأنه غيبة، فلا ينبغي ذكر سيئاتهم، بل ينبغي ذكر أعمالهم الطيبة التي يقتدى بهم فيها. أما السيئات فينبغي دفنها، وعدم ذكرها؛ لأنها من الغيبة، والله -جل وعلا- يقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] اللهم إلا أن يكون ذلك الرجل من أهل البدع، من أهل الكفر بالله، ممن يخشى أن يقتدى به في الباطل، فتذكر مساويه ليحذر، ولا يقتدى به في باطله، فيكون هذا من باب النصيحة للمسلمين، فإذا ذكر المترجم أو المؤرخ بعض عيوب الأموات التي يخشى أن يتأسى بهم فيها من البدع التي فعلوها أو الدعاية ضد الإسلام، أو ما أشبه ذلك، وبين هذا ليحذروا، وأن لا يقتدى بهم في الباطل فهذا حسن. أما السيئات التي بينه وبين الله التي دون الكفر، فينبغي ألا تذكر، وأن تترك؛ لأن ذلك من الغيبة، وأن تذكر حسناتهم العظيمة، وأعمالهم الطيبة التي يدعى لهم بسببها، ويتأسى بهم فيها، هكذا ينبغي للمؤرخ والمترجم للأموات، لكن من اشتهر بالشر والبدعة، ونحو ذلك تبين بدعته وشره الذي اشتهر به حتى لا يقتدى به، وحتى تعلم حاله، والله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17800/كيفية-التعامل-مع-المستشرقين-وكتاباتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92007.mp3","categories":["الطب والتداوي","قضايا معاصرة"]},{"id":18701,"question":"السائلة أختكم في الله (ف. السبيعي) تقول في سؤالها الأول: يقوم البعض من الناس إذا أتاهم من يخشون منه العين بغسل الأواني التي يشرب منها هذا الشخص بعد ذهابه عنهم، ويشربون الماء الذي غسلت فيه هذه الأواني، ويمسحون بها وجوههم، ويرون في ذلك أنه يزيل ما يتعلق بالعين، وأن ذلك لا يضرهم -إن شاء الله- إذا فعلوا ذلك، ما نصيحتكم لمثل هؤلاء سماحة الشيخ؟","title":"حكم استعمال آثار من يخشى منه العين","answer":"الجواب: لا أعلم لهذا أصلًا، لكن من اتهم بالعين، أو عرف أنها عين، يطلب منه أن يغسل وجهه، ويديه، وداخلة إزاره، وأطراف قدميه، كما جاء في الحديث، والغالب أنه إذا غسل وجهه ويديه كفى، يصب على المعين، ويبرأ -بإذن الله- كما جرى لسهل بن حنيف وعامر بن ربيعة. المقصود: أن هذا هو المطلوب إذا عرفوا أنه عان هذا الشخص، أو ظنوا أنه عان هذا الشخص؛ يطلب ماء ليغسل وجهه، ويديه، ويصب على المعين ويبرأ.  أما كونهم إذا جاء عندهم يغسلون الأواني بعده، ما أعرف لهذا أصلًا، ولا أعرف، ولكن إذا اتهموه ونفع لا بأس، إذا اتهموا أهله بالعين، وغسلوا الإناء الذي شرب منه ونفعه، لا بأس، الحمد لله. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17827/حكم-استعمال-اثار-من-يخشى-منه-العين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78815.mp3","categories":["الطب والتداوي"]},{"id":18787,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أخوكم في الإسلام مصري مقيم في السعودية بمدينة الرياض، أخونا بدأ رسالته بقوله: قرأت في إحدى المجلات مقالًا عن مرض السكر، وما مدى تأثيره في زواج الأقارب، ويتضح مما قرأت بأنه إذا كانت الزوجة والزوج والداهما مصابان بمرض السكر؛ أصبحت نسبة الإصابات عند الأبناء أكثر، أما إذا كان الزوج أو الزوجة أحد والديهم مصاب بمرض السكر، فإنها تقل احتمالات الإصابة.وأنا قد قمت بعقد قراني على ابنة عمي منذ سنة تقريبًا وعلى وشك الزفاف، ولكن بعد قراءتي لهذا المقال منذ أيام وأنا في حيرة في أمري؛ لأن والدي وعمي الذي هو والد زوجتي مصاب بمرض السكر، ولكن بنسب متفاوتة، وهذا المرض عندهم وراثي ويعالجان منه.سماحة الشيخ، أرجو من سماحتكم التكرم بإفادتي، هل إتمام الزواج بالنسبة لي سيكون فيه ضرر؟أرجو أيضًا إذا كان فيه ضرر إفادتي هل أقوم بفسخ هذا الزواج للأسباب الموضحة، أم أتمسك بزوجتي مع العلم بأنني متمسك بها؛ لأن ما بها من صفات وأخلاق تجعلها زوجة صالحة مع العلم بأن أهل زوجتي لا يعلمون بهذا الموضوع إلى الآن؟أفيدوني أفادكم الله على أن يكون الرد واضحًا وصريحًا، جزاكم الله خيرًا.","title":"حكم ترك الزواج من الأقارب خشية الأمراض الوراثية","answer":"الجواب: نصيحتي لك أيها الأخ، نصيحتي لك أن تكمل زواجك، وأن تعتمد على الله سبحانه، وأن تدع هذه الوساوس، وأبشر بالخير الكثير، وسوف ترى منها -إن شاء الله- ما يسرك ولا ترى إلا الخير. أما تفاصيل أمر السكر، وما يحصل للأولاد، فهذا شيء يحتاج إلى نظر، وقد يعرف بالتجارب الكثيرة، وقد يعرفه خواص الأطباء الذي جربوا كثيرًا، فلا ينبغي لك أن تلتفت إلى هذا، بل استعن بالله، وكمل زواجك وأبشر بالخير ودع عنك هذه الوساوس، وهذه الأشياء التي يقولها الناس، واسأل ربك العافية لك ولها ولا ترى إلا الخير -إن شاء الله-.","link":"https://binbaz.org.sa/fatwas/17924/حكم-ترك-الزواج-من-الاقارب-خشية-الامراض-الوراثية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87605.mp3","categories":["الطب والتداوي"]},{"id":19077,"question":"سماحة الشيخ يقول السائل: ما حكم استعمال حبوب منع الحمل بالنسبة للنساء؟","title":"حكم استعمال حبوب منع الحمل","answer":"الجواب: إذا كانت الحبوب تنفع ولا تضر إذا كانت تنفع ولا تضر فلا بأس إذا اتفقت مع الزوج على منع الحمل لأسباب شرعية من مضرتها أو رضاعها أو نحو ذلك من الأسباب التي يتفقان عليها فتعاطي الحبوب التي لا ضرر فيها لا بأس، إذا تراضى عليه الزوجان لمصلحة شرعية. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18245/حكم-استعمال-حبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88321.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":19164,"question":"رسالة وصلت إلى البرنامج من بغداد وباعثها أحد المستمعين من هناك يقول أخوكم أبا عمر، يسأل ويقول: لقد قرأت سورة الجن، وقرأت تفسيرها، ولم أفهم إلا الشيء القليل، والسؤال الذي يخطر ببالي دائمًا وأبدًا وهو: هل يمكن للبشر أن يصادق الجني الصالح؟ وهل يمكن مشاهدة هؤلاء الجن؟ وموضوع الجن موضوع طويل عريض حيث أنه دوخني - كما يقول - وأقلقني، أرجو إجابتي جزاكم الله خيرًا.","title":"حكم مصادقة الجن","answer":"الجواب: ليس للمسلم أن يصادق الجن؛ لأنه لا يأمنهم، ولا يعرف أحوالهم، وليس له أن يصادقهم، ولكن من عرف منهم بالخير، وأرشده إلى الخير؛ يدعو له بالتوفيق والسداد، والهداية والحمد لله. أما أنه يصادقهم فلا يصادقهم؛ لأنه لا يعرفهم كما ينبغي، وقد يكون منافقًا، ولا يعرف حاله، يتظاهرون بالإسلام، ولكن من أظهر له الإسلام دعا له بالخير، ومن ادعى له أنه مسلم دعا له بالتوفيق، والثبات على الحق، وينصحه، ويأمره بالمعروف، وينهاه عن المنكر والحمد لله، ولا يصادقه يتخذه صديقًا ويأمنه في كل شيء لا، إنما يدعو له بالتوفيق يدعو له بالهداية، ويشكره إذا أحسن إليه إذا أرشده إلى الخير، أو دله على خير، أو أمره بمعروف، أو نهاه عن منكر يقول: جزاك الله خيرًا، وما أشبه ذلك، أمره بالصلاة، أيقظه للصلاة قال: جزاك الله خيرًا، قال له: اجتهد في قراءة القرآن قال: جزاك الله خيرًا، أمره بمعروف نهاه عن منكر يقول: جزاك الله خيرًا. وأما كونه يراهم فالغالب أنه لا يراهم مثلما قال الله جل وعلا: إِنَّهُ يَرَاكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لا تَرَوْنَهُمْ[الأعراف:27]، الغالب أننا لا نراهم، وقد يتشكلون، ويراهم الإنسان في أشكال حيات، أو كلاب، أو سنور، أو حية .. أو ما أشبه ذلك قد يراهم في أشكال كما وقع قديمًا وحديثًا. وأما أنه يراه على صورته التي خلق عليها فقد لا يجزم بذلك، وقد لا يعرف ذلك؛ لأنهم أشكال لا نعرفها، أشكال وألوان كثيرة، لكن قد يتصورون في صور معروفة من الحيات، أو الكلاب، أو السنور أو غير ذلك كما هو واقع عرفه الناس، ونقله الناس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18363/حكم-مصادقة-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_798/nour_79808.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19209,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: المرسل (ح.ع) يمني من تعز، أخونا له مجموعة من الأسئلة والقضايا، القضية الأولى التي نطرحها في بداية هذه الحلقة يقول فيها: إذا كانت الزوجة تتعرض للمرض والتعب والتدهور في الصحة؛ بسبب الحمل والولادة بفترات متقاربة، ومع هذا كله لا يوجد لدينا الأغذية اللازمة للمرأة الحامل والمرضعة، ولا يوجد لدينا رعاية صحية متكاملة؛ لأن المعيشة في الريف قاسية، هل يجوز استخدام أي وسيلة من وسائل تنظيم الحمل لتلافي ما ذكر؟ جزاكم الله خيرًا.","title":"حكم استخدام وسائل تنظيم الحمل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، نبينا وإمامنا وسيدنا محمد بن عبد الله وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين، أما بعد: فلا حرج في استعمال الوسائل المباحة لتنظيم الحمل إذا كان على المرأة مشقة، إما لمرض أصابها، وإما للأسباب التي ذكرها السائل، فلا مانع من أن تستعمل حبوبًا أو شرابًا أو غير ذلك مما يباح؛ لأجل تنظيم الحمل حتى لا يضرها الحمل، وحتى لا يضر بتربية أولادها إذا تتابعوا عليها وهي لا تتحمل ذلك. والمقصود من ذلك هو الإحسان إليها، والإحسان إلى أولادها، فإذا كان في تنظيم الحمل إحسان إليها من جهة صحتها، والإحسان إلى أولادها من جهة التربية فلا حرج في ذلك والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18394/حكم-استخدام-وساىل-تنظيم-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88801.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":19222,"question":"أخت لنا من الجزائر تقول: (س. ب. م. ب) تقول: لقد ذكر السحر في كتاب الله، وهذا يؤكد كل التوكيد أن السحر شيء لا بد أن نؤمن بوجوده، وهذه هي مشكلتي، أنا أبلغ من العمر ثمان وعشرين سنة، ولم أتزوج بعد، وعندي شك بأنني مسحورة، ما هو الطريق الذي أسلكه حتى يبتعد عني ما أخافه؟ جزاكم الله خيرًا.","title":"حكم من تشك أنها مسحورة لأنها لم تتزوج وعلاج ذلك","answer":"الجواب: هذه يا بنتي أوهام، لا ينبغي لك أن تعتقديها، هذه أوهام وليست سحرًا، ولكنها الأوهام التي تخيف الناس، إذا تعطل شيء من شئونهم توهموا أشياء، فلا ينبغي لك أن تعتقدي هذا، نعم السحر موجود وله أسباب، لكن ليس تعطل الزواج أو تعطل بيع السلعة أو طول المرض يدل على السحر، بل قد يقع لأسباب أخرى. وإذا كنت قد شعرتي من أحد أنه فعل شيئًا أوجب لك ما يضرك تعالجه والحمد لله، العلاج موجود في كلام الله وكلام رسوله صلى الله عليه وسلم، فأحسن علاج وأولى علاج القرآن الكريم تلاوة الآيات والنفث بها على المسحور، فإن هذا من أسباب الشفاء، الله جعل كتابه شفاء من كل داء، وشفاء من كل سوء كما قال : قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44]، وقال : يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُمْ مَوْعِظَةٌ مِنْ رَبِّكُمْ وَشِفَاءٌ لِمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِلْمُؤْمِنِينَ [يونس:57]، وقال سبحانه: وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِينَ [الإسراء:82].  فالقرآن كله شفاء، ولا سيما إذا قرأ القارئ المؤمن المعروف بالاستقامة إذا قرأ على المريض ونفث عليه ودعا له، فلا شك أن هذا من أسباب الإجابة، وقد كان النبي ﷺ يرقى، قد كان يرقي بعض أصحابه عليه الصلاة والسلام، وقد رقاه جبرائيل، فالرقية أمر معروف، في الحديث: لا رقية إلا من عين أو حمة، يعني: لا رقية أولى وأشفى إلا من عين أو حمة، و(العين) من عين العائن، و(الحمة): سم ذوات السموم، فالسحر يزال، إذا ظنت المرأة أنها مسحورة أو الرجل بقرائن وأمارات فليستعمل ما شرع الله من الدعاء وسؤال الله العافية، ولا مانع أن يستعين ببعض أهل العلم المعروفين بالخير للقراءة عليه والنفث عليه، وذلك من أسباب الشفاء. ومن أسباب الشفاء أيضًا قراءة آيات السحر التي في سورة الأعراف ويونس وطه في إناء، ثم يقرأ معها آية الكرسي و قل هو الله أحد والمعوذتين، ثم يشرب منها ماء ثلاث غرفات .. ثلاث حسوات ثم يغتسل بالباقي، هذا مجرب في زوال السحر إذا كان موجود سحر، مجرب في زوال السحر، ومجرب في شفاء الرجل إذا حبس عن زوجته. وإن جعل في الماء سبع ورقات من السدر الأخضر، دقها وجعلها في الماء كان أيضًا من أسباب الشفاء، نبه على هذا كثير من أهل العلم، ونبه عليه الشيخ عبد الرحمن بن حسن في كتابه فتح المجيد في شرح باب ما جاء في النشرة. فالمقصود أن هذا بحمد الله له علاج مثل سائر الأمراض له علاج، فالعلاج من أعظم الأسباب التي يشفي الله بها العبد إذا صدق، وأخلص لله وحسنت نيته وضرع إلى الله وسأله العافية، فهو سبحانه قريب مجيب، وهو القائل: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، والله المستعان. نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/18420/حكم-من-تشك-انها-مسحورة-لانها-لم-تتزوج-وعلاج-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_890/nour_89008.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19240,"question":"..... وهو أن زوجتي كانت تدوخ أو تدخن غليون، وهو ما نسميه عندنا بالقدو، ولكن تاب الله ...... ولكن لم نتحصل على علاج، ولا فائدة من ذلك، وعليه هل يمكن رجوعها مرة ثانية لهذا الغليون الدوخة أو تدخن القدو، وللتوضيح أكثر؛ هل علينا الإثم فيما إذا عادت إلى ما كانت عليه، وهي تعتقد أن مرضها بسبب تركها له؟ جزاكم الله خيرًا.","title":"حكم التداوي بالحرام من المخدرات والتدخين وغيرها","answer":"الجواب: ليس لها أن تعود إليه، وليس لكم أن تعينوها على ذلك، والحمد لله الذي هداها ومن عليها بالتوبة، ولو قدر أنه من أسبابه فإنها لا تعود إليه، ولا تداوي بالحرام، لا يداوى بالحرام، يقول النبي ﷺ: عباد الله! تداووا ولا تداووا بحرام»، ويقول عليه الصلاة والسلام: «إن الله لم يجعل شفاءكم فيما حرم عليكم، فعليها أن تحتسب وتسأل الله العافية، وتجتهد في ذلك ولها البشرى بالخير، نسأل الله لها الشفاء العاجل والعافية مما أصابها. ونوصيكم بالعناية بعلاجها عند الأطباء المختصين بمثل هذا، والله جل وعلا يشفيها سبحانه، ويمن عليها بالعافية، ولها الأجر العظيم على صبرها في طاعة الله وتقواه ، وأنتم مشكورون أيضًا على تصبيرها وحثها على الثبات والصبر والحرص على ما يسبب شفاءها وعافيتها من هذا الأثر الذي أساء إليها، والله جل وعلا هو الحكيم العليم في ذلك، يمتحن صبرها ويمتحن إيمانها، فعليها أن تصبر وأن تحتسب، والله جل وعلا يعينها ويثبتها، يقول : وَلَنَبْلُوَنَّكُمْ حَتَّى نَعْلَمَ الْمُجَاهِدِينَ مِنْكُمْ وَالصَّابِرِينَ وَنَبْلُوَ أَخْبَارَكُمْ [محمد:31]، والله يقول جل وعلا: وَنَبْلُوكُمْ بِالشَّرِّ وَالْخَيْرِ فِتْنَةً [الأنبياء:35]. فعليها أن تصبر، وهذا ابتلاء وامتحان، فعليها أن تصبر ، وقد يكون هذا المرض ليس من أجل ذلك، بل أمر جديد، بل مرض جديد، ولكن الشيطان قد يزين لها أنه من أسباب الترك، فلا ينبغي لها، ولا يجوز لها أن تطيع الشيطان، ولا أن ترجع إلى ما عافاها الله منه وهداها الله فتركته. ونسأل الله لها مرة أخرى العافية والشفاء مما أصابها، وأن يتقبل توبتها ويثبتها. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18437/حكم-التداوي-بالحرام-من-المخدرات-والتدخين-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_891/nour_89107.mp3","categories":["الطب والتداوي"]},{"id":19276,"question":"ما حكم الرجيم؟ أي: الامتناع عن الأكل خوفًا من السمنة، وللمحافظة على شكل الجسم، علمًا بأن الرجيم لا يؤثر على الإنسان في صحته، هكذا تقول.","title":"حكم الامتناع عن الأكل خوفًا من السمنة","answer":"الجواب: لا أعلم بأسًا بذلك، كون الإنسان يعتني بأسباب السلامة من السمنة، وخفة البدن؛ حتى يرتاح من السمن وتعبه، لا بأس بذلك، بالطرق المباحة التي لا محذور فيها ولا مضرة فيها. نعم.","link":"https://binbaz.org.sa/fatwas/18456/حكم-الامتناع-عن-الاكل-خوفا-من-السمنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89203.mp3","categories":["الطب والتداوي"]},{"id":19321,"question":"نعود في بداية هذه الحلقة إلى رسالة المستمعة هدى ، أختنا عرضنا جزءاً من أسئلتها في حلقتين مضتا وفي هذه الحلقة بقي لها مجموعة من الأسئلة نرجو أن نتمكن من عرض بعض منها.في سؤالها الأول تقول: كيف يؤثر السحر على الناس مع أنه لا يحصل شيء إلا بإذن الله تعالى، وهل يجوز أن أذهب إلى شيخ لأرى هل من أحد ضرني إذا كنت أشك في ذلك؟ أرجو الإفادة والتوضيح جزاكم الله خيراً؟","title":"السحر ومدى تأثيره وكيفية علاجه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد دل كتاب الله  وسنة رسوله عليه الصلاة والسلام على أن السحر قد يقع بالنسبة إلى بعض الناس وقد يؤثر في المسحور بإذن الله  كما قال الله : وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102]. فبين سبحانه أنهم قد يضرون به لكن بإذن الله، يعني بقضاء الله وقدره، ثم قال بعدها: وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ [البقرة:102]، يعني: اعتاضه مَا لَهُ فِي الآخِرَةِ مِنْ خَلاقٍ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ [البقرة:102]، يعني: باعوا أنفسهم لو كانوا يعلمون، وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللَّهِ خَيْرٌ لَوْ كَانُوا يَعْلَمُونَ [البقرة:103]. فهذا يدل على خطر السحر، وأن صاحبه لا خلاق له عند الله، يعني: لاحظ له ولا نصيب، وأنه ضد الإيمان وضد التقوى وأنه كفر، كما قال عن الملكين أنهم يقولان لمن يتعلم: إنه كفر، فَلا تَكْفُرْ [البقرة:102]، وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولا [البقرة:102]، يعني: للمتعلم: إِنَّمَا نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ [البقرة:102]. فدل ذلك على أن تعلم السحر وتعليمه والعمل به كفر -نسأل الله العافية- وما ذاك إلا لأنه عبادة للشياطين وتقرب إليهم بالذبائح والنذور والدعاء والاستغاثة ونحو ذلك، فلا يكون الساحر ساحرًا إلا بتقربه للشياطين والجن وعبادتهم من دون الله  فقد يقع تأثر في المسحور ببغضه لزوجته، أو بغضها لزوجها إذا كانت هي المسحورة؛ ولهذا قال سبحانه: فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ [البقرة:102] بين المرء يعني: الرجل، وزوجه يعني: زوجته، وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102]، يعني: لا يضر السحرة أحداً إلا بإذن الله يعني بمشيئته  . فدل ذلك على أن ما يقع من الضرر بمشيئة الله ليس من قدرة الساحر، بل الساحر سبب، والله جل وعلا هو مقدر الأمور سبحانه وتعالى وهو الذي قضاها بحكمته وقدره السابق سبحانه وتعالى، وكل ما في الوجود فهو بمشيئة الله، ما شاء الله كان وما لم يشأ لم يكن، من كفر وسحر ومعاصي وطاعات كله بقدر الله  وله الحكمة البالغة جل وعلا، كما قال : مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الأَرْضِ وَلا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا [الحديد:22]، قال تعالى: إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ [القمر:49]، فالأمور كلها بيده  ولا يقع منها شيء في هذه الدنيا إلا بمشيئته سبحانه وتعالى وقدره السابق، فالطاعات بقدره السابق والمعاصي بقدره السابق والعبد له اختيار وله مشيئة يفعل ويختار، ويعرف ما يضره وما ينفعه فهو مؤاخذ باختياره إذا اختار ما يضره، كما أنه مثاب إذا اختار ما ينفعه من طاعات الله ، ولكنه مع هذا تابع لمشيئة الله، كما قال سبحانه: لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ [التكوير:28] وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:29]، قال سبحانه: فَمَنْ شَاءَ ذَكَرَهُ [المدثر:55] وَمَا يَذْكُرُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ هُوَ أَهْلُ التَّقْوَى وَأَهْلُ الْمَغْفِرَةِ [المدثر:56] . وقد يكون السحر تخييلًا وتزويرًا ليس له أثر في بدن الإنسان، كما قال جل وعلا في قصة موسى وفرعون: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66]، فهم أوجدوا حبالًا وعصيًا أمام الناس فظنها الناس حيات في الأرض، وإنما هي حبال وعصي، لكن خيل للناس أنها حيات لما فعلوا من التزوير والتضليل على عيونهم بأشياء عرفوها وأقدرهم الله عليها، حتى ظن العصي والحبال ظنها المشاهدون حيات وخافوا منها، والحقيقة أنها ليست حيات، ولكنها حبال وعصي؛ ولهذا يقول سبحانه: يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى [طه:66]، بخلاف يد موسى فإنها حقيقة، وبخلاف عصاه فإنها حقيقة، جعل الله العصا حية تسعى، ثم أعادها سبحانه سيرتها الأولى جل وعلا، وهكذا يده جعلها بيضاء ليس فيها مرض ولكنه آية، فعرفت بهذا أيها السائل وأيها المستمع أن السحر له حالان: إحداهما: حقيقية تؤثر في المسحور بمرض أو قتل أو بغضاء بينه وبين صاحبه أو بينه وبين زوجته.\nوالحال الثاني: تخييل وتزوير، وليس لها أثر في نفس الإنسان، ولكنه يخيل إليه أن زوجته غير زوجته، وأن أخاه غير أخاه، وأن صاحبه غير صاحبه وهكذا، فيخيل إليه أشياء تنفره من صاحبه، وتنفره من زوجته، أو تنفرها من زوجها بسبب ما وضعوا من الأشياء التي شوهت منظر الزوج أو الزوجة أو الصاحب؛ حتى صار غير حاله الأولى، فوقعت البغضاء والتغير والتكدر لما حصل من التزوير والتخييل من الساحر بين هذا وهذا، والله المستعان ولا حول ولا قوة إلا بالله. وله علاج والحمد لله، الله جعل له علاجًا من القرآن الكريم؛ فإن الله جعل في القرآن شفاء من كل داء، فالقراءة على المسحور من آيات الله التي نزلت في السحر وآية الكرسي، و قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1]، قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] وسورة المعوذتين، هذه إذا قرئت على المسحور وعليه بها ودعي له بالعافية ينفعه الله بذلك، أو تقرأ في ماء ينفث في الماء آيات السحر التي في الأعراف، والتي في يونس، والتي في طه، ثم يقرأ معها آية الكرسي و قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1] و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين، ثم يشرب منها المسحور أو المسحورة أو المحبوس عن زوجته ثلاث حسوات، ثم يغتسل بالباقي، هذا بإذن الله مجرب لزوال السحر وزوال الحبس الذي حبس عن زوجته، هذا مجرب وواقع والحمد لله، وهو من الدواء النافع المجدي الناجع بحمد الله. وقد يعرف المسحور من سحره في مسامير ينظم بعضها في بعض، أو في شعر عقد بعضه ببعض أو خرق أو أشباه ذلك قد يعرفها المسحور، فإذا عرفها وأزالها بطل السحر، والله المستعان، ولا حول ولا قوة إلا بالله، والآيات التي تقرأ من سورة الأعراف قوله تعالى: وَأَوْحَيْنَا إِلَى مُوسَى أَنْ أَلْقِ عَصَاكَ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ۝ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ۝ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ [الأعراف:119]، ومن سورة يونس: وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ [يونس:79] فَلَمَّا جَاءَ السَّحَرَةُ قَالَ لَهُمْ مُوسَى أَلْقُوا مَا أَنْتُمْ مُلْقُونَ [يونس:80] فَلَمَّا أَلْقَوْا قَالَ مُوسَى مَا جِئْتُمْ بِهِ السِّحْرُ إِنَّ اللَّهَ سَيُبْطِلُهُ إِنَّ اللَّهَ لا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ [يونس:81] وَيُحِقُّ اللَّهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ [يونس:82]، وفي سورة طه يقول سبحانه: قَالُوا يَا مُوسَى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ أَوَّلَ مَنْ أَلْقَى ۝ قَالَ بَلْ أَلْقُوا فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى ۝ فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً مُوسَى ۝ قُلْنَا لا تَخَفْ إِنَّكَ أَنْتَ الأَعْلَى ۝ وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ وَلا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى [طه:69]، فهذه الآيات وآية الكرسي و قُلْ يَا أَيُّهَا الْكَافِرُونَ [الكافرون:1]، و قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1]، و قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1] و قُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1. كلها تقرأ في الماء أو على المسحور أو المحبوس عن زوجته، ويدعى له بالشفاء والعافية بالدعاء المشهور الذي علمه النبي أصحابه عليه الصلاة والسلام، اللهم رب الناس أذهب البأس واشف أنت الشافي لا شفاء إلا شفاؤك شفاء لا يغادر سقمًا، وإذا كررها ثلاثًا كان أحسن؛ لأنه عليه الصلاة والسلام كان إذا دعا دعا ثلاثًا، وهكذا الدعاء المشهور الذي رقى به جبرائيل النبي عليه الصلاة والسلام باسم الله أرقيك، من كل شيءٍ يؤذيك، ومن شر كل نفس أو عين حاسد الله يشفيك، باسم الله أرقيك، هذا أيضًا ينبغي أن يكرر ثلاثًا، كما فعل جبرائيل مع النبي ﷺ فإنه رقاه بهذه الرقية العظيمة، باسم الله أرقيك من كل شيء يؤذيك، ومن شر كل نفس أو عين حاسد الله يشفيك، باسم الله أرقيك، وإذا دعا له معه بدعوات أخرى فلا بأس، من الدعوات الطيبة، كاللهم اشفه وعافه، اللهم أزل عنه السوء، اللهم أبرئه من مرضه، نحو هذه الدعوات لا بأس، كله طيب.  المقدم: بارك الله فيكم وجزاكم الله خيراً، شيخ عبد العزيز كون السحر يقع هل يخرج عن قدرة الله وإرادته؟ الشيخ: مثلما تقدم، كله بمشيئة الله، مثلما قال سبحانه: وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ [البقرة:102] .\nفالشيء كله بإذن الله وقضائه، إذا أراده سبحانه وقع، وإذا ما أراده لم يقع، ولو فعل الساحر ما فعل.  وهناك أشياء ينبغي التحرز منها ومن غير هؤلاء وهي: التعوذ بكلمات الله التامات من شر ما خلق صباحًا ومساء ثلاث مرات، وقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم، ثلاث مرات صباحًا ومساء، كل هذا من أسباب السلامة من السحر والعين وغير ذلك، كذلك قراءة آية الكرسي بعد كل صلاة وقراءتها عند النوم، كذلك قراءة قل هو الله أحد والمعوذتين بعد كل صلاة مرة، وبعد الفجر والمغرب ثلاث مرات، كل هذا من أسباب العافية من كل سوء بإذن الله عز وجل.  المقدم: جزاكم الله خيرًا، شيخ عبد العزيز سمعت من بعض طلبة العلم إنكاره للسحر حتى أنه قال: ائتوا بالسحرة ليسحروني إن كانوا صادقين، توجيهكم لو سمحتوا ولاسيما إذا كانت هذه العبارة من شخصٍ مشهور وله شعبية لا بأس بها؟ الشيخ: هذا جهل وغلط، هذه المقالة تصدر عن جهل، فقد سحر النبي ﷺ وهو أفضل الخلق، وقد صحت الأحاديث عن رسول الله ﷺ أنه سحر وعافاه الله من ذلك وشفاه الله سبحانه وتعالى، هذا شيء معروف، وقد أجمع المسلمون على أنه يقع بإذن الله سبحانه وتعالى، لكن بعضه يؤثر على المريض وبعضه بالتخييل كما تقدم. المقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18524/السحر-ومدى-تاثيره-وكيفية-علاجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_895/nour_89501.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19347,"question":"حدثت قصة سأرويها لكم، وأريد تفسيرا أو نصحا عن موضوعها، لنا جار له ابنة تبلغ من العمر الثامنة عشرة، مرضت بمرض نفسي وذهب بها إلى الأطباء ولم تستفد شيئا، ثم ذهب بها إلى الكهنة والمشعوذين، وقالوا: إن بها جنا ونحن سوف نخرجه، ولبثت البنت عندهم فترة وجيزة من يوم واحد، وعادت إلى البيت طبيعية ليس فيها شيء، وهي الآن تعيش حالة طبيعية مستقرة في بيت أبيها وجهونا لو تكرمتم جزاكم الله خيرًا؟","title":"حقيقة شفاء الكهان والمشعوذين للمرضى","answer":"الجواب: هذا قد يقع من الجن وشياطينهم، فقد يتعدون على امرأة أو على رجل بأسباب المرض، فيمرض، ثم إذا فزع إليهم وهرع إليهم ولي المرأة أو ولي الرجل وطلب منهم النجدة ساعدوا في ذلك وأزالوا ما فعلوا من الشر؛ حتى يغروا الناس ويخدعوهم، وحتى يدعوهم بهذا إلى الشرك، وإلى تعظيم الجن والشياطين، واللجوء إليهم ودعائهم والاستغاثة بهم ونحو ذلك، هذا من مكائد الشياطين ومن خبثهم وأعمالهم الخبيثة. فالواجب على المؤمن ألا يغتر بهذا، وألا يذهب إليهم، وألا يلتجئ إليهم وألا يسألهم، كما قال النبي ﷺ في الحديث الصحيح: من أتى عرافا فسأله عن شيء لم تقبل له صلاة أربعين يومًا، «وقال ﷺ لما سئل عن الكهان، قال: لا تأتوهم، قال: ليسوا بشيء، وقال: من أتى كاهنًا فصدقه بما يقول، فقد كفر بما أنزل على محمد صلى الله عليه وسلم، وقال: ليس منا من سحر أو سحر له، أو تكهن أو تكهن له، أو تطير أو تطير له، ووجود هذا منهم وكيدهم للناس، وهذا العمل منهم ولعبهم لهم، هذا لا يسوغ الذهاب إليهم والمجيء إليهم بل يجب أن يحذروا، وأن يبتعد عنهم، وأن يعالج من أصيب بهذه الأمراض بالعلاج الشرعي بالقراءة التي شرعها الله، فإن القراءة دواء تداوي به المرضى من الجن وغيرهم، يقرأ عليه المؤمن طالب العلم بما تيسر من القرآن ويدعو له، ويزول الضرر بإذن الله، وهذا أمر مجرب، قد فعله الأئمة والعلماء من قديم الزمان وحديثه، ونفع الله بذلك، ولو قدر أنه مات بسبب ذلك، فإنه ما مات إلا بأجله، حيث قدر الله أن يموت بهذا المرض، وبهذا الشيء الذي يتوهمون أنه من عمل السحرة أو الجن، فلا ينبغي لعاقل أن يؤثر حظه العاجل بتوهم الصحة على أيديهم، أو العلاج على أيديهم بما يضره في دينه ويغضب الله عليه سبحانه وتعالى، فكونه يلتزم بالأمر الشرعي، والعلاج الشرعي، ولو فرض أنه مات، ما مات إلا بأجله، هذا هو الواجب عليه، وليس له أن يلجأ إلى السحرة أو الكهنة، بزعمه خوفًا من الموت كل هذا من أبطل الباطل، ومن أعظم الفساد في الأرض، وأيضا من أعظم المحادة لدين الله، والتعدي لما شرعه الله  والله المستعان.","link":"https://binbaz.org.sa/fatwas/18555/حقيقة-شفاء-الكهان-والمشعوذين-للمرضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_899/nour_89904.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19349,"question":"يقول أخونا: يقول: بعض الناس: إن هناك شيطان قد أسلم وشيطان كفر، هل ما يقال صحيح؟","title":"وجود المسلم والكافر في الجن","answer":"الجواب:\n\nالجن فيهم المسلم وفيهم الكافر، والشيطان هو المتمرد، شياطين الجن متمردهم، وشياطين الإنس متمردهم، فذرية الشيطان من الشياطين هم على حالهم شياطين يصدون الناس عن الهدى، ومن هداه الله من الجن ما يسمى شيطان، الشيطان هو الذي يتمرد عن الحق والهدى ويتبع جده الشيطان في الباطل، ومن هداه الله منهم كان من جنسنا له فضله وله ما وعد الله من الجنة والخير، كما قال الله  في سورة الجن: وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذَلِكَ كُنَّا طَرَائِقَ قِدَدًا [الجن:11]، فإذا أسلم من تشيطن منهم ورجع إلى الإسلام وتمسك بالإسلام فهو مثل الإنسي الذي كان كافرًا ثم رجع إلى الإسلام وهداه الله.\n\nفالجن والإنس فيهم الكافر وفيهم المسلم وفيهم المبتدع وفيهم العاصي وفيهم الجهمي وفيهم المرجي وفيهم الرافضي وفيهم غير ذلك، كما قال سبحانه: وَأَنَّا مِنَّا الصَّالِحُونَ وَمِنَّا دُونَ ذَلِكَ [الجن:11] ثم قال بعده: كُنَّا طَرَائِقَ قِدَدًا [الجن:11] يعني: أقسام متفرقة مطلقة متنوعة فيهم الطيب والخبيث، فيهم الصالح والطالح، فيهم صاحب السنة وصاحب البدعة، وقال في الآية وما بعدها: وَأَنَّا مِنَّا الْمُسْلِمُونَ وَمِنَّا الْقَاسِطُونَ فَمَنْ أَسْلَمَ فَأُوْلَئِكَ تَحَرَّوْا رَشَدًا ۝ وَأَمَّا الْقَاسِطُونَ فَكَانُوا لِجَهَنَّمَ حَطَبًا [الجن:14-15] القاسط: العادل عن الحق، يقال: قسط؛ إذا جار، أما أقسط فهو العادل، ومنه قوله جل وعلا: إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ [الممتحنة:8] أهل العدل والفضل والبصيرة، فالمقسط: صفة مدح وهو الذي التزم الحق واعتدل وأخذ بالعدالة، والقاسط: المائل عن الحق، الذي جار عن الحق وأبى اتباع الحق، ولهذا قال سبحانه: وَأَمَّا الْقَاسِطُونَ يعني: الجائرون المنحرفون عن الحق فَكَانُوا لِجَهَنَّمَ حَطَبًا.\n\nفهكذا يقال في الجن والإنس، فهم سواء: من ترك شركه وباطله، ودخل في الإسلام فله ما للمسلمين، من الجن والإنس، وعليه ما عليهم، ومن بقي في شيطنته وكفره وضلاله، فله ما لأصحابه من جن أو إنس، ومن استقر على الهدى ومضى على الهدى، وسار على الهدى، فله ما وعد الله به المهتدين، والله المستعان.\n\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18554/وجود-المسلم-والكافر-في-الجن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_899/nour_89903.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19404,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من السودان، وباعثها أحد الإخوة يقول يوسف الطاهر عبد البنات، أخونا يوسف له رسالة مطولة فيها سؤالان، سؤاله الأول مطول أيضاً ملخصه: أنه حفر بئرًا وفجأة بدأ الناس يتبركون بهذه البئر، ويتعالجون من مياهها، ويسأل الآن سماحة الشيخ، هل عليه إثم في ذلك أو لا؟","title":"حكم التبرك بمياه الآبار","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإذا كانت البئر المذكورة فيها ماء ينفع من بعض الأمراض وحصل تجارب بذلك وانتفع الناس بها فلا بأس بذلك، لكن يعلمون ويوجهون أن البرء من الله والشفاء من الله، وأن هذا الماء جعل الله فيه بركة ينفع الناس من مرض كذا أو مرض كذا، كما جعل الله في زمزم بركة ينفع الله بها عباده في أشياء كثيرة  والله جعل في بعض المخلوقات خصائص تنفع في بعض الأمراض فلا يضر ذلك، لكن يعلم الجاهل أنها ليس عندها بركة إنما هذا خاصية فيها جعلها الله في هذا الماء ينفع من كذا أو من كذا يبين له أنها تنفع من كذا وكذا بالتجارب. وأما طلب البركة منها فالبركة من الله، لا يطلب منها بركة، ولكن تطلب البركة من الله، والشفاء من الله  هو الذي يشفي، وهو الذي يعطي البركة جل وعلا، ولكن بعض المخلوقات تنفع كما ينفع لحم كذا من كذا، وثمرة كذا من كذا، والكي من كذا وكذا، والدهن زيت من كذا وكذا، وهكذا أشياء جعلها الله خاصة في بعض المخلوقات، تنفع في أشياء، فلا ينافي ذلك أنها مخلوقة، وأنها مربوبة، وأن الله هو خالقها، وأن الله هو الشافي والمعافي . فالحاصل: أن بعض المخلوقات فيها خصائص تنفع من بعض الأمراض فلا مانع من استعمالها في الأمراض التي تنفع فيها حسب التجارب، ولكن مع الإيمان بأن الشفاء من الله والبركة من الله ، فلا يطلب منها شيء لا يطلب منها بركة ولا يطلب منها شفاء، الشفاء من عند الله  والبركة من عند الله . المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18630/حكم-التبرك-بمياه-الابار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93601.mp3","categories":["الطب والتداوي"]},{"id":19408,"question":"لقد سمعت من البعض أن هناك من الأطباء من يستطيع أن يرد قصار القامة إلى الطول المناسب الذي هو فيه عن طريق الأدوية والحبوب، ولقد شاهدت ذلك في بعض الأقرباء، بحيث أن تناولهم لهذه الحبوب رد لهم نموهم الذي توقف في سن معين، فهل هذا جائز، أفتونا أثابكم الله؟","title":"حكم التداوي من القصر","answer":"الجواب: ليس عندي علم بذلك، أقول ليس عندي علم من ذلك والتجارب تبين الأمر، التجارب تبين الأمر، الله جل وعلا ما أنزل داء إلا أنزل له شفاء علمه من علمه وجهله من جهله، قد يكون القصر له أسباب مرضية داخلية؛ فإذا هدي الطبيب إلى أسبابها وعالجها فلا أعلم مانعًا من ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18636/حكم-التداوي-من-القصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_936/nour_93605.mp3","categories":["الطب والتداوي"]},{"id":19470,"question":"يسأل أخونا ويقول: هل يجوز للإنسان أن يكتوي إذا مرض؟","title":"حكم التداوي بالكي","answer":"الجواب: نعم نعم، الكي جائز، لكن إذا تيسر دواء آخر فهو أفضل، ينبغي أن يكون الكي آخر الطب، فإذا تيسر له دواء آخر بغير الكي من حبوب، أو إبر، أو مروخ بزيت أو غيره أو ما أشبه ذلك، أو بالقراءة عليه، يقرأ عليه بعض أهل الخير، وينفث عليه كل ذلك حسن، وإذا احتاج إلى الكي فلا بأس، يقول النبي ﷺ: الشفاء في ثلاث: كية نار، أو شرطة محجم، أو شربة عسل، وما أحب أن أكتوي رواه البخاري في صحيحه، وفي رواية: وإني أنهى أمتي عن الكي. فالكي ينبغي أن يكون هو الآخر؛ لأنه نوع من التعذيب، نوع من النار، فلا يصار إليه إلا عند الحاجة، فإذا احتاج إليه كوى، وقد كوى النبي بعض أصحابه عليه الصلاة والسلام، فإذا احتاج إلى الكي فلا بأس، وقد كوى خباب بن الأرت الصحابي الجليل عن بعض المرض، فالكي جائز عند الحاجة إليه، ولكن تركه أفضل إذا تيسر غيره. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18719/حكم-التداوي-بالكي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_944/nour_94411.mp3","categories":["الطب والتداوي"]},{"id":19511,"question":"سماحة الشيخ! هذا سائل يقول: ما كيفية الرقية بالدعاء يا سماحة الشيخ! وما هي الأدعية التي تقرأ؟","title":"صفة الرقية الشرعية","answer":"الجواب: ينفث على المريض على محل المرض، ويدعو له، ينفث عليه من ريقه، ويقرأ الفاتحة، ويكررها سبع مرات، ويقرأ آية الكرسي، ويقرأ ما تيسر من القرآن، ويقرأ: قُلْ هُوَ اللَّهُ أَحَدٌ[الإخلاص:1] والمعوذتين يكررها ثلاثًا، هذه الرقية وينفث معها ويدعو الله، اللهم أذهب الباس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا كما فعله النبي ﷺ. ويقول: باسم الله أرقيك من كل شيء يؤذيك، من شر كل نفس، أو عين حاسد، الله يشفيك باسم الله أرقيك هكذا رقى جبرائيل النبي عليه الصلاة والسلام كما أخبر بذلك النبي عليه الصلاة والسلام فكل هذا حسن. وإذا قال: اللهم اشفه، اللهم عافه، اللهم يسر له العافية والدعوات المناسبة لا بأس، لكن هذا الدعاء الشرعي الوارد عن النبي ﷺ: اللهم أذهب البأس رب الناس، واشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقمًا، باسم الله أرقيك من كل شيء يؤذيك، من شر كل نفس أو عين حاسد الله يشفيك، باسم الله أرقيك، وإذا رقى بدعوات أخرى للمريض بطلب العافية فلا بأس. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18771/صفة-الرقية-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94613.mp3","categories":["الطب والتداوي","الرقى والتمائم"]},{"id":19523,"question":"تقول السائلة يا سماحة الشيخ، هل ننكر على من تذهب لتتعالج عند رجل في طب الأسنان مثلًا، بحجة أن هذا الدكتور ماهر، وله خبرة قديمة، أم أن الدكتورة هي الأولى؟","title":"حكم علاج المرأة عند الطبيب لخبرته","answer":"الجواب: الواجب عند الدكتورة، فإذا كانت الدكتورة غير متبصرة، وهو خير منها، وأحذق منها؛ فلا بأس، مع العناية بالتستر والتحفظ، وعدم الخلوة مع الطبيب. نعم. المقدم: أحسن الله إليكم، وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18782/حكم-علاج-المراة-عند-الطبيب-لخبرته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94619.mp3","categories":["قضايا المرأة","الطب والتداوي"]},{"id":19531,"question":"يقول السائل: ما حكم من يقول بعد الصلاة: الفاتحة، بنية الشفاء لطالب الشفاء؟","title":"حكم طلب قراءة الفاتحة عقب الفريضة بنية الشفاء","answer":"الجواب: هذا بدعة لا أصل له، هذا بدعة، وإنما المشروع يقرأ على المريض إذا قرأ عليه الفاتحة أو غيرها لا بأس، أما يقول: الفاتحة وبس هذا بدعة. نعم.","link":"https://binbaz.org.sa/fatwas/18777/حكم-طلب-قراءة-الفاتحة-عقب-الفريضة-بنية-الشفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93939.mp3","categories":["البدع والمحدثات","الطب والتداوي"]},{"id":19570,"question":"سماحة الشيخ! هذا سائل يقول: هل توجد آيات من القرآن الكريم معينة تقرأ على المسحور والذي به مس، ومن أصيب بالعين هل هم سواء؟","title":"الآيات التي يتداوى بها من السحر والعين والمس","answer":"الجواب: القرآن كله شفاء، ولكن من أنفع ذلك الفاتحة، كونه يقرأ الحمد سبع مرات يكررها، وآية الكرسي، وآيات السحر التي في الأعراف، ويونس، وطه، والشعراء آيات السحر، كل هذا من أنفع العلاج، مع قراءة قل هو الله أحد والمعوذتين ثلاث مرات، كل هذا من العلاج ..... وكل القرآن شفاء، كلما قرأ فهو من أسباب الشفاء والعافية؛ لكن هذه بوجه أخص من أعظم أسباب الشفاء، الفاتحة تكرارها سبع مرات، آية الكرسي، كذلك آيات السحر التي في طه وغيرها، في يونس وغيرها، في سورة يونس وغيرها وفي سورة طه، وفي سورة الشعراء كل هذه من أسباب الشفاء مع قراءة قل هو الله أحد والمعوذتين. نعم. المقدم: حفظكم الله سماحة الشيخ! المريض بمرض نفسي، وضيق الصدر، وأيضًا المريض المصاب بمرض عضوي هل يقرأ على نفسه من القرآن؟ الشيخ: نعم يرقي نفسه، كان النبي يرقي نفسه عليه الصلاة والسلام، فالإنسان يرقي نفسه كل ذلك مطلوب مشروع، ومن أهم الرقية أن يرقي نفسه بالفاتحة، وقل هو الله أحد والمعوذتين، وآية الكرسي هذا من أفضل الرقية، وإذا قرأ الفاتحة كررها سبعًا وقل هو الله أحد والمعوذتين كررها ثلاثًا كما كان النبي يفعل ﷺ، كان عند النوم يرقي نفسه بـقل هو الله أحد والمعوذتين في يديه ثلاث مرات، يمسح بهما على ما أقبل من جسده عليه الصلاة والسلام. المقدم: أحسن الله إليكم، وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18826/الايات-التي-يتداوى-بها-من-السحر-والعين-والمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94716.mp3","categories":["الطب والتداوي","السحر والكهانة"]},{"id":19614,"question":"السائل أبو معاذ يقول: حفظكم الله سماحة الشيخ من المعروف أن الرسول ﷺ شبه المنافق بالحنظل وهي الشجرة، أي: شجرة الحنظل، هناك بعض الناس يستعمل هذه الثمرة في علاج بعض الأمراض، فما حكم ذلك مأجورين؟","title":"حكم التداوي بشجرة الحنظل","answer":"الجواب: ما أعلم فيها شيئًا، إذا نفعت ما أعلم فيها شيئًا، ولو كانت مثل المنافق، ما أعلم في هذا بأسًا، إذا جرب الأطباء أنها تنفع في بعض الأمراض فلا بأس، عباد الله تداووا، ولا تداووا بحرام، الحمد لله.","link":"https://binbaz.org.sa/fatwas/18883/حكم-التداوي-بشجرة-الحنظل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94815.mp3","categories":["الطب والتداوي"]},{"id":19627,"question":"ما حكم التداوي بالقرآن الكريم يا سماحة الشيخ؟","title":"حكم التداوي بالقرآن","answer":"الجواب: مشروع، الله جعله شفاء؛ فإذا نفث الإنسان على نفسه بآيات من القرآن بالفاتحة، أو بآية الكرسي، أو قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذات كله طيب، كان النبي يعالج نفسه بالقرآن عليه الصلاة والسلام، فالعلاج بالقرآن من أفضل العلاج، بل هو أفضل العلاج. نعم. المقدم: جزاكم الله خير يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18898/حكم-التداوي-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94829.mp3","categories":["الطب والتداوي"]}]
